const GcAge = enum(u8) {
    new,
    survival,
    old0,
    old1,
    old,
    touched1,
    touched2,

    fn isYoung(self: GcAge) bool {
        return self == .new or self == .survival;
    }

    fn isOld(self: GcAge) bool {
        return !self.isYoung();
    }
};

/// PUC lgc.h:79-86 — per-object mark bits stored in `gc_marked`.
///
/// Bit layout (matching PUC's `marked` byte, bits 3-7; bits 0-2 are
/// `gc_age` which we store separately as `GcAge`):
///   bit 3 (WHITE0BIT): object is white type 0
///   bit 4 (WHITE1BIT): object is white type 1
///   bit 5 (BLACKBIT):  object is black (fully traversed)
///   bit 6 (FINALIZEDBIT): object is registered for finalization
///
/// Color semantics (PUC lgc.h:91-94):
///   white = one of WHITE0BIT/WHITE1BIT set (matches currentwhite)
///   black = BLACKBIT set
///   gray  = neither white nor black (in marking progress)
///
/// `gc_current_white` on Vm tracks which white bit (WHITE0BIT or WHITE1BIT)
/// is active for the current cycle. It flips at the end of each cycle
/// (PUC lgc.c:1579). New objects are created with the current white bit
/// (PUC lgc.c:301: `o->marked = luaC_white(g)`).
///
/// === PUC FINALIZEDBIT audit (lgc.c / lgc.h) ===
///
/// (a) What FINALIZEDBIT means in PUC:
///   FINALIZEDBIT means "this object is registered for finalization" — it
///   lives in the `finobj` list (or `tobefnz` after separation). It is NOT a
///   recursive visited-bit for the finalizer-reachable graph.
///   - SET: `luaC_checkfinalizer` (lgc.c:1088) sets it when an object with a
///     `__gc` metamethod is moved from `allgc` to `finobj` (registration).
///   - CLEARED: `udata2finalize` (lgc.c:953) clears it when the object is
///     moved back from `tobefnz` to `allgc` after its finalizer runs — the
///     object becomes "normal" again.
///   - PRESERVED: `sweeplist` (lgc.c `maskmarks = ~(BLACKBIT|WHITEBITS)`)
///     preserves FINALIZEDBIT during sweep, so registered objects keep it
///     across cycles until their finalizer runs.
///   - `separatetobefnz` (lgc.c:1023) does NOT touch FINALIZEDBIT — it only
///     relinks objects from `finobj` to `tobefnz`.
///
/// (b) FINALIZEDBIT is NOT a recursive visited-bit:
///   CONFIRMED. PUC keeps the finalizer-reachable graph alive through ORDINARY
///   marking: `markbeingfnz` (lgc.c:388) calls `markobject` on each `tobefnz`
///   object (ordinary gray/black mark), then `propagateall` (lgc.c:1569)
///   drains the gray list normally. No FINALIZEDBIT is set on merely-reachable
///   objects — only on the registered objects themselves.
///
/// (c) Which types can be registered for finalization in PUC 5.5:
///   Only TABLES and USERDATA. `luaC_checkfinalizer` is called exclusively
///   from `lua_setmetatable` (lapi.c:981,989) for LUA_TTABLE and LUA_TUSERDATA.
///   Threads, closures, and other types go through the `default` case which
///   sets a type-level metatable but does NOT call `luaC_checkfinalizer`.
///   Verified empirically: a thread/closure with a type-level `__gc` metatable
///   does NOT get its finalizer called in PUC 5.5.
const WHITE0BIT: u8 = 1 << 3;
const WHITE1BIT: u8 = 1 << 4;
const BLACKBIT: u8 = 1 << 5;
const FINALIZEDBIT: u8 = 1 << 6;
const WHITEBITS: u8 = WHITE0BIT | WHITE1BIT;
const MASKCOLORS: u8 = BLACKBIT | WHITEBITS;

/// PUC lgc.h:213-215: GC stop bits for `g->gcstp`.
const GCSTPUSR: u8 = 1; // stopped by user
const GCSTPGC: u8 = 2; // stopped by GC itself
const GCSTPCLS: u8 = 4; // closing Lua state

/// Check if object is white (has either white bit set).
fn gcIsWhite(marked: u8) bool {
    return (marked & WHITEBITS) != 0;
}

/// Check if object is black (BLACKBIT set).
fn gcIsBlack(marked: u8) bool {
    return (marked & BLACKBIT) != 0;
}

/// Check if object is dead: its white bits don't match currentwhite.
/// PUC lgc.h:100: `isdead(g,v) = isdeadm(otherwhite(g), v->marked)`
/// `otherwhite(g) = currentwhite ^ WHITEBITS` (the OTHER white bit).
/// An object is dead if it has the OTHER white bit set (created in a
/// previous cycle, never marked in this one).
fn gcIsDead(marked: u8, current_white: u8) bool {
    return (marked & (current_white ^ WHITEBITS)) != 0;
}

/// Set object's white bit to currentwhite (PUC lgc.c:52: `makewhite`).
fn gcMakeWhite(marked: *u8, current_white: u8) void {
    marked.* = (marked.* & ~MASKCOLORS) | (current_white & WHITEBITS);
}

/// Set object to gray: clear all color bits (PUC lgc.c:55: `set2gray`).
fn gcSetGray(marked: *u8) void {
    marked.* &= ~MASKCOLORS;
}

/// Set object to black: clear white bits, set BLACKBIT (PUC lgc.c:59: `set2black`).
fn gcSetBlack(marked: *u8) void {
    marked.* = (marked.* & ~WHITEBITS) | BLACKBIT;
}

/// PUC `ll_accessible` (loadlib.c): the no-op C function returned by
/// `package.loadlib(path, "*")` when the probe succeeds. PUC uses this to
/// signal "the library can be opened" without actually loading any symbols.
/// When called, it simply returns zero values — exactly like PUC's original.
fn llAccessible(L: ?*lua_State) callconv(.c) c_int {
    _ = L;
    return 0;
}

/// ═══════════════════════════════════════════════════════════════════════
/// CAPTURED-LOCAL STORAGE INVARIANT (P16.8a)
/// ═══════════════════════════════════════════════════════════════════════
///
/// For an active bytecode frame: if `boxed[reg]` holds an open Cell, that
/// Cell observes exactly `bc_stack[reg]` — `Cell.get` reads the stack slot,
/// `Cell.set` writes the stack slot. The stack register IS the authoritative
/// storage while the Cell is open.
///
/// Consequence: any direct write to `regs[reg]` (arithmetic ADD, MOVE,
/// direct-store, LOADNIL, etc.) is immediately visible to closures that
/// captured the local, because the open Cell reads from the same slot.
/// Conversely, any SETUPVAL from a nested closure (which calls `Cell.set`)
/// writes through to the parent frame's `regs[reg]`, so the parent sees the
/// new value on a direct read.
///
/// On close (`closeBytecodeUpvaluesFrom` / `cell.close`): the current stack
/// value is copied into `cell.value`, `bc_stack_idx` is set to null, and
/// `boxed[reg]` is set to null. The frame's boxed slot no longer represents
/// an open stack-backed upvalue. A closed Cell is NEVER present in `boxed[]`.
///
/// Consequence for codegen: the register holds the live value directly, so
/// no temp MOVE is needed for captured locals in `dischargeVars(.local)`.
/// OP_MOVE needs no boxed slow path: source read through `cell.get()` ==
/// `regs[b]`, and `boxed[]` only holds open cells, so a destination sync for
/// a closed cell never fires.
/// ═══════════════════════════════════════════════════════════════════════
pub const Cell = struct {
    /// "Closed" sentinel for `bc_stack_idx` (P16.16 C5/T5): a real stack
    /// slot index can never reach 4G (stacks are bounded far below that),
    /// so maxInt(u32) unambiguously means "no open stack reference" — the
    /// closed-upvalue state (PUC: `uv->v.p == &uv->u.value`).
    pub const bc_stack_closed: u32 = std.math.maxInt(u32);

    value: Value,
    gc_age: GcAge = .new,
    /// Position of this object in `Vm.gc_objects` (P16.16 C1: u32 — the
    /// list can never exceed 4G entries). Used by `gcUnregisterObject`
    /// for O(1) swapRemove; corrupted by the swap, never reused for
    /// ordering.
    gc_index: u32 = 0,
    /// PUC `marked` byte — tri-color mark bits (WHITE0/WHITE1/BLACK/
    /// FINALIZED/TEST). See constants above.
    gc_marked: u8 = 0,
    /// When != bc_stack_closed, this is an "open" upvalue that directly
    /// references the owning thread's bytecode stack at this index
    /// (P16.16 C5: u32 + sentinel instead of ?usize — 8B → 4B; slot 0 is
    /// unambiguous because the sentinel is maxInt, not 0).
    /// The thread is needed because a suspended coroutine's stack lives
    /// in `th.bytecode_stack`, not in `vm.bc_stack` (which belongs to
    /// whichever thread is currently executing).
    /// When closed, `value` is the actual value (closed upvalue).
    /// This mirrors PUC Lua's UpVal model: open upvalues point to stack,
    /// closed upvalues have their own copy.
    bc_stack_idx: u32 = bc_stack_closed,
    bc_stack_thread: ?*Thread = null,

    /// Resolve the correct bytecode stack slice for this cell.
    /// For open upvalues: if the owning thread is currently active,
    /// use `vm.bc_stack`; otherwise use `th.bytecode_stack`.
    fn resolveStack(self: *const Cell, vm: *const Vm) []Value {
        if (self.bc_stack_thread) |th| {
            if (vm.active_runtime_thread == th) return vm.bc_stack;
            return th.bytecode_stack;
        }
        return vm.bc_stack;
    }

    /// Read the current value of this cell.
    /// For open upvalues: reads from the owning thread's stack.
    /// For closed upvalues: reads from value.
    /// If the owning thread's stack is gone (freed/empty), falls back to
    /// the last snapshot in `value`. This covers the edge case where a
    /// coroutine's stack was freed while an open upvalue is still
    /// reachable by GC (e.g. coroutine.close on a running thread).
    pub fn get(self: *const Cell, vm: *const Vm) Value {
        if (self.isOpen()) {
            const idx: usize = self.bc_stack_idx;
            const stack = self.resolveStack(vm);
            if (idx < stack.len) return stack[idx];
            // Stack is gone or too small — return last known value.
            return self.value;
        }
        return self.value;
    }

    /// Write a value to this cell.
    /// For open upvalues: writes to the owning thread's stack.
    /// For closed upvalues: writes to value.
    pub fn set(self: *Cell, vm: *Vm, v: Value) void {
        if (self.isOpen()) {
            self.resolveStack(vm)[self.bc_stack_idx] = v;
        } else {
            self.value = v;
        }
    }

    /// Close this upvalue: snapshot the stack value into `value`,
    /// mark as closed (bc_stack_idx = bc_stack_closed).
    pub fn close(self: *Cell, vm: *const Vm) void {
        if (self.isOpen()) {
            self.value = self.resolveStack(vm)[self.bc_stack_idx];
            self.bc_stack_idx = bc_stack_closed;
            self.bc_stack_thread = null;
        }
    }

    /// Check if this cell is an open upvalue.
    pub fn isOpen(self: *const Cell) bool {
        return self.bc_stack_idx != bc_stack_closed;
    }
};

/// PUC `lua_State` (lstate.h:struct lua_State): the C API handle for a Lua
/// thread. In PUC, `lua_State` IS the thread — it contains the stack, call
/// info, and global state pointer. In luazig, the `Vm` struct holds the global
/// state and the main thread's runtime; `lua_State` is a **handle** that
/// wraps a `*Vm` and a `*Thread` (the thread this handle represents).
///
/// C code receives `?*lua_State` from `luaL_newstate` / `lua_newthread` and
/// passes it to every `lua_*` function. The handle is always heap-allocated
/// (never on the C stack) and its lifetime is tied to the VM (main handle) or
/// the Thread's GC lifetime (coroutine handle, freed in `gcFreeObject(.thread)`).
///
/// Since P15.83f every handle owns its own C API stack (`c_stack`), with
/// `Vm.cur_c_stack` pointing at the active handle's stack — mirrors of PUC's
/// per-`lua_State` stacks. All live handle stacks are marked as GC roots.
pub const lua_State = struct {
    /// The VM this handle belongs to. Always non-null after creation.
    /// C API functions resolve `vm = L.vm` to access the shared global state.
    vm: *Vm,
    /// The Thread object this handle represents. For coroutine states this
    /// is the coroutine's Thread (set by `lua_newthread`); for the main
    /// state it is `Vm.main_thread` (set by `setupMainHandle`, P15.83k) —
    /// every lua_State maps to a Lua thread Value, including the main one
    /// (PUC: lua_State IS the thread; the main lua_State is the main thread).
    /// `is_main` distinguishes the main handle where behavior differs
    /// (lua_pushthread return, lua_status, handle lifetime).
    thread: ?*Thread = null,
    /// Per-handle C API stack (PUC `L->stack`; landed in P15.83f). Each
    /// handle — main and coroutine alike — operates on its own stack, and
    /// `Vm.cur_c_stack` points to the active handle's stack so the VM's
    /// C-dispatch paths (callCFunction etc.) address the right one. All
    /// live handle stacks are GC roots (see the GC mark phase).
    c_stack: std.ArrayListUnmanaged(Value) = .empty,
    /// `true` for the main state (created by `luaL_newstate` / `lua_newstate`).
    /// `false` for coroutine states (created by `lua_newthread`).
    is_main: bool = false,
    /// PUC `ci->func` position for coroutine states (P15.83j): the index in
    /// `c_stack` where the coroutine's function was placed by the FIRST
    /// `lua_resume`. Every subsequent resume truncates the stack back to
    /// this base and pushes results there (PUC `lua_resume`: results end at
    /// `L->top`, start at `ci->func + 1` — `*nresults = top - (func + 1)`),
    /// so stale yielded values from a previous yield can never remain under
    /// the new results.
    resume_func_base: ?usize = null,
};

pub const Closure = struct {
    gc_age: GcAge = .new,
    /// Position in `Vm.gc_objects` (P16.16 C1: u32; see Cell.gc_index).
    gc_index: u32 = 0,
    /// PUC `marked` byte — tri-color mark bits. See constants above.
    gc_marked: u8 = 0,
    proto: ?*const bc.Proto = null, // bytecode proto (non-null for bytecode closures)
    /// The proto tree's lifetime (P16.10b Task 4/5) is DERIVED from the
    /// proto (P16.16 C2/T4.2): every bytecode closure RETAINS the tree
    /// owner at creation (`retainTreeForClosure(proto)`, which returns
    /// `proto.?.tree`), and `gcFreeObject(.closure)` releases it through
    /// `closure.proto.?.tree` — the invariant `tree == proto.?.tree` held
    /// at every creation site, so the field was pure duplication (8B per
    /// closure). This is what makes OP_CLOSURE sharing safe: many closures
    /// over one child proto, child closures outliving the root closure —
    /// the tree stays alive while ANY closure of ANY of its nodes lives.
    /// C closures (c_func) and builtin closures have proto == null and
    /// never retained a tree.
    upvalues: []const *Cell,
    /// C function pointer (PUC CClosure.f / `lua_CFunction`). Non-null when
    /// this closure wraps a C function registered through the C API
    /// (`luaL_setfuncs`, `lua_pushcfunction`). When non-null, `proto` is null.
    ///
    /// The type mirrors PUC's `lua_CFunction = int (*)(lua_State *)`: a C-ABI
    /// function taking a `?*lua_State` handle and returning a c_int result
    /// count. `callCFunction` passes `vm.cur_handle` — the active handle — so
    /// the C function receives its own `lua_State*`, matching PUC's contract.
    c_func: ?*const fn (?*lua_State) callconv(.c) c_int = null,
};

/// Error state hidden by a protected Lua call.  PUC Lua keeps this state in
/// the protected-call record; storing it on the explicit bytecode continuation
/// lets the dispatch loop suspend and resume `pcall`/`xpcall` without a Zig
/// activation record.
const BytecodeSavedError = struct {
    err_present: bool,
    err_len: u16,
    err_bytes: [256]u8,
    err_obj: Value,
    err_has_obj: bool,
    err_source: ?[]const u8,
    err_line: i64,
    err_traceback: ?[]u8,
    /// PUC `L->errfunc`: saved/cleared during protected calls so errors
    /// inside pcall don't invoke the outer message handler.
    /// P15.78: Changed from ?Value to StackOffset (per-Thread state).
    /// P15.83b: ERRFUNC_NONE sentinel (was 0; 0 collided with bc_stack[0]).
    errfunc: StackOffset = ERRFUNC_NONE,
};

const BytecodeProtectedKind = enum { pcall, xpcall };

const BytecodeProtectedLayer = struct {
    thread: *Thread,
    kind: BytecodeProtectedKind,
    handler: Value = .Nil,
    saved_error: BytecodeSavedError,
};

const BytecodeProtectedCall = struct {
    thread: *Thread,
    kind: BytecodeProtectedKind,
    /// P16.23 T6: nCcalls at protection entry. On a CAUGHT error the
    /// iterative unwind pops frames WITHOUT running their paired ccall
    /// exits (no C-stack unwind like PUC), so the recovery point restores
    /// the thread depth to this snapshot. Parked/continued frames across
    /// yield never pass here, preserving their live increments.
    saved_ncalls: u32 = 0,
    phase: enum { target, handler } = .target,
    handler: Value = .Nil,
    handler_depth: usize = 0,
    on_error_stack: bool = false,
    saved_error: BytecodeSavedError,
    /// Outermost-to-innermost protected builtins whose target is another
    /// pcall/xpcall. The innermost Lua target is the active protection above;
    /// once it completes, each parked outer target completed successfully and
    /// contributes one leading `true` result without re-entering Zig.
    outer_layers: []BytecodeProtectedLayer = &.{},
};

const BytecodeProtectedRecovery = union(enum) {
    not_handled,
    resumed,
    completed: []Value,
};

const BytecodeResultContinuation = struct {
    dst: u8,
    nresults: i32,
    /// Some call-like opcodes (currently TFORCALL) have fixed destinations
    /// but still extend the caller's live register top beyond `dst+nresults`.
    min_reg_top: ?u32 = null,
    /// Lua 5.5 `pairs` exposes a fourth to-be-closed result. Its __pairs
    /// metamethod supplies the iterator triple; the C wrapper appends nil.
    append_nil: bool = false,
    /// The protected builtin itself is in tail position.  When its target
    /// completes, the result must return from this frame directly because our
    /// bytecode codegen deliberately emits no synthetic RETURN after TAILCALL.
    tail_return: bool = false,
};

const BytecodeValueContinuation = struct {
    dst: u8,
};

const BytecodeIgnoreContinuation = struct {};

const BytecodeCompareContinuation = struct {
    invert: bool,
};

const BytecodeConcatContinuation = struct {
    dst: u8,
    values: []Value,
    /// Number of operands still waiting on the left of `acc`.  Lua
    /// concatenation is right-associative, so a suspended __concat resumes
    /// with values[remaining - 1] .. acc.
    remaining: usize,
    acc: Value,
};

/// Heap-owned state for string.gsub while a Lua replacement function or a
/// table __index metamethod runs as an explicit bytecode child.  PUC keeps the
/// C activation in CallInfo; retaining the scan/output state here gives the
/// bytecode backend the same property without recursively entering
/// runBytecode from the builtin.
const BytecodeGsubContinuation = struct {
    /// P16.23 T6: one C-depth unit is held while a replacement-function
    /// continuation frame is in flight (PUC: lua_call → ccall(nyci) around
    /// each repl invocation). The flag makes the accounting IDEMPOTENT
    /// against boundary replay after a coroutine yield/resume.
    repl_ccall_active: bool = false,
    result: BytecodeResultContinuation,
    subject: Value,
    pattern: Value,
    replacement: Value,
    limit: usize,
    count: usize = 0,
    index: usize = 0,
    disallow_empty_at: ?usize = null,
    had_subst: bool = false,
    anchored_start: bool,
    anchored_end: bool,
    literal: bool,
    out: std.ArrayListUnmanaged(u8) = .empty,
    pending_start: usize = 0,
    pending_end: usize = 0,
    pending_empty: bool = false,
};

const BytecodeGsubProgress = union(enum) {
    pushed,
    final: []Value,
};

const BytecodeGsubStart = union(enum) {
    not_handled,
    pushed,
    returned: []Value,
};

const BytecodeCoroutineKind = enum { resume_call, wrap_call };

const BytecodeCoroutineContinuation = struct {
    target: *Thread,
    kind: BytecodeCoroutineKind,
    result: BytecodeResultContinuation,
    saved_error: BytecodeSavedError,
};

const BytecodeCoroutineSwitchRequest = struct {
    caller: *Thread,
    target: *Thread,
    args: []Value,
};

const BytecodeCoroutineTarget = struct {
    thread: *Thread,
    args: []const Value,
    kind: BytecodeCoroutineKind,
};

const BytecodeCoroutineStep = union(enum) {
    returned: []Value,
    yielded: []Value,
    failed: Value,
    forced_close,
};

const BytecodeClosePost = union(enum) {
    advance_instruction,
    retry_tailcall,
    return_frame: []Value,
    unwind_frame,
};

const BytecodeCloseContinuation = struct {
    min_reg: u8,
    scan_index: usize,
    current_err: ?Value,
    had_close_error: bool,
    close_all: bool,
    err_depth: bool,
    owner_thread: *Thread,
    child_active: bool = false,
    waiting_builtin_yield: bool = false,
    post: BytecodeClosePost,
};

const BytecodeCloseProgress = union(enum) {
    resume_dispatch,
    final: []Value,
    propagate_error,
};

const BytecodeDispatchFault = enum {
    runtime,
    out_of_memory,
};

const BytecodeUnwindDisposition = union(enum) {
    protected_parent: usize,
    close_parent: usize,
    propagate,
};

/// Persistent Lua error-unwind state.  It lives on Thread because a __close
/// handler may yield while the failed frame suffix is being unwound.
const BytecodeUnwindState = struct {
    boundary_depth: usize,
    target_depth: usize,
    fault: BytecodeDispatchFault,
    error_value: Value,
    disposition: BytecodeUnwindDisposition,
};

const BytecodeDispatchRecovery = union(enum) {
    resumed,
    completed: []Value,
    propagate: BytecodeDispatchFault,
};

const BytecodeHookPost = union(enum) {
    /// Resume the same opcode after an instruction-boundary hook. Count hooks
    /// additionally skip one debit at that PC because the hook already fired.
    resume_instruction: struct { skip_count: bool = false, skip_line: bool = false },
    /// Re-resolve and execute OP_CALL/OP_TAILCALL, suppressing only the hook
    /// that has just completed. This lets debug.setlocal changes made by the
    /// hook affect the actual call arguments, as in PUC Lua.
    retry_call,
    /// A builtin/IR call already produced these values; store them after its
    /// return hook completes.
    store_results: struct {
        continuation: BytecodeResultContinuation,
        values: []Value,
    },
    /// The current bytecode frame has run its closers and is waiting only for
    /// the return hook before it can be popped.
    return_frame: []Value,
};

const BytecodeHookContinuation = struct {
    transfer: []Value,
    event_calllike: bool,
    event_tailcall: bool,
    event_is_count: bool,
    saved_parent_callee: Value,
    saved_parent_tailcall: bool,
    post: BytecodeHookPost,
};

// P15.78: `max_non_yieldable_c_depth` removed — the C-call overflow guard now
// uses PUC's LUAI_MAXCCALLS (200) against `Thread.getCcalls()`, and the
// non-yieldable boundary uses `Thread.yieldable()`/`incnny`/`decnny`.
// coroutine.close is a deliberately non-yieldable C-library boundary. Keep a
// conservative logical nesting cap so Debug builds remain safe on the 1-MB
// minimum stack used by the dispatch regression; the exact overflow depth is
// implementation-defined in PUC Lua as well.
const max_coroutine_close_c_depth: usize = 4;

/// Bytecode continuation ownership and control-flow invariants.
///
/// * `Thread.bytecode_frames` owns every pending completion. Heap slices stored
///   in a completion (`concat.values`, `gsub.out`, hook transfer/post values,
///   protected layers, saved tracebacks, and return/close payloads) remain owned
///   by that parent frame until the completion is applied or cancelled.
/// * Successful completion transfers or frees its owned payload in the matching
///   `applyBytecodePending*` path. Abandonment and error unwind go exclusively
///   through `cancelBytecodePendingCall`, which is therefore the single cleanup
///   authority for still-pending state.
/// * `results`, `value`, `ignore`, and `compare` are pure post-call actions.
///   `concat`, `gsub`, `hook`, and `close` may suspend because their Lua child
///   or callback may yield. `coroutine_resume` is the only continuation allowed
///   to request activation of another `Thread`.
/// * A coroutine switch is represented internally by `error.ThreadSwitch`. It
///   is consumed by `driveBytecodeCoroutineTrampoline`; no public API or API
///   adapter may observe or handle that signal.
/// Continuation recorded while a child Lua frame runs.
///
/// P15.44: Small variants (`results`, `value`, `ignore`, `compare`) are stored
/// inline — they're on the hot path (OP_CALL, simple metamethods). Big
/// variants (`concat`, `gsub`, `hook`, `close`, `coroutine_resume`) are
/// heap-allocated pointers — they're rare (each fires only for specific
/// features like __concat chains or debug hooks) and inline storage would
/// bloat the union to ~150 B. With this split, the union is 24 B and
/// PendingCallSlot is ~64 B (down from ~768 B), matching PUC Lua's per-frame
/// continuation cost (~80 B for `nresults`+`savedpc` in CallInfo).
///
/// Lifetime: heap variants are owned by the parent frame's PendingCallSlot.
/// `set()` allocates; `cancelBytecodePendingCall` and the per-variant
/// `applyBytecodePending*` paths free.
const BytecodePendingCompletion = union(enum) {
    results: BytecodeResultContinuation,
    value: BytecodeValueContinuation,
    ignore: BytecodeIgnoreContinuation,
    compare: BytecodeCompareContinuation,
    concat: *BytecodeConcatContinuation,
    gsub: *BytecodeGsubContinuation,
    hook: *BytecodeHookContinuation,
    close: *BytecodeCloseContinuation,
    coroutine_resume: *BytecodeCoroutineContinuation,
};

/// Continuation recorded on a bytecode caller while a child Lua frame runs.
///
/// PUC Lua stores the destination and the post-call operation in `CallInfo`.
/// Keeping a tagged completion here lets non-CALL opcodes (metamethods first,
/// then hooks/closers/coroutine switches) use the same explicit frame stack
/// without replaying the opcode or retaining a Zig activation record.
const BytecodePendingCall = struct {
    callee: Value,
    completion: BytecodePendingCompletion,
    protection: ?*BytecodeProtectedCall = null,
    /// P15.51n: Debug name override for the child frame created by this
    /// continuation. Set when the child frame is pushed (e.g. "metamethod"
    /// / "__add"). Read by debug.getinfo and traceback. Stored here rather
    /// than in CallFrame to avoid per-frame overhead for ordinary frames.
    /// Both default to empty slices (no override).
    debug_namewhat: []const u8 = &.{},
    debug_name: []const u8 = &.{},
    /// P15.51n: Free-list link (only valid when PendingCallSlot.active = false).
    free_next: u32 = INVALID_PENDING,
};

/// Heap-resident execution state for one bytecode activation.
///
/// The descriptor belongs to `Thread.bytecode_frames`, mirroring PUC Lua's
/// per-thread `CallInfo` chain.  `runBytecode` only borrows a depth-bounded
/// suffix of that stack; nested protected/metamethod entry therefore no longer
/// creates a second owner for bytecode frame descriptors.
/// Extra register slots pre-allocated per frame for multiret temporaries.
/// Matches PUC EXTRA_STACK=5 (lstate.h:142). Per-frame margin is safer
/// than PUC's global end-of-stack margin — each frame has its own.
/// bcGrowFrame is a no-op for typical multiret (≤5 values).
/// Eliminates the per-instruction stack_ptr realloc check.
const EXTRA_MARGIN: usize = 5;

/// P16.10 T8: SIGINT_CHECK_INTERVAL removed — replaced by PUC-style trap
/// (cached bool refreshed at backward jumps). The old countdown amortization
/// is no longer used.
/// P15.37a: Hot/cold split for the bytecode pending-call continuation.
///
/// `BytecodePendingCall` is 48 bytes (after P15.44 moved large continuation
/// variants — concat, gsub, hook, close, coroutine_resume — to heap pointers).
/// Storing it as `?BytecodePendingCall` (inline optional) caused the Zig
/// compiler to emit a memset every time the optional was set to `null` —
/// which happens on every frame push (to initialize) and every frame return
/// (after the continuation is consumed). Together these two memsets were
/// 53% of cycles on the `lua_calls` microbench (when the struct was 760
/// bytes pre-P15.44; the memset cost scales with struct size).
///
/// The fix separates the active flag (1 byte, hot) from the payload (48
/// bytes, cold). `clear()` writes a single byte; the payload retains stale
/// bytes but they are only read when `active` is true, i.e. after `set()`
/// has written a fresh value. This is safe because every `set()` writes
/// every field of `BytecodePendingCall` that will be read (the struct has
/// no fields with non-trivial defaults that `set()` callers rely on without
/// explicitly providing — `protection` defaults to `null` inside the struct
/// literal at each `set()` callsite).
///
/// PUC Lua parallel: PUC's `CallInfo` does not carry an inline continuation
/// payload. The caller's `savedpc` and the bytecode itself encode the
/// post-call operation. luazig uses explicit continuations for non-OP_CALL
/// entry points (metamethods, hooks, closers, coroutines); this slot is the
/// equivalent storage, kept cold to avoid penalising the common case.
const PendingCallSlot = struct {
    active: bool = false,
    payload: BytecodePendingCall = undefined,

    /// Returns `null` when inactive, or a pointer to the payload when active.
    /// Callers must not retain the pointer across a `set()` or `clear()`.
    pub fn getPtr(self: *PendingCallSlot) ?*BytecodePendingCall {
        if (!self.active) return null;
        return &self.payload;
    }

    /// Const access to the payload when active.
    /// Returns a pointer to avoid copying the 48-byte payload on every call.
    pub fn get(self: *const PendingCallSlot) ?*const BytecodePendingCall {
        if (!self.active) return null;
        return &self.payload;
    }

    /// Write a fresh continuation and mark the slot active.
    /// Overwrites every payload field; previous contents are irrelevant.
    pub fn set(self: *PendingCallSlot, value: BytecodePendingCall) void {
        self.payload = value;
        self.active = true;
    }

    /// Mark the slot inactive. Does NOT clear the payload bytes (they are
    /// stale but never read while `active` is false). This is the hot-path
    /// replacement for `?BytecodePendingCall = null` — one byte instead of
    /// a 768-byte memset.
    pub fn clear(self: *PendingCallSlot) void {
        self.active = false;
    }
};

/// P15.40b: Merged call frame — PUC `CallInfo` equivalent.
///
/// Replaces the dual `BytecodeExecFrame` + `RuntimeFrame` arrays with a
/// single array. PUC Lua has one `CallInfo` per call frame; we now match
/// that architecture. The `proto` field (null for IR frames, non-null for
/// bytecode frames) is the discriminator, like PUC's `CIST_C` bit.
///
/// Fields from BytecodeExecFrame that were also in RuntimeFrame under
/// different names:
/// - `base` (was `bc_base` in RuntimeFrame)
/// - `reg_top` (was `top` in RuntimeFrame)
/// - `nvarstack`: REMOVED in P16.21 T5 (debug-only fallback -> reg_top)
/// - `proto` made optional (was non-optional in BytecodeExecFrame)
///
/// Removed: `runtime_frame_index` (no longer needed — single array).
/// Removed: `bc_dummy_func_global` — the placeholder function that
/// existed only because `Closure.func`/`CallFrame.func` needed a value.
/// All closures now carry a bytecode `proto`; the old `func` field is gone.
/// PUC `CIST_NRESULTS` (`lstate.h:223`): low 8 bits of callstatus encode
/// `nresults + 1`. MULTRET (`LUA_MULTRET = -1`) encodes as `0`.
/// `MAXRESULTS = 250` fits (`251 <= 255`).
const CIST_NRESULTS: u32 = 0xff;
const MAXRESULTS: i32 = 250;

/// PUC callstatus flag bits (`lstate.h:222-254`).
/// Low 8 bits are CIST_NRESULTS (nresults+1). Upper bits are flags.
/// Bits 8-11: CIST_CCMT — __call metamethod count.
const CIST_CCMT: u32 = 8; // shift count, not mask
const MAX_CCMT: u32 = 0xf << CIST_CCMT;
/// Bits 12-14: CIST_RECST — recover status (error during pcallk).
const CIST_RECST: u32 = 12; // shift count
/// Bit 15: CIST_C — C function frame (discriminator).
const CIST_C: u32 = 1 << 15;
/// Bit 16: CIST_FRESH — fresh luaV_execute frame.
const CIST_FRESH: u32 = 1 << 16;
/// Bit 17: CIST_CLSRET — closing TBC variables on return.
const CIST_CLSRET: u32 = 1 << 17;
/// Bit 18: CIST_TBC — has TBC variables.
const CIST_TBC: u32 = 1 << 18;
/// Bit 19: CIST_OAH — saved allowhook.
const CIST_OAH: u32 = 1 << 19;
/// Bit 20: CIST_HOOKED — running debug hook.
const CIST_HOOKED: u32 = 1 << 20;
/// Bit 21: CIST_YPCALL — yieldable protected call.
const CIST_YPCALL: u32 = 1 << 21;
/// Bit 22: CIST_TAIL — tail call.
const CIST_TAIL: u32 = 1 << 22;
/// Bit 23: CIST_HOOKYIELD — last hook yielded.
const CIST_HOOKYIELD: u32 = 1 << 23;
/// Bit 24: CIST_FIN — finalizer.
const CIST_FIN: u32 = 1 << 24;
/// Bit 25: CIST_HIDE — luazig-specific: hide from debug.getinfo.
const CIST_HIDE: u32 = 1 << 25;
/// P15.51n: Sentinel for Thread.hook_frame_index meaning "no hook frame active".
const INVALID_HOOK_FRAME: usize = std.math.maxInt(usize);
/// P15.51n: Sentinel for u32 pc fields meaning "no pc" (replaces ?usize null).
const INVALID_PC: u32 = std.math.maxInt(u32);
/// P15.51n: Sentinel for CallFrame.pending_call_index meaning "no pending call".
const INVALID_PENDING: u32 = std.math.maxInt(u32);

/// P16.8 Task 1: Sentinel for LuaFrameState.simple_result_dst.
/// NO_REG (0xFF = 255) = no value-mode destination (PUC lopcodes.h NO_REG).
/// In compare mode, simple_result_dst is always NO_REG (invariant).
/// In value mode, 0..254 = destination register (R254 is VALID).
const SIMPLE_RESULT_NONE: u8 = 0xFF; // == NO_REG

/// P16.8 Task 1: Bit 7 of lua_packed_flags — simple_result_compare flag.
/// When set, the simple-result completion is in compare mode (check
/// truthiness, adjust pc). When clear, value mode if dst != NONE.
const SIMPLE_RESULT_COMPARE_FLAG: u8 = 0x80;

/// Encode nresults into callstatus low 8 bits (PUC `ldo.c:716`).
/// MULTRET (-1) encodes as 0. Non-negative encodes as nresults + 1.
inline fn encodeNresults(nresults: i32) u32 {
    return @intCast(@as(u32, @bitCast(@as(i32, nresults + 1))) & CIST_NRESULTS);
}

/// Decode nresults from callstatus low 8 bits (PUC `get_nresults`, `lstate.h:254`).
/// 0 → MULTRET (-1). Non-zero → value - 1.
inline fn decodeNresults(callstatus: u32) i32 {
    const raw: u32 = callstatus & CIST_NRESULTS;
    return @as(i32, @intCast(raw)) - 1;
}

/// PUC `getcistrecst` (`lstate.h:243`): extract recover status from callstatus.
inline fn getcistrecst(callstatus: u32) u32 {
    return (callstatus >> CIST_RECST) & 7;
}

/// PUC `setcistrecst` (`lstate.h:244`): set recover status in callstatus.
inline fn setcistrecst(callstatus: u32, st: u32) u32 {
    return (callstatus & ~@as(u32, 7 << CIST_RECST)) | (st << CIST_RECST);
}

/// PUC `setoah` (`lstate.h:248`): save allowhook in callstatus.
inline fn setoah(callstatus: u32, v: bool) u32 {
    return if (v) callstatus | CIST_OAH else callstatus & ~CIST_OAH;
}

/// PUC `getoah` (`lstate.h:249`): restore allowhook from callstatus.
inline fn getoah(callstatus: u32) bool {
    return (callstatus & CIST_OAH) != 0;
}

/// PUC `ptrdiff_t` — stack offset for errfunc and funcidx.
const StackOffset = usize;

/// Sentinel for "no errfunc". PUC uses 0 because the Lua stack base is
/// never at offset 0 in practice; luazig's bc_stack starts at 0, so a
/// legitimate handler pushed at index 0 would collide with the sentinel.
pub const ERRFUNC_NONE: StackOffset = std.math.maxInt(StackOffset);

/// PUC `CallInfo.u2` — mutually exclusive C-frame auxiliary state.
/// PUC `CallInfo.u2` — mutually exclusive auxiliary state.
/// `extern union` (not tagged) to match C union semantics: writing to any
/// field is always safe, no active-field tracking. PUC's `u2` is a C union
/// where `funcidx` (pcallk) and `nyield` (yieldk) share the same storage.
const CFrameAux = extern union {
    /// pcallk: callee stack offset for error recovery (PUC `u2.funcidx`).
    funcidx: StackOffset,
    /// yieldk: number of values yielded out (PUC `u2.nyield`).
    nyield: i32,
    /// CIST_CLSRET: saved nres (PUC `u2.nres`) for finishCcall to redo poscall.
    nres: i32,
};

/// P15.82: Heap-allocated state for CIST_CLSRET (TBC close yielded mid-way
/// during callCFunction's return-path close). Allocated on demand only when
/// a `__close` metamethod yields during C function return. Freed when all
/// closers complete (or on error/C-frame pop).
///
/// Stored as a pointer (not inline) to keep CallFrame compact (~96-104B).
/// Must be traced by GC while the C-frame is suspended (CIST_CLSRET).
const CClsretState = struct {
    /// Remaining TBC values to close (LIFO order). On resume, finishCcall
    /// closes these one by one. If a closer yields again, this slice is
    /// updated to skip the already-closed value.
    remaining_tbc: []Value,
    /// C function results saved before TBC close. Returned to the caller
    /// after all closers complete (return_close mode).
    results: []Value,
    /// P15.83c FIX B: Discriminator for which close mode we're in.
    /// - `.return_close`: TBC close during callCFunction's normal return
    ///   path. After closers complete, the saved results are returned.
    /// - `.pcall_error_close`: TBC close during finishpcallk's error path.
    ///   After closers complete, the error object is placed at funcidx
    ///   and the error status is returned to k.
    mode: CloseMode = .return_close,
    /// P15.83c FIX B: For pcall_error_close — the error value passed to
    /// __close as the 2nd argument. PUC luaF_close passes the current
    /// error value to each closer. If a closer itself errors, the new
    /// error replaces this value (LIFO, last-error-wins). Preserved
    /// across yield so resumed closers receive the correct error.
    error_value: ?Value = null,
    /// P15.83c FIX B: For pcall_error_close — the error STATUS to return
    /// to k after all closers complete. Preserved across yield (mirrors
    /// PUC CIST_RECST).
    error_status: i32 = 0,
};

const CloseMode = enum { return_close, pcall_error_close };

/// PUC `CallInfo.u.c` — C function frame state.
/// Only valid when `callstatus & CIST_C != 0`.
const CFrameState = extern struct {
    /// PUC `u.c.k`: continuation function, called on resume after yield.
    /// null = no continuation (plain yield or non-yieldable call).
    k: ?*const fn (?*lua_State, c_int, isize) callconv(.c) c_int = null,
    /// PUC `u.c.ctx`: continuation context, passed to k on resume.
    ctx: isize = 0,
    /// PUC `u.c.old_errfunc`: saved errfunc for pcallk error recovery.
    /// ERRFUNC_NONE = no errfunc was set.
    old_errfunc: StackOffset = ERRFUNC_NONE,
    /// PUC `u2`: mutually exclusive auxiliary state.
    aux: CFrameAux = .{ .funcidx = 0 },
    /// P15.78 Task 13: Per-frame continuation state for testC
    /// callk/pcallk/yieldk. When non-null, the C-frame was pushed by
    /// callk/pcallk/yieldk and the state hasn't been consumed by
    /// testcContShim yet. When null (consumed by testcContShim), the
    /// C-frame is being processed by finishCcall and can be reused by
    /// a nested callk (the reuse_cframe check).
    /// This replaces the single-valued `th.testc_cont_state` — each
    /// C-frame carries its own state, enabling chained callk calls.
    ///
    /// P15.80: Heap-allocated pointer (was inline `?TestcContState`).
    /// TestcContState is ~184B; storing it inline in every CallFrame
    /// inflated CFrameState to 224B and CallFrame to 264B. Moving to a
    /// pointer drops CFrameState to 56B. For reference: PUC CallInfo is
    /// 64 B on this 64-bit ABI (gcc-measured; see
    /// tools/perf/current-callframe-layout.json) — luazig's 88-B CallFrame
    /// is an architecture-specific larger representation (iterative
    /// yieldable frames, inline hook-replay state). Allocated on demand only when
    /// callk/pcallk/yieldk is used; freed when the C-frame is consumed
    /// or popped.
    testc_state: ?*TestcContState = null,
    /// P15.82: When CIST_CLSRET is set, heap-allocated state for the
    /// interrupted TBC close. null when CIST_CLSRET is not set.
    /// Must be freed by freeCFrameOwnedState on C-frame pop.
    clsret_state: ?*CClsretState = null,
    /// P15.82: Per-C-frame TBC base. When a C-frame is pushed, this saves
    /// the current `c_toclose_slots.len`. On return, only slots in
    /// `[toclose_base, c_toclose_slots.len)` belong to THIS C-frame.
    /// This mirrors PUC's per-call-info TBC scope (stack range
    /// `[ci->func, ci->top]`). Without this, nested C calls with
    /// `lua_toclose` corrupt each other's TBC slots.
    toclose_base: usize = 0,
};

/// PUC `CallInfo.u.l` — Lua function frame state.
/// Only valid when `callstatus & CIST_C == 0`.
const LuaFrameState = extern struct {
    /// PUC `Proto*` — the bytecode prototype. Non-optional for Lua frames.
    /// Invariant: isLua(fr) → fr.u.lua.proto is a valid pointer.
    /// The `undefined` default is safe because LuaFrameState is only valid
    /// when CIST_C is clear, and `pushBytecodeExecFrame` always sets `proto`
    /// before the frame becomes visible to the dispatch loop.
    // P16.20 T1: declaration order = memory order (extern struct). The
    // 8-aligned trio first, then u32/u32/u16/u8/u8 (10 B starting at 24),
    // then the five hook-replay u32s at 36 — total 56 B, no tail waste.
    proto: *const bc.Proto = undefined,
    /// PUC `u.l.savedpc`: current bytecode PC.
    pc: usize = 0,
    /// Register window upper bound (PUC `ci->top - ci->func`).
    frame_cap: u32 = 0,
    /// PUC `u.l.nextraargs`: extra vararg arguments.
    nextraargs: u16 = 0,
    /// Packed Lua-frame flags: bit0 has_open_upvalues, bit1
    /// simple_result_invert, bits 2-6 simple_result_event (TmsEvent u5),
    /// bit7 simple_result_compare (see the invariant block below).
    lua_packed_flags: u8 = 0,
    /// Inline simple-result completion destination:
    /// 0xFF (NO_REG) = no value destination (NONE or compare mode);
    /// 0x00-0xFE = value mode register (R254 VALID — MAX_FSTACK=255).
    simple_result_dst: u8 = 0xFF,
    /// Hook PC tracking (Lua-only, per-frame).
    resume_pc: u32 = INVALID_PC,
    last_line_pc: u32 = INVALID_PC,
    skip_line_hook_pc: u32 = INVALID_PC,
    skip_call_hook_pc: u32 = INVALID_PC,
    resume_skip_count_pc: u32 = INVALID_PC,

    /// P16.8 Task 1: INVARIANT — The simple-result state machine has
    /// exactly three states, encoded by (compare_flag, simple_result_dst):
    ///
    ///   1. NONE  (compare=0, dst=NO_REG): no simple-result pending.
    ///   2. VALUE (compare=0, dst=0..254): put 1 result into register
    ///      `simple_result_dst`, advance pc by 1. Zero returns → nil
    ///      (matches PUC `luaT_callTMres`).
    ///   3. COMPARE (compare=1, dst=NO_REG): check truthiness of 1 result;
    ///      advance pc by 1, then by 1 more if (truthy != invert).
    ///      Zero returns → false.
    ///
    /// Representation invariant: compare=1 ⟹ dst=NO_REG.
    /// R254 is fully valid in value mode — the old 0xFE sentinel is gone.
    ///
    /// This bypasses the pending_calls array entirely. The completion info
    /// lives inline in LuaFrameState (packed into 2 bytes: lua_packed_flags +
    /// simple_result_dst), using the 2 bytes of slack at the end of the
    /// 48-byte struct since P16.21 T2 (func_slot_base removed; the outer
    /// CallFrame stays 88 B because the C arm is the 56-B union floor).
    ///
    /// Resume equivalence: a frame with hasSimpleResult() that is suspended
    /// (coroutine yield) resumes identically to the old `.value`/`.compare`
    /// completion. The inline fields persist on the CallFrame (heap-resident
    /// in thread.call_frames), and the return path checks `hasSimpleResult()`
    /// before `pending_call_index`. The metamethod child frame is also
    /// heap-resident and persists across yield/resume. The ONLY difference
    /// from the old path is WHERE the completion info is stored (inline vs.
    /// pending_calls array); the semantics are identical.
    ///
    /// `pending_call_index` remains `INVALID_PENDING` while a simple-result is
    /// pending — the two completion mechanisms are mutually exclusive.
    pub fn hasOpenUpvalues(self: *const LuaFrameState) bool {
        return (self.lua_packed_flags & 0x01) != 0;
    }
    pub fn setOpenUpvalues(self: *LuaFrameState, v: bool) void {
        self.lua_packed_flags = if (v) self.lua_packed_flags | 0x01 else self.lua_packed_flags & ~@as(u8, 0x01);
    }

    // ── P16.8 Task 1: Simple-result state machine helpers ──
    // All simple_result access goes through these typed helpers. Callers
    // cannot construct impossible states (compare+dst, stale flags, etc.).

    /// True if a simple-result completion is pending (value OR compare mode).
    pub fn hasSimpleResult(self: *const LuaFrameState) bool {
        return (self.lua_packed_flags & SIMPLE_RESULT_COMPARE_FLAG) != 0 or
            self.simple_result_dst != SIMPLE_RESULT_NONE;
    }

    /// True if the pending simple-result is in compare mode.
    pub fn simpleResultIsCompare(self: *const LuaFrameState) bool {
        return (self.lua_packed_flags & SIMPLE_RESULT_COMPARE_FLAG) != 0;
    }

    pub fn simpleResultEvent(self: *const LuaFrameState) TmsEvent {
        return @enumFromInt((self.lua_packed_flags >> 2) & 0x1f);
    }

    pub fn simpleResultInvert(self: *const LuaFrameState) bool {
        return (self.lua_packed_flags & 0x02) != 0;
    }

    /// Value mode: put 1 result into register `dst` (0..254), advance pc by 1.
    /// Clears compare flag, sets dst and event.
    pub fn setSimpleValueResult(self: *LuaFrameState, dst: u8, event: TmsEvent) void {
        std.debug.assert(dst != SIMPLE_RESULT_NONE); // dst must be a real register
        self.lua_packed_flags = (self.lua_packed_flags & 0x01) | // keep has_open_upvalues
            (@as(u8, @intFromEnum(event)) << 2); // clear compare+invert, set event
        self.simple_result_dst = dst;
    }

    /// Compare mode: check truthiness of 1 result, advance pc by 1, then by
    /// 1 more if (truthy != invert). Sets compare flag, dst=NONE, event, invert.
    pub fn setSimpleCompareResult(self: *LuaFrameState, event: TmsEvent, invert: bool) void {
        self.lua_packed_flags = (self.lua_packed_flags & 0x01) | // keep has_open_upvalues
            SIMPLE_RESULT_COMPARE_FLAG |
            (if (invert) @as(u8, 0x02) else 0) |
            (@as(u8, @intFromEnum(event)) << 2);
        self.simple_result_dst = SIMPLE_RESULT_NONE; // invariant: compare ⟹ dst=NONE
    }

    /// Clear all simple-result state (back to NONE). Called on completion,
    /// error-unwind, and frame initialization.
    pub fn clearSimpleResult(self: *LuaFrameState) void {
        self.lua_packed_flags &= 0x01; // keep only has_open_upvalues
        self.simple_result_dst = SIMPLE_RESULT_NONE;
    }
};

pub const CallFrame = extern struct {
    // ── Common fields (both Lua and C frames) ──
    // P15.51k: callee field removed — derived from bc_stack[func_slot]
    // (PUC's ci->func points into the shared stack).
    // P15.51n: current_line removed — derive from proto.lineinfo[pc].
    // P15.51n: last_hook_line moved to Thread (single-valued, PUC oldpc).
    // P15.51i: is_tailcall moved to CIST_TAIL bit in callstatus.
    // P16.20 T1/T3: extern layout packs by DECLARATION order — 8-aligned
    // fields first, then the 4-byte group; after removing the stored base,
    // the variant union starts at offset 32 and @sizeOf(CallFrame) == 88
    // in BOTH build modes.
    /// PUC `ci->func` equivalent: bc_stack index of the function value.
    /// The function value at `bc_stack[func_slot]` is preserved for
    /// debug.getinfo and return value placement.
    /// P16.20 T3: `base` is NO LONGER STORED — the invariant
    /// `base == func_slot + 1` is universal (audited at all three writers:
    /// C-frame push, Lua pushStaged incl. VAHID-shifted slot, tailcall
    /// reuse), mirroring PUC luaV_execute `base = ci->func.p + 1`.
    func_slot: usize = 0,
    tbc_mark: usize = 0,
    activation_id: ActivationId = 0,
    /// PUC `callstatus` (`lstate.h:208`): low 8 bits = nresults+1 (CIST_NRESULTS),
    /// upper bits = flags; CIST_C discriminates the u-variant (PUC model).
    callstatus: u32 = 0,
    reg_top: u32 = 0,
    // P15.51i: is_debug_hook moved to CIST_HOOKED bit in callstatus.
    // P15.51i: hide_from_debug moved to CIST_HIDE bit in callstatus.
    // P15.51n: debug_namewhat/debug_name moved to BytecodePendingCall.
    pending_call_index: u32 = INVALID_PENDING,

    // ── Variant state (PUC CallInfo.u) ──
    // Discriminator: callstatus & CIST_C. When CIST_C is set, u.c is valid;
    // otherwise u.lua is valid. Mirrors PUC `CallInfo.u` union (`lstate.h:194`).
    // P16.20 T1: extern union — build-mode-stable, NO hidden active-arm
    // tag (a plain Zig union was 104 B in Debug vs 96 B in ReleaseFast —
    // the same hidden-safety-tag class of bug fixed for LuaString in
    // P16.17 T1). The semantic discriminator is `callstatus & CIST_C`,
    // exactly like PUC CallInfo: isLua()/isC() guard every arm access, and
    // construction sites activate the correct variant explicitly.
    u: extern union {
        lua: LuaFrameState,
        c: CFrameState,
    } = .{ .c = .{} },

    /// PUC lvm.c `updatebase(ci)`: base = ci->func.p + 1. Universal for
    /// Lua AND C frames (P16.20 T3 audit); inline single-add.
    pub inline fn frameBase(fr: CallFrame) usize {
        return fr.func_slot + 1;
    }

    /// P16.21 T2: the ORIGINAL (unshifted) function slot — where call
    /// results must land. PUC does not store a second pointer: for
    /// PF_VAHID it restores `ci->func.p -= (nextraargs + nparams1)`
    /// (OP_VARARGPREP / OP_RETURN handling). The push invariant is
    /// `shifted = original + nextraargs + numparams + 1` (pushStaged
    /// buildhiddenargs, and the tailcall re-setup writes the same triple),
    /// so the original is always derivable. VATAB/non-vararg frames are
    /// never shifted (original == func_slot). `nextraargs` mutates only at
    /// activation and tailcall-reuse — both rewrite the whole triple
    /// consistently (audited).
    pub inline fn originalFuncSlot(fr: CallFrame) usize {
        const p = fr.u.lua.proto;
        if (p.flags.is_vararg and fr.u.lua.nextraargs > 0 and
            p.vararg_table_reg == bc.Proto.no_vararg_reg)
        {
            return fr.func_slot -
                (@as(usize, fr.u.lua.nextraargs) + p.numparams + 1);
        }
        return fr.func_slot;
    }

    // P15.51g: regs/boxed removed — derived on demand from base + frame_cap
    // via regsSlice()/boxedSlice(). Eliminates stale slices after bc_stack realloc.

    // ── Accessors (migrated from RuntimeFrame) ──
    // All closures carry a bytecode proto. These accessors delegate to the
    // proto directly.
    // For synthetic C-frames (proto = null), return PUC-faithful defaults:
    // C functions are never vararg, have no source line, source "[C]",
    // line_defined = -1, 0 params, no name.

    /// PUC `ci->func->value.gc->p` accessor: return the bytecode proto for
    /// Lua frames, null for C frames. Use this for reads instead of direct
    /// field access (proto moved into u.lua).
    pub fn proto(fr: CallFrame) ?*const bc.Proto {
        if (fr.isLua()) return fr.u.lua.proto;
        return null;
    }

    pub fn isVararg(fr: CallFrame) bool {
        if (fr.proto()) |p| return p.flags.is_vararg;
        return false;
    }

    pub fn lineDefined(fr: CallFrame) i64 {
        if (fr.proto()) |p| return @intCast(p.line_defined);
        return -1;
    }

    pub fn sourceName(fr: CallFrame) []const u8 {
        if (fr.proto()) |p| return p.sourceName();
        return "=[C]";
    }

    pub fn funcName(fr: CallFrame) []const u8 {
        if (fr.proto()) |p| return p.name();
        return "?";
    }

    /// P15.51i: callstatus flag accessors (PUC CIST_* bits).
    /// CIST_C discriminator: distinguishes C function frames from Lua
    /// bytecode frames. Mirrors PUC `CIST_C` (`lstate.h:223`).
    pub fn isLua(fr: CallFrame) bool {
        return (fr.callstatus & CIST_C) == 0;
    }
    pub fn isC(fr: CallFrame) bool {
        return (fr.callstatus & CIST_C) != 0;
    }
    pub fn isYpcall(fr: CallFrame) bool {
        return (fr.callstatus & CIST_YPCALL) != 0;
    }
    pub fn isTbc(fr: CallFrame) bool {
        return (fr.callstatus & CIST_TBC) != 0;
    }
    pub fn isClsret(fr: CallFrame) bool {
        return (fr.callstatus & CIST_CLSRET) != 0;
    }

    pub fn setC(fr: *CallFrame) void {
        fr.callstatus |= CIST_C;
    }
    /// PUC `setoah` (`lstate.h:248`): save allowhook in callstatus via
    /// CIST_OAH. Used by `lua_pcallk` to preserve `L->allowhook` across a
    /// yieldable protected call so it can be restored on resume/error.
    pub fn setOah(fr: *CallFrame, v: bool) void {
        fr.callstatus = setoah(fr.callstatus, v);
    }
    /// PUC `getoah` (`lstate.h:249`): restore allowhook from CIST_OAH.
    pub fn getOah(fr: CallFrame) bool {
        return getoah(fr.callstatus);
    }
    pub fn setYpcall(fr: *CallFrame) void {
        fr.callstatus |= CIST_YPCALL;
    }
    pub fn clearYpcall(fr: *CallFrame) void {
        fr.callstatus &= ~CIST_YPCALL;
    }
    pub fn setTbc(fr: *CallFrame) void {
        fr.callstatus |= CIST_TBC;
    }
    pub fn setClsret(fr: *CallFrame) void {
        fr.callstatus |= CIST_CLSRET;
    }

    pub fn clearClsret(fr: *CallFrame) void {
        fr.callstatus &= ~CIST_CLSRET;
    }

    pub fn isTailCall(fr: CallFrame) bool {
        return (fr.callstatus & CIST_TAIL) != 0;
    }
    pub fn isDebugHook(fr: CallFrame) bool {
        return (fr.callstatus & CIST_HOOKED) != 0;
    }
    pub fn isHookYield(fr: CallFrame) bool {
        return (fr.callstatus & CIST_HOOKYIELD) != 0;
    }
    pub fn isHidden(fr: CallFrame) bool {
        return (fr.callstatus & CIST_HIDE) != 0;
    }
    pub fn setTailCall(fr: *CallFrame) void {
        fr.callstatus |= CIST_TAIL;
    }
    pub fn setDebugHook(fr: *CallFrame) void {
        fr.callstatus |= CIST_HOOKED;
    }
    pub fn setHookYield(fr: *CallFrame) void {
        fr.callstatus |= CIST_HOOKYIELD;
    }
    /// Set hook-yield flag from a bool (for assignment-from-bool sites).
    pub fn setHookYieldBool(fr: *CallFrame, v: bool) void {
        if (v) fr.callstatus |= CIST_HOOKYIELD else fr.callstatus &= ~CIST_HOOKYIELD;
    }
    pub fn setHidden(fr: *CallFrame) void {
        fr.callstatus |= CIST_HIDE;
    }
    pub fn clearTailCall(fr: *CallFrame) void {
        fr.callstatus &= ~CIST_TAIL;
    }
    pub fn clearDebugHook(fr: *CallFrame) void {
        fr.callstatus &= ~CIST_HOOKED;
    }
    pub fn clearHookYield(fr: *CallFrame) void {
        fr.callstatus &= ~CIST_HOOKYIELD;
    }
    pub fn clearHidden(fr: *CallFrame) void {
        fr.callstatus &= ~CIST_HIDE;
    }
    /// Set tail-call flag from a bool (for assignment-from-bool sites).
    pub fn setTailCallBool(fr: *CallFrame, v: bool) void {
        if (v) fr.callstatus |= CIST_TAIL else fr.callstatus &= ~CIST_TAIL;
    }

    /// P15.51g: Derive register slice from base + frame_cap (PUC: `ci->func + 1
    /// .. ci->top`). NOT stored in the frame — eliminates stale slices after
    /// bc_stack realloc. Callers must pass the correct stack for the thread
    /// (self.bc_stack for the VM-active thread, th.bytecode_stack for parked).
    pub fn regsSlice(fr: CallFrame, stack: []Value) []Value {
        return stack[fr.frameBase() .. fr.frameBase() + fr.u.lua.frame_cap];
    }

    /// P15.51g: Derive boxed-cell slice from base + frame_cap.
    pub fn boxedSlice(fr: CallFrame, boxed_stack: []?*Cell) []?*Cell {
        return boxed_stack[fr.frameBase() .. fr.frameBase() + fr.u.lua.frame_cap];
    }
};

/// P15.51g: Resolve the correct bytecode stack for a thread.
/// Active thread → self.bc_stack; parked coroutine → th.bytecode_stack.
/// Mirrors PUC Lua where each lua_State has its own stack.
fn stackForThread(self: *Vm, th: ?*Thread) []Value {
    if (th) |t| {
        if (t == self.active_runtime_thread) return self.bc_stack;
        return t.bytecode_stack;
    }
    return self.bc_stack;
}

/// PUC `base_ci` equivalent: inline call-frame storage with heap overflow.
///
/// Frames 0..INLINE_FRAME_CAP-1 live in the inline array (no heap
/// allocation). Deeper chains spill to `heap`, which is a standard
/// ArrayList. PUC Lua uses a single inline `base_ci` entry + heap chain;
/// we inline 32 entries because our CallFrame is larger than PUC's ~48B
/// CallInfo, and typical Lua call depth is well under 32.
///
/// All access goes through `getPtr(index)` and `len()` — never index
/// the arrays directly from outside this struct.
const INLINE_FRAME_CAP: usize = 32;

// P16.2d: CallFrame size invariant — must stay <= 104 bytes to keep the
// inline frame cache (32 entries) within a reasonable L1 footprint.
comptime {
    std.debug.assert(@sizeOf(CallFrame) <= 104);
}

const FrameStack = struct {
    inline_frames: [INLINE_FRAME_CAP]CallFrame = undefined,
    inline_count: usize = 0,
    heap: std.ArrayListUnmanaged(CallFrame) = .empty,

    /// Total number of frames (inline + heap).
    pub fn len(self: *const FrameStack) usize {
        return self.inline_count + self.heap.items.len;
    }

    /// Mutable pointer to frame at `index`.
    pub fn getPtr(self: *FrameStack, index: usize) *CallFrame {
        if (index < INLINE_FRAME_CAP) {
            std.debug.assert(index < self.inline_count);
            return &self.inline_frames[index];
        }
        return &self.heap.items[index - INLINE_FRAME_CAP];
    }

    /// Const pointer to frame at `index`.
    pub fn getConstPtr(self: *const FrameStack, index: usize) *const CallFrame {
        if (index < INLINE_FRAME_CAP) {
            std.debug.assert(index < self.inline_count);
            return &self.inline_frames[index];
        }
        return &self.heap.items[index - INLINE_FRAME_CAP];
    }

    /// P16.20 T6: PUC `L->ci` — direct current(top) frame access. Chooses
    /// the last heap entry when the heap is non-empty, else the last inline
    /// slot — ONE conditional instead of len()+index arithmetic, and the
    /// returned pointer is the same object getPtr(len()-1) yields.
    pub fn topPtr(self: *FrameStack) *CallFrame {
        if (self.heap.items.len != 0) {
            return &self.heap.items[self.heap.items.len - 1];
        }
        std.debug.assert(self.inline_count != 0);
        return &self.inline_frames[self.inline_count - 1];
    }

    pub fn topConstPtr(self: *const FrameStack) *const CallFrame {
        if (self.heap.items.len != 0) {
            return &self.heap.items[self.heap.items.len - 1];
        }
        std.debug.assert(self.inline_count != 0);
        return &self.inline_frames[self.inline_count - 1];
    }

    /// PUC `ci->previous` — parent of the current top frame. NULL-equivalent
    /// is impossible to express with a non-optional return, so callers must
    /// check len() > 1 first (Debug assert below enforces it).
    pub fn parentPtrOfTop(self: *FrameStack) *CallFrame {
        std.debug.assert(self.len() > 1);
        if (self.heap.items.len >= 2) {
            // Top is heap; parent is the heap entry before it.
            return &self.heap.items[self.heap.items.len - 2];
        }
        if (self.heap.items.len == 1) {
            // Top is the first heap frame; parent is the last inline frame.
            std.debug.assert(self.inline_count == INLINE_FRAME_CAP);
            return &self.inline_frames[INLINE_FRAME_CAP - 1];
        }
        // Both inline.
        std.debug.assert(self.inline_count >= 2);
        return &self.inline_frames[self.inline_count - 2];
    }

    pub fn parentPtrOfTopConst(self: *const FrameStack) *const CallFrame {
        std.debug.assert(self.len() > 1);
        if (self.heap.items.len >= 2) {
            return &self.heap.items[self.heap.items.len - 2];
        }
        if (self.heap.items.len == 1) {
            std.debug.assert(self.inline_count == INLINE_FRAME_CAP);
            return &self.inline_frames[INLINE_FRAME_CAP - 1];
        }
        std.debug.assert(self.inline_count >= 2);
        return &self.inline_frames[self.inline_count - 2];
    }

    /// Grow by one frame, return mutable pointer to the new slot.
    /// Mirrors `ArrayList.addOne` semantics.
    pub fn addOne(self: *FrameStack, alloc: std.mem.Allocator) !*CallFrame {
        if (self.inline_count < INLINE_FRAME_CAP) {
            const idx = self.inline_count;
            self.inline_count += 1;
            return &self.inline_frames[idx];
        }
        return try self.heap.addOne(alloc);
    }

    /// Ensure total capacity is at least `cap` (pre-allocation hint).
    pub fn ensureTotalCapacity(self: *FrameStack, alloc: std.mem.Allocator, cap: usize) !void {
        if (cap > INLINE_FRAME_CAP) {
            try self.heap.ensureTotalCapacity(alloc, cap - INLINE_FRAME_CAP);
        }
    }

    /// Shrink to exactly `new_len` frames. Mirrors `items.len = new_len`.
    pub fn shrinkTo(self: *FrameStack, new_len: usize) void {
        if (new_len <= INLINE_FRAME_CAP) {
            // All frames fit in inline — clear heap if any spilled.
            self.heap.items.len = 0;
            self.inline_count = new_len;
        } else {
            self.inline_count = INLINE_FRAME_CAP;
            self.heap.items.len = new_len - INLINE_FRAME_CAP;
        }
    }

    /// Clear all frames and free heap storage.
    pub fn clearAndFree(self: *FrameStack, alloc: std.mem.Allocator) void {
        self.inline_count = 0;
        self.heap.clearAndFree(alloc);
    }
};

/// P16.3: small-vector storage for per-thread yield/resume value lists.
/// The overwhelmingly common case is 0-4 values (coroutine.yield(42),
/// resume with no args), which must not pay a heap round-trip per
/// iteration. Values beyond the inline capacity spill to a heap slice.
/// API mirrors the old `?[]Value` field semantics:
///   - `slice()` returns null when empty (was: null field)
///   - `setFrom()` copies (replaces alloc.dupe into the field)
///   - `setOwned()` adopts an existing heap slice without copying
///   - `take()` moves the contents out (emptying the storage)
///   - `deinit()` frees the heap spill if any
const INLINE_VALUES_CAP: usize = 4;

const InlineValues = struct {
    inline_buf: [INLINE_VALUES_CAP]Value = undefined,
    heap: ?[]Value = null,
    len: usize = 0,

    /// `?[]Value` view: null when empty (matches the old null-field
    /// semantics at every read site).
    fn slice(self: *const InlineValues) ?[]Value {
        if (self.len == 0) return null;
        if (self.heap) |h| return h[0..self.len];
        return @constCast(self).inline_buf[0..self.len];
    }

    /// Replace contents with a copy of `vals` (inline when it fits).
    /// Frees any previous heap spill. Errors only on heap spill OOM.
    fn setFrom(self: *InlineValues, alloc: std.mem.Allocator, vals: []const Value) error{OutOfMemory}!void {
        self.deinit(alloc);
        self.len = vals.len;
        if (vals.len == 0) return;
        if (vals.len <= INLINE_VALUES_CAP) {
            @memcpy(self.inline_buf[0..vals.len], vals);
        } else {
            self.heap = try alloc.alloc(Value, vals.len);
            @memcpy(self.heap.?, vals);
        }
    }

    /// Adopt an already-owned heap slice (replaces `field = slice`
    /// assignments; no copy). Frees any previous heap spill first.
    fn setOwned(self: *InlineValues, alloc: std.mem.Allocator, vals: []Value) void {
        self.deinit(alloc);
        if (vals.len == 0) {
            // Empty owned slice: nothing to keep. Callers historically
            // stored empty slices and freed them later; storing empty is
            // equivalent to clearing.
            return;
        }
        if (vals.len <= INLINE_VALUES_CAP) {
            // Small owned slice: copy inline and free the donor (avoids a
            // long-lived tiny heap block). This changes ownership: the
            // caller must NOT free vals afterwards. All setOwned call sites
            // previously transferred ownership to the field, which freed it
            // on the next replacement — semantics preserved.
            @memcpy(self.inline_buf[0..vals.len], vals);
            self.len = vals.len;
            alloc.free(vals);
            return;
        }
        self.len = vals.len;
        self.heap = vals;
    }

    /// True when the storage currently holds a heap spill (debug/audit).
    fn isHeap(self: *const InlineValues) bool {
        return self.heap != null;
    }

    /// Free heap storage and reset to empty (replaces `field = null`).
    fn deinit(self: *InlineValues, alloc: std.mem.Allocator) void {
        if (self.heap) |h| alloc.free(h);
        self.heap = null;
        self.len = 0;
    }
};

pub const Thread = struct {
    const WrapYield = struct {
        values: []Value,
    };
    gc_age: GcAge = .new,
    /// Position in `Vm.gc_objects` (P16.16 C1: u32; see Cell.gc_index).
    gc_index: u32 = 0,
    /// PUC `marked` byte — tri-color mark bits. See constants above.
    gc_marked: u8 = 0,
    status: enum { suspended, running, dead } = .suspended,
    /// PUC `L->status` (lstate.h:283): the thread's status code, holding
    /// LUA_OK (0), LUA_YIELD (1), or error codes (LUA_ERRRUN=2, LUA_ERRMEM=4,
    /// LUA_ERRERR=5). Updated at every lifecycle transition (resume start,
    /// yield, error, completion, close). Read by `lua_status` (C API) and
    /// `api.State.status()` (Zig API).
    ///
    /// This mirrors PUC's `L->status` field exactly: PUC stores the raw
    /// TStatus code in `L->status` and updates it at every throw/resume
    /// boundary (ldo.c:luaD_throw, ldo.c:lua_resume, lstate.c:luaE_resetthread).
    /// luazig's `Thread.status` enum ({suspended,running,dead}) drives the
    /// coroutine state machine, but cannot represent error codes —
    /// `api_status` fills that gap.
    api_status: c_int = 0,
    /// PUC `L->allowhook` (lstate.h:290): whether hooks are allowed.
    /// PUC sets this to 0 while a hook is running and during certain
    /// non-reentrant operations. Stored per-thread (like PUC's lua_State
    /// field) so coroutine yield/resume automatically switches context.
    /// NOTE: The existing `DebugHookState.in_debug_hook` (inverted sense)
    /// still drives the current hook-suppression machinery; this field is
    /// the PUC-faithful home for the CIST_OAH save/restore added in later
    /// tasks and currently defaults to true (hooks allowed).
    allowhook: bool = true,
    /// PUC `L->nCcalls` (lstate.h:308): packed C-call depth.
    /// Lower 16 bits = C call depth (LUAI_MAXCCALLS guard against runaway
    /// recursion through C functions). Upper 16 bits = non-yieldable call
    /// depth (NYC): while nonzero, the thread may not yield across the
    /// C-call boundary. `yieldable` is true iff the upper 16 bits are 0.
    /// PUC packs both into a single `lu_byte`-counted `unsigned short` in
    /// some builds; we use `u32` to keep both counters in one field with
    /// room to spare, matching PUC's `nCcalls` semantics exactly.
    nCcalls: u32 = 0,
    /// PUC `L->errfunc` (lstate.h:307): stack offset of error handler.
    /// ERRFUNC_NONE = no errfunc. Set by xpcall and pcallk.
    errfunc: StackOffset = ERRFUNC_NONE,
    /// True while errfunc handler is running. Prevents infinite recursion.
    errfunc_running: bool = false,
    callee: Value, // .Closure or .Builtin
    /// P16.3: inline small-vector (0-4 values stay off the heap; the
    /// yield/resume hot loop must be allocation-free).
    yielded: InlineValues = .{},
    wrap_eager_mode: bool = false,
    wrap_started: bool = false,
    wrap_yields: std.ArrayListUnmanaged(WrapYield) = .empty,
    wrap_yield_index: usize = 0,
    wrap_final_values: ?[]Value = null,
    wrap_final_error: ?Value = null,
    wrap_final_delivered: bool = false,
    close_mode: bool = false,
    close_has_err: bool = false,
    close_err: Value = .Nil,
    wrap_repeat_closure: ?*Closure = null,
    entry_args: ?[]Value = null,
    debug_hook: DebugHookState = .{},
    trace_yields: usize = 0,
    trace_had_error: bool = false,
    trace_currentline: i64 = 0,
    trace_stack_depth: usize = 0,
    trace_frame_names: [64]?[]const u8 = @splat(null),
    pending_close_builtin: bool = false,
    pending_close_builtin_obj: Value = .Nil,
    pending_close_err_active: bool = false,
    pending_close_err: Value = .Nil,
    dofile_entry_closure: ?*Closure = null,
    resume_base_depth: usize = 0,
    resume_pop_consumed: bool = false,
    resume_recursive_mode: bool = false,
    /// Authoritative explicit bytecode activation stack for this Lua thread.
    /// Calls, metamethods, hooks, closers, protected calls, and coroutine
    /// switches all push continuations here instead of nesting runBytecode on
    /// the Zig stack. A top-level entry borrows only the suffix it creates.
    /// P15.40b: Merged with runtime_frames into a single call_frames array.
    /// P15.51n: Moved from CallFrame — only the active hook frame needs
    /// these. INVALID_HOOK_FRAME means no hook frame is active.
    hook_frame_index: usize = std.math.maxInt(usize),
    debug_hook_transfer: ?[]const Value = null,
    debug_hook_transfer_start: i64 = 1,
    debug_hook_event_calllike: bool = false,
    debug_hook_event_tailcall: bool = false,
    debug_hook_event_is_count: bool = false,
    debug_hook_allow_yield: bool = false,
    /// P15.51n: Per-frame debug name overrides (moved from CallFrame).
    /// Only continuation-entered frames (metamethods, close hooks) set these.
    /// Small fixed array — at most a few frames have names at any time.
    // P15.51n: debug_name_entries/debug_name_count removed — debug names
    // are now stored in BytecodePendingCall (parent's continuation).
    call_frames: FrameStack = .{},
    /// P16.22 T2: one named identity type for the activation guard (the
    /// frame slot identity used by syncFrame's deferred-write check).
    bytecode_activation_counter: ActivationId = 0,
    /// P15.51n: Moved from CallFrame — single-valued (only active frame's
    /// line hook matters), matching PUC's oldpc on lua_State.
    last_hook_line: i64 = -1,
    /// Parked runtime storage for this Lua thread. While the thread is active,
    /// ownership is temporarily moved into the VM's hot dispatch fields so the
    /// existing helpers can keep using contiguous arrays without per-access
    /// indirection. Context switches move the buffers, never copy them.
    bytecode_stack: []Value = &.{},
    bytecode_boxed: []?*Cell = &.{},
    bytecode_stack_top: usize = 0,
    bytecode_tbc_regs: std.ArrayListUnmanaged(u8) = .empty,
    /// Any bytecode `coroutine.yield` parks the thread-owned execution stacks
    /// in place. Resume continues the same descriptors without snapshot/replay.
    bytecode_inplace_suspended: bool = false,
    /// P15.65: When a bytecode yield is parked from within a nested call
    /// (e.g. __close metamethod running via callMetamethod → runClosure →
    /// runBytecodeInternal), the original boundary_depth of that
    /// runBytecodeInternal call must be preserved so resume doesn't process
    /// frames belonging to outer callers.
    bytecode_resume_boundary: usize = 0,
    /// Protected bytecode continuations are per Lua thread. Parked coroutines
    /// must not consume another thread's protected-call/error-handler budget.
    bytecode_protected_depth: usize = 0,
    bytecode_error_handler_depth: usize = 0,
    /// Nested unwind states are possible when a yielding __close handler
    /// raises while an older error is already closing another frame.
    bytecode_unwinds: std.ArrayListUnmanaged(BytecodeUnwindState) = .empty,
    bytecode_close_metamethod_depth: usize = 0,
    bytecode_close_metamethod_err_depth: usize = 0,
    resume_inbox: InlineValues = .{},
    tail_resume_inbox: ?[]Value = null,
    suspended_pc: usize = 0,
    suspended_direct_yield: bool = false,
    capture_yield_id: usize = 0,
    next_yield_id: usize = 1,
    resume_yield_id: usize = 0,
    yield_origin_depth: usize = 0,
    in_resume: bool = false,
    suspended_builtin: ?BuiltinId = null,
    /// P16.3: inline small-vector (0-4 values off-heap; see InlineValues).
    suspended_builtin_args: InlineValues = .{},
    /// P15.83q: C-frame residue of the error that killed this thread
    /// (PUC: the value the raising C function left below the error object
    /// on its frame — e.g. error()'s original string argument). Set by
    /// builtinCoroutineResume's error tail from vm.err_cframe_residue;
    /// read by c_api lua_resume to expose the PUC error window
    /// [residue?, err, err]. Persists for the thread's lifetime, like
    /// the stack residue it transcribes.
    api_err_residue: ?Value = null,
    capture_from_debug_hook: bool = false,
    capture_from_count_hook: bool = false,
    /// P15.68: True if the last yield was from inside a debug hook. Unlike
    /// capture_from_debug_hook, this flag persists across coroutine.resume
    /// so that debug.getinfo can distinguish hook yields (level 0 = the
    /// interrupted Lua function) from non-hook testC yields (level 0 = the
    /// builtin that yielded).
    yielded_from_debug_hook: bool = false,
    testc_state_main: bool = false,
    started: bool = false,
    finished: bool = false,
    caller: ?*Thread = null,

    /// PUC `lua_State` lifetime is tied to the Thread's GC lifetime. When a
    /// coroutine handle is created via `lua_newthread`, this field stores the
    /// handle so `gcFreeObject(.thread)` can free it when the Thread is
    /// collected. The main thread also carries its handle here (P15.83k, set
    /// by `setupMainHandle`) so `lua_tothread` can reverse-map the main
    /// thread Value to the main handle; the main handle itself is freed by
    /// `lua_close` / `api.State.deinit`, never by GC (the main thread is a
    /// permanent root, and `gcFreeObject(.thread)` skips main handles).
    /// `null` for Lua-created coroutines (no C handle).
    api_handle: ?*lua_State = null,

    /// PUC `isyieldable` (ldo.c): the thread may yield iff no non-yieldable
    /// C-call boundary is active (upper 16 bits of `nCcalls` are zero).
    pub fn yieldable(th: *const Thread) bool {
        return th.nCcalls & 0xffff0000 == 0;
    }
    /// PUC `getCcalls` (lstate.h macro): lower 16 bits of `nCcalls`,
    /// the C-call nesting depth used by the LUAI_MAXCCALLS overflow guard.
    pub fn getCcalls(th: *const Thread) u16 {
        return @truncate(th.nCcalls & 0xffff);
    }
    /// PUC `incnny` (ldo.c): enter a non-yieldable C-call boundary.
    /// Adds 0x10000 so `yieldable` becomes false until the matching `decnny`.
    /// P16.23 T6: PUC LUAI_MAXCCALLS (llimits.h) — nested C-call limit
    /// (lower 16 bits of nCcalls). One named constant, no scattered 200s.
    pub const LUA_MAX_C_CALLS: u16 = 200;
    /// PUC ldo.c ccall increments: plain yieldable call (+1 lower depth)...
    pub const CCALL_INC_YIELDABLE: u32 = 1;
    /// ...and nyci — non-yieldable (+1 upper nny AND +1 lower depth).
    pub const CCALL_INC_NOYIELD: u32 = 0x10000 | 1;

    /// PUC ldo.c `ccall` exit half: nCcalls -= inc. Pairs with
    /// `Vm.ccallEnter` via defer. (No RAII scope object: yield boundaries
    /// park the C frame ACROSS the boundary, so an automatic scope end
    /// could decrement too early — explicit enter/exit at the same
    /// control-flow level as the synchronous call.)
    pub fn ccallExit(th: *Thread, inc: u32) void {
        th.nCcalls -%= inc;
    }

    pub fn incnny(th: *Thread) void {
        th.nCcalls +%= 0x10000;
    }
    /// PUC `decnny` (ldo.c): leave a non-yieldable C-call boundary.
    pub fn decnny(th: *Thread) void {
        th.nCcalls -%= 0x10000;
    }
};

const DebugHookState = struct {
    func: ?Value = null,
    mask: []const u8 = "",
    mask_buf: [8]u8 = [_]u8{0} ** 8,
    mask_len: usize = 0,
    count: i64 = 0,
    budget: i64 = 0,
    tick: i64 = 0,
    has_call: bool = false,
    has_return: bool = false,
    has_line: bool = false,
    skip_line_once: bool = false,
    skip_line_until_depth: usize = 0,
    skip_count_once: bool = false,
    skip_bc_line_once: bool = false,
    /// PUC C hooks may yield; ordinary Lua hooks may not. testC installs its
    /// emulated C hook through a private marker after debug.sethook.
    allow_yield: bool = false,
    /// PUC `L->hook` (lstate.c): C hook function installed by `lua_sethook`.
    /// When non-null, the VM calls this function at hook events instead of
    /// the Lua-level `func`. PUC has a single hook slot per thread: setting
    /// a C hook clears `func` (and vice versa). The mask/count/budget fields
    /// above are SHARED between C and Lua hooks — `lua_sethook` mirrors the
    /// PUC mask bits into `has_call`/`has_return`/`has_line`/`count`, and the
    /// existing trigger sites fire for both C and Lua hooks.
    /// P15.83h: Moved from Vm to DebugHookState (per-thread, PUC-faithful).
    c_hook: ?*const fn (?*anyopaque, ?*anyopaque) callconv(.c) void = null,
    /// P15.38f: Per-thread "hook is currently running" flag, mirroring PUC
    /// Lua's `L->allowhook` (inverted sense: PUC sets allowhook=0 while a
    /// hook runs; we set in_debug_hook=true). Stored on DebugHookState
    /// (which lives on Thread) so coroutine yield/resume automatically
    /// switches to the correct thread's flag without any recompute.
    /// Both the sync path (debugDispatchHookTransfer) and the async path
    /// (bytecode hook frame push/pop) set/clear this flag.
    in_debug_hook: bool = false,

    fn setMask(self: *DebugHookState, mask: []const u8) void {
        self.mask_len = @min(mask.len, self.mask_buf.len);
        @memcpy(self.mask_buf[0..self.mask_len], mask[0..self.mask_len]);
        self.mask = self.mask_buf[0..self.mask_len];
    }

    pub fn clear(self: *DebugHookState) void {
        self.func = null;
        self.mask = "";
        self.mask_len = 0;
        self.count = 0;
        self.budget = 0;
        self.tick = 0;
        self.has_call = false;
        self.has_return = false;
        self.has_line = false;
        self.skip_line_once = false;
        self.skip_line_until_depth = 0;
        self.skip_count_once = false;
        self.skip_bc_line_once = false;
        self.allow_yield = false;
        self.in_debug_hook = false;
        self.c_hook = null;
    }
};

/// P15.78 Task 13: Continuation state for testC callk/pcallk/yieldk.
/// Stored per-C-frame in `CFrameState.testc_state` — each chained callk
/// gets its own C-frame with its own state, enabling "chain of suspendable
/// C calls" (coroutine.lua:1191). GC-traced in `gcPropagateOne`'s `.thread`
/// case via C-frame iteration — without
/// GC tracing, the GC collects objects referenced by these slices, causing
/// "switch on corrupt value" crashes.
const TestcContState = struct {
    script: []const u8,
    stack_prefix: []Value,
    upvalues: ?[]Value = null,
    upenv: Value = .Nil,
    state: ?*Table = null,
    ctx_id: i64 = 0,
    first_arg: ?Value = null,
    closers: ?[]Value = null,
    nupvalues: usize = 0,
    nresults: i32 = 0,
    is_pcallk: bool = false,
    /// PUC CIST_CLSRET: TBC close yielded mid-way. On resume, testcContShim
    /// continues closing remaining `closers` and returns `close_return_values`.
    /// `script` is "__close__" sentinel.
    close_return_values: ?[]Value = null,
    /// Index of next closer to run (for CIST_CLSRET case).
    close_current_index: usize = 0,
    /// Current close error (PUC luaF_close: last __close error wins, LIFO).
    /// Preserved across yield so resumed closers receive the correct error.
    /// Nil means no error yet (first closer receives null per PUC luaF_close).
    close_err: ?Value = null,
    /// True after the continuation script has run. Prevents re-running the
    /// script on re-entry after a yieldk yield (where a new C-frame was
    /// pushed on top and has already been processed).
    script_run: bool = false,
};

// Interned Lua string. P16.18 T5: layout mirrors PUC Lua's TString
// ALLOCATION model per kind (lstring.h sizestrshr / lstring.c
// luaS_sizelngstr), not just the full struct size:
//
//   kind            allocated bytes        content location
//   short           24 + len + 1           inline at offset 24
//   LSTRREG long    32 + len + 1           inline at offset 32
//   LSTRFIX ext     32                     external (`c.extptr`)
//   LSTRMEM ext     48                     external (`c.extptr`)
//
// Header layout (explicit extern struct — build-mode-stable, no hidden
// tags; identical offsets in Debug and ReleaseFast):
//
//   0..8   hash: u64                (every kind)
//   8..12  gc_index: u32            (every kind)
//   12     srkind: i8               (every kind; PUC `shrlen`)
//   13     gc_marked: u8            (every kind)
//   14     gc_age: u8               (every kind)
//   15     padding (never read)
//   16..24 u: hnext (short) | lnglen (all long kinds)
//   24..32 c: extptr (external kinds) | inline content start (short)
//   32..40 falloc (LSTRMEM only)
//   40..48 ud     (LSTRMEM only)
//
// GC metadata (hash/index/srkind/marked/age) lives within the first 16 B,
// so it is inside EVERY variant's allocation, including the 32-B
// truncated LSTRFIX header. Short content may extend past offset 48 (a
// 40-byte short allocates 65 B), exactly like PUC's flexible `contents`.
// P16.20 T1 invariant: CallFrame layout is build-mode-stable (extern
// struct/union — a plain Zig union here once made Debug 104 B vs RF 96 B,
// the LuaString P16.17 bug class). The assert compiles in EVERY build
// mode; offsets are part of the representation contract (u-variant at 32).
comptime {
    std.debug.assert(@sizeOf(CallFrame) == 88);
    std.debug.assert(@offsetOf(CallFrame, "u") == 32);
    std.debug.assert(@alignOf(CallFrame) == 8);
}

/// P16.22 T2: CallFrame slot identity (monotonic per-thread counter;
/// compared for EQUALITY only — 0 carries no sentinel meaning, proven by
/// audit: no activation_id == 0 / != 0 site exists).
pub const ActivationId = u32;

pub const LuaString = extern struct {
    hash: u64,
    /// Position in `Vm.gc_objects` (P16.16 C1: u32).
    gc_index: u32 = 0,
    /// PUC `shrlen` — ONE byte that is BOTH the kind discriminator and,
    /// for shorts, the length (lobject.h: `>= 0` short of that length;
    /// `LSTRREG -1`, `LSTRFIX -2`, `LSTRMEM -3`). This is the byte
    /// `luaS_sizelngstr` switches on; keeping the PUC encoding makes the
    /// allocated-size rule a single switch on this field.
    srkind: i8,
    /// PUC `marked` byte — tri-color mark bits. See constants above.
    gc_marked: u8 = 0,
    gc_age: GcAge = .new,
    _pad: u8 = 0,
    /// Offset 16: PUC unions `u.sh.hnext` (short chain link) with
    /// `u.lng.lnglen` (long length) — mutually exclusive by kind. The two
    /// arms are 8 B each; no hidden tag (extern union, P16.17 T1 lesson).
    u: extern union {
        hnext: ?*LuaString,
        lnglen: usize,
    } = .{ .hnext = null },
    /// Offset 24: PUC `u.lng.contents` — the external-content pointer for
    /// LSTRFIX/LSTRMEM. For SHORT strings these bytes are the START of the
    /// inline content (never read as a pointer on that path). For LSTRREG
    /// this slot is unused (inline content begins at offset 32).
    c: extern union {
        extptr: ?[*]const u8,
        content_start: u64,
    } = .{ .content_start = 0 },
    /// Offset 32: dealloc callback with PUC `lua_Alloc` signature, called
    /// as `falloc(ud, ptr, len+1, 0)`. LSTRMEM only — this field lies
    /// beyond the LSTRFIX truncation boundary, matching PUC
    /// `offsetof(TString, falloc)`.
    falloc: ?*const fn (?*anyopaque, ?*anyopaque, usize, usize) callconv(.c) ?*anyopaque = null,
    /// Offset 40: user-data pointer passed through to `falloc` (LSTRMEM
    /// only, beyond the LSTRFIX truncation boundary).
    ud: ?*anyopaque = null,

    // ------------------------------------------------------------------
    // Kind discriminants (PUC shrlen encoding; one load + sign check).
    // ------------------------------------------------------------------

    /// PUC `LSTRREG`/`LSTRFIX`/`LSTRMEM` encodings (lobject.h).
    pub const lstrreg: i8 = -1;
    pub const lstrfix: i8 = -2;
    pub const lstrmem: i8 = -3;

    /// PUC `offsetof(TString, contents)` == 24 on 64-bit: short inline
    /// content starts here (and the allocation is `24 + len + 1`).
    pub const short_content_offset: usize = @offsetOf(LuaString, "c");
    /// PUC `offsetof(TString, falloc)` == 32 on 64-bit: regular-long
    /// inline content starts here (allocation `32 + len + 1`) and the
    /// LSTRFIX header ends here (allocation exactly 32).
    pub const long_content_offset: usize = @offsetOf(LuaString, "falloc");
    /// Back-compat alias: the LSTRFIX truncated header size.
    pub const lstrfix_header_size: usize = long_content_offset;

    /// PUC `isshrstr`: interned short variant (pointer-identity equality,
    /// intern-table membership).
    pub inline fn isShort(self: *const LuaString) bool {
        return self.srkind >= 0;
    }

    /// PUC `isextstr`: content lives at `c.extptr`, not inline. True for
    /// BOTH external kinds (fixed and dealloc).
    pub inline fn isExternal(self: *const LuaString) bool {
        return self.srkind <= lstrfix;
    }

    /// Fixed external string (PUC LSTRFIX): truncated 32-B header, no
    /// deallocator. Check BEFORE any access to `falloc`/`ud`.
    pub inline fn isFixedExternal(self: *const LuaString) bool {
        return self.srkind == lstrfix;
    }

    /// Content length. Shorts read it from the discriminator byte (PUC
    /// `shrlen`); longs from `u.lnglen` (PUC `u.lng.lnglen`).
    pub inline fn len(self: *const LuaString) usize {
        if (self.srkind >= 0) return @intCast(self.srkind);
        return self.u.lnglen;
    }

    /// Intern-table chain link (SHORT strings only — the sole variant ever
    /// inserted into `StringTable`). PUC `u.sh.hnext`.
    pub inline fn nextShort(self: *const LuaString) ?*LuaString {
        if (std.debug.runtime_safety) std.debug.assert(self.isShort());
        return self.u.hnext;
    }

    pub inline fn setNextShort(self: *LuaString, next: ?*LuaString) void {
        if (std.debug.runtime_safety) std.debug.assert(self.isShort());
        self.u.hnext = next;
    }

    /// Content bytes. Regular strings: inline in the same allocation
    /// (shorts at offset 24, regular longs at offset 32 — one allocation
    /// per string, cache-friendly). External kinds: caller-owned memory at
    /// `c.extptr`. The returned slice EXCLUDES the trailing NUL that
    /// inline kinds store at `content[len]` for C-API `const char*` safety
    /// (PUC `contents[len] = '\0'`).
    pub inline fn bytes(self: *const LuaString) []const u8 {
        const header: [*]const u8 = @ptrCast(self);
        if (self.srkind <= lstrfix) {
            const ptr = self.c.extptr orelse @as([*]const u8, @ptrFromInt(@alignOf([*]const u8)));
            return ptr[0..self.u.lnglen];
        }
        const off: usize = if (self.srkind >= 0) short_content_offset else long_content_offset;
        const body = header + off;
        return body[0..self.len()];
    }

    /// P16.18 T7: THE single allocated-size rule — the exact counterpart
    /// of PUC `sizestrshr(l)` for shorts and `luaS_sizelngstr(l, kind)`
    /// for longs. Every charge/credit/free site must use THIS helper so
    /// accounting can never drift from the actual allocation.
    pub inline fn allocatedSize(self: *const LuaString) usize {
        return switch (self.srkind) {
            0...@as(i8, @intCast(lua_string_max_short_len)) => short_content_offset + @as(usize, @intCast(self.srkind)) + 1,
            lstrreg => long_content_offset + self.u.lnglen + 1,
            lstrfix => lstrfix_header_size,
            lstrmem => @sizeOf(LuaString),
            else => unreachable,
        };
    }
};

// P16.17 T1 / P16.18 T5 invariants: LuaString's layout must be
// build-mode-stable AND match PUC's TString offsets on 64-bit. A plain
// Zig `union` in any variant slot would grow a hidden Debug safety tag
// (48→56 B), which once pushed the api.lua:580 fixed-load delta to exactly
// 400 = upstream FAIL in Debug while ReleaseFast passed at 392. These
// asserts compile in EVERY build mode, so a future build-mode-dependent
// layout regression fails the BUILD, not a test.
comptime {
    std.debug.assert(@sizeOf(LuaString) == 48);
    // PUC offsetof(TString, contents) == 24: short inline content start.
    std.debug.assert(LuaString.short_content_offset == 24);
    // PUC offsetof(TString, falloc) == 32: long inline content start AND
    // the LSTRFIX truncated-header boundary.
    std.debug.assert(LuaString.long_content_offset == 32);
    std.debug.assert(LuaString.lstrfix_header_size == 32);
    // GC metadata must be inside every variant's allocation prefix.
    std.debug.assert(@offsetOf(LuaString, "gc_age") < LuaString.short_content_offset);
}

// PUC Lua's LUAI_MAXSHORTLEN (lstring.h): strings up to this many bytes are
// interned as short strings; longer strings are allocated fresh each time.
pub const lua_string_max_short_len: usize = 40;

// Equality of two Lua strings, matching PUC `luaV_equalobj` for strings
// (lvm.c:600-624) + `luaS_eqstr` (lstring.c:44-50):
//   - two short strings: pointer identity (both interned => same pointer)
//   - otherwise (at least one long): content compare (length then bytes)
pub fn luaStringEq(a: *const LuaString, b: *const LuaString) bool {
    if (a.isShort() and b.isShort()) return a == b;
    if (a.len() != b.len()) return false;
    return std.mem.eql(u8, a.bytes(), b.bytes());
}

// Allocate a LuaString with `raw` copied inline right after the header.
// Exposed (`pub`) so the experimental bytecode const pool (bytecode.zig) can
// pre-intern string constants at chunk-build time, keeping the VM consistent
// with the main VM's interned-string model.
pub fn createLuaString(alloc: std.mem.Allocator, raw: []const u8, hash: u64) !*LuaString {
    // PUC allocates PER KIND from the moment of creation (this is the whole
    // point of sizestrshr / luaS_sizelngstr):
    //   short  -> 24 + len + 1  (content inline at offset 24)
    //   long   -> 32 + len + 1  (content inline at offset 32)
    // The trailing '\0' (`contents[len] = '\0'`, lstring.c) is not part of
    // the logical length (`bytes()` returns `[0..len]`); it exists so C-API
    // callers can hand out a NUL-terminated `const char*` safely.
    const is_short = raw.len <= lua_string_max_short_len;
    const content_off: usize =
        if (is_short) LuaString.short_content_offset else LuaString.long_content_offset;
    const total = content_off + raw.len + 1;
    const buf = try alloc.alignedAlloc(
        u8,
        std.mem.Alignment.fromByteUnits(@alignOf(LuaString)),
        total,
    );
    errdefer alloc.free(buf);
    const ls: *LuaString = @ptrCast(@alignCast(buf.ptr));
    ls.hash = hash;
    // PUC shrlen: the byte IS the short length (or the long-kind code).
    ls.srkind = if (is_short) @intCast(raw.len) else LuaString.lstrreg;
    ls.gc_index = 0;
    ls.gc_marked = 0;
    ls.gc_age = .new;
    ls._pad = 0;
    // Variant slot: shorts carry the intern-chain link (null until
    // StringTable.insert links them); regular longs carry the length.
    // Inline content at `content_off` in the SAME allocation (the c-union
    // region for shorts is pure content bytes — never read as a pointer
    // on the short path).
    if (is_short) {
        ls.u = .{ .hnext = null };
    } else {
        ls.u = .{ .lnglen = raw.len };
    }
    const body = buf[content_off..];
    @memcpy(body[0..raw.len], raw);
    body[raw.len] = 0; // C-string NUL terminator (PUC `contents[len] = '\0'`)
    return ls;
}

// Free a LuaString allocated by `createLuaString` or `createExternalLuaString`.
// For regular strings this matches the `+1` in `createLuaString` so the
// allocator sees the same length on free as on alloc (Zig checks slice length
// on free). For external strings, only the header is freed here — the external
// content is released first via the dealloc callback (PUC lgc.c:874-875):
//   `(*ts->falloc)(ts->ud, ts->contents, ts->u.lnglen + 1, 0);`
pub fn destroyLuaString(alloc: std.mem.Allocator, ls: *LuaString) void {
    // LSTRMEM: release the caller-owned content first via the dealloc
    // callback (PUC lgc.c:873-875: `if (ts->shrlen == LSTRMEM)
    // (*ts->falloc)(ts->ud, ts->contents, ts->u.lnglen + 1, 0);`). The
    // +1 is the NUL the caller promised at s[len] (PUC
    // lua_pushexternalstring api_check). LSTRFIX never runs a callback
    // (fixed content is caller-owned static memory), and its truncated
    // header never reaches the `falloc`/`ud` fields — the branch on
    // srkind happens BEFORE those bytes could be read.
    if (ls.srkind == LuaString.lstrmem) {
        if (ls.falloc) |falloc| {
            const content = ls.c.extptr orelse @as([*]const u8, @ptrFromInt(@alignOf([*]const u8)));
            _ = falloc(ls.ud, @ptrCast(@constCast(content)), ls.u.lnglen + 1, 0);
        }
    }
    // Free EXACTLY the allocated size for every kind (PUC luaM_freemem
    // with luaS_sizelngstr / sizestrshr). `_ = &n` keeps the length
    // runtime-known so buf[0..n] is a slice, not *[N]u8.
    const buf: [*]align(@alignOf(LuaString)) u8 = @ptrCast(ls);
    var n: usize = ls.allocatedSize();
    _ = &n;
    alloc.free(buf[0..n]);
}

// Global table of all live interned strings. Keyed by content bytes (the inline
// slice of the stored LuaString, which is stable for the allocation's lifetime),
// mapping to the canonical `*LuaString`. Mirrors PUC `lstring.c` stringtable:
// at most one entry per distinct content, so string equality becomes pointer
// comparison.
/// PUC `stringtable` (lstring.c): an array of bucket heads with each string
/// linked into its bucket through `LuaString.next`. Chained storage gives
/// O(1) removal (luaS_remove just unlinks), which is the property Zig's
/// open-addressing HashMap lacks: its tombstones accumulate under constant
/// alloc-intern-free churn into O(N) probe chains. With PUC-faithful
/// generational pacing (a minor collection every MINORMUL% of the base
/// heap) that churn is steady-state, so the chained layout is required
/// for parity in both semantics and asymptotics.
pub const StringTable = struct {
    /// PUC MINSTRTABSIZE: initial bucket count (power of two).
    const min_size: usize = 128;

    buckets: []?*LuaString = &.{},
    nuse: u32 = 0,

    fn bucketOf(self: *const StringTable, hash: u64) usize {
        // PUC lmod(h, size): power-of-two modulo (size is always a pow2).
        return @intCast(hash & (self.buckets.len - 1));
    }

    /// PUC internshrstr lookup: walk the bucket chain comparing length and
    /// content (lstring.c:219-229). The cached hash need not be compared —
    /// content equality implies hash equality.
    pub fn lookup(self: *const StringTable, raw: []const u8, hash: u64) ?*LuaString {
        if (self.buckets.len == 0) return null;
        var cur = self.buckets[self.bucketOf(hash)];
        while (cur) |ls| : (cur = ls.nextShort()) {
            if (ls.len() == raw.len and std.mem.eql(u8, ls.bytes(), raw)) return ls;
        }
        return null;
    }

    /// PUC luaS_resize / tablerehash (lstring.c:70-113): relink every chain
    /// into a fresh bucket array. On allocation failure the old table is
    /// kept intact (PUC: "any non-zero size should work correctly").
    fn resize(self: *StringTable, alloc: std.mem.Allocator, new_size: usize) std.mem.Allocator.Error!void {
        const old = self.buckets;
        const fresh = try alloc.alloc(?*LuaString, new_size);
        @memset(fresh, null);
        // PUC tablerehash: for each old bucket, walk the chain and relink each
        // node into its new bucket. The old `next` link MUST be saved before
        // it is overwritten (PUC: `hnext = p->u.hnext` before `p->u.hnext = vect[h]`),
        // otherwise the loop continuation reads the just-clobbered link and
        // silently drops every subsequent node in the old chain.
        for (old) |head| {
            var p = head;
            while (p) |ls| {
                const save_next = ls.nextShort();
                const b: usize = @intCast(ls.hash & (new_size - 1));
                ls.setNextShort(fresh[b]);
                fresh[b] = ls;
                p = save_next;
            }
        }
        if (old.len != 0) alloc.free(old);
        self.buckets = fresh;
    }

    /// PUC internshrstr insert (lstring.c:230-239): grow when the table is
    /// full (nuse >= size, doubling like growstrtab), then push to the head
    /// of the bucket.
    pub fn insert(self: *StringTable, alloc: std.mem.Allocator, ls: *LuaString) std.mem.Allocator.Error!void {
        if (self.nuse >= self.buckets.len) {
            const target = @max(self.buckets.len * 2, min_size);
            if (self.buckets.len == 0) {
                // Initial bucket allocation: a zero-bucket table cannot host
                // the string, and creating an UNINTERNED short string would
                // break the pointer-identity invariant (a later equal short
                // would be a different pointer, and luaStringEq compares
                // shorts BY POINTER). PUC never reaches internshrstr with a
                // zero-size table: luaS_init allocates MINSTRTABSIZE buckets
                // during state creation and fails the STATE on OOM. Mirror
                // that — propagate the failure to the caller.
                try self.resize(alloc, target);
            } else {
                // Grow failure: PUC luaS_resize keeps the old bucket array
                // ("leave table as it was"), and internshrstr then
                // RECOMPUTES `list = &tb->hash[lmod(h, tb->size)]` with the
                // OLD size and still creates+links the new short string
                // (lstring.c:230-246). There is NO "demote to long string"
                // fallback on this path in PUC 5.5. Swallowing the grow
                // failure and inserting anyway preserves the central
                // invariant: every live short string is interned exactly
                // once, so equal shorts stay pointer-identical even under
                // allocator failure.
                self.resize(alloc, target) catch {};
            }
        }
        const b = self.bucketOf(ls.hash);
        ls.setNextShort(self.buckets[b]);
        self.buckets[b] = ls;
        self.nuse += 1;
    }

    /// PUC luaS_remove (lstring.c:190-196): unlink from its bucket chain.
    /// The string must currently be in the table (callers only remove at
    /// free time, and insertion happens exactly once per live string).
    pub fn removeString(self: *StringTable, ls: *LuaString) void {
        if (self.buckets.len == 0) return;
        var p: *?*LuaString = &self.buckets[self.bucketOf(ls.hash)];
        while (p.*) |cur| : (p = &cur.u.hnext) {
            if (cur == ls) {
                p.* = cur.nextShort();
                cur.setNextShort(null);
                self.nuse -= 1;
                return;
            }
        }
    }

    /// PUC checkSizes (lgc.c:936-938): during atomic, if the table is less
    /// than a quarter full, halve it. Keeps the bucket array proportional to
    /// the live string population after churn episodes.
    pub fn shrinkIfNeeded(self: *StringTable, alloc: std.mem.Allocator) void {
        if (self.buckets.len > min_size and self.nuse < self.buckets.len / 4) {
            // PUC checkSizes (lgc.c:936-938): halve the bucket array if < 25%
            // full. luaS_resize keeps the old size on OOM — legitimate OOM
            // tolerance (PUC never propagates this error). The bucket array
            // is oversized but functional; next cycle will retry the shrink.
            self.resize(alloc, self.buckets.len / 2) catch {};
        }
    }

    /// Free every string and the bucket array (close-time teardown).
    pub fn deinit(self: *StringTable, alloc: std.mem.Allocator) void {
        for (self.buckets) |head| {
            var p = head;
            while (p) |ls| : (p = ls.nextShort()) destroyLuaString(alloc, ls);
        }
        if (self.buckets.len != 0) alloc.free(self.buckets);
        self.* = .{};
    }
};

pub const StringIntern = struct {
    const Map = std.HashMapUnmanaged(
        []const u8,
        *LuaString,
        Context,
        std.hash_map.default_max_load_percentage,
    );

    const Context = struct {
        pub fn hash(_: @This(), k: []const u8) u64 {
            var h = std.hash.Wyhash.init(0);
            h.update(k);
            return h.final();
        }

        pub fn eql(_: @This(), a: []const u8, b: []const u8) bool {
            return std.mem.eql(u8, a, b);
        }
    };

    table: Map = .empty,

    /// Sweep: remove and free entries whose LuaString is dead (not marked
    /// during this GC cycle). Safe to call during GC — collects entries to
    /// remove first, then removes+frees one at a time (key is valid until the
    /// LuaString is freed).
    pub fn sweep(self: *StringIntern, alloc: std.mem.Allocator, current_white: u8) !void {
        var to_remove = std.ArrayListUnmanaged(*LuaString).empty;
        defer to_remove.deinit(alloc);
        var it = self.table.iterator();
        while (it.next()) |entry| {
            if (gcIsDead(entry.value_ptr.*.gc_marked, current_white)) {
                try to_remove.append(alloc, entry.value_ptr.*);
            }
        }
        for (to_remove.items) |ls| {
            _ = self.table.remove(ls.bytes());
            destroyLuaString(alloc, ls);
        }
    }

    // Return the canonical *LuaString for `raw`, creating+inserting it if absent.
    // `hash` is the caller-computed content hash (random-seeded at the Vm level),
    // cached on the LuaString so the Table's own hash and all later uses are free.
    fn intern(self: *StringIntern, alloc: std.mem.Allocator, raw: []const u8, hash: u64) !*LuaString {
        if (self.table.get(raw)) |existing| return existing;
        const ls = try createLuaString(alloc, raw, hash);
        try self.table.put(alloc, ls.bytes(), ls);
        return ls;
    }

    fn deinit(self: *StringIntern, alloc: std.mem.Allocator) void {
        var it = self.table.valueIterator();
        while (it.next()) |ls_ptr| destroyLuaString(alloc, ls_ptr.*);
        self.table.deinit(alloc);
    }
};

test "LuaString stores inline bytes and cached hash" {
    const alloc = std.testing.allocator;
    const h: u64 = 0xdeadbeef;
    const ls = try createLuaString(alloc, "hello", h);
    defer destroyLuaString(alloc, ls);
    try std.testing.expectEqual(@as(usize, 5), ls.len());
    try std.testing.expectEqual(h, ls.hash);
    try std.testing.expectEqualStrings("hello", ls.bytes());
}

fn hashStringForTest(s: []const u8) u64 {
    var h = std.hash.Wyhash.init(0);
    h.update(s);
    return h.final();
}

test "StringIntern dedups equal content to same pointer" {
    var intern = StringIntern{};
    defer intern.deinit(std.testing.allocator);
    const a = try intern.intern(std.testing.allocator, "foo", hashStringForTest("foo"));
    const b = try intern.intern(std.testing.allocator, "foo", hashStringForTest("foo"));
    try std.testing.expect(a == b); // pointer identity
    try std.testing.expectEqualStrings("foo", a.bytes());
}

test "StringIntern keeps distinct content distinct" {
    var intern = StringIntern{};
    defer intern.deinit(std.testing.allocator);
    const a = try intern.intern(std.testing.allocator, "foo", hashStringForTest("foo"));
    const c = try intern.intern(std.testing.allocator, "bar", hashStringForTest("bar"));
    try std.testing.expect(a != c);
}

// PUC Lua has two string variants: short (<= LUAI_MAXSHORTLEN=40) interned in
// the string table, and long (>40) NOT interned — each a fresh allocation.
// Equality therefore cannot be pointer-eq in general: two long strings with the
// same content are equal-by-value but distinct pointers. See lvm.c:600-624 and
// lstring.c:44-50 (luaS_eqstr).
test "luaStringEq: long strings equal by content, distinct pointers" {
    const alloc = std.testing.allocator;
    const long = "a" ** 300; // > MAX_SHORT_LEN => long, not interned
    const a = try createLuaString(alloc, long, 0);
    defer destroyLuaString(alloc, a);
    const b = try createLuaString(alloc, long, 0);
    defer destroyLuaString(alloc, b);
    try std.testing.expect(a != b); // separate allocations
    try std.testing.expect(luaStringEq(a, b)); // equal by content
}

test "luaStringEq: short strings use pointer identity" {
    const alloc = std.testing.allocator;
    const a = try createLuaString(alloc, "abc", 0);
    defer destroyLuaString(alloc, a);
    const b = try createLuaString(alloc, "abc", 0);
    defer destroyLuaString(alloc, b);
    // Two separately-allocated short strings are NOT pointer-equal, so even with
    // equal content luaStringEq is false. (In the VM, short strings always go
    // through the intern table, so equal content => same pointer.)
    try std.testing.expect(a != b);
    try std.testing.expect(!luaStringEq(a, b));
    try std.testing.expect(luaStringEq(a, a));
}

// --- hash_seed coherence test ---

// Verify that a string interned via `internStr` and then used as a table
// key is found by `ltable.nodeLookup`. Both paths must consume the same
// `hash_seed`: `internStr` computes `Wyhash.init(hash_seed)` and caches
// the result in `LuaString.hash`; `ltable.keyHash(.String)` returns that
// cached hash. If the seed were mutated mid-run (the old canonicalization
// bug) or if intern/table-key used different seeds, this lookup would fail.
test "hash_seed: intern/table-key coherence" {
    const testing = std.testing;
    var vm = Vm.initWithSeed(testing.allocator, false, 0x9E3779B97F4A7C15);
    defer vm.deinit();

    // Intern a string — its hash is Wyhash(seed, content).
    const key = try vm.internStr("coherence_key_42");

    // Create a table and insert the interned string as a key.
    const tbl = try vm.alloc.create(Table);
    tbl.* = .{};
    defer {
        tbl.deinit(vm.alloc);
        vm.alloc.destroy(tbl);
    }
    try vm.tableResize(tbl, 0, 4); // allocate a 4-slot hash part
    _ = ltable.nodeInsert(tbl.hash, &tbl.hash_lastfree, .{ .String = key }, .{ .Int = 99 }, vm.hash_seed);

    // Lookup must find the value — proves intern hash == table-key hash.
    const node = ltable.nodeLookup(tbl.hash, .{ .String = key }, vm.hash_seed);
    try testing.expect(node != null);
    try testing.expectEqual(@as(i64, 99), node.?.value.Int);
}

// --- External string tests (PUC 5.5 lua_pushexternalstring / LSTRMEM) ---

/// Dealloc callback for external-string tests. Sets `freed.* = true` and
/// frees the external content via the testing allocator so leaks are caught.
fn testFalloc(
    ud: ?*anyopaque,
    ptr: ?*anyopaque,
    osize: usize,
    nsize: usize,
) callconv(.c) ?*anyopaque {
    _ = nsize; // always 0 (free)
    const flag: *bool = @ptrCast(@alignCast(ud.?));
    flag.* = true;
    // The external content was allocated by the test; free it here so the
    // testing allocator doesn't report a leak.
    const alloc = std.testing.allocator;
    if (ptr) |p| {
        const buf: [*]u8 = @ptrCast(p);
        alloc.free(buf[0..osize]);
    }
    return null;
}

test "external string: destroyLuaString invokes falloc and frees header only" {
    const alloc = std.testing.allocator;
    var freed = false;

    // Simulate what createExternalLuaString does: allocate the header via
    // alloc.create, and separate external content via alloc.alloc.
    const content = try alloc.alloc(u8, 6);
    @memcpy(content[0..5], "hello");
    const ls = try alloc.create(LuaString); // full-size header (LSTRMEM)
    ls.* = .{
        .hash = 0,
        .srkind = LuaString.lstrmem,
        .u = .{ .lnglen = 5 },
        .c = .{ .extptr = content.ptr },
        .falloc = testFalloc,
        .ud = @ptrCast(&freed),
    };

    // destroyLuaString should: (1) call falloc to release external content,
    // (2) free the header via alloc.destroy. Both must happen so neither the
    // content nor the header leaks.
    destroyLuaString(alloc, ls);
    try std.testing.expect(freed);
}

test "external string: regular string does NOT invoke falloc" {
    const alloc = std.testing.allocator;
    var freed = false;

    // A regular (non-external) string must never call falloc. Set the external
    // payload to a non-null falloc to verify the branch is skipped for inline
    // strings (is_external is the sole discriminator).
    const ls = try createLuaString(alloc, "inline", 0);
    // Writing falloc on a REGULAR long is legal (its allocation is 32+7 > 40
    // bytes — the field exists within the allocation); destroy must still
    // never invoke it because srkind is not LSTRMEM.
    ls.falloc = testFalloc;
    ls.ud = @ptrCast(&freed);
    destroyLuaString(alloc, ls);
    try std.testing.expect(!freed);
}

// P16.18 T3: PUC-faithful StringTable OOM semantics.
//
// PUC internshrstr (lstring.c:230-246) NEVER demotes a short string to long
// on resize failure: luaS_resize keeps the old bucket array ("leave table as
// it was"), internshrstr recomputes the bucket with the OLD size and links
// the new string anyway. Every live short string therefore stays interned
// exactly once — equal shorts remain pointer-identical even under OOM.
// (The previous luazig `catch return` skipped insertion, so a second intern
// of equal bytes produced a DIFFERENT pointer — breaking luaStringEq, which
// compares shorts by pointer identity.)

test "StringTable: initial bucket allocation OOM propagates (no uninterned shorts)" {
    const alloc = std.testing.allocator;
    // fail the FIRST allocation through the wrapper (= the initial resize)
    var failing = std.testing.FailingAllocator.init(alloc, .{
        .fail_index = 0,
        .resize_fail_index = 0,
    });
    var t: StringTable = .{};
    const ls = try createLuaString(alloc, "abc", 0x1);
    defer destroyLuaString(alloc, ls);
    // The initial zero-bucket table cannot host a short string; the error
    // must PROPAGATE (PUC fails state creation in luaS_init) instead of
    // silently creating an uninterned short.
    try std.testing.expectError(error.OutOfMemory, t.insert(failing.allocator(), ls));
    try std.testing.expectEqual(@as(u32, 0), t.nuse);
    try std.testing.expectEqual(@as(usize, 0), t.buckets.len);
}

test "StringTable: grow OOM keeps old table, still interns, identity holds" {
    const alloc = std.testing.allocator;
    var t: StringTable = .{};
    // alloc #0 = initial 128-bucket array; alloc #1 = grow to 256 (fails).
    var failing = std.testing.FailingAllocator.init(alloc, .{
        .fail_index = 1,
        .resize_fail_index = 1,
    });
    const fa = failing.allocator();
    defer alloc.free(t.buckets);

    // 129 distinct short strings; #129 trips nuse >= 128 -> grow -> OOM.
    var strings: [129]*LuaString = undefined;
    defer for (&strings) |s| destroyLuaString(alloc, s);
    for (0..129) |i| {
        var content: [6]u8 = undefined;
        _ = std.fmt.bufPrint(&content, "s{d:0>5}", .{i}) catch unreachable;
        strings[i] = try createLuaString(alloc, &content, (i + 1) *% 0x9E3779B97F4A7C15);
    }
    for (strings[0..128]) |s| try t.insert(fa, s);
    try std.testing.expectEqual(@as(usize, 128), t.buckets.len);
    try std.testing.expectEqual(@as(u32, 128), t.nuse);

    // The failing grow must be swallowed: insert proceeds into the OLD table.
    try t.insert(fa, strings[128]);
    try std.testing.expectEqual(@as(usize, 128), t.buckets.len); // old kept
    try std.testing.expectEqual(@as(u32, 129), t.nuse); // nuse grew

    // Lookup finds it; repeated lookup/intern yields the SAME pointer, so
    // luaStringEq's pointer identity for shorts survives the OOM.
    const found = t.lookup("s00128", strings[128].hash).?;
    try std.testing.expectEqual(strings[128], found);
    try std.testing.expectEqual(found, t.lookup("s00128", strings[128].hash).?);
    try std.testing.expect(luaStringEq(strings[128], found));

    // Removal stays correct on the un-grown table.
    t.removeString(strings[128]);
    try std.testing.expectEqual(@as(u32, 128), t.nuse);
    try std.testing.expectEqual(@as(?*LuaString, null), t.lookup("s00128", strings[128].hash));
    // And a re-insert after the failed grow still works (grow retried).
    try t.insert(alloc, strings[128]);
    try std.testing.expectEqual(strings[128], t.lookup("s00128", strings[128].hash).?);
}

// P16.18 T2: ordinary-string GC accounting must equal the ACTUALLY-OWNED
// allocation, NUL included (PUC sizestrshr / luaS_sizelngstr(LSTRREG) both
// charge len+1). Charged bytes are observed at three symmetric sites —
// gcNoteAlloc at intern, gcObjectBytes while live, gcNoteFree at sweep —
// and must all equal @sizeOf(LuaString)+len+1 (until the per-kind layout
// lands; then this test moves to luaStringAllocatedBytes).
// P16.18 T2/T7: ordinary-string GC accounting must equal the ACTUALLY-OWNED
// per-kind allocation (PUC sizestrshr / luaS_sizelngstr include the NUL).
// T7 permanent table: every charge/credit site funnels through
// allocatedSize(), so this single test pins the whole allocation model.
// P16.18 T9: string-key survival across table rehash + a full GC cycle,
// and content-equality of equal regular longs (longs are never interned —
// two separate allocations with equal bytes MUST compare equal by content).
test "string keys survive rehash+GC; equal longs compare by content" {
    const testing = std.testing;
    var vm = Vm.init(testing.allocator, false);
    defer vm.deinit();
    // Two distinct longs with equal content (fresh allocations each — the
    // regular-long model: NOT interned; internStrAll would dedupe them).
    const long_content = "long-key-with-equal-content-AAAAAAAAAAAAAAAAAAAAAAAAAAAA";
    // Equal content MUST hash identically (VM invariant: per-VM seed), or
    // content-equality lookups would land in different buckets.
    const long_hash = std.hash.Wyhash.hash(vm.hash_seed, long_content);
    const la = try createLuaString(vm.alloc, long_content, long_hash);
    const lb = try createLuaString(vm.alloc, long_content, long_hash);
    defer destroyLuaString(vm.alloc, la);
    defer destroyLuaString(vm.alloc, lb);
    if (la.isShort() or lb.isShort()) unreachable;
    try testing.expect(la != lb); // longs are not interned
    try testing.expect(luaStringEq(la, lb)); // ...so equality is by content
    const sa = try vm.internStr("sh");
    const sb = try vm.internStr("sh");
    try testing.expectEqual(sa, sb); // shorts ARE pointer-identical

    // Table with short + long string keys, grown past a rehash, then GC'd.
    const tbl = try vm.allocTableNoGc(); // GC-registered so its keys trace
    // Root the table (+ its long-key strings) across the GC cycle below —
    // a bare registered table is not otherwise reachable and would be swept.
    var roots = vm.gcTempRoots();
    defer roots.end();
    try roots.add(.{ .Table = tbl });
    try roots.add(.{ .String = la });
    try roots.add(.{ .String = lb });
    var i: usize = 0;
    while (i < 200) : (i += 1) {
        var kb: [8]u8 = undefined;
        _ = std.fmt.bufPrint(&kb, "k{d:0>7}", .{i}) catch unreachable;
        const key = try vm.internStr(&kb);
        try vm.rawSet(tbl, .{ .String = key }, .{ .Int = @intCast(i) });
    }
    try vm.rawSet(tbl, .{ .String = la }, .{ .Int = 777 });
    try vm.rawSet(tbl, .{ .String = sa }, .{ .Int = 888 });
    vm.gcFullCollectionForUser() catch unreachable; // full mark+sweep cycle
    i = 0;
    while (i < 200) : (i += 1) {
        var kb: [8]u8 = undefined;
        _ = std.fmt.bufPrint(&kb, "k{d:0>7}", .{i}) catch unreachable;
        const key = try vm.internStr(&kb); // same bytes -> same pointer
        const v = vm.rawGet(tbl, .{ .String = key });
        try testing.expect(v == .Int and v.Int == @as(i64, @intCast(i)));
    }
    try testing.expectEqual(@as(Value, .{ .Int = 777 }), vm.rawGet(tbl, .{ .String = lb })); // long lookup by CONTENT twin
    try testing.expectEqual(@as(Value, .{ .Int = 888 }), vm.rawGet(tbl, .{ .String = sb })); // short lookup by identity twin
}

test "string allocated-size rule: per-kind table (PUC parity)" {
    const testing = std.testing;
    var vm = Vm.init(testing.allocator, false);
    defer vm.deinit();
    const Case = struct { raw: []const u8, expected: usize };
    const cases = [_]Case{
        .{ .raw = "", .expected = LuaString.short_content_offset + 0 + 1 }, // short 0 -> 25
        .{ .raw = "a", .expected = LuaString.short_content_offset + 1 + 1 }, // short 1 -> 26
        .{ .raw = "x" ** 40, .expected = LuaString.short_content_offset + 40 + 1 }, // max short -> 65
        .{ .raw = "y" ** 41, .expected = LuaString.long_content_offset + 41 + 1 }, // min long -> 74
        .{ .raw = "z" ** 300, .expected = LuaString.long_content_offset + 300 + 1 },
    };
    for (cases) |c| {
        const before = vm.gc_count_kb;
        const ls = try vm.internStr(c.raw);
        // Charged at intern == per-kind allocated size (NUL included)...
        try testing.expectEqual(
            c.expected,
            @as(usize, @intFromFloat((vm.gc_count_kb - before) * 1024.0)),
        );
        // ... == gcObjectBytes while live ...
        try testing.expectEqual(c.expected, gcObjectBytes(.{ .string = ls }));
        // ... == the single-rule helper ...
        try testing.expectEqual(c.expected, ls.allocatedSize());
        // ... and the variant classification is semantic, not byte-length:
        try testing.expectEqual(c.raw.len <= 40, ls.isShort());
    }
    // External kinds: LSTRFIX = 32 (truncated header) regardless of length,
    // LSTRMEM = 48 (full header) — including lengths BELOW the short cutoff,
    // which must stay long-kind (T8).
    const fx = try vm.createExternalLuaString("tiny fixed", "tiny fixed".len, null, null);
    try testing.expectEqual(@as(usize, 32), fx.allocatedSize());
    try testing.expect(!fx.isShort());
    var freed = false;
    // LSTRMEM transfers content ownership to Lua: allocate len+1 bytes
    // (testFalloc frees buf[0..osize] with osize = len+1, PUC contract).
    const mem_content = try vm.alloc.alloc(u8, 2);
    @memcpy(mem_content, "t\x00");
    const fm = try vm.createExternalLuaString(mem_content.ptr, 1, testFalloc, @ptrCast(&freed));
    try testing.expectEqual(@as(usize, 48), fm.allocatedSize());
    try testing.expect(!fm.isShort());
    // LSTRMEM dealloc fires exactly once — at destroy. Unregister from the
    // GC list first (the test destroys manually; vm.deinit must not see it
    // again) and credit the accounting symmetrically.
    try testing.expect(!freed);
    vm.gcUnregisterObject(.{ .string = fm });
    vm.gcNoteFree(fm.allocatedSize());
    destroyLuaString(vm.alloc, fm);
    try testing.expect(freed);
    // NOTE: fx is GC-registered; vm.deinit() frees it (no dealloc for LSTRFIX).
}

test "external string: createExternalLuaString content readable via bytes()" {
    const testing = std.testing;
    var vm = Vm.init(testing.allocator, false);
    defer vm.deinit();

    // External content must outlive the LuaString for this test. Use a
    // static constant array so no falloc is needed (LSTRFIX-like).
    const content = "hello external world";
    const ls = try vm.createExternalLuaString(content.ptr, content.len, null, null);
    try testing.expect(ls.isFixedExternal()); // falloc == null => LSTRFIX
    try testing.expect(ls.isExternal());
    try testing.expect(!ls.isShort()); // external strings are always "long"
    try testing.expectEqualStrings(content, ls.bytes());
    try testing.expectEqual(@as(usize, content.len), ls.len());
    try testing.expectEqual(LuaString.lstrfix_header_size, @as(usize, 32));
}

pub const Value = union(enum) {
    Nil,
    Bool: bool,
    Int: i64,
    Num: f64,
    String: *LuaString, // interned; compare by pointer identity
    Table: *Table,
    Builtin: BuiltinId,
    Closure: *Closure,
    Thread: *Thread,
    // PUC LUA_TLIGHTUSERDATA: a plain C pointer wrapped as a Lua value.
    // NOT garbage-collected — the GC does not own or trace the pointer.
    // Has a single shared metatable (per-VM `light_userdata_metatable`),
    // matching PUC's `mt[LUA_TLIGHTUSERDATA]`.
    LightUserdata: ?*anyopaque,
    // PUC LUA_TUSERDATA: a full GC-managed userdata object with per-object
    // metatable and uservalues. Distinct from LightUserdata (which is a bare
    // pointer, not GC'd). See `Userdata` struct above.
    Userdata: *Userdata,

    pub fn typeName(self: Value) []const u8 {
        return switch (self) {
            .Nil => "nil",
            .Bool => "boolean",
            .Int, .Num => "number",
            .String => "string",
            .Table => "table",
            .Builtin, .Closure => "function",
            .Thread => "thread",
            .LightUserdata, .Userdata => "userdata",
        };
    }
};

/// Tagged union of all GC-managed heap objects. Replaces PUC's intrusive
/// `GCObject.next` singly-linked `allgc` list with a type-safe Zig union.
/// Each variant is a pointer to a struct with flat `gc_marked: u8`,
/// `gc_age: GcAge`, `gc_index: usize` fields (no layout change needed).
/// Generic GC code accesses these through `gcPtr()` which returns a
/// struct of pointers to the flat fields.
pub const GcObject = union(enum) {
    table: *Table,
    closure: *Closure,
    thread: *Thread,
    string: *LuaString,
    cell: *Cell,
    userdata: *Userdata,

    /// Convert to Value. Returns null for Cell (not a Value variant).
    pub fn toValue(self: GcObject) ?Value {
        return switch (self) {
            .table => |t| .{ .Table = t },
            .closure => |c| .{ .Closure = c },
            .thread => |t| .{ .Thread = t },
            .string => |s| .{ .String = s },
            .userdata => |u| .{ .Userdata = u },
            .cell => null,
        };
    }

    /// Convert from Value. Returns null for non-GC Value variants
    /// (Nil, Bool, Int, Num, Builtin, LightUserdata).
    pub fn fromValue(v: Value) ?GcObject {
        return switch (v) {
            .Table => |t| .{ .table = t },
            .Closure => |c| .{ .closure = c },
            .Thread => |t| .{ .thread = t },
            .String => |s| .{ .string = s },
            .Userdata => |u| .{ .userdata = u },
            else => null,
        };
    }
};

/// Pointer bundle to the flat GC header fields on any GC-managed struct.
/// Returned by `gcPtr()`, used by generic GC code to access marked/age/index
/// without switching on GcObject variant at every access site.
/// P16.16 C1: no `seq` here — only the finalizable types (Table, Userdata)
/// carry a creation sequence, accessed via `gcFinalizableSeq` at the single
/// finalizer-sort site. No fake uniform field for non-finalizable types.
const GcPtr = struct {
    marked: *u8,
    age: *GcAge,
    index: *u32,
};

/// Access the flat GC header fields (gc_marked, gc_age, gc_index) of any
/// GC-managed object through its GcObject tag. This is the single dispatch
/// point that lets generic GC code operate on all types uniformly.
fn gcPtr(obj: GcObject) GcPtr {
    return switch (obj) {
        .table => |t| .{ .marked = &t.gc_marked, .age = &t.gc_age, .index = &t.gc_index },
        .closure => |c| .{ .marked = &c.gc_marked, .age = &c.gc_age, .index = &c.gc_index },
        .thread => |t| .{ .marked = &t.gc_marked, .age = &t.gc_age, .index = &t.gc_index },
        .string => |s| .{ .marked = &s.gc_marked, .age = &s.gc_age, .index = &s.gc_index },
        .cell => |c| .{ .marked = &c.gc_marked, .age = &c.gc_age, .index = &c.gc_index },
        .userdata => |u| .{ .marked = &u.gc_marked, .age = &u.gc_age, .index = &u.gc_index },
    };
}

/// Creation sequence of a finalizable object (Table/Userdata only — the
/// only types `gcCanFinalize` admits, hence the only types ever present in
/// the `finalizables` set and its LIFO sort). Used by `gcFinalizeLessThan`
/// for PUC LIFO finalization order and by `gcRegisterObject` to stamp the
/// sequence at creation. Returns null for non-finalizable types (they carry
/// no seq field — no fake uniform value).
fn gcFinalizableSeqPtr(obj: GcObject) ?*u64 {
    return switch (obj) {
        .table => |t| &t.gc_seq,
        .userdata => |u| &u.gc_seq,
        else => null,
    };
}

/// Byte size of a GC-managed object (for memory accounting).
fn gcObjectBytes(obj: GcObject) usize {
    return switch (obj) {
        .table => |t| @sizeOf(Table) + t.asize * @sizeOf(Value) + t.hash.len * @sizeOf(ltable.Node),
        .closure => @sizeOf(Closure),
        .thread => @sizeOf(Thread),
        // Charged bytes == actually-allocated bytes (PUC luaC_newobj charges
        // luaS_sizelngstr/sizestrshr per kind) — single rule, T7.
        .string => |s| s.allocatedSize(),
        .cell => @sizeOf(Cell),
        .userdata => |u| @sizeOf(Userdata) + u.uservalues.len * @sizeOf(Value) + u.payload.len,
    };
}

/// Whether this object type can have a finalizer (__gc metamethod).
/// PUC: only tables and userdata support finalization — `luaC_checkfinalizer`
/// is called exclusively from `lua_setmetatable` (lapi.c:981,989) for
/// LUA_TTABLE and LUA_TUSERDATA. See the FINALIZEDBIT audit above.
fn gcCanFinalize(obj: GcObject) bool {
    return switch (obj) {
        .table, .userdata => true,
        .closure, .thread, .string, .cell => false,
    };
}

/// `TmsEvent` and `opname` are imported from `tag_method.zig` — the single
/// source of truth for the PUC TMS enum (`ltm.h:19-43`) and its debug
/// opname strings. See `tag_method.zig` for the enum definition and the
/// `isFastCached` / `opname` helpers.
///
/// Non-TMS metafields (`__pairs`, `__tostring`, `__name`, `__metatable`) are
/// NOT part of the TMS enum — PUC handles them via `luaL_getmetafield`
/// (direct string lookup), not via `tmname[]`. They live in `MetaField` below.
/// Non-TMS metafields — metamethod names that PUC Lua does NOT include in
/// the `TMS` enum (`ltm.h:18-45`). PUC handles these via `luaL_getmetafield`
/// (lauxlib.c) or direct `luaH_Hgetshortstr` calls (ltm.c:95 for `__name`),
/// not via `tmname[]`. They are pre-interned separately in `metafield_names`
/// for pointer-identity lookups, mirroring how PUC interns them on demand
/// via `luaS_new(L, "__name")` etc.
///
/// `__iter` does not exist in PUC 5.5 at all (no TMS entry, no metafield
/// lookup). The old luazig `TmsEvent.iter` was dead code — initialized in
/// `tm_names` but never looked up by any dispatch path. Removed entirely.
const MetaField = enum(u8) {
    pairs, // __pairs (lbaselib.c:287 via luaL_getmetafield)
    tostring, // __tostring (lauxlib.c:924 via luaL_callmeta)
    name, // __name (ltm.c:95 via luaH_Hgetshortstr)
    metatable, // __metatable (lbaselib.c:134 via luaL_getmetafield)
};

/// PUC BITRAS-style metamethod cache. Bit set (1) = "this table does NOT
/// have the corresponding metamethod field". All bits start set (no
/// metamethods). Cleared on new-key insertion to force re-check.
/// Checked before hash lookup in `fastTm` / `indexValueDepth` /
/// `tryPushBytecode*Metamethod`.
/// Mirrors lua-5.5.0/src/ltm.h:54 (`maskflags`, `checknoTM`,
/// `invalidateTMcache`) and lua-5.5.0/src/ltable.h:23.
///
/// Only events in the "fast access" zone (`tag_method.isFastCached`,
/// i.e. index..eq) participate in the flags cache. Events above `.eq`
/// always do a full hash lookup.
const TableFlags = struct {
    pub const TM_INDEX: u8 = 1 << @intFromEnum(TmsEvent.index);
    pub const TM_NEWINDEX: u8 = 1 << @intFromEnum(TmsEvent.newindex);
    pub const TM_GC: u8 = 1 << @intFromEnum(TmsEvent.gc);
    pub const TM_MODE: u8 = 1 << @intFromEnum(TmsEvent.mode);
    pub const TM_LEN: u8 = 1 << @intFromEnum(TmsEvent.len);
    pub const TM_EQ: u8 = 1 << @intFromEnum(TmsEvent.eq);
    /// All fast-access metamethod bits. Bits set = "no metamethods present".
    pub const MASK: u8 = 0x3F;

    /// Return the bit for a cached event. Only valid for fast-cached
    /// events (index..eq, see `tag_method.isFastCached`).
    pub fn bit(event: TmsEvent) u8 {
        return @as(u8, 1) << @intCast(@intFromEnum(event));
    }
};

pub const Table = struct {
    gc_age: GcAge = .new,
    /// Position in `Vm.gc_objects` (P16.16 C1: u32; see Cell.gc_index).
    gc_index: u32 = 0,
    /// Monotonic creation sequence — never changes after allocation.
    /// Used for PUC LIFO finalization order (independent of gc_index,
    /// which is corrupted by swapRemove during sweep). P16.16 C1: only
    /// the finalizable types (Table, Userdata) carry a sequence — the
    /// finalizer sort never sees other types, so they carry no seq field.
    gc_seq: u64 = 0,
    /// PUC `marked` byte — tri-color mark bits. See constants above.
    gc_marked: u8 = 0,

    // Array part: keys 1..n stored contiguously. A nil entry inside the array
    // is a "hole"; next()/length skip holes by scanning. Mirrors PUC Lua's
    // `Table` struct: `asize` is the logical array size (allocated slots),
    // `lenhint` is the cached length hint (PUC `*lenhint(t)`). In PUC's model
    // capacity == asize (no over-allocation); trailing nils are valid holes.
    array: []Value = &[_]Value{},
    asize: u32 = 0,
    lenhint: u32 = 0,

    // Unified hash part: one PUC-style chained scatter table (Brent's
    // variation) holding all non-array keys (strings, ints out of array range,
    // tables/closures/threads as pointer keys, bools, etc.). Replaces the old
    // three separate maps (`fields` / `int_keys` / `ptr_keys`).
    //
    // A node with `key == .Nil` is a free slot. A node with a non-nil key but
    // `value == .Nil` is a logically-deleted entry (PUC 5.5 semantics: chain
    // links stay intact, compaction happens at rehash).
    hash: []ltable.Node = &[_]ltable.Node{},

    // High-water-mark cursor for `ltable.nodeInsert`'s getFreePos scan. PUC
    // stores this implicitly; we keep it as a sibling field so nodeInsert can
    // resume its downward scan across calls without rescanning the top of the
    // array each time.
    hash_lastfree: usize = 0,

    metatable: ?*Table = null,

    // PUC BITRAS-style metamethod cache. Bit set (1) = "this table does NOT
    // have the corresponding metamethod field". All bits start set (no
    // metamethods). Cleared on new-key insertion to force re-check.
    // Checked before hash lookup in tableGetValueDepth /
    // tryPushBytecode*Metamethod / setIndexValueDepth.
    // See lua-5.5.0/src/ltm.h:54, lua-5.5.0/src/ltable.h:23.
    //
    // The flags live on the METATABLE itself (the table that contains the
    // metamethod fields), not on the table that has the metatable attached.
    // When checking if table `tbl` has `__index`, we read
    // `tbl.metatable.?.flags & TableFlags.TM_INDEX`.
    flags: u8 = TableFlags.MASK,

    // Testc-only bookkeeping carried over from the old struct. Unrelated to the
    // hash representation; preserved verbatim.
    testc_deferred_vararg_accounting: bool = false,

    pub fn deinit(self: *Table, alloc: std.mem.Allocator) void {
        if (self.array.len != 0) alloc.free(self.array);
        if (self.hash.len != 0) alloc.free(self.hash);
    }
};

/// Full userdata (PUC `LUA_TUSERDATA`). GC-managed, with per-object
/// metatable and an array of user values. Mirrors PUC's `Udata` struct
/// (`lobject.h:491-498`) but uses separate Zig slices instead of PUC's
/// inline `uv[1]` + binary data layout.
///
/// PUC packs `UValue uv[1]` and the binary payload inline after the header,
/// then computes the payload pointer via `getudatamem(u)`. We keep the
/// slices separate: `uservalues` and `payload` are independently allocated
/// and owned by the Userdata (freed in `gcFreeObject`). This is idiomatic
/// Zig and lets the GC trace uservalues without pointer arithmetic, while
/// preserving PUC semantics: per-object metatable, `nuvalue` user values
/// (1-indexed from Lua via `debug.setiuservalue`), and `len` raw bytes.
pub const Userdata = struct {
    gc_marked: u8 = 0,
    gc_age: GcAge = .new,
    /// Position in `Vm.gc_objects` (P16.16 C1: u32; see Cell.gc_index).
    gc_index: u32 = 0,
    /// Monotonic creation sequence for PUC LIFO finalization order
    /// (P16.16 C1: finalizable-types-only; see Table.gc_seq).
    gc_seq: u64 = 0,
    /// Per-object metatable (PUC `Udata.metatable`). Null = no metatable.
    metatable: ?*Table = null,
    /// User values array (PUC `Udata.uv[]`). `nuvalue` elements, all
    /// initialized to Nil. Accessed 1-indexed from Lua via debug.setiuservalue.
    uservalues: []Value = &.{},
    /// Binary payload (PUC `getudatamem(u)`). `len` bytes of raw data.
    /// The testC `newuserdata` command allocates this as zero-filled.
    payload: []u8 = &.{},
};

/// Result of compiling a text chunk through the host-selected bytecode
/// frontend. Diagnostic slices are allocated with the supplied allocator and
/// ownership transfers to the VM caller.
pub const DynamicBytecodeCompileResult = union(enum) {
    proto: *const bc.Proto,
    diagnostic: []u8,
};

/// Optional frontend hook installed by the CLI when `--vm=bc` is active.
/// Keeping codegen outside vm.zig avoids the codegen_bc -> vm import cycle,
/// while ensuring Lua `load`/`loadfile`/`dofile` use the same backend as the
/// outer chunk.
pub const DynamicBytecodeCompiler = *const fn (
    alloc: std.mem.Allocator,
    source: LuaSource,
    chunk: *const lua_ast.Chunk,
) std.mem.Allocator.Error!DynamicBytecodeCompileResult;

/// Default bytecode compiler used when no host-specific compiler is installed
/// (C API states created via `luaL_newstate`/`lua_newstate`). This mirrors
/// `compileDynamicBytecode` in `src/bin/luazig.zig` — the same codegen_bc
/// backend — so C API states have the same compilation path as CLI states.
/// Without this, `compileTextChunk` (used by `loadChunk` for text loading)
/// would fail with "no bytecode compiler configured" on C API states.
pub fn defaultBytecodeCompiler(
    alloc: std.mem.Allocator,
    source: LuaSource,
    chunk: *const lua_ast.Chunk,
) std.mem.Allocator.Error!DynamicBytecodeCompileResult {
    var codegen = lua_codegen_bc.Codegen.init(alloc, source.name, source.bytes);
    defer codegen.deinit();
    const proto = codegen.compileChunk(chunk) catch {
        if (codegen.diag) |d| {
            return .{ .diagnostic = try std.fmt.allocPrint(alloc, ":{d}: {s}", .{ d.line, d.msg }) };
        }
        return .{ .diagnostic = try alloc.dupe(u8, codegen.diagString()) };
    };
    return .{ .proto = proto };
}

/// PUC lauxlib.c:1074-1128 default warnf 3-state machine states. Mirrors
/// PUC's function-pointer swap between `warnfon`/`warnfoff`/`warnfcont`.
/// Initial state is `.on` (warnfon), matching `luaL_newstate` (lauxlib.c:1188).
const WarnfState = enum { on, off, cont };

/// PUC `luai_makeseed` (lauxlib.c:1155-1168): mix `time(NULL)` and the
/// address of a local variable to produce a non-deterministic seed.
fn makeRandomSeed() u64 {
    const t: i64 = std.Io.Timestamp.now(stdio.activeIo(), .real).toSeconds();
    var dummy: u8 = undefined;
    const addr: u64 = @intFromPtr(&dummy);
    // Mix time and address like PUC's addbuff + XOR fold.
    return @as(u64, @bitCast(t)) ^ (addr +% 0x9e3779b97f4a7c15);
}

/// P16.0b: Default-off runtime VM counters, surfaced two ways:
///   * CLI `--stats <out.json>` (src/bin/luazig.zig serializes at exit),
///   * testC module `T.stats()` (returns a Lua table snapshot).
///
/// GATING DESIGN (zero aggregate cost when disabled — A/B measured on
/// ReleaseFast, see STATUS.md "P16.0b"): the struct lives INLINE on the
/// (singleton) Vm. Every instrumented site — including the
/// per-instruction histogram site — checks `self.stats.enabled` directly:
/// one L1 byte-load + predictable never-taken branch (`enabled` is placed
/// right after the per-instruction-written `dispatch_pc`, so it shares a
/// cache line). Two alternatives were measured and REJECTED: (a) a cached
/// `?*VmStats` loop-local pointer costs a register across the whole
/// dispatch switch (+3% on branchy microbenchmarks); (b) converting every
/// counter site to @branchHint(.unlikely) block form — reproducibly WORSE
/// on some benches (+12% comparisons) because the extra block form shifts
/// hot code layout; the codegen layout lottery dominates sub-cycle branch
/// costs. `enabled` is flipped only by the CLI/tests BEFORE execution
/// starts; execution semantics never read these counters.
pub const VmStats = struct {
    enabled: bool = false,

    // ── Instruction histogram (runBytecodeDispatch fetch site) ──
    instructions_total: u64 = 0,
    instructions_by_op: [@typeInfo(bc.Op).@"enum".fields.len]u64 =
        [_]u64{0} ** @typeInfo(bc.Op).@"enum".fields.len,

    // ── Call funnel ──
    /// OP_CALL inline fast path (Lua closure w/ proto, no hooks, no replay).
    calls_fast: u64 = 0,
    /// opCall slow entry (builtin callee / __call chain / hooks / resume).
    calls_slow: u64 = 0,
    /// pushBytecodeExecFrame: EVERY Lua activation (calls_fast + tailcall +
    /// resume + pcall/hook routes). Superset of calls_fast.
    calls_lua_frames: u64 = 0,
    /// callBuiltin entry. A builtin invoked AS a metamethod additionally
    /// counts once in calls_metamethod (documented overlap).
    calls_builtin: u64 = 0,
    calls_metamethod: u64 = 0,
    /// callCFunction entry (C-ABI closures/extensions).
    calls_c: u64 = 0,

    // ── Table access split ──
    // Fast-path counters fire at the typed opcode sites (GETTABLE/GETI/
    // GETFIELD/GETTABUP, SETTABLE/SETI/SETFIELD/SETTABUP). The generic
    // funnels rawGet/rawSet count everything that was NOT served by an
    // inline fast path (incl. non-dispatch callers: helpers, C API, next).
    // Fast-path misses fall through to the funnels, so generic counts also
    // include those. rawSet outcomes are split into insert/update/rehash.
    tbl_get_fast_int: u64 = 0,
    tbl_get_fast_str: u64 = 0,
    tbl_get_generic: u64 = 0,
    tbl_set_fast_int: u64 = 0,
    tbl_set_fast_str: u64 = 0,
    tbl_set_generic: u64 = 0,
    /// New key inserted (nodeInsert sites, incl. post-rehash insertion).
    tbl_insert: u64 = 0,
    /// Existing key written in place (update or nil-delete).
    tbl_update: u64 = 0,
    tbl_rehash: u64 = 0,

    // ── Allocations ──
    /// Count per GC object type, indexed by GcObject tag order
    /// (table, closure, thread, string, cell, userdata).
    alloc_by_type: [@typeInfo(GcObject).@"union".fields.len]u64 =
        [_]u64{0} ** @typeInfo(GcObject).@"union".fields.len,
    /// Approximate pacing bytes as seen by gcNoteAlloc. Exact live total
    /// remains T.totalmem() (tracker-based); this counts allocation volume.
    alloc_bytes_total: u64 = 0,

    // ── GC steps (entries that pass the gc_busy guard) ──
    gc_steps_auto: u64 = 0,
    gc_steps_manual: u64 = 0,

    // ── GC stale-entry debug counters (Task 7) ──
    // Count hits at the gcQueueScanObject/gcDrainGrayagain stale-entry
    // asserts. These should ALWAYS be zero: with the correct grayagain
    // lifecycle (save+clear at atomic, gcCorrectGrayAgain after sweep),
    // no freed object can remain in any GC aux list. Non-zero indicates
    // a lifecycle bug.
    gc_stale_queue_scan: u64 = 0,
    gc_stale_grayagain: u64 = 0,

    // ── Coroutines ──
    yields: u64 = 0,
    resumes: u64 = 0,
    /// Allocs performed on the yield path (th.yielded copies incl. wrap
    /// mode, suspended_builtin_args copy, appendThreadWrapYield copy).
    yield_allocs: u64 = 0,
    /// Allocs performed on the resume path (resume inbox copy, entry_args
    /// save, trampoline args_copy + BytecodeCoroutineContinuation).
    resume_allocs: u64 = 0,
};

pub const Vm = struct {
    const Frame = CallFrame;

    const GmatchState = struct {
        s: *LuaString,
        p: *LuaString,
        pos: usize,
        disallow_empty_at: ?usize = null,
    };

    /// Persistent collector phase, mirroring PUC Lua's `g->gcstate`.
    /// Unlike the old debt gate, every non-pause state owns resumable work
    /// that survives across `collectgarbage("step")` calls.
    /// PUC has 9 GC states. luazig maps them to its simpler 4-state model:
    ///   pause → "pause"
    ///   propagate → "propagate" (includes PUC's propagate + enteratomic)
    ///   atomic → "atomic"
    ///   sweep → maps to PUC's sweepallgc/sweepfinobj/sweeptobefnz/sweepend/callfin
    /// When queried, sweep returns "sweepallgc" (the first sweep sub-state).
    /// `enteratomic` is reported when in propagate phase and close to atomic.
    const GcState = enum { pause, propagate, atomic, sweep };

    fn gcStateName(self: *const Vm) []const u8 {
        return switch (self.gc_state) {
            .pause => "pause",
            .propagate => if (self.gc_gray.items.len == 0) "enteratomic" else "propagate",
            .atomic => "atomic",
            .sweep => "sweepallgc",
        };
    }
    const GcGenPhase = enum { minor, major };

    const FileBuffer = struct {
        mode: enum { full, no, line } = .full,
        pending: std.ArrayListUnmanaged(u8) = .empty,
        pos: u64 = 0,
        /// Pipes and other non-seekable streams use the streaming File API;
        /// ordinary files keep positional I/O so Lua's independent file
        /// position remains explicit in this descriptor.
        sequential: bool = false,
        unread_byte: ?u8 = null,
    };

    const ManagedFileClose = union(enum) {
        regular,
        process: std.process.Child.Term,
        wait_error: []const u8,
    };

    alloc: std.mem.Allocator,
    /// Optional pointer to TrackingAllocator.total_bytes for accurate
    /// `collectgarbage("count")`. Set by the main binary; null in tests
    /// and sub-VMs (which fall back to approximate gc_count_kb).
    /// The tracker itself lives OUTSIDE the Vm (in the main binary) to
    /// avoid nested-allocator chains.
    tracker_total: ?*usize = null,
    tracker_alloc_count: ?*usize = null,
    tracker_free_count: ?*usize = null,
    /// Scratch AST arena reused by runtime `load`/`loadfile`/`dofile`. The
    /// generated IR/Proto owns every value that survives compilation, so AST
    /// storage can be reset immediately after each frontend invocation.
    dynamic_ast_arena: lua_ast.AstArena,
    dynamic_bytecode_compiler: ?DynamicBytecodeCompiler = null,
    global_env: *Table,
    string_metatable: *Table,
    string_metatable_enabled: bool = true,
    number_metatable: ?*Table = null,
    boolean_metatable: ?*Table = null,
    nil_metatable: ?*Table = null,
    function_metatable: ?*Table = null,
    thread_metatable: ?*Table = null,
    // PUC mt[LUA_TLIGHTUSERDATA]: a single shared metatable for all light
    // userdata values (which are plain pointers, not GC-objects). Set via
    // debug.setmetatable / setmetatable builtin when the value is light
    // userdata.
    light_userdata_metatable: ?*Table = null,
    /// Pre-interned metamethod name strings, indexed by `TmsEvent`.
    /// Used by `fastTm`/`getTm` for pointer-identity key comparison (avoids
    /// `internStrAssume` hashmap lookup on every metamethod check).
    /// Populated in `Vm.init` after `string_intern` is ready.
    /// Entries for fast-cached events (index..eq) are the 6 cached
    /// metamethods; entries above are for non-cached events (still useful
    /// for key comparison in `getTm` lookups).
    tm_names: [@typeInfo(TmsEvent).@"enum".fields.len]*LuaString = undefined,
    /// Pre-interned non-TMS metafield name strings, indexed by `MetaField`.
    /// These are the metamethod names that PUC does NOT include in `TMS`
    /// (`__pairs`, `__tostring`, `__name`, `__metatable`). PUC looks them up
    /// via `luaL_getmetafield` / `luaH_Hgetshortstr` with on-demand interning.
    /// We pre-intern them for the same pointer-identity fast path as `tm_names`.
    metafield_names: [@typeInfo(MetaField).@"enum".fields.len]*LuaString = undefined,
    /// PUC lmathlib.c `setrandfunc`: the initial seed comes from
    /// `luaL_makeseed` which mixes `time(NULL)` + a stack address.
    /// We approximate with `std.time.timestamp()` + address of a local.
    /// The seed is then "spread" by 16 discard iterations (setseed).
    rng_state: [4]u64 = .{ 1, 0xff, 0, 0 },

    // Stable hash seed for `ltable.keyHash` (hashes every int/pointer key on
    // each lookup) and for `internStr` (Wyhash init seed for string content).
    // MUST be invariant across the Vm's lifetime: a mutating seed (e.g. reading
    // rng_state mid-run) would orphan every prior insert and break intern-table
    // lookups for strings interned earlier.
    //
    // PUC Lua initializes `g->seed` once per lua_State from entropy via
    // `luai_makeseed` (lauxlib.c:1155 — time + address mixing) in `lua_newstate`
    // (lstate.c:354). The seed is stable for the state's lifetime and is NEVER
    // mutated by `math.random`/`math.randomseed` — those operate on a separate
    // `Rand64` state stored in the math library's uservalue (lmathlib.c:617-642).
    // We mirror this: `hash_seed` is set once in `Vm.init` from `makeRandomSeed`
    // (same time+address entropy as PUC) and never touched again. The PRNG
    // (`rng_state`) is a completely separate field, warmed up in
    // `bootstrapGlobals` via `randomSetSeed`.
    //
    // A zero seed makes `hash_search`'s `rnd = 0`, so the exponential probe
    // always doubles (j = j*2 + 0), which an attacker can exploit by inserting
    // exactly the powers of 2 — the "attack on table length" test in nextvar.lua.
    // A non-zero seed breaks the attack: `rnd & 1` is sometimes 1, so the probe
    // hits a non-present key and terminates early.
    //
    // Coherence invariant: `internStr` computes `Wyhash.init(hash_seed)` and
    // caches the result in `LuaString.hash`. `ltable.keyHash(.String)` returns
    // `s.hash` (the cached value). Both paths consume the same `hash_seed`, so
    // a string interned and used as a table key is always found. See the
    // coherence test "hash_seed: intern/table-key coherence" below.
    hash_seed: u64 = 0,

    // Content→canonical *LuaString dedup table. All `Value.String` pointers
    // come from here, so string equality reduces to pointer comparison.
    string_intern: StringTable = .{},
    /// Dedup cache for long string constants (> 40 bytes) loaded from
    /// bytecode constant pools. PUC Lua shares these across functions
    /// in the same chunk; we replicate that here.
    long_string_cache: std.StringHashMapUnmanaged(*LuaString) = .{},
    // Long string literals (loaded via ConstString) are deduped by content at
    // compile time regardless of length, like PUC's per-Proto constant table
    // (luaK_stringK search). Long RUNTIME strings (string.rep/concat/format)
    // are NOT deduped — they go through `internStr` which allocates them fresh.
    // So a separate table is needed: a long literal and a long runtime string
    // with the same content must have distinct pointers.
    long_literals: StringIntern = .{},
    /// Set of objects (tables and userdata) that have a __gc metamethod.
    /// During the atomic phase, white (unreachable) objects in this set
    /// are queued for finalization. PUC uses the FINALIZEDBIT on each
    /// object + the tobefnz list; we use a HashSet for the same purpose.
    finalizables: std.AutoHashMapUnmanaged(GcObject, void) = .{},
    debug_registry: ?*Table = null,

    /// PUC `-E` flag (lua.c:720-723): when true, the VM ignores LUA_PATH /
    /// LUA_CPATH / LUA_INIT_5_5 / LUA_INIT environment variables and uses
    /// the compiled-in default package paths. PUC signals this by pushing
    /// a boolean into the registry under "LUA_NOENV" before `luai_openlibs`;
    /// `setpath` (loadlib.c:282) then checks `noenv(L)` and skips the
    /// `getenv` calls entirely. We mirror that by checking this flag inside
    /// `resolveEnvPath` so env vars are never read when `-E` is set.
    noenv: bool = false,

    // Universal registry of every GC-able object allocated during the VM's
    // lifetime. Each object is appended exactly once at its allocation site;
    // the GC sweep phase enumerates this list to find and free unreachable
    // objects. `Vm.deinit` drains it as the single ownership point for object
    // destruction at teardown.
    //
    // This replaces PUC Lua's intrusive `GCObject.next` singly-linked list
    // (`g->allgc`) with a single `ArrayList(GcObject)` living on the Vm.
    // Overhead is one pointer per object — identical to PUC's intrusive node —
    // with zero layout change to the managed types, type-safe iteration, and
    // no pointer-juggling during sweep (`swapRemove` is O(1)).
    gc_objects: std.ArrayListUnmanaged(GcObject) = .empty,
    gc_objects_snapshot_len: usize = 0,
    /// Monotonic creation counter — never decreases. Used for PUC LIFO
    /// finalization order. Unlike `gc_index` (which is corrupted by
    /// `swapRemove` during sweep), `gc_seq` is set once at allocation
    /// and never changed.
    gc_creation_seq: u64 = 0,
    // (P16.10b Task 6) The old VM-global `pinned_source_strings` list is
    // RETIRED: source pins now live on each tree's root Proto (CUT2)
    // (`source_backing.pinned`) and are marked through the closure
    // traversal (gcMarkBytecodeProto), like PUC's traverseLClosure. Pins
    // therefore die with their trees instead of accumulating for the VM's
    // whole lifetime.
    /// Temporary GC roots (Handle API). Builtins push Values here to protect
    /// newly-allocated objects held in Zig locals across subsequent allocations
    /// that may trigger GC. The scope helper `gcTempRoots()` snapshots the
    /// length; `defer .end()` restores it. GC mark phase traverses this list
    /// in `gcMarkVmRoots`. Non-moving GC → no indirection needed (unlike V8's
    /// HandleScope), just root registration.
    gc_temp_roots: std.ArrayListUnmanaged(Value) = .empty,

    gc_running: bool = true,
    gc_mode: enum { incremental, generational } = .incremental,
    gc_gen_phase: GcGenPhase = .minor,
    /// PUC `g->gcparams[LUA_GCPN]` (lstate.h:338) — 6 coded `lu_byte` values.
    /// Each param is a floating-point byte (eeee xxxx format) decoded by
    /// `gcApplyParam`. Index order matches PUC lua.h:347-354:
    ///   [0]=MINORMUL(20), [1]=MAJORMINOR(50), [2]=MINORMAJOR(70),
    ///   [3]=PAUSE(250), [4]=STEPMUL(200), [5]=STEPSIZE(9600).
    /// Initialized in `init` via `gcCodeParam` with PUC defaults.
    gcparams: [6]u8 = .{ 0, 0, 0, 0, 0, 0 },
    /// PUC `g->gcstp` (lgc.h:213-215): GC stop bits.
    ///   GCSTPUSR=1 (user stop), GCSTPGC=2 (internal stop),
    ///   GCSTPCLS=4 (closing state). `gcrunning(g)` = (gcstp == 0).
    /// `gc_running` is kept as a hot-path cache of `(gc_stp == 0)`.
    gc_stp: u8 = 0,
    gc_gen_major_base_kb: f64 = 0.0,
    gc_gen_major_start_kb: f64 = 0.0,
    gc_gen_added_old_kb: f64 = 0.0,
    /// PUC GCmarked equivalent for major mode: total KB of objects marked
    /// during the atomic phase. Used by checkmajorminor to compute
    /// tobecollected = total - marked.
    gc_gen_marked_kb: f64 = 0.0,

    // Generational registries mirror PUC's nursery/survival/old1 and
    // grayagain lists without requiring intrusive links in every object.
    // Minor collections walk only these lists, not the complete old heap.
    /// Unified young list for generational GC.
    gc_young_objects: std.ArrayListUnmanaged(GcObject) = .empty,
    gc_young_objects_snapshot_len: usize = 0,
    /// PUC lgc.c uses a single gclist per object; we mirror that by keeping
    /// one list per role.
    gc_old1: std.ArrayListUnmanaged(GcObject) = .empty,
    gc_grayagain: std.ArrayListUnmanaged(GcObject) = .empty,
    gc_gen_threads: std.ArrayListUnmanaged(*Thread) = .empty,
    gc_gen_last_minor_visited: usize = 0,
    gc_gen_last_minor_old_visited: usize = 0,
    gc_minor_cycle: bool = false,
    gc_old1_snapshot_len: usize = 0,
    gc_grayagain_snapshot_len: usize = 0,

    // Persistent incremental collector state. Mark sets and gray/weak queues
    // are retained between steps, so each step performs bounded real work
    // instead of decrementing a synthetic debt counter before one full cycle.
    gc_state: GcState = .pause,
    /// PUC `currentwhite` — which white bit (WHITE0BIT or WHITE1BIT) is
    /// active for the current GC cycle. New objects get this bit on
    /// creation. Flips at the end of each cycle (PUC lgc.c:1579).
    /// Starts with WHITE0BIT (PUC initializes to WHITE0BIT in luaC_init).
    gc_current_white: u8 = WHITE0BIT,
    /// Monotonically increasing counter, bumped every time a white object
    /// transitions to gray or black during this cycle. The ephemeron fixpoint
    /// (`gcPropagateEphemerons`) uses it to detect convergence: if a full pass
    /// + drainGray does not bump the epoch, no new objects were marked and the
    /// fixpoint has settled. This replaces the old HashSet `.count()` growth
    /// check with a PUC-faithful equivalent (PUC tracks work via `g->gcstate`
    /// transitions and the gray list; the epoch serves the same "did marking
    /// progress?" role without an external side-table).
    gc_mark_epoch: u64 = 0,
    gc_busy: bool = false,
    gc_do_sweep: bool = true,
    /// PUC lstate.c `close_state` sets `g->gcstp = GCSTPCLS` before running
    /// finalizers, which prevents new finalizers from being queued and makes
    /// `collectgarbage()` return false. This flag mirrors that behavior:
    /// when true, the VM is in the state-closing sequence triggered by
    /// `os.exit(_, true)`. Re-entrant `os.exit` calls become no-ops, and
    /// `collectgarbage()` returns false (PUC `callallpendingfinalizers`
    /// runs under GCSTPCLS, which blocks new cycles).
    is_closing: bool = false,
    /// When `os.exit(code, true)` is called from within a finalizer during
    /// the state-closing sequence, PUC's re-entrant `lua_close` runs all
    /// remaining finalizers and then calls `exit(code)`. We can't call
    /// `std.process.exit` immediately (remaining finalizers must run first),
    /// so we store the exit code here and call `std.process.exit` after
    /// `gcFinalizeAtClose` completes.
    pending_exit_code: ?u8 = null,
    /// PUC lgc.h `g->gray` — objects painted gray awaiting propagation.
    /// A3: migrated from ArrayList(Value) to ArrayList(GcObject) so that
    /// Cell (not a Value variant) can flow through the same gray queue as
    /// tables/closures/threads/strings. PUC has a single gray list with a
    /// tagged-union GCObject; this is the Zig-idiomatic equivalent.
    gc_gray: std.ArrayListUnmanaged(GcObject) = .empty,
    gc_marked_tables: std.AutoHashMapUnmanaged(*Table, void) = .{},
    gc_marked_closures: std.AutoHashMapUnmanaged(*Closure, void) = .{},
    gc_marked_threads: std.AutoHashMapUnmanaged(*Thread, void) = .{},
    gc_weak_tables: std.ArrayListUnmanaged(*Table) = .empty,
    gc_fin_tables: std.AutoHashMapUnmanaged(*Table, void) = .{},
    gc_fin_closures: std.AutoHashMapUnmanaged(*Closure, void) = .{},
    gc_fin_threads: std.AutoHashMapUnmanaged(*Thread, void) = .{},
    gc_to_finalize: std.ArrayListUnmanaged(GcObject) = .empty,
    /// Incremental sweep cursor over `gc_objects`. Walks from 0 to
    /// `gc_objects_snapshot_len` (set at cycle start in `gcStartCycle`).
    /// PUC-faithful: sweeps `allgc` in allocation order.
    gc_sweep_objects_cursor: usize = 0,
    gc_alloc_tables: usize = 0,
    // Allocation sites and the dispatch loop periodically *check* this debt
    // threshold. They no longer run a full collection merely because a fixed
    // number of VM instructions elapsed: doing so repeatedly rescanned a large
    // live heap and made repeated dynamic-load workloads quadratic. Like PUC's
    // pause/debt model,
    // the next automatic cycle is scheduled from the live heap size left by the
    // previous cycle.
    gc_alloc_threshold: usize = 20000,
    gc_auto_threshold_kb: f64 = 32768.0,
    gc_finalizer_tick_pending: bool = false,
    /// PUC GCdebt analogue — kept on Vm (not tracker) for exact behavioral
    /// match with the pre-tracking-allocator code.
    gc_step_debt_kb: f64 = 0.0,
    gc_finalizer_epoch: usize = 0,
    gc_cycle_finalizer_epoch: usize = 0,
    /// Number of finalizers called in the most recent atomic phase.
    /// Used by gcFullCollectionForUser to decide if a second cycle is needed
    /// to free the finalized objects (PUC sweeptobefnz).
    gc_finalizers_ran_count: usize = 0,
    gc_tick: usize = 0,
    gc_inst: usize = 0,
    gc_last_table_inst: usize = 0,
    /// Approximate GC memory counter for GC PACING ONLY.
    /// `collectgarbage("count")` reads the accurate `tracker.total_bytes`
    /// instead. This counter is kept for threshold calculations because
    /// its approximate behavior (undercounting → more aggressive GC)
    /// compensates for GC effectiveness gaps. TODO: remove once GC
    /// correctly reclaims all dead objects.
    gc_count_kb: f64 = 0.0,
    testc_gc_count_bonus_once_kb: f64 = 0.0,
    testc_gc_manual_kb: f64 = 0.0,
    testc_gc_pending_finalize_kb: f64 = 0.0,
    testc_gc_pending_finalize_seen: bool = false,
    testc_total_bytes: usize = 0,
    testc_mem_limit: ?usize = null,
    /// PUC lauxlib.c:1074-1128 default warnf 3-state machine.
    /// State of the current warnf handler, mirroring PUC's function-pointer
    /// swap between `warnfon`/`warnfoff`/`warnfcont`. Initial state is `.on`
    /// (warnfon), matching `luaL_newstate` (lauxlib.c:1188:
    /// `lua_setwarnf(L, warnfon, L)`). The stand-alone launcher later sends
    /// `@off` to disable warnings by default (lua.c:352), matching PUC.
    warnf_state: WarnfState = .on,

    /// PUC ltests.c:95-156 testC warnf state. Active only when
    /// `testc_warn_enabled` is set by `enableTestcModuleInternal`
    /// (mirrors PUC `luaB_opentests` replacing the default warnf with the
    /// testC version). mode: 0=normal, 1=allow, 2=store.
    /// onoff: 0=off, 1=on. buff: buffer for multi-part warnings.
    /// lasttocont: whether the previous piece had tocont=1.
    testc_warn_enabled: bool = false,
    testc_warn_mode: u8 = 0,
    testc_warn_onoff: bool = false,
    testc_warn_buff: std.ArrayListUnmanaged(u8) = .empty,
    testc_warn_lasttocont: bool = false,
    /// PUC lua_status(L1) equivalent for testC `threadstatus` command.
    /// Set by checkpanic when catching the sub-VM error. Mirrors PUC
    /// statcodes[]: "OK" (default), "ERRRUN", or "not enough memory"
    /// (statcodes[ERRMEM] == MEMERRMSG — the message IS the status string).
    testc_thread_status: []const u8 = "OK",
    testc_obj_tables: usize = 0,
    testc_obj_functions: usize = 0,
    testc_obj_threads: usize = 0,
    testc_obj_strings: usize = 0,
    testc_obj_userdata: usize = 0,
    // "Allocation-based" triggering is too limited (strings/functions also
    // allocate). To keep the upstream GC tests progressing, also run a
    // best-effort cycle periodically based on VM instruction count.
    gc_tick_threshold: usize = 20000,

    /// P15.33: Cached hook-active flag. Updated by `refreshHooksCached()`
    /// whenever debug.sethook modifies hook state, so the dispatch loop only
    /// needs a single bool read instead of calling activeHookState() per
    /// instruction.
    hooks_active_cached: bool = false,
    /// P16.19 T5 (Experiment A): combined per-instruction dispatch gate.
    /// bit0 HOOKS mirrors hooks_active_cached, bit1 STATS mirrors
    /// stats.enabled; both maintained at exactly the sites that already
    /// write those flags. The hot loop pays ONE load + ONE branch for both
    /// (PUC vmfetch also pays one trap branch — this is shape parity).
    dispatch_gate: u8 = 0,

    /// Current dispatch pc — mirrors PUC's `ci->u.l.savedpc` but kept
    /// up-to-date per-instruction so that fail() and GC safepoints can read
    /// the current pc without the dispatch loop syncing to the frame.
    /// Written at the top of the inner dispatch loop.
    dispatch_pc: usize = 0,

    /// P16.0b: default-off runtime counters (see VmStats). Inline on the
    /// singleton Vm: ~250 bytes of cold-when-disabled state is acceptable
    /// on a heap singleton, and the `enabled` bool gates every counter
    /// site with one predictable branch.
    stats: VmStats = .{},

    // ── Shared bytecode stack (PUC Lua model) ──
    // A single contiguous array that serves as the register file for ALL
    // bytecode frames. Each frame occupies bc_stack[base .. base+maxstack].
    // No per-frame heap allocation. Stack grows via realloc when needed.
    // After realloc, all `base` offsets in frames are still valid.
    bc_stack: []Value = &.{},
    bc_boxed: []?*Cell = &.{}, // parallel to bc_stack — open upvalue cells per slot
    bc_stack_top: usize = 0, // high-water mark (next available slot)
    bc_stack_initial: usize = 2048,
    /// Per-frame TBC register indices. Tracks registers marked as
    /// to-be-closed by the TBC opcode. CLOSE calls __close on these.
    bc_tbc_regs: std.ArrayListUnmanaged(u8) = .empty,

    /// C API stack for lua_State-compatible push/pop operations.
    /// Used by C extension functions loaded via package.loadlib (and by the
    /// exported `lua_*` C-ABI shim in `c_api.zig`).
    ///
    /// Deliberately separate from `bc_stack` (the bytecode register file).
    /// PUC Lua's `lua_State` keeps the C-API stack and the VM-internal call
    /// frames on the same `L->stack` array, distinguishing them only by
    /// `base`/`top` pointers. We mirror the *semantics* — C push/pop is
    /// distinct from in-flight bytecode registers — with a dedicated
    /// `ArrayListUnmanaged(Value)`, which avoids entangling C-API operations
    /// with the bytecode dispatch loop's active register window.
    ///
    /// **Phase 2:** This is a pointer to the active handle's `c_stack` field
    /// (`&cur_handle.c_stack`). It is reassigned only during coroutine
    /// resume/return (switching to/from the coroutine's handle). During
    /// `callCFunction`/`finishCcall` stack swaps, the pointer itself stays
    /// fixed — the swap operates on `cur_c_stack.*` (the value pointed to).
    cur_c_stack: *std.ArrayListUnmanaged(Value) = undefined,

    /// Active `jmp_buf` for the C-function error boundary (PUC's
    /// `L->errorjmp`). `null` while no C extension runs through the boundary.
    /// `callCFunctionWithBoundary` installs the address of its stack-local
    /// `JmpBuf` here before calling the C function; `lua_error` (c_api.zig)
    /// reads it and `_longjmp`s to it. Stored as `?*anyopaque` because
    /// `JmpBuf` is private to vm.zig — c_api.zig only needs to forward the
    /// pointer to `_longjmp`, never to inspect it.
    c_error_jmp: ?*anyopaque = null,

    /// Error value captured by `lua_error` before the `_longjmp`, so the Zig
    /// dispatch path can read it after the boundary returns -1 (PUC's
    /// `L->top` at throw time). Mirrors how `fail`/`err_obj` carry the error
    /// object for native runtime errors; `callCFunction`'s error path copies
    /// this into `err_obj` so the rest of the VM's error machinery (pcall,
    /// tracebacks, coroutine resume) sees a uniform error object.
    c_error_value: ?Value = null,

    /// PUC `L->warnf` (lstate.c): warning handler installed by `lua_setwarnf`.
    /// When non-null, `lua_warning` forwards the message to this callback.
    /// `null` means warnings are silently dropped (PUC's default when no
    /// handler is installed — `lua_setwarnf(L, NULL, ud)` disables warnings).
    c_warnf: ?*const fn (?*anyopaque, [*:0]const u8, c_int) callconv(.c) void = null,

    /// PUC `L->ud_warn` (lstate.c): user data passed to the warning handler.
    /// Paired with `c_warnf`; set together by `lua_setwarnf`.
    c_warn_ud: ?*anyopaque = null,

    // P15.83h: C hook state (c_hook/c_hook_mask/c_hook_count) moved from Vm
    // to DebugHookState (per-thread). PUC stores L->hook/hookmask/
    // basehookcount per lua_State; DebugHookState lives on Thread, which is
    // the PUC-faithful home. lua_sethook/lua_gethook etc. resolve the thread
    // via the handle and access the thread's DebugHookState.

    /// PUC `G->panic` (lstate.c:142): the panic function called by `luaD_throw`
    /// when an error propagates past the last protected call boundary. Set by
    /// `lua_atpanic` (lapi.c:lua_atpanic). Returns the previous panic function.
    c_panicf: ?*const fn (?*lua_State) callconv(.c) c_int = null,

    /// Currently executing C closure (set by runClosure before calling
    /// callCFunction). Used to resolve upvalue pseudo-indices
    /// (lua_upvalueindex) in the C API.
    c_active_closure: ?*Closure = null,

    /// The thread most recently created via C API `lua_newthread`. The
    /// internal Zig-level `api.State` helpers (`api.zig` `status` /
    /// `pushthread`) use it as "the current thread" because they carry no
    /// handle context; the C API proper ignores it and resolves threads from
    /// each handle's own `lua_State.thread` field (P15.83e/k) — `lua_resume`
    /// in particular resolves the thread exclusively via the handle.
    c_api_thread: ?*Thread = null,

    /// The active `lua_State` handle for C function calls. `callCFunction`
    /// passes `cur_handle` to the C function as its `?*lua_State` argument,
    /// matching PUC's `(*f)(L)` contract. Set by `setupMainHandle` (main
    /// state) and switched to the coroutine's handle for the duration of a
    /// C API `lua_resume` (restored afterwards; c_api.zig:lua_resume).
    /// `null` before `setupMainHandle` is called — `callCFunction` asserts
    /// non-null.
    cur_handle: ?*lua_State = null,

    /// The main state handle (created by `luaL_newstate` / `lua_newstate`).
    /// Freed by `lua_close` alongside the Vm. Coroutine handles are freed
    /// by `gcFreeObject(.thread)` via `Thread.api_handle`.
    main_handle: ?*lua_State = null,

    /// P15.78: Continuation invocation scratch space. `finishCcall` stores
    /// the saved k/status/ctx here so `callContWrapper` (a C-callable shim
    /// with the `lua_CFunction` signature) can dispatch to `k(L, status, ctx)`
    /// through `callCFunctionWithBoundary`. This is needed because `k` has
    /// signature `fn(?*lua_State, c_int, isize) c_int` (3 args), while
    /// `callCFunctionWithBoundary` expects `fn(?*lua_State) c_int` (1 arg).
    c_cont_k: ?*const fn (?*lua_State, c_int, isize) callconv(.c) c_int = null,
    c_cont_status: c_int = 0,
    c_cont_ctx: isize = 0,

    /// PUC `L->l_G->ud` / `L->l_G->frealloc` (lstate.c): custom C allocator
    /// function and its opaque user-data, set by `lua_newstate` /
    /// `lua_setallocf`. When non-null, `lua_getallocf` returns these so C
    /// code can inspect or replace the allocator — matching PUC's contract.
    ///
    /// The VM's actual allocations continue to go through `self.alloc`
    /// (currently `std.heap.c_allocator`). A full bridge that routes every
    /// `vm.alloc` call through `c_alloc_fn` would require a custom
    /// `std.mem.Allocator` vtable wrapping the C function. Since 99% of
    /// C `lua_Alloc` implementations wrap `realloc`/`free` (which is exactly
    /// what `c_allocator` does), the pragmatic choice is to store the
    /// function + ud for `lua_getallocf` round-tripping while delegating
    /// actual allocation to `c_allocator`. This preserves the observable
    /// contract (getallocf returns what was set) without a pervasive
    /// vtable that would complicate every allocation site.
    c_alloc_fn: ?*const fn (?*anyopaque, ?*anyopaque, usize, usize) callconv(.c) ?*anyopaque = null,
    c_alloc_ud: ?*anyopaque = null,

    /// PUC `L->ci->tbclist` (ldo.c): C-stack slots marked for auto-closing
    /// by `lua_toclose`. Stored as absolute indices into the handle's
    /// `c_stack`. When `lua_closeslot` is called, or when the owning C
    /// function returns (each C frame snapshots `toclose_base` in
    /// `callCFunction` and closes slots in `[toclose_base, len)` on unwind —
    /// P15.83c), the VM invokes the `__close` metamethod on the value at
    /// each marked slot. PUC chains these as a linked list on the stack;
    /// we use a simple ArrayList since the C API typically marks few slots.
    c_toclose_slots: std.ArrayListUnmanaged(usize) = .empty,

    /// Monotonic counter backing `luaL_ref` (PUC lauxlib's `t->alref`).
    /// Each successful ref allocates the next integer key in the registry
    /// table, mirroring PUC's scheme where freed refs are recycled via a
    /// free-list. We use a plain growing counter for now; correctness of the
    /// ref→value mapping does not depend on recycling.
    c_ref_counter: i64 = 0,

    /// PUC `CLIBS` (loadlib.c:54): cache of opened C shared-library handles.
    /// Maps absolute or relative path → dlopen handle. PUC stores this in the
    /// registry under `"_CLIBS"`; we store it directly on the Vm for
    /// simplicity. Handles are intentionally never closed. Although PUC closes
    /// them via the CLIBS `__gc` finalizer at `lua_close`, we keep them alive
    /// for the process lifetime because loaded C extensions may have registered
    /// `__gc` finalizers or cached pointers from the .so.
    ///
    /// The cache enables PUC's `lookforfunc` flow: `package.loadlib(p, "*")`
    /// probes with `RTLD_GLOBAL` and caches the handle; subsequent
    /// `package.loadlib(p, "symbol")` reuses the cached handle (and thus the
    /// global visibility) instead of re-dlopen'ing.
    c_libs: std.StringHashMapUnmanaged(*anyopaque) = .empty,

    /// P15.35: Scratch buffer for return values (OP_RETURN0/1/return fast path).
    /// When the return fast path has no pending TBC closers and no debug hooks,
    /// return values are stashed here instead of heap-allocating a buffer.
    /// `completeBytecodeExecFrame` and the `applyBytecodePending*` family detect
    /// this slice by pointer identity and skip the free.
    /// This mirrors PUC Lua, where return values live in known register slots
    /// (L->top) rather than separately allocated buffers.
    /// Sized to 32 — covers the vast majority of multi-value returns without
    /// adding excessive cache pressure to the Vm struct. Returns with more than
    /// 32 values fall back to the heap-allocated slow path.
    bc_return_scratch: [1]Value = .{.Nil},

    err: ?[]const u8 = null,
    err_obj: Value = .Nil,
    err_has_obj: bool = false,
    /// P15.83q: C-frame residue of the raising builtin (PUC lbaselib
    /// luaB_error, level >= 1 with a string argument): luaB_error pushes
    /// `luaL_where` + a copy of the argument and concatenates them, so the
    /// ORIGINAL argument string remains on the error() C-frame BELOW the
    /// built message. At a lua_resume error boundary, PUC's visible window
    /// is that whole C-frame area: [orig, prefixed-msg, prefixed-msg-dup]
    /// (luaD_seterrorobj duplicates top-1). This field transcribes the
    /// `orig` slot: set by error()/assert() when they prefix a string
    /// message, snapshotted onto the failing thread by
    /// builtinCoroutineResume's error tail, exposed by c_api lua_resume as
    /// the window's leading slot. Save/restored alongside the other err_*
    /// fields at every protected boundary (pcall/xpcall/resume), so a
    /// recovered error never leaks a stale residue into a later window.
    err_cframe_residue: ?Value = null,
    /// PUC LUA_ERRERR signal (PUC luaD_rawrunprotected in ldo.c): set by
    /// invokeErrfunc when the message handler itself errors, signalling that
    /// the error status should be LUA_ERRERR (5) instead of LUA_ERRRUN (2).
    /// Reset to false at every error-throw site BEFORE invokeErrfunc so fresh
    /// errors start as LUA_ERRRUN. Read by status-determination sites (pcall
    /// catch, precover, lua_resume, lua_pcallk) to pick the correct status.
    err_is_errerr: bool = false,
    err_buf: [2048]u8 = undefined,
    err_render_buf: [512]u8 = undefined,
    err_source: ?[]const u8 = null,
    err_line: i64 = -1,
    err_traceback: ?[]u8 = null,
    /// When non-null, the traceback inserts a synthetic C-frame line at the
    /// top (most recent). Format: `\t[C]: in {label}`.
    /// Examples: `"global 'error'"`, `"field 'yield'"`.
    /// Set by callers before invoking failC/fail for C-function errors that
    /// need their frame visible in the traceback (matching PUC's CallInfo).
    err_cfunc_label: ?[]const u8 = null,
    oom_context: ?[]const u8 = null,
    oom_table_array_len: usize = 0,
    oom_table_array_capacity: usize = 0,
    in_error_handler: usize = 0,
    protected_call_depth: usize = 0,
    // P15.78: errfunc and errfunc_running moved from Vm to Thread, matching
    // PUC's L->errfunc on lua_State (not global_State). See Thread.errfunc.
    /// Native pcall/xpcall activations are not represented in `frames`, but
    /// `error(message, level)` must still count them while resolving a source
    /// location. Store the Lua-frame depth at each native protected boundary.
    protected_c_frame_depths: [128]usize = undefined,
    protected_c_frame_count: usize = 0,
    close_metamethod_depth: usize = 0,
    close_metamethod_err_depth: usize = 0,
    testc_close_metamethod_depth: usize = 0,
    /// True when the testC module (`T`) is enabled via `--testc`.
    /// In testC mode, `global` is a reserved keyword (PUC Lua ltests behavior
    /// without LUA_COMPAT_GLOBAL). In normal mode, `global` is a regular name
    /// (PUC Lua compatibility mode with LUA_COMPAT_GLOBAL).
    testc_module_enabled: bool = false,
    coroutine_close_depth: usize = 0,
    current_thread: ?*Thread = null,
    /// Thread whose runtime buffers are currently borrowed by `frames`,
    /// `bc_stack`, `bc_boxed`, and `bc_tbc_regs` below.
    active_runtime_thread: ?*Thread = null,
    debug_hook_main: DebugHookState = .{},
    /// Yield capability captured for the synchronous/frozen-IR hook path.
    /// Bytecode hooks carry the same bit on RuntimeFrame instead.
    debug_hook_allow_yield: bool = false,
    debug_hooks_suppressed: usize = 0,

    /// P15.38i: PUC-style builtin results on bc_stack. When callBuiltin is
    /// invoked from the bytecode dispatch loop, results are written directly
    /// to bc_stack[outs_base..outs_base+outs_len] (above the arguments),
    /// matching PUC Lua's model where C functions write results to L->top.p.
    /// This eliminates the outs_small local buffer and the dupe for debug
    /// hook transfer values.
    ///
    /// Builtins with re-entry (pcall, xpcall, tostring with __tostring, etc.)
    /// use these fields to re-derive their outs slice after nested Lua calls
    /// that may realloc bc_stack — PUC's savestack/restorestack equivalent.
    builtin_outs_base: usize = 0,
    builtin_outs_len: usize = 0,
    builtin_outs_on_bc_stack: bool = false,
    /// P15.83r: set by the OP_CALL/OP_TAILCALL/OP_TFORCALL dispatch sites when
    /// they pre-pushed the builtin's C-frame so the CALL hook could fire on
    /// the C activation (PUC precallC ordering). callBuiltin consumes (clears)
    /// it at entry and REUSES that frame instead of pushing its own — exactly
    /// one frame per builtin invocation, whoever pushed it. The diverting
    /// fast-path branches (pairs/pcall/coroutine-switch/gsub) pop the
    /// pre-pushed frame themselves before installing their continuations,
    /// because the iterative completion machinery requires the callee body
    /// frame to sit directly above its pending-call owner (see the
    /// `parent.isC()` return routing in runBytecodeInternal's frame-return
    /// path — a plain builtin C-frame there has no continuation k and would
    /// be misrouted to finishCcall).
    builtin_cframe_pre_pushed: bool = false,
    debug_transfer_values: ?[]const Value = null,
    debug_transfer_start: i64 = 1,
    debug_hook_event_calllike: bool = false,
    debug_hook_event_tailcall: bool = false,
    debug_hook_event_is_count: bool = false,
    /// P15.51n: Vm-level pending call storage (moved from CallFrame).
    ///
    /// ## Design rationale
    ///
    /// Pending call continuations are stored at the Vm level rather than
    /// per-Thread. This is a deliberate design choice: during coroutine
    /// resume/yield, `self.activeBytecodeThread()` returns the wrong thread
    /// (the resumed coroutine, not the resumer), making per-Thread storage
    /// unsafe for continuation access.
    ///
    /// ## Ownership model
    ///
    /// Each `CallFrame.pending_call_index` (u32) is the handle to a slot in
    /// this array. Ownership is per-frame, not per-Thread:
    /// - `setPendingCall(frame, ...)` allocates/reuses a slot and stores the
    ///   index in `frame.pending_call_index`.
    /// - `clearPendingCall(frame)` returns the slot to the free list and
    ///   resets `frame.pending_call_index = INVALID_PENDING`.
    /// - `freeThreadBytecodeFrames(th)` iterates all of `th.call_frames` and
    ///   clears each frame's pending call, ensuring no slots leak when a
    ///   Thread is GC'd.
    ///
    /// ## Invariants
    ///
    /// 1. A slot is only accessed via the owning frame's `pending_call_index`.
    /// 2. Interleaved coroutines have distinct `call_frames`, so their
    ///    `pending_call_index` values point to distinct slots.
    /// 3. Thread destruction (`freeThreadBytecodeFrames`) clears all slots
    ///    owned by that thread's frames before the Thread is freed.
    /// 4. Reused free-list slots have no stale state: `setPendingCall` writes
    ///    the entire `payload` via a struct literal at every call site.
    /// 5. `pending_calls.deinit()` is called AFTER `drainGcRegistries()` in
    ///    `Vm.deinit`, because `drainGcRegistries` → `gcFreeObject(.thread)`
    ///    → `freeThreadBytecodeFrames` → `getPendingCallPtr` accesses this
    ///    array.
    ///
    /// Uses a free list: entries[free_head] is next free, linked by
    /// payload.free_next. `active` flag distinguishes live slots from
    /// free-list entries.
    pending_calls: std.ArrayListUnmanaged(PendingCallSlot) = .empty,
    pending_free_head: u32 = INVALID_PENDING,
    debug_namewhat_override: ?[]const u8 = null,
    debug_name_override: ?[]const u8 = null,
    last_builtin_out_count: usize = 0,
    active_builtin: ?BuiltinId = null,
    active_builtin_args: ?[]const Value = null,
    gmatch_state: ?GmatchState = null,
    wrap_thread: ?*Thread = null,
    main_thread: ?*Thread = null,
    forced_close_thread: ?*Thread = null,
    forced_close_had_error: bool = false,
    bytecode_coroutine_trampoline_active: bool = false,
    bytecode_coroutine_switch_request: ?BytecodeCoroutineSwitchRequest = null,
    pattern_match_budget: usize = 0,
    pattern_budget_active: bool = false,
    current_locale: []const u8 = "C",
    next_file_id: i64 = 1,
    file_metatable: ?*Table = null,
    open_files: std.AutoHashMapUnmanaged(i64, std.Io.File) = .{},
    file_buffers: std.AutoHashMapUnmanaged(i64, FileBuffer) = .{},
    /// Child processes backing FILE* values returned by io.popen. The process
    /// is reaped when the corresponding file is closed, matching pclose.
    open_processes: std.AutoHashMapUnmanaged(i64, std.process.Child) = .{},

    /// Errors visible to embedders and the public Zig API. Internal dispatch
    /// control flow is deliberately excluded from this set.
    pub const Error = std.mem.Allocator.Error || error{ RuntimeError, Yield };

    /// Private execution-layer signal set. `ThreadSwitch` is raised only while
    /// the bytecode coroutine trampoline is active and must be consumed by
    /// `driveBytecodeCoroutineTrampoline`; it must never cross a public Vm API.
    const DispatchError = Error || error{ThreadSwitch};

    /// P15.33: Recompute hooks_active_cached from the active thread's hook
    /// state. Called after every debug.sethook / hook clear.
    /// P15.35: Now includes call/return hooks — the OP_RETURN fast path relies
    /// on this flag to decide whether to skip the return hook dispatch.
    pub const DISPATCH_GATE_HOOKS: u8 = 1;
    pub const DISPATCH_GATE_STATS: u8 = 2;

    /// P16.21 T4.3: sanitize hook-replay state for every live Lua frame of
    /// `th` when hooks transition to active. Frames created while hooks were
    /// off carry semantically-dead (possibly stale/garbage) replay fields;
    /// activation makes them LIVE, so they must become valid sentinels
    /// before any hook-side read. last_line_pc is SEEDED to each frame's
    /// current pc (the existing sethook invariant — no spurious line hook
    /// on the install line); the skip fields become INVALID (no replay
    /// pending). Called by BOTH installation paths: debug.sethook and
    /// lua_sethook.
    pub fn sanitizeHookReplayState(self: *Vm, th: *Thread) void {
        _ = self;
        var i: usize = 0;
        const n = th.call_frames.len();
        while (i < n) : (i += 1) {
            const fr = th.call_frames.getPtr(i);
            if (fr.isC()) continue;
            fr.u.lua.last_line_pc = @intCast(fr.u.lua.pc);
            fr.u.lua.skip_line_hook_pc = INVALID_PC;
            fr.u.lua.skip_call_hook_pc = INVALID_PC;
            fr.u.lua.resume_skip_count_pc = INVALID_PC;
        }
    }

    pub fn refreshHooksCached(self: *Vm) void {
        const hs = self.activeHookState();
        // P15.83h: C hook state is now per-thread in DebugHookState.c_hook.
        // The mask/count are mirrored into has_call/has_return/has_line/count
        // by lua_sethook, so the existing check covers C hooks too.
        self.hooks_active_cached =
            hs.has_line or hs.count > 0 or hs.has_call or hs.has_return;
        if (self.hooks_active_cached) {
            self.dispatch_gate |= DISPATCH_GATE_HOOKS;
        } else {
            self.dispatch_gate &= ~DISPATCH_GATE_HOOKS;
        }
    }

    /// P15.35: Returns true if `ret` points into the VM's `bc_return_scratch`
    /// slot. Such slices are statically owned by the VM and must not be freed
    /// by `completeBytecodeExecFrame` or the `applyBytecodePending*` family.
    /// Detection is by pointer identity — cheap and exact for the 1-element
    /// scratch slot. Both OP_RETURN0 (empty slice `scratch[0..0]`) and
    /// OP_RETURN1 (`scratch[0..1]`) fast paths use this slot.
    fn returnSliceIsOwned(self: *Vm, ret: []const Value) bool {
        return ret.ptr == self.bc_return_scratch[0..].ptr;
    }

    /// Narrow a private execution result at a public Vm boundary. A switch can
    /// only be produced while an existing trampoline owns the call chain, so a
    /// top-level API entry observing it would violate the dispatch invariant.
    fn exposeDispatchResult(comptime T: type, result: DispatchError!T) Error!T {
        return result catch |err| switch (err) {
            error.ThreadSwitch => unreachable,
            error.OutOfMemory => return error.OutOfMemory,
            error.RuntimeError => return error.RuntimeError,
            error.Yield => return error.Yield,
        };
    }
    /// Create a new VM with entropy-derived hash seed. `noenv` mirrors PUC's
    /// `LUA_NOENV` registry flag (lua.c:720-723): when true, `resolveEnvPath`
    /// skips all env var reads and uses compiled-in defaults for
    /// `package.path`/`package.cpath`. Must be known at `init` time because
    /// `bootstrapGlobals` (the equivalent of `luai_openlibs`) runs inside
    /// `init` and reads env vars to set up the initial `package` table.
    ///
    /// The hash seed is derived from real entropy via `makeRandomSeed`
    /// (time + address mixing, mirroring PUC's `luai_makeseed`), matching
    /// PUC `luaL_newstate` → `lua_newstate(luaL_alloc, NULL, luaL_makeseed())`.
    /// For test reproducibility or C API `lua_newstate` (which receives an
    /// explicit seed), use `initWithSeed`.
    pub fn init(alloc: std.mem.Allocator, noenv: bool) Vm {
        return initWithSeed(alloc, noenv, makeRandomSeed());
    }

    /// Create a new VM with an explicit hash seed (PUC `g->seed`).
    /// Used by `lua_newstate` (which receives the seed parameter) and by
    /// tests that require deterministic hashing. The seed is set ONCE here
    /// and never mutated (PUC: `g->seed` is stable for the state's lifetime,
    /// independent of `math.random` which uses a separate `rng_state`).
    pub fn initWithSeed(alloc: std.mem.Allocator, noenv: bool, hash_seed: u64) Vm {
        const env = alloc.create(Table) catch @panic("oom");
        env.* = .{};
        const str_mt = alloc.create(Table) catch @panic("oom");
        str_mt.* = .{};
        var vm: Vm = .{
            .alloc = alloc,
            .dynamic_ast_arena = lua_ast.AstArena.init(alloc),
            .global_env = env,
            .string_metatable = str_mt,
            .noenv = noenv,
        };
        vm.gcRegisterTable(env) catch @panic("oom");
        vm.gcRegisterTable(str_mt) catch @panic("oom");
        const main_th = alloc.create(Thread) catch @panic("oom");
        main_th.* = .{
            .callee = .Nil,
            .status = .running,
        };
        vm.main_thread = main_th;
        vm.active_runtime_thread = main_th;
        // P15.40a: Pre-allocate frame capacity for the main thread (same as
        // activateRuntime does for coroutines). The main thread is activated
        // directly here, not via activateRuntime, so we pre-allocate inline.
        main_th.call_frames.ensureTotalCapacity(alloc, 64) catch @panic("oom");
        vm.gcRegisterThread(main_th) catch @panic("oom");
        vm.gcNoteAlloc(@sizeOf(Thread));
        // Allocate shared bytecode stack.
        vm.bc_stack = alloc.alloc(Value, vm.bc_stack_initial) catch @panic("oom");
        @memset(vm.bc_stack, .Nil);
        vm.bc_boxed = alloc.alloc(?*Cell, vm.bc_stack_initial) catch @panic("oom");
        @memset(vm.bc_boxed, null);
        // PUC lstate.c:354: g->seed = seed. The hash seed is initialized ONCE
        // from the caller-provided value (entropy via makeRandomSeed for
        // Vm.init, explicit seed for lua_newstate/tests). It is never mutated
        // again — math.random/randomseed operate on the separate rng_state.
        vm.hash_seed = hash_seed;
        // Pre-intern all metamethod name strings ("__index", "__newindex",
        // "__gc", "__mode", "__len", "__eq", "__add", ...). These are short
        // strings so they go through `string_intern` and deduplicate to a
        // single canonical *LuaString pointer. `fastTm`/`getTm` uses pointer
        // identity for key comparison, avoiding `internStrAssume` on every
        // lookup. Mirrors PUC's `luaT_init` (ltm.c:38-53), which pre-interns
        // `tmname[]` during state creation so metamethod lookups never
        // allocate. (PUC f_luaopen order is luaS_init -> luaT_init ->
        // luaX_init — the string table exists FIRST; luazig populates
        // tm_names at the equivalent bootstrap point in ITS initialization
        // sequence, which is luazig architecture, not literal PUC order.)
        //
        // MUST be populated BEFORE bootstrapGlobals() — bootstrapGlobals sets
        // up the string metatable and other global tables whose operations
        // may trigger metamethod lookups (getTmByObj → getTm → tm_names).
        // With non-optional *LuaString (no null check), accessing tm_names
        // before this point would read undefined memory.
        {
            const names = [_]struct { ev: TmsEvent, s: []const u8 }{
                .{ .ev = .index, .s = "__index" },
                .{ .ev = .newindex, .s = "__newindex" },
                .{ .ev = .gc, .s = "__gc" },
                .{ .ev = .mode, .s = "__mode" },
                .{ .ev = .len, .s = "__len" },
                .{ .ev = .eq, .s = "__eq" },
                .{ .ev = .add, .s = "__add" },
                .{ .ev = .sub, .s = "__sub" },
                .{ .ev = .mul, .s = "__mul" },
                .{ .ev = .mod, .s = "__mod" },
                .{ .ev = .pow, .s = "__pow" },
                .{ .ev = .div, .s = "__div" },
                .{ .ev = .idiv, .s = "__idiv" },
                .{ .ev = .band, .s = "__band" },
                .{ .ev = .bor, .s = "__bor" },
                .{ .ev = .bxor, .s = "__bxor" },
                .{ .ev = .shl, .s = "__shl" },
                .{ .ev = .shr, .s = "__shr" },
                .{ .ev = .unm, .s = "__unm" },
                .{ .ev = .bnot, .s = "__bnot" },
                .{ .ev = .lt, .s = "__lt" },
                .{ .ev = .le, .s = "__le" },
                .{ .ev = .concat, .s = "__concat" },
                .{ .ev = .call, .s = "__call" },
                .{ .ev = .close, .s = "__close" },
            };
            inline for (names) |entry| {
                vm.tm_names[@intFromEnum(entry.ev)] =
                    vm.internStr(entry.s) catch @panic("oom");
            }
        }
        // Pre-intern non-TMS metafield names ("__pairs", "__tostring",
        // "__name", "__metatable"). PUC does NOT include these in `tmname[]`
        // — it interns them on demand via `luaS_new`. We pre-intern them for
        // the same pointer-identity fast path as `tm_names`.
        {
            const mf_names = [_]struct { mf: MetaField, s: []const u8 }{
                .{ .mf = .pairs, .s = "__pairs" },
                .{ .mf = .tostring, .s = "__tostring" },
                .{ .mf = .name, .s = "__name" },
                .{ .mf = .metatable, .s = "__metatable" },
            };
            inline for (mf_names) |entry| {
                vm.metafield_names[@intFromEnum(entry.mf)] =
                    vm.internStr(entry.s) catch @panic("oom");
            }
        }
        vm.bootstrapGlobals() catch @panic("oom");
        // PUC lstate.c:375-380: setgcparam for all 6 GC params with PUC
        // defaults. Each param is coded via gcCodeParam (floating-point byte).
        //   [0]=MINORMUL(20), [1]=MAJORMINOR(50), [2]=MINORMAJOR(70),
        //   [3]=PAUSE(250), [4]=STEPMUL(200), [5]=STEPSIZE(9600).
        vm.gcparams = .{
            Vm.gcCodeParam(20), // LUA_GCPMINORMUL
            Vm.gcCodeParam(50), // LUA_GCPMAJORMINOR
            Vm.gcCodeParam(70), // LUA_GCPMINORMAJOR (decodes to 68)
            Vm.gcCodeParam(250), // LUA_GCPPAUSE
            Vm.gcCodeParam(200), // LUA_GCPSTEPMUL
            Vm.gcCodeParam(9600), // LUA_GCPSTEPSIZE (200 * sizeof(Table))
        };
        return vm;
    }

    /// Create the main `lua_State` handle for this VM and wire it as
    /// `cur_handle` / `main_handle`. Must be called AFTER `Vm.init` returns
    /// and the `*Vm` pointer is stable (the handle stores `self` as `vm`).
    ///
    /// `luaL_newstate` / `lua_newstate` / `api.State.init` / tests all call
    /// this after constructing the Vm. The handle is freed by `lua_close`
    /// (C API) or `api.State.deinit` (Zig API) alongside the Vm.
    pub fn setupMainHandle(self: *Vm) !*lua_State {
        const h = try self.alloc.create(lua_State);
        // P15.83k: the main handle references the main Thread (PUC: the main
        // lua_State IS the main thread). This makes every lua_State map to a
        // Lua thread Value: lua_pushthread pushes a real thread value for the
        // main state too, and lua_tothread reverse-maps main_thread.api_handle
        // back to the main handle. `is_main` distinguishes behavior where the
        // main state differs (pushthread return value, status, lifetime).
        h.* = .{ .vm = self, .thread = self.main_thread, .is_main = true };
        self.main_thread.?.api_handle = h;
        self.main_handle = h;
        self.cur_handle = h;
        self.cur_c_stack = &h.c_stack;
        return h;
    }

    pub fn setDynamicBytecodeCompiler(self: *Vm, compiler: ?DynamicBytecodeCompiler) void {
        self.dynamic_bytecode_compiler = compiler;
    }

    /// Park the currently active runtime buffers into their owning Lua thread.
    /// This is a move-only operation: register/TBC/frame storage is never
    /// duplicated during a coroutine switch.
    fn parkActiveRuntime(self: *Vm) void {
        const owner = self.active_runtime_thread orelse return;
        std.debug.assert(owner.bytecode_stack.len == 0);
        std.debug.assert(owner.bytecode_boxed.len == 0);
        std.debug.assert(owner.bytecode_tbc_regs.items.len == 0);

        // fr.u.lua.pc is already current — the dispatch loop writes ctx.pc
        // directly (fr.u.lua.pc IS the sole program counter). No sync needed
        // on park.

        owner.bytecode_stack = self.bc_stack;
        owner.bytecode_boxed = self.bc_boxed;
        owner.bytecode_stack_top = self.bc_stack_top;
        owner.bytecode_tbc_regs = self.bc_tbc_regs;

        self.bc_stack = &.{};
        self.bc_boxed = &.{};
        self.bc_stack_top = 0;
        self.bc_tbc_regs = .empty;
        self.active_runtime_thread = null;
    }

    /// Activate a parked Lua thread's runtime buffers in the VM hot path.
    fn activateRuntime(self: *Vm, owner: *Thread) void {
        std.debug.assert(self.active_runtime_thread == null);
        std.debug.assert(self.bc_stack.len == 0);
        std.debug.assert(self.bc_boxed.len == 0);
        std.debug.assert(self.bc_tbc_regs.items.len == 0);

        self.bc_stack = owner.bytecode_stack;
        self.bc_boxed = owner.bytecode_boxed;
        self.bc_stack_top = owner.bytecode_stack_top;
        self.bc_tbc_regs = owner.bytecode_tbc_regs;

        owner.bytecode_stack = &.{};
        owner.bytecode_boxed = &.{};
        owner.bytecode_stack_top = 0;
        owner.bytecode_tbc_regs = .empty;
        self.active_runtime_thread = owner;

        // P15.40a: Pre-allocate frame capacity to avoid capacity-check branch
        // on the hot path. 64 frames covers typical Lua call depth; deeper
        // chains fall back to geometric growth (rare). PUC has no limit
        // (linked list) but amortizes via never freeing on return.
        // Memory cost: 64 * (BytecodeExecFrame + RuntimeFrame) = ~30KB per
        // active thread (acceptable; threads are not lightweight).
        //
        // `ensureTotalCapacity` is infallible in practice (only fails on OOM).
        // We use `catch {}` because `activateRuntime` is invoked from
        // `switchRuntime` in the coroutine hot path and cannot return an error.
        // If pre-allocation fails, `addOne` retries on the next push — correct
        // behavior, just slower.
        owner.call_frames.ensureTotalCapacity(self.alloc, 64) catch {};

        // fr.u.lua.pc is already current in the activated thread's frames.
        // No bc_dispatch_pc sync needed — the field no longer exists.
    }

    fn switchRuntime(self: *Vm, next: *Thread) void {
        if (self.active_runtime_thread == next) return;
        self.parkActiveRuntime();
        self.activateRuntime(next);
        // P15.33: Different threads may have different hook states. Refresh
        // the cached flag so the dispatch loop picks up the new thread's hooks.
        self.refreshHooksCached();
    }

    /// PUC luaE_freethread → luaF_closeupval: close all open upvalues of a
    /// thread before its stack is freed. Called from gcFreeObject(.thread).
    ///
    /// Open upvalue cells live in th.bytecode_boxed (for a parked/suspended
    /// coroutine) — each non-null entry is a *Cell with bc_stack_idx pointing
    /// into th.bytecode_stack. Closing copies the stack value into cell.value
    /// and clears bc_stack_idx/bc_stack_thread, so the cell becomes
    /// self-contained and survives the thread's stack deallocation.
    ///
    /// For the active_runtime_thread (main thread at Vm.deinit), th.bytecode_boxed
    /// is empty — its open upvalues (if any) live in vm.bc_boxed, which is freed
    /// separately in Vm.deinit before drainGcRegistries. The main thread should
    /// have no open upvalues at teardown (the main chunk returns and closes them).
    ///
    /// PUC uses luaF_closeupval (not luaF_close): no __close metamethods are
    /// invoked — the thread is being freed and cannot run Lua code. This mirrors
    /// closeBytecodeUpvaluesFrom but operates on the whole th.bytecode_boxed
    /// array rather than a single frame's slice.
    fn closeThreadOpenUpvalues(self: *Vm, th: *Thread) void {
        for (th.bytecode_boxed) |maybe_cell| {
            if (maybe_cell) |cell| {
                // PUC luaF_closeupval (lfunc.c:197-210): setobj(slot, uv->v.p);
                // uv->v.p = slot. cell.close copies the stack value into
                // cell.value and clears bc_stack_idx/bc_stack_thread.
                cell.close(self);
                // PUC luaF_closeupval (lfunc.c:205-208): if !iswhite(uv):
                //   nw2black(uv) + luaC_barrier(L, uv, slot).
                // Closed upvalues cannot be gray — fix color to black.
                // The forward barrier marks the copied value. Do NOT rely
                // on the child having been marked earlier (PUC barriers
                // explicitly, and this runs during gcFreeObject sweep where
                // the thread's stack is about to be freed).
                if (!gcIsWhite(cell.gc_marked)) {
                    gcSetBlack(&cell.gc_marked);
                    self.gcWriteBarrierCell(cell, cell.value) catch {};
                }
            }
        }
    }

    fn freeParkedThreadRuntime(self: *Vm, th: *Thread) void {
        std.debug.assert(self.active_runtime_thread != th);
        if (th.bytecode_stack.len != 0) self.alloc.free(th.bytecode_stack);
        if (th.bytecode_boxed.len != 0) self.alloc.free(th.bytecode_boxed);
        th.bytecode_tbc_regs.deinit(self.alloc);
        th.bytecode_stack = &.{};
        th.bytecode_boxed = &.{};
        th.bytecode_stack_top = 0;
    }

    fn activeBytecodeThread(self: *Vm) *Thread {
        return self.current_thread orelse self.main_thread.?;
    }

    /// P15.78: Set the error handler function (PUC `L->errfunc`).
    /// Pushes `v` onto bc_stack and stores its index as `th.errfunc`.
    /// Pass `null` to clear (restores bc_stack_top below the old handler).
    /// Used by the CLI to install `cli_msghandler` before runBytecode.
    pub fn setErrfuncValue(self: *Vm, v: ?Value) void {
        const th = self.activeBytecodeThread();
        if (v) |val| {
            const idx = self.bc_stack_top;
            if (idx >= self.bc_stack.len) {
                self.ensureBcStackCap(idx + 1) catch {
                    th.errfunc = ERRFUNC_NONE;
                    return;
                };
            }
            self.bc_stack[idx] = val;
            self.bc_stack_top = idx + 1;
            th.errfunc = idx;
        } else {
            if (th.errfunc != ERRFUNC_NONE) {
                self.bc_stack_top = th.errfunc;
                th.errfunc = ERRFUNC_NONE;
            }
        }
    }

    /// P15.78: Get the error handler function (PUC `L->errfunc`).
    /// Returns the Value at `th.errfunc` on bc_stack, or null if no handler.
    pub fn getErrfuncValue(self: *Vm) ?Value {
        const th = self.activeBytecodeThread();
        if (th.errfunc != ERRFUNC_NONE) {
            return self.bc_stack[th.errfunc];
        }
        return null;
    }

    /// PUC-faithful overlapping model: derive the varargs slice for a CallFrame.
    /// Bytecode frames (proto != null): hidden varargs on bc_stack at
    /// [func_slot - nextraargs .. func_slot] (PUC buildhiddenargs layout).
    /// IR/C frames (proto == null): no varargs (return empty slice).
    /// P15.51g: Accept optional thread to resolve correct stack for parked coroutines.
    fn frameVarargs(self: *Vm, frame: *const CallFrame, th: ?*Thread) []Value {
        const proto = frame.proto() orelse return &.{};
        const nextra: usize = frame.u.lua.nextraargs;
        if (nextra == 0) return &.{};
        const stack = stackForThread(self, th);
        // P16.10b fix: the two vararg storage modes keep the extra args in
        // DIFFERENT places, and this accessor must respect the mode:
        //  - vahid (vararg_table_reg == null): buildhiddenargs shifted func
        //    past the extras — hidden args at [func_slot-nextra, func_slot).
        //  - table mode (named `...` table): extras stay INSIDE the frame at
        //    [base+numparams, base+numparams+nextra) (read once by OP_VARARGPREP,
        //    VATAB layout). The old func_slot-nextra computation was WRONG for
        //    this mode — it marked the PARENT's registers below the frame and
        //    underflowed whenever func_slot < nextraargs (first frames; latent
        //    since the vararg-table feature landed, exposed by P16.10b GC
        //    timing shifts in locals.lua to-be-closed coroutine sections).
        if (proto.vararg_table_reg != bc.Proto.no_vararg_reg) {
            const start = frame.frameBase() + proto.numparams;
            if (start + nextra > stack.len) return &.{}; // frame being torn down
            return stack[start .. start + nextra];
        }
        // PUC model: hidden varargs below ci->func.
        return stack[frame.func_slot - nextra .. frame.func_slot];
    }

    /// P15.51n: Derive current line from proto.lineinfo[pc].
    /// Returns -1 for C frames or protos without lineinfo.
    pub fn frameCurrentLine(self: *Vm, frame: *const CallFrame) i64 {
        _ = self;
        if (frame.proto()) |p| {
            if (frame.u.lua.pc < p.lineinfo.len) return @intCast(p.lineinfo[frame.u.lua.pc]);
        }
        return -1;
    }

    /// P15.51n: Set debug name override on a parent frame's continuation.
    /// The debug name describes WHY the child frame was created (e.g.
    /// "metamethod" / "__add"). It is stored in the parent's pending call
    /// continuation, not in the child frame itself, to avoid per-frame
    /// overhead for ordinary frames.
    fn setDebugName(self: *Vm, parent_frame: *CallFrame, namewhat: ?[]const u8, name: ?[]const u8) void {
        if (self.getPendingCallPtr(parent_frame.pending_call_index)) |pending| {
            pending.debug_namewhat = namewhat orelse &.{};
            pending.debug_name = name orelse &.{};
        }
    }

    /// P15.51n: Get debug name override from a parent frame's continuation.
    /// Returns the debug name that was set when the child frame was created.
    /// `parent_frame` is the frame BELOW the current frame (the caller).
    pub fn getDebugName(self: *Vm, parent_frame: ?*const CallFrame) ?struct { namewhat: ?[]const u8, name: ?[]const u8 } {
        const parent = parent_frame orelse return null;
        // P16.8 Task 1: Check inline simple-result completion first.
        // The debug name is derived from simple_result_event — no pending_calls
        // slot is involved.
        if (parent.isLua() and parent.u.lua.hasSimpleResult()) {
            const event: TmsEvent = parent.u.lua.simpleResultEvent();
            return .{
                .namewhat = "metamethod",
                .name = tag_method.opname(event),
            };
        }
        const pending = self.getPendingCallConst(parent.pending_call_index) orelse return null;
        if (pending.debug_namewhat.len == 0 and pending.debug_name.len == 0) return null;
        return .{
            .namewhat = if (pending.debug_namewhat.len > 0) pending.debug_namewhat else null,
            .name = if (pending.debug_name.len > 0) pending.debug_name else null,
        };
    }

    /// PUC `getfuncname` (ldebug.c:323) — how was the function running in
    /// `call_frames[frame_idx]` called? The name comes from the CALLER's
    /// bytecode at its current instruction (funcnamefromcall →
    /// funcnamefromcode, ldebug.c:615/659):
    ///   - OP_CALL/OP_TAILCALL: getobjname on the callee's register —
    ///     "local"/"upvalue"/"global"/"field"/"method" (luazig:
    ///     debugBytecodeOperandName, the same backward trace used for
    ///     "attempt to call a nil value" messages).
    ///   - OP_TFORCALL: "for iterator".
    ///   - other call-capable instructions: the metamethod name recorded on
    ///     the caller's pending call (setDebugName), matching PUC's
    ///     tmname[tm]+2 with namewhat "metamethod".
    ///   - caller is the hook frame: "?" / "hook" (PUC CIST_HOOKED).
    ///   - tail-called frames have no name (PUC: CIST_TAIL → NULL).
    ///   - C callers (no proto) and frames without a caller: no name.
    /// Returns null when PUC's getfuncname returns NULL (auxgetinfo then
    /// sets namewhat="" and name=NULL).
    pub fn getFuncNameForFrame(self: *Vm, th: *Thread, frame_idx: usize) ?struct { namewhat: []const u8, name: ?[]const u8 } {
        if (frame_idx >= th.call_frames.len()) return null;
        const frame = th.call_frames.getConstPtr(frame_idx);
        // PUC getfuncname: no way to find a name for a tail-called frame.
        if (frame.isTailCall()) return null;
        if (frame_idx == 0) return null;
        const parent = th.call_frames.getConstPtr(frame_idx - 1);
        // Caller executing inside a hook (PUC CIST_HOOKED): "?" / "hook".
        if (parent.isDebugHook()) return .{ .namewhat = "hook", .name = "?" };
        const proto = parent.proto() orelse return null; // C caller: no name
        const pc = parent.u.lua.pc;
        if (pc >= proto.code.len) return null;
        const inst = proto.code[pc];
        const op: bc.Op = @enumFromInt(inst.op);
        switch (op) {
            .call, .tailcall => {
                // The callee's register: the caller-relative position the
                // callee frame was pushed at. Frames NOT pushed from this
                // caller's registers (entry chunks, pcall bodies pushed at
                // bc_stack_top) carry an out-of-range offset — PUC's
                // equivalent (a C-function caller) yields no name.
                //
                // P15.83r: C frames (builtin/C-closure callees) are pushed at
                // bc_stack_top, so `u.lua.func_slot_base` is NOT valid (union
                // member mismatch — the frame is `.c`). PUC instead places
                // ci->func at the caller's stack slot holding the callee and
                // funcnamefromcode reads the call instruction's A operand
                // directly (ldebug.c:615 funcnamefromcode OP_CALL branch).
                // Mirror that: for C frames take the operand register from
                // the instruction itself.
                const off: usize = if (frame.isC())
                    inst.a
                else
                    frame.originalFuncSlot() - parent.frameBase();
                if (off >= proto.maxstacksize) return null;
                const dn = debugBytecodeOperandName(proto, pc, @intCast(off));
                if (dn.name) |nm| return .{ .namewhat = dn.namewhat, .name = nm };
                return .{ .namewhat = "", .name = null };
            },
            .tforcall => return .{ .namewhat = "for iterator", .name = "for iterator" },
            else => {
                // Metamethod-calling instruction: the pending-call debug
                // name carries the metamethod identity (PUC
                // funcnamefromcode's tmname[tm]+2, namewhat "metamethod").
                if (self.getDebugName(parent)) |dn| {
                    return .{
                        .namewhat = dn.namewhat orelse "",
                        .name = dn.name,
                    };
                }
                return null;
            },
        }
    }

    /// P15.51n: Allocate a pending call slot on the Vm.
    /// Returns the slot index, or error.OutOfMemory if allocation fails.
    fn allocPendingCall(self: *Vm) error{OutOfMemory}!u32 {
        if (self.pending_free_head != INVALID_PENDING) {
            const idx = self.pending_free_head;
            self.pending_free_head = self.pending_calls.items[idx].payload.free_next;
            self.pending_calls.items[idx].active = true;
            return idx;
        }
        const idx: u32 = @intCast(self.pending_calls.items.len);
        try self.pending_calls.append(self.alloc, .{});
        self.pending_calls.items[idx].active = true;
        return idx;
    }

    fn getPendingCallPtr(self: *Vm, index: u32) ?*BytecodePendingCall {
        if (index == INVALID_PENDING) return null;
        if (self.pending_calls.items.len == 0) return null;
        if (@as(usize, index) >= self.pending_calls.items.len) return null;
        if (!self.pending_calls.items[index].active) return null;
        return &self.pending_calls.items[index].payload;
    }

    fn getPendingCallConst(self: *Vm, index: u32) ?*const BytecodePendingCall {
        if (index == INVALID_PENDING) return null;
        if (self.pending_calls.items.len == 0) return null;
        if (@as(usize, index) >= self.pending_calls.items.len) return null;
        if (!self.pending_calls.items[index].active) return null;
        return &self.pending_calls.items[index].payload;
    }

    fn freePendingCall(self: *Vm, index: u32) void {
        if (index == INVALID_PENDING or index >= self.pending_calls.items.len) return;
        if (!self.pending_calls.items[index].active) return;
        self.pending_calls.items[index].active = false;
        self.pending_calls.items[index].payload.free_next = self.pending_free_head;
        self.pending_free_head = index;
    }

    fn setPendingCall(self: *Vm, frame: *CallFrame, value: BytecodePendingCall) error{OutOfMemory}!void {
        if (frame.pending_call_index == INVALID_PENDING) {
            frame.pending_call_index = try self.allocPendingCall();
        }
        self.pending_calls.items[frame.pending_call_index].payload = value;
        self.pending_calls.items[frame.pending_call_index].active = true;
    }

    fn clearPendingCall(self: *Vm, frame: *CallFrame) void {
        self.freePendingCall(frame.pending_call_index);
        frame.pending_call_index = INVALID_PENDING;
    }

    /// P15.51n: Derive upvalues from bc_stack[func_slot].Closure.upvalues.
    /// Not stored in CallFrame — eliminates duplicated slice.
    pub fn frameUpvalues(self: *Vm, frame: *const CallFrame, th: ?*Thread) []const *Cell {
        if (frame.proto()) |_| {
            const stack = stackForThread(self, th);
            if (stack[frame.func_slot] == .Closure) {
                return stack[frame.func_slot].Closure.upvalues;
            }
        }
        return &.{};
    }

    fn activeProtectedCallDepth(self: *Vm) usize {
        return self.protected_call_depth + self.activeBytecodeThread().bytecode_protected_depth;
    }

    fn activeErrorHandlerDepth(self: *Vm) usize {
        return self.in_error_handler + self.activeBytecodeThread().bytecode_error_handler_depth;
    }

    fn hasActiveBytecodeNonYieldableBoundary(self: *Vm) bool {
        const thread = self.activeBytecodeThread();
        var i = thread.call_frames.len();
        while (i != 0) {
            i -= 1;
            const pending = self.getPendingCallConst(thread.call_frames.getConstPtr(i).pending_call_index) orelse continue;
            if (pending.completion == .gsub) return true;
        }
        return false;
    }

    fn activeCloseMetamethodDepth(self: *Vm) usize {
        return self.close_metamethod_depth + self.activeBytecodeThread().bytecode_close_metamethod_depth;
    }

    fn activeAsyncDebugHookFrame(self: *Vm) ?*CallFrame {
        // P15.51n: O(1) lookup via Thread.hook_frame_index (replaces scan).
        const th = self.activeBytecodeThread();
        if (th.hook_frame_index != INVALID_HOOK_FRAME and th.hook_frame_index < th.call_frames.len()) {
            return th.call_frames.getPtr(th.hook_frame_index);
        }
        return null;
    }

    fn isInDebugHook(self: *Vm) bool {
        // P15.38f: O(1) check via per-thread flag (PUC Lua's `allowhook` model).
        // Both sync (debugDispatchHookTransfer) and async (bytecode hook frame
        // push/pop) paths maintain this flag on the active thread's DebugHookState.
        return self.activeHookState().in_debug_hook;
    }

    /// PUC distinguishes Lua hook functions from native C hooks: the former
    /// cannot yield, while a C line/count hook may suspend the running thread.
    /// Bytecode hooks capture that capability on their activation frame so a
    /// hook replacing itself cannot retroactively change the active call.
    fn activeDebugHookAllowsYield(self: *Vm) bool {
        if (self.activeAsyncDebugHookFrame()) |_| {
            return self.activeBytecodeThread().debug_hook_allow_yield;
        }
        return self.activeHookState().in_debug_hook and self.debug_hook_allow_yield;
    }

    fn activeDebugTransferValues(self: *Vm) ?[]const Value {
        if (self.activeAsyncDebugHookFrame()) |_| {
            return self.activeBytecodeThread().debug_hook_transfer;
        }
        return self.debug_transfer_values;
    }

    fn activeDebugTransferStart(self: *Vm) i64 {
        if (self.activeAsyncDebugHookFrame()) |_| {
            return self.activeBytecodeThread().debug_hook_transfer_start;
        }
        return self.debug_transfer_start;
    }

    fn activeDebugHookEventCalllike(self: *Vm) bool {
        if (self.activeAsyncDebugHookFrame()) |_| {
            return self.activeBytecodeThread().debug_hook_event_calllike;
        }
        return self.debug_hook_event_calllike;
    }

    fn activeDebugHookEventTailcall(self: *Vm) bool {
        if (self.activeAsyncDebugHookFrame()) |_| {
            return self.activeBytecodeThread().debug_hook_event_tailcall;
        }
        return self.debug_hook_event_tailcall;
    }

    fn activeDebugHookEventIsCount(self: *Vm) bool {
        if (self.activeAsyncDebugHookFrame()) |_| {
            return self.activeBytecodeThread().debug_hook_event_is_count;
        }
        return self.debug_hook_event_is_count;
    }

    fn freeThreadBytecodeFrames(self: *Vm, th: *Thread) void {
        // P15.51n: Cancel all pending calls on this thread's frames.
        //
        // cancelBytecodePendingCall is cleanup-only: it frees continuation-
        // owned allocations (concat buffers, gsub state, close state, hook
        // transfer arrays) and restores saved callee/tailcall state. It does
        // NOT run Lua code or push new frames.
        //
        // We iterate call_frames from top to bottom. Each frame's pending
        // call (if any) is cancelled, then the slot is returned to the
        // Vm-level free list via clearPendingCall. The loop is a simple
        // reverse iteration — no reentrancy to guard against.
        var i: usize = th.call_frames.len();
        while (i > 0) {
            i -= 1;
            const frame = th.call_frames.getPtr(i);
            if (frame.pending_call_index == INVALID_PENDING) continue;
            if (self.getPendingCallPtr(frame.pending_call_index)) |pending| {
                self.cancelBytecodePendingCall(pending, frame);
                self.clearPendingCall(frame);
            }
        }
        th.call_frames.clearAndFree(self.alloc);
        th.bytecode_unwinds.clearAndFree(self.alloc);
        th.bytecode_inplace_suspended = false;
        th.bytecode_resume_boundary = 0;
    }

    /// Ensure the shared bytecode stack can hold at least `needed` slots.
    /// Grows by doubling + `needed`, reallocating both bc_stack and bc_boxed.
    /// After realloc, all frame `base` offsets remain valid (they're indices).
    // P16.2d: Fast path is a single comparison (needed <= bc_stack.len).
    // Inlining avoids call overhead (~40% of this symbol's 3.2% in perf
    // annotate). The rare growth path is outlined into growBcStackCapSlow
    // to keep the inlined fast path minimal and avoid code bloat at every
    // call site.
    inline fn ensureBcStackCap(self: *Vm, needed: usize) DispatchError!void {
        if (needed > self.bc_stack.len) {
            @branchHint(.cold);
            try self.growBcStackCapSlow(needed);
        }
    }

    fn growBcStackCapSlow(self: *Vm, needed: usize) DispatchError!void {
        const old_len = self.bc_stack.len;
        // PUC luaD_growstack: newsize = size + size/2 (1.5x growth),
        // capped at MAXSTACK. If needed > MAXSTACK, the overflow check
        // in pushBytecodeExecFrame catches it and grows to ERRORSTACKSIZE
        // (MAXSTACK + 200) directly. Normal growth MUST NOT exceed MAXSTACK,
        // otherwise T.stacklevel() reports ERRORSTACKSIZE before overflow,
        // breaking cstack.lua's assertion: stacknow == stack1 + 200.
        const MAXSTACK: usize = 1_000_000;
        var new_cap = if (old_len == 0) self.bc_stack_initial else old_len + (old_len >> 1);
        if (new_cap < needed) new_cap = needed;
        if (new_cap > MAXSTACK) new_cap = MAXSTACK;
        // If needed > MAXSTACK, don't grow — the caller (pushBytecodeExecFrame)
        // handles the overflow by growing to ERRORSTACKSIZE. Growing beyond
        // MAXSTACK here would break the stack-overflow detection invariant.
        if (new_cap <= old_len) return;
        self.bc_stack = try self.alloc.realloc(self.bc_stack, new_cap);
        self.bc_boxed = try self.alloc.realloc(self.bc_boxed, new_cap);
        // Initialize new slots.
        @memset(self.bc_stack[old_len..], .Nil);
        @memset(self.bc_boxed[old_len..], null);
        // After realloc, bytecode frames no longer cache slices — their
        // register windows are derived on demand from base + frame_cap.
        // Nothing to update here (PUC Lua's luaD_reallocstack also needs
        // no per-frame fixup because ci->func points into the stack).
    }

    /// PUC ldo.c `luaD_shrinkstack`: shrink bc_stack back to a reasonable
    /// size after a stack overflow has been handled.
    ///
    /// PUC algorithm:
    ///   inuse = stackinuse(L)   // max(L->top, all ci->top), min LUA_MINSTACK
    ///   max   = (inuse > MAXSTACK/3) ? MAXSTACK : inuse*3
    ///   if inuse <= MAXSTACK && stacksize > max:
    ///     nsize = (inuse > MAXSTACK/2) ? MAXSTACK : inuse*2
    ///     luaD_reallocstack(L, nsize)
    ///
    /// In our architecture, bc_stack_top is the equivalent of L->top.p.
    /// After an overflow, bc_stack was grown to lua_max_stack_slots (32K).
    /// Once the error handler returns and the protected frame unwinds,
    /// bc_stack_top drops back to normal, but bc_stack.len stays at 32K.
    /// This function shrinks it back to ~2x current usage.
    ///
    /// Called after pcall/xpcall completes (success or error), matching
    /// PUC's luaD_pcall which calls luaD_shrinkstack on the error path.
    fn shrinkBcStack(self: *Vm) void {
        const MAXSTACK: usize = 1_000_000; // lua_max_stack_slots
        const LUA_MINSTACK: usize = 20;

        // PUC's `stackinuse` computes the max extent across all CallInfo
        // frames. In the overlapping model, bc_stack_top only reflects the
        // TOP frame's extent — a lower frame may extend further. Walk all
        // active bytecode frames to find the true high-water mark.
        var inuse = self.bc_stack_top;
        const th = self.activeBytecodeThread();
        for (0..th.call_frames.len()) |i| {
            const fr = th.call_frames.getConstPtr(i);
            if (fr.proto() != null) {
                const extent = fr.frameBase() + fr.u.lua.frame_cap;
                if (extent > inuse) inuse = extent;
            }
        }
        if (inuse < LUA_MINSTACK) inuse = LUA_MINSTACK;

        // Don't shrink if we're still in an error handler.
        if (inuse > MAXSTACK) return; // still handling overflow

        // PUC: max = (inuse > MAXSTACK/3) ? MAXSTACK : inuse*3
        const max = if (inuse > MAXSTACK / 3) MAXSTACK else inuse * 3;
        if (self.bc_stack.len <= max) return;

        // PUC: nsize = (inuse > MAXSTACK/2) ? MAXSTACK : inuse*2
        const nsize = if (inuse > MAXSTACK / 2) MAXSTACK else inuse * 2;
        // Shrink both bc_stack and bc_boxed. realloc with smaller size
        // is valid and will shrink the allocation.
        self.bc_stack = self.alloc.realloc(self.bc_stack, nsize) catch return;
        self.bc_boxed = self.alloc.realloc(self.bc_boxed, nsize) catch return;

        // After realloc, bytecode frame slices are derived on demand
        // from base + frame_cap — no per-frame slice update needed.
    }

    /// Grow the current bytecode frame's capacity to hold at least
    /// `needed_local` registers (relative to base).  Grows the shared
    /// stack if necessary, refreshes regs/boxed slices, updates bc_stack_top,
    /// and patches the Frame struct for GC/debug visibility.
    ///
    /// Call this BEFORE writing variable-length results to regs (CALL multret,
    /// VARARG expansion, etc.).  Replaces the old fixed EXTRA_STACK margin.
    /// P16.21 T6: dispatch-path frame growth — bcGrowFrame + immediate
    /// publication of the new frame_cap to the CURRENT CallFrame. Parked
    /// frames' caps are read by GC register scans and debug walkers; with
    /// mutation-site publishing, the generic frame-exit syncFrame no longer
    /// needs to carry frame_cap (it becomes pc-only, like PUC's savedpc).
    /// Publication happens only after successful growth (error paths leave
    /// both the ctx cap and the frame copy unchanged — rollback consistency).
    fn growCtxFrame(
        self: *Vm,
        ctx: *BytecodeDispatchCtx,
        needed_local: usize,
    ) DispatchError!void {
        try self.bcGrowFrame(ctx.base, needed_local, &ctx.frame_cap, &ctx.regs);
        ctx.exec_frames.getPtr(ctx.frame_index).u.lua.frame_cap = ctx.frame_cap;
    }

    fn bcGrowFrame(
        self: *Vm,
        base: usize,
        needed_local: usize,
        frame_cap: *u32,
        regs: *[]Value,
    ) DispatchError!void {
        const old_cap = frame_cap.*;
        if (needed_local > frame_cap.*) {
            frame_cap.* = @intCast(needed_local);
            try self.ensureBcStackCap(base + frame_cap.*);
            self.bc_stack_top = @max(self.bc_stack_top, base + frame_cap.*);
        }

        // A nested call can grow and reallocate the shared bytecode stack even
        // when this frame itself does not need more registers.  Always derive
        // these slices again before the caller writes return values; otherwise
        // it can write through pointers into the old allocation and leave the
        // live registers unchanged.
        const cap: usize = frame_cap.*;
        regs.* = self.bc_stack[base .. base + cap];

        if (frame_cap.* > old_cap) {
            // Nil-fill new register slots and clear the corresponding boxed
            // slots. Both are critical: stale register values break GC
            // safety, and a stale boxed cell pointer would alias a captured
            // upvalue from a previous frame (captured-local coherence,
            // smoke 61/67). P16.19 T3: boxed slots are derived here, not
            // carried in the hot dispatch context.
            for (regs.*[old_cap..]) |*r| r.* = .Nil;
            for (self.bc_boxed[base + old_cap .. base + cap]) |*b| b.* = null;
        }

        // P15.51g: No frame slice update needed — regs/boxed are derived
        // on demand from base + frame_cap, not cached in the frame.
    }

    const BytecodeVarargTable = struct {
        table: *Table,
        len: usize,
    };

    fn getBytecodeVarargTable(self: *Vm, proto: *const bc.Proto, regs: []Value) DispatchError!?BytecodeVarargTable {
        const reg = proto.vararg_table_reg;
        if (reg == bc.Proto.no_vararg_reg) return null;
        const idx: usize = @intCast(reg);
        if (idx >= regs.len or regs[idx] != .Table) return null;
        const tbl = regs[idx].Table;
        var n: usize = tbl.asize;
        const nv = self.getField(tbl, "n");
        if (nv != .Nil) {
            switch (nv) {
                .Int => |iv| {
                    if (iv < 0 or iv > 100_000) return self.fail("no proper 'n'", .{});
                    n = @intCast(iv);
                },
                else => return self.fail("no proper 'n'", .{}),
            }
        }
        return .{ .table = tbl, .len = n };
    }

    pub fn deinit(self: *Vm) void {
        // Run closing finalizers first — they execute Lua __gc metamethods and
        // need most objects (global_env, frames, tables) still alive.
        self.gcFinalizeAtClose();
        // If a finalizer called `os.exit(code, true)` during close, PUC
        // calls `exit(code)` after `lua_close` returns. All finalizers have
        // run; terminate the process now before teardown frees structures
        // that the finalizer might still reference.
        if (self.pending_exit_code) |code| {
            std.process.exit(code);
        }
        // Cleanup non-GC-object resources and bookkeeping maps. These own their
        // own metadata but NOT the GC objects themselves — the registries below
        // are the single ownership point for object destruction.
        var bit = self.file_buffers.iterator();
        while (bit.next()) |entry| entry.value_ptr.pending.deinit(self.alloc);
        self.file_buffers.deinit(self.alloc);
        var fit = self.open_files.iterator();
        while (fit.next()) |entry| {
            // Never close stdin/stdout/stderr. Sub-VMs (e.g. checkpanic)
            // register the process's standard streams as managed files; closing
            // them here would break the parent VM's I/O. PUC Lua's std files
            // are likewise never closed by `lua_close` — they are marked
            // `isstd` in `liolib.c` and skipped by `closefunc`.
            const fd = entry.value_ptr.*.handle;
            if (fd == std.posix.STDIN_FILENO or
                fd == std.posix.STDOUT_FILENO or
                fd == std.posix.STDERR_FILENO) continue;
            entry.value_ptr.*.close(stdio.activeIo());
        }
        self.open_files.deinit(self.alloc);
        var pit = self.open_processes.iterator();
        while (pit.next()) |entry| {
            var child = entry.value_ptr.*;
            _ = child.wait(stdio.activeIo()) catch {
                child.kill(stdio.activeIo());
            };
        }
        self.open_processes.deinit(self.alloc);
        if (self.err_traceback) |tb| self.alloc.free(tb);
        // Note: string_intern.deinit is deferred to AFTER drainGcRegistries,
        // because gcFreeObject for short strings calls string_intern.table.remove.
        self.long_literals.deinit(self.alloc);
        self.finalizables.deinit(self.alloc);
        self.dynamic_ast_arena.deinit();
        self.alloc.free(self.bc_stack);
        self.alloc.free(self.bc_boxed);
        // PUC-faithful teardown: free non-GC managed buffers before destroying
        // GC objects. `long_string_cache` keys point into GC-owned LuaString
        // bytes, but deinit only frees the hashmap backing storage (never
        // touches keys/values), so ordering relative to drainGcRegistries is
        // safe. Without this, every sub-VM (checkpanic) leaks both buffers.
        self.long_string_cache.deinit(self.alloc);
        self.testc_warn_buff.deinit(self.alloc);
        // C API stack: no longer owned by Vm directly (Phase 2: per-handle
        // stacks). The main handle's c_stack is freed by lua_close /
        // api.State.deinit; coroutine handles' c_stacks are freed by
        // gcFreeObject(.thread). Nothing to deinit here.
        // C API to-close slots: owns only the index list, not the Values.
        self.c_toclose_slots.deinit(self.alloc);
        // C library cache (c_libs): free the dupe'd path keys and the HashMap
        // backing storage. The dlopen handles themselves are intentionally NOT
        // dlclose'd — see the comment on the `c_libs` field declaration.
        var clit = self.c_libs.keyIterator();
        while (clit.next()) |k| {
            self.alloc.free(k.*);
        }
        self.c_libs.deinit(self.alloc);
        // Drain GC registries — destroy every object allocated during the VM's
        // lifetime. Mid-run sweep (when implemented) frees unreachable objects
        // during execution; this catches the survivors at teardown.
        self.drainGcRegistries();
        // P15.51n: Free pending call storage AFTER drainGcRegistries, which
        // calls freeThreadBytecodeFrames → getPendingCallPtr on each thread.
        self.pending_calls.deinit(self.alloc);
    }

    /// Single ownership point for GC-able object destruction. Iterates the
    /// unified `gc_objects` list, freeing each object's type-specific memory.
    /// No need to call `gcUnregisterObject` — the list itself is being
    /// deinit'd. Order is irrelevant: each type's cleanup only touches its
    /// own memory, never dereferencing Values (which may be dangling by
    /// this point).
    fn drainGcRegistries(self: *Vm) void {
        // Unified destruction: free every GC object via the generic dispatcher.
        for (self.gc_objects.items) |obj| {
            self.gcFreeObject(obj);
        }
        self.gc_objects.deinit(self.alloc);
        self.gc_young_objects.deinit(self.alloc);
        self.gc_gray.deinit(self.alloc);
        self.gc_marked_tables.deinit(self.alloc);
        self.gc_marked_closures.deinit(self.alloc);
        self.gc_marked_threads.deinit(self.alloc);
        self.gc_weak_tables.deinit(self.alloc);
        self.gc_fin_tables.deinit(self.alloc);
        self.gc_fin_closures.deinit(self.alloc);
        self.gc_fin_threads.deinit(self.alloc);
        self.gc_to_finalize.deinit(self.alloc);
        self.gc_old1.deinit(self.alloc);
        self.gc_grayagain.deinit(self.alloc);
        self.gc_gen_threads.deinit(self.alloc);
        self.gc_temp_roots.deinit(self.alloc);
        // Now safe to deinit string_intern — all GC objects (including
        // short strings) have been freed by drainGcRegistries above.
        self.string_intern.deinit(self.alloc);
    }

    // Public API helpers for `src/lua/api.zig`.
    pub fn apiGetGlobal(self: *Vm, name: []const u8) Value {
        return self.getGlobal(name);
    }

    /// Lazily create and return the PUC registry table (the table accessible
    /// via the `LUA_REGISTRYINDEX` pseudo-index). Used by the C API shim
    /// (`luaL_ref(L, LUA_REGISTRYINDEX)`, etc.). Wraps `ensureDebugRegistry`
    /// to expose a clean `Error` result to `c_api.zig`.
    pub fn apiEnsureRegistry(self: *Vm) Error!*Table {
        return exposeDispatchResult(*Table, self.ensureDebugRegistry());
    }

    pub fn apiSetGlobal(self: *Vm, name: []const u8, v: Value) Error!void {
        return exposeDispatchResult(void, self.setGlobal(name, v));
    }

    pub fn apiNewTable(self: *Vm) Error!*Table {
        return exposeDispatchResult(*Table, self.allocTable());
    }

    pub fn apiNewThread(self: *Vm, callee: Value) Error!*Thread {
        try exposeDispatchResult(void, self.testcChargeMemory(@sizeOf(Thread) + 64));
        const th = try self.alloc.create(Thread);
        th.* = .{ .status = .suspended, .callee = callee };
        try self.gcRegisterThread(th);
        self.gcNoteAlloc(@sizeOf(Thread));
        self.testc_obj_threads += 1;
        // P15.40a: Pre-allocate frame capacity for the new coroutine. This
        // avoids the capacity-check branch on the first 64 bytecode calls.
        // activateRuntime also does this (for threads parked and re-activated),
        // but pre-allocating here means the first activation is already ready.
        th.call_frames.ensureTotalCapacity(self.alloc, 64) catch {};
        return th;
    }

    pub fn apiRawGet(self: *Vm, tbl: *Table, key: Value) Error!Value {
        return exposeDispatchResult(Value, self.tableGetRawValue(tbl, key));
    }

    pub fn apiRawSet(self: *Vm, tbl: *Table, key: Value, value: Value) Error!void {
        return exposeDispatchResult(void, self.tableSetValue(tbl, key, value));
    }

    pub fn apiGetTable(self: *Vm, object: Value, key: Value) Error!Value {
        return exposeDispatchResult(Value, self.indexValue(object, key));
    }

    pub fn apiSetTable(self: *Vm, object: Value, key: Value, value: Value) Error!void {
        return exposeDispatchResult(void, self.setIndexValue(object, key, value));
    }

    pub fn apiNext(self: *Vm, tbl: *Table, key: Value, outs: []Value) Error!usize {
        var tmp: [2]Value = .{ .Nil, .Nil };
        try exposeDispatchResult(void, self.builtinNext(&[_]Value{ .{ .Table = tbl }, key }, tmp[0..]));
        if (tmp[0] == .Nil) return 0;
        if (outs.len < 2) return error.RuntimeError;
        outs[0] = tmp[0];
        outs[1] = tmp[1];
        return 2;
    }

    pub fn apiConcat(self: *Vm, lhs: Value, rhs: Value) Error!Value {
        return exposeDispatchResult(Value, self.binConcat(lhs, rhs));
    }

    /// PUC `lua_arith` (lapi.c:lua_arith → luaO_arith): perform an arithmetic
    /// operation on two Values. `op` is a LUA_OP* constant (0–13). For unary
    /// ops (UNM=12, BNOT=13), `rhs` is ignored (PUC duplicates the operand,
    /// but the result is identical). Handles Int/Num directly and falls back
    /// to metamethods (__add, __sub, etc.) for tables/userdata.
    pub fn apiArith(self: *Vm, op: u8, lhs: Value, rhs: Value) Error!Value {
        const result: DispatchError!Value = switch (op) {
            0 => self.binAdd(lhs, rhs), // LUA_OPADD
            1 => self.binSub(lhs, rhs), // LUA_OPSUB
            2 => self.binMul(lhs, rhs), // LUA_OPMUL
            3 => self.binMod(lhs, rhs), // LUA_OPMOD
            4 => self.binPow(lhs, rhs), // LUA_OPPOW
            5 => self.binDiv(lhs, rhs), // LUA_OPDIV
            6 => self.binIdiv(lhs, rhs), // LUA_OPIDIV
            7 => self.binBand(lhs, rhs), // LUA_OPBAND
            8 => self.binBor(lhs, rhs), // LUA_OPBOR
            9 => self.binBxor(lhs, rhs), // LUA_OPBXOR
            10 => self.binShl(lhs, rhs), // LUA_OPSHL
            11 => self.binShr(lhs, rhs), // LUA_OPSHR
            12 => self.evalUnOp(.Minus, lhs), // LUA_OPUNM
            13 => self.evalUnOp(.Tilde, lhs), // LUA_OPBNOT
            else => return error.RuntimeError,
        };
        return exposeDispatchResult(Value, result);
    }

    /// PUC `lua_rawequal` (lapi.c:lua_rawequal): raw equality without
    /// metamethods. Delegates to the private `valuesEqual` which compares
    /// by type and value (pointer identity for tables/closures/threads,
    /// byte comparison for strings, numeric cross-comparison for Int/Num).
    pub fn apiRawEqual(lhs: Value, rhs: Value) bool {
        return valuesEqual(lhs, rhs);
    }

    /// PUC `lua_compare` (lapi.c:lua_compare): comparison with metamethods.
    /// `op` is LUA_OPEQ (0), LUA_OPLT (1), or LUA_OPLE (2). For numbers and
    /// strings, comparison is direct. For tables/userdata, __eq/__lt/__le
    /// metamethods are tried.
    pub fn apiCompare(self: *Vm, op: u8, lhs: Value, rhs: Value) Error!bool {
        const result: DispatchError!bool = switch (op) {
            0 => self.cmpEq(lhs, rhs), // LUA_OPEQ
            1 => self.cmpLt(lhs, rhs), // LUA_OPLT
            2 => self.cmpLte(lhs, rhs), // LUA_OPLE
            else => return error.RuntimeError,
        };
        return exposeDispatchResult(bool, result);
    }

    /// PUC `lua_len` (lapi.c:lua_len): length with metamethods. For strings:
    /// byte length. For tables: border length (or __len metamethod). For
    /// other types: tries __len metamethod, errors if none.
    pub fn apiLen(self: *Vm, v: Value) Error!Value {
        return exposeDispatchResult(Value, self.evalUnOp(.Hash, v));
    }

    /// PUC `lua_gc` (lapi.c:lua_gc): garbage collector control. This is the
    /// ONE unified implementation used by both the C API (`lua_gc` via
    /// `luazigGcFixed`/`luazigGcParam` in c_api.zig) and the Lua builtin
    /// (`collectgarbage` via `builtinCollectgarbage`). Maps LUA_GC* constants
    /// to VM GC operations following the PUC lapi.c switch table exactly.
    ///
    /// `what` is a LUA_GC* constant. `param` and `value` are used only for
    /// LUA_GCPARAM (param=LUA_GCP* index, value=new value or -1 for getter).
    /// Returns context-dependent values per PUC semantics.
    pub fn gcControl(self: *Vm, what: i32, param: i32, value: i32) i32 {
        // PUC lapi.c:1174: if gcstp & (GCSTPGC|GCSTPCLS) return -1.
        if (self.gc_stp & (GCSTPGC | GCSTPCLS) != 0) return -1;
        return switch (what) {
            0 => blk: { // LUA_GCSTOP: gcstp = GCSTPUSR
                self.gc_stp = GCSTPUSR;
                self.gc_running = false;
                break :blk 0;
            },
            1 => blk: { // LUA_GCRESTART: luaE_setdebt(g,0); gcstp = 0
                self.gc_step_debt_kb = 0;
                self.gc_auto_threshold_kb = self.gc_count_kb;
                self.gc_stp = 0;
                self.gc_running = true;
                break :blk 0;
            },
            2 => blk: { // LUA_GCCOLLECT: fullgc
                // PUC lua_gc(LUA_GCCOLLECT) → luaC_fullgc(L,0) → luaC_runtilstate
                // which can luaD_throw on OOM (longjmp). gcControl returns i32
                // (C ABI boundary), so we cannot propagate via longjmp. The
                // catch {} swallows OOM: the collection is incomplete (some
                // objects not collected), but GC invariants are not corrupted
                // — gcFullCollectionForUser uses try internally, so a failure
                // aborts mid-cycle leaving gc_state in a valid intermediate
                // state. PUC's longjmp also aborts the operation; the
                // difference is that PUC unwinds the C stack while we return
                // normally. This is the best we can do at a non-throwing C
                // ABI boundary.
                self.gcFullCollectionForUser() catch {};
                break :blk 0;
            },
            3 => @as(i32, @intFromFloat(@max(0.0, self.gc_count_kb))), // LUA_GCCOUNT: totalbytes >> 10
            4 => blk: { // LUA_GCCOUNTB: totalbytes & 0x3ff
                const total_bytes: u64 = @intFromFloat(@max(0.0, self.gc_count_kb * 1024.0));
                break :blk @intCast(total_bytes & 0x3ff);
            },
            5 => blk: { // LUA_GCSTEP
                const oldstp = self.gc_stp;
                self.gc_stp = 0; // allow GC to run
                const n: i64 = if (param <= 0) 0 else param; // param carries the size_t n
                // PUC lapi.c:1206-1208: n<=0 → n=GCdebt; setdebt(GCdebt-n)=0
                // (force due). n>0 → setdebt(GCdebt-n) (debt -= n).
                // Our gc_step_debt_kb fires at <=0 and decrements on alloc.
                // n<=0 → debt := 0 (force due); n>0 → debt -= n_kb.
                if (n <= 0) {
                    self.gc_step_debt_kb = 0;
                } else {
                    self.gc_step_debt_kb -= @as(f64, @floatFromInt(n)) / 1024.0;
                }
                // PUC luaC_step can luaD_throw on OOM (longjmp). gcControl
                // returns i32 (C ABI boundary), so we swallow OOM via
                // `catch false` (treat as "cycle not completed"). PUC's longjmp
                // also aborts the step; the return-value semantics (1 =
                // completed, 0 = not completed) are identical for the
                // non-OOM path.
                //
                // STEP pacing note: our incremental step may complete a cycle
                // in a different number of internal gcAdvance calls than PUC's
                // singlestep (implementation-granularity difference: PUC's
                // singlestep does one atomic mark/sweep unit per call, while
                // gcAdvance batches GCSWEEPMAX=20 objects). The return value
                // (1 = cycle reached GCSpause, 0 = still in progress) is
                // identical to PUC's — only the internal work granularity
                // differs. The 17_gccontrol differential test verifies this.
                const completed = self.gcStep(n) catch false;
                self.gc_stp = oldstp; // restore previous state
                self.gc_running = (self.gc_stp == 0);
                break :blk if (completed) 1 else 0;
            },
            6 => if (self.gc_running) 1 else 0, // LUA_GCISRUNNING: gcrunning
            7 => blk: { // LUA_GCGEN: changemode(KGC_GENMINOR); ret previous mode
                // PUC lapi.c:1220: res = (g->gckind == KGC_INC) ? LUA_GCINC : LUA_GCGEN.
                // KGC_GENMAJOR is NOT KGC_INC → returns LUA_GCGEN (7).
                // Our gc_mode == .incremental covers both KGC_INC and KGC_GENMAJOR;
                // gc_gen_phase == .major distinguishes KGC_GENMAJOR from KGC_INC.
                const prev_was_pure_inc = (self.gc_mode == .incremental and self.gc_gen_phase != .major);
                if (prev_was_pure_inc) {
                    // PUC luaC_changemode → entergen → luaC_fullgc can throw
                    // (luaD_throw/longjmp). gcControl returns i32 (C ABI
                    // boundary), so we swallow OOM. If entergen fails, the
                    // mode transition is incomplete but gc_mode/gc_gen_phase
                    // remain in their prior valid state — no invariant
                    // corruption.
                    self.gcEnterGenerational() catch {};
                } else if (self.gc_mode == .incremental and self.gc_gen_phase == .major) {
                    // PUC luaC_changemode: KGC_GENMAJOR → KGC_INC (rename), then
                    // newmode (KGC_GENMINOR) != KGC_INC → entergen.
                    self.gc_gen_phase = .minor;
                    self.gcEnterGenerational() catch {};
                }
                break :blk if (prev_was_pure_inc) 8 else 7; // LUA_GCINC=8, LUA_GCGEN=7
            },
            8 => blk: { // LUA_GCINC: changemode(KGC_INC); ret previous mode
                // PUC lapi.c:1224: res = (g->gckind == KGC_INC) ? LUA_GCINC : LUA_GCGEN.
                // KGC_GENMAJOR is NOT KGC_INC → returns LUA_GCGEN (7).
                const prev_was_pure_inc = (self.gc_mode == .incremental and self.gc_gen_phase != .major);
                if (!prev_was_pure_inc) {
                    if (self.gc_mode == .generational) {
                        self.gcLeaveGenerational();
                    } else {
                        // PUC luaC_changemode: KGC_GENMAJOR → KGC_INC (rename only).
                        self.gc_gen_phase = .minor;
                    }
                }
                break :blk if (prev_was_pure_inc) 8 else 7; // LUA_GCINC=8, LUA_GCGEN=7
            },
            9 => blk: { // LUA_GCPARAM: res = applyparam(gcparams[param], 100)
                if (param < 0 or param >= 6) break :blk -1;
                const idx: usize = @intCast(param);
                const res = gcApplyParam(self.gcparams[idx], 100);
                if (value >= 0) {
                    self.gcparams[idx] = gcCodeParam(@intCast(value));
                    if (idx == 3 or idx == 0) self.gcScheduleNextAutomaticCycle();
                }
                break :blk @intCast(@min(res, @as(u64, std.math.maxInt(i32))));
            },
            else => -1, // invalid option
        };
    }

    /// Legacy 2-arg entry point for the Zig API (`api.State.gc`). Delegates
    /// to `gcControl` with param=value=0 (unused for non-GCPARAM options).
    pub fn apiGc(self: *Vm, what: i32, data: i32) i32 {
        // For LUA_GCSTEP, `data` carries the step size (PUC's vararg n).
        // For LUA_GCPARAM, `data` is unused (param/value come separately).
        if (what == 5) return self.gcControl(what, data, -1);
        return self.gcControl(what, 0, -1);
    }

    pub fn apiCall(self: *Vm, ccall_inc: u32, callee: Value, args: []const Value) Error![]Value {
        // P16.23 T6: PUC ldo.c ccall — every synchronous call THROUGH the
        // C API consumes one C-depth unit (lower 16 bits) and, for the
        // non-yieldable variant, one nny unit. Direct VM→builtin calls do
        // NOT pass through here (PUC precall adds no depth), preserving the
        // PUC distinction.
        const th = self.activeBytecodeThread();
        try exposeDispatchResult(void, self.ccallEnter(th, ccall_inc));
        defer th.ccallExit(ccall_inc);
        const resolved = try exposeDispatchResult(ResolvedCall, self.resolveCallable(callee, args, null));
        defer if (resolved.owned_args) |owned| self.alloc.free(owned);
        switch (resolved.callee) {
            .Builtin => |id| {
                const out_len = self.builtinOutLen(id, resolved.args);
                const outs = try self.alloc.alloc(Value, out_len);
                errdefer self.alloc.free(outs);
                try exposeDispatchResult(void, self.callBuiltin(id, resolved.args, outs));
                const used = if (builtinHasDynamicOutCount(id)) @min(self.last_builtin_out_count, outs.len) else outs.len;
                if (used == outs.len) return outs;
                const ret = try self.alloc.alloc(Value, used);
                for (0..used) |i| ret[i] = outs[i];
                self.alloc.free(outs);
                return ret;
            },
            .Closure => |cl| return exposeDispatchResult([]Value, self.runClosure(cl, resolved.args)),
            else => unreachable,
        }
    }

    pub fn apiResumeThread(self: *Vm, th: *Thread, args: []const Value, outs: []Value) Error!usize {
        if (outs.len == 0) return 0;
        const resume_args = try self.alloc.alloc(Value, args.len + 1);
        defer self.alloc.free(resume_args);
        resume_args[0] = .{ .Thread = th };
        for (args, 0..) |v, i| resume_args[i + 1] = v;
        try exposeDispatchResult(void, self.builtinCoroutineResume(resume_args, outs));
        return self.last_builtin_out_count;
    }

    /// PUC hook-yield visibility window (P15.83q). When a coroutine
    /// suspends because a debug hook yielded, `lua_resume` reports
    /// `*nresults = ci->u2.nyield = 0` (hooks cannot yield values, PUC
    /// ldo.c:1023-1024) while `lua_gettop` exposes the ENTIRE register
    /// window of the suspended Lua frame:
    ///
    ///   1. luaG_traceexec sets `L->top.p = ci->top.p` BEFORE dispatching
    ///      the hook (ldebug.c:954) — top spans the frame's whole
    ///      register file (ci->top = ci->func + 1 + maxstacksize).
    ///   2. lua_yieldk inside a hook (isLua(ci)) merely returns
    ///      (ldo.c:1025-1028) after setting `L->status = LUA_YIELD` and
    ///      `ci->u2.nyield = 0`; luaG_traceexec then marks
    ///      CIST_HOOKYIELD and `luaD_throw(L, LUA_YIELD)` (ldebug.c:971-977).
    ///   3. The longjmp skips luaD_hook's `ci->top`/`L->top` restore
    ///      (ldo.c:458-465), so at the lua_resume boundary top still
    ///      equals the frame's register window end. `lua_gettop` =
    ///      `L->top - (ci->func + 1)` = maxstacksize slots.
    ///
    /// Returns that window as a BORROWED slice of the thread's parked
    /// register stack (callers must copy before mutating anything that
    /// could reallocate it), or null when `th` is not suspended in a
    /// hook-yield state (last yield not from a debug hook, or no parked
    /// Lua frame — e.g. a C-function yield, where PUC's window is the
    /// yielded values themselves).
    pub fn apiHookYieldWindow(self: *Vm, th: *Thread) ?[]const Value {
        if (th.status != .suspended) return null;
        // yielded_from_debug_hook is refreshed on EVERY yield
        // (builtinCoroutineYield), so at the resume boundary it says
        // whether THIS suspension came from a debug hook. Hooks cannot
        // yield values (api_check), so the yielded slice is empty.
        if (!th.yielded_from_debug_hook) return null;
        // The suspended frame whose trap fired the hook: topmost parked
        // Lua frame (C-hook frames never park a CallFrame, mirroring PUC
        // where the hook runs with the Lua frame's own CallInfo).
        const fr = threadCurrentParkedRuntimeFrame(th) orelse return null;
        const proto = fr.proto() orelse return null;
        const stack = stackForThread(self, th);
        // PUC window: ci->func + 1 .. ci->func + 1 + maxstacksize. Zig
        // frames may grow frame_cap beyond maxstacksize (EXTRA_MARGIN /
        // bcGrowFrame for multret) — the exposed window is exactly the
        // proto's register file, matching PUC's ci->top.
        const n: usize = proto.maxstacksize;
        const fb = fr.frameBase();
        if (fb + n > stack.len) return null;
        return stack[fb .. fb + n];
    }

    /// PUC `lua_closethread` → `luaE_resetthread` (lstate.c:324-333).
    /// Delegates to `builtinCoroutineClose`, which implements the full
    /// reset semantics: close all upvalues/TBCs, run `__close`
    /// metamethods (a `__close` error replaces the status — last error
    /// wins), set thread status to dead.
    ///
    /// Returns the PUC status code (0 = `LUA_OK`, 2 = `LUA_ERRRUN`) and
    /// the error object (`Nil` on success). The caller
    /// (`c_api.zig:lua_closethread`) is responsible for pushing the error
    /// object onto `c_stack` on error, matching PUC `luaD_seterrorobj`.
    pub fn apiCloseThread(self: *Vm, th: *Thread) Error!struct { status: i32, err: Value } {
        var out = [_]Value{ .Nil, .Nil };
        try exposeDispatchResult(void, self.builtinCoroutineClose(&[_]Value{.{ .Thread = th }}, out[0..]));
        const ok = out[0] == .Bool and out[0].Bool;
        return .{ .status = if (ok) 0 else 2, .err = out[1] };
    }

    pub fn apiYield(self: *Vm, args: []const Value) Error!void {
        var out: [0]Value = .{};
        return exposeDispatchResult(void, self.builtinCoroutineYield(args, out[0..]));
    }

    /// PUC api_check invariants for C continuations used inside debug hooks
    /// (spec §7 "API checks"). The PUC sources:
    ///   lapi.c:1041-1042 (lua_callk) and lapi.c:1082-1083 (lua_pcallk):
    ///     api_check(L, k == NULL || !isLua(L->ci),
    ///               "cannot use continuations inside hooks");
    ///   ldo.c:1023-1024 (lua_yieldk, hook branch):
    ///     api_check(L, nresults == 0, "hooks cannot yield values");
    ///     api_check(L, k == NULL, "hooks cannot continue after yielding");
    ///
    /// Why the condition is `isInDebugHook()`: while a hook runs, PUC's
    /// current CallInfo is the hooked Lua frame (luaD_hook sets CIST_HOOKED
    /// on L->ci and calls the hook with that ci on top), so isLua(L->ci) is
    /// true and any non-NULL k is an API violation; a yielding hook may
    /// pass neither results nor a continuation. luazig's equivalent of
    /// "the hook is running" is the per-thread `in_debug_hook` flag,
    /// maintained around every hook dispatch: sync C hooks
    /// (debugDispatchHookTransfer), sync Lua/testC hooks, and async
    /// Lua-hook frames (tryPushBytecodeDebugHook / popBytecodeExecFrame).
    /// At every call site `th` is `current_thread`, so the flag on `th`
    /// and isInDebugHook() are the same condition — both are checked for
    /// robustness against future call-site drift.
    ///
    /// Enforcement model: PUC compiles api_check out of release builds
    /// (under LUA_USE_APICHECK it aborts via lua_assert). Silently
    /// ignoring the violation would leave the continuation half-installed
    /// (the old P15.83i deviation #3), which the spec explicitly forbids
    /// ("Violations must not be silently ignored"). Instead the check
    /// raises a deterministic runtime error carrying the PUC message text:
    /// the callers (c_api wrappers / testC) convert error.RuntimeError to
    /// their regime (`_longjmp` to the C boundary / Zig error), so
    /// lua_resume / lua_pcall report LUA_ERRRUN with the message and the
    /// coroutine dies — no continuation state is mutated. `is_yield`
    /// selects the lua_yieldk variant of the checks (PUC checks nresults
    /// first, then k — same order here).
    pub fn apiCheckHookContinuationInvariant(
        self: *Vm,
        th: *Thread,
        k_nonnull: bool,
        is_yield: bool,
        nresults: i32,
    ) Error!void {
        if (!th.debug_hook.in_debug_hook and !self.isInDebugHook()) return;
        if (is_yield) {
            if (nresults != 0)
                return self.fail("hooks cannot yield values", .{});
            if (k_nonnull)
                return self.fail("hooks cannot continue after yielding", .{});
        } else if (k_nonnull) {
            return self.fail("cannot use continuations inside hooks", .{});
        }
    }

    /// Shared core of PUC `lua_callk` (lapi.c:1037-1056): save k/ctx on the
    /// current top C-frame (PUC `ci->u.c.k = k`), then invoke `apiCall` with
    /// the caller-supplied callee/args. Returns callee results (caller-owned
    /// slice, free with `alloc.free`). On `error.Yield`/`error.RuntimeError`
    /// the C-frame is left for `finishCcall`/`precover` — callers convert
    /// (c_api: `_longjmp`; testC: propagate through `callBuiltin`).
    /// `k == null` → `incnny` (non-yieldable boundary, PUC `luaD_callnoyield`)
    /// with `decnny` on return.
    ///
    /// Both c_api (`lua_callk`) and testC (`.callk` branch) delegate here so
    /// the production k/ctx lifecycle has a single implementation. The caller
    /// is responsible for reading callee/args from its stack (c_stack or st),
    /// marshalling results back, and converting errors to its regime
    /// (`_longjmp` or Zig error propagation).
    /// PUC ldo.c `ccall` enter half: nCcalls += inc, then the depth guard
    /// (getCcalls >= LUAI_MAXCCALLS → "C stack overflow"; PUC first tier of
    /// luaE_checkcstack). On failure the increment is rolled back so the
    /// error path cannot underflow. This is THE single C-call boundary
    /// model — no local depth counters anywhere (P16.23 T6).
    pub fn ccallEnter(self: *Vm, th: *Thread, inc: u32) DispatchError!void {
        th.nCcalls +%= inc;
        if (th.getCcalls() >= Thread.LUA_MAX_C_CALLS) {
            th.nCcalls -%= inc;
            return self.fail("C stack overflow", .{});
        }
    }

    pub fn luaCallKShared(
        self: *Vm,
        th: *Thread,
        callee: Value,
        args: []const Value,
        k: ?*const fn (?*lua_State, c_int, isize) callconv(.c) c_int,
        ctx: isize,
    ) Error![]Value {
        // PUC lapi.c:1041-1042: api_check(k == NULL || !isLua(L->ci),
        // "cannot use continuations inside hooks"). Checked BEFORE the
        // yieldable branch (PUC's check is unconditional) and BEFORE any
        // frame state is saved — a violation must not leave k/ctx
        // half-installed.
        try self.apiCheckHookContinuationInvariant(th, k != null, false, 0);
        // PUC lapi.c:1047-1053: if k != NULL and yieldable, save k/ctx on
        // L->ci (the current top C-frame); else callnoyield (incnny).
        if (k) |kf| {
            if (th.yieldable()) {
                if (th.call_frames.len() > 0) {
                    const fr = th.call_frames.getPtr(th.call_frames.len() - 1);
                    if (fr.isC()) {
                        fr.u.c.k = kf;
                        fr.u.c.ctx = ctx;
                    }
                }
            }
        }
        // P16.23 T6: PUC lua_callk — k (and yieldable) uses the yieldable
        // increment (plain +1 depth); no k is luaD_callnoyield (nyci: nny
        // + depth). The old bare incnny/decnny is superseded by ccall.
        const ccall_inc: u32 = if (k != null)
            Thread.CCALL_INC_YIELDABLE
        else
            Thread.CCALL_INC_NOYIELD;
        try exposeDispatchResult(void, self.ccallEnter(th, ccall_inc));
        defer th.ccallExit(ccall_inc);
        return self.apiCall(ccall_inc, callee, args);
    }

    /// Shared core of PUC `lua_pcallk` yieldable path (lapi.c:1097-1117):
    /// save k/ctx/funcidx/old_errfunc/OAH on the current top C-frame, set
    /// `CIST_YPCALL`, invoke `apiCall`. Normal return: `clearYpcall` +
    /// restore errfunc (lapi.c:1110-1112) and return results. `error.Yield` /
    /// `error.RuntimeError`: C-frame stays (`CIST_YPCALL`) for `precover` —
    /// propagate to the caller's regime.
    ///
    /// `errfunc_val` null = no handler for the duration (`th.errfunc := ERRFUNC_NONE`,
    /// matching PUC `L->errfunc = func` where `func = 0` when `errfunc == 0`).
    /// On normal return, `th.errfunc` is restored to the saved `old_errfunc`.
    ///
    /// Both c_api (`lua_pcallk` yieldable path) and testC (`.pcallk` branch)
    /// delegate here. The caller handles error conversion (`_longjmp` or Zig
    /// propagation) and result marshalling. On error, the caller's fallback
    /// (no `_longjmp` boundary) must `clearYpcall` + restore errfunc itself.
    pub fn luaPcallKShared(
        self: *Vm,
        th: *Thread,
        callee: Value,
        args: []const Value,
        errfunc_val: ?Value,
        funcidx: usize,
        k: *const fn (?*lua_State, c_int, isize) callconv(.c) c_int,
        ctx: isize,
    ) Error![]Value {
        // PUC lapi.c:1082-1083: api_check(k == NULL || !isLua(L->ci),
        // "cannot use continuations inside hooks") — unconditional in PUC,
        // before any state is saved. Checked before reading/writing the
        // C-frame so a violation leaves no k/ctx/funcidx/errfunc residue.
        try self.apiCheckHookContinuationInvariant(th, true, false, 0);
        if (th.call_frames.len() == 0) return error.RuntimeError;
        const fr = th.call_frames.getPtr(th.call_frames.len() - 1);
        if (!fr.isC()) return error.RuntimeError;

        // PUC lapi.c:1101-1108: save k/ctx, funcidx, old_errfunc, set new
        // errfunc, save OAH, set CIST_YPCALL.
        fr.u.c.k = k;
        fr.u.c.ctx = ctx;
        fr.u.c.aux.funcidx = @intCast(funcidx);
        fr.u.c.old_errfunc = th.errfunc;
        if (errfunc_val) |ef| {
            self.setErrfuncValue(ef);
        } else {
            th.errfunc = ERRFUNC_NONE;
        }
        fr.setOah(th.allowhook);
        fr.setYpcall();

        // P16.23 T6: pcallk yieldable path — DEPTH-ONLY inc (the C-frame
        // continuation machinery owns yield semantics; an nny unit would
        // block yield-through-pcallk, regressing c_api 10_continuations t2).
        const ret = self.apiCall(Thread.CCALL_INC_YIELDABLE, callee, args) catch |e| {
            // PUC: on error/yield, `luaD_call` longjmps — CIST_YPCALL stays,
            // errfunc stays set. `precover`/`finishpcallk` handles cleanup on
            // resume. Propagate to the caller's regime.
            return e;
        };

        // Normal return: clear CIST_YPCALL, restore errfunc
        // (PUC lapi.c:1110-1112).
        fr.clearYpcall();
        if (errfunc_val != null) {
            self.setErrfuncValue(null);
        }
        th.errfunc = fr.u.c.old_errfunc;
        return ret;
    }

    /// Shared core of PUC `lua_yieldk` (ldo.c:1006-1034): enforce the hook
    /// api_checks (nresults == 0, k == NULL — violations raise a runtime
    /// error with the PUC message, see
    /// `apiCheckHookContinuationInvariant`), save `nyield` and k/ctx on the
    /// current top C-frame, then invoke `apiYield`. Returns `error.Yield`
    /// on success (the caller converts: c_api `_longjmp(jb, 2)`; testC
    /// propagates through `callBuiltin`). On `error.RuntimeError`
    /// (non-yieldable or hook api_check violation), the C-frame state is
    /// left as-is for the caller to handle.
    ///
    /// Both c_api (`lua_yieldk`) and testC (`.yieldk` / `.yield` non-hook
    /// path) delegate here. The caller is responsible for reading yielded
    /// values from its stack and converting errors to its regime.
    pub fn luaYieldKShared(
        self: *Vm,
        th: *Thread,
        yielded: []const Value,
        nresults: i32,
        k: ?*const fn (?*lua_State, c_int, isize) callconv(.c) c_int,
        ctx: isize,
    ) Error!void {
        // PUC ldo.c:1021-1024 (hook branch of lua_yieldk):
        //   api_check(nresults == 0, "hooks cannot yield values");
        //   api_check(k == NULL, "hooks cannot continue after yielding");
        // (PUC checks nresults first, then k — apiCheckHookContinuationInvariant
        // preserves that order.) The check runs BEFORE nyield/k/ctx are
        // saved: a violating yield must fail cleanly instead of parking a
        // hook yield with bogus nresults or a continuation the hook is
        // forbidden to have.
        try self.apiCheckHookContinuationInvariant(th, k != null, true, nresults);
        // PUC ldo.c:1020-1028: ci->u2.nyield = nresults; if not a hook,
        // ci->u.c.k = k; ci->u.c.ctx = ctx. The isDebugHook() guard below
        // is now defense-in-depth only: the api_check above already
        // rejected k != NULL inside hooks, so this branch is unreachable
        // for hook frames — kept in case a future dispatch path runs a
        // hook without setting in_debug_hook.
        if (th.call_frames.len() > 0) {
            const fr = th.call_frames.getPtr(th.call_frames.len() - 1);
            if (fr.isC()) {
                fr.u.c.aux.nyield = nresults;
                if (k) |kf| {
                    if (!fr.isDebugHook()) {
                        fr.u.c.k = kf;
                        fr.u.c.ctx = ctx;
                    }
                }
            }
        }
        return self.apiYield(yielded);
    }

    pub fn apiIsYieldable(self: *Vm, th: ?*Thread) Error!bool {
        var out: [1]Value = .{.Nil};
        if (th) |t| {
            try exposeDispatchResult(void, self.builtinCoroutineIsyieldable(&[_]Value{.{ .Thread = t }}, out[0..]));
        } else {
            try exposeDispatchResult(void, self.builtinCoroutineIsyieldable(&.{}, out[0..]));
        }
        return out[0] == .Bool and out[0].Bool;
    }

    pub fn apiStackNormalizeIndex(_: *Vm, stack: *const std.ArrayListUnmanaged(Value), idx: i32) Error!usize {
        if (idx == 0) return error.RuntimeError;
        if (idx > 0) {
            const abs: usize = @intCast(idx - 1);
            if (abs >= stack.items.len) return error.RuntimeError;
            return abs;
        }
        const r: usize = @intCast(-idx);
        if (r == 0 or r > stack.items.len) return error.RuntimeError;
        return stack.items.len - r;
    }

    pub fn apiStackAbsIndex(self: *Vm, stack: *const std.ArrayListUnmanaged(Value), idx: i32) Error!i32 {
        _ = try self.apiStackNormalizeIndex(stack, idx);
        if (idx > 0) return idx;
        return @intCast(@as(i64, @intCast(stack.items.len)) + @as(i64, idx) + 1);
    }

    pub fn apiStackPop(_: *Vm, stack: *std.ArrayListUnmanaged(Value), n: usize) Error!void {
        if (n > stack.items.len) return error.RuntimeError;
        stack.items.len -= n;
    }

    pub fn apiStackPush(self: *Vm, stack: *std.ArrayListUnmanaged(Value), value: Value) Error!void {
        try stack.append(self.alloc, value);
    }

    pub fn apiStackPushValue(self: *Vm, stack: *std.ArrayListUnmanaged(Value), idx: i32) Error!void {
        const abs = try self.apiStackNormalizeIndex(stack, idx);
        try stack.append(self.alloc, stack.items[abs]);
    }

    pub fn apiStackRemove(self: *Vm, stack: *std.ArrayListUnmanaged(Value), idx: i32) Error!void {
        try self.apiStackRotate(stack, idx, -1);
        try self.apiStackPop(stack, 1);
    }

    pub fn apiStackInsert(self: *Vm, stack: *std.ArrayListUnmanaged(Value), idx: i32) Error!void {
        try self.apiStackRotate(stack, idx, 1);
    }

    pub fn apiStackReplace(self: *Vm, stack: *std.ArrayListUnmanaged(Value), idx: i32) Error!void {
        if (stack.items.len == 0) return error.RuntimeError;
        const abs = try self.apiStackNormalizeIndex(stack, idx);
        const top = stack.items.len - 1;
        stack.items[abs] = stack.items[top];
        stack.items.len = top;
    }

    pub fn apiStackCopy(self: *Vm, stack: *std.ArrayListUnmanaged(Value), from_idx: i32, to_idx: i32) Error!void {
        const from = try self.apiStackNormalizeIndex(stack, from_idx);
        const to = try self.apiStackNormalizeIndex(stack, to_idx);
        stack.items[to] = stack.items[from];
    }

    pub fn apiStackRotate(self: *Vm, stack: *std.ArrayListUnmanaged(Value), idx: i32, n: i32) Error!void {
        const start = try self.apiStackNormalizeIndex(stack, idx);
        const slice = stack.items[start..];
        if (slice.len <= 1) return;
        var nmod = @mod(@as(i64, n), @as(i64, @intCast(slice.len)));
        if (nmod < 0) nmod += @intCast(slice.len);
        if (nmod == 0) return;
        std.mem.rotate(Value, slice, slice.len - @as(usize, @intCast(nmod)));
    }

    pub fn apiStackConcat(self: *Vm, stack: *std.ArrayListUnmanaged(Value), n: usize) Error!void {
        if (n > stack.items.len) return error.RuntimeError;
        if (n == 0) {
            try stack.append(self.alloc, .{ .String = try self.internStr("") });
            return;
        }
        if (n == 1) return;
        const start = stack.items.len - n;
        var acc = stack.items[start];
        var i = start + 1;
        while (i < stack.items.len) : (i += 1) {
            acc = try self.apiConcat(acc, stack.items[i]);
        }
        stack.items.len = start;
        try stack.append(self.alloc, acc);
    }

    pub fn apiStackXMove(self: *Vm, from_stack: *std.ArrayListUnmanaged(Value), to_stack: *std.ArrayListUnmanaged(Value), n: usize) Error!void {
        if (n > from_stack.items.len) return error.RuntimeError;
        if (n == 0) return;
        const start_idx = from_stack.items.len - n;
        const moved = try self.alloc.alloc(Value, n);
        defer self.alloc.free(moved);
        for (0..n) |i| moved[i] = from_stack.items[start_idx + i];
        from_stack.items.len = start_idx;
        try to_stack.appendSlice(self.alloc, moved);
    }

    fn gcFinalizeAtClose(self: *Vm) void {
        // PUC `close_state` → `luaC_freeallobjects` → `callallpendingfinalizers`.
        // Runs all pending __gc finalizers at state close time. Finalizers are
        // called in LIFO order (most recently created first), matching PUC's
        // `tobefnz` list which is prepended to by `separatetobefnz`.
        //
        // PUC sets `g->gcstp = GCSTPCLS` before running finalizers, which:
        //   - prevents new objects from being queued for finalization
        //   - makes `collectgarbage()` return false
        //   - prevents re-entrant finalization
        // We set `is_closing` here to handle all three behaviors. This covers
        // both the `os.exit(_, true)` path (via `closeStateForExit`) and the
        // `Vm.deinit()` path (normal teardown).
        self.is_closing = true;
        self.gc_stp |= GCSTPCLS; // PUC: gcstp = GCSTPCLS
        // Keep the collector non-reentrant while registry ownership is being
        // torn down; allocations remain owned by the registries and are
        // drained immediately after all closing finalizers return.
        const was_busy = self.gc_busy;
        self.gc_busy = true;
        defer self.gc_busy = was_busy;

        // Snapshot all objects currently marked as finalizable. PUC's
        // `separatetobefnz(g, 1)` separates ALL finalizable objects into
        // `tobefnz` in one pass; we snapshot the `finalizables` set.
        // Objects created by finalizers during the close sequence are NOT
        // included (PUC GCSTPCLS prevents queuing).
        var to_finalize = std.ArrayListUnmanaged(GcObject).empty;
        defer to_finalize.deinit(self.alloc);

        var it = self.finalizables.iterator();
        while (it.next()) |entry| {
            to_finalize.append(self.alloc, entry.key_ptr.*) catch return;
        }

        // Sort by gc_seq descending (LIFO creation order), matching PUC's
        // `tobefnz` list order. Reuses the same comparator as the GC path.
        std.sort.block(GcObject, to_finalize.items, self, gcFinalizeLessThan);

        for (to_finalize.items) |obj| {
            // PUC udata2finalize (lgc.c:947-960): dequeue and clear
            // FINALIZEDBIT BEFORE resolving __gc on the current metatable.
            self.takeFinalizable(obj);
            const mt: ?*Table = switch (obj) {
                .table => |t| t.metatable,
                .userdata => |u| u.metatable,
                else => null,
            };
            const m = mt orelse continue;
            const gc = self.fastTm(m, .gc) orelse continue;
            const self_val: Value = obj.toValue() orelse continue;
            const call_args = &[_]Value{self_val};
            _ = self.callFinalizer(gc, call_args) catch |e| switch (e) {
                // PUC lgc.c:988-991 (GCTM): errors in __gc finalizers are
                // reported through the warning channel via
                // `luaE_warnerror(L, "__gc")`, producing
                // "error in __gc (<error message>)". The error object is
                // then popped and closing continues with the next finalizer.
                error.RuntimeError => {
                    const err_obj = self.protectedErrorValue();
                    const err_msg: []const u8 = switch (err_obj) {
                        .String => |s| s.bytes(),
                        else => "error object is not a string",
                    };
                    var warn_buf: std.ArrayListUnmanaged(u8) = .empty;
                    defer warn_buf.deinit(self.alloc);
                    warn_buf.appendSlice(self.alloc, "error in __gc (") catch return;
                    warn_buf.appendSlice(self.alloc, err_msg) catch return;
                    warn_buf.append(self.alloc, ')') catch return;
                    self.warnfHandler(warn_buf.items, false) catch {};
                    self.err = null;
                    self.err_has_obj = false;
                    self.err_obj = .Nil;
                },
                else => return,
            };
        }
    }

    fn callFinalizer(self: *Vm, gc: Value, args: []const Value) DispatchError!Value {
        // PUC Lua does not run debug hooks while executing a finalizer body.
        // Keep hooks installed, but suppress line/count/call events for the
        // finalizer call itself.
        self.debug_hooks_suppressed += 1;
        defer self.debug_hooks_suppressed -= 1;
        return self.callMetamethod(gc, "__gc", args);
    }

    pub fn errorString(self: *Vm) []const u8 {
        return self.err orelse "<no error object>";
    }

    /// PUC `msghandler` (lua.c:136-148) for the CLI error-reporting path.
    ///
    /// After `runBytecode` fails at the top level, this method formats the
    /// error object the same way PUC's `msghandler` does when used as a
    /// `pcall` message handler:
    ///
    /// 1. If the error object is a string, use it as the message and append
    ///    the traceback captured at the fault point (`err_traceback`).
    /// 2. If the error object is NOT a string:
    ///    a. Try the `__tostring` metamethod. If it returns a string, use
    ///       that string directly — NO traceback is appended (matching PUC's
    ///       `return 1` before `luaL_traceback`).
    ///    b. Otherwise, format `(error object is a %s value)` with the type
    ///       name and append the traceback.
    ///
    /// The returned slice is allocated from `alloc` and must be freed by the
    /// caller. The VM's error state (`err_obj`, `err_traceback`, etc.) is
    /// preserved — calling this method does not consume the error.
    ///
    /// PUC `msghandler` (lua.c:136-148): message handler for the CLI.
    /// Called via `errfunc` BEFORE call stack unwinding, so `__tostring`
    /// metamethods can access `debug.getinfo(N)`.
    ///
    /// Logic (matching PUC):
    /// 1. If error object is a string → use it + append traceback.
    /// 2. If error object is not a string → try `__tostring` metamethod.
    ///    If it returns a string → use it (NO traceback).
    /// 3. If no `__tostring` or it fails → use `"(error object is a %s value)"`
    ///    + append traceback.
    fn builtinCliMsghandler(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0) {
            outs[0] = .{ .String = self.internStrAssume("(no error object)") };
            return;
        }
        const err_obj = args[0];

        // Case 1: error object is a string → use it + append traceback.
        // PUC: the error object already includes source location (added by
        // luaG_addinfo). In luazig, fail() stores the raw message; use
        // protectedErrorString to add the source location.
        if (err_obj == .String) {
            const msg = self.protectedErrorString();
            const result = self.formatErrorWithTraceback(self.alloc, msg) catch return error.OutOfMemory;
            defer self.alloc.free(result); // temp; internStr copies
            outs[0] = .{ .String = self.internStr(result) catch return error.OutOfMemory };
            return;
        }

        // Case 2: error object is not a string → try `__tostring` metamethod.
        if (self.getMetaFieldByObj(err_obj, .tostring)) |mm| {
            var call_args = [_]Value{err_obj};
            const result = self.callMetamethod(mm, "__tostring", call_args[0..]) catch {
                // Metamethod errored → fall through to "(error object is a %s value)".
                const type_name = self.valueTypeName(err_obj);
                const msg = std.fmt.allocPrint(self.alloc, "(error object is a {s} value)", .{type_name}) catch return error.OutOfMemory;
                defer self.alloc.free(msg);
                const tb_result = self.formatErrorWithTraceback(self.alloc, msg) catch return error.OutOfMemory;
                defer self.alloc.free(tb_result); // temp; internStr copies
                outs[0] = .{ .String = self.internStr(tb_result) catch return error.OutOfMemory };
                return;
            };
            if (result == .String) {
                // PUC: metamethod returned a string → use it directly, NO traceback.
                outs[0] = result;
                return;
            }
        }

        // Case 3: no `__tostring` or it didn't return a string.
        const type_name = self.valueTypeName(err_obj);
        const msg = std.fmt.allocPrint(self.alloc, "(error object is a {s} value)", .{type_name}) catch return error.OutOfMemory;
        defer self.alloc.free(msg);
        const tb_result = self.formatErrorWithTraceback(self.alloc, msg) catch return error.OutOfMemory;
        defer self.alloc.free(tb_result); // temp; internStr copies
        outs[0] = .{ .String = self.internStr(tb_result) catch return error.OutOfMemory };
    }

    /// This is the CLI-side equivalent of PUC's `docall` → `msghandler` →
    /// `report` chain. The `progname:` prefix is added by the caller, matching
    /// PUC's `l_message(progname, msg)`.
    pub fn formatCliError(self: *Vm, alloc: std.mem.Allocator) Error![]u8 {
        // Determine the error object. If err_has_obj is false (shouldn't
        // happen for a real RuntimeError, but guard anyway), synthesize a
        // string from errorString().
        const err_obj: Value = if (self.err_has_obj) self.err_obj else blk: {
            const s = self.internStr(self.errorString()) catch return error.OutOfMemory;
            break :blk .{ .String = s };
        };

        // Case 1: error object is a string → use it + append traceback.
        // PUC: `const char *msg = lua_tostring(L, 1);` succeeds → falls
        // through to `luaL_traceback(L, L, msg, 1)`.
        // In PUC, the error object already includes the source location
        // (added by luaG_addinfo). In luazig, fail() stores the raw message
        // in err_obj; protectedErrorString adds the source location.
        if (err_obj == .String) {
            const msg = self.protectedErrorString();
            return self.formatErrorWithTraceback(alloc, msg);
        }

        // Case 2: error object is not a string.
        // PUC: `lua_tostring` returns NULL → try `__tostring` metamethod.
        if (self.getMetaFieldByObj(err_obj, .tostring)) |mm| {
            // Save the error state — calling the metamethod may clobber it.
            const saved_err = self.err;
            const saved_err_obj = self.err_obj;
            const saved_err_has_obj = self.err_has_obj;
            const saved_err_source = self.err_source;
            const saved_err_line = self.err_line;
            const saved_err_traceback = self.err_traceback;
            self.err_traceback = null;

            var call_args = [_]Value{err_obj};
            const result = self.callMetamethod(mm, "__tostring", call_args[0..]) catch |e| switch (e) {
                // If __tostring itself errors, fall through to the
                // "(error object is a %s value)" format. PUC's msghandler
                // runs inside pcall protection; we approximate by treating
                // a metamethod error as "no usable result".
                error.RuntimeError => null,
                error.OutOfMemory => {
                    // Restore error state before propagating OOM.
                    self.clearErrorTraceback();
                    self.err = saved_err;
                    self.err_obj = saved_err_obj;
                    self.err_has_obj = saved_err_has_obj;
                    self.err_source = saved_err_source;
                    self.err_line = saved_err_line;
                    self.err_traceback = saved_err_traceback;
                    return error.OutOfMemory;
                },
                // Yield/ThreadSwitch at the CLI top level is unexpected;
                // treat as "no usable result" and fall through.
                error.Yield, error.ThreadSwitch => null,
            };

            // Restore the original error state.
            self.clearErrorTraceback();
            self.err = saved_err;
            self.err_obj = saved_err_obj;
            self.err_has_obj = saved_err_has_obj;
            self.err_source = saved_err_source;
            self.err_line = saved_err_line;
            self.err_traceback = saved_err_traceback;

            // PUC: `if (luaL_callmeta(...) && lua_type(L, -1) == LUA_TSTRING)
            //        return 1;` — metamethod returned a string → use it
            // directly, NO traceback.
            if (result) |v| {
                if (v == .String) {
                    const msg = v.String.bytes();
                    return alloc.dupe(u8, msg);
                }
            }
        }

        // Case 2b: no `__tostring` metamethod, or it didn't return a string.
        // PUC: `msg = lua_pushfstring(L, "(error object is a %s value)",
        //          luaL_typename(L, 1));` then falls through to
        // `luaL_traceback`.
        const type_name = self.valueTypeName(err_obj);
        const msg = std.fmt.allocPrint(alloc, "(error object is a {s} value)", .{type_name}) catch return error.OutOfMemory;
        defer alloc.free(msg);
        return self.formatErrorWithTraceback(alloc, msg);
    }

    /// Format `msg` followed by the captured traceback (if any), matching
    /// PUC's `luaL_traceback(L, L, msg, 1)` which prepends `msg\n` before
    /// the stack traceback.
    fn formatErrorWithTraceback(self: *Vm, alloc: std.mem.Allocator, msg: []const u8) std.mem.Allocator.Error![]u8 {
        if (self.err_traceback) |tb| {
            return std.fmt.allocPrint(alloc, "{s}\n{s}", .{ msg, tb });
        }
        return alloc.dupe(u8, msg);
    }

    fn protectedErrorValue(self: *Vm) Value {
        // PUC model: the error object IS the Lua value thrown by error() or
        // constructed by luaG_runerror (with source prefix baked in at the
        // point of error). We return err_obj directly — no reconstruction,
        // no heuristic source-prefix addition. The error object is finalized
        // at the point of error (error() builtin, fail()/luaG_runerror) and
        // carried as-is through pcall/xpcall recovery.
        //
        // The previous heuristic (adding source prefix if the message had no
        // ":") was wrong: it double-prefixed some errors and missed others.
        // PUC's luaG_addinfo adds the source prefix at error creation time,
        // not at pcall recovery time. If err_obj doesn't have a prefix, it's
        // because the error was created without one (e.g. error(msg, 0) or
        // a C function error with currentline=-1).
        if (self.err_has_obj) {
            return self.err_obj;
        }
        // Fallback: err_obj not set (e.g. C-level error before err_obj was
        // populated). Reconstruct from the diagnostic message.
        return .{ .String = self.internStrAssume(self.protectedErrorString()) };
    }

    /// Value passed to an xpcall message handler.
    ///
    /// PUC Lua calls the handler before normalizing a nil error object to
    /// `"<no error object>"`.  Protected-call results use the normalized form,
    /// but the handler must still receive the original nil object.
    fn errorHandlerInput(self: *Vm) Value {
        if (!self.err_has_obj) return .Nil;
        return self.protectedErrorValue();
    }

    /// Normalize a message-handler result the same way luaG_errormsg does.
    fn normalizeProtectedErrorResult(self: *Vm, value: Value) DispatchError!Value {
        if (value == .Nil) {
            return .{ .String = try self.internStr("<no error object>") };
        }
        return value;
    }

    fn clearErrorTraceback(self: *Vm) void {
        if (self.err_traceback) |tb| self.alloc.free(tb);
        self.err_traceback = null;
    }

    fn appendFmt(alloc: std.mem.Allocator, out: anytype, comptime fmt: []const u8, args: anytype) std.mem.Allocator.Error!void {
        const text = try std.fmt.allocPrint(alloc, fmt, args);
        defer alloc.free(text);
        try out.appendSlice(alloc, text);
    }

    fn captureErrorTraceback(self: *Vm) void {
        self.clearErrorTraceback();
        var aw: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer aw.deinit();
        var w = &aw.writer;
        w.writeAll("stack traceback:\n") catch return;

        // If the error was raised by a C function (error(), yield, etc.),
        // insert the synthetic [C]: in {label} frame at the top (most recent).
        // PUC's C functions push a CallInfo; luazig doesn't push C-frames for
        // builtins, so we synthesize them here for traceback parity.
        if (self.err_cfunc_label) |label| {
            w.print("\t[C]: in {s}\n", .{label}) catch return;
        }

        // Capture at the fault point, before the explicit CallInfo-like stack
        // is unwound for pcall/xpcall.  Like PUC Lua, retain both ends of a
        // deep traceback and omit its repetitive middle; emitting every frame
        // would make a recoverable stack overflow allocate another huge
        // object while the VM is already at its stack limit.
        //
        // P15.46b: Walk bytecode frames (Thread.call_frames) (most recent).
        // Bytecode frames live in Thread.call_frames; IR frames used to live
        // in Vm.call_frames but that array is always empty now, so only the
        // bytecode walk remains.
        var frame_ptrs = std.ArrayListUnmanaged(*const CallFrame).empty;
        defer frame_ptrs.deinit(self.alloc);
        {
            const th_bc = self.activeBytecodeThread();
            var i: usize = th_bc.call_frames.len();
            while (i > 0) {
                i -= 1;
                if (th_bc.call_frames.getConstPtr(i).isHidden()) continue;
                frame_ptrs.append(self.alloc, th_bc.call_frames.getPtr(i)) catch return;
            }
        }

        const head_count: usize = 10;
        const tail_count: usize = 10;
        if (frame_ptrs.items.len > head_count + tail_count + 2) {
            for (frame_ptrs.items[0..head_count], 0..) |fr_ptr, i| {
                if (self.getPendingCallConst(fr_ptr.pending_call_index)) |pending| {
                    if (pending.protection) |prot| {
                        const cname: []const u8 = if (prot.kind == .pcall) "pcall" else "xpcall";
                        w.print("\t[C]: in global '{s}'\n", .{cname}) catch return;
                    }
                }
                const caller_opt: ?*const Frame = if (i + 1 < frame_ptrs.items.len)
                    frame_ptrs.items[i + 1]
                else
                    null;
                const line = self.tracebackFrameLabel(fr_ptr, caller_opt, false) catch return;
                defer self.alloc.free(line);
                w.print("{s}\n", .{line}) catch return;
            }
            w.print("\t...\t(skipping {d} levels)\n", .{frame_ptrs.items.len - head_count - tail_count}) catch return;
            const tail_start = frame_ptrs.items.len - tail_count;
            for (frame_ptrs.items[tail_start..], 0..) |fr_ptr, i| {
                const idx = tail_start + i;
                if (self.getPendingCallConst(fr_ptr.pending_call_index)) |pending| {
                    if (pending.protection) |prot| {
                        const cname: []const u8 = if (prot.kind == .pcall) "pcall" else "xpcall";
                        w.print("\t[C]: in global '{s}'\n", .{cname}) catch return;
                    }
                }
                const caller_opt: ?*const Frame = if (idx + 1 < frame_ptrs.items.len)
                    frame_ptrs.items[idx + 1]
                else
                    null;
                const line = self.tracebackFrameLabel(fr_ptr, caller_opt, false) catch return;
                defer self.alloc.free(line);
                w.print("{s}\n", .{line}) catch return;
            }
        } else {
            for (frame_ptrs.items, 0..) |fr_ptr, i| {
                // If this frame has a pending protected call (pcall/xpcall),
                // insert a synthetic [C]: in global 'pcall'/'xpcall' line BEFORE
                // this frame. PUC's CallInfo stack includes the C frame for
                // pcall/xpcall; luazig's fast path (tryPushBytecodeProtectedCall)
                // skips it. The C-frame sits between the callee (previous frame)
                // and the caller (this frame).
                if (self.getPendingCallConst(fr_ptr.pending_call_index)) |pending| {
                    if (pending.protection) |prot| {
                        const cname: []const u8 = if (prot.kind == .pcall) "pcall" else "xpcall";
                        w.print("\t[C]: in global '{s}'\n", .{cname}) catch return;
                    }
                }
                const caller_opt: ?*const Frame = if (i + 1 < frame_ptrs.items.len)
                    frame_ptrs.items[i + 1]
                else
                    null;
                const line = self.tracebackFrameLabel(fr_ptr, caller_opt, false) catch return;
                defer self.alloc.free(line);
                w.print("{s}\n", .{line}) catch return;
            }
        }

        // PUC luaL_traceback walks the CallInfo stack which includes the
        // top-level C entry point. In luazig, the C entry point (lua_main /
        // docall) doesn't push a call frame, so we synthesize it here.
        // PUC shows [C]: in ? as the final frame (from pushfuncname's
        // fallback for C functions without a name).
        w.writeAll("\t[C]: in ?") catch return;
        self.err_traceback = aw.toOwnedSlice() catch null;
    }

    fn fail(self: *Vm, comptime fmt: []const u8, args: anytype) Error {
        // Fresh error: reset LUA_ERRERR signal before invokeErrfunc.
        self.err_is_errerr = false;
        // PUC Lua error messages can be long — e.g. `require`'s "module not
        // found" message lists every searched path (path + cpath), which can
        // exceed 512 bytes with the full default LUA_PATH_DEFAULT. Use a
        // generous stack buffer to avoid truncating to the "runtime error"
        // fallback (which loses the diagnostic entirely).
        var tmp: [2048]u8 = undefined;
        const msg = std.fmt.bufPrint(tmp[0..], fmt, args) catch "runtime error";
        self.err = std.fmt.bufPrint(self.err_buf[0..], "{s}", .{msg}) catch "runtime error";
        self.err_cfunc_label = null;
        // Use topLuaFrame() to skip C-frames (which don't have u.lua fields).
        // This prevents union field mismatch panic when callBuiltin pushes a
        // C-frame and a builtin calls fail().
        if (self.topLuaFrame()) |fr| {
            // Sync pc from the dispatch loop's working copy. With the
            // value-copy dispatch context, fr.u.lua.pc may be stale (only
            // updated at frame_loop boundaries by syncFrame).
            // dispatch_pc is written every instruction in the inner loop.
            fr.u.lua.pc = self.dispatch_pc;
            // P15.51n: current_line derived from proto.lineinfo[pc].
            self.err_source = fr.sourceName();
            self.err_line = self.frameCurrentLine(fr);
            // PUC luaG_runerror → luaG_addinfo: bake "source:line: " prefix
            // into the error message at creation time. The error object
            // (err_obj) is the full "source:line: msg" string, matching
            // PUC's luaO_pushfstring(L, "%s:%d: %s", chunk, line, msg).
            // protectedErrorValue() returns err_obj as-is — no reconstruction.
            // A NULL source (empty source_name — a stripped proto, which
            // has no line info either) takes PUC's luaG_addinfo NULL branch:
            // "?:?: msg" (same condition as protectedErrorString below).
            const src = self.err_source.?;
            const null_source = (src.len == 0 or std.mem.eql(u8, src, "=?")) and self.err_line < 1;
            const full = if (null_source)
                std.fmt.allocPrint(self.alloc, "?:?: {s}", .{msg}) catch msg
            else blk: {
                var id_buf: [59]u8 = undefined;
                const chunk = diag.chunkId(id_buf[0..], src);
                const line = self.err_line;
                break :blk if (line >= 1)
                    std.fmt.allocPrint(self.alloc, "{s}:{d}: {s}", .{ chunk, line, msg }) catch msg
                else
                    std.fmt.allocPrint(self.alloc, "{s}:?: {s}", .{ chunk, msg }) catch msg;
            };
            self.err_obj = .{ .String = self.internStrAssume(full) };
            self.err_has_obj = true;
        } else {
            self.err_source = null;
            self.err_line = -1;
            self.err_obj = .{ .String = try self.internStr(self.err.?) };
            self.err_has_obj = true;
        }
        self.captureErrorTraceback();
        try self.invokeErrfunc();
        return error.RuntimeError;
    }

    /// C-function variant of `fail`. Use this for errors that originate from
    /// a C builtin (e.g. `coroutine.yield`), matching PUC's `luaG_runerror`
    /// when `isLua(ci)` is false: `luaG_addinfo` is NOT called, so the error
    /// message has no "file:line:" prefix and `err_source`/`err_line` stay
    /// cleared. This matters because `invokeErrfunc` (the CLI message handler)
    /// reads `err_source` to format the final message — clearing must happen
    /// before the handler runs, not after `fail` returns.
    fn failC(self: *Vm, comptime fmt: []const u8, args: anytype) Error {
        // Fresh error: reset LUA_ERRERR signal before invokeErrfunc.
        self.err_is_errerr = false;
        var tmp: [2048]u8 = undefined;
        const msg = std.fmt.bufPrint(tmp[0..], fmt, args) catch "runtime error";
        self.err = std.fmt.bufPrint(self.err_buf[0..], "{s}", .{msg}) catch "runtime error";
        self.err_obj = .{ .String = try self.internStr(self.err.?) };
        self.err_has_obj = true;
        // err_cfunc_label may have been set by the caller — preserve it so
        // captureErrorTraceback can insert the synthetic C-frame.
        // No source location for C-function errors (PUC skips luaG_addinfo).
        self.err_source = null;
        self.err_line = -1;
        self.captureErrorTraceback();
        try self.invokeErrfunc();
        return error.RuntimeError;
    }

    /// PUC `luaL_error` equivalent: throws a formatted error message WITHOUT
    /// source prefix. Unlike `fail` (which is `luaG_runerror` and adds
    /// "source:line: " via `luaG_addinfo`), `luaL_error` calls `lua_error`
    /// directly without `luaG_addinfo`. Used by C library functions like
    /// `require` (loadlib.c) and `assert` (lauxlib.c) where PUC does not
    /// add source location to the error object.
    fn failLib(self: *Vm, comptime fmt: []const u8, args: anytype) Error {
        // Fresh error: reset LUA_ERRERR signal before invokeErrfunc.
        self.err_is_errerr = false;
        var tmp: [2048]u8 = undefined;
        const msg = std.fmt.bufPrint(tmp[0..], fmt, args) catch "runtime error";
        self.err = std.fmt.bufPrint(self.err_buf[0..], "{s}", .{msg}) catch "runtime error";
        self.err_obj = .{ .String = try self.internStr(self.err.?) };
        self.err_has_obj = true;
        self.err_cfunc_label = null;
        // PUC luaL_error: no source prefix (luaG_addinfo not called).
        self.err_source = null;
        self.err_line = -1;
        self.captureErrorTraceback();
        try self.invokeErrfunc();
        return error.RuntimeError;
    }

    /// Push a synthetic CallFrame representing a C function (builtin) call.
    /// In PUC Lua, every function call — including C functions — pushes a
    /// `CallInfo` onto `L->ci`. luazig skips this for builtins as a
    /// performance optimization (print/type/tostring are very hot). However,
    /// the error path needs C-frames so `debug.getinfo(N)` level numbers
    /// match PUC when `__tostring` introspects the call stack from within
    /// the message handler.
    ///
    /// The pushed frame has `proto = null` (no bytecode), `current_line = -1`
    /// (C functions have no source line), and is visible to `debug.getinfo`.
    /// PUC `prepCallInfo` for C functions: push a synthetic C-frame with
    /// `proto = null` (CIST_C equivalent). The callee is placed on bc_stack
    /// at `func_slot` (PUC `ci->func`), so `debug.getinfo().func` and GC
    /// marking can derive it from the shared stack — no separate `callee`
    /// field needed.
    fn pushBuiltinCFrame(self: *Vm, callee: Value) std.mem.Allocator.Error!void {
        const th = self.activeBytecodeThread();
        // Place callee on bc_stack (PUC: ci->func points into L->stack).
        const func_slot = self.bc_stack_top;
        // Grow bc_stack + bc_boxed transactionally: realloc bc_boxed first
        // (into a temp), then bc_stack. If bc_stack realloc fails, restore
        // bc_boxed. This avoids divergent sizes between the two arrays.
        if (func_slot + 1 > self.bc_stack.len) {
            const new_cap = @max(func_slot + 1, self.bc_stack.len + (self.bc_stack.len >> 1));
            const new_boxed = try self.alloc.realloc(self.bc_boxed, new_cap);
            const old_boxed = self.bc_boxed;
            errdefer {
                self.bc_boxed = old_boxed;
                _ = self.alloc.realloc(new_boxed, old_boxed.len) catch {};
            }
            self.bc_boxed = new_boxed;
            self.bc_stack = try self.alloc.realloc(self.bc_stack, new_cap);
            @memset(self.bc_stack[func_slot..], .Nil);
            @memset(self.bc_boxed[func_slot..], null);
        }
        self.bc_stack[func_slot] = callee;
        self.bc_stack_top = func_slot + 1;
        // addOne may fail with OOM — rollback bc_stack_top on failure.
        const slot = th.call_frames.addOne(self.alloc) catch |err| {
            self.bc_stack_top = func_slot;
            return err;
        };
        slot.* = .{
            .func_slot = func_slot, // base derived: func_slot + 1
        };
        // P15.78: Mark this as a C function frame (PUC CIST_C). The frame
        // has no proto (no bytecode), so the CIST_C bit is the explicit
        // discriminator — mirroring PUC `prepCallInfo` for C functions.
        slot.setC();
        // P15.79: Hide builtin C-frames from debug.getinfo/debug.traceback.
        // Unlike PUC Lua (where C-frames are visible), luazig pushes C-frames
        // for ALL builtins (pcall, load, etc.), not just C API functions.
        // Making them visible breaks debug.getinfo level numbering: level 1
        // would return the C-frame instead of the calling Lua function.
        // Hiding them preserves the luazig convention that level 1 = the
        // Lua function that called the builtin. The continuation mechanism
        // (finishCcall, poscallCFrame, etc.) uses isC(), not isHidden(), so
        // hiding doesn't affect continuation dispatch.
        slot.setHidden();
    }

    /// Pop the topmost CallFrame (the synthetic C-frame pushed by
    /// `pushBuiltinCFrame`). Called via `defer` after the builtin call
    /// completes. Restores bc_stack_top to the C-frame's func_slot.
    /// P15.83c FIX B: Snapshot TBC values from c_stack into the C-frame's
    /// `clsret_state` field (pcall_error_close mode, CIST_CLSRET NOT set)
    /// before c_stack is freed on yield.
    ///
    /// In PUC Lua, TBC vars live on the shared L->stack and survive across
    /// yields naturally — `luaF_close(L, func, status, 1)` in `finishpcallk`
    /// can access them on resume. In luazig, c_stack is per-C-frame and freed
    /// by `callCFunction`'s errdefer when it returns `error.Yield`. This
    /// function snapshots the TBC Values into `fr.u.c.clsret_state` (a
    /// heap-allocated `CClsretState` in `pcall_error_close` mode, without
    /// setting CIST_CLSRET) so `finishCcall`'s error path can close them
    /// via CIST_CLSRET when the resumed callee errors.
    ///
    /// After snapshotting, `c_toclose_slots` is truncated to `toclose_base`
    /// because the c_stack indices are about to become stale.
    ///
    /// Reuses `clsret_state` (already a `?*CClsretState` = 8 bytes) instead
    /// of adding a new field to CFrameState, keeping CallFrame ≤ 104B.
    /// CIST_CLSRET is NOT set here — it's set later by `finishCcall` when
    /// the resumed callee errors and the TBC values need to be closed.
    fn snapshotYieldedTbc(self: *Vm, cframe_idx: usize) void {
        const fr = self.activeBytecodeThread().call_frames.getPtr(cframe_idx);
        const tbc_base = fr.u.c.toclose_base;
        if (self.c_toclose_slots.items.len <= tbc_base) return; // no TBC vars

        // Collect TBC values in LIFO order (last-marked first), matching
        // PUC's luaF_close which walks L->tbclist in stack order (most
        // recent first via the linked list).
        var tbc_vals: std.ArrayListUnmanaged(Value) = .empty;
        defer tbc_vals.deinit(self.alloc);
        while (self.c_toclose_slots.items.len > tbc_base) {
            const tbc_idx = self.c_toclose_slots.pop().?;
            if (tbc_idx < self.cur_c_stack.items.len) {
                tbc_vals.append(self.alloc, self.cur_c_stack.items[tbc_idx]) catch return;
            }
        }

        // Free any previous snapshot (can happen if k yields again after
        // a previous yield cycle without an intervening error).
        if (fr.u.c.clsret_state) |old| {
            self.alloc.free(old.remaining_tbc);
            self.alloc.free(old.results);
            self.alloc.destroy(old);
        }
        const remaining_copy = self.alloc.dupe(Value, tbc_vals.items) catch return;
        const cs = self.alloc.create(CClsretState) catch {
            self.alloc.free(remaining_copy);
            return;
        };
        cs.* = .{
            .remaining_tbc = remaining_copy,
            .results = &[_]Value{},
            .mode = .pcall_error_close,
            .error_value = null, // set by finishCcall on resume-error
            .error_status = 0,
        };
        fr.u.c.clsret_state = cs;
        // CIST_CLSRET is NOT set — finishCcall detects the snapshot via
        // clsret_state != null && !isClsret() && isYpcall() && recst != 0.
    }

    fn popBuiltinCFrame(self: *Vm) void {
        const th = self.activeBytecodeThread();
        const cur_len = th.call_frames.len();
        if (cur_len > 0) {
            const frame = th.call_frames.getPtr(cur_len - 1);
            // P15.80: Free heap-allocated state before shrinking.
            // Without this, the pointer is lost and the allocation leaks.
            if (frame.isC()) self.freeCFrameOwnedState(frame);
            // P15.83c FIX A: Truncate c_toclose_slots to the popped frame's
            // toclose_base. On normal return, callCFunction already closed
            // and popped all TBC slots before calling popBuiltinCFrame. On
            // error (non-YPCALL), the TBC slots are stale (their c_stack
            // indices point into the freed c_stack) and must be truncated
            // to prevent use-after-free. This mirrors PUC's per-CallInfo
            // TBC scope: when a CallInfo is popped, its TBC vars are gone.
            if (frame.isC()) {
                const tbc_base = frame.u.c.toclose_base;
                if (self.c_toclose_slots.items.len > tbc_base) {
                    self.c_toclose_slots.shrinkRetainingCapacity(tbc_base);
                }
            }
            self.bc_stack_top = frame.func_slot;
            th.call_frames.shrinkTo(cur_len - 1);
        }
    }

    /// PUC `luaG_errormsg` (ldebug.c:840-854): call the message handler
    /// (`errfunc`) BEFORE the call stack is unwound. The handler runs with
    /// `Thread.call_frames` still intact, so `debug.getinfo(N)` works inside
    /// `__tostring` metamethods. The handler's return value replaces the
    /// PUC `luaG_errormsg` (ldebug.c:840-854): call the message handler
    /// (`errfunc`) BEFORE the call stack is unwound. The handler runs with
    /// `Thread.call_frames` still intact, so `debug.getinfo(N)` works inside
    /// `__tostring` metamethods. The handler's return value replaces the
    /// error object. If the handler itself errors, the error becomes
    /// `"error in error handling"` (PUC `LUA_ERRERR`).
    pub fn invokeErrfunc(self: *Vm) !void {
        const th = self.activeBytecodeThread();
        if (th.errfunc != ERRFUNC_NONE) {
            const ef = self.bc_stack[th.errfunc];
            if (th.errfunc_running) return;
            th.errfunc_running = true;
            defer th.errfunc_running = false;
            // Push a synthetic C-frame for the msghandler call. In PUC,
            // `luaG_errormsg` calls the handler via `luaD_callnoyield`, which
            // pushes a `CallInfo` (CIST_C) so `debug.getinfo` counts it as a
            // stack level. Without this frame, `debug.getinfo` level numbers
            // wouldn't match PUC.
            try self.pushBuiltinCFrame(ef);
            defer self.popBuiltinCFrame();
            // Save the error object before calling the handler.
            const err_obj = if (self.err_has_obj) self.err_obj else .Nil;
            var call_args = [_]Value{err_obj};
            const result = self.apiCall(Thread.CCALL_INC_NOYIELD, ef, call_args[0..]) catch {
                // Handler errored — set error to "error in error handling"
                // (PUC LUA_ERRERR). Don't re-invoke the handler.
                // Signal LUA_ERRERR (5) to status-determination sites.
                self.err_is_errerr = true;
                self.err = "error in error handling";
                self.err_obj = .{ .String = self.internStrAssume("error in error handling") };
                self.err_has_obj = true;
                self.err_source = null;
                self.err_line = -1;
                self.clearErrorTraceback();
                return;
            };
            // Handler succeeded — replace the error object with the result.
            if (result.len > 0) {
                self.err_obj = result[0];
                if (result[0] == .String) {
                    self.err = result[0].String.bytes();
                } else {
                    // Non-string result: convert to string via tostring.
                    const str = self.valueToStringAlloc(result[0]) catch {
                        self.err = "(error object is a table value)";
                        self.err_obj = .{ .String = self.internStrAssume("(error object is a table value)") };
                        self.err_has_obj = true;
                        return;
                    };
                    self.err = str;
                    self.err_obj = .{ .String = self.internStrAssume(str) };
                }
            }
            self.err_has_obj = true;
        }
    }

    fn setOutOfMemoryError(self: *Vm) void {
        // Fresh error: reset LUA_ERRERR signal.
        self.err_is_errerr = false;
        self.err = "not enough memory";
        self.err_obj = .{ .String = self.internStrAssume("not enough memory") };
        self.err_has_obj = true;
        if (stdio.activeEnviron().containsConstant("LUAZIG_TRACE_OOM")) {
            if (self.oom_context) |ctx| {
                std.debug.print("luazig oom: {s} array_len={} array_capacity={}\n", .{
                    ctx,
                    self.oom_table_array_len,
                    self.oom_table_array_capacity,
                });
            }
        }
        // Use topLuaFrame() to skip C-frames (which don't have u.lua fields).
        if (self.topLuaFrame()) |fr| {
            // P15.51n: current_line derived from proto.lineinfo[pc].
            self.err_source = fr.sourceName();
            self.err_line = self.frameCurrentLine(fr);
        } else {
            self.err_source = null;
            self.err_line = -1;
        }
        self.captureErrorTraceback();
    }

    /// PUC `luaH_resizearray` (ltable.c:751). Resize only the array part,
    /// keeping the hash part at its current size.
    fn tableResizeArray(self: *Vm, tbl: *Table, new_asize: u32) DispatchError!void {
        try self.tableResize(tbl, new_asize, @intCast(tbl.hash.len));
    }

    /// PUC `luaH_resize` (ltable.c:716). Joint array+hash resize.
    /// 1. Create new hash part (power-of-2 size).
    /// 2. If array shrinks: move vanishing slice keys → new hash.
    /// 3. Allocate new array, copy common elements, nil-fill new slots.
    /// 4. Reinsert old hash entries into new table (array or hash).
    /// 5. Free old parts, swap in new.
    fn tableResize(self: *Vm, tbl: *Table, new_asize: u32, new_hsize: u32) DispatchError!void {
        const old_asize = tbl.asize;

        // 1. Create new hash part (power-of-2, PUC setnodevector).
        //    Always allocate a fresh hash of the requested size, even if the
        //    table already has a hash part — PUC's `setnodevector` does the same.
        var new_hash: []ltable.Node = &[_]ltable.Node{};
        var new_hash_lastfree: usize = 0;
        if (new_hsize > 0) {
            const hsize: usize = if (new_hsize == 1) 1 else std.math.ceilPowerOfTwo(usize, new_hsize) catch new_hsize;
            // PUC `luaM_reallocvector` → `luaM_realloc_` charges both bytes
            // and alloc count. `testcChargeMemory` does both.
            try self.testcChargeMemory(hsize * @sizeOf(ltable.Node));
            new_hash = try self.alloc.alloc(ltable.Node, hsize);
            // PUC luaM_realloc_ adds the new block's bytes to totalbytes.
            // gc_count_kb mirrors totalbytes: charge the new hash part here
            // so gcFreeObject's full-size credit (header + array + hash)
            // stays symmetric. Without this, every freed table with a hash
            // part over-decrements the count (P16.4f bug B).
            self.gcNoteAlloc(hsize * @sizeOf(ltable.Node));
            for (new_hash) |*n| n.* = .{};
            new_hash_lastfree = hsize;
        }

        // 2. If array shrinks, move vanishing slice keys into new_hash.
        //    PUC `reinsertOldSlice`: keys at array indices [new_asize, old_asize)
        //    (0-based) correspond to PUC keys [new_asize+1, old_asize]; they
        //    must be reinserted into the new hash part. We temporarily swap
        //    in `new_hash` so `nodeInsert` operates on the new hash, then
        //    restore the old hash (PUC's `exchangehashpart` pattern keeps the
        //    old hash alive so an allocation failure in step 3 leaves the
        //    table in a recoverable state).
        if (new_asize < old_asize) {
            const saved_hash = tbl.hash;
            const saved_lastfree = tbl.hash_lastfree;
            tbl.hash = new_hash;
            tbl.hash_lastfree = new_hash_lastfree;
            for (new_asize..old_asize) |i| {
                if (tbl.array[i] != .Nil) {
                    // PUC key for array slot i (0-based) is i+1.
                    const key: Value = .{ .Int = @intCast(i + 1) };
                    const val = tbl.array[i];
                    const inserted = ltable.nodeInsert(tbl.hash, &tbl.hash_lastfree, key, val, self.hash_seed);
                    std.debug.assert(inserted != null);
                }
            }
            // Restore old hash (error recovery — PUC exchanges back).
            tbl.hash = saved_hash;
            tbl.hash_lastfree = saved_lastfree;
        }

        // 3. Allocate new array, copy common elements, nil-fill new slots.
        //    PUC `resizearray` + `clearNewSlice`. When the array size doesn't
        //    change, PUC reuses the existing array (no allocation). This is
        //    critical for table constructors: a rehash that only grows the
        //    hash part must not count as an array allocation (testC
        //    `alloccount` expects exactly header + array + hash = 3 allocs).
        const new_array: []Value = if (new_asize == old_asize) blk: {
            // Array size unchanged: reuse existing array (PUC resizearray
            // line 566-567). If growing the hash, the array is already the
            // right size; if shrinking, step 2 already moved vanishing keys
            // to the hash part.
            break :blk tbl.array;
        } else if (new_asize > 0) blk: {
            try self.testcChargeMemory(new_asize * @sizeOf(Value));
            const arr = try self.alloc.alloc(Value, new_asize);
            // Charge the new array part (PUC luaM_realloc_ → totalbytes).
            // See the hash-part charge above for the symmetry argument.
            self.gcNoteAlloc(new_asize * @sizeOf(Value));
            const copy_len = @min(old_asize, new_asize);
            if (copy_len > 0) @memcpy(arr[0..copy_len], tbl.array[0..copy_len]);
            for (arr[copy_len..]) |*slot| slot.* = .Nil;
            break :blk arr;
        } else &[_]Value{};

        // 4. Free old array (only if we allocated a new one), set new array +
        //    asize. PUC does this between `exchangehashpart` and
        //    `reinserthash`: the table now points at the new array, and the
        //    new hash will be swapped in next.
        if (new_asize != old_asize and tbl.array.len != 0) {
            // Credit the replaced array part back (PUC frees the old block
            // through luaM_free_, subtracting from totalbytes).
            self.gcNoteFree(tbl.array.len * @sizeOf(Value));
            self.alloc.free(tbl.array);
        }
        tbl.array = new_array;
        tbl.asize = new_asize;

        // 5. Reinsert old hash entries into new table. PUC `reinserthash`:
        //    walk the old hash part, and for each live entry call
        //    `luaH_newcheckedkey` — which routes integer keys in array range
        //    to the array part, and everything else to `nodeInsert` on the
        //    new hash. We swap `tbl.hash` to the new hash first so inserts
        //    land in the right place; the old hash is iterated via a local.
        const old_hash = tbl.hash;
        tbl.hash = new_hash;
        tbl.hash_lastfree = new_hash_lastfree;
        for (old_hash) |*n| {
            if (n.key_tt == .empty or n.key_tt == .dead) continue;
            if (n.value == .Nil) continue; // skip deleted entries
            const key = n.getKey();
            const val = n.value;
            // newcheckedkey: integer key in array range → array slot.
            if (key == .Int) {
                const k = key.Int;
                if (k >= 1 and @as(u64, @intCast(k)) <= new_asize) {
                    tbl.array[@intCast(k - 1)] = val;
                    continue;
                }
            }
            const inserted = ltable.nodeInsert(tbl.hash, &tbl.hash_lastfree, key, val, self.hash_seed);
            std.debug.assert(inserted != null);
        }

        // Free old hash part (PUC `freehash` on the temporary `newt`).
        if (old_hash.len != 0) {
            // Credit the replaced hash part back (see array credit above).
            self.gcNoteFree(old_hash.len * @sizeOf(ltable.Node));
            self.alloc.free(old_hash);
        }

        // Set lenhint (PUC: `*lenhint(t) = newasize / 2u`).
        tbl.lenhint = new_asize / 2;
    }

    /// PUC `rehash` (ltable.c:762). Count keys, compute optimal array+hash
    /// sizes, then resize. `ek` is the extra key that triggered the rehash
    /// (it may or may not be an array index).
    ///
    /// Algorithm:
    /// 1. Count the extra key (if it's an array-index integer, it may go to
    ///    the array part — `countInt` updates `nums`/`na`).
    /// 2. `numUseHash`: walk the hash part, counting live entries into
    ///    `total`; integer keys are also `countInt`-ed. Deleted entries
    ///    (key present, value nil) set `ct.deleted`.
    /// 3. If any array-index candidates exist (`ct.na > 0`), count the
    ///    array part via `numUseArray` and compute the optimal array size
    ///    via `computeSizes`. Otherwise keep the current array size.
    /// 4. Hash size = total non-array entries (`ct.total - ct.na`). If the
    ///    table has deleted entries, add 25% to avoid repeated resizings.
    /// 5. `tableResize` to the computed sizes.
    fn tableRehash(self: *Vm, tbl: *Table, ek: Value) DispatchError!void {
        if (self.stats.enabled) self.stats.tbl_rehash += 1; // P16.0b
        var ct = ltable.Counters{};
        ct.total = 1; // count the extra key that triggered the rehash
        if (ek == .Int) {
            ltable.countInt(ek.Int, &ct);
        }
        ltable.numUseHash(tbl.hash, &ct);
        var asize: u32 = 0;
        if (ct.na > 0) {
            ltable.numUseArray(tbl.array, &ct);
            asize = ltable.computeSizes(&ct);
        } else {
            asize = tbl.asize; // no new array keys; keep current array size
        }
        var nsize: u32 = ct.total - ct.na;
        if (ct.deleted > 0) {
            nsize += nsize >> 2; // +25% to avoid repeated resizings
        }
        try self.tableResize(tbl, asize, nsize);
    }

    fn protectedErrorString(self: *Vm) []const u8 {
        const base = self.errorString();
        if (self.err_source) |src| {
            if (std.mem.indexOf(u8, base, ":") != null) return base;
            var tmp: [256]u8 = undefined;
            const base_copy = std.fmt.bufPrint(tmp[0..], "{s}", .{base}) catch base;
            // PUC luaG_addinfo (ldebug.c): a NULL source (no debug info —
            // a stripped proto) renders as "?:?: msg". NULL-source in
            // luazig is the empty source_name (dumped stripped chunks);
            // requiring err_line < 1 keeps a real empty chunk name
            // (load(s, ""), which has lines) on the normal path below.
            if ((src.len == 0 or std.mem.eql(u8, src, "=?")) and self.err_line < 1) {
                return std.fmt.bufPrint(self.err_render_buf[0..], "?:?: {s}", .{base_copy}) catch base;
            }
            // PUC luaG_addinfo uses luaO_chunkid to format the source name.
            var id_buf: [59]u8 = undefined;
            const chunk = diag.chunkId(id_buf[0..], src);
            const line = self.err_line;
            if (line >= 1) {
                return std.fmt.bufPrint(self.err_render_buf[0..], "{s}:{d}: {s}", .{ chunk, line, base_copy }) catch base;
            }
            return std.fmt.bufPrint(self.err_render_buf[0..], "{s}:?: {s}", .{ chunk, base_copy }) catch base;
        }
        return base;
    }

    fn activeHookState(self: *Vm) *DebugHookState {
        if (self.current_thread) |th| return &th.debug_hook;
        if (self.main_thread) |th| return &th.debug_hook;
        return &self.debug_hook_main;
    }

    pub fn hookStateFor(self: *Vm, target_thread: ?*Thread) *DebugHookState {
        if (target_thread) |th| return &th.debug_hook;
        if (self.current_thread) |th| return &th.debug_hook;
        if (self.main_thread) |th| return &th.debug_hook;
        return &self.debug_hook_main;
    }

    fn testcChargeMemory(self: *Vm, bytes: usize) DispatchError!void {
        if (bytes == 0) return;
        try self.testcConsumeAllocCount();
        const next = self.testc_total_bytes +| bytes;
        if (self.testc_mem_limit) |limit| {
            if (next > limit) return self.failTestcRaw("not enough memory");
        }
        self.testc_total_bytes = next;
    }

    fn testcConsumeAllocCount(self: *Vm) DispatchError!void {
        const t_global = self.getGlobal("T");
        if (t_global != .Table) return;
        const cur = self.getField(t_global.Table, "_alloccount");
        if (cur == .Nil) return;
        const n = switch (cur) {
            .Int => |i| i,
            .Num => |x| @as(i64, @intFromFloat(x)),
            else => return,
        };
        if (n < 0) return;
        if (n == 0) return self.failTestcRaw("not enough memory");
        try self.setField(t_global.Table, "_alloccount", .{ .Int = n - 1 });
    }

    fn testcNoteMemory(self: *Vm, bytes: usize) void {
        self.testc_total_bytes +|= bytes;
    }

    fn isTestcMemoryErrorValue(v: Value) bool {
        return v == .String and std.mem.indexOf(u8, v.String.bytes(), "not enough memory") != null;
    }

    /// Scoped temporary GC root registration (Handle API).
    ///
    /// Usage:
    ///   var roots = self.gcTempRoots();
    ///   defer roots.end();
    ///   try roots.add(.{ .Table = tbl });
    ///
    /// `add()` pushes a Value onto `gc_temp_roots`; `end()` truncates back to
    /// the snapshot length. GC mark phase traverses all entries in
    /// `gc_temp_roots` (via gcMarkVmRoots), so pushed objects survive sweep.
    /// This is the non-moving-GC analog of PUC Lua's `L->stack[0..top]` —
    /// builtins register their Zig-local temporaries as GC roots.
    const TempRoots = struct {
        vm: *Vm,
        snapshot: usize,

        pub fn add(self: *TempRoots, v: Value) DispatchError!void {
            try self.vm.gc_temp_roots.append(self.vm.alloc, v);
        }

        pub fn end(self: *TempRoots) void {
            self.vm.gc_temp_roots.shrinkRetainingCapacity(self.snapshot);
        }
    };

    fn gcTempRoots(self: *Vm) TempRoots {
        return .{ .vm = self, .snapshot = self.gc_temp_roots.items.len };
    }

    // === FINALIZER REGISTRATION INVARIANT ===
    //
    // FINALIZEDBIT set ⟺ object is in the registered-finalizable lifecycle
    // (PUC `finobj`/`tobefnz` equivalent). The bit is the O(1) semantic
    // membership test (PUC `tofinalize(o)`, lgc.h:96); the `finalizables`
    // HashSet is the iterable container (insert at registration, remove at
    // dequeue). They MUST agree at every boundary:
    //
    //   registerFinalizable(obj):  set bit  ⟺  set.insert(obj)
    //   takeFinalizable(obj):      clear bit ⟺  set.remove(obj)
    //
    // Registration is PERSISTENT (PUC luaC_checkfinalizer, lgc.c:1068-1090):
    // changing or removing the metatable NEVER deregisters. The __gc
    // metamethod is resolved DYNAMICALLY at finalization time (PUC GCTM,
    // lgc.c:968, calls luaT_gettmbyobj on the CURRENT metatable).
    // lua_setmetatable(nil) does not call checkfinalizer at all (lapi.c:964).
    //
    // Dequeue (takeFinalizable) clears the bit BEFORE resolving __gc (PUC
    // udata2finalize, lgc.c:947-960, resets FINALIZEDBIT before GCTM looks
    // up the metamethod). If the current metatable is nil or has no __gc,
    // no callback fires, but the object is "normal" again and will be
    // collected on the next cycle.

    /// Register an object (table or userdata) for finalization.
    /// PUC `luaC_checkfinalizer` (lgc.c:1068-1090): moves the object from
    /// `allgc` to `finobj` and sets FINALIZEDBIT. We use a HashSet
    /// (`finalizables`) as the non-intrusive equivalent of `finobj`, and set
    /// FINALIZEDBIT on the object's `marked` byte as PUC does — the bit is the
    /// fast-check for "is this object registered for finalization?" (PUC
    /// `tofinalize(o)`, lgc.h:96), used by the sweep and weak-key pruning to
    /// avoid a HashMap lookup on every object.
    /// During the atomic phase, white (unreachable) objects in this set are
    /// queued for __gc finalization.
    pub fn registerFinalizable(self: *Vm, obj: GcObject) std.mem.Allocator.Error!void {
        // PUC GCSTPCLS: when the state is closing (lua_close →
        // luaC_freeallobjects sets g->gcstp = GCSTPCLS), `luaC_checkfinalizer`
        // returns early via `gcstopp(g)` — new objects are NOT queued for
        // finalization. This prevents objects created during the close
        // sequence (e.g. inside a __gc finalizer) from having their own
        // finalizers called (main.lua:324-326: object 3 created during
        // object 2's finalizer must NOT be finalized).
        if (self.is_closing) return;
        // PUC luaC_checkfinalizer (lgc.c:1072): `if (tofinalize(o) || ...) return;`
        // The bit test IS the PUC `tofinalize(o)` check — if already
        // registered, keep the registration untouched (PUC returns early).
        if ((gcPtr(obj).marked.* & FINALIZEDBIT) != 0) return;
        try self.finalizables.put(self.alloc, obj, {});
        // PUC luaC_checkfinalizer (lgc.c:1088): l_setbit(o->marked, FINALIZEDBIT)
        gcPtr(obj).marked.* |= FINALIZEDBIT;
        self.gc_finalizer_epoch +%= 1;
        // Do NOT set gc_finalizer_tick_pending here. In PUC Lua, registering
        // a finalizer does not force the next GC step to run; the finalizer
        // will run when the object is collected. Setting the tick flag here
        // causes spurious automatic minor collections that promote young
        // objects' ages prematurely, breaking gengc.lua age assertions.
    }

    /// PUC `udata2finalize` (lgc.c:947-960): atomic semantic transition that
    /// dequeues a finalizable object for finalization. Removes from the
    /// `finalizables` set (our finobj/tobefnz equivalent) and clears
    /// FINALIZEDBIT — the object is "normal" again. Called BEFORE resolving
    /// the current __gc metamethod (PUC GCTM does the lookup AFTER
    /// udata2finalize returns). If the current metatable is nil or has no
    /// __gc, no callback fires, but the bit is already cleared so the object
    /// will be collected on the next cycle.
    ///
    /// ARCHITECTURE NOTE: luazig runs finalizers during the atomic phase
    /// (BEFORE sweep), while PUC runs them AFTER sweep. To prevent the
    /// sweep from freeing the just-finalized object in the current cycle
    /// (PUC's sweep has already passed when finalizers run), we call
    /// `gcMakeWhite` to set the object to the current white — making it
    /// "not dead" for this sweep. This mirrors PUC's `makewhite(g, o)` in
    /// `udata2finalize` when `issweepphase(g)` is true. The object is
    /// collected on the NEXT cycle if still unreachable.
    fn takeFinalizable(self: *Vm, obj: GcObject) void {
        _ = self.finalizables.remove(obj);
        gcPtr(obj).marked.* &= ~FINALIZEDBIT;
        // PUC udata2finalize (lgc.c:953-955): resetbit + makewhite-if-sweep.
        // In PUC, finalizers run AFTER sweep (callfin phase), so
        // issweepphase(g) is true and makewhite is called to make the
        // object white for the NEXT cycle's sweep.
        // In luazig, finalizers run DURING atomic (BEFORE sweep). The
        // object was marked BLACK in atomic Step 10 (gcMarkValue on each
        // to-finalize object). We must NOT call gcMakeWhite here: the
        // white flip happens after atomic (line ~20868), so gcMakeWhite
        // would set the object to the PRE-flip white, which becomes the
        // "other" (dead) white after the flip — causing the sweep to free
        // it in the SAME cycle (breaking the two-cycle finalization
        // contract). Instead, leave the object BLACK: gcIsDead returns
        // false for black objects, so it survives the sweep. The sweep's
        // own gcMakeWhite (gcSweepOne line ~21422) then resets it to the
        // new current white for the next cycle.
    }

    /// PUC luaC_condGC pacing: decrement GC debt at Lua-object allocation
    /// sites, and update the approximate memory counter for pacing.
    /// The tracker handles exact byte counting (total_bytes) for
    /// `collectgarbage("count")`; this function controls WHEN the GC
    /// check triggers and maintains the approximate counter used for
    /// threshold calculations.
    pub inline fn gcNoteAlloc(self: *Vm, bytes: usize) void {
        const kb: f64 = @as(f64, @floatFromInt(bytes)) / 1024.0;
        self.gc_count_kb += kb;
        self.gc_step_debt_kb -= kb;
        if (self.stats.enabled) self.stats.alloc_bytes_total += bytes; // P16.0b
    }
    /// an object. The tracker's total_bytes is updated automatically by
    /// the allocator's free callback.
    /// Decrement testc_total_bytes and approximate gc_count_kb when GC frees
    /// an object. The tracker's total_bytes is updated automatically by
    /// the allocator's free callback.
    inline fn gcNoteFree(self: *Vm, bytes: usize) void {
        const kb: f64 = @as(f64, @floatFromInt(bytes)) / 1024.0;
        self.gc_count_kb = @max(0, self.gc_count_kb - kb);
        self.testc_total_bytes -|= bytes;
    }

    // --- Native tree memory accounting (Task 7) ---
    //
    // Proto trees are native allocations (not GC objects). Their footprint
    // is charged to `gc_count_kb` at adoption (first closure creation)
    // and credited at last release, so `collectgarbage("count")` coherently
    // reflects tree memory while closures are retained.
    //
    // Unlike `gcNoteAlloc`/`gcNoteFree`, these do NOT touch
    // `testc_total_bytes` — tree memory is not tracked by the testc
    // allocator (which tracks only GC objects via `testcChargeMemory`).
    // Only the approximate `gc_count_kb` (which `collectgarbage("count")`
    // reads) is updated.

    pub fn gcChargeTreeMemory(self: *Vm, bytes: usize) void {
        const kb: f64 = @as(f64, @floatFromInt(bytes)) / 1024.0;
        self.gc_count_kb += kb;
        self.gc_step_debt_kb -= kb;
    }

    pub fn gcCreditTreeMemory(self: *Vm, bytes: usize) void {
        const kb: f64 = @as(f64, @floatFromInt(bytes)) / 1024.0;
        self.gc_count_kb = @max(0, self.gc_count_kb - kb);
    }

    /// Register a Table in the unified GC list. Thin wrapper for call-site
    /// type safety; delegates to the generic `gcRegisterObject`.
    fn gcRegisterTable(self: *Vm, table: *Table) std.mem.Allocator.Error!void {
        try self.gcRegisterObject(.{ .table = table });
    }

    /// Register a Closure in the unified GC list.
    ///
    /// Public so the C-ABI shim (`c_api.zig`) can register C closures created
    /// by `luaL_setfuncs` / `lua_pushcfunction`. Mirrors PUC's `luaC_newclosure`
    /// linking a new GC object into `g->allgc`.
    pub fn gcRegisterClosure(self: *Vm, closure: *Closure) std.mem.Allocator.Error!void {
        try self.gcRegisterObject(.{ .closure = closure });
    }

    /// Register a Thread in the unified GC list.
    pub fn gcRegisterThread(self: *Vm, thread: *Thread) std.mem.Allocator.Error!void {
        try self.gcRegisterObject(.{ .thread = thread });
    }

    /// Register a Cell in the unified GC list.
    pub fn gcRegisterCell(self: *Vm, cell: *Cell) std.mem.Allocator.Error!void {
        try self.gcRegisterObject(.{ .cell = cell });
    }

    /// Register a LuaString in the unified GC list.
    fn gcRegisterString(self: *Vm, string: *LuaString) std.mem.Allocator.Error!void {
        try self.gcRegisterObject(.{ .string = string });
    }

    /// Generic GC registration for any GcObject. Appends to both
    /// `gc_objects` (the unified list) and `gc_young_objects` (if in
    /// generational minor mode). Sets gc_marked to current white and
    /// gc_age to .new (if generational).
    ///
    /// PUC lgc.c:301: new objects get the current white bit.
    /// `gc_index` is the object's position in `gc_objects`, used by
    /// `gcUnregisterObject` for O(1) `swapRemove`.
    fn gcRegisterObject(self: *Vm, obj: GcObject) std.mem.Allocator.Error!void {
        // P16.0b: per-type allocation counts. GcObject is a tagged union,
        // so @intFromEnum yields the active tag (declaration order: table,
        // closure, thread, string, cell, userdata — matches alloc_by_type).
        if (self.stats.enabled) self.stats.alloc_by_type[@intFromEnum(obj)] += 1;
        try self.gc_objects.ensureUnusedCapacity(self.alloc, 1);
        if (self.gc_mode == .generational and self.gc_gen_phase == .minor)
            try self.gc_young_objects.ensureUnusedCapacity(self.alloc, 1);
        const p = gcPtr(obj);
        p.marked.* = self.gc_current_white & WHITEBITS;
        // P16.16 C1: gc_index is u32 — the list can never exceed 4G entries
        // (each entry is 16B, so 4G entries = 64GB of list alone).
        std.debug.assert(self.gc_objects.items.len <= std.math.maxInt(u32));
        p.index.* = @intCast(self.gc_objects.items.len);
        // Creation sequence: only the finalizable types (Table/Userdata)
        // carry one — it exists solely for the finalizer LIFO sort, which
        // never sees another type (see gcFinalizableSeq).
        switch (obj) {
            .table, .userdata => {
                gcFinalizableSeqPtr(obj).?.* = self.gc_creation_seq;
                self.gc_creation_seq += 1;
            },
            else => {},
        }
        self.gc_objects.appendAssumeCapacity(obj);
        if (self.gc_mode == .generational and self.gc_gen_phase == .minor) {
            p.age.* = .new;
            self.gc_young_objects.appendAssumeCapacity(obj);
        }
    }

    /// Generic GC unregistration. swapRemoves from gc_objects using the
    /// object's `gc_index` field for O(1) lookup. Does NOT remove from
    /// gc_young_objects (filtered during sweep via snapshot/write-pointer).
    ///
    /// PUC lgc.c `sweepstep` unlinks from `allgc`; our `swapRemove` is the
    /// equivalent, with the swapped object's `gc_index` updated to maintain
    /// the position invariant.
    fn gcUnregisterObject(self: *Vm, obj: GcObject) void {
        const p = gcPtr(obj);
        const index = p.index.*;
        std.debug.assert(index < self.gc_objects.items.len and
            std.meta.eql(self.gc_objects.items[index], obj));
        _ = self.gc_objects.swapRemove(index);
        if (index < self.gc_objects.items.len) {
            const swapped = self.gc_objects.items[index];
            gcPtr(swapped).index.* = index;
        }
    }

    fn allocTableNoGc(self: *Vm) std.mem.Allocator.Error!*Table {
        self.testcNoteMemory(@sizeOf(Table) + 64);
        const t = try self.alloc.create(Table);
        t.* = .{};
        try self.gcRegisterTable(t);
        self.gcNoteAlloc(@sizeOf(Table));
        self.testc_obj_tables += 1;
        return t;
    }

    /// Sync the top frame's pc from the dispatch loop's
    /// local state before GC runs. The fast dispatch path (P15.33) defers
    /// per-instruction RuntimeFrame sync to safepoints. Any code path that
    /// triggers GC from within the dispatch loop (allocTable, callBuiltin,
    /// etc.) must call this so that gcMarkMutableRoots and
    /// gcClearDeadFrameRegisters see the correct pc and live_reg_top.
    fn syncTopFrameForGc(self: *Vm) void {
        // Sync dispatch_pc to the frame so gcMarkMutableRoots reads the
        // correct live_reg_top[pc]. dispatch_pc is written every instruction
        // in the inner dispatch loop.
        // Use topLuaFrame() to skip C-frames (which don't have u.lua.pc).
        if (self.topLuaFrame()) |fr| {
            fr.u.lua.pc = self.dispatch_pc;
        }
    }

    /// PUC `checkGC(L,c)` analogue: conditionally run a GC step after an
    /// allocation site. Called from OP_CONCAT, OP_CLOSURE, and string
    /// allocation paths — the same points where PUC invokes `luaC_condGC`.
    /// `ctx` provides the current dispatch state (pc, reg_top, etc.) so the
    /// heap CallFrame is synced before GC scans live registers.
    ///
    /// Unlike the per-instruction GC tick (which checks every instruction),
    /// this is only called at allocation sites, matching PUC's model where
    /// `luaC_condGC` appears in `checkGC(L,c)` at NEWTABLE/CONCAT/CLOSURE and
    /// in `luaC_checkGC` inside string/table allocators.
    fn condGcFromDispatch(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!void {
        if (!self.gc_running or self.gc_busy) return;
        // PUC luaC_condGC: if GCdebt <= 0, run a step. gc_step_debt_kb is
        // decremented by gcNoteAlloc on every allocation (PUC: GCdebt
        // decreases as bytes are allocated via luaM_*).
        if (self.gc_step_debt_kb > 0 and !self.gc_finalizer_tick_pending and !self.gcAutoCycleDue()) return;
        // Safepoint: sync dispatch state to the heap CallFrame so
        // gcMarkMutableRoots sees correct pc/reg_top for live_reg_top.
        const fr = ctx.exec_frames.getPtr(ctx.frame_index);
        fr.u.lua.pc = ctx.pc;
        // reg_top is read directly from the CallFrame (P15.51l).
        try self.gcAutomaticStep();
        // bc_stack may have been realloc'd by GC finalizers.
        ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
    }

    fn allocTable(self: *Vm) DispatchError!*Table {
        try self.testcConsumeAllocCount();
        const t = try self.allocTableNoGc();
        self.gc_alloc_tables += 1;
        self.gc_last_table_inst = self.gc_inst;

        // PUC luaC_condGC: if GCdebt <= 0, run a step. gc_step_debt_kb is
        // decremented by gcNoteAlloc on every allocation.
        if (self.gc_running and !self.gc_busy and
            (self.gc_step_debt_kb <= 0 or self.gc_finalizer_tick_pending or self.gcAutoCycleDue()))
        {
            self.gc_alloc_tables = 0;
            // Protect the just-allocated table: it is registered but has
            // not yet been returned to the caller and therefore is not in
            // a Lua root. This is the non-moving equivalent of keeping it
            // on L's stack while the collector runs.
            var roots = self.gcTempRoots();
            defer roots.end();
            try roots.add(.{ .Table = t });
            // Sync frame.u.lua.pc from dispatch_pc so gcMarkMutableRoots reads the
            // correct live_reg_top[pc]. dispatch_pc is updated every
            // instruction in the dispatch loop (line: self.dispatch_pc = ctx.pc).
            self.syncTopFrameForGc();
            try self.gcAutomaticStep();
        }
        return t;
    }

    fn allocTableEphemeral(self: *Vm) std.mem.Allocator.Error!*Table {
        const t = try self.alloc.create(Table);
        t.* = .{};
        try self.gcRegisterTable(t);
        return t;
    }

    /// Allocate a new full userdata (PUC `luaS_newudata` / `lua_newuserdatauv`).
    /// `size` is the binary payload size; `nuvalue` is the number of user values.
    /// All payload bytes are zero-filled; all uservalues are Nil.
    ///
    /// PUC `luaS_newudata` (lstring.c) allocates `Udata + nuvalue * UValue +
    /// size` contiguously. Our `Userdata` struct keeps the uservalues and
    /// payload as separate slices (idiomatic Zig, see the struct doc comment),
    /// but the accounting is identical: `gcNoteAlloc` is charged the same total
    /// and `gcFreeObject` frees both slices.
    pub fn allocUserdata(self: *Vm, size: usize, nuvalue: usize) DispatchError!*Userdata {
        const total = @sizeOf(Userdata) + nuvalue * @sizeOf(Value) + size;
        try self.testcChargeMemory(total);
        const ud = try self.alloc.create(Userdata);
        ud.* = .{
            .uservalues = if (nuvalue > 0) try self.alloc.alloc(Value, nuvalue) else &.{},
            .payload = if (size > 0) try self.alloc.alloc(u8, size) else &.{},
        };
        @memset(ud.payload, 0);
        for (ud.uservalues) |*uv| uv.* = .Nil;
        try self.gcRegisterObject(.{ .userdata = ud });
        self.testc_obj_userdata += 1;
        self.gcNoteAlloc(total);
        return ud;
    }

    // -----------------------------------------------------------------------
    // Bytecode VM dispatch loop
    // -----------------------------------------------------------------------
    //
    // Executes PUC-style bytecode (bc.Proto) with runtime top tracking for GC.
    // Reuses the same Value-level helpers as the IR VM (indexValue, evalBinOp,
    // resolveCallable, etc.). The dispatch loop decodes 32-bit instructions
    // and switches on the opcode.

    /// Resolve a proto's constants to VM-canonical form. TREE-WIDE and
    /// idempotent: the readiness flag lives on the tree owner, so the first
    /// execution of ANY proto of a tree adopts the whole tree (constants
    /// VM-interned, `resolved_values` built everywhere). Called from
    /// `pushBytecodeExecFrame` and the OP_TAILCALL frame-reuse path.
    inline fn resolveProtoConstants(self: *Vm, proto: *bc.Proto) DispatchError!void {
        const owner = proto.tree orelse return; // owner-less: unit-test protos
        if (owner.flags.constants_resolved) return;
        try self.resolveTreeConstants(owner);
    }

    /// Tree-wide constant resolution (P16.10b Task 9). Two-phase so that a
    /// partial failure NEVER leaves the tree mutated — fixing the latent
    /// re-resolution bug where `intern` failed AFTER in-place destroys and
    /// a retry destroyed already-VM-owned strings:
    ///
    ///   Phase 1 (fallible, no mutation): for every proto of the tree,
    ///   allocate the `resolved_values` array and intern every `.str`
    ///   constant into the VM's string table, staging the interned pointers
    ///   inside the fresh array. An OOM here frees the staged arrays and
    ///   returns; the tree is byte-identical to before, so a retry is safe.
    ///
    ///   Phase 2 (infallible): publish — store each `resolved_values`,
    ///   swap the k pool's `.str` pointers to the staged VM strings,
    ///   destroy the old seed-0 strings (text trees only; undumped trees
    ///   are VM-owned from birth — `flags.k_strings_vm_owned`), flip the owner
    ///   flags. Frees and stores cannot fail.
    /// Staging record for tree-wide constant resolution (see
    /// resolveTreeConstants): the fresh resolved_values array for one proto,
    /// with string constants staged as VM-interned pointers.
    const ResolveStage = struct { proto: *bc.Proto, vals: []Value };

    fn resolveTreeConstants(self: *Vm, owner: *bc.Proto) DispatchError!void {
        // CUT1: for undumped trees (flags.k_strings_vm_owned==true from birth),
        // the k strings are already VM-interned at deserialization time.
        // Alias resolved_values onto the SAME allocation as k via in-place
        // Constant→Value conversion (both 16B, align 8; .int→.Int,
        // .num_bits→.Num, .str→.String are value-preserving rewrites).
        // After conversion, k.len==0 and resolved_values is the single
        // constant array — matching PUC Lua where Proto.k IS the runtime
        // TValue array. This eliminates the dual Constant[]+Value[] storage
        // for undumped trees (compiled trees still need both: k holds
        // compile-time Constant that must survive for source/debug info).
        if (owner.flags.k_strings_vm_owned) {
            aliasUndumpConstantsTree(owner);
            owner.flags.constants_resolved = true;
            return;
        }
        // Compiled tree: two-phase resolution (allocates resolved_values,
        // swaps k string pointers to VM-interned, destroys old seed-0 strings).
        var built: std.ArrayListUnmanaged(ResolveStage) = .empty;
        defer {
            // On error: free every staged array. On success the arrays were
            // published to the protos and `built` was drained — nothing to
            // free but the list storage itself.
            for (built.items) |b| {
                if (b.vals.len > 0) self.alloc.free(b.vals);
            }
            built.deinit(self.alloc);
        }
        // Phase 1. The walk is recursive over the tree, staging interned
        // pointers in Value form (this mirrors PUC Lua, whose compiler
        // interns constants through the same string table as the runtime
        // and stores them in runtime TValue format from birth).
        try self.stageResolveTree(owner, &built);
        // Phase 2: publish (infallible).
        for (built.items) |b| {
            b.proto.resolved_values = b.vals;
            for (b.proto.k, 0..) |*c, i| {
                if (c.* == .str) {
                    const new = b.vals[i].String;
                    if (!owner.flags.k_strings_vm_owned) {
                        // Destroy the compile-time LuaString (seed-0). The
                        // VM-interned version is now the canonical pointer.
                        // Seed strings were created by the compiler with the
                        // VM's allocator (same family in production; possibly
                        // a test arena otherwise — arena free is a no-op).
                        // CUT2: allocator no longer stored in Proto; use
                        // self.alloc (the tree's creating allocator in
                        // production, same family in tests).
                        destroyLuaString(self.alloc, c.str);
                    }
                    c.str = new;
                }
            }
        }
        owner.flags.k_strings_vm_owned = true;
        owner.flags.constants_resolved = true;
        // Ownership of the staged arrays moved to the protos — drain the
        // list so the defer above does not free them.
        built.clearRetainingCapacity();
    }

    fn stageResolveTree(
        self: *Vm,
        proto: *bc.Proto,
        built: *std.ArrayListUnmanaged(ResolveStage),
    ) DispatchError!void {
        const vals = try self.alloc.alloc(Value, proto.k.len);
        errdefer if (vals.len > 0) self.alloc.free(vals);
        for (proto.k, 0..) |c, i| {
            vals[i] = switch (c) {
                .nil => .Nil,
                .bool => |b| .{ .Bool = b },
                .int => |i64_val| .{ .Int = i64_val },
                .num_bits => |n| .{ .Num = @bitCast(n) },
                .str => |s| .{ .String = try self.internStrAll(s.bytes()) },
            };
        }
        try built.append(self.alloc, .{ .proto = proto, .vals = vals });
        for (proto.p) |child| {
            try self.stageResolveTree(@constCast(child), built);
        }
    }

    /// CUT1: alias resolved_values onto the k allocation for undumped trees.
    /// Converts each Constant slot in-place to its Value equivalent (both are
    /// 16B, align 8). The .str pointers are already VM-interned at undump
    /// time (flags.k_strings_vm_owned==true), so .str→.String is a pointer-preserving
    /// rewrite. After conversion, k.len==0 (signaling aliased) and
    /// resolved_values is the single constant array. Recursive over the tree.
    /// Infallible: no allocation, no interning — pure in-place rewrites.
    fn aliasUndumpConstantsTree(proto: *bc.Proto) void {
        const k = proto.k;
        if (k.len > 0) {
            // In-place Constant→Value conversion. Both types are 16B with
            // alignment 8, so the allocation is reinterpret-safe.
            const vals: [*]Value = @ptrCast(@alignCast(k.ptr));
            for (k, 0..) |c, i| {
                vals[i] = switch (c) {
                    .nil => .Nil,
                    .bool => |b| .{ .Bool = b },
                    .int => |v| .{ .Int = v },
                    .num_bits => |n| .{ .Num = @bitCast(n) },
                    .str => |s| .{ .String = s },
                };
            }
            proto.resolved_values = vals[0..k.len];
            // k.len=0 signals aliased; the ptr stays (for alloc.free via
            // resolved_values). destroyProtoTree detects k_aliased and
            // frees the single allocation via resolved_values.
            proto.k = k[0..0];
        }
        for (proto.p) |child| aliasUndumpConstantsTree(@constCast(child));
    }

    fn takeBytecodeResumeValues(th: *Thread, alloc: std.mem.Allocator) ?[]Value {
        // P16.3: move the inbox contents out. Inline contents are duped to a
        // heap slice (the caller owns and frees it); heap spills are adopted
        // as-is. The inbox is emptied either way.
        const cur = th.resume_inbox.slice() orelse return null;
        if (th.resume_inbox.heap) |h| {
            const out = h[0..th.resume_inbox.len];
            th.resume_inbox.heap = null;
            th.resume_inbox.len = 0;
            return out;
        }
        const out = alloc.dupe(Value, cur) catch return null;
        th.resume_inbox.len = 0;
        return out;
    }

    noinline fn dispatchBytecodeHook(
        self: *Vm,
        event: []const u8,
        line: ?i64,
        transfer: ?[]const Value,
    ) DispatchError!void {
        // Line/count/return events reference the topmost visible frame
        // (PUC luaD_hook's `ar.i_ci = L->ci`).
        try self.debugDispatchHookTransfer(event, line, transfer, 1, null);
    }

    noinline fn dispatchBytecodeHookWithCallee(
        self: *Vm,
        event: []const u8,
        callee: Value,
        transfer: ?[]const Value,
    ) DispatchError!void {
        try self.debugDispatchHookWithCalleeTransfer(event, null, callee, transfer, 1, null);
    }

    /// Fire the CALL hook for a Lua activation that has just been pushed
    /// onto `exec_frames` — PUC's luaD_hookcall ordering (ldo.c:476,
    /// ldebug.c:918 luaG_tracecall): the callee's CallInfo exists FIRST,
    /// then the hook fires with ar.i_ci referencing the callee frame.
    /// Used by every site that pushes a bytecode frame as a function call:
    /// OP_CALL, entry chunks (runBytecodeInternal), pcall'd bodies,
    /// metamethod activations, and for-in iterators.
    ///
    /// `callee` is the closure being called; `nargs` the actual argument
    /// count (PUC passes ntransfer = p->numparams to luaD_hook — the fixed
    /// parameters are what the 'r' (transfer) flag exposes; we slice the
    /// fixed params from the just-built frame registers).
    fn dispatchCalleeActivationHook(
        self: *Vm,
        exec_frames: *FrameStack,
        callee: Value,
        nargs: usize,
    ) DispatchError!void {
        // Same guards as the dispatch fast path (PUC checks hookmask and
        // allowhook in luaD_hook; luaG_tracecall additionally checks that
        // hooks are enabled for the event).
        if (!self.hooks_active_cached) return;
        if (self.debug_hooks_suppressed != 0) return;
        if (self.isInDebugHook()) return;
        const hook_state = self.activeHookState();
        if (!hook_state.has_call) return;

        const frame_idx = exec_frames.len() - 1;
        const fr = exec_frames.getConstPtr(frame_idx);
        // PUC luaD_hookcall (ldo.c:476): `ci->u.l.savedpc++; luaD_hook(...);
        // ci->u.l.savedpc--;` — the hook observes the pc of the instruction
        // AFTER the first one. For a vararg function the first instruction
        // is OP_VARARGPREP (lvm.c:1958 fires luaD_hookcall right after it
        // adjusts the varargs), so getinfo('l') must report the line of
        // instruction 1, not 0. Mirror the temporary bump by index (the
        // frame array may realloc while the hook runs).
        const vararg_bump = if (fr.proto()) |p| p.flags.is_vararg else false;
        if (vararg_bump) exec_frames.getPtr(frame_idx).u.lua.pc = 1;
        defer {
            if (vararg_bump) exec_frames.getPtr(frame_idx).u.lua.pc = 0;
        }
        // PUC luaD_hookcall: ftransfer=1, ntransfer=p->numparams. The fixed
        // parameters sit contiguously at the frame base for both VAHID and
        // non-VAHID frames (buildhiddenargs copies them there).
        const nparams: usize = if (fr.proto()) |p| p.numparams else 0;
        const n_transfer = @min(nargs, nparams);
        const transfer = self.bc_stack[fr.frameBase() .. fr.frameBase() + n_transfer];
        try self.debugDispatchHookWithCalleeTransfer(
            "call",
            null,
            callee,
            transfer,
            1,
            frame_idx,
        );
    }

    /// Fire the CALL hook for a C-function activation whose CallFrame has
    /// just been pushed (PUC ldo.c:642-656 precallC): the C CallInfo is
    /// created FIRST (prepCallInfo ... | CIST_C), then
    /// `luaD_hook(L, LUA_HOOKCALL, -1, 1, narg)` fires with ar.i_ci = that
    /// frame. Differences from the Lua-callee helper above, all mirroring
    /// precallC vs luaD_hookcall:
    ///   - ntransfer is the ACTUAL argument count narg (precallC), not the
    ///     fixed numparams (luaD_hookcall);
    ///   - no savedpc bump — C frames have no bytecode pc;
    ///   - the event is always plain "call": PUC routes tail calls to C
    ///     through luaD_pretailcall → precallC, which pushes a FRESH ci
    ///     without CIST_TAIL (never a "tail call" event).
    ///
    /// `cframe_idx` is the just-pushed C-frame's index in call_frames;
    /// `args` the callee's arguments (the transfer values, ftransfer=1).
    fn dispatchCCalleeActivationHook(
        self: *Vm,
        cframe_idx: usize,
        callee: Value,
        args: []const Value,
    ) DispatchError!void {
        // Same guards as the dispatch fast path (PUC checks hookmask and
        // allowhook in luaD_hook before doing any work).
        if (!self.hooks_active_cached) return;
        if (self.debug_hooks_suppressed != 0) return;
        if (self.isInDebugHook()) return;
        const hook_state = self.activeHookState();
        if (!hook_state.has_call) return;
        try self.debugDispatchHookWithCalleeTransfer(
            "call",
            null,
            callee,
            args,
            1,
            cframe_idx,
        );
    }

    fn saveBytecodeProtectedError(self: *Vm) BytecodeSavedError {
        const th = self.activeBytecodeThread();
        var saved: BytecodeSavedError = .{
            .err_present = self.err != null,
            .err_len = 0,
            .err_bytes = undefined,
            .err_obj = self.err_obj,
            .err_has_obj = self.err_has_obj,
            .err_source = self.err_source,
            .err_line = self.err_line,
            .err_traceback = self.err_traceback,
            .errfunc = th.errfunc,
        };
        if (self.err) |msg| {
            const len = @min(msg.len, saved.err_bytes.len);
            @memcpy(saved.err_bytes[0..len], msg[0..len]);
            saved.err_len = @intCast(len);
        }
        // The protected child owns any traceback it creates.  The caller's
        // traceback pointer stays parked in the continuation until completion.
        self.err_traceback = null;
        // PUC luaD_pcall: clear errfunc for the protected child — pcall
        // has no message handler. xpcall sets its own handler separately.
        th.errfunc = ERRFUNC_NONE;
        return saved;
    }

    fn restoreBytecodeSavedError(self: *Vm, saved: BytecodeSavedError) void {
        const th = self.activeBytecodeThread();
        self.clearErrorTraceback();
        if (saved.err_present) {
            const len: usize = saved.err_len;
            @memcpy(self.err_buf[0..len], saved.err_bytes[0..len]);
            self.err = self.err_buf[0..len];
        } else {
            self.err = null;
        }
        self.err_obj = saved.err_obj;
        self.err_has_obj = saved.err_has_obj;
        self.err_source = saved.err_source;
        self.err_line = saved.err_line;
        self.err_traceback = saved.err_traceback;
        th.errfunc = saved.errfunc;
    }

    fn discardBytecodeSavedError(self: *Vm, saved: BytecodeSavedError) void {
        if (saved.err_traceback) |traceback| self.alloc.free(traceback);
    }

    fn releaseBytecodeProtectedDepth(self: *Vm, protection: *BytecodeProtectedCall) void {
        _ = self;
        std.debug.assert(protection.thread.bytecode_protected_depth != 0);
        protection.thread.bytecode_protected_depth -= 1;
        if (protection.phase == .handler) {
            std.debug.assert(protection.thread.bytecode_error_handler_depth != 0);
            protection.thread.bytecode_error_handler_depth -= 1;
        }
    }

    fn releaseBytecodeProtectedLayer(self: *Vm, layer: BytecodeProtectedLayer) void {
        _ = self;
        std.debug.assert(layer.thread.bytecode_protected_depth != 0);
        layer.thread.bytecode_protected_depth -= 1;
    }

    fn finishBytecodeProtectedCall(self: *Vm, protection: *BytecodeProtectedCall) void {
        // P16.23 T6: restore the C-call depth to the protection's entry
        // snapshot. On SUCCESS this is a no-op (paired ccall exits already
        // returned to the entry depth); on a CAUGHT error the iterative
        // unwind popped frames without running their paired exits, so this
        // is where the leaked increments are reclaimed (PUC gets this for
        // free from the C-stack unwind). Parked frames above a YIELDED
        // protection never reach here — their live increments persist.
        protection.thread.nCcalls = protection.saved_ncalls;
        self.restoreBytecodeSavedError(protection.saved_error);
        self.releaseBytecodeProtectedDepth(protection);
        var i = protection.outer_layers.len;
        while (i > 0) {
            i -= 1;
            const layer = protection.outer_layers[i];
            self.restoreBytecodeSavedError(layer.saved_error);
            self.releaseBytecodeProtectedLayer(layer);
        }
        if (protection.outer_layers.len != 0) self.alloc.free(protection.outer_layers);
        // PUC ldo.c:luaD_pcall calls luaD_shrinkstack after the protected
        // call completes (success or error). This shrinks bc_stack back
        // to normal size if it was grown during a stack overflow.
        self.shrinkBcStack();
    }

    /// Drop a protected continuation because its caller itself is being
    /// unwound or collected.  Unlike normal completion, the current error is
    /// authoritative and must not be overwritten with the parked caller error.
    fn discardBytecodeProtectedCall(self: *Vm, protection: *BytecodeProtectedCall) void {
        self.discardBytecodeSavedError(protection.saved_error);
        self.releaseBytecodeProtectedDepth(protection);
        for (protection.outer_layers) |layer| {
            self.discardBytecodeSavedError(layer.saved_error);
            self.releaseBytecodeProtectedLayer(layer);
        }
        if (protection.outer_layers.len != 0) self.alloc.free(protection.outer_layers);
    }

    fn freeBytecodeHookPost(self: *Vm, post: BytecodeHookPost) void {
        switch (post) {
            .store_results => |state| self.alloc.free(state.values),
            .return_frame => |values| if (!self.returnSliceIsOwned(values)) self.alloc.free(values),
            else => {},
        }
    }

    fn freeBytecodeClosePost(self: *Vm, post: BytecodeClosePost) void {
        switch (post) {
            .return_frame => |values| if (!self.returnSliceIsOwned(values)) self.alloc.free(values),
            else => {},
        }
    }

    fn releaseBytecodeCloseChild(self: *Vm, state: *BytecodeCloseContinuation) void {
        _ = self;
        if (!state.child_active) return;
        std.debug.assert(state.owner_thread.bytecode_close_metamethod_depth != 0);
        state.owner_thread.bytecode_close_metamethod_depth -= 1;
        if (state.err_depth) {
            std.debug.assert(state.owner_thread.bytecode_close_metamethod_err_depth != 0);
            state.owner_thread.bytecode_close_metamethod_err_depth -= 1;
        }
        state.child_active = false;
    }

    /// Roll an installed __close continuation back to its exact prior state
    /// after a failure between continuation install and child activation
    /// (staging or frame push). Shared by both failure points of the
    /// PUC luaF_close → luaT_callTM → luaD_callnoyield sequence.
    fn rollbackBytecodeCloseChild(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        state: *BytecodeCloseContinuation,
    ) void {
        self.releaseBytecodeCloseChild(state);
        self.getPendingCallPtr(exec_frames.getPtr(parent_index).pending_call_index).?.completion = .{ .close = state };
    }

    fn currentRuntimeErrorValue(self: *Vm) DispatchError!Value {
        // PUC prefixes string errors before stack unwinding. Our fail helpers
        // keep source/line separately until an error crosses a protected,
        // coroutine, or __close boundary, so materialize that normalized value
        // before the frame carrying the location is popped. Non-string error
        // objects keep their original identity.
        if (self.err_has_obj and self.err_obj != .String) return self.err_obj;
        return .{ .String = try self.internStr(self.protectedErrorString()) };
    }

    fn restoreRuntimeErrorValue(self: *Vm, value: Value) void {
        // The traceback belongs to the active error and is captured before
        // explicit frame unwinding. Restoring the error value while a closer,
        // protected handler, or coroutine continuation runs must not discard
        // that pre-unwind stack. A caller that intentionally injects a fresh
        // error (for example coroutine.close with nil) clears it explicitly.
        self.err_obj = value;
        self.err_has_obj = true;
        self.err = if (value == .String) value.String.bytes() else null;
        self.err_source = null;
        self.err_line = -1;
    }

    fn closeBytecodeUpvaluesFrom(self: *Vm, frame: *CallFrame, min_reg: u8) void {
        const boxed = self.bc_boxed[frame.frameBase() .. frame.frameBase() + frame.u.lua.frame_cap];
        var i: usize = min_reg;
        while (i < boxed.len) : (i += 1) {
            if (boxed[i]) |cell| {
                // Close the upvalue: copy the stack value into cell.value,
                // then mark as closed (bc_stack_idx = null).
                // PUC luaF_close: uv->u.value = *uv->v.p; uv->v.p = &uv->u.value
                cell.close(self);
                // PUC luaF_closeupval (lfunc.c:205-208): if !iswhite(uv):
                //   nw2black(uv) + luaC_barrier(L, uv, slot).
                // Closed upvalues cannot be gray — fix color to black.
                // The forward barrier marks the copied value if the cell
                // is black and the value is white. Do NOT rely on the
                // child having been marked earlier (PUC barriers explicitly).
                if (!gcIsWhite(cell.gc_marked)) {
                    gcSetBlack(&cell.gc_marked);
                    self.gcWriteBarrierCell(cell, cell.value) catch {};
                }
                boxed[i] = null;
            }
        }
    }

    fn recordBytecodeCloseError(self: *Vm, state: *BytecodeCloseContinuation) DispatchError!void {
        state.had_close_error = true;
        state.close_all = true;
        state.current_err = try self.currentRuntimeErrorValue();
        if (self.forced_close_thread != null) self.forced_close_had_error = true;
    }

    fn beginBytecodeClose(
        self: *Vm,
        exec_frames: *FrameStack,
        boundary_depth: usize,
        parent_index: usize,
        min_reg: u8,
        initial_err: ?Value,
        close_all: bool,
        post: BytecodeClosePost,
    ) DispatchError!BytecodeCloseProgress {
        std.debug.assert(!(exec_frames.getPtr(parent_index).pending_call_index != INVALID_PENDING));
        const owner = self.activeBytecodeThread();
        const close_state = try self.alloc.create(BytecodeCloseContinuation);
        close_state.* = .{
            .min_reg = min_reg,
            .scan_index = self.bc_tbc_regs.items.len,
            .current_err = initial_err,
            .had_close_error = false,
            .close_all = close_all,
            .err_depth = initial_err != null,
            .owner_thread = owner,
            .post = post,
        };
        try self.setPendingCall(exec_frames.getPtr(parent_index), .{
            .callee = .Nil,
            .completion = .{ .close = close_state },
        });
        return self.continueBytecodeClose(exec_frames, boundary_depth, parent_index);
    }

    fn continueBytecodeClose(
        self: *Vm,
        exec_frames: *FrameStack,
        boundary_depth: usize,
        parent_index: usize,
    ) DispatchError!BytecodeCloseProgress {
        const state = switch (self.getPendingCallPtr(exec_frames.getPtr(parent_index).pending_call_index).?.completion) {
            .close => |cont| cont,
            else => unreachable,
        };
        std.debug.assert(!state.child_active);
        if (state.waiting_builtin_yield) state.waiting_builtin_yield = false;

        while (true) {
            const parent = exec_frames.getPtr(parent_index);
            state.scan_index = @min(state.scan_index, self.bc_tbc_regs.items.len);
            var found_index: ?usize = null;
            var i = state.scan_index;
            while (i > parent.tbc_mark) {
                i -= 1;
                const reg = self.bc_tbc_regs.items[i];
                if (reg >= parent.u.lua.frame_cap) continue;
                if (!state.close_all and reg < state.min_reg) continue;
                found_index = i;
                break;
            }

            const close_index = found_index orelse break;
            const tbc_reg = self.bc_tbc_regs.items[close_index];
            _ = self.bc_tbc_regs.orderedRemove(close_index);
            state.scan_index = close_index;

            const regs = self.bc_stack[parent.frameBase() .. parent.frameBase() + parent.u.lua.frame_cap];
            const obj = regs[tbc_reg];
            if (obj == .Nil or (obj == .Bool and !obj.Bool)) continue;

            const mm = self.getTmByObj(obj, .close) orelse {
                _ = self.fail("metamethod 'close' is nil", .{}) catch {};
                try self.recordBytecodeCloseError(state);
                continue;
            };
            var argv: [2]Value = undefined;
            argv[0] = obj;
            var argc: usize = 1;
            if (state.current_err) |err_value| {
                argv[1] = err_value;
                argc = 2;
            }

            const resolved = self.resolveCallable(mm, argv[0..argc], null) catch |resolve_err| switch (resolve_err) {
                error.RuntimeError => {
                    try self.recordBytecodeCloseError(state);
                    continue;
                },
                else => return resolve_err,
            };
            defer if (resolved.owned_args) |owned| self.alloc.free(owned);
            if (resolved.callee == .Closure and resolved.callee.Closure.proto != null) {
                state.child_active = true;
                state.owner_thread.bytecode_close_metamethod_depth += 1;
                if (state.err_depth) state.owner_thread.bytecode_close_metamethod_err_depth += 1;
                try self.setPendingCall(exec_frames.getPtr(parent_index), .{
                    .callee = resolved.callee,
                    .completion = .{ .close = state },
                });
                // PUC luaF_close → luaT_callTM stages func+obj(+err) at
                // L->top, then luaD_callnoyield activates. On any failure
                // between continuation install and activation, roll the
                // __close continuation back to its exact prior state.
                const staged = self.stageBytecodeCall(
                    self.bc_stack_top,
                    resolved.callee.Closure,
                    resolved.args,
                ) catch |push_err| {
                    self.rollbackBytecodeCloseChild(exec_frames, parent_index, state);
                    return push_err;
                };
                self.pushStagedBytecodeExecFrame(
                    exec_frames,
                    resolved.callee.Closure.proto.?,
                    staged.func_slot,
                    staged.nargs,
                    0,
                ) catch |push_err| {
                    self.rollbackBytecodeCloseChild(exec_frames, parent_index, state);
                    return push_err;
                };
                self.setDebugName(exec_frames.getPtr(parent_index), "metamethod", "close");
                // PUC luaF_close → luaD_call → luaG_tracecall: the __close
                // metamethod activation gets its LUA_HOOKCALL here.
                try self.dispatchCalleeActivationHook(exec_frames, resolved.callee, resolved.args.len);
                return .resume_dispatch;
            }

            self.runCloseMetamethod(obj, state.current_err) catch |close_err| switch (close_err) {
                error.RuntimeError => {
                    try self.recordBytecodeCloseError(state);
                    continue;
                },
                error.Yield => {
                    state.waiting_builtin_yield = true;
                    self.getPendingCallPtr(exec_frames.getPtr(parent_index).pending_call_index).?.completion = .{ .close = state };
                    const th = self.current_thread orelse return error.Yield;
                    th.bytecode_inplace_suspended = true;
                    th.capture_yield_id = 0;
                    th.capture_from_debug_hook = false;
                    th.capture_from_count_hook = false;
                    return error.Yield;
                },
                else => return close_err,
            };
        }

        // Save fields needed after clear/destroy: the close continuation is
        // heap-allocated (beginBytecodeClose → alloc.create) and must be freed
        // once the close scan completes. PendingCallSlot.clear() only flips the
        // active flag (hot-path optimization); it does NOT free heap-allocated
        // completions. cancelBytecodePendingCall handles the error/cancel path;
        // this is the normal-completion path.
        const post = state.post;
        const had_close_error = state.had_close_error;
        const close_err = state.current_err;
        const close_min_reg = state.min_reg;
        self.clearPendingCall(exec_frames.getPtr(parent_index));
        self.alloc.destroy(state);
        if (had_close_error) {
            self.freeBytecodeClosePost(post);
            if (close_err) |err_value| self.restoreRuntimeErrorValue(err_value);
            if (exec_frames.getPtr(parent_index).u.lua.hasOpenUpvalues())
                self.closeBytecodeUpvaluesFrom(exec_frames.getPtr(parent_index), 0);
            self.popBytecodeExecFrame(exec_frames);
            return .propagate_error;
        }

        switch (post) {
            .advance_instruction => {
                if (exec_frames.getPtr(parent_index).u.lua.hasOpenUpvalues())
                    self.closeBytecodeUpvaluesFrom(exec_frames.getPtr(parent_index), close_min_reg);
                // PUC-faithful: the caller (OP_CLOSE handler) increments its
                // local `ctx.pc` directly. We must NOT write to the frame's
                // `pc` here — the dispatch loop's defer will sync `ctx.pc`
                // back to the frame, and writing here would be clobbered.
                return .resume_dispatch;
            },
            .retry_tailcall => {
                exec_frames.getPtr(parent_index).u.lua.skip_call_hook_pc = @intCast(exec_frames.getPtr(parent_index).u.lua.pc);
                return .resume_dispatch;
            },
            .return_frame => |values| {
                if (try self.tryPushBytecodeDebugHook(
                    exec_frames,
                    parent_index,
                    "return",
                    null,
                    null,
                    values,
                    1,
                    .{ .return_frame = values },
                )) return .resume_dispatch;
                try self.dispatchBytecodeHook("return", null, values);
                if (try self.completeBytecodeExecFrame(exec_frames, boundary_depth, values)) |final| {
                    return .{ .final = final };
                }
                return .resume_dispatch;
            },
            .unwind_frame => {
                if (close_err) |err_value| self.restoreRuntimeErrorValue(err_value);
                if (exec_frames.getPtr(parent_index).u.lua.hasOpenUpvalues())
                    self.closeBytecodeUpvaluesFrom(exec_frames.getPtr(parent_index), 0);
                self.popBytecodeExecFrame(exec_frames);
                return .propagate_error;
            },
        }
    }

    fn applyBytecodePendingClose(
        self: *Vm,
        exec_frames: *FrameStack,
        boundary_depth: usize,
        parent_index: usize,
        ret: []Value,
        cont: *BytecodeCloseContinuation,
    ) DispatchError!BytecodeCloseProgress {
        if (!self.returnSliceIsOwned(ret)) self.alloc.free(ret);
        const state = cont;
        self.releaseBytecodeCloseChild(state);
        self.getPendingCallPtr(exec_frames.getPtr(parent_index).pending_call_index).?.completion = .{ .close = state };
        return self.continueBytecodeClose(exec_frames, boundary_depth, parent_index);
    }

    fn cancelBytecodePendingCall(
        self: *Vm,
        pending: *BytecodePendingCall,
        owner_runtime: ?*CallFrame,
    ) void {
        switch (pending.completion) {
            .concat => |cont| self.alloc.free(cont.values),
            .gsub => |cont| {
                const state = cont;
                // P16.23 T6: release the in-flight repl unit (the unwind
                // pops the frame without a completion pass). The owning
                // protection's snapshot restore makes this belt-and-braces.
                if (state.repl_ccall_active) {
                    self.activeBytecodeThread().ccallExit(Thread.CCALL_INC_NOYIELD);
                    state.repl_ccall_active = false;
                }
                self.deinitBytecodeGsub(state);
                self.alloc.destroy(state);
            },
            .close => |cont| {
                const state = cont;
                self.releaseBytecodeCloseChild(state);
                self.freeBytecodeClosePost(state.post);
                self.alloc.destroy(state);
            },
            .hook => |cont| {
                if (owner_runtime) |runtime| {
                    self.bc_stack[runtime.func_slot] = cont.saved_parent_callee;
                    runtime.setTailCallBool(cont.saved_parent_tailcall);
                }
                self.alloc.free(cont.transfer);
                self.freeBytecodeHookPost(cont.post);
                self.alloc.destroy(cont);
            },
            .coroutine_resume => |cont| self.discardBytecodeSavedError(cont.saved_error),
            else => {},
        }
        if (pending.protection) |protection| {
            self.discardBytecodeProtectedCall(protection);
            pending.protection = null;
        }
    }

    /// Start a Lua call owned by a bytecode continuation.
    ///
    /// Push a bytecode callee for a non-OP_CALL continuation when possible.
    /// Returns false for builtins and frozen IR closures so the existing
    /// synchronous semantic helper can handle those non-bytecode cases.
    fn tryPushBytecodeContinuationCall(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        callee_value: Value,
        args: []const Value,
        completion: BytecodePendingCompletion,
        debug_namewhat: ?[]const u8,
        debug_name: ?[]const u8,
    ) DispatchError!bool {
        // Resolve through normal callable semantics (handles __call chains).
        // Errors are caught → return false so the caller can fall through to
        // the synchronous path. This is the resolve-once entry point for
        // callers that do NOT pre-resolve (pairs, debug hooks, etc.).
        const resolved = self.resolveCallable(callee_value, args, null) catch return false;
        defer if (resolved.owned_args) |owned| self.alloc.free(owned);
        return self.tryPushResolvedContinuationCall(
            exec_frames,
            parent_index,
            resolved,
            completion,
            debug_namewhat,
            debug_name,
        );
    }

    /// P16.10a T4: Push a KNOWN resolved bytecode Closure as a child frame
    /// with already-resolved args and the given continuation. This is the
    /// single invocation primitive for directly-pushed bytecode Closures —
    /// it does NO callable resolution (no `resolveCallable`, no `__call`
    /// chain handling).
    ///
    /// **Resolution-once invariant (Task 5):** The caller MUST have already
    /// resolved the callee (via `resolveCallable` or by proving it is a
    /// bytecode Closure with `proto != null`). This primitive never calls
    /// `resolveCallable`. Resolution happens exactly once per invocation:
    /// either in the caller (generic path) or not at all (proven-Closure
    /// fast path — a Closure is already callable, `__call` is irrelevant).
    ///
    /// **Order (unchanged from the pre-P16.10a paths):**
    /// 1. Assert no conflicting continuation state on the parent.
    /// 2. Install continuation state (pending_call or simple_result).
    /// 3. Push the child bytecode exec frame (`pushBytecodeExecFrame`).
    /// 4. Set debug name override (pending path only; simple_result derives
    ///    name from `event` at read time via `getDebugName()`).
    /// 5. Dispatch the CALL hook (`dispatchCalleeActivationHook`).
    /// P16.22 T4: ONE semantic implementation, specialized per completion
    /// mode at COMPILE TIME (Zig-native instead of the runtime union switch):
    /// each instantiation keeps only its own arm — no runtime completion
    /// dispatch, no dead payload loads, no duplicated function bodies.
    fn pushResolvedBytecodeClosure(
        self: *Vm,
        comptime mode: PushClosureMode,
        exec_frames: *FrameStack,
        parent_index: usize,
        closure: *Closure,
        args: []const Value,
        payload: switch (mode) {
            .pending => PendingPayload,
            .simple_result => SimpleResultPayload,
        },
    ) DispatchError!void {
        const proto = closure.proto orelse unreachable; // caller proves proto != null
        const parent = exec_frames.getPtr(parent_index);
        std.debug.assert(parent.pending_call_index == INVALID_PENDING);
        // P16.8 Task 1: simple_result and pending_calls are mutually exclusive.
        if (!parent.isC()) {
            std.debug.assert(!parent.u.lua.hasSimpleResult());
        }

        if (mode == .pending) {
            const p = payload;
            // Install pending_call continuation state BEFORE the fallible
            // child-frame push (mirrors PUC luaD_precall → setobj2s).
            try self.setPendingCall(parent, .{
                .callee = .{ .Closure = closure },
                .completion = p.completion,
            });
            // Roll back if child-frame push or hook dispatch fails.
            // Re-fetch via getPtr: pushStagedBytecodeExecFrame may realloc.
            errdefer self.clearPendingCall(exec_frames.getPtr(parent_index));
            const cont_nresults: i32 = switch (p.completion) {
                .results => |r| r.nresults,
                else => -1,
            };
            // PUC luaT_callTMres two-step: stage [func, args...] at
            // L->top (bc_stack_top), then activate (luaD_precall).
            const staged = try self.stageBytecodeCall(
                self.bc_stack_top,
                closure,
                args,
            );
            try self.pushStagedBytecodeExecFrame(
                exec_frames,
                proto,
                staged.func_slot,
                staged.nargs,
                cont_nresults,
            );
            // The debug name must be recorded BEFORE the CALL hook fires:
            // PUC's hook-time getinfo('n') resolves the metamethod name
            // from the caller's instruction (funcnamefromcode "metamethod"
            // branch).
            self.setDebugName(exec_frames.getPtr(parent_index), p.debug_namewhat, p.debug_name);
        } else {
            const sr = payload;
            // P16.8a Task 5: The simple_result state is set BEFORE the
            // fallible child-activation operations (staging + activation +
            // hook dispatch). The errdefer below rolls it back if any
            // fails, mirroring the errdefer clearPendingCall pattern above.
            switch (sr.completion) {
                .value => |dst| parent.u.lua.setSimpleValueResult(dst, sr.event),
                .compare => |invert| parent.u.lua.setSimpleCompareResult(sr.event, invert),
            }
            // Re-fetch via getPtr: pushStagedBytecodeExecFrame may realloc.
            errdefer exec_frames.getPtr(parent_index).u.lua.clearSimpleResult();
            // simple_result always consumes exactly 1 result (nresults=-1
            // means "the continuation handles result count" — the
            // simple_result completion reads exactly 1 value from the
            // child's return slot).
            //
            // PUC luaT_callTMres two-step: stage [func, args...] at
            // L->top (bc_stack_top), then activate (luaD_precall).
            const staged = try self.stageBytecodeCall(
                self.bc_stack_top,
                closure,
                args,
            );
            try self.pushStagedBytecodeExecFrame(
                exec_frames,
                proto,
                staged.func_slot,
                staged.nargs,
                -1,
            );
            // No setDebugName — debug name is derived from simple_result_event
            // at read time via getDebugName().
        }
        // Metamethod/continuation activations get their CALL event when the
        // frame exists (PUC: luaT_calltm → luaD_call → luaD_precall →
        // luaG_tracecall fires LUA_HOOKCALL for the metamethod function).
        try self.dispatchCalleeActivationHook(exec_frames, .{ .Closure = closure }, args.len);
    }

    /// Push a pre-resolved `ResolvedCall` as a bytecode continuation frame.
    /// This is the invocation half of the resolve→invoke split for the
    /// `pending_calls`-based continuation path (CONCAT, pairs, hooks, etc.).
    /// Returns false if the resolved callee is not a bytecode Closure (Builtin,
    /// C-closure) — the caller handles the synchronous case using the same
    /// `ResolvedCall`, avoiding double resolution (Task 5).
    ///
    /// P16.10a T4: Delegates to `pushResolvedBytecodeClosure` — the shared
    /// primitive for all directly-pushed bytecode Closures. Resolution already
    /// happened in the caller (exactly once per invocation).
    fn tryPushResolvedContinuationCall(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        resolved: ResolvedCall,
        completion: BytecodePendingCompletion,
        debug_namewhat: ?[]const u8,
        debug_name: ?[]const u8,
    ) DispatchError!bool {
        const cl = switch (resolved.callee) {
            .Closure => |closure| closure,
            else => return false,
        };
        if (cl.proto == null) return false;

        try self.pushResolvedBytecodeClosure(.pending, exec_frames, parent_index, cl, resolved.args, .{
            .completion = completion,
            .debug_namewhat = debug_namewhat,
            .debug_name = debug_name,
        });
        return true;
    }

    fn tryPushBytecodeMetamethod(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        metamethod: Value,
        opname: []const u8,
        args: []const Value,
        completion: BytecodePendingCompletion,
    ) DispatchError!bool {
        return self.tryPushBytecodeContinuationCall(
            exec_frames,
            parent_index,
            metamethod,
            args,
            completion,
            "metamethod",
            opname,
        );
    }

    /// Invoke an ALREADY-RESOLVED metamethod value as a bytecode continuation
    /// frame. This is the invocation half of the resolve→invoke split:
    /// `findBinaryTm`/`findUnaryTm` resolve, this function invokes.
    ///
    /// The resolved value may be non-callable or a Builtin/Closure-without-proto
    /// — in that case this returns `false` so the caller can fall through to
    /// `callMetamethod` (the synchronous path), which handles all value types.
    /// The `event` parameter is used solely to derive the debug opname via
    /// `tag_method.opname(event)` — no lookup is performed here.
    ///
    /// P16.10a T4: The pre-filter proves `metamethod` is a bytecode Closure
    /// with `proto != null`. Since a Closure is already callable (`__call` is
    /// irrelevant), `resolveCallable` would be a no-op wrapper returning
    /// `{same callee, same args, owned_args=null}`. Skip it — push directly
    /// via the shared `pushResolvedBytecodeClosure` primitive (zero resolution).
    /// Resolution happens exactly once per invocation (Task 5): here it is
    /// the trivial "already callable" case (zero-cost).
    fn tryPushResolvedMetamethod(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        metamethod: Value,
        args: []const Value,
        event: TmsEvent,
        completion: BytecodePendingCompletion,
    ) DispatchError!bool {
        // Fast filter: only bytecode Closures with proto can be pushed as
        // continuation frames. This avoids the resolveCallable call for
        // Builtin/non-Closure values (the common synchronous fallback).
        if (metamethod != .Closure or metamethod.Closure.proto == null) return false;
        try self.pushResolvedBytecodeClosure(
            .pending,
            exec_frames,
            parent_index,
            metamethod.Closure,
            args,
            .{
                .completion = completion,
                .debug_namewhat = "metamethod",
                .debug_name = tag_method.opname(event),
            },
        );
        return true;
    }

    /// P16.7 Task 6: Inline simple-result completion type.
    /// `value`: put 1 result into register `dst`, advance pc by 1.
    /// `compare`: check truthiness of 1 result, adjust pc (advance by 1,
    ///   then by 1 more if truthy != invert). Zero returns → false.
    const SimpleResultCompletion = union(enum) {
        value: u8, // dst register
        compare: bool, // invert
    };

    /// P16.10a T4: Completion for `pushResolvedBytecodeClosure` — the
    /// continuation state to install on the parent frame when pushing a
    /// KNOWN resolved bytecode Closure as a child frame. This is the single
    /// representation of "how the parent frame consumes the child's result"
    /// for a directly-pushed bytecode Closure.
    ///
    /// **Resolution-once invariant (Task 5):** `pushResolvedBytecodeClosure`
    /// does NO callable resolution. The caller MUST have already resolved
    /// the callee through `resolveCallable` (generic path) or proven it is a
    /// bytecode Closure with `proto != null` (fast path — a Closure is
    /// already callable, `__call` is irrelevant, so `resolveCallable` would
    /// be a no-op wrapper returning `{callee, args, owned_args=null}`).
    /// Resolution happens exactly once per invocation: either in the caller
    /// (generic path) or not at all (proven-Closure fast path).
    const PushClosureMode = enum { pending, simple_result };
    const PendingPayload = struct {
        completion: BytecodePendingCompletion,
        debug_namewhat: ?[]const u8,
        debug_name: ?[]const u8,
    };
    const SimpleResultPayload = struct {
        event: TmsEvent,
        completion: SimpleResultCompletion,
    };

    /// Outcome of `tryPushSimpleResultMetamethod`: either a continuation frame
    /// was pushed (caller continues `:frame_loop`), or the metamethod was
    /// invoked synchronously and the result is available directly.
    const SimpleResultOutcome = union(enum) {
        pushed, // continuation frame pushed — caller does continue :frame_loop
        value: Value, // synchronous result for `.value` completion
        compare: bool, // synchronous result for `.compare` completion
    };

    /// PUC two-stage metamethod invocation for the bytecode VM (Task 1+3+5+6+7+8).
    ///
    /// Stage 1 (caller): `findBinaryTm`/`findUnaryTm` resolves the TMS field
    /// — UNCHANGED, no `__call` logic inside lookup.
    ///
    /// Stage 2 (this function): Call the resolved VALUE via normal callable
    /// semantics — exactly once per invocation (Task 5: NO resolve→fallback→
    /// resolve-again). `resolveCallable` handles `__call` chains with the
    /// standard argument transformation (self prepended, original operands
    /// follow — Task 7: NO special metamethod convention). Then invoke the
    /// `ResolvedCall`:
    ///   - bytecode Closure → push child-frame continuation with `simple_result`
    ///     completion (SAME state as direct-Closure metamethods, so yielding
    ///     works — Task 6: continuation semantics, NOT forced synchronous
    ///     host-recursion).
    ///   - Builtin/C-closure → existing synchronous call boundary.
    ///
    /// **P16.10a T4 (direct-Closure fast path):** When the metamethod value
    /// is already a bytecode Closure (`proto != null`), `resolveCallable` is
    /// a no-op wrapper (a Closure is already callable, `__call` is irrelevant)
    /// returning `{same callee, same args, owned_args=null}`. Skip it — push
    /// directly via `pushResolvedBytecodeClosure` (zero resolution). This
    /// eliminates ~12% of `metamethod_call_noalloc` that was spent in
    /// `resolveCallable` on the proven-Closure hot path. Non-Closure values
    /// (tables with `__call`, numbers, etc.) still go through `resolveCallable`
    /// for `__call` chain handling and PUC's exact error text.
    ///
    /// **Error naming (Task 8):** `resolveCallable` receives
    /// `.{ .namewhat = "metamethod", .name = opname(event) }` so non-callable
    /// values produce PUC's exact error text:
    ///   "attempt to call a number value (metamethod 'add')"
    ///
    /// **`__index`/`__newindex` boundary (Task 2):** This function is NOT used
    /// for `__index`/`__newindex` — their non-function values follow table-index
    /// chaining (PUC `luaV_finishget`/`luaV_finishset`), not `__call` resolution.
    /// The `__index`/`__newindex` bytecode paths pre-filter to bytecode Closures
    /// before calling this function, so the `__call` resolution path is never
    /// triggered for them.
    fn tryPushSimpleResultMetamethod(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        metamethod: Value,
        args: []const Value,
        event: TmsEvent,
        completion: SimpleResultCompletion,
    ) DispatchError!SimpleResultOutcome {
        const opname = tag_method.opname(event);

        // P16.10a T4: Fast path for proven bytecode Closures — skip
        // resolveCallable entirely. A Closure is already callable (__call is
        // irrelevant), so resolveCallable would return {same callee, same
        // args, owned_args=null} — a no-op wrapper. Resolution happens exactly
        // once per invocation (Task 5): here it is the trivial "already
        // callable" case (zero-cost).
        if (metamethod == .Closure) {
            if (metamethod.Closure.proto) |_| {
                // Bytecode closure — push continuation frame with simple_result
                // completion via the shared primitive. This is the SAME
                // continuation state as direct-Closure metamethods, so
                // yielding works (Task 6).
                try self.pushResolvedBytecodeClosure(
                    .simple_result,
                    exec_frames,
                    parent_index,
                    metamethod.Closure,
                    args,
                    .{ .event = event, .completion = completion },
                );
                return .pushed;
            }
            // C closure (c_func set, proto null) — fall through to
            // resolveCallable path (handles __call chains + error text
            // for consistency with non-Closure values).
        }

        // Non-Closure (or C-closure): resolve ONCE through normal callable
        // semantics. resolveCallable handles __call chains (self prepended,
        // operands follow) and produces PUC's exact error text for non-callable
        // values.
        const resolved = try self.resolveCallable(metamethod, args, .{
            .namewhat = "metamethod",
            .name = opname,
        });
        defer if (resolved.owned_args) |owned| self.alloc.free(owned);

        switch (resolved.callee) {
            .Closure => |cl| {
                if (cl.proto == null) {
                    // C closure (c_func set, proto null) — synchronous.
                    return .{ .value = try self.callResolvedMetamethodSync(
                        resolved,
                        opname,
                    ) };
                }
                // Bytecode closure reached via __call chain — push continuation
                // frame via the shared primitive. Resolution already happened
                // above (exactly once — Task 5).
                try self.pushResolvedBytecodeClosure(
                    .simple_result,
                    exec_frames,
                    parent_index,
                    cl,
                    resolved.args,
                    .{ .event = event, .completion = completion },
                );
                return .pushed;
            },
            .Builtin => {
                return .{ .value = try self.callResolvedMetamethodSync(
                    resolved,
                    opname,
                ) };
            },
            else => unreachable, // resolveCallable errors on non-callable
        }
    }

    /// Synchronous invocation of a resolved metamethod for the non-continuation
    /// case (Builtin or C-closure). Sets debug name overrides matching
    /// `callMetamethod`'s behavior, then invokes via `callBuiltin`/`runClosure`.
    /// Returns the raw result Value — the caller handles `.value`/`.compare`
    /// completion transformation.
    fn callResolvedMetamethodSync(
        self: *Vm,
        resolved: ResolvedCall,
        opname: []const u8,
    ) DispatchError!Value {
        const saved_nwo = self.debug_namewhat_override;
        const saved_no = self.debug_name_override;
        self.debug_namewhat_override = "metamethod";
        self.debug_name_override = opname;
        defer {
            self.debug_namewhat_override = saved_nwo;
            self.debug_name_override = saved_no;
        }
        return switch (resolved.callee) {
            .Builtin => |id| blk: {
                var out: [1]Value = .{.Nil};
                try self.callBuiltin(id, resolved.args, out[0..]);
                break :blk out[0];
            },
            .Closure => |cl| blk: {
                const ret = try self.runClosure(cl, resolved.args);
                defer self.alloc.free(ret);
                break :blk if (ret.len > 0) ret[0] else .Nil;
            },
            else => unreachable,
        };
    }

    /// `pairs` is one of the standard-library C functions that Lua makes
    /// yieldable across its `__pairs` call.  Running the metamethod inside
    /// builtinPairs would re-enter runBytecode and replay the builtin after a
    /// yield; push the bytecode metamethod onto the shared dispatch stack
    /// instead.  Non-bytecode metamethods keep using builtinPairs.
    fn tryPushBytecodePairsMetamethod(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        args: []const Value,
        result: BytecodeResultContinuation,
    ) DispatchError!bool {
        if (args.len == 0 or args[0] != .Table) return false;
        const mm = self.getMetaFieldByObj(args[0], .pairs) orelse return false;
        var mm_args = [_]Value{args[0]};
        var pairs_result = result;
        pairs_result.append_nil = true;
        return self.tryPushBytecodeMetamethod(
            exec_frames,
            parent_index,
            mm,
            "pairs",
            mm_args[0..],
            .{ .results = pairs_result },
        );
    }

    fn debugHookMatchesEvent(hook_state: *const DebugHookState, event: []const u8) bool {
        if (std.mem.eql(u8, event, "call") or std.mem.eql(u8, event, "tail call")) return hook_state.has_call;
        if (std.mem.eql(u8, event, "return")) return hook_state.has_return;
        if (std.mem.eql(u8, event, "line")) return hook_state.has_line;
        if (std.mem.eql(u8, event, "count")) return hook_state.count > 0;
        return true;
    }

    /// Push a Lua bytecode debug hook as an ordinary explicit child frame.
    /// Non-bytecode hooks return false and are executed by the existing
    /// synchronous hook helper. `post` remains caller-owned unless true is
    /// returned.
    fn tryPushBytecodeDebugHook(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        event: []const u8,
        line: ?i64,
        event_callee: ?Value,
        transfer: ?[]const Value,
        transfer_start: i64,
        post: BytecodeHookPost,
    ) DispatchError!bool {
        if (!self.hooks_active_cached) return false;
        if (self.debug_hooks_suppressed != 0 or self.isInDebugHook()) return false;
        const hook_state = self.activeHookState();
        const hook = hook_state.func orelse return false;
        if (hook == .Nil or !debugHookMatchesEvent(hook_state, event)) return false;
        const cl = switch (hook) {
            .Closure => |closure| closure,
            else => return false,
        };
        const proto = cl.proto orelse return false;

        const transfer_copy = try self.alloc.dupe(Value, transfer orelse &.{});
        errdefer self.alloc.free(transfer_copy);

        var argv: [2]Value = undefined;
        argv[0] = .{ .String = try self.internStr(event) };
        var argc: usize = 1;
        var hook_line = line;
        if (hook_line == null and std.mem.eql(u8, event, "line") and exec_frames.len() != 0) {
            const runtime = exec_frames.getPtr(exec_frames.len() - 1);
            // P15.51n: current_line derived from proto.lineinfo[pc].
            const rt_line = self.frameCurrentLine(runtime);
            if (rt_line > 0) hook_line = rt_line;
        }
        if (hook_line) |value| {
            argv[1] = .{ .Int = value };
            argc = 2;
        }

        std.debug.assert(!(exec_frames.getPtr(parent_index).pending_call_index != INVALID_PENDING));
        // P15.51k: Callee is stored at bc_stack[func_slot] (PUC's ci->func),
        // not in a duplicated field. The hook dispatch temporarily changes
        // bc_stack[func_slot] so debug.getinfo(2).func = event_callee, then
        // restores it when the hook returns.
        const parent_frame = exec_frames.getPtr(parent_index);
        const saved_callee = self.bc_stack[parent_frame.func_slot];
        const saved_tailcall = parent_frame.isTailCall();
        if (event_callee) |callee| self.bc_stack[parent_frame.func_slot] = callee;
        if (std.mem.eql(u8, event, "tail call")) parent_frame.setTailCall() else if (std.mem.eql(u8, event, "call")) parent_frame.clearTailCall();

        const hook_state_ptr = try self.alloc.create(BytecodeHookContinuation);
        hook_state_ptr.* = .{
            .transfer = transfer_copy,
            .event_calllike = std.mem.eql(u8, event, "call") or std.mem.eql(u8, event, "tail call"),
            .event_tailcall = std.mem.eql(u8, event, "tail call"),
            .event_is_count = std.mem.eql(u8, event, "count"),
            .saved_parent_callee = saved_callee,
            .saved_parent_tailcall = saved_tailcall,
            .post = post,
        };
        try self.setPendingCall(exec_frames.getPtr(parent_index), .{
            .callee = hook,
            .completion = .{ .hook = hook_state_ptr },
        });
        // PUC luaD_hook: the hook function + event/line args are staged on
        // the stack, then called via luaD_call.
        const staged_hook = self.stageBytecodeCall(self.bc_stack_top, cl, argv[0..argc]) catch |err| {
            self.clearPendingCall(exec_frames.getPtr(parent_index));
            self.alloc.destroy(hook_state_ptr);
            self.bc_stack[parent_frame.func_slot] = saved_callee;
            exec_frames.getPtr(parent_index).setTailCallBool(saved_tailcall);
            return err;
        };
        self.pushStagedBytecodeExecFrame(exec_frames, proto, staged_hook.func_slot, staged_hook.nargs, -1) catch |err| {
            self.clearPendingCall(exec_frames.getPtr(parent_index));
            self.alloc.destroy(hook_state_ptr);
            self.bc_stack[parent_frame.func_slot] = saved_callee;
            exec_frames.getPtr(parent_index).setTailCallBool(saved_tailcall);
            return err;
        };
        const hook_runtime = exec_frames.getPtr(exec_frames.len() - 1);
        hook_runtime.setDebugHook();
        // P15.51n: Track hook frame index on Thread for O(1) access.
        const th = self.activeBytecodeThread();
        th.hook_frame_index = exec_frames.len() - 1;
        // P15.38f: Set per-thread in_debug_hook so isInDebugHook() is O(1).
        // This mirrors PUC Lua's `L->allowhook = 0` in luaD_hook.
        self.activeHookState().in_debug_hook = true;
        th.debug_hook_transfer = transfer_copy;
        th.debug_hook_transfer_start = transfer_start;
        th.debug_hook_event_calllike = std.mem.eql(u8, event, "call") or std.mem.eql(u8, event, "tail call");
        th.debug_hook_event_tailcall = std.mem.eql(u8, event, "tail call");
        th.debug_hook_event_is_count = std.mem.eql(u8, event, "count");
        th.debug_hook_allow_yield = hook_state.allow_yield;
        return true;
    }

    /// Result of trying to push an INDEX/NEWINDEX metamethod as a bytecode
    /// continuation frame. Carries the resolved metamethod value when it was
    /// found but not pushable (Builtin, Closure without proto), so the caller
    /// can invoke it synchronously without re-resolving.
    const TryPushIndexResult = union(enum) {
        /// Bytecode frame pushed — caller does `continue :frame_loop`.
        pushed,
        /// No metamethod found — caller uses `indexValue`/`setIndexValue`.
        not_found,
        /// Metamethod resolved but not pushable. Caller calls
        /// `callMetamethod(mm, ...)` directly — no re-lookup.
        resolved: struct { mm: Value, obj: Value },
    };

    /// Probe the `__index` chain without executing a Lua closure.  The common
    /// raw/table-only path returns `.not_found` and is completed by `indexValue`;
    /// when the first callable slow path is a bytecode closure we push it directly
    /// and let the parent continuation store its first result.  When a metamethod
    /// is found but not pushable, `.resolved` carries it out — no re-lookup.
    fn tryPushBytecodeIndexMetamethod(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        initial_object: Value,
        key: Value,
        dst: u8,
    ) DispatchError!TryPushIndexResult {
        var object = initial_object;
        var depth: usize = 0;
        while (depth < 200) : (depth += 1) {
            if (object == .Table) {
                const table = object.Table;
                if (try self.tableGetRawValue(table, key) != .Nil) return .not_found;
                const mt = table.metatable orelse return .not_found;
                // PUC fasttm: check flags bit, cache-on-miss via fasttm.
                // (lua-5.5.0/src/ltm.h:63 checknoTM + luaT_gettm.)
                const mm = self.fastTm(mt, .index) orelse return .not_found;
                if (mm == .Table) {
                    object = .{ .Table = mm.Table };
                    continue;
                }
                if (mm == .Closure and mm.Closure.proto != null) {
                    const args = [_]Value{ object, key };
                    // Task 2: __index pre-filters to bytecode Closures —
                    // tryPushSimpleResultMetamethod only pushes (no __call
                    // resolution for __index; non-function values follow
                    // table-index chaining via .resolved below).
                    switch (try self.tryPushSimpleResultMetamethod(
                        exec_frames,
                        parent_index,
                        mm,
                        args[0..],
                        .index,
                        .{ .value = dst },
                    )) {
                        .pushed => return .pushed,
                        else => {},
                    }
                }
                return .{ .resolved = .{ .mm = mm, .obj = object } };
            }

            const mm = self.getTmByObj(object, .index) orelse return .not_found;
            if (mm == .Table) {
                object = .{ .Table = mm.Table };
                continue;
            }
            if (mm == .Closure and mm.Closure.proto != null) {
                const args = [_]Value{ object, key };
                switch (try self.tryPushSimpleResultMetamethod(
                    exec_frames,
                    parent_index,
                    mm,
                    args[0..],
                    .index,
                    .{ .value = dst },
                )) {
                    .pushed => return .pushed,
                    else => {},
                }
            }
            return .{ .resolved = .{ .mm = mm, .obj = object } };
        }
        return .not_found;
    }

    /// `__newindex` counterpart of `tryPushBytecodeIndexMetamethod`.
    fn tryPushBytecodeNewIndexMetamethod(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        initial_object: Value,
        key: Value,
        value: Value,
    ) DispatchError!TryPushIndexResult {
        var object = initial_object;
        var depth: usize = 0;
        while (depth < 200) : (depth += 1) {
            if (object == .Table) {
                const table = object.Table;
                const raw = try self.tableGetRawValue(table, key);
                if (raw != .Nil or table.metatable == null) return .not_found;
                // PUC fasttm: check flags bit, cache-on-miss via fasttm.
                const mm = self.fastTm(table.metatable.?, .newindex) orelse return .not_found;
                if (mm == .Table) {
                    object = .{ .Table = mm.Table };
                    continue;
                }
                if (mm == .Closure and mm.Closure.proto != null) {
                    const args = [_]Value{ object, key, value };
                    const pushed = try self.tryPushBytecodeMetamethod(
                        exec_frames,
                        parent_index,
                        mm,
                        "newindex",
                        args[0..],
                        .{ .ignore = .{} },
                    );
                    if (pushed) return .pushed;
                }
                return .{ .resolved = .{ .mm = mm, .obj = object } };
            }

            const mm = self.getTmByObj(object, .newindex) orelse return .not_found;
            if (mm == .Table) {
                object = .{ .Table = mm.Table };
                continue;
            }
            if (mm == .Closure and mm.Closure.proto != null) {
                const args = [_]Value{ object, key, value };
                const pushed = try self.tryPushBytecodeMetamethod(
                    exec_frames,
                    parent_index,
                    mm,
                    "newindex",
                    args[0..],
                    .{ .ignore = .{} },
                );
                if (pushed) return .pushed;
            }
            return .{ .resolved = .{ .mm = mm, .obj = object } };
        }
        return .not_found;
    }

    /// Complete an INDEX operation: try push as bytecode frame, else fall
    /// through to `indexValue` (for upvalues) or `bytecodeIndexValue` (for
    /// register-based opcodes). Returns true if pushed (caller does
    /// `continue :frame_loop`).
    fn bytecodeGetIndex(
        self: *Vm,
        exec_frames: *FrameStack,
        ctx: *BytecodeDispatchCtx,
        obj: Value,
        key: Value,
        a: u8,
        b: u8,
        use_bytecode_fallback: bool,
    ) DispatchError!bool {
        switch (try self.tryPushBytecodeIndexMetamethod(exec_frames, ctx.frame_index, obj, key, a)) {
            .pushed => return true,
            .not_found => {
                if (use_bytecode_fallback) {
                    const result = try self.bytecodeIndexValue(ctx.cur_proto, ctx.pc, b, obj, key);
                    ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                    ctx.regs[a] = result;
                } else {
                    ctx.regs[a] = try self.indexValue(obj, key);
                }
            },
            .resolved => |r| {
                exec_frames.getPtr(ctx.frame_index).u.lua.pc = ctx.pc;
                ctx.regs[a] = try self.callResolvedIndexMetamethod(r.mm, r.obj, key);
                ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
            },
        }
        return false;
    }

    /// Complete a NEWINDEX operation: try push as bytecode frame, else fall
    /// through to `setIndexValue` (for upvalues) or `bytecodeSetIndexValue`
    /// (for register-based opcodes). Returns true if pushed.
    fn bytecodeSetIndex(
        self: *Vm,
        exec_frames: *FrameStack,
        ctx: *BytecodeDispatchCtx,
        obj: Value,
        key: Value,
        val: Value,
        a: u8,
        use_bytecode_fallback: bool,
    ) DispatchError!bool {
        switch (try self.tryPushBytecodeNewIndexMetamethod(exec_frames, ctx.frame_index, obj, key, val)) {
            .pushed => return true,
            .not_found => {
                if (use_bytecode_fallback) {
                    try self.bytecodeSetIndexValue(ctx.cur_proto, ctx.pc, a, obj, key, val);
                } else {
                    try self.setIndexValue(obj, key, val);
                }
            },
            .resolved => |r| {
                exec_frames.getPtr(ctx.frame_index).u.lua.pc = ctx.pc;
                try self.callResolvedNewIndexMetamethod(r.mm, r.obj, key, val);
                ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
            },
        }
        return false;
    }

    fn bytecodeComparisonHasFastPath(lhs: Value, rhs: Value) bool {
        const lhs_number = lhs == .Int or lhs == .Num;
        const rhs_number = rhs == .Int or rhs == .Num;
        return (lhs_number and rhs_number) or (lhs == .String and rhs == .String);
    }

    /// PUC-faithful result application for ordinary Lua CALL (no pending_call).
    /// dst = callee.func_slot_base - parent.frameBase() (PUC: ci->func.p is result dest).
    /// nresults from callee callstatus (PUC: CIST_NRESULTS).
    fn applyBytecodeResultsDirect(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        ret: []Value,
        dst: usize,
        nresults: i32,
    ) DispatchError!void {
        errdefer if (!self.returnSliceIsOwned(ret)) self.alloc.free(ret);
        const parent = exec_frames.getPtr(parent_index);
        var regs = self.bc_stack[parent.frameBase() .. parent.frameBase() + parent.u.lua.frame_cap];
        const nstore: usize = if (nresults >= 0) @intCast(nresults) else ret.len;
        // P16.2e (CHANGE 5): Guard bcGrowFrame — only call when growth is
        // actually needed. bcGrowFrame unconditionally re-derives regs/boxed
        // slices even when no growth occurs, which is pure overhead on the
        // return hot path. The guard condition (dst + nstore > frame_cap) is
        // semantically identical to bcGrowFrame's internal check.
        //
        // Safety: the slices derived above are always valid because they are
        // computed from the current self.bc_stack pointer. No code between the
        // derivation and the write below can reallocate bc_stack (it is a
        // simple loop copy). If a previous operation in this caller did
        // reallocate bc_stack, the slices were derived AFTER that realloc, so
        // they point into the current allocation. The parent frame's
        // frame_cap field is always up-to-date (frames are not moved by stack
        // realloc — only the bc_stack/bc_boxed arrays grow).
        if (dst + nstore > parent.u.lua.frame_cap) {
            try self.bcGrowFrame(parent.frameBase(), dst + nstore, &parent.u.lua.frame_cap, &regs);
        }
        for (0..nstore) |i| regs[dst + i] = if (i < ret.len) ret[i] else .Nil;
        if (nresults < 0) parent.reg_top = @intCast(@as(usize, dst) + ret.len);
        parent.u.lua.pc += 1;
        if (!self.returnSliceIsOwned(ret)) self.alloc.free(ret);
    }

    fn applyBytecodePendingResults(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        ret: []Value,
        dst: usize,
        nresults: i32,
    ) DispatchError!void {
        errdefer if (!self.returnSliceIsOwned(ret)) self.alloc.free(ret);
        const parent = exec_frames.getPtr(parent_index);
        const pending = self.getPendingCallConst(parent.pending_call_index) orelse unreachable;
        const min_reg_top: ?u32 = switch (pending.completion) {
            .results => |cont| cont.min_reg_top,
            else => unreachable,
        };
        var regs = self.bc_stack[parent.frameBase() .. parent.frameBase() + parent.u.lua.frame_cap];
        const nstore: usize = if (nresults >= 0) @intCast(nresults) else ret.len;
        try self.bcGrowFrame(parent.frameBase(), dst + nstore, &parent.u.lua.frame_cap, &regs);
        for (0..nstore) |i| regs[dst + i] = if (i < ret.len) ret[i] else .Nil;
        if (nresults < 0) parent.reg_top = @intCast(dst + ret.len);
        if (min_reg_top) |minimum| parent.reg_top = @max(parent.reg_top, minimum);

        // GC liveness: `frame.reg_top` is the dynamic upper bound (set above).
        // GC read sites use `max(proto.live_reg_top[pc], frame.reg_top)` so the
        // compile-time static liveness (a lower bound) does not need runtime
        // extension. `Proto.live_reg_top` stays read-only at runtime.

        parent.u.lua.pc += 1;
        self.clearPendingCall(parent);
        if (!self.returnSliceIsOwned(ret)) self.alloc.free(ret);
    }

    /// Complete a synchronous or resumed frozen-IR call owned by a bytecode
    /// frame. Unlike a bytecode child, there is no explicit exec frame to pop,
    /// so this path emits the callee return hook and then applies the recorded
    /// result continuation itself.
    fn completeBytecodePendingExternalResults(
        self: *Vm,
        exec_frames: *FrameStack,
        boundary_depth: usize,
        parent_index: usize,
        ret_in: []Value,
    ) DispatchError!?[]Value {
        var ret = ret_in;
        var ret_owned = true;
        errdefer if (ret_owned and !self.returnSliceIsOwned(ret)) self.alloc.free(ret);

        const pending = self.getPendingCallConst(exec_frames.getPtr(parent_index).pending_call_index) orelse unreachable;
        // P15.51n: Snapshot fields needed across reentrant operations.
        // clearPendingCall + tryPushBytecodeDebugHook + dispatchBytecodeHookWithCallee
        // can realloc pending_calls, invalidating the pointer.
        const pending_callee = pending.callee;
        const cont = switch (pending.completion) {
            .results => |result| result,
            else => unreachable,
        };
        if (cont.append_nil) {
            const extended = try self.alloc.alloc(Value, ret.len + 1);
            @memcpy(extended[0..ret.len], ret);
            extended[ret.len] = .Nil;
            if (!self.returnSliceIsOwned(ret)) self.alloc.free(ret);
            ret = extended;
        }

        if (cont.tail_return) {
            self.clearPendingCall(exec_frames.getPtr(parent_index));
            ret_owned = false;
            return switch (try self.beginBytecodeClose(
                exec_frames,
                boundary_depth,
                parent_index,
                0,
                null,
                true,
                .{ .return_frame = ret },
            )) {
                .resume_dispatch => null,
                .final => |final| final,
                .propagate_error => error.RuntimeError,
            };
        }

        // A hook continuation needs the pending slot, so detach the IR call
        // before possibly pushing the hook child. `store_results` owns `ret`.
        self.clearPendingCall(exec_frames.getPtr(parent_index));
        if (try self.tryPushBytecodeDebugHook(
            exec_frames,
            parent_index,
            "return",
            null,
            pending_callee,
            ret,
            1,
            .{ .store_results = .{
                .continuation = cont,
                .values = ret,
            } },
        )) {
            ret_owned = false;
            return null;
        }
        try self.dispatchBytecodeHookWithCallee("return", pending_callee, ret);
        try self.setPendingCall(exec_frames.getPtr(parent_index), .{
            .callee = pending_callee,
            .completion = .{ .results = cont },
        });
        ret_owned = false;
        try self.applyBytecodePendingResults(exec_frames, parent_index, ret, cont.dst, cont.nresults);
        return null;
    }

    fn applyBytecodePendingValue(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        ret: []Value,
        cont: BytecodeValueContinuation,
    ) DispatchError!void {
        defer if (!self.returnSliceIsOwned(ret)) self.alloc.free(ret);
        const parent = exec_frames.getPtr(parent_index);
        var regs = self.bc_stack[parent.frameBase() .. parent.frameBase() + parent.u.lua.frame_cap];
        try self.bcGrowFrame(parent.frameBase(), @as(usize, cont.dst) + 1, &parent.u.lua.frame_cap, &regs);
        regs[cont.dst] = if (ret.len == 0) .Nil else ret[0];
        parent.u.lua.pc += 1;
        self.clearPendingCall(parent);
    }

    fn applyBytecodePendingIgnore(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        ret: []Value,
    ) void {
        if (!self.returnSliceIsOwned(ret)) self.alloc.free(ret);
        const parent = exec_frames.getPtr(parent_index);
        parent.u.lua.pc += 1;
        self.clearPendingCall(parent);
    }

    fn applyBytecodePendingCompare(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        ret: []Value,
        cont: BytecodeCompareContinuation,
    ) void {
        defer if (!self.returnSliceIsOwned(ret)) self.alloc.free(ret);
        const result = ret.len != 0 and isTruthy(ret[0]);
        const parent = exec_frames.getPtr(parent_index);
        parent.u.lua.pc += 1;
        if (result != cont.invert) parent.u.lua.pc += 1;
        self.clearPendingCall(parent);
    }

    const BytecodeConcatOutcome = union(enum) {
        pushed,
        value: Value,
    };

    fn isDirectConcatOperand(value: Value) bool {
        return value == .String or value == .Int or value == .Num;
    }

    /// Continue a CONCAT without retaining state on the native stack.
    ///
    /// `values` is owned by this operation.  It is either freed on immediate
    /// completion/error or transferred to a `.concat` pending continuation.
    /// Processing is right-to-left to match Lua's right-associative `..`.
    fn advanceBytecodeConcat(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        dst: u8,
        values: []Value,
        remaining_in: usize,
        acc_in: Value,
    ) DispatchError!BytecodeConcatOutcome {
        var roots = self.gcTempRoots();
        defer roots.end();
        for (values) |value| try roots.add(value);
        try roots.add(acc_in);

        var owns_values = true;
        defer if (owns_values) self.alloc.free(values);

        var remaining = remaining_in;
        var acc = acc_in;
        while (remaining != 0) {
            const lhs = values[remaining - 1];
            if (isDirectConcatOperand(lhs) and isDirectConcatOperand(acc)) {
                var pair = [_]Value{ lhs, acc };
                acc = try self.concatValuesDirect(pair[0..]);
                try roots.add(acc);
                remaining -= 1;
                continue;
            }

            const mm = self.getTmByObj(lhs, .concat) orelse
                self.getTmByObj(acc, .concat) orelse {
                const bad = if (!isDirectConcatOperand(lhs)) lhs else acc;
                return self.fail("attempt to concatenate a {s} value", .{bad.typeName()});
            };
            const args = [_]Value{ lhs, acc };

            // PUC two-stage: resolve ONCE through normal callable semantics
            // (handles __call chains), then invoke — bytecode Closure as
            // continuation frame (yieldable), Builtin/C-closure synchronously.
            // No double resolution (Task 5).
            const resolved = try self.resolveCallable(mm, args[0..], .{
                .namewhat = "metamethod",
                .name = "concat",
            });
            defer if (resolved.owned_args) |owned| self.alloc.free(owned);

            const concat_state = try self.alloc.create(BytecodeConcatContinuation);
            concat_state.* = .{
                .dst = dst,
                .values = values,
                .remaining = remaining - 1,
                .acc = acc,
            };
            if (try self.tryPushResolvedContinuationCall(
                exec_frames,
                parent_index,
                resolved,
                .{ .concat = concat_state },
                "metamethod",
                "concat",
            )) {
                owns_values = false;
                return .pushed;
            }
            self.alloc.destroy(concat_state);

            // Synchronous invocation (Builtin or C-closure).
            const saved_nwo = self.debug_namewhat_override;
            const saved_no = self.debug_name_override;
            self.debug_namewhat_override = "metamethod";
            self.debug_name_override = "concat";
            defer {
                self.debug_namewhat_override = saved_nwo;
                self.debug_name_override = saved_no;
            }
            acc = switch (resolved.callee) {
                .Builtin => |id| blk: {
                    var out: [1]Value = .{.Nil};
                    try self.callBuiltin(id, resolved.args, out[0..]);
                    break :blk out[0];
                },
                .Closure => |cl| blk: {
                    const ret = try self.runClosure(cl, resolved.args);
                    defer self.alloc.free(ret);
                    break :blk if (ret.len > 0) ret[0] else .Nil;
                },
                else => unreachable,
            };
            try roots.add(acc);
            remaining -= 1;
        }

        return .{ .value = acc };
    }

    fn applyBytecodePendingConcat(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        ret: []Value,
        cont: *BytecodeConcatContinuation,
    ) DispatchError!void {
        const acc = if (ret.len == 0) Value.Nil else ret[0];

        // Root the continuation while detaching it from the parent.  The next
        // bytecode metamethod, if any, installs a fresh pending owner before
        // this function returns.
        var roots = self.gcTempRoots();
        defer roots.end();
        for (cont.values) |value| try roots.add(value);
        try roots.add(acc);
        if (!self.returnSliceIsOwned(ret)) self.alloc.free(ret);

        self.clearPendingCall(exec_frames.getPtr(parent_index));
        const outcome = try self.advanceBytecodeConcat(
            exec_frames,
            parent_index,
            cont.dst,
            cont.values,
            cont.remaining,
            acc,
        );
        switch (outcome) {
            .pushed => {},
            .value => |value| {
                const parent = exec_frames.getPtr(parent_index);
                var regs = self.bc_stack[parent.frameBase() .. parent.frameBase() + parent.u.lua.frame_cap];
                try self.bcGrowFrame(parent.frameBase(), @as(usize, cont.dst) + 1, &parent.u.lua.frame_cap, &regs);
                regs[cont.dst] = value;
                parent.u.lua.pc += 1;
            },
        }
    }

    fn deinitBytecodeGsub(self: *Vm, state: *BytecodeGsubContinuation) void {
        state.out.deinit(self.alloc);
        state.out = .empty;
    }

    fn bytecodeGsubHasAsyncReplacement(self: *Vm, replacement: Value) bool {
        _ = self;
        return switch (replacement) {
            .Closure => |cl| cl.proto != null,
            // A table replacement can invoke an arbitrary Lua __index. Route
            // all table replacements through the state machine; raw hits still
            // complete synchronously without pushing a child.
            .Table => true,
            else => false,
        };
    }

    fn initBytecodeGsub(
        self: *Vm,
        args: []const Value,
        result: BytecodeResultContinuation,
    ) DispatchError!*BytecodeGsubContinuation {
        const state = try self.alloc.create(BytecodeGsubContinuation);
        state.* = try self.initBytecodeGsubInner(args, result);
        return state;
    }

    fn initBytecodeGsubInner(
        self: *Vm,
        args: []const Value,
        result: BytecodeResultContinuation,
    ) DispatchError!BytecodeGsubContinuation {
        if (args.len < 3) return self.fail("string.gsub expects (s, pattern, repl [, n])", .{});
        const subject = args[0];
        const pattern = args[1];
        const s = switch (subject) {
            .String => |value| value.bytes(),
            else => return self.fail("string.gsub expects string", .{}),
        };
        _ = s;
        var pat = switch (pattern) {
            .String => |value| value.bytes(),
            else => return self.fail("string.gsub expects pattern string", .{}),
        };
        var anchored_start = false;
        var anchored_end = false;
        if (pat.len > 0 and pat[0] == '^') {
            anchored_start = true;
            pat = pat[1..];
        }
        if (pat.len > 0 and pat[pat.len - 1] == '$' and (pat.len == 1 or pat[pat.len - 2] != '%')) {
            anchored_end = true;
            pat = pat[0 .. pat.len - 1];
        }
        const limit: usize = if (args.len >= 4) switch (args[3]) {
            .Int => |n| if (n <= 0) 0 else @intCast(n),
            else => return self.fail("string.gsub: n must be integer", .{}),
        } else std.math.maxInt(usize);
        return .{
            .result = result,
            .subject = subject,
            .pattern = pattern,
            .replacement = args[2],
            .limit = limit,
            .anchored_start = anchored_start,
            .anchored_end = anchored_end,
            .literal = pat.len > 0 and patIsLiteral(pat),
        };
    }

    fn bytecodeGsubPattern(state: *const BytecodeGsubContinuation) []const u8 {
        var pat = state.pattern.String.bytes();
        if (state.anchored_start) pat = pat[1..];
        if (state.anchored_end) pat = pat[0 .. pat.len - 1];
        return pat;
    }

    fn appendBytecodeGsubResult(
        self: *Vm,
        state: *BytecodeGsubContinuation,
        value: Value,
    ) DispatchError!void {
        const s = state.subject.String.bytes();
        if (value == .Nil or (value == .Bool and !value.Bool)) {
            try state.out.appendSlice(self.alloc, s[state.pending_start..state.pending_end]);
            return;
        }
        const replacement = try self.valueToStringAlloc(value);
        try state.out.appendSlice(self.alloc, replacement);
        state.had_subst = true;
    }

    fn advanceBytecodeGsubAfterMatch(
        self: *Vm,
        state: *BytecodeGsubContinuation,
    ) DispatchError!void {
        const s = state.subject.String.bytes();
        state.count += 1;
        if (state.pending_empty) {
            if (state.pending_start >= s.len) {
                state.index = s.len + 1;
            } else {
                try state.out.append(self.alloc, s[state.pending_start]);
                state.index = state.pending_start + 1;
                state.disallow_empty_at = null;
            }
        } else {
            state.index = state.pending_end;
            if (!state.literal) state.disallow_empty_at = state.pending_end;
        }
    }

    fn applyBytecodeGsubCallbackReturn(
        self: *Vm,
        state: *BytecodeGsubContinuation,
        ret: []Value,
    ) DispatchError!void {
        defer if (!self.returnSliceIsOwned(ret)) self.alloc.free(ret);
        try self.appendBytecodeGsubResult(state, if (ret.len == 0) .Nil else ret[0]);
        try self.advanceBytecodeGsubAfterMatch(state);
    }

    fn bytecodeGsubCallbackArgs(
        self: *Vm,
        s: []const u8,
        match_start: usize,
        match_end: usize,
        caps: *const [10]Capture,
        storage: *[10]Value,
    ) DispatchError![]const Value {
        var count: usize = 0;
        var cap_i: usize = 1;
        while (cap_i < caps.len and count < storage.len) : (cap_i += 1) {
            if (!caps[cap_i].set) continue;
            storage[count] = if (caps[cap_i].is_pos)
                .{ .Int = @intCast(caps[cap_i].start + 1) }
            else
                .{ .String = try self.internStr(s[caps[cap_i].start..caps[cap_i].end]) };
            count += 1;
        }
        if (count == 0) {
            storage[0] = .{ .String = try self.internStr(s[match_start..match_end]) };
            count = 1;
        }
        return storage[0..count];
    }

    fn tryPushBytecodeGsubTableIndex(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        initial_table: *Table,
        key: Value,
        state: *BytecodeGsubContinuation,
    ) DispatchError!bool {
        var object: Value = .{ .Table = initial_table };
        var depth: usize = 0;
        while (depth < 200) : (depth += 1) {
            const table = object.Table;
            if (try self.tableGetRawValue(table, key) != .Nil) return false;
            const mt = table.metatable orelse return false;
            // PUC fasttm: check flags bit, cache-on-miss via fasttm.
            const mm = self.fastTm(mt, .index) orelse return false;
            if (mm == .Table) {
                object = .{ .Table = mm.Table };
                continue;
            }
            if (mm == .Closure and mm.Closure.proto != null) {
                const call_args = [_]Value{ object, key };
                return self.tryPushBytecodeContinuationCall(
                    exec_frames,
                    parent_index,
                    mm,
                    call_args[0..],
                    .{ .gsub = state },
                    "metamethod",
                    "index",
                );
            }
            return false;
        }
        return false;
    }

    fn finishBytecodeGsub(
        self: *Vm,
        state: *BytecodeGsubContinuation,
    ) DispatchError![]Value {
        const ret = try self.alloc.alloc(Value, 2);
        errdefer self.alloc.free(ret);
        if (!state.had_subst) {
            state.out.deinit(self.alloc);
            state.out = .empty;
            ret[0] = state.subject;
        } else {
            const bytes = try state.out.toOwnedSlice(self.alloc);
            state.out = .empty;
            ret[0] = .{ .String = try self.internStr(bytes) };
        }
        ret[1] = .{ .Int = @intCast(state.count) };
        return ret;
    }

    fn advanceBytecodeGsub(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        state_in: *BytecodeGsubContinuation,
        callback_ret: ?[]Value,
    ) DispatchError!BytecodeGsubProgress {
        var state = state_in;
        var owns_state = true;
        defer if (owns_state) {
            self.deinitBytecodeGsub(state);
            self.alloc.destroy(state);
        };

        var roots = self.gcTempRoots();
        defer roots.end();
        try roots.add(state.subject);
        try roots.add(state.pattern);
        try roots.add(state.replacement);
        if (callback_ret) |values| for (values) |value| try roots.add(value);

        if (callback_ret) |values| try self.applyBytecodeGsubCallbackReturn(state, values);

        const s = state.subject.String.bytes();
        const pat = bytecodeGsubPattern(state);
        if (state.limit == 0) {
            const final = try self.finishBytecodeGsub(state);
            owns_state = false;
            return .{ .final = final };
        }

        var toks: ?[]PatTok = null;
        defer if (toks) |tokens| self.alloc.free(tokens);
        if (!state.literal) toks = try self.compilePattern(pat);

        while (if (state.literal) state.index < s.len else state.index <= s.len) {
            if (state.anchored_start and state.index != 0) {
                try state.out.appendSlice(self.alloc, s[state.index..]);
                state.index = s.len + 1;
                break;
            }
            if (state.count >= state.limit) {
                if (state.index < s.len) try state.out.appendSlice(self.alloc, s[state.index..]);
                state.index = s.len + 1;
                break;
            }

            var caps: [10]Capture = [_]Capture{.{}} ** 10;
            var matched = false;
            var match_end: usize = state.index;
            if (state.literal) {
                matched = state.index + pat.len <= s.len and
                    (!state.anchored_end or state.index + pat.len == s.len) and
                    std.mem.eql(u8, s[state.index .. state.index + pat.len], pat);
                if (matched) match_end = state.index + pat.len;
            } else {
                const endpos = try self.matchTokens(toks.?, 0, s, state.index, &caps, state.index, state.anchored_end);
                if (endpos) |end| {
                    if (!state.anchored_end or end == s.len) {
                        matched = true;
                        match_end = end;
                    }
                }
                if (matched and match_end == state.index and state.disallow_empty_at == state.index) {
                    matched = false;
                    state.disallow_empty_at = null;
                }
            }

            if (!matched) {
                if (state.index >= s.len) break;
                try state.out.append(self.alloc, s[state.index]);
                state.index += 1;
                if (!state.literal) state.disallow_empty_at = null;
                continue;
            }

            state.pending_start = state.index;
            state.pending_end = match_end;
            state.pending_empty = !state.literal and match_end == state.index;

            switch (state.replacement) {
                .String => |replacement| {
                    const expanded = try self.expandReplacement(
                        replacement.bytes(),
                        s,
                        state.pending_start,
                        state.pending_end,
                        &caps,
                    );
                    try state.out.appendSlice(self.alloc, expanded);
                    state.had_subst = true;
                    try self.advanceBytecodeGsubAfterMatch(state);
                },
                .Table => |table| {
                    const key: Value = if (caps[1].set)
                        (if (caps[1].is_pos)
                            .{ .Int = @intCast(caps[1].start + 1) }
                        else
                            .{ .String = try self.internStr(s[caps[1].start..caps[1].end]) })
                    else
                        .{ .String = try self.internStr(s[state.pending_start..state.pending_end]) };
                    if (try self.tryPushBytecodeGsubTableIndex(
                        exec_frames,
                        parent_index,
                        table,
                        key,
                        state,
                    )) {
                        owns_state = false;
                        return .pushed;
                    }
                    const value = try self.tableGetFromNonYieldableC(table, key);
                    if (value == .Nil or (value == .Bool and !value.Bool)) {
                        try state.out.appendSlice(self.alloc, s[state.pending_start..state.pending_end]);
                    } else switch (value) {
                        .String, .Int, .Num => {
                            const replacement = try self.valueToStringAlloc(value);
                            try state.out.appendSlice(self.alloc, replacement);
                            state.had_subst = true;
                        },
                        else => return self.fail("invalid replacement value (a {s})", .{value.typeName()}),
                    }
                    try self.advanceBytecodeGsubAfterMatch(state);
                },
                .Closure => |closure| {
                    if (closure.proto != null) {
                        var call_storage: [10]Value = undefined;
                        const call_args = try self.bytecodeGsubCallbackArgs(
                            s,
                            state.pending_start,
                            state.pending_end,
                            &caps,
                            &call_storage,
                        );
                        if (try self.tryPushBytecodeContinuationCall(
                            exec_frames,
                            parent_index,
                            state.replacement,
                            call_args,
                            .{ .gsub = state },
                            null,
                            null,
                        )) {
                            owns_state = false;
                            // P16.23 T6: PUC invokes each gsub replacement
                            // through lua_call → ccall(nyci): one C-depth
                            // unit per repl invocation. The iterative
                            // continuation has no C frame, so the unit is
                            // accounted HERE, at the push, and released at
                            // the continuation's completion (in
                            // applyBytecodePendingGsub). Errors unwind to a
                            // protection whose finish restores the snapshot.
                            if (!state.repl_ccall_active) {
                                const th_g = self.activeBytecodeThread();
                                try self.ccallEnter(th_g, Thread.CCALL_INC_NOYIELD);
                                state.repl_ccall_active = true;
                            }
                            return .pushed;
                        }
                    }
                    const value = try self.runGsubReplacementFunction(
                        state.replacement,
                        s,
                        state.pending_start,
                        state.pending_end,
                        &caps,
                    );
                    try self.appendBytecodeGsubResult(state, value);
                    try self.advanceBytecodeGsubAfterMatch(state);
                },
                .Builtin => {
                    const value = try self.runGsubReplacementFunction(
                        state.replacement,
                        s,
                        state.pending_start,
                        state.pending_end,
                        &caps,
                    );
                    try self.appendBytecodeGsubResult(state, value);
                    try self.advanceBytecodeGsubAfterMatch(state);
                },
                else => return self.fail("string.gsub: replacement must be string, table, or function", .{}),
            }
        }

        const final = try self.finishBytecodeGsub(state);
        owns_state = false;
        return .{ .final = final };
    }

    fn tryStartBytecodeGsub(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        args: []const Value,
        result: BytecodeResultContinuation,
    ) DispatchError!BytecodeGsubStart {
        if (args.len < 3 or !self.bytecodeGsubHasAsyncReplacement(args[2])) return .not_handled;
        const state = try self.initBytecodeGsub(args, result);
        return switch (try self.advanceBytecodeGsub(exec_frames, parent_index, state, null)) {
            .pushed => .pushed,
            .final => |values| .{ .returned = values },
        };
    }

    fn applyBytecodePendingGsub(
        self: *Vm,
        exec_frames: *FrameStack,
        boundary_depth: usize,
        parent_index: usize,
        ret: []Value,
        state: *BytecodeGsubContinuation,
    ) DispatchError!?[]Value {
        // P16.23 T6: the in-flight repl's C-depth unit is complete
        // (paired exit for the guarded enter at the push site).
        if (state.repl_ccall_active) {
            self.activeBytecodeThread().ccallExit(Thread.CCALL_INC_NOYIELD);
            state.repl_ccall_active = false;
        }
        self.clearPendingCall(exec_frames.getPtr(parent_index));
        switch (try self.advanceBytecodeGsub(exec_frames, parent_index, state, ret)) {
            .pushed => return null,
            .final => |values| {
                try self.setPendingCall(exec_frames.getPtr(parent_index), .{
                    .callee = .{ .Builtin = .string_gsub },
                    .completion = .{ .results = state.result },
                });
                return self.completeBytecodePendingExternalResults(
                    exec_frames,
                    boundary_depth,
                    parent_index,
                    values,
                );
            },
        }
    }

    fn applyBytecodePendingHook(
        self: *Vm,
        exec_frames: *FrameStack,
        boundary_depth: usize,
        parent_index: usize,
        ret: []Value,
        cont: *BytecodeHookContinuation,
    ) DispatchError!?[]Value {
        if (!self.returnSliceIsOwned(ret)) self.alloc.free(ret);
        // P15.51k: Restore callee at bc_stack[func_slot] (PUC's ci->func).
        const runtime = exec_frames.getPtr(parent_index);
        self.bc_stack[runtime.func_slot] = cont.saved_parent_callee;
        runtime.setTailCallBool(cont.saved_parent_tailcall);
        self.clearPendingCall(exec_frames.getPtr(parent_index));
        self.alloc.free(cont.transfer);

        switch (cont.post) {
            .resume_instruction => |state| {
                if (state.skip_count) runtime.u.lua.resume_skip_count_pc = @intCast(exec_frames.getPtr(parent_index).u.lua.pc);
                if (state.skip_line) self.activeHookState().skip_bc_line_once = true;
                return null;
            },
            .retry_call => {
                const retry_pc: u32 = @intCast(exec_frames.getPtr(parent_index).u.lua.pc);
                exec_frames.getPtr(parent_index).u.lua.skip_call_hook_pc = retry_pc;
                // The call hook ran before OP_CALL. Retrying that same opcode
                // must not also look like a backward/same-pc line transition;
                // PUC resumes luaG_traceexec with oldpc still at this call.
                exec_frames.getPtr(parent_index).u.lua.skip_line_hook_pc = retry_pc;
                return null;
            },
            .store_results => |state| {
                try self.setPendingCall(exec_frames.getPtr(parent_index), .{
                    .callee = cont.saved_parent_callee,
                    .completion = .{ .results = state.continuation },
                });
                try self.applyBytecodePendingResults(exec_frames, parent_index, state.values, state.continuation.dst, state.continuation.nresults);
                return null;
            },
            .return_frame => |values| {
                return try self.completeBytecodeExecFrame(exec_frames, boundary_depth, values);
            },
        }
    }

    /// P15.83r: builtins whose OP_CALL/OP_TAILCALL dispatch may be REPLACED by
    /// the iterative fast paths (tryPushBytecodePairsMetamethod,
    /// tryPushBytecodeProtectedCall, tryRequestBytecodeCoroutineSwitch,
    /// tryStartBytecodeGsub) before callBuiltin ever runs. These keep the
    /// legacy caller-frame CALL identity because the fast-path completion
    /// machinery requires the callee body frame to sit directly above its
    /// pending-call owner (a plain builtin C-frame in between would be
    /// misrouted by the `parent.isC()` return routing in
    /// completeBytecodeExecFrame).
    ///
    /// `pairs` is the one exactly-predictable case: the metamethod fast path
    /// applies iff the first argument is a table with a BYTECODE __pairs
    /// metamethod (tryPushBytecodePairsMetamethod's own conditions), so a
    /// plain-table `pairs(t)` gets the full PUC precallC identity.
    ///
    /// The rest are conservative by id only: a false "divert" (e.g. pcall
    /// with a C target) merely keeps the caller-frame identity for that
    /// invocation; it can never duplicate or lose an event.
    fn builtinCallMayDivert(self: *Vm, id: BuiltinId, args: []const Value) bool {
        switch (id) {
            .pairs => {
                if (args.len == 0 or args[0] != .Table) return false;
                const mm = self.getMetaFieldByObj(args[0], .pairs) orelse return false;
                return mm == .Closure and mm.Closure.proto != null;
            },
            .pcall,
            .xpcall,
            .string_gsub,
            .coroutine_resume,
            .coroutine_wrap_iter,
            => return true,
            else => return false,
        }
    }

    fn bytecodeCoroutineTarget(
        self: *Vm,
        id: BuiltinId,
        args: []const Value,
    ) ?BytecodeCoroutineTarget {
        switch (id) {
            .coroutine_resume => {
                if (args.len == 0 or args[0] != .Thread) return null;
                return .{
                    .thread = args[0].Thread,
                    .args = args[1..],
                    .kind = .resume_call,
                };
            },
            .coroutine_wrap_iter => {
                if (args.len == 0 or args[0] != .Table) return null;
                const thread_value = self.getFieldOpt(args[0].Table, "__thread") orelse return null;
                if (thread_value != .Thread) return null;
                return .{
                    .thread = thread_value.Thread,
                    .args = args[1..],
                    .kind = .wrap_call,
                };
            },
            else => return null,
        }
    }

    fn canTrampolineBytecodeThread(th: *const Thread) bool {
        if (th.status != .suspended or th.close_mode) return false;
        // P15.78: Check C-frames for pending testc_state — if any C-frame
        // has unconsumed continuation state, the coroutine is in the middle
        // of a callk/pcallk/yieldk chain and must not be trampolined.
        for (0..th.call_frames.len()) |i| {
            const fr = th.call_frames.getConstPtr(i);
            if (fr.isC() and fr.u.c.testc_state != null) return false;
        }
        if (th.bytecode_inplace_suspended or th.call_frames.len() != 0) return true;
        return th.callee == .Closure and th.callee.Closure.proto != null;
    }

    /// Suspend the current bytecode caller and hand a nested coroutine switch
    /// to the one active trampoline. The caller's activation stays in its
    /// Thread-owned frame stack; no Zig frame has to remain alive while the
    /// child coroutine runs.
    fn tryRequestBytecodeCoroutineSwitch(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        dst: u8,
        nresults: i32,
        id: BuiltinId,
        args: []const Value,
        tail_return: bool,
    ) DispatchError!bool {
        if (!self.bytecode_coroutine_trampoline_active) return false;
        const target = self.bytecodeCoroutineTarget(id, args) orelse return false;
        const caller = self.activeBytecodeThread();
        // A coroutine that is waiting for this caller is "normal", not
        // resumable. Let the ordinary builtin produce `(false, message)`;
        // switching the trampoline back into an ancestor would create a cycle
        // and turn a non-throwing resume failure into a coroutine error.
        if (target.thread.status == .suspended and caller != target.thread and caller.caller == target.thread) return false;
        if (!canTrampolineBytecodeThread(target.thread)) return false;
        if (target.thread == caller) return false;
        if (self.bytecode_coroutine_switch_request != null) return false;
        if (exec_frames.getPtr(parent_index).pending_call_index != INVALID_PENDING) return false;

        const args_copy = try self.alloc.dupe(Value, target.args);
        if (self.stats.enabled) self.stats.resume_allocs += 1; // P16.0b (trampoline resume args)
        errdefer self.alloc.free(args_copy);
        const saved_error = self.saveBytecodeProtectedError();
        var saved_error_owned = true;
        errdefer if (saved_error_owned) self.restoreBytecodeSavedError(saved_error);

        const co_state = try self.alloc.create(BytecodeCoroutineContinuation);
        if (self.stats.enabled) self.stats.resume_allocs += 1; // P16.0b (trampoline continuation)
        co_state.* = .{
            .target = target.thread,
            .kind = target.kind,
            .result = .{
                .dst = dst,
                .nresults = nresults,
                .tail_return = tail_return,
            },
            .saved_error = saved_error,
        };
        try self.setPendingCall(exec_frames.getPtr(parent_index), .{
            .callee = .{ .Builtin = id },
            .completion = .{ .coroutine_resume = co_state },
        });
        self.bytecode_coroutine_switch_request = .{
            .caller = caller,
            .target = target.thread,
            .args = args_copy,
        };
        caller.bytecode_inplace_suspended = true;
        saved_error_owned = false;
        return true;
    }

    /// P16.5b: Check if a coroutine.resume/yield builtin call is eligible for
    /// the fast path — direct call without pushBuiltinCFrame/callBuiltin
    /// dispatch overhead.
    ///
    /// The C-frame exists in PUC Lua as a CallInfo on L->ci (pushed by
    /// luaD_precall for C functions). In luazig, the synthetic C-frame
    /// (pushBuiltinCFrame) adds overhead that PUC doesn't have: CallFrame
    /// init/bookkeeping (func_slot/base/setC/setHidden), bc_stack_top
    /// manipulation, the generic callBuiltin context (outs tracking,
    /// args re-derivation, Nil-init of outs — memset was 6.9% of
    /// coroutine_yield cycles), and the callBuiltinSwitch dispatch
    /// indirection. FrameStack.addOne itself is inline storage for the
    /// common case (depth <= INLINE_FRAME_CAP=32, no heap); a heap spill
    /// only occurs when call depth exceeds the inline cap (rare). For the
    /// hot coroutine.resume/yield cycle (the dominant coroutine workload),
    /// this overhead is ~12% of cycles (pushBuiltinCFrame 5.2% + memset
    /// 6.9%).
    ///
    /// Guards exclude ALL cases where the C-frame is semantically needed:
    /// - Debug hooks (CALL/RETURN hook dispatch requires the C-frame)
    /// - Debug hook context (special yield handling via the hook frame)
    /// - C continuations (callk/pcallk/yieldk testc_state on C-frames)
    /// - Close mode (special C-frame discard in builtinCoroutineResume)
    /// - Wrap eager mode (wrap has its own yield semantics — outs consumed)
    /// - Non-yieldable boundary (C-call boundary — yield must error)
    /// - Trampoline active for resume (nested case handled by
    ///   tryRequestBytecodeCoroutineSwitch)
    fn coroutineBuiltinFastPathEligible(
        self: *Vm,
        id: BuiltinId,
        args: []const Value,
    ) bool {
        // No debug hooks — C-frame is needed for CALL/RETURN hook dispatch.
        if (self.hooks_active_cached) return false;
        // Not inside a debug hook — debug hooks have special yield handling
        // that uses the hook frame's pending_call state.
        if (self.isInDebugHook()) return false;

        switch (id) {
            .coroutine_yield => {
                const th = self.current_thread orelse return false;
                // Wrap eager mode has its own yield semantics: outs are
                // consumed by the wrap driver (not error.Yield). The fast
                // path skips Nil-fill of outs, which wrap_eager_mode needs.
                if (th.wrap_eager_mode) return false;
                // Close mode has special C-frame discard logic in
                // builtinCoroutineResume (resetCI drops all C-frames).
                if (th.close_mode) return false;
                // Thread must be yieldable (PUC lua_yield: L->ci must be
                // yieldable — nCcalls < LUAI_MAXCCALLS).
                if (!th.yieldable()) return false;
                // No non-yieldable boundary (gsub pending call — PUC's
                // CIST_YPCALL makes lua_yield fail with "C-call boundary").
                if (self.hasActiveBytecodeNonYieldableBoundary()) return false;
                // No C-frames on the stack at all. When yielding from within
                // a builtin C-frame (e.g. pcall(foo) where foo yields),
                // builtinCoroutineYield's P15.79 path expects the yield's
                // own C-frame at len()-1 to find the Lua frame at len()-2.
                // Without the C-frame (fast path), the P15.79 path sees the
                // pcall C-frame at len()-2 and doesn't set
                // bytecode_inplace_suspended. On resume, the pcall C-frame
                // would be incorrectly popped by finishCcall. The C-frame
                // is also needed on resume: builtinCoroutineResume checks
                // for a C-frame on top and calls finishCcall to pop the
                // yield's C-frame (not the pcall's).
                const th_bc = self.activeBytecodeThread();
                for (0..th_bc.call_frames.len()) |i| {
                    if (th_bc.call_frames.getConstPtr(i).isC()) return false;
                }
                return true;
            },
            .coroutine_resume => {
                // Trampoline active — nested resume is handled by
                // tryRequestBytecodeCoroutineSwitch (iterative switch,
                // no C-frame at all). Don't double-handle.
                if (self.bytecode_coroutine_trampoline_active) return false;
                // Target must be a thread (builtinCoroutineResume's first
                // check — if it fails, the builtin raises a "bad argument"
                // error). Bail to the generic callBuiltin path so the error
                // is raised with the full C-frame + error-recovery context
                // (YPCALL guard, cframe_preserved defer) that the fast path
                // skips.
                if (args.len == 0 or args[0] != .Thread) return false;
                const target = args[0].Thread;
                // Target not in close mode — close mode has special C-frame
                // discard logic (resetCI drops ALL C-frames without calling
                // continuations).
                if (target.close_mode) return false;
                // No C-frames with testc_state on target thread — the
                // continuation k must be invoked via finishCcall on resume,
                // which requires the C-frame.
                for (0..target.call_frames.len()) |i| {
                    const fr = target.call_frames.getConstPtr(i);
                    if (fr.isC() and fr.u.c.testc_state != null) return false;
                }
                return true;
            },
            else => return false,
        }
    }

    /// P16.5b: Call a coroutine builtin directly, without the generic
    /// pushBuiltinCFrame/callBuiltin dispatch cycle.
    ///
    /// This mirrors what PUC Lua does natively: luaD_precall pushes a
    /// CallInfo for the C function, calls it, and pops the CallInfo — all
    /// on the C stack with no heap allocation. luazig's synthetic C-frame
    /// (pushBuiltinCFrame) adds CallFrame init/bookkeeping + bc_stack
    /// manipulation + generic callBuiltin context that PUC doesn't have.
    /// This fast path eliminates that overhead for the hot
    /// coroutine.resume/yield cycle.
    ///
    /// Sets up the active_builtin context (needed by builtinCoroutineYield
    /// for th.suspended_builtin, and by the coroutine body's yield to
    /// detect that it's yielding from a builtin) and calls the builtin
    /// function directly.
    ///
    /// Skips vs generic callBuiltin:
    /// - pushBuiltinCFrame/popBuiltinCFrame (5.2% of coroutine_yield cycles)
    /// - Nil-fill of outs (6.9% memset — neither builtin reads outs before
    ///   writing; the OP_CALL post-call handler Nil-fills result slots)
    /// - callBuiltin dispatch switch (part of 7.6%)
    /// - builtin_outs_on_bc_stack tracking (neither builtin uses
    ///   refreshBuiltinOuts — the target thread's bc_stack is separate)
    fn callCoroutineBuiltinDirect(
        self: *Vm,
        id: BuiltinId,
        args: []const Value,
        outs: []Value,
    ) DispatchError!void {
        // Set active_builtin context — needed by builtinCoroutineYield
        // (th.suspended_builtin = self.active_builtin) and by the coroutine
        // body's yield to detect it's yielding from a builtin.
        const prev_active_builtin = self.active_builtin;
        const prev_active_builtin_args = self.active_builtin_args;
        self.active_builtin = id;
        self.active_builtin_args = args;
        defer {
            self.active_builtin = prev_active_builtin;
            self.active_builtin_args = prev_active_builtin_args;
        }

        switch (id) {
            .coroutine_resume => try self.builtinCoroutineResume(args, outs),
            .coroutine_yield => try self.builtinCoroutineYield(args, outs),
            else => unreachable,
        }
    }

    fn resetBytecodeCoroutineResumeState(th: *Thread) void {
        th.in_resume = false;
        th.resume_pop_consumed = false;
        th.resume_recursive_mode = false;
        th.resume_yield_id = 0;
        th.capture_yield_id = 0;
        th.capture_from_debug_hook = false;
        th.capture_from_count_hook = false;
        th.resume_base_depth = 0;
    }

    /// Prepare a coroutine selected by the trampoline. All allocations happen
    /// before the caller is parked, so OOM cannot leave two runtimes half-active.
    fn prepareBytecodeCoroutineSwitch(
        self: *Vm,
        request: BytecodeCoroutineSwitchRequest,
    ) DispatchError!bool {
        defer self.alloc.free(request.args);
        const target = request.target;
        std.debug.assert(self.current_thread == request.caller);
        std.debug.assert(self.active_runtime_thread == request.caller);
        std.debug.assert(canTrampolineBytecodeThread(target));

        const first_start = !target.started and target.entry_args == null;
        if (first_start) target.entry_args = try self.alloc.dupe(Value, request.args);
        try self.setThreadResumeInbox(target, request.args);
        target.yielded.deinit(self.alloc);

        request.caller.status = .suspended;
        target.status = .running;
        target.in_resume = true;
        target.resume_pop_consumed = false;
        target.resume_recursive_mode = false;
        target.yield_origin_depth = 0;
        target.suspended_direct_yield = false;
        target.capture_yield_id = 0;
        target.resume_yield_id = 0;
        target.resume_recursive_mode = false;
        target.caller = request.caller;

        // P15.33: Set current_thread before switchRuntime so that
        // refreshHooksCached (called inside switchRuntime) reads the
        // target thread's hook state.
        self.current_thread = target;
        self.switchRuntime(target);
        target.resume_base_depth = 0;
        return first_start;
    }

    fn finishNestedBytecodeCoroutine(
        self: *Vm,
        thread: *Thread,
        step: BytecodeCoroutineStep,
    ) void {
        switch (step) {
            .returned => {
                thread.trace_had_error = false;
                thread.status = .dead;
                thread.close_has_err = false;
                thread.started = true;
                thread.finished = true;
                self.clearThreadContinuationScratch(thread, .{});
            },
            .yielded => {
                thread.yielded.deinit(self.alloc);
                thread.trace_yields += 1;
                thread.status = .suspended;
                thread.close_has_err = false;
                thread.started = true;
                thread.finished = false;
            },
            .failed => |error_value| {
                thread.yielded.deinit(self.alloc);
                thread.trace_had_error = true;
                thread.status = .dead;
                thread.close_has_err = true;
                thread.close_err = error_value;
                thread.started = true;
                thread.finished = true;
                self.clearThreadContinuationScratch(thread, .{});
            },
            .forced_close => unreachable,
        }
        resetBytecodeCoroutineResumeState(thread);
    }

    fn completeBytecodeCoroutineResult(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        ret: []Value,
        cont: *BytecodeCoroutineContinuation,
    ) DispatchError!?[]Value {
        var result_roots = self.gcTempRoots();
        defer result_roots.end();
        for (ret) |value| try result_roots.add(value);

        const pending = self.getPendingCallConst(exec_frames.getPtr(parent_index).pending_call_index) orelse unreachable;
        // P15.51n: Snapshot callee before reentrant operations.
        const pending_callee = pending.callee;
        std.debug.assert(pending.completion == .coroutine_resume);
        self.restoreBytecodeSavedError(cont.saved_error);

        if (cont.result.tail_return) {
            self.clearPendingCall(exec_frames.getPtr(parent_index));
            return switch (try self.beginBytecodeClose(
                exec_frames,
                0,
                parent_index,
                0,
                null,
                true,
                .{ .return_frame = ret },
            )) {
                .resume_dispatch => null,
                .final => |final| final,
                .propagate_error => error.RuntimeError,
            };
        }

        self.clearPendingCall(exec_frames.getPtr(parent_index));
        if (try self.tryPushBytecodeDebugHook(
            exec_frames,
            parent_index,
            "return",
            null,
            pending_callee,
            ret,
            1,
            .{ .store_results = .{
                .continuation = cont.result,
                .values = ret,
            } },
        )) return null;
        self.dispatchBytecodeHookWithCallee("return", pending_callee, ret) catch |hook_err| {
            if (!self.returnSliceIsOwned(ret)) self.alloc.free(ret);
            return hook_err;
        };
        try self.setPendingCall(exec_frames.getPtr(parent_index), .{
            .callee = pending_callee,
            .completion = .{ .results = cont.result },
        });
        try self.applyBytecodePendingResults(exec_frames, parent_index, ret, cont.result.dst, cont.result.nresults);
        return null;
    }

    fn wrapBytecodeCoroutineValues(
        self: *Vm,
        kind: BytecodeCoroutineKind,
        ok: bool,
        values: []Value,
    ) DispatchError![]Value {
        if (kind == .wrap_call) return values;
        const wrapped = try self.alloc.alloc(Value, values.len + 1);
        wrapped[0] = .{ .Bool = ok };
        @memcpy(wrapped[1..], values);
        self.alloc.free(values);
        return wrapped;
    }

    fn bytecodeCoroutineYieldStep(self: *Vm, thread: *Thread, is_initial: bool) DispatchError!BytecodeCoroutineStep {
        if (is_initial) {
            // Common case: yield values are in thread.yielded, read directly
            // by builtinCoroutineResume. No dupe needed — saves one alloc
            // per yield/resume cycle (PUC uses zero allocs via lua_xmove).
            return .{ .yielded = &[_]Value{} };
        }
        // Nested coroutine: bubble path needs owned values because
        // finishNestedBytecodeCoroutine frees thread.yielded.
        const values = thread.yielded.slice() orelse &[_]Value{};
        return .{ .yielded = try self.alloc.dupe(Value, values) };
    }

    fn recoverTrampolineParentError(
        self: *Vm,
        parent: *Thread,
    ) DispatchError!?BytecodeCoroutineStep {
        const exec_frames = &parent.call_frames;
        return switch (try self.recoverBytecodeDispatchError(exec_frames, 0, error.RuntimeError)) {
            .resumed => null,
            .completed => |ret| .{ .returned = ret },
            .propagate => |fault| switch (fault) {
                .runtime => .{ .failed = try self.currentRuntimeErrorValue() },
                .out_of_memory => error.OutOfMemory,
            },
        };
    }

    /// PUC `finishpcallk` (ldo.c:804-821): error recovery for yieldable pcall.
    ///
    /// Called from `finishCcall` when the suspended C-frame has `CIST_YPCALL`
    /// set (i.e. the C function was entered via `lua_pcallk` and yielded).
    /// Returns the status to pass to the continuation `k`:
    ///
    /// - `LUA_OK` (0) saved in `CIST_RECST` → the pcall was interrupted by a
    ///   plain yield, not an error. PUC promotes this to `LUA_YIELD` (1) so
    ///   `k` sees a yield status.
    /// - An error status saved in `CIST_RECST` → a real error occurred while
    ///   the pcall was suspended. PUC restores `allowhook`, closes TBC
    ///   variables (`luaF_close`, which may itself yield), places the error
    ///   object on the stack (`luaD_seterrorobj`), shrinks the stack, and
    ///   clears the saved status. The error status is returned to `k`.
    ///
    /// In both cases `CIST_YPCALL` is cleared and `L->errfunc` is restored
    /// from `ci->u.c.old_errfunc` (saved at pcallk entry).
    ///
    /// P15.83c FIX B: C-frame TBC close (`luaF_close`) is handled by the
    /// CIST_CLSRET path in `finishCcall` (TBC values pre-collected by
    /// `callCFunction`'s error path before c_stack is restored). When
    /// `finishpcallk` is called, CIST_CLSRET is NOT set — meaning either
    /// there were no C-frame TBC variables, or they were already closed by
    /// the CLSRET path. So `finishpcallk` does NOT need to close TBC vars.
    fn finishpcallk(self: *Vm, th: *Thread) i32 {
        const th_bc = &th.call_frames;
        const fr = th_bc.getPtr(th_bc.len() - 1);
        std.debug.assert(fr.isC() and fr.isYpcall());

        // PUC: status = getcistrecst(ci)
        var status: i32 = @intCast(getcistrecst(fr.callstatus));
        if (status == 0) {
            // PUC: no error saved → was interrupted by a plain yield.
            // Promote to LUA_YIELD so k sees a yield, not OK.
            status = 1; // LUA_YIELD
        } else {
            // PUC: error — restore allowhook, close TBC, set error object,
            // shrink stack, clear saved status.
            // PUC: func = restorestack(L, ci->u2.funcidx)
            const funcidx = fr.u.c.aux.funcidx;
            // PUC: L->allowhook = getoah(ci)
            th.allowhook = getoah(fr.callstatus);
            // P15.83c FIX B: C-frame TBC close (luaF_close) is handled by
            // the CIST_CLSRET path in finishCcall. When finishpcallk is
            // called, CIST_CLSRET is NOT set (no TBC to close, or already
            // closed). Lua-frame TBC variables are closed by the bytecode
            // dispatch loop's error unwinding path (beginBytecodeClose)
            // before precover is called.
            // PUC: luaD_seterrorobj(L, status, func) — place error object at
            // func on the stack. The error object is in self.err_obj.
            // luazig: place the error object on bc_stack at funcidx so k can
            // read it via lua_tovalue(L, 1) etc. (c_stack is set up by
            // finishCcall before calling k).
            if (self.err_has_obj) {
                if (funcidx < self.bc_stack.len) {
                    self.bc_stack[funcidx] = self.err_obj;
                    self.bc_stack_top = funcidx + 1;
                }
            }
            // PUC: luaD_shrinkstack(L)
            self.shrinkBcStack();
            // PUC: setcistrecst(ci, LUA_OK) — clear saved status.
            fr.callstatus = setcistrecst(fr.callstatus, 0);
        }

        // PUC: ci->callstatus &= ~CIST_YPCALL
        fr.clearYpcall();
        // PUC: L->errfunc = ci->u.c.old_errfunc
        th.errfunc = fr.u.c.old_errfunc;

        return status;
    }

    /// PUC `findpcall` (ldo.c:884-891): scan `call_frames` for a frame with
    /// `CIST_YPCALL` set. Returns the index of the innermost such frame, or
    /// null if none. Used by `precover` to locate a suspended yieldable
    /// pcall for error recovery.
    fn findpcall(self: *Vm, th: *Thread) ?usize {
        _ = self;
        const th_bc = th.call_frames;
        var i = th_bc.len();
        while (i > 0) {
            i -= 1;
            const fr = th_bc.getConstPtr(i);
            if (fr.isYpcall()) return i;
        }
        return null;
    }

    /// PUC `precover` (ldo.c:955-963): error recovery loop.
    ///
    /// While the status is an error status (not `LUA_OK` and not `LUA_YIELD`),
    /// find the innermost suspended `CIST_YPCALL` frame, save the error status
    /// into its `CIST_RECST` field, and re-enter `unroll` (the trampoline) from
    /// that frame to unwind through the pcall's error path.
    ///
    /// luazig: the trampoline IS `unroll`. `precover` finds the CIST_YPCALL
    /// frame, pops all frames above it (mirroring PUC's `L->ci = ci` which
    /// discards frames above the recovery point), saves the error status into
    /// CIST_RECST, and returns `true` to signal the trampoline to continue the
    /// drive loop. The drive loop will see the C-frame on top and call
    /// `finishCcall` → `finishpcallk` → k to complete error recovery.
    ///
    /// Returns `true` if recovered (CIST_YPCALL frame found), `false` if not.
    fn precover(self: *Vm, th: *Thread) bool {
        const ci_idx = self.findpcall(th) orelse {
            return false;
        };
        // PUC: L->ci = ci — go down to the recovery function.
        // Pop all frames above the CIST_YPCALL frame. This mirrors PUC's
        // `L->ci = ci` which effectively discards all CallInfo records above
        // the recovery point. In luazig, the frames above may include Lua
        // frames from the errored callee — they are unwound here.
        // P15.81: Free heap-allocated testc_state on any C-frames being
        // popped, preventing leaks when precover discards a testcContShim
        // C-frame (e.g., error from __close during TBC close).
        {
            var fi: usize = th.call_frames.len();
            while (fi > ci_idx + 1) {
                fi -= 1;
                const f = th.call_frames.getPtr(fi);
                if (f.isC()) self.freeCFrameOwnedState(f);
            }
        }
        th.call_frames.shrinkTo(ci_idx + 1);
        // PUC: setcistrecst(ci, status) — save error status for finishpcallk.
        const fr = th.call_frames.getPtr(ci_idx);
        // LUA_ERRRUN = 2 (most common error status).
        // LUA_ERRERR = 5 (error in message handler — set by invokeErrfunc).
        // Stack overflow uses LUA_ERRRUN with a "stack overflow" message.
        const err_status: u32 = if (self.err_is_errerr) 5 else 2;
        fr.callstatus = setcistrecst(fr.callstatus, err_status);
        // PUC: luaD_rawrunprotected(L, unroll, NULL) — re-enter unroll.
        // luazig: the drive loop IS unroll. Return true to signal the
        // trampoline to continue the drive loop. The drive loop will see
        // the C-frame on top and call finishCcall → finishpcallk → k.
        return true;
    }

    /// PUC `finishCcall` (ldo.c:837-858): resume a C function's continuation.
    /// Called when the topmost frame is a C-frame after resume.
    /// Calls k via raw invocation (no new C-frame), then poscall.
    ///
    /// In PUC, `finishCcall` is called from `unroll` when the topmost CallInfo
    /// is a C function frame (`!isLua(ci)`). It invokes the saved continuation
    /// `k` directly — without pushing a new CallInfo — then calls
    /// `luaD_poscall` to move results and pop the frame.
    ///
    /// luazig mirrors this: `k` runs in the existing suspended C-frame (no
    /// `pushBuiltinCFrame` / `callCFunction` wrapper). The continuation returns
    /// `n` (result count), which `poscallCFrame` uses to set `bc_stack_top`
    /// and pop the frame.
    ///
    /// **CIST_YPCALL**: if the C-frame was a yieldable pcall, `finishpcallk`
    /// (Task 12) restores error state and close TBC variables, then returns
    /// the status to pass to `k` (LUA_YIELD for a plain yield, or the error
    /// status for an error).
    ///
    /// **CIST_CLSRET**: In PUC, set when TBC close yields during `luaD_poscall`
    /// for a C function. On resume, `finishCcall` redoes poscall with saved
    /// nres. In luazig, testC handles TBC close via `testcContShim` pushed
    /// BEFORE running closers. For generic C API calls, `callCFunction`
    /// closes TBC slots directly — if `__close` yields in a non-yieldable
    /// context, it's an error (PUC: "attempt to yield from outside a
    /// coroutine"). If `__close` yields in a yieldable context (inside a
    /// coroutine), the C-frame stays and `finishCcall` continues closing
    /// on resume via CIST_CLSRET.
    fn finishCcall(self: *Vm, th: *Thread) DispatchError!i32 {
        const th_bc = &th.call_frames;
        const fr = th_bc.getPtr(th_bc.len() - 1);
        std.debug.assert(fr.isC());

        // P15.83c FIX B: status variable visible across CLSRET and k paths.
        // For pcall_error_close, the CLSRET completion sets status and falls
        // through to the k invocation below.
        var status: i32 = 1; // LUA_YIELD (default for plain yield)
        var skip_finishpcallk = false;

        // P15.83c FIX B: Resume-error with yield-snapshotted TBC values.
        // When a yieldable pcall's C-frame has `clsret_state` (TBC Values
        // snapshotted from c_stack at yield time, pcall_error_close mode,
        // CIST_CLSRET NOT set) and the resumed callee errored (CIST_RECST
        // has an error status), we must close those TBC Values before
        // completing finishpcallk. This mirrors PUC's
        // `luaF_close(L, func, status, 1)` in `finishpcallk`.
        //
        // Set CIST_CLSRET so the close loop below picks up the clsret_state,
        // set the error value, then fall through to the CLSRET close loop.
        if (!fr.isClsret() and fr.isYpcall() and fr.u.c.clsret_state != null) {
            const recst = getcistrecst(fr.callstatus);
            if (recst != 0) { // error status (not LUA_OK)
                const cs = fr.u.c.clsret_state.?;
                // Set the error value from the current error state.
                cs.error_value = if (self.err_has_obj) self.err_obj else .Nil;
                fr.setClsret();
                // Fall through to the CLSRET close loop below.
            } else {
                // Normal yield resume (no error): the pcall succeeded.
                // Free the yield-snapshotted TBC values — they don't need
                // to be closed. This mirrors PUC where TBC vars survive
                // naturally on L->stack and are closed later by lua_closeslot
                // or normal return.
                const cs = fr.u.c.clsret_state.?;
                self.alloc.free(cs.remaining_tbc);
                self.alloc.destroy(cs);
                fr.u.c.clsret_state = null;
            }
        }

        // CIST_CLSRET: TBC close yielded mid-way (return_close mode) OR
        // C-frame TBC pre-collected for pcallk error recovery (pcall_error_close
        // mode). Continue closing remaining TBC values from the saved
        // CClsretState on the C-frame.
        if (fr.isClsret()) {
            const cs = fr.u.c.clsret_state orelse {
                // Should never happen: CIST_CLSRET without clsret_state.
                return error.RuntimeError;
            };
            // Run closers LIFO. The err_arg passed to __close depends on mode:
            // - return_close: null (no error, normal return close)
            // - pcall_error_close: cs.error_value (the current error object,
            //   PUC luaF_close passes the error to __close as 2nd arg)
            var ci: usize = 0;
            while (ci < cs.remaining_tbc.len) {
                const err_arg: ?Value = switch (cs.mode) {
                    .return_close => null,
                    .pcall_error_close => cs.error_value,
                };
                self.runCloseMetamethod(cs.remaining_tbc[ci], err_arg) catch |e| switch (e) {
                    error.Yield => {
                        // __close yielded again. Update remaining_tbc to
                        // skip the closed value. C-frame stays with CIST_CLSRET.
                        const remaining = cs.remaining_tbc[ci + 1 ..];
                        if (remaining.len == 0) {
                            self.alloc.free(cs.remaining_tbc);
                            cs.remaining_tbc = &[_]Value{};
                        } else {
                            const new_remaining = self.alloc.dupe(Value, remaining) catch return error.OutOfMemory;
                            self.alloc.free(cs.remaining_tbc);
                            cs.remaining_tbc = new_remaining;
                        }
                        return error.Yield;
                    },
                    else => {
                        if (cs.mode == .pcall_error_close) {
                            // PUC luaF_close: __close errored during error
                            // unwinding. The new error replaces the old error
                            // value (LIFO, last-error-wins). Continue closing
                            // remaining TBC vars. self.err_obj is already the
                            // new error (set by fail() inside runCloseMetamethod).
                            cs.error_value = self.err_obj;
                            cs.error_status = 2; // LUA_ERRRUN
                            // Continue closing remaining TBC vars.
                        } else {
                            // return_close: __close errored. Free clsret_state
                            // and propagate the error.
                            self.alloc.free(cs.remaining_tbc);
                            self.alloc.free(cs.results);
                            self.alloc.destroy(cs);
                            fr.u.c.clsret_state = null;
                            return e;
                        }
                    },
                };
                ci += 1;
            }
            // All closers done. Mode-specific completion.
            switch (cs.mode) {
                .return_close => {
                    // Free remaining_tbc, extract results.
                    self.alloc.free(cs.remaining_tbc);
                    const saved_results = cs.results;
                    self.alloc.destroy(cs);
                    fr.u.c.clsret_state = null;
                    fr.clearClsret();

                    // DON'T pop C-frame here — poscallCFrame (called by the
                    // trampoline after finishCcall returns) will pop it.
                    // Put results in resume_inbox for the Lua frame to pick up.
                    if (saved_results.len > 0) {
                        if (th.resume_inbox.slice()) |old| self.alloc.free(old);
                        th.resume_inbox.setOwned(self.alloc, saved_results);
                    } else {
                        self.alloc.free(saved_results);
                    }
                    // Set isHookYield on the Lua frame below so OP_CALL uses resume_inbox.
                    {
                        var fi: usize = th_bc.len();
                        while (fi > 0) {
                            fi -= 1;
                            const f = th_bc.getPtr(fi);
                            if (!f.isC()) {
                                f.setHookYield();
                                f.u.lua.resume_pc = @intCast(f.u.lua.pc);
                                break;
                            }
                        }
                    }
                    return @intCast(saved_results.len);
                },
                .pcall_error_close => {
                    // P15.83c FIX B: Complete finishpcallk's error path.
                    // All C-frame TBC closers have run. Place the final error
                    // object at funcidx, clear recovery flags, restore
                    // allowhook/errfunc, then fall through to k invocation
                    // with the error status.
                    const funcidx = fr.u.c.aux.funcidx;
                    // The final error value: if a closer errored, cs.error_value
                    // was updated (last-error-wins). Otherwise, cs.error_value
                    // is the original error (set by callCFunction).
                    const final_err = cs.error_value orelse (if (self.err_has_obj) self.err_obj else .Nil);
                    self.err_obj = final_err;
                    self.err_has_obj = true;
                    // Determine the final error status:
                    // - If a closer errored, cs.error_status is 2 (LUA_ERRRUN).
                    // - Otherwise, use CIST_RECST (set by precover: 2 or 5).
                    const final_status: i32 = if (cs.error_status != 0)
                        cs.error_status
                    else
                        @intCast(getcistrecst(fr.callstatus));
                    // PUC: luaD_seterrorobj(L, status, func) — place error at funcidx.
                    if (funcidx < self.bc_stack.len) {
                        self.bc_stack[funcidx] = final_err;
                        self.bc_stack_top = funcidx + 1;
                    }
                    // PUC: luaD_shrinkstack(L)
                    self.shrinkBcStack();
                    // PUC: setcistrecst(ci, LUA_OK) — clear saved status.
                    fr.callstatus = setcistrecst(fr.callstatus, 0);
                    // PUC: L->allowhook = getoah(ci) — restore allowhook.
                    th.allowhook = getoah(fr.callstatus);
                    // PUC: ci->callstatus &= ~CIST_YPCALL
                    fr.clearYpcall();
                    // Clear CIST_CLSRET (close complete).
                    fr.clearClsret();
                    // PUC: L->errfunc = ci->u.c.old_errfunc
                    th.errfunc = fr.u.c.old_errfunc;
                    // Free clsret_state (remaining_tbc already freed above,
                    // results is &.{} for pcall_error_close).
                    self.alloc.destroy(cs);
                    fr.u.c.clsret_state = null;
                    // Set status for k invocation and skip finishpcallk
                    // (already completed above).
                    status = final_status;
                    skip_finishpcallk = true;
                    // Fall through to k invocation below.
                },
            }
        }

        // PUC: status = LUA_YIELD (1). APIstatus(LUA_YIELD) = LUA_YIELD (1)
        // — APIstatus is a no-op (llimits.h:50: cast_int(st)). k receives
        // LUA_YIELD for a plain yield resume.
        // If CIST_YPCALL and error occurred, finishpcallk returns the error
        // status, and APIstatus passes it through (non-YIELD statuses are
        // passed as-is).
        // P15.83c FIX B: `status` and `skip_finishpcallk` are declared above
        // the CLSRET block so pcall_error_close completion can set them and
        // fall through to the k invocation here.
        const kf = fr.u.c.k;

        // PUC: if CIST_YPCALL, status = finishpcallk(L, ci).
        // finishpcallk restores allowhook/errfunc, handles TBC close and
        // error-object placement, clears CIST_YPCALL, and returns the status
        // to pass to k (LUA_YIELD for plain yield, error status for errors).
        // P15.83c FIX B: Skip finishpcallk if pcall_error_close already
        // completed it in the CLSRET path above.
        if (!skip_finishpcallk and fr.isYpcall()) {
            status = self.finishpcallk(th);
        }

        // PUC: adjustresults(L, LUA_MULTRET) — no-op for MULTRET.

        // P15.78: After finishCcall returns, poscallCFrame pops the C-frame,
        // and the trampoline resumes the Lua frame below via runBytecodeInternal
        // with resume_in_place. The Lua frame's PC is at the OP_CALL that
        // called the C function. On resume, the OP_CALL must NOT re-call the
        // C function — instead, it must use the results from k (or the resume
        // values for k==NULL) as the OP_CALL results.
        //
        // We achieve this by setting isHookYield + resume_pc on the Lua frame
        // below the C-frame, and putting the results in th.resume_inbox. The
        // opCall dispatch checks isHookYield at the top: if set, it takes the
        // values from resume_inbox and stores them as the OP_CALL results,
        // then advances the PC. This is the same mechanism used for
        // coroutine.yield (parkDirectBytecodeYield sets isHookYield).

        // PUC: n = (*kf)(L, APIstatus(status), ci->u.c.ctx)
        // APIstatus(st) = cast_int(st) — no conversion (llimits.h:50).
        // In vendored Lua 5.5, LUA_YIELD == 1 and is passed as-is to k.
        if (kf) |k| {
            // Continuation invocation — k runs in the existing suspended C-frame.
            // k pushes results onto c_stack and returns the count.
            //
            // P15.78: k is a C function that uses the C API (c_stack).
            // We give it a clean c_stack (swapping out the current one)
            // so its results don't corrupt the caller's c_stack. After k
            // returns, we put the results in th.resume_inbox for the Lua
            // frame's OP_CALL to pick up via takeBytecodeResumeValues.
            //
            // P15.78 multi-yield: k may itself call lua_yieldk to yield again.
            // In PUC, lua_yieldk longjmps to the lua_resume boundary. In
            // luazig, lua_yieldk _longjmps to c_error_jmp, so we invoke k
            // through callCFunctionWithBoundary (via the callContShim wrapper)
            // to provide a proper setjmp/longjmp landing pad. Without this,
            // the _longjmp would target a stale/null boundary and the yield
            // would be lost (lua_yieldk would return 1 instead of longjmp'ing,
            // and finishCcall would treat it as a normal return, popping the
            // C-frame and breaking the yield chain).
            // PUC ldo.c:853: n = (*kf)(L, APIstatus(status), ci->u.c.ctx)
            // APIstatus(st) = cast_int(st) — no conversion. k receives the
            // raw status: LUA_YIELD (1) for plain yield, or the error status
            // for pcallk errors.
            const api_status: c_int = @intCast(status);
            const saved_c_stack = self.cur_c_stack.*;
            self.cur_c_stack.* = .empty;

            // PUC: if error status (not LUA_YIELD), luaD_seterrorobj has
            // already placed the error object on the Lua stack at func.
            // k reads it via lua_tostring(L, 1) etc. In luazig, k uses
            // c_stack, so we place the error object on c_stack[0] for k
            // to read via lua_to*(L, 1). This mirrors PUC's
            // luaD_seterrorobj(L, status, func) which sets L->top = func + 1.
            if (status != 1) { // not LUA_YIELD — error status
                if (self.err_has_obj) {
                    self.cur_c_stack.append(self.alloc, self.err_obj) catch {
                        self.cur_c_stack.deinit(self.alloc);
                        self.cur_c_stack.* = saved_c_stack;
                        return error.OutOfMemory;
                    };
                }
            }

            // Store continuation params for callContShim.
            self.c_cont_k = k;
            self.c_cont_status = api_status;
            self.c_cont_ctx = fr.u.c.ctx;

            // Invoke k through the setjmp/longjmp boundary. Returns:
            //   >= 0: normal return, value is result count
            //   -1:    lua_error was called inside k
            //   -2:    lua_yieldk was called inside k (yield)
            //   -3:    ThreadSwitch — a __close metamethod triggered a
            //          coroutine switch via coroutine.resume. The C-frame
            //          is preserved (like yield), but the trampoline must
            //          process the switch request instead of parking as
            //          a yield.
            const nret_signed = self.callCFunctionWithBoundary(&callContShim);

            // Clear the continuation params.
            self.c_cont_k = null;

            if (nret_signed == -3) {
                // ThreadSwitch: a __close metamethod inside the C
                // continuation triggered a coroutine switch. The C-frame
                // is preserved (testc_state stays). Clean up c_stack and
                // propagate ThreadSwitch so the trampoline processes the
                // switch request.
                self.cur_c_stack.deinit(self.alloc);
                self.cur_c_stack.* = saved_c_stack;
                return error.ThreadSwitch;
            }

            if (nret_signed == -2) {
                // k yielded via lua_yieldk. The yielded values are already
                // stored in th.yielded by builtinCoroutineYield (before the
                // _longjmp). The C-frame's k/ctx have been updated by
                // lua_yieldk for the next resume. Clean up c_stack and leave
                // the C-frame in place (NOT popped) so finishCcall runs again
                // on the next resume.
                // P15.83c FIX B: Snapshot TBC values from k's c_stack before
                // freeing it, so they can be closed on resume-error.
                self.snapshotYieldedTbc(th_bc.len() - 1);
                self.cur_c_stack.deinit(self.alloc);
                self.cur_c_stack.* = saved_c_stack;
                return error.Yield;
            }

            if (nret_signed < 0) {
                // k called lua_error. The error object is in c_error_value
                // (if k used the C API lua_error) or already in err_obj
                // (if k's script used the Lua error() builtin, which sets
                // err_obj directly without going through c_error_value).
                // Don't overwrite err_obj if c_error_value is null — the
                // error builtin may have already set it.
                self.cur_c_stack.deinit(self.alloc);
                self.cur_c_stack.* = saved_c_stack;
                if (self.c_error_value) |cv| {
                    self.c_error_value = null;
                    self.err_obj = cv;
                    self.err_has_obj = true;
                }
                // If c_error_value was null but err_has_obj is true,
                // err_obj was already set by the error builtin.
                if (!self.err_has_obj) {
                    self.err_obj = .Nil;
                    self.err_has_obj = true;
                }
                const errval = self.err_obj;
                self.err = if (errval == .String) errval.String.bytes() else null;
                self.err_source = null;
                self.err_line = -1;
                self.captureErrorTraceback();
                return error.RuntimeError;
            }

            // Normal return: collect results from c_stack into resume_inbox.
            const n: i32 = nret_signed;
            const n_usize: usize = @intCast(@max(n, 0));
            if (n_usize > 0) {
                const c_top = self.cur_c_stack.items.len;
                const src_start = if (c_top >= n_usize) c_top - n_usize else 0;
                const actual_n = if (c_top >= n_usize) n_usize else c_top;
                const results = self.alloc.alloc(Value, actual_n) catch {
                    self.cur_c_stack.deinit(self.alloc);
                    self.cur_c_stack.* = saved_c_stack;
                    return error.OutOfMemory;
                };
                for (0..actual_n) |i| {
                    results[i] = self.cur_c_stack.items[src_start + i];
                }
                th.resume_inbox.setOwned(self.alloc, results);
            } else {
                th.resume_inbox.deinit(self.alloc);
            }
            // Restore c_stack
            self.cur_c_stack.deinit(self.alloc);
            self.cur_c_stack.* = saved_c_stack;
            // Set isHookYield on the Lua frame below the C-frame so the
            // OP_CALL dispatch uses resume_inbox values instead of re-calling.
            // P15.78: Skip stale C-frames (testc_state=null, k=testcContShim)
            // when searching for the Lua frame — these are leftovers from the
            // yieldk chain that will be popped by the resume loop.
            {
                var fi: usize = th_bc.len();
                while (fi > 0) {
                    fi -= 1;
                    const f = th_bc.getPtr(fi);
                    if (!f.isC()) {
                        f.setHookYield();
                        f.u.lua.resume_pc = @intCast(f.u.lua.pc);
                        break;
                    }
                    // Skip stale C-frames (will be popped by resume loop).
                    // Stop if we hit a C-frame with active testc_state.
                    if (f.u.c.testc_state != null) break;
                }
            }
            return @intCast(n);
        } else {
            // k == NULL: plain yield without continuation.
            // PUC: poscall with resume nargs (not nyield). nyield was used
            // for lua_resume(&nresults) at yield time, not for poscall.
            // The resume values are already in th.resume_inbox (set by
            // builtinCoroutineResume). Set isHookYield so the OP_CALL
            // dispatch uses them instead of re-calling the C function.
            //
            // P15.79: If CIST_YPCALL was set (pcall C-frame) and the
            // status is an error (not LUA_YIELD), format the results as
            // pcall failure: false, error_object. finishpcallk already
            // placed the error object on bc_stack[funcidx] and restored
            // errfunc. We put the formatted results in resume_inbox for
            // the caller (builtinCoroutineResume) to pick up.
            if (status != 1) {
                // Error status — pcall caught the error.
                const funcidx = fr.u.c.aux.funcidx;
                const errv = if (funcidx < self.bc_stack.len)
                    self.bc_stack[funcidx]
                else
                    self.protectedErrorValue();
                const results = try self.alloc.alloc(Value, 2);
                results[0] = .{ .Bool = false };
                results[1] = errv;
                if (th.resume_inbox.slice()) |old| self.alloc.free(old);
                th.resume_inbox.setOwned(self.alloc, results);
                // Set isHookYield on the Lua frame below so the OP_CALL
                // dispatch uses resume_inbox values instead of re-calling
                // the C function (pcall). Without this, runBytecodeInternal
                // re-executes the OP_CALL, re-running pcall → testC →
                // closers, causing double-close.
                if (th_bc.len() >= 2) {
                    var fi: usize = th_bc.len();
                    while (fi > 0) {
                        fi -= 1;
                        const f = th_bc.getPtr(fi);
                        if (!f.isC()) {
                            f.setHookYield();
                            f.u.lua.resume_pc = @intCast(f.u.lua.pc);
                            break;
                        }
                    }
                }
                return 2;
            }
            // P15.82: Search for the Lua frame below ALL C-frames, not just
            // th_bc.len()-2. When __close yields during return-path close,
            // there may be multiple C-frames on top of the Lua frame.
            {
                var fi: usize = th_bc.len();
                while (fi > 0) {
                    fi -= 1;
                    const f = th_bc.getPtr(fi);
                    if (!f.isC()) {
                        f.setHookYield();
                        f.u.lua.resume_pc = @intCast(f.u.lua.pc);
                        break;
                    }
                }
            }
            const nargs = if (th.resume_inbox.slice()) |ri| @as(i32, @intCast(ri.len)) else 0;
            return nargs;
        }
    }

    /// PUC `luaD_poscall` for C-frames: move n results and pop the C-frame.
    ///
    /// In PUC, `luaD_poscall` calls `move2result` to shift results from the
    // callee's area to the caller's result registers, then pops the CallInfo.
    /// In luazig, `bc_stack_top` is restored to `func_slot + 1 + n` (the
    // function value plus n results), and the C-frame is popped from
    // `call_frames`. The Lua frame below will pick up the results from
    // `bc_stack[func_slot + 1 .. func_slot + 1 + n]` via the normal
    // OP_CALL result handling.
    fn poscallCFrame(self: *Vm, th: *Thread, n: i32) DispatchError!void {
        _ = n; // Results are consumed via resume_inbox, not bc_stack.
        const th_bc = &th.call_frames;
        const cur_len = th_bc.len();
        if (cur_len == 0) return;
        const fr = th_bc.getPtr(cur_len - 1);
        // P15.80: Free heap-allocated testc_state before shrinking.
        // Without this, the pointer is lost and the allocation leaks.
        if (fr.isC()) self.freeCFrameOwnedState(fr);
        th_bc.shrinkTo(cur_len - 1);
        // PUC model: restore bc_stack_top to the caller's frame capacity,
        // mirroring popBytecodeExecFrame (line ~10533). The C-frame's results
        // are consumed via resume_inbox (set by finishCcall), NOT from
        // bc_stack — so bc_stack_top must point to the caller's register
        // limit, not to saved_func_slot + 1 + n. Without this, bc_stack_top
        // grows by 2 per yield/resume cycle (pushBuiltinCFrame +1,
        // poscallCFrame +1), causing unbounded bc_stack/bc_boxed growth.
        if (th_bc.len() > 0) {
            const caller = th_bc.getConstPtr(th_bc.len() - 1);
            if (!caller.isC()) {
                self.bc_stack_top = caller.frameBase() + caller.u.lua.frame_cap;
            } else {
                // C-frame caller: restore bc_stack_top to the C-frame's base
                // (= func_slot + 1), matching popBytecodeExecFrame's C-frame
                // caller path.
                self.bc_stack_top = caller.frameBase();
            }
        } else {
            self.bc_stack_top = 0;
        }
    }

    /// Discard a C-frame WITHOUT calling its continuation (k).
    ///
    /// PUC `luaE_resetthread` → `resetCI` (lstate.c:146-155): drops ALL
    /// CallInfos back to `base_ci` without invoking any C continuation
    /// (`ci->u.c.k = NULL`). The TBC variables are closed separately by
    /// `luaD_closeprotected` → `luaF_close`, which traverses the stack's
    /// `tbclist` — NOT the CallInfos.
    ///
    /// In luazig, `lua_closethread` (close_mode) must mirror this: discard
    /// C-frames (free owned state + pop) WITHOUT calling `finishCcall`/k.
    /// The Lua-frame TBC variables are closed by the existing forced-close
    /// unwind (`appendBytecodeForcedCloseUnwind` in `runBytecodeInternal`'s
    /// `resume_in_place and close_mode` branch), which runs `__close` for
    /// each Lua frame's TBC variables.
    ///
    /// C-frame TBC (`clsret_state.remaining_tbc`): PUC closes these via
    /// `luaF_close` which traverses the stack's `tbclist`. In luazig, these
    /// TBC values are stored in `clsret_state`, not on the Lua stack. They
    /// are freed (not closed) here — a deviation for the rare pcallk-error-
    /// recovery-with-TBC case. The common case (Lua-level TBC in Lua frames)
    /// is handled correctly by the forced-close unwind.
    fn discardCFrame(self: *Vm, th: *Thread) void {
        const th_bc = &th.call_frames;
        const cur_len = th_bc.len();
        if (cur_len == 0) return;
        const fr = th_bc.getPtr(cur_len - 1);
        if (!fr.isC()) return;
        const saved_func_slot = fr.func_slot;
        self.freeCFrameOwnedState(fr);
        self.bc_stack_top = saved_func_slot + 1;
        th_bc.shrinkTo(cur_len - 1);
    }

    /// Drive a chain of bytecode coroutine.resume/wrap calls without nesting
    /// `builtinCoroutineResume` or `runBytecode` on the Zig stack. Each switch
    /// parks the active Thread runtime and activates the target's owned buffers.
    fn driveBytecodeCoroutineTrampoline(
        self: *Vm,
        initial: *Thread,
        initial_closure: *Closure,
        initial_args: []const Value,
    ) DispatchError!BytecodeCoroutineStep {
        std.debug.assert(!self.bytecode_coroutine_trampoline_active);
        std.debug.assert(self.current_thread == initial);
        self.bytecode_coroutine_trampoline_active = true;
        defer {
            self.bytecode_coroutine_trampoline_active = false;
            if (self.bytecode_coroutine_switch_request) |request| {
                self.alloc.free(request.args);
                self.bytecode_coroutine_switch_request = null;
            }
        }

        var active = initial;
        var first_run = true;
        var needs_call_hook = false;
        // PUC Lua limits coroutine nesting via LUAI_MAXCCALLS (200): each
        // lua_resume inherits getCcalls(from)+1, so ~200 nested resumes are
        // possible before "C stack overflow".  The trampoline is iterative
        // (no physical C-stack growth), so we simulate this with a logical
        // chain-depth counter.  PUC's nCcalls tracks C-call depth, NOT total
        // Lua stack frames — a coroutine with 1000 Lua frames still only
        // consumes ONE C-call slot.  Do NOT conflate Lua frame count with
        // C-call depth (the old coroutine_parked_frames metric did this,
        // capping nesting at 5 coroutines * 1000 frames = 5000 frames).
        const luai_maxccalls: usize = 200;
        // The initial chain depth accounts for the C-call overhead already
        // on the stack (xpcall/pcall and builtinCoroutineResume itself).
        // This mirrors PUC where getCcalls(from) already includes those
        // frames before lua_resume adds its own +1.
        var coroutine_resume_chain: usize = self.activeProtectedCallDepth() + 1;

        drive: while (true) {
            var step: BytecodeCoroutineStep = undefined;
            var have_step = false;

            if (needs_call_hook) {
                needs_call_hook = false;
                // Bytecode-Closure bodies get their CALL event at the body
                // frame's creation (runBytecodeInternal →
                // dispatchCalleeActivationHook, mirroring PUC luaG_tracecall);
                // this trampoline site only covers bodies without bytecode
                // frames (C/builtin bodies). See builtinCoroutineResume.
                const switch_body_is_bc = switch (active.callee) {
                    .Closure => |cl| cl.proto != null,
                    else => false,
                };
                if (!switch_body_is_bc) self.debugDispatchHookWithCalleeTransfer(
                    "call",
                    null,
                    active.callee,
                    active.entry_args orelse &[_]Value{},
                    1,
                    null,
                ) catch |hook_err| {
                    switch (hook_err) {
                        error.RuntimeError => step = .{ .failed = try self.currentRuntimeErrorValue() },
                        error.OutOfMemory => return error.OutOfMemory,
                        error.Yield => step = try self.bytecodeCoroutineYieldStep(active, active == initial),
                        error.ThreadSwitch => return error.ThreadSwitch,
                    }
                    have_step = true;
                };
            }

            if (!have_step) {
                // PUC `resume` (ldo.c:916-944): after resume, check isLua(ci).
                // If Lua: continue bytecode execution (the runClosure path below).
                // If C: call finishCcall (invoke k continuation, pop C-frame).
                // This mirrors PUC's `resume` → `unroll` → `finishCcall` chain.
                // The C-frame check must happen BEFORE runClosure, because a
                // C-frame on top means the coroutine yielded from a C function
                // via lua_yieldk — the continuation k must be invoked, not the
                // coroutine body re-executed.
                {
                    const th_bc = active.call_frames;
                    if (th_bc.len() > 0) {
                        const fr = th_bc.getConstPtr(th_bc.len() - 1);
                        if (fr.isC()) {
                            // C-frame resume: finishCcall equivalent.
                            // k is called via raw invocation (no new C-frame),
                            // then poscallCFrame moves results and pops the frame.
                            //
                            // P15.78 multi-yield: k may itself call lua_yieldk
                            // to yield again. finishCcall returns error.Yield
                            // in that case; we create a yield step (like
                            // runClosure's error.Yield path) and leave the
                            // C-frame in place for the next resume.
                            const fc_result = self.finishCcall(active);
                            if (fc_result) |n| {
                                try self.poscallCFrame(active, n);
                                // After poscall, the C-frame is popped. The frame
                                // below may be Lua (continue bytecode via
                                // runClosure) or another C-frame (finishCcall
                                // again). Loop back to re-check.
                                // If the frame below is Lua, mark it as
                                // bytecode_inplace_suspended so runBytecodeInternal
                                // resumes from the existing frame (with
                                // isHookYield set by finishCcall) instead of
                                // pushing a new frame and re-executing from the
                                // beginning. This mirrors PUC's `unroll` which
                                // calls `luaV_execute` on the existing CallInfo.
                                if (active.call_frames.len() > 0) {
                                    const below = active.call_frames.getConstPtr(active.call_frames.len() - 1);
                                    if (!below.isC()) {
                                        active.bytecode_inplace_suspended = true;
                                        // P15.78: Set boundary = 0 so runBytecodeInternal
                                        // resumes with boundary_depth = 0 (outermost call),
                                        // continuing through all Lua frames until completion
                                        // or next yield. The previous value (set by pcallk/
                                        // callk) is stale after the C-frame was popped.
                                        active.bytecode_resume_boundary = 0;
                                    }
                                } else {
                                    // P15.78: No more frames — coroutine is
                                    // complete. The continuation's results are
                                    // in resume_inbox. Return them as the
                                    // coroutine's return values.
                                    const ri = active.resume_inbox.slice() orelse &[_]Value{};
                                    const results = try self.alloc.alloc(Value, ri.len);
                                    for (ri, 0..) |v, i| results[i] = v;
                                    active.resume_inbox.deinit(self.alloc);
                                    step = .{ .returned = results };
                                    have_step = true;
                                }
                                continue :drive;
                            } else |e| switch (e) {
                                error.Yield => {
                                    step = try self.bytecodeCoroutineYieldStep(active, active == initial);
                                    have_step = true;
                                },
                                error.ThreadSwitch => {
                                    // A __close metamethod inside the C
                                    // continuation triggered a coroutine
                                    // switch. Process it the same way as
                                    // the runClosure ThreadSwitch path
                                    // below: switch to the target thread
                                    // and continue the trampoline loop.
                                    const request = self.bytecode_coroutine_switch_request orelse return e;
                                    self.bytecode_coroutine_switch_request = null;
                                    if (coroutine_resume_chain >= luai_maxccalls) {
                                        self.alloc.free(request.args);
                                        request.target.caller = request.caller;
                                        active = request.target;
                                        coroutine_resume_chain += 1;
                                        step = .{ .failed = .{ .String = try self.internStr("C stack overflow") } };
                                        have_step = true;
                                        continue :drive;
                                    }
                                    const first_start = try self.prepareBytecodeCoroutineSwitch(request);
                                    coroutine_resume_chain += 1;
                                    active = request.target;
                                    needs_call_hook = first_start and !self.isInDebugHook();
                                    first_run = false;
                                    continue :drive;
                                },
                                error.RuntimeError => {
                                    // PUC precover: find the innermost
                                    // CIST_YPCALL frame for error recovery.
                                    // If found, save the error status, pop
                                    // frames above it, and continue the drive
                                    // loop — finishCcall will handle it via
                                    // finishpcallk → k. This mirrors the
                                    // runClosure RuntimeError path below.
                                    if (self.precover(active)) {
                                        continue :drive;
                                    }
                                    // Not recovered: unrecoverable error
                                    step = .{ .failed = try self.currentRuntimeErrorValue() };
                                    have_step = true;
                                },
                                else => return e,
                            }
                        }
                    }
                }

                if (!have_step) {
                    const closure: *Closure = if (first_run) initial_closure else blk: {
                        if (active.callee != .Closure or active.callee.Closure.proto == null)
                            return self.fail("coroutine.resume: bad thread", .{});
                        break :blk active.callee.Closure;
                    };
                    const args = if (first_run) initial_args else active.entry_args orelse &[_]Value{};
                    first_run = false;

                    const ret_opt: ?[]Value = retblk: {
                        const values = self.runClosure(closure, args) catch |run_err| switch (run_err) {
                            error.ThreadSwitch => {
                                const request = self.bytecode_coroutine_switch_request orelse unreachable;
                                self.bytecode_coroutine_switch_request = null;
                                // PUC-faithful C-stack-overflow check: the only
                                // limit is the resume-chain depth (analogous to
                                // LUAI_MAXCCALLS).  Each coroutine switch adds 1
                                // to the chain, matching PUC's lua_resume which
                                // does getCcalls(from)+1 per nesting level.
                                if (coroutine_resume_chain >= luai_maxccalls) {
                                    self.alloc.free(request.args);
                                    request.target.caller = request.caller;
                                    active = request.target;
                                    coroutine_resume_chain += 1;
                                    step = .{ .failed = .{ .String = try self.internStr("C stack overflow") } };
                                    break :retblk null;
                                }
                                const first_start = try self.prepareBytecodeCoroutineSwitch(request);
                                coroutine_resume_chain += 1;
                                active = request.target;
                                needs_call_hook = first_start and !self.isInDebugHook();
                                first_run = false;
                                continue :drive;
                            },
                            error.Yield => {
                                step = try self.bytecodeCoroutineYieldStep(active, active == initial);
                                break :retblk null;
                            },
                            error.RuntimeError => {
                                // PUC precover (ldo.c:955-963): find the innermost
                                // CIST_YPCALL frame for error recovery. If found,
                                // save the error status, pop frames above it, and
                                // continue the drive loop — the C-frame on top will
                                // be handled by finishCcall → finishpcallk → k.
                                if (self.precover(active)) {
                                    // Recovered: continue the drive loop. The
                                    // C-frame with CIST_YPCALL is on top;
                                    // finishCcall will handle it.
                                    continue :drive;
                                }
                                // Not recovered: unrecoverable error
                                if (active.yielded.slice() != null and active.capture_yield_id != 0) {
                                    step = try self.bytecodeCoroutineYieldStep(active, active == initial);
                                } else if (self.forced_close_thread == active and active.close_mode and !self.forced_close_had_error and !self.isStackOverflowRuntimeError()) {
                                    step = .forced_close;
                                } else {
                                    step = .{ .failed = try self.currentRuntimeErrorValue() };
                                }
                                break :retblk null;
                            },
                            error.OutOfMemory => return error.OutOfMemory,
                        };
                        break :retblk values;
                    };
                    post_runclosure: {
                        if (ret_opt) |values| {
                            // P15.78 Task 13: After runClosure returns (resuming a
                            // callee that yielded via callk/pcallk), check if a C-frame
                            // is now on top. If so, the callee's return values go to
                            // resume_inbox, and finishCcall → testcContShim runs the
                            // continuation. This mirrors PUC's `unroll` which, after
                            // resuming a Lua frame that returns, checks if the next
                            // frame is C and calls finishCcall.
                            if (active.call_frames.len() > 0) {
                                const top_fr = active.call_frames.getConstPtr(active.call_frames.len() - 1);
                                if (top_fr.isC()) {
                                    // Put callee's return values in resume_inbox.
                                    try self.setThreadResumeInbox(active, values);
                                    self.alloc.free(values);

                                    // P15.78: Clear bytecode_inplace_suspended before
                                    // calling finishCcall, because testcContShim may
                                    // call runTestcCloseMetamethod → runClosure →
                                    // runBytecodeInternal. If bytecode_inplace_suspended
                                    // is true, runBytecodeInternal would try resume_in_place
                                    // instead of pushing a new Lua frame for the __close
                                    // metamethod, causing a crash or silent skip.
                                    // NOTE: Do NOT save/restore bytecode_inplace_suspended
                                    // here. If finishCcall yields, parkDirectBytecodeYield
                                    // (called from within finishCcall → testcContShim →
                                    // runBytecodeInternal) sets bytecode_inplace_suspended
                                    // = true for the __close frame. Restoring the old
                                    // value (false) would break resume_in_place on the
                                    // next resume, causing runBytecodeInternal to push a
                                    // new Lua wrapper frame instead of resuming the
                                    // __close frame.
                                    active.bytecode_inplace_suspended = false;

                                    const fc_result = self.finishCcall(active) catch |e| switch (e) {
                                        error.Yield => {
                                            step = try self.bytecodeCoroutineYieldStep(active, active == initial);
                                            have_step = true;
                                            break :post_runclosure;
                                        },
                                        error.ThreadSwitch => {
                                            const request = self.bytecode_coroutine_switch_request orelse return @as(DispatchError, e);
                                            self.bytecode_coroutine_switch_request = null;
                                            if (coroutine_resume_chain >= luai_maxccalls) {
                                                self.alloc.free(request.args);
                                                request.target.caller = request.caller;
                                                active = request.target;
                                                coroutine_resume_chain += 1;
                                                step = .{ .failed = .{ .String = try self.internStr("C stack overflow") } };
                                                have_step = true;
                                                continue :drive;
                                            }
                                            const first_start = try self.prepareBytecodeCoroutineSwitch(request);
                                            coroutine_resume_chain += 1;
                                            active = request.target;
                                            needs_call_hook = first_start and !self.isInDebugHook();
                                            first_run = false;
                                            continue :drive;
                                        },
                                        error.RuntimeError => {
                                            // PUC precover: find the innermost
                                            // CIST_YPCALL frame for error recovery.
                                            if (self.precover(active)) {
                                                continue :drive;
                                            }
                                            // Not recovered: unrecoverable error
                                            step = .{ .failed = try self.currentRuntimeErrorValue() };
                                            have_step = true;
                                            break :post_runclosure;
                                        },
                                        else => return @as(DispatchError, e),
                                    };
                                    try self.poscallCFrame(active, fc_result);

                                    // Set up for resuming the Lua frame below.
                                    if (active.call_frames.len() > 0) {
                                        const below = active.call_frames.getConstPtr(active.call_frames.len() - 1);
                                        if (!below.isC()) {
                                            active.bytecode_inplace_suspended = true;
                                            active.bytecode_resume_boundary = active.call_frames.len() - 1;
                                        }
                                    } else {
                                        // P15.78: No more frames — coroutine is
                                        // complete. Results are in resume_inbox.
                                        const ri = active.resume_inbox.slice() orelse &[_]Value{};
                                        const results = try self.alloc.alloc(Value, ri.len);
                                        for (ri, 0..) |v, i| results[i] = v;
                                        active.resume_inbox.deinit(self.alloc);
                                        step = .{ .returned = results };
                                        have_step = true;
                                    }
                                    continue :drive;
                                }
                            }
                            step = .{ .returned = values };
                        }
                    }
                }
            }

            bubble: while (active != initial) {
                const child = active;
                const parent = child.caller orelse unreachable;
                const child_step = step;
                self.finishNestedBytecodeCoroutine(child, child_step);
                self.current_thread = parent;
                self.switchRuntime(parent);
                child.caller = null;
                std.debug.assert(coroutine_resume_chain > 1);
                coroutine_resume_chain -= 1;
                parent.status = .running;
                active = parent;

                const exec_frames = &parent.call_frames;
                if (exec_frames.len() == 0) return self.fail("coroutine trampoline lost caller frame", .{});
                const parent_index = exec_frames.len() - 1;
                const pending = self.getPendingCallConst(exec_frames.getPtr(parent_index).pending_call_index) orelse
                    return self.fail("coroutine trampoline lost continuation", .{});
                const cont = switch (pending.completion) {
                    .coroutine_resume => |value| value,
                    else => return self.fail("coroutine trampoline continuation mismatch", .{}),
                };
                std.debug.assert(cont.target == child);

                var applied: DispatchError!?[]Value = undefined;
                switch (child_step) {
                    .returned => |values| {
                        const call_values = try self.wrapBytecodeCoroutineValues(cont.kind, true, values);
                        applied = self.completeBytecodeCoroutineResult(exec_frames, parent_index, call_values, cont);
                    },
                    .yielded => |values| {
                        const call_values = try self.wrapBytecodeCoroutineValues(cont.kind, true, values);
                        applied = self.completeBytecodeCoroutineResult(exec_frames, parent_index, call_values, cont);
                    },
                    .failed => |error_value| {
                        if (cont.kind == .resume_call) {
                            const one = try self.alloc.alloc(Value, 1);
                            one[0] = error_value;
                            const call_values = try self.wrapBytecodeCoroutineValues(cont.kind, false, one);
                            applied = self.completeBytecodeCoroutineResult(exec_frames, parent_index, call_values, cont);
                        } else {
                            self.discardBytecodeSavedError(cont.saved_error);
                            self.alloc.destroy(cont);
                            self.clearPendingCall(exec_frames.getPtr(parent_index));
                            self.restoreRuntimeErrorValue(error_value);
                            applied = error.RuntimeError;
                        }
                    },
                    .forced_close => unreachable,
                }

                const completed = applied catch |apply_err| switch (apply_err) {
                    error.RuntimeError => {
                        if (try self.recoverTrampolineParentError(parent)) |parent_step| {
                            step = parent_step;
                            continue :bubble;
                        }
                        continue :drive;
                    },
                    error.OutOfMemory => return error.OutOfMemory,
                    error.Yield => {
                        step = try self.bytecodeCoroutineYieldStep(parent, parent == initial);
                        continue :bubble;
                    },
                    error.ThreadSwitch => return error.ThreadSwitch,
                };
                if (completed) |ret| {
                    step = .{ .returned = ret };
                    continue :bubble;
                }
                continue :drive;
            }
            return step;
        }
    }

    /// Convert a bytecode OP_CALL to pcall/xpcall into an explicit child frame.
    /// Returns false for builtin/IR targets, which keep using the ordinary
    /// builtin implementation.  The important Lua-controlled path never calls
    /// `runBytecode` recursively.
    fn tryPushBytecodeProtectedCall(
        self: *Vm,
        exec_frames: *FrameStack,
        parent_index: usize,
        dst: u8,
        nresults: i32,
        id: BuiltinId,
        args: []const Value,
        tail_return: bool,
    ) DispatchError!bool {
        if (id != .pcall and id != .xpcall) return false;
        const owner = self.activeBytecodeThread();
        const protected_depth_before = self.protected_call_depth + owner.bytecode_protected_depth;

        const LayerSpec = struct {
            kind: BytecodeProtectedKind,
            handler: Value,
        };
        var outer_specs = std.ArrayListUnmanaged(LayerSpec).empty;
        defer outer_specs.deinit(self.alloc);

        var active_id = id;
        var active_args = args;
        while (true) {
            const min_args: usize = if (active_id == .pcall) 1 else 2;
            if (active_args.len < min_args) return false;
            const target = active_args[0];
            const nested_id = switch (target) {
                .Builtin => |builtin_id| builtin_id,
                else => break,
            };
            if (nested_id != .pcall and nested_id != .xpcall) break;
            try outer_specs.append(self.alloc, .{
                .kind = if (active_id == .pcall) .pcall else .xpcall,
                .handler = if (active_id == .xpcall) active_args[1] else .Nil,
            });
            active_args = if (active_id == .pcall) active_args[1..] else active_args[2..];
            active_id = nested_id;
        }

        const min_args: usize = if (active_id == .pcall) 1 else 2;
        if (active_args.len < min_args) return false;
        const target = active_args[0];
        const target_args = if (active_id == .pcall) active_args[1..] else active_args[2..];
        const resolved = self.resolveCallable(target, target_args, null) catch return false;
        defer if (resolved.owned_args) |owned| self.alloc.free(owned);

        // Most protected targets are bytecode closures directly. `pairs` is a
        // special yieldable C-library bridge: its __pairs metamethod may also
        // be bytecode and must share this protected continuation instead of
        // re-entering runBytecode inside builtinPcall -> builtinPairs.
        var pairs_arg_buf: [1]Value = undefined;
        var child_owned_args: ?[]Value = null;
        defer if (child_owned_args) |owned| self.alloc.free(owned);
        var child_args: []const Value = resolved.args;
        var child_debug_pairs = false;
        const cl = child: switch (resolved.callee) {
            .Closure => |closure| break :child closure,
            .Builtin => |builtin_id| {
                if (builtin_id != .pairs or resolved.args.len == 0 or resolved.args[0] != .Table) return false;
                const mm = self.getMetaFieldByObj(resolved.args[0], .pairs) orelse return false;
                pairs_arg_buf[0] = resolved.args[0];
                const mm_resolved = self.resolveCallable(mm, pairs_arg_buf[0..], null) catch return false;
                child_owned_args = mm_resolved.owned_args;
                child_args = mm_resolved.args;
                child_debug_pairs = true;
                break :child switch (mm_resolved.callee) {
                    .Closure => |closure| closure,
                    else => return false,
                };
            },
            else => return false,
        };
        const proto = cl.proto orelse return false;

        const outer_layers = try self.alloc.alloc(BytecodeProtectedLayer, outer_specs.items.len);
        var initialized_outer: usize = 0;
        var outer_armed = true;
        errdefer if (outer_armed) {
            var i = initialized_outer;
            while (i > 0) {
                i -= 1;
                const layer = outer_layers[i];
                self.restoreBytecodeSavedError(layer.saved_error);
                self.releaseBytecodeProtectedLayer(layer);
            }
            if (outer_layers.len != 0) self.alloc.free(outer_layers);
        };
        for (outer_specs.items, 0..) |spec, i| {
            outer_layers[i] = .{
                .thread = owner,
                .kind = spec.kind,
                .handler = spec.handler,
                .saved_error = self.saveBytecodeProtectedError(),
            };
            owner.bytecode_protected_depth += 1;
            initialized_outer += 1;
        }

        const saved_error = self.saveBytecodeProtectedError();
        owner.bytecode_protected_depth += 1;
        outer_armed = false;
        var active_armed = true;
        errdefer if (active_armed) {
            // Allocation can fail in errdefer; fall back to stack-allocated cleanup.
            var stack_protection: BytecodeProtectedCall = .{
                .thread = owner,
                .kind = if (active_id == .pcall) .pcall else .xpcall,
                .handler = if (active_id == .xpcall) active_args[1] else .Nil,
                .saved_error = saved_error,
                .outer_layers = outer_layers,
            };
            // This releases both the active layer and all initialized outers.
            self.finishBytecodeProtectedCall(&stack_protection);
            initialized_outer = 0;
        };

        const protection_ptr = try self.alloc.create(BytecodeProtectedCall);
        // P16.23 T6: snapshot BEFORE the target runs — nested ccalls must
        // not leak past a caught recovery (see BytecodeProtectedCall).
        protection_ptr.* = .{
            .thread = owner,
            .saved_ncalls = owner.nCcalls,
            .kind = if (active_id == .pcall) .pcall else .xpcall,
            .handler = if (active_id == .xpcall) active_args[1] else .Nil,
            .saved_error = saved_error,
            .outer_layers = outer_layers,
        };
        try self.setPendingCall(exec_frames.getPtr(parent_index), .{
            .callee = .{ .Builtin = id },
            .completion = .{ .results = .{
                .dst = dst,
                .nresults = nresults,
                .append_nil = child_debug_pairs,
                .tail_return = tail_return,
            } },
            .protection = protection_ptr,
        });
        // Once the continuation is installed, every target-start failure is
        // part of the innermost protected call. In particular, a Lua stack or
        // protected-depth limit becomes `false, error`; parked outer pcall/
        // xpcall targets then complete normally and prepend their own `true`.
        active_armed = false;
        initialized_outer = 0;
        if (protected_depth_before + outer_specs.items.len >= 200)
            return self.fail("C stack overflow", .{});

        // Push a synthetic C-frame for the pcall/xpcall builtin call.
        // In PUC, pcall/xpcall pushes a CallInfo via luaD_precall. luazig's
        // fast path doesn't push a C-frame (it causes stack management issues
        // with the frame stack). Instead, captureErrorTraceback and
        // debugBuildCurrentTraceback synthetically insert [C]: in global
        // 'pcall'/'xpcall' lines by checking pending_call.protection.
        // PUC luaB_pcall: the target + args are staged on the stack, then
        // activated (luaD_pcall → luaD_precall).
        const staged_target = try self.stageBytecodeCall(self.bc_stack_top, cl, child_args);
        try self.pushStagedBytecodeExecFrame(exec_frames, proto, staged_target.func_slot, staged_target.nargs, -1);
        // The pcall/xpcall target gets its CALL event here (PUC: pcall runs
        // the target via luaD_call → luaD_precall → luaG_tracecall).
        if (child_debug_pairs) {
            self.setDebugName(exec_frames.getPtr(parent_index), "metamethod", "pairs");
        }
        try self.dispatchCalleeActivationHook(exec_frames, .{ .Closure = cl }, child_args.len);
        return true;
    }

    fn completeBytecodeProtectedResult(
        self: *Vm,
        exec_frames: *FrameStack,
        boundary_depth: usize,
        parent_index: usize,
        ret: []Value,
    ) DispatchError!?[]Value {
        var result_roots = self.gcTempRoots();
        defer result_roots.end();
        for (ret) |value| try result_roots.add(value);

        const pending = self.getPendingCallConst(exec_frames.getPtr(parent_index).pending_call_index) orelse unreachable;
        // P15.51n: Snapshot callee and completion before reentrant operations.
        const pending_callee = pending.callee;
        const protection = pending.protection orelse unreachable;
        var completed_ret = ret;
        var outer_index = protection.outer_layers.len;
        while (outer_index > 0) {
            outer_index -= 1;
            const wrapped = try self.alloc.alloc(Value, completed_ret.len + 1);
            wrapped[0] = .{ .Bool = true };
            @memcpy(wrapped[1..], completed_ret);
            self.alloc.free(completed_ret);
            completed_ret = wrapped;
            for (completed_ret) |value| try result_roots.add(value);
        }
        self.finishBytecodeProtectedCall(protection);
        self.getPendingCallPtr(exec_frames.getPtr(parent_index).pending_call_index).?.protection = null;

        const result_cont = switch (pending.completion) {
            .results => |cont| cont,
            else => unreachable,
        };
        // pending pointer is now invalid after finishBytecodeProtectedCall
        // (which may trigger GC). Use pending_callee and result_cont below.
        if (result_cont.tail_return) {
            // Our bytecode codegen emits TAILCALL as a terminal opcode.  Pop
            // the protected builtin's caller exactly like the synchronous
            // tail-call path instead of trying to advance to a non-existent
            // RETURN instruction.
            self.clearPendingCall(exec_frames.getPtr(parent_index));
            return switch (try self.beginBytecodeClose(
                exec_frames,
                boundary_depth,
                parent_index,
                0,
                null,
                true,
                .{ .return_frame = completed_ret },
            )) {
                .resume_dispatch => null,
                .final => |final| final,
                .propagate_error => error.RuntimeError,
            };
        }

        self.clearPendingCall(exec_frames.getPtr(parent_index));
        if (try self.tryPushBytecodeDebugHook(
            exec_frames,
            parent_index,
            "return",
            null,
            pending_callee,
            completed_ret,
            1,
            .{ .store_results = .{
                .continuation = result_cont,
                .values = completed_ret,
            } },
        )) return null;
        self.dispatchBytecodeHookWithCallee("return", pending_callee, completed_ret) catch |hook_err| {
            self.alloc.free(completed_ret);
            return hook_err;
        };
        try self.setPendingCall(exec_frames.getPtr(parent_index), .{
            .callee = pending_callee,
            .completion = .{ .results = result_cont },
        });
        try self.applyBytecodePendingResults(exec_frames, parent_index, completed_ret, result_cont.dst, result_cont.nresults);
        return null;
    }

    fn finishBytecodeProtectedFailure(
        self: *Vm,
        exec_frames: *FrameStack,
        boundary_depth: usize,
        parent_index: usize,
        error_value: Value,
    ) DispatchError!?[]Value {
        var error_root = self.gcTempRoots();
        defer error_root.end();
        try error_root.add(error_value);
        const ret = try self.alloc.alloc(Value, 2);
        ret[0] = .{ .Bool = false };
        ret[1] = error_value;
        return try self.completeBytecodeProtectedResult(
            exec_frames,
            boundary_depth,
            parent_index,
            ret,
        );
    }

    fn startBytecodeXpcallHandler(
        self: *Vm,
        exec_frames: *FrameStack,
        boundary_depth: usize,
        parent_index: usize,
        first_error: Value,
    ) DispatchError!?[]Value {
        var handler_roots = self.gcTempRoots();
        defer handler_roots.end();
        var emsg = first_error;
        try handler_roots.add(emsg);
        while (true) {
            const pending = self.getPendingCallPtr(exec_frames.getPtr(parent_index).pending_call_index).?;
            const protection = pending.protection.?;
            const handler = protection.handler;

            const one_arg = [_]Value{emsg};
            const resolved = self.resolveCallable(handler, one_arg[0..], null) catch {
                if (protection.on_error_stack) {
                    return self.finishBytecodeProtectedFailure(
                        exec_frames,
                        boundary_depth,
                        parent_index,
                        .{ .String = try self.internStr("error in error handling") },
                    );
                }
                protection.handler_depth += 1;
                emsg = self.errorHandlerInput();
                try handler_roots.add(emsg);
                if (protection.handler_depth >= 256) {
                    protection.on_error_stack = true;
                    emsg = .{ .String = try self.internStr("C stack overflow") };
                    try handler_roots.add(emsg);
                }
                continue;
            };
            defer if (resolved.owned_args) |owned| self.alloc.free(owned);

            switch (resolved.callee) {
                .Closure => |cl| if (cl.proto) |proto| {
                    // PUC luaG_errormsg: the error handler runs at the top
                    // of the overflowed stack (near MAXSTACK), with only
                    // ERRORSTACKSIZE (200) headroom.  Set bc_stack_top to
                    // MAXSTACK so the handler's pushBytecodeExecFrame starts
                    // near the top, and any recursion quickly hits the
                    // ERRORSTACKSIZE limit — matching PUC behavior where
                    // xpcall(loop, loop) produces "error in error handling".
                    const MAXSTACK: usize = 1_000_000;
                    if (self.bc_stack.len > MAXSTACK and self.bc_stack_top < MAXSTACK) {
                        self.bc_stack_top = MAXSTACK;
                    }
                    // PUC luaG_errormsg → luaD_callnoyield(handler): the
                    // handler + error message are staged at L->top, then
                    // activated.
                    const staged_handler = try self.stageBytecodeCall(self.bc_stack_top, cl, resolved.args);
                    try self.pushStagedBytecodeExecFrame(exec_frames, proto, staged_handler.func_slot, staged_handler.nargs, -1);
                    // PUC luaG_errormsg → luaD_callnoyield(handler) →
                    // luaD_precall → luaG_tracecall: the error handler's
                    // activation gets its LUA_HOOKCALL here.
                    try self.dispatchCalleeActivationHook(exec_frames, resolved.callee, resolved.args.len);
                    return null;
                } else {
                    const handler_ret = self.runClosure(cl, resolved.args) catch {
                        if (protection.on_error_stack) {
                            return self.finishBytecodeProtectedFailure(
                                exec_frames,
                                boundary_depth,
                                parent_index,
                                .{ .String = try self.internStr("error in error handling") },
                            );
                        }
                        protection.handler_depth += 1;
                        emsg = self.errorHandlerInput();
                        try handler_roots.add(emsg);
                        if (protection.handler_depth >= 256) {
                            protection.on_error_stack = true;
                            emsg = .{ .String = try self.internStr("C stack overflow") };
                            try handler_roots.add(emsg);
                        }
                        continue;
                    };
                    defer self.alloc.free(handler_ret);
                    const value = try self.normalizeProtectedErrorResult(if (handler_ret.len == 0) .Nil else handler_ret[0]);
                    return self.finishBytecodeProtectedFailure(
                        exec_frames,
                        boundary_depth,
                        parent_index,
                        value,
                    );
                },
                .Builtin => |builtin_id| {
                    var out = [_]Value{Value.Nil};
                    self.callBuiltin(builtin_id, resolved.args, out[0..]) catch {
                        if (protection.on_error_stack) {
                            return self.finishBytecodeProtectedFailure(
                                exec_frames,
                                boundary_depth,
                                parent_index,
                                .{ .String = try self.internStr("error in error handling") },
                            );
                        }
                        protection.handler_depth += 1;
                        emsg = self.errorHandlerInput();
                        try handler_roots.add(emsg);
                        if (protection.handler_depth >= 256) {
                            protection.on_error_stack = true;
                            emsg = .{ .String = try self.internStr("C stack overflow") };
                            try handler_roots.add(emsg);
                        }
                        continue;
                    };
                    const value = try self.normalizeProtectedErrorResult(out[0]);
                    return self.finishBytecodeProtectedFailure(
                        exec_frames,
                        boundary_depth,
                        parent_index,
                        value,
                    );
                },
                else => unreachable,
            }
        }
    }

    fn finishBytecodeProtectedRecoveryAt(
        self: *Vm,
        exec_frames: *FrameStack,
        boundary_depth: usize,
        parent_index: usize,
    ) DispatchError!BytecodeDispatchRecovery {
        const pending = self.getPendingCallPtr(exec_frames.getPtr(parent_index).pending_call_index).?;
        const protection = pending.protection.?;
        if (protection.kind == .pcall) {
            const error_value = if (self.activeErrorHandlerDepth() != 0)
                Value{ .String = try self.internStr("error in error handling") }
            else
                self.protectedErrorValue();
            const final = try self.finishBytecodeProtectedFailure(
                exec_frames,
                boundary_depth,
                parent_index,
                error_value,
            );
            return if (final) |ret| .{ .completed = ret } else .resumed;
        }

        if (protection.phase == .target) {
            protection.phase = .handler;
            protection.thread.bytecode_error_handler_depth += 1;
        } else if (protection.on_error_stack) {
            const final = try self.finishBytecodeProtectedFailure(
                exec_frames,
                boundary_depth,
                parent_index,
                .{ .String = try self.internStr("error in error handling") },
            );
            return if (final) |ret| .{ .completed = ret } else .resumed;
        } else {
            protection.handler_depth += 1;
        }

        var error_value = self.errorHandlerInput();
        if (protection.handler_depth >= 256 and !protection.on_error_stack) {
            protection.on_error_stack = true;
            error_value = .{ .String = try self.internStr("C stack overflow") };
        }
        const final = try self.startBytecodeXpcallHandler(
            exec_frames,
            boundary_depth,
            parent_index,
            error_value,
        );
        return if (final) |ret| .{ .completed = ret } else .resumed;
    }

    fn bytecodeUnwindDisposition(
        self: *Vm,
        exec_frames: *FrameStack,
        boundary_depth: usize,
    ) struct { target_depth: usize, disposition: BytecodeUnwindDisposition } {
        var i = exec_frames.len();
        while (i > boundary_depth) {
            i -= 1;
            // PUC precover (ldo.c:955-963): a C-frame with CIST_YPCALL is a
            // recovery barrier. The error must propagate past runBytecodeInternal
            // to the trampoline, which calls precover → finishCcall → finishpcallk
            // → k. Do NOT unwind past a CIST_YPCALL frame — stop here and
            // propagate, preserving the C-frame for precover to find.
            const fr = exec_frames.getConstPtr(i);
            if (fr.isC() and fr.isYpcall()) {
                return .{
                    .target_depth = i + 1,
                    .disposition = .propagate,
                };
            }
            if (self.getPendingCallConst(exec_frames.getConstPtr(i).pending_call_index)) |pending| {
                switch (pending.completion) {
                    .close => |cont| if (cont.child_active) {
                        return .{
                            .target_depth = i + 1,
                            .disposition = .{ .close_parent = i },
                        };
                    },
                    else => {},
                }
                if (pending.protection != null) {
                    return .{
                        .target_depth = i + 1,
                        .disposition = .{ .protected_parent = i },
                    };
                }
            }
        }
        return .{ .target_depth = boundary_depth, .disposition = .propagate };
    }

    fn appendBytecodeUnwind(
        self: *Vm,
        exec_frames: *FrameStack,
        boundary_depth: usize,
        fault: BytecodeDispatchFault,
        error_value: Value,
    ) DispatchError!void {
        const recovery = self.bytecodeUnwindDisposition(exec_frames, boundary_depth);
        try self.activeBytecodeThread().bytecode_unwinds.append(self.alloc, .{
            .boundary_depth = boundary_depth,
            .target_depth = recovery.target_depth,
            .fault = fault,
            .error_value = error_value,
            .disposition = recovery.disposition,
        });
    }

    /// A running coroutine can close itself from below protected/C-call
    /// boundaries.  That reset signal is not a catchable Lua error: it must
    /// discard every recovery record and unwind the thread to its root while
    /// still executing all pending to-be-closed variables.
    fn appendBytecodeForcedCloseUnwind(
        self: *Vm,
        boundary_depth: usize,
    ) DispatchError!void {
        try self.activeBytecodeThread().bytecode_unwinds.append(self.alloc, .{
            .boundary_depth = boundary_depth,
            .target_depth = boundary_depth,
            .fault = .runtime,
            .error_value = .Nil,
            .disposition = .propagate,
        });
    }

    fn continueBytecodeErrorUnwind(
        self: *Vm,
        exec_frames: *FrameStack,
    ) DispatchError!BytecodeDispatchRecovery {
        const owner = self.activeBytecodeThread();
        unwind_loop: while (owner.bytecode_unwinds.items.len != 0) {
            const state_index = owner.bytecode_unwinds.items.len - 1;
            var state = owner.bytecode_unwinds.items[state_index];
            self.restoreRuntimeErrorValue(state.error_value);

            while (exec_frames.len() > state.target_depth) {
                const frame_index = exec_frames.len() - 1;
                if (self.getPendingCallPtr(exec_frames.getPtr(frame_index).pending_call_index)) |pending| {
                    self.cancelBytecodePendingCall(pending, exec_frames.getPtr(frame_index));
                    self.clearPendingCall(exec_frames.getPtr(frame_index));
                }

                const frame = exec_frames.getPtr(frame_index);
                if (self.bc_tbc_regs.items.len > frame.tbc_mark) {
                    owner.bytecode_unwinds.items[state_index] = state;
                    switch (try self.beginBytecodeClose(
                        exec_frames,
                        state.boundary_depth,
                        frame_index,
                        0,
                        state.error_value,
                        true,
                        .unwind_frame,
                    )) {
                        .resume_dispatch => return .resumed,
                        .final => |final| return .{ .completed = final },
                        .propagate_error => {
                            state.error_value = try self.currentRuntimeErrorValue();
                            state.fault = .runtime;
                            owner.bytecode_unwinds.items[state_index] = state;
                            continue;
                        },
                    }
                }

                if (frame.u.lua.hasOpenUpvalues())
                    self.closeBytecodeUpvaluesFrom(frame, 0);
                self.popBytecodeExecFrame(exec_frames);
            }

            _ = owner.bytecode_unwinds.pop();
            self.restoreRuntimeErrorValue(state.error_value);
            switch (state.disposition) {
                .protected_parent => |parent_index| {
                    return try self.finishBytecodeProtectedRecoveryAt(
                        exec_frames,
                        state.boundary_depth,
                        parent_index,
                    );
                },
                .close_parent => |parent_index| {
                    var pending = self.getPendingCallPtr(exec_frames.getPtr(parent_index).pending_call_index).?;
                    var close_state = switch (pending.completion) {
                        .close => |cont| cont,
                        else => unreachable,
                    };
                    self.releaseBytecodeCloseChild(close_state);
                    close_state.had_close_error = true;
                    if (self.forced_close_thread != null) self.forced_close_had_error = true;
                    close_state.close_all = true;
                    close_state.current_err = state.error_value;
                    close_state.err_depth = true;
                    pending.completion = .{ .close = close_state };
                    switch (try self.continueBytecodeClose(
                        exec_frames,
                        state.boundary_depth,
                        parent_index,
                    )) {
                        .resume_dispatch => return .resumed,
                        .final => |final| return .{ .completed = final },
                        .propagate_error => {
                            const replacement = try self.currentRuntimeErrorValue();
                            if (owner.bytecode_unwinds.items.len != 0) {
                                const outer_index = owner.bytecode_unwinds.items.len - 1;
                                owner.bytecode_unwinds.items[outer_index].error_value = replacement;
                                owner.bytecode_unwinds.items[outer_index].fault = .runtime;
                                continue :unwind_loop;
                            }
                            try self.appendBytecodeUnwind(
                                exec_frames,
                                state.boundary_depth,
                                .runtime,
                                replacement,
                            );
                            continue :unwind_loop;
                        },
                    }
                },
                .propagate => return .{ .propagate = state.fault },
            }
        }
        unreachable;
    }

    fn recoverBytecodeDispatchError(
        self: *Vm,
        exec_frames: *FrameStack,
        boundary_depth: usize,
        dispatch_err: DispatchError,
    ) DispatchError!BytecodeDispatchRecovery {
        if (dispatch_err == error.Yield or self.shouldRethrowForcedCloseFromBytecode()) {
            return .{ .propagate = .runtime };
        }
        const fault: BytecodeDispatchFault = if (dispatch_err == error.OutOfMemory)
            .out_of_memory
        else
            .runtime;
        if (fault == .out_of_memory) self.setOutOfMemoryError();
        const error_value = try self.currentRuntimeErrorValue();
        try self.appendBytecodeUnwind(exec_frames, boundary_depth, fault, error_value);
        return self.continueBytecodeErrorUnwind(exec_frames);
    }

    /// PUC-faithful staged-call ABI (P16.15 T4).
    ///
    /// PUC splits every non-OP_CALL Lua activation into two steps:
    ///
    ///   1. STAGE (luaT_callTMres, ltm.c:119-131): the caller writes
    ///      [func, args...] contiguously onto the value stack at L->top
    ///      (setobj2s x3) — the stack IS the argument-passing ABI.
    ///   2. ACTIVATE (luaD_precall LUA_VLCL, ldo.c:725-735): precall
    ///      consumes only (func slot, nresults); it derives narg from
    ///      L->top - func - 1 and NEVER classifies where the caller
    ///      stored the arguments — they are on the stack by contract.
    ///
    /// luazig's previous single-step ABI (args: []const Value) forced the
    /// activation to GUESS the argument storage origin with a pointer test
    /// (`args.ptr == &bc_stack[func_slot+1]?`) and copy host slices through
    /// an outlined `prepareHostArgs` — a decision PUC's precall never makes
    /// (P16.15 T2: classification 4.0% + host-branch/call-setup 9.2% of
    /// pushBytecodeExecFrame; prepareHostArgs prologue+marshaling 37.5% of
    /// its own symbol on the metamethod path).
    ///
    /// The new ABI mirrors PUC exactly:
    ///
    ///   - `stageBytecodeCall`  — the setobj2s sequence: reserve space for
    ///     func+args, write the callee at func_slot and the args at
    ///     func_slot+1.., return {func_slot, nargs}.
    ///   - `pushStagedBytecodeExecFrame` — the luaD_precall LUA_VLCL body:
    ///     contract is "func + nargs args already staged at func_slot".
    ///     No pointer test, no host copy, no storage-origin classification.
    ///
    /// Category-A callers (OP_CALL / OP_TFORCALL / opCall plain-Lua) have
    /// func+args already contiguous in bc_stack and know nargs locally —
    /// they call `pushStagedBytecodeExecFrame` directly (zero-copy, exactly
    /// like PUC's OP_CALL which skips the staging because the operands are
    /// already in the caller's registers).
    ///
    /// `bc_stack_top` is NOT bumped by staging: the activation owns the
    /// top update (bc_stack_top = base + frame_cap) and its errdefer
    /// restores the old top on failure — identical transactionality to the
    /// previous prepareHostArgs-based flow. Staged values above
    /// bc_stack_top are not GC-marked through bc_stack, exactly as before;
    /// their sources (caller registers / host slices / metatables) remain
    /// reachable across the stage→activate window, and the activation
    /// makes them live as frame registers.
    const StagedCall = struct {
        func_slot: usize,
        nargs: usize,
    };

    /// STAGE step (PUC luaT_callTMres setobj2s sequence, ltm.c:119-131):
    /// write [callee, args...] contiguously onto bc_stack at `func_slot`
    /// so the activation can consume slot+count. Shared and generic —
    /// every Category-B caller (metamethods, __close, hooks, protected
    /// targets, coroutine bodies) stages through this one primitive; no
    /// caller-specific fast-path copies.
    fn stageBytecodeCall(
        self: *Vm,
        func_slot: usize,
        callee_cl: ?*Closure,
        args: []const Value,
    ) DispatchError!StagedCall {
        // Reserve space for func + args only (PUC: luaT_callTMres assumes
        // EXTRA_STACK for the staged values; the frame's own space is
        // reserved by the activation's checkstackp equivalent).
        const needed = func_slot + 1 + args.len;
        if (needed > self.bc_stack.len) {
            try self.ensureBcStackCap(needed);
        }
        self.bc_stack[func_slot] = if (callee_cl) |cl|
            .{ .Closure = cl }
        else
            .Nil;
        for (args, 0..) |v, i| {
            self.bc_stack[func_slot + 1 + i] = v;
        }
        return .{ .func_slot = func_slot, .nargs = args.len };
    }

    /// ACTIVATE step (PUC luaD_precall LUA_VLCL branch, ldo.c:725-735).
    ///
    /// Contract: the callee value is at bc_stack[func_slot_in] and `nargs`
    /// arguments are at bc_stack[func_slot_in+1 .. func_slot_in+1+nargs]
    /// — either staged there by `stageBytecodeCall` (Category B) or
    /// already in place as the caller's registers (Category A, zero-copy).
    /// This function never inspects WHERE the values came from; it only
    /// consumes the slot+count, exactly like PUC's precall derives
    /// `narg = L->top.p - func - 1`.
    fn pushStagedBytecodeExecFrame(
        self: *Vm,
        exec_frames: *FrameStack,
        proto: *const bc.Proto,
        func_slot_in: usize,
        nargs: usize,
        nresults: i32,
    ) DispatchError!void {
        if (self.stats.enabled) self.stats.calls_lua_frames += 1; // P16.0b: ALL Lua activations
        // P16.10b Task 15: constants are runtime-ready by construction —
        // every closure-creation path adopts its tree at the
        // createBytecodeChunkClosure boundary (see there). The old lazy
        // first-call resolveProtoConstants is GONE from the hot path;
        // this Debug assert is the invariant's tripwire. Owner-less
        // protos are unit-test constructs and pass freely.
        if (@import("builtin").mode == .Debug) {
            if (proto.tree) |t| std.debug.assert(t.flags.constants_resolved);
        }
        // PUC Lua limits the value stack, not the number of Lua activations.
        // P16.20 T5: the independent frame-count machinery is REMOVED. Every
        // Lua activation consumes >= 3 bc_stack slots (func + frame_cap,
        // frame_cap = maxstacksize + margin >= 3), so 1M−200 soft / 1M+200
        // physical slot limits are ALWAYS reached before 1e6 frames; inside
        // an error handler the physical cap bounds handler recursion exactly
        // like PUC's ERRORSTACKSIZE headroom (PUC raises a second
        // luaD_growstack "stack overflow" there — so does the
        // handling_overflow branch below). No separate Lua-frame limit.
        // PUC: LUAI_MAXSTACK = 1000000. Physical stack is LUAI_MAXSTACK +
        // ERRORSTACKSIZE. Overflow triggers at LUAI_MAXSTACK uniformly.
        // The extra ERRORSTACKSIZE slots are physical headroom so error
        // handlers can run after overflow (the stack is unwound by pcall,
        // but the handler frame needs a few slots which are available below
        // the physical end).
        const ERRORSTACKSIZE: usize = 200;
        const lua_max_stack_slots: usize = 1_000_000;
        const lua_stack_overflow_limit: usize = lua_max_stack_slots - ERRORSTACKSIZE;
        const frame_cap: u32 = @intCast(proto.maxstacksize + EXTRA_MARGIN);

        const nparams = proto.numparams;
        // PUC-faithful overlapping model: each new frame's func starts at the
        // caller's function register position (PUC `ci->func`). Arguments
        // already live at func+1 in the caller's registers on the OP_CALL fast
        // path — no arg copy needed for the non-vararg case.
        //
        // For vararg functions WITHOUT a vararg table (PF_VAHID / "hidden
        // args"), PUC Lua's buildhiddenargs (ltm.c:255) shifts func+params UP
        // past the extra args, leaving the extra args as "hidden varargs" at
        // [ci->func - nextra .. ci->func]. This protects them from being
        // overwritten by register allocation (OP_VARARG reads them later).
        // For vararg functions WITH a table (PF_VATAB), no shift is needed —
        // VARARGPREP (first instruction) consumes the extra args into a table.
        const nextra: usize = if (proto.flags.is_vararg and nargs > nparams)
            nargs - nparams
        else
            0;
        // VAHID: virtual varargs (no table). Needs buildhiddenargs shift.
        const is_vahid: bool = proto.flags.is_vararg and nextra > 0 and proto.vararg_table_reg == bc.Proto.no_vararg_reg;

        // ── Step 2: buildhiddenargs for VAHID ──
        // PUC ltm.c buildhiddenargs: shift func+params UP past the extra args.
        // final stack: [old_func nil...nil extra0..extraN new_func param0..paramP]
        //                                                  ^ new ci->func
        // Extra args stay at their original positions and become hidden varargs
        // at [new_func - nextra .. new_func].
        // P16.10a T12: `nargs` is the staged-ABI parameter (PUC precall's
        // derived narg). The dead nil-fill loop `nparams..@max(nparams,
        // nparams)` (an empty range — VAHID requires nextra>0 i.e. nargs>
        // nparams, so missing params are impossible) was provably-redundant
        // and deleted.
        const func_slot: usize = if (is_vahid) func_slot_in + nargs + 1 else func_slot_in;
        const base = func_slot + 1;

        if (is_vahid) {
            try self.prepareVahidShift(func_slot_in, func_slot, base, nparams, frame_cap);
        }

        // PUC checkstackp overflow check: base + frame_cap must fit.
        const needed_top = base + frame_cap;
        // PUC luaD_growstack: if stack is already at ERRORSTACKSIZE
        // (bc_stack.len > MAXSTACK) AND we're inside an error handler,
        // don't trigger another overflow check — allow the handler to
        // run with the extra ERRORSTACKSIZE slots. This matches PUC's
        // "thread is handling a stack error" path in luaD_growstack.
        // However, if the handler itself needs more than the available
        // ERRORSTACKSIZE headroom (needed_top > bc_stack.len), raise
        // another error — the handler overflowed its emergency stack.
        const handling_overflow = self.bc_stack.len > lua_max_stack_slots and
            self.activeErrorHandlerDepth() > 0;
        // When handling overflow, the error handler runs with ERRORSTACKSIZE
        // headroom (200 slots).  Skip the frame-count and stack-overflow
        // checks; only fail if the handler itself exhausts the headroom.
        // This matches PUC luaD_growstack's "thread is handling a stack
        // error" path, which allows the handler to run without re-triggering
        // the overflow check.
        if (handling_overflow) {
            if (needed_top > self.bc_stack.len) {
                return self.fail("stack overflow", .{});
            }
        } else if (needed_top > lua_stack_overflow_limit) {
            // P16.10a T12: the realloc-to-PHYSICAL_LIMIT + fail body is
            // cold (only reached on actual overflow). Outlined to a
            // noinline helper to keep the allocator vtable calls and
            // bc_boxed reload out of the hot path's register pressure.
            return self.raiseFrameOverflow();
        }

        try self.ensureBcStackCap(needed_top);

        const old_stack_top = self.bc_stack_top;
        self.bc_stack_top = needed_top;
        errdefer self.bc_stack_top = old_stack_top;

        const regs = self.bc_stack[base .. base + frame_cap];
        // P15.51g: boxed no longer cached in frame — derive locally for nil-fill.
        // Nil-fill missing parameters (PUC luaD_precall behavior).
        // For VAHID, params were already copied during buildhiddenargs.
        // For non-VAHID, args are already in regs[0..nargs] — either staged
        // there by stageBytecodeCall (Category B) or in place as the caller's
        // registers (Category A, zero-copy).
        if (!is_vahid) {
            const ncopy = @min(nparams, nargs);
            for (ncopy..nparams) |i| regs[i] = .Nil;
        }

        const tbc_mark = self.bc_tbc_regs.items.len;
        errdefer self.bc_tbc_regs.items.len = tbc_mark;

        // P15.51k: callee lives at bc_stack[func_slot] (PUC's ci->func).
        // No duplicated callee field in CallFrame.
        const activation_owner = self.activeBytecodeThread();
        // P16.22 T2: the old wrap-skip-to-1 branch is REMOVED — 0 is not a
        // sentinel anywhere (equality-only guard; audit in ActivationId doc).
        activation_owner.bytecode_activation_counter +%= 1;

        // P15.40b-full: Single addOne + unified field writes (was two addOne + ~50 writes).
        // The CallFrame in Thread.call_frames holds ALL fields — no runtime copy
        // in Vm.call_frames needed. GC, ensureBcStackCap, bcGrowFrame, and debug
        // all walk Thread.call_frames for bytecode frames (added in Tasks 1-4).
        //
        // P15.37a: Avoid `frames.append(self.alloc, .{...})` because the struct
        // literal triggers a byte-wise `compiler_rt.memset` of the whole
        // CallFrame before field assignment. Instead, grow the list by one
        // slot with `addOne` (which only bumps `items.len`, no zero-init) and
        // write every field explicitly.
        //
        // CRITICAL: struct-declaration defaults (e.g. `debug_hook_transfer_start: i64 = 1`,
        // `last_hook_line: i64 = -1`) only apply to struct-literal init. Writing
        // into a reused slot does NOT re-apply them, so every field — including
        // those with non-zero defaults — must be written here. Stale values
        // from a previous frame activation would otherwise leak across reuse.
        const ef_slot = try exec_frames.addOne(self.alloc);
        errdefer exec_frames.shrinkTo(exec_frames.len() - 1);

        // Activate the .lua variant BEFORE writing .u.lua fields. Since
        // P16.20 T1 the union is an extern union (no active-arm safety tag,
        // no Debug panic on arm access) — this write is a plain store, kept
        // because every LuaFrameState field is explicitly initialized below
        // (stale data from a reused C-frame slot must not leak).
        //
        // P16.2d: `undefined` is safe: every LuaFrameState field is explicitly
        // initialized below (audited against the struct definition). Debug
        // mode's 0xaa fill catches regressions if a field is missed.
        ef_slot.u = .{ .lua = undefined };

        // Common fields (shared with IR RuntimeFrame semantics)
        ef_slot.u.lua.proto = proto;
        // P15.51k: callee is at bc_stack[func_slot] (PUC's ci->func).
        // No duplicated callee field — derived on demand.
        ef_slot.u.lua.pc = 0;

        // Bytecode-specific fields
        ef_slot.activation_id = activation_owner.bytecode_activation_counter;
        ef_slot.func_slot = func_slot; // base derived: func_slot + 1
        ef_slot.u.lua.frame_cap = frame_cap;
        ef_slot.u.lua.nextraargs = @intCast(nextra);
        // P16.2d: encodeNresults masks with CIST_NRESULTS (0xff, low 8 bits),
        // so ALL flag bits (CIST_TAIL, CIST_HOOKED, CIST_HOOKYIELD, CIST_HIDE,
        // CIST_C, ...) are provably 0 after this assignment. The per-bit
        // clearTailCall/clearHookYield/clearHidden/clearDebugHook calls and
        // the isDebugHook block that were here were all dead — they operated
        // on bits already guaranteed zero by this mask.
        ef_slot.callstatus = encodeNresults(nresults);
        // P16.21 T3: resume_pc NOT initialized here — every production read
        // is gated by isHookYield() (CIST_HOOKYIELD), and every site that
        // sets that bit writes resume_pc first/at the same transition
        // (value-then-flag ordering). A fresh activation writes callstatus
        // from scratch (CIST_HOOKYIELD clear), so a stale reused-slot value
        // is semantically dead. PUC-style validity-by-status-bit.
        ef_slot.reg_top = @intCast(nparams);
        ef_slot.tbc_mark = tbc_mark;
        // P15.51n: Initialize pending_call_index (addOne doesn't zero-init).
        ef_slot.pending_call_index = INVALID_PENDING;
        // P16.8 Task 1: Initialize simple_result state (no simple-result pending).
        ef_slot.u.lua.clearSimpleResult();

        // P15.51g: regs/boxed are no longer cached in the frame — they are
        // derived on demand from base + frame_cap. The local `regs`/`boxed`
        // slices are used only for the nil-fill below.
        ef_slot.u.lua.setOpenUpvalues(false);

        // P16.21 T4.3: hook-replay sentinels are initialized ONLY when hooks
        // are active for this thread (one predictable branch on the common
        // no-hooks path instead of four u32 stores). Validity model:
        //  - frame created with hooks ON  -> initialized here;
        //  - frame created with hooks OFF -> fields are semantically dead
        //    (every read is inside the hooks-active dispatch block or the
        //    hook push machinery), and BOTH hook-installation paths
        //    (debug.sethook and lua_sethook) sanitize every live Lua frame
        //    when hooks transition to active — see sanitizeHookReplayState.
        if (self.dispatch_gate & DISPATCH_GATE_HOOKS != 0) {
            ef_slot.u.lua.last_line_pc = INVALID_PC;
            ef_slot.u.lua.skip_line_hook_pc = INVALID_PC;
            ef_slot.u.lua.skip_call_hook_pc = INVALID_PC;
            ef_slot.u.lua.resume_skip_count_pc = INVALID_PC;
        }
    }

    /// VAHID buildhiddenargs (PUC ltm.c): shift func+params UP past the extra
    /// args so the extra args become hidden varargs at [func-nextra..func].
    /// Cold: only vararg functions WITHOUT a vararg table AND with extra args.
    noinline fn prepareVahidShift(
        self: *Vm,
        func_slot_in: usize,
        func_slot: usize,
        base: usize,
        nparams: u8,
        frame_cap: u32,
    ) DispatchError!void {
        // Ensure space for the shifted func+params + frame_cap.
        const needed_shift = base + frame_cap;
        try self.ensureBcStackCap(needed_shift);
        // Copy func to new position (PUC: setobjs2s(L, L->top++, ci->func)).
        self.bc_stack[func_slot] = self.bc_stack[func_slot_in];
        // Copy fixed params above the new func position.
        for (0..nparams) |i| {
            self.bc_stack[base + i] = self.bc_stack[func_slot_in + 1 + i];
            // Nil original param position (PUC: for GC safety).
            self.bc_stack[func_slot_in + 1 + i] = .Nil;
        }
        // VAHID requires nextra > 0 (args.len > nparams), so there are never
        // missing params to nil-fill here — the old dead nil-fill loop was
        // `nparams..@max(nparams, nparams)` (an empty range), now removed.
    }

    /// Overflow body: realloc bc_stack/bc_boxed to PHYSICAL_LIMIT (MAXSTACK +
    /// ERRORSTACKSIZE) to give the error handler room, then raise the error.
    /// Cold: only reached on actual stack/frame overflow.
    /// PUC luaD_growstack: this bypasses ensureBcStackCap's MAXSTACK cap
    /// because ERRORSTACKSIZE > MAXSTACK by design.
    noinline fn raiseFrameOverflow(self: *Vm) DispatchError!void {
        const PHYSICAL_LIMIT: usize = 1_000_000 + 200;
        if (self.bc_stack.len < PHYSICAL_LIMIT) {
            const old_len = self.bc_stack.len;
            self.bc_stack = self.alloc.realloc(self.bc_stack, PHYSICAL_LIMIT) catch {
                return self.fail("stack overflow", .{});
            };
            self.bc_boxed = self.alloc.realloc(self.bc_boxed, PHYSICAL_LIMIT) catch {
                return self.fail("stack overflow", .{});
            };
            // Initialize new slots.
            @memset(self.bc_stack[old_len..], .Nil);
            @memset(self.bc_boxed[old_len..], null);
            // P15.51g: No per-frame slice refresh needed — regs/boxed
            // are derived on demand from base + frame_cap.
        }
        return self.fail("stack overflow", .{});
    }

    inline fn popBytecodeExecFrame(
        self: *Vm,
        exec_frames: *FrameStack,
    ) void {
        std.debug.assert(exec_frames.len() != 0);
        const idx = exec_frames.len() - 1;
        const frame = exec_frames.getPtr(idx);
        // P15.40b-full: Single pop — the merged CallFrame holds all fields.
        if (self.getPendingCallPtr(frame.pending_call_index)) |pending| {
            self.cancelBytecodePendingCall(pending, frame);
            self.clearPendingCall(frame);
        }
        // P16.8 Task 1: Clear inline simple-result completion if set.
        // Handles the error-unwind case where the parent frame is popped
        // without the normal return path clearing simple_result state.
        if (!frame.isC()) {
            frame.u.lua.clearSimpleResult();
        }
        // P15.38f: Clear in_debug_hook if this was a debug hook frame.
        // Since isInDebugHook() prevents nested hooks, at most one hook frame
        // exists at a time, so a simple clear is correct.
        if (frame.isDebugHook()) {
            self.activeHookState().in_debug_hook = false;
        }
        // Phase D: Varargs are on bc_stack, no heap free needed.
        self.bc_tbc_regs.items.len = frame.tbc_mark;
        frame.callstatus = 0;
        // PUC model: restore bc_stack_top to the caller's frame capacity.
        if (idx > 0) {
            const caller = exec_frames.getConstPtr(idx - 1);
            if (!caller.isC()) {
                self.bc_stack_top = caller.frameBase() + caller.u.lua.frame_cap;
            } else {
                // C-frame caller: restore bc_stack_top to the C-frame's base
                // (= func_slot + 1). Without this, each runBytecodeInternal
                // call from a C-frame context (e.g. table.sort's comparison
                // function via tableSortLess → runClosure) would leave
                // bc_stack_top at the Lua frame's base + frame_cap, causing
                // bc_stack_top to grow without bound across repeated calls
                // and eventually triggering "stack overflow error".
                self.bc_stack_top = caller.frameBase();
            }
        } else {
            self.bc_stack_top = 0;
        }
        exec_frames.shrinkTo(idx);
    }

    fn completeBytecodeExecFrame(
        self: *Vm,
        exec_frames: *FrameStack,
        boundary_depth: usize,
        ret: []Value,
    ) DispatchError!?[]Value {
        // P15.51j: gcTempRoots is NOT needed on the common path. After
        // popBytecodeExecFrame the child's register window is dead, but:
        //  - closeBytecodeUpvaluesFrom fires write barriers only (gcMarkValue
        //    queues objects; it does not run a full GC cycle).
        //  - popBytecodeExecFrame, alloc.dupe/alloc.alloc/alloc.free, and
        //    bcGrowFrame (ensureBcStackCap → Zig realloc) never trigger GC.
        //  - applyBytecodeResultsDirect copies ret into the parent's registers
        //    (a GC root via bc_stack) before any Lua code can run.
        //  - Paths that DO run Lua code (concat, gsub, protection) have their
        //    own gcTempRoots. Paths that free ret before running Lua (hook,
        //    close) don't need protection either.
        //  - The ONLY path that needs gcTempRoots is tail_return, where
        //    beginBytecodeClose runs __close metamethods while ret is still
        //    alive. gcTempRoots is added there.
        //
        // P15.36: Close all open upvalues of the returning frame BEFORE popping.
        // PUC Lua's luaD_poscall calls luaF_close before removing the frame.
        // Without this, cells in boxed[] remain "open" (bc_stack_idx != null)
        // and would be corrupted when a new frame reuses this stack space.
        // Double-close is safe: closeBytecodeUpvaluesFrom checks boxed[i] for
        // non-null and clears it after closing, so a second call is a no-op.
        const child_idx = exec_frames.len() - 1;
        const child_frame = exec_frames.getConstPtr(child_idx);
        const callee_nresults = decodeNresults(child_frame.callstatus);
        if (exec_frames.getPtr(child_idx).u.lua.hasOpenUpvalues())
            self.closeBytecodeUpvaluesFrom(exec_frames.getPtr(child_idx), 0);
        self.popBytecodeExecFrame(exec_frames);

        // P15.78: If the parent frame is a C-frame (pushed by runTestcScript's
        // closer loop or by callk/pcallk/yieldk), return the results to the
        // caller. The trampoline (driveBytecodeCoroutineTrampoline) detects
        // the C-frame on top and calls finishCcall → testcContShim to
        // continue closing or run the continuation.
        // Set bytecode_inplace_suspended = true so the runBytecodeInternal
        // assertion allows frames to remain above boundary_depth (the C-frame
        // and below are intentionally preserved for the trampoline to process).
        //
        // Ownership contract: runClosure() (and thus runBytecodeInternal) must
        // ALWAYS return a caller-owned, freeable slice. If ret is the VM's
        // bc_return_scratch (OP_RETURN0/1 fast path), it is borrowed — dupe it
        // to a heap-owned slice. If ret is already heap-owned (e.g. from
        // OP_RETURN with multiple values), return it as-is. This matches the
        // external-boundary branch below and ensures all consumers can safely
        // call alloc.free(ret).
        if (exec_frames.len() > 0) {
            const parent = exec_frames.getConstPtr(exec_frames.len() - 1);
            if (parent.isC()) {
                if (self.returnSliceIsOwned(ret)) {
                    const owned = try self.alloc.dupe(Value, ret);
                    return owned;
                }
                return ret;
            }
        }

        // P15.35: If ret is the VM's scratch slice (OP_RETURN0/1 fast path),
        // it is statically owned — never returned to the external caller as
        // `.final`. The external boundary path below allocates a real buffer
        // when needed. For the common case (returning to a parent Lua frame),
        // the scratch is consumed by `applyBytecodePendingResults` which copies
        // values into the parent register window.
        if (exec_frames.len() == boundary_depth) {
            if (self.returnSliceIsOwned(ret)) {
                // External caller needs an owned copy — the scratch is not
                // safe to return (it can be overwritten by the next return).
                const owned = try self.alloc.dupe(Value, ret);
                return owned;
            }
            return ret;
        }

        const parent_index = exec_frames.len() - 1;
        // P16.8 Task 1: Check for inline simple-result completion BEFORE
        // the pending_call_index check. simple_result and pending_calls are
        // mutually exclusive (asserted in tryPushBytecodeContinuationCall
        // and tryPushSimpleResultMetamethod). When hasSimpleResult() is true,
        // the completion is handled inline — no pending_calls slot involved.
        {
            const parent_ptr = exec_frames.getPtr(parent_index);
            if (parent_ptr.isLua() and parent_ptr.u.lua.hasSimpleResult()) {
                if (parent_ptr.u.lua.simpleResultIsCompare()) {
                    // Compare mode: check truthiness, adjust pc.
                    const invert = parent_ptr.u.lua.simpleResultInvert();
                    const result = ret.len != 0 and isTruthy(ret[0]);
                    parent_ptr.u.lua.pc += 1;
                    if (result != invert) parent_ptr.u.lua.pc += 1;
                } else {
                    // Value mode: put 1 result into register, advance pc.
                    const sr_dst = parent_ptr.u.lua.simple_result_dst;
                    var regs = self.bc_stack[parent_ptr.frameBase() .. parent_ptr.frameBase() + parent_ptr.u.lua.frame_cap];
                    try self.bcGrowFrame(parent_ptr.frameBase(), @as(usize, sr_dst) + 1, &parent_ptr.u.lua.frame_cap, &regs);
                    regs[sr_dst] = if (ret.len == 0) .Nil else ret[0];
                    parent_ptr.u.lua.pc += 1;
                }
                parent_ptr.u.lua.clearSimpleResult();
                if (!self.returnSliceIsOwned(ret)) self.alloc.free(ret);
                return null;
            }
        }
        // P15.51c: Ordinary Lua CALL has no pending_call. Result contract is
        // fully in callee's callstatus (nresults) + originalFuncSlot (dst).
        if (self.getPendingCallConst(exec_frames.getPtr(parent_index).pending_call_index) == null) {
            const parent0 = exec_frames.getConstPtr(parent_index);
            const dst = child_frame.originalFuncSlot() - parent0.frameBase();
            try self.applyBytecodeResultsDirect(exec_frames, parent_index, ret, dst, callee_nresults);
            return null;
        }
        const pending = self.getPendingCallConst(exec_frames.getPtr(parent_index).pending_call_index) orelse unreachable;
        var completed_ret = ret;
        if (pending.completion == .results and pending.completion.results.append_nil) {
            const extended = try self.alloc.alloc(Value, completed_ret.len + 1);
            @memcpy(extended[0..completed_ret.len], completed_ret);
            extended[completed_ret.len] = .Nil;
            if (!self.returnSliceIsOwned(completed_ret)) self.alloc.free(completed_ret);
            completed_ret = extended;
        }
        // OP_RETURN dispatches the callee's return hook while its frame is
        // still active. Ordinary Lua calls therefore need no second event.
        // A protected-call continuation is different: the Lua child returned,
        // but the builtin pcall/xpcall activation is completing now.
        if (pending.protection) |protection| {
            const protected_ret = switch (protection.phase) {
                .target => blk: {
                    const wrapped = try self.alloc.alloc(Value, completed_ret.len + 1);
                    wrapped[0] = .{ .Bool = true };
                    @memcpy(wrapped[1..], completed_ret);
                    if (!self.returnSliceIsOwned(completed_ret)) self.alloc.free(completed_ret);
                    break :blk wrapped;
                },
                .handler => blk: {
                    const wrapped = try self.alloc.alloc(Value, 2);
                    wrapped[0] = .{ .Bool = false };
                    wrapped[1] = try self.normalizeProtectedErrorResult(if (completed_ret.len == 0) .Nil else completed_ret[0]);
                    if (!self.returnSliceIsOwned(completed_ret)) self.alloc.free(completed_ret);
                    break :blk wrapped;
                },
            };
            return try self.completeBytecodeProtectedResult(
                exec_frames,
                boundary_depth,
                parent_index,
                protected_ret,
            );
        }
        switch (pending.completion) {
            .results => |cont| {
                if (cont.tail_return) {
                    // P15.51j: beginBytecodeClose runs __close metamethods
                    // which can trigger GC via condGcFromDispatch. The child
                    // frame is already popped, so completed_ret's values are
                    // only reachable through this slice — protect them.
                    var tail_roots = self.gcTempRoots();
                    defer tail_roots.end();
                    for (completed_ret) |value| try tail_roots.add(value);
                    self.clearPendingCall(exec_frames.getPtr(parent_index));
                    return switch (try self.beginBytecodeClose(
                        exec_frames,
                        boundary_depth,
                        parent_index,
                        0,
                        null,
                        true,
                        .{ .return_frame = completed_ret },
                    )) {
                        .resume_dispatch => null,
                        .final => |final| final,
                        .propagate_error => error.RuntimeError,
                    };
                }
                try self.applyBytecodePendingResults(exec_frames, parent_index, completed_ret, cont.dst, callee_nresults);
            },
            .value => |cont| try self.applyBytecodePendingValue(exec_frames, parent_index, completed_ret, cont),
            .ignore => self.applyBytecodePendingIgnore(exec_frames, parent_index, completed_ret),
            .compare => |cont| self.applyBytecodePendingCompare(exec_frames, parent_index, completed_ret, cont),
            .concat => |cont| try self.applyBytecodePendingConcat(exec_frames, parent_index, completed_ret, cont),
            .gsub => |cont| return try self.applyBytecodePendingGsub(exec_frames, boundary_depth, parent_index, completed_ret, cont),
            .hook => |cont| return try self.applyBytecodePendingHook(exec_frames, boundary_depth, parent_index, completed_ret, cont),
            .close => |cont| switch (try self.applyBytecodePendingClose(exec_frames, boundary_depth, parent_index, completed_ret, cont)) {
                .resume_dispatch => {},
                .final => |final| return final,
                .propagate_error => return error.RuntimeError,
            },
            .coroutine_resume => unreachable,
        }
        return null;
    }

    fn unwindBytecodeExecFrames(
        self: *Vm,
        exec_frames: *FrameStack,
        boundary_depth: usize,
    ) void {
        // Normal runtime/OOM propagation is handled by
        // continueBytecodeErrorUnwind, including all yielding __close
        // continuations. Direct yields and coroutine thread switches park the
        // authoritative Thread-owned suffix and bypass this defer. Reaching
        // this fallback therefore means frame construction/dispatch aborted
        // before a semantic unwind could start; release only the owned suffix.
        while (exec_frames.len() > boundary_depth) {
            const frame = exec_frames.getPtr(exec_frames.len() - 1);
            // PUC precover: a C-frame with CIST_YPCALL is a recovery barrier.
            // Stop unwinding here — the C-frame must stay in place for
            // precover → finishCcall → finishpcallk → k to find.
            if (frame.isC() and frame.isYpcall()) {
                break;
            }
            if (!frame.isC() and frame.u.lua.hasOpenUpvalues())
                self.closeBytecodeUpvaluesFrom(frame, 0);
            self.popBytecodeExecFrame(exec_frames);
        }
    }

    /// A bytecode coroutine yield is parkable when this runBytecode invocation
    /// owns the whole active explicit stack. Nested host entries are either
    /// non-yieldable C callbacks or the frozen IR compatibility path; they must
    /// not retain a native activation as part of a bytecode continuation.
    fn canParkDirectBytecodeYield(self: *const Vm, boundary_depth: usize, id: BuiltinId) bool {
        if (id != .coroutine_yield) return false;
        const th = self.current_thread orelse return false;
        if (th.close_mode) return false;
        // P15.65: When a __close metamethod is running as part of a testC
        // close continuation, it runs via callMetamethod → runClosure →
        // runBytecodeInternal, which pushes a new frame (boundary_depth != 0).
        // coroutine.yield from within such a __close metamethod must park the
        // bytecode frame in-place so it can be resumed on the next
        // coroutine.resume. Without this, the errdefer in runBytecodeInternal
        // unwinds the frame and the __close metamethod is lost.
        if (self.testc_close_metamethod_depth > 0) return true;
        return boundary_depth == 0;
    }

    fn parkDirectBytecodeYield(
        self: *Vm,
        th: *Thread,
        pc: usize,
        resume_pc: *u32,
        resumed_direct_yield: *bool,
        boundary_depth: usize,
    ) void {
        _ = self;
        resume_pc.* = @intCast(pc);
        resumed_direct_yield.* = true;
        th.bytecode_inplace_suspended = true;
        th.bytecode_resume_boundary = boundary_depth;

        // No frame serialization will run for this yield. The active frame,
        // register and TBC stacks already belong to `th` and are parked by the
        // coroutine context switch. Clear only the frozen IR snapshot request that
        // the shared `coroutine.yield` builtin also arms.
        th.capture_yield_id = 0;
        th.capture_from_debug_hook = false;
        th.capture_from_count_hook = false;
    }

    /// A native/testC hook is represented by the frozen IR compatibility
    /// path, but it may run while a bytecode frame owns the coroutine. If a
    /// line/count hook yields, keep that bytecode frame parked and let the IR
    /// child finish first on resume. Count hooks additionally suppress the
    /// immediate re-fire at the same opcode.
    fn parkBytecodeIrHookYield(
        self: *Vm,
        exec_frames: *FrameStack,
        frame_index: usize,
        pc: usize,
        skip_count: bool,
        yielded_in_place: *bool,
    ) void {
        const th = self.current_thread orelse return;
        th.bytecode_inplace_suspended = true;
        yielded_in_place.* = true;
        if (skip_count) {
            exec_frames.getPtr(frame_index).u.lua.resume_skip_count_pc = @intCast(pc);
        } else {
            self.activeHookState().skip_bc_line_once = true;
        }
    }

    /// Public direct-bytecode entry point. Internal coroutine trampoline
    /// control flow is narrowed at this boundary and cannot escape to callers.
    pub fn runBytecode(self: *Vm, proto_in: *const bc.Proto, upvalues_in: []const *Cell, args: []const Value, callee_cl: ?*Closure) Error![]Value {
        // P16.10b Task 7+15 (adoption): this is the VM-bind boundary for
        // directly executed protos (CLI source/binary execution and any
        // embedding caller that compiled a Proto and runs it without an
        // intermediate Closure). Trees adopted at closure creation are
        // already ready and skip this in O(1).
        if (proto_in.tree) |t| {
            // resolveTreeConstants is pure allocation+interning: it can
            // never yield or switch threads, but its signature carries the
            // full DispatchError set. Map the impossible arm explicitly.
            if (!t.flags.constants_resolved) {
                self.resolveTreeConstants(t) catch |e| switch (e) {
                    error.ThreadSwitch => unreachable, // pure allocation+interning: no control flow inside
                    error.OutOfMemory => return error.OutOfMemory,
                    error.RuntimeError => return error.RuntimeError,
                    error.Yield => return error.Yield,
                };
            }
        }
        // exposeDispatchResult performs the DispatchError→Error narrowing
        // (ThreadSwitch is unreachable at this boundary; see doc comment).
        return exposeDispatchResult([]Value, self.runBytecodeInternal(proto_in, upvalues_in, args, callee_cl));
    }

    fn runBytecodeInternal(self: *Vm, proto_in: *const bc.Proto, upvalues_in: []const *Cell, args: []const Value, callee_cl: ?*Closure) DispatchError![]Value {
        // A directly executed chunk is still a first-class Lua function.
        // Materialize its closure so debug.getinfo(level, "f") and
        // debug.getupvalue can expose the running main function just like PUC
        // Lua. Nested bytecode calls already arrive with their real closure.
        // Ownership invariant: every GC-registered Closure owns its `upvalues`
        // slice. gcFreeObject(.closure) calls self.alloc.free(c.upvalues), so
        // the slice must be heap-allocated by the closure creator. Callers of
        // runBytecode pass borrowed upvalues (stack-local arrays, &.{}, etc.);
        // we dup the slice here so the closure owns it.
        const effective_callee = callee_cl orelse blk: {
            const owned_upvalues = try self.alloc.alloc(*Cell, upvalues_in.len);
            errdefer self.alloc.free(owned_upvalues);
            @memcpy(owned_upvalues, upvalues_in);
            const cl = try self.alloc.create(Closure);
            errdefer self.alloc.destroy(cl);
            cl.* = .{
                .proto = proto_in,
                .upvalues = owned_upvalues,
            };
            // Retain the tree owner (P16.16 C2/T4.2: derived from proto).
            _ = self.retainTreeForClosure(proto_in);
            try self.gcRegisterClosure(cl);
            self.gcNoteAlloc(@sizeOf(Closure) + upvalues_in.len * @sizeOf(*Cell));
            self.testc_obj_functions += 1;
            break :blk cl;
        };

        const exec_thread = self.current_thread orelse self.main_thread.?;
        const exec_frames = &exec_thread.call_frames;
        const resume_in_place = exec_thread.in_resume and
            exec_thread.bytecode_inplace_suspended and
            exec_frames.len() != 0;
        // P15.65: When resuming a parked bytecode yield, use the boundary
        // depth saved at park time. For top-level yields (boundary_depth == 0)
        // this is 0, same as before. For nested yields (e.g. __close
        // metamethod yielding via coroutine.yield), this preserves the
        // original boundary so resume doesn't process frames belonging to
        // outer callers.
        const boundary_depth: usize = if (resume_in_place)
            exec_thread.bytecode_resume_boundary
        else
            exec_frames.len();
        if (resume_in_place) {
            exec_thread.bytecode_inplace_suspended = false;
        } else {
            // PUC lua_pcallk/lua_resume: the C API stages func+args on the
            // value stack before docall — mirror it: stage at bc_stack_top
            // (L->top), then activate.
            const staged_entry = try self.stageBytecodeCall(self.bc_stack_top, effective_callee, args);
            try self.pushStagedBytecodeExecFrame(exec_frames, proto_in, staged_entry.func_slot, staged_entry.nargs, -1);
            // PUC luaG_tracecall (ldebug.c:903-921): when a fresh activation
            // starts executing, the CALL hook fires with the NEW ci — the
            // main chunk of a lua_pcall/dostring, a C-API-called function,
            // or a coroutine body on first resume all get their LUA_HOOKCALL
            // here (ar.i_ci = the entry frame). Resumed activations skip it:
            // they already fired before yielding (ldebug.c:910).
            try self.dispatchCalleeActivationHook(exec_frames, .{ .Closure = effective_callee }, args.len);
        }

        var yielded_in_place = false;
        // Register the invariant first so the error-unwind defer runs before
        // it (defer execution is LIFO). A direct bytecode yield deliberately
        // leaves the suffix resident in the thread instead of unwinding it.
        defer std.debug.assert(
            exec_frames.len() == boundary_depth or
                ((yielded_in_place or exec_thread.bytecode_inplace_suspended) and exec_frames.len() > boundary_depth) or
                // P15.78: A C-frame may remain as the TOP frame above
                // boundary_depth after a Lua frame returns to a C-frame
                // parent. completeBytecodeExecFrame returns the results to
                // the caller (the trampoline), which detects the C-frame on
                // top and calls finishCcall. Also handles CIST_YPCALL
                // C-frames left by callCFunction on error for precover →
                // finishCcall → finishpcallk → k.
                // Check the TOP frame specifically (not any C-frame anywhere
                // above boundary_depth) to catch stack corruption where Lua
                // frames are left above a C-frame.
                (exec_frames.len() > boundary_depth and
                    exec_frames.getConstPtr(exec_frames.len() - 1).isC()),
        );
        // P15.70: When bytecode_inplace_suspended is true (set by a C-frame
        // with testc_state during callk/yieldk/pcallk/yield, or by
        // parkDirectBytecodeYield for coroutine.yield inside a __close
        // metamethod), the CURRENT runBytecodeInternal's frame must be
        // preserved for resume. But frames pushed by NESTED
        // runBytecodeInternal calls (e.g. testC `call` command → apiCall →
        // runClosure → runBytecodeInternal for a selection function) must
        // still be unwound, otherwise they accumulate on the stack and
        // confuse resume.
        //
        // With the save/restore of bytecode_current_boundary above, this
        // runBytecodeInternal's boundary_depth always equals
        // bytecode_current_boundary (since we just set it). So the owner
        // check becomes: is bytecode_inplace_suspended true? If yes, this
        // runBytecodeInternal is the outermost one — preserve its frame but
        // unwind any leftover nested frames above boundary_depth + 1.
        errdefer if (!yielded_in_place) {
            // P15.70: The "owner" of the suspension is the runBytecodeInternal
            // that should preserve its frame for resume. The outermost call
            // (boundary_depth == 0, the coroutine body) is always the owner.
            // Nested calls (e.g. f-closures from apiCall → runClosure) are
            // owners only if their boundary matches bytecode_resume_boundary
            // (set by parkDirectBytecodeYield for __close metamethod yields).
            // Non-owners unwind their frames to prevent stale re-execution.
            //
            // P15.78 Task 13: When callk/pcallk/yieldk pushes C-frames with
            // testc_state above this boundary, those C-frames MUST be preserved
            // for finishCcall → testcContShim on resume. The suspension spans
            // this runBytecodeInternal call (the f-closure that called T.testC
            // which called callk). Without this check, the errdefer would
            // unwind the C-frames, losing continuation state.
            const has_testc_cframes_above = blk: {
                if (!exec_thread.bytecode_inplace_suspended) break :blk false;
                var i: usize = boundary_depth;
                while (i < exec_frames.len()) : (i += 1) {
                    const f = exec_frames.getConstPtr(i);
                    if (f.isC() and f.u.c.testc_state != null) break :blk true;
                }
                break :blk false;
            };
            const is_suspension_owner = exec_thread.bytecode_inplace_suspended and
                (boundary_depth == 0 or boundary_depth == exec_thread.bytecode_resume_boundary or has_testc_cframes_above);
            if (!is_suspension_owner) {
                self.unwindBytecodeExecFrames(exec_frames, boundary_depth);
            }
        };

        // A yielding native/testC hook is the only frozen-IR child allowed to
        // IR yield child resume removed — all closures are bytecode.

        // coroutine.close resumes a suspended coroutine only to unwind it. Do
        // not execute the instruction after coroutine.yield: inject the close
        // signal directly into the explicit frame stack, exactly where PUC's
        // lua_resetthread starts luaF_close. A nil error object is passed to
        // the first __close; later close errors replace it in LIFO order.
        //
        // PUC lua_resetthread: L->ci = &L->base_ci (unwind to base), then
        // luaF_close(L, L->stack, LUA_OK, 1). This discards ALL frames
        // including pcall C-frames — __close errors are NOT caught by pcall.
        // We use appendBytecodeForcedCloseUnwind (target_depth = boundary_depth)
        // which unwinds all frames to the boundary without stopping at
        // CIST_YPCALL frames (unlike appendBytecodeUnwind which uses
        // bytecodeUnwindDisposition that stops at CIST_YPCALL).
        if (resume_in_place and exec_thread.close_mode) {
            self.clearErrorTraceback();
            self.restoreRuntimeErrorValue(.Nil);
            try self.appendBytecodeForcedCloseUnwind(boundary_depth);
            switch (try self.continueBytecodeErrorUnwind(exec_frames)) {
                .resumed => {},
                .completed => |ret| return ret,
                .propagate => return error.RuntimeError,
            }
        }

        while (true) {
            const result = self.runBytecodeDispatch(exec_frames, boundary_depth, &yielded_in_place) catch |dispatch_err| {
                if (dispatch_err == error.Yield or dispatch_err == error.ThreadSwitch) return dispatch_err;
                if (self.shouldRethrowForcedCloseFromBytecode()) {
                    // Re-entrant bytecode entries made by a C callback only
                    // release their borrowed suffix. The root owner performs
                    // the semantic reset so protected continuations cannot
                    // intercept coroutine.close() and all root TBC slots run.
                    if (boundary_depth != 0) return dispatch_err;
                    // P15.79: If __close metamethods already errored during
                    // the forced close, all TBC slots have been processed by
                    // continueBytecodeErrorUnwind → close_parent →
                    // continueBytecodeClose. The error is already set
                    // correctly (the last __close error). Don't clear it —
                    // just propagate. Clearing and re-running the forced
                    // close would discard the __close error and set err_obj
                    // to nil, causing coroutine.close to return (false, nil)
                    // instead of (false, "last_close_error").
                    if (self.forced_close_had_error) return error.RuntimeError;
                    self.clearErrorTraceback();
                    self.restoreRuntimeErrorValue(.Nil);
                    try self.appendBytecodeForcedCloseUnwind(boundary_depth);
                    switch (try self.continueBytecodeErrorUnwind(exec_frames)) {
                        .resumed => continue,
                        .completed => |ret| return ret,
                        .propagate => return error.RuntimeError,
                    }
                }
                switch (try self.recoverBytecodeDispatchError(exec_frames, boundary_depth, dispatch_err)) {
                    .resumed => continue,
                    .completed => |ret| return ret,
                    .propagate => |fault| return switch (fault) {
                        .runtime => error.RuntimeError,
                        .out_of_memory => error.OutOfMemory,
                    },
                }
            };
            return result;
        }
    }

    // ─────────────────────────────────────────────────────────────────────
    // P15.42 opcode-handler extraction scaffolding (additive, unused).
    //
    // BytecodeDispatchCtx is a plain data carrier holding the same 15 fields
    // that runBytecodeDispatch currently keeps as local variables. Once the
    // 11 complex opcode handlers (OP_CALL, OP_TAILCALL, OP_CONCAT, OP_FORPREP,
    // OP_TFORCALL, OP_CLOSURE, OP_VARARG, OP_RETURN*, OP_SETLIST) are
    // extracted to separate methods, they will receive *BytecodeDispatchCtx
    // and mutate it directly. This shrinks the dispatcher's C stack frame
    // from 139 KB (Debug) to <1 KB, which unblocks PUC-faithful host
    // recursion (see docs/superpowers/specs/2026-07-21-opcode-extraction-design.md).
    //
    // Design notes:
    // - The ctx is a plain struct, not a state machine. Behavior stays in Vm
    //   methods (loadDispatchCtx / syncDispatchCtx / refreshCtxSlices + the
    //   per-opcode opXxx methods).
    // - `regs` / `boxed` slices are mutable and may be invalidated by any
    //   callee that reallocs `bc_stack`. Use refreshCtxSlices after such
    //   calls (matches the existing bcGrowFrame pattern).
    // ─────────────────────────────────────────────────────────────────────

    /// Plain data carrier for bytecode dispatch state. Lives in the
    /// dispatcher's C frame; one instance per `runBytecodeDispatch` call.
    ///
    /// PUC Lua pattern: `luaV_execute` works with `ci` (pointer to CallInfo)
    /// directly. Hot variables (`pc`, `base`) are kept as locals; the heap
    /// CallFrame is synced only at boundaries (CALL, RETURN, GC, hook, error,
    /// yield). We replicate this by keeping only the 7 hottest fields as
    /// value fields on `ctx` (362+140+104+83+76+40+9 = 814 of ~906 accesses).
    /// The rare fields (reg_top, nextraargs, varargs, tbc_mark,
    /// resume_pc, func_slot, is_tailcall, resumed_direct_yield,
    /// has_open_upvalues, hooks_active — 92 accesses) are read/written
    /// directly on the heap CallFrame via `ctx.exec_frames.getPtr(ctx.frame_index)`.
    ///
    /// This eliminates the dangling-pointer hazard: `exec_frames` may
    /// realloc inside the inner loop (via `pushBytecodeExecFrame`), but
    /// since `ctx` holds values (not pointers), no re-derivation is needed
    /// for the hot fields. Rare fields are re-derived on each access.
    const BytecodeDispatchCtx = struct {
        // Immutable within a frame_loop iteration.
        exec_frames: *FrameStack,
        frame_index: usize,
        boundary_depth: usize,
        yielded_in_place: *bool,

        // Hot frame state — cached from the heap CallFrame for register
        // performance. Only state touched EVERY iteration lives here;
        // rare frame metadata stays on the CallFrame and is loaded at use
        // sites. (ctx.boxed was removed in P16.19 T3; syncFrame publishes
        // pc only since P16.21 T6.)
        cur_proto: *const bc.Proto,
        cur_upvalues: []const *Cell,
        base: usize,
        frame_cap: u32,
        regs: []Value,
        pc: usize,
    };

    /// Result of an extracted opcode handler. The dispatcher switch unwraps
    /// this to drive the inner dispatch loop.
    const DispatchResult = union(enum) {
        /// Advance pc and continue the inner dispatch loop. The handler must
        /// NOT have modified ctx.pc to point at the next instruction — the
        /// dispatcher's `ctx.pc += 1` does that. (Most handlers return this.)
        continue_dispatch,

        /// Continue the inner dispatch loop WITHOUT advancing pc. The handler
        /// has set ctx.pc itself (e.g., OP_TAILCALL bytecode-to-bytecode frame
        /// reuse resets pc to 0). The dispatcher's `ctx.pc += 1` is skipped.
        continue_no_advance,

        /// Re-enter the outer frame_loop. The handler may have popped the
        /// current frame (OP_RETURN*), replaced it (OP_TAILCALL), or pushed
        /// a child frame (OP_CALL iterative path).
        continue_frame_loop,

        /// Return from `runBytecodeDispatch` with the given result slice.
        return_results: []Value,

        /// Signal a runtime error. The dispatcher runs error recovery.
        propagate_error,
    };

    /// Sync the 5 hot ctx fields (pc, base, frame_cap, cur_proto, cur_upvalues)
    /// back to the heap-resident CallFrame. Called at frame_loop boundaries
    /// (before `continue :frame_loop`, before yield/error, before GC/hooks).
    ///
    /// PUC Lua pattern: `ci->u.l.savedpc = pc` at call/return boundaries.
    /// We sync more fields because our iterative frame_loop (not host
    /// recursion) requires persisting all hot state to the heap CallFrame
    /// before switching to a different frame.
    ///
    /// The activation_id check ensures we don't write to a frame that was
    /// popped or replaced (e.g., after OP_RETURN pops the frame, the defer
    /// runs but the check skips the write).
    fn syncFrame(self: *Vm, ctx: *BytecodeDispatchCtx, frame_identity: ActivationId) void {
        _ = self;
        if (ctx.frame_index < ctx.exec_frames.len() and
            ctx.exec_frames.getPtr(ctx.frame_index).activation_id == frame_identity)
        {
            const fr = ctx.exec_frames.getPtr(ctx.frame_index);
            fr.u.lua.pc = ctx.pc;
            // P16.21 T6: syncFrame is now PC-ONLY (PUC persists savedpc
            // at boundaries). frame_cap is published at its mutation sites:
            // growCtxFrame (every dispatch growth, immediately after
            // success) plus the tailcall/call-staging paths that already
            // wrote it explicitly. Parked-frame GC/debug readers therefore
            // always see the live cap. Base write removed P16.19 T9.1
            // (provably identity); proto/upvalues never generic sync
            // writes (P16.2d / P15.51n).
        }
    }

    /// Re-derive `ctx.regs` / `ctx.boxed` after a callee may have realloc'd
    /// `bc_stack`. Cheap (slice arithmetic only); call liberally after any
    /// function that may grow the shared stack.
    fn refreshCtxSlices(self: *Vm, ctx: *BytecodeDispatchCtx) void {
        ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
    }

    fn runBytecodeDispatch(
        self: *Vm,
        exec_frames: *FrameStack,
        boundary_depth: usize,
        yielded_in_place: *bool,
    ) DispatchError![]Value {
        // P16.19/P16.20: ctx caches the hottest dispatch fields as locals
        // (pc, base, regs, frame_cap, cur_proto, cur_upvalues; boxed was
        // removed in P16.19 T3). Rare fields live directly on the heap
        // CallFrame via exec_frames.getPtr, like PUC accessing `ci`.
        var ctx: BytecodeDispatchCtx = .{
            .exec_frames = exec_frames,
            .frame_index = 0, // set per-iteration below
            .boundary_depth = boundary_depth,
            .yielded_in_place = yielded_in_place,
            // hot fields — initialized from CallFrame at top of frame_loop
            .cur_proto = undefined,
            .cur_upvalues = &.{},
            .base = 0,
            .frame_cap = 0,
            .regs = &.{},
            .pc = 0,
        };

        // Read once — sigint_installed is set before runBytecode and cleared
        // after. No data race within the loop. Compiler hoists into register.
        const check_sigint = sigint_installed;

        // P16.10 T8: PUC-style SIGINT — boundary-only check, no per-instruction
        // variable.
        //
        // PUC Lua's mechanism (lua.c:laction → lua_sethook → ci->u.l.trap=1):
        // the signal handler sets a per-CallInfo trap flag. The dispatch loop
        // caches `trap` from L->hookmask at function entry, checks it every
        // instruction (single predictable not-taken branch), and refreshes it
        // from ci->u.l.trap at backward jumps (dojump → updatetrap) and C-call
        // boundaries. PUC's per-instruction cost is 1 branch (the trap check);
        // the refresh is 1 load at backward jumps.
        //
        // luazig's approach: check signal_int_pending DIRECTLY at backward
        // jumps and frame boundaries — NO per-instruction variable. This
        // eliminates the register pressure of a per-instruction SIGINT local
        // (which was +7 instr/iter with the old countdown, and +7 with a
        // cached trap bool — the cost is dominated by register spills in the
        // dispatch switch, not by the check itself).
        //
        // SIGINT latency: 1 backward-jump for tight loops (FORLOOP/JMP/
        // TFORLOOP), 1 function call for non-loop code (frame_loop entry).
        // Basic blocks in Lua bytecode are short (<30 instructions), so
        // worst-case latency is <30 instructions (<100ns). PUC has the same
        // latency characteristic (trap is only refreshed at backward jumps).
        //
        // Library/embedding users (sigint_installed=false) pay zero:
        // check_sigint is const false → all SIGINT checks are dead-coded.

        frame_loop: while (exec_frames.len() > boundary_depth) {
            ctx.frame_index = exec_frames.len() - 1;

            if (self.getPendingCallConst(exec_frames.getPtr(ctx.frame_index).pending_call_index)) |pending| {
                switch (pending.completion) {
                    .results => {}, // IR closure resume removed — all closures have proto
                    .close => |cont| if (cont.waiting_builtin_yield and !cont.child_active) {
                        switch (try self.continueBytecodeClose(exec_frames, boundary_depth, ctx.frame_index)) {
                            .resume_dispatch => continue :frame_loop,
                            .final => |final| return final,
                            .propagate_error => {
                                return error.RuntimeError;
                            },
                        }
                    },
                    else => {},
                }
            }
            const frame_identity = exec_frames.getPtr(ctx.frame_index).activation_id;

            // P15.51l: Inline initialization of the hot fields from the
            // heap CallFrame. Replaces the old loadDispatchCtx which copied
            // ~20 fields (including 11 rare ones that are now accessed
            // directly on the CallFrame). Only the hot fields that are
            // accessed in the inner dispatch loop are cached as locals.
            {
                // P16.22 T3: direct Lua-arm access — the frame_loop body is
                // BYTECODE dispatch, so the current frame is provably a Lua
                // frame (the old `fr.proto().?` paid an isC branch + null
                // unwrap for an invariant control flow already proves).
                // base/frame_cap are each computed ONCE and reused for the
                // register slice (was: frameBase() twice).
                const fr = exec_frames.getPtr(ctx.frame_index);
                const fb = fr.frameBase();
                ctx.cur_proto = fr.u.lua.proto;
                // P15.51n: upvalues derived from bc_stack[func_slot].Closure.
                ctx.cur_upvalues = self.bc_stack[fr.func_slot].Closure.upvalues;
                ctx.base = fb;
                const cap = fr.u.lua.frame_cap;
                ctx.frame_cap = cap;
                ctx.pc = fr.u.lua.pc;
                ctx.regs = self.bc_stack[fb .. fb + cap];
            }

            // P16.21 T6: syncFrame is PC-ONLY (frame_cap published at
            // mutation sites via growCtxFrame; base/proto/upvalues are
            // never generic sync writes).
            // The activation_id check skips the write for popped/replaced frames.
            defer self.syncFrame(&ctx, frame_identity);

            // P16.10 T8: Check SIGINT at frame boundary — catches signals
            // that fired while a child frame was executing.
            if (check_sigint and signal_int_pending.load(.acquire)) {
                signal_int_pending.store(false, .release);
                return self.fail("interrupted!", .{});
            }

            // P16.10 T6: Stack-pointer poll — REMOVED.
            //
            // The per-instruction `if (self.bc_stack.ptr != stack_ptr)` check
            // was +3 instr/iter. It is unnecessary because every bc_stack
            // realloc path reachable from the inner loop either (a) explicitly
            // refreshes ctx.regs afterward, or (b) exits to
            // frame_loop (which re-derives slices at lines 11771-11772).
            //
            // Classification table (all realloc paths reachable from the inner
            // loop, including hooks-active handler-level hook dispatches):
            //
            //   Site                          | Realloc via         | Refreshes? | Exits to frame_loop?
            //   ------------------------------+---------------------+------------+--------------------
            //   OP_CALL inline (vm.zig:13557) | ensureBcStackCap    | YES (13558)| YES (13587)
            //   opCall builtin (vm.zig:15402) | ensureBcStackCap    | YES (15403)| YES (via .continue_frame_loop)
            //   opCall pushBuiltinCFrame(598)| pushBuiltinCFrame   | YES (15603)| YES (refresh at 15666 before .continue_dispatch)
            //   opCall IR closure (15781)     | bcGrowFrame         | YES (out-params) | NO (.continue_dispatch)
            //   opTforcall (vm.zig:14479)     | ensureBcStackCap    | YES (14480)| YES (via .continue_frame_loop)
            //   opTailcall bc-to-bc (15029)   | ensureBcStackCap    | YES (15060+15066) | NO (.continue_no_advance)
            //   opTailcall VAHID (15051)      | ensureBcStackCap    | YES (15060+15066) | NO (.continue_no_advance)
            //   opVararg (vm.zig:14306,14318)| bcGrowFrame         | YES (out-params) | NO (.continue_dispatch)
            //   opConcat value path (14771)   | none (string alloc) | YES (14771)| NO (.continue_dispatch)
            //   opClosure (vm.zig:14335)      | none (heap alloc)   | N/A        | NO (.continue_dispatch)
            //   opSetlist (vm.zig:13948)      | none (table alloc)  | N/A        | NO (.continue_dispatch)
            //   opForprep (vm.zig:14608)      | none                | N/A        | NO (.continue_dispatch)
            //
            // Handler-level hook dispatches (dispatchBytecodeHook* called from
            // within switch handlers) can also realloc bc_stack via C hook
            // functions that call lua_call. These sites refresh ctx.regs/
            // ctx.boxed after the hook dispatch (e.g., opCall builtin return
            // hook at vm.zig:15666, opTailcall return hook refreshes via
            // bcGrowFrame at 15781). The hooks block at the top of the loop
            // (line 11844) also refreshes after synchronous line/count hooks.
            //
            // Every path that actually reallocs bc_stack either refreshes
            // ctx.regs/ctx.boxed explicitly or exits to frame_loop. The
            // per-instruction check is therefore unnecessary and has been
            // removed. (P15.33 original rationale: safety net before explicit
            // refreshes were added at all realloc sites. P16.10 T6: explicit
            // refreshes now cover all sites — see table above.)

            while (ctx.pc < ctx.cur_proto.code.len) {
                const inst = ctx.cur_proto.code[ctx.pc];
                const op: bc.Op = @enumFromInt(inst.op);
                const a = inst.a;
                const b = inst.b;
                const c = inst.c;

                // P16.0b: default-off instruction histogram. When disabled
                // this is one L1 byte-load + predictable not-taken branch
                // (the `enabled` field sits in the same cache line as the
                // per-instruction-written `dispatch_pc`). Deliberately NOT
                // a cached `?*VmStats` local: a loop-wide live pointer
                // costs a register across the whole dispatch switch, which
                // measured +3% on branchy microbenchmarks (see STATUS.md
                // "P16.0b" for the A/B history). The hint keeps the
                // increments out of the hot instruction stream.
                // Publish the current pc so fail() and GC safepoints can read
                // it without the dispatch loop syncing to the frame first.
                // This mirrors PUC's `ci->u.l.savedpc` but is kept per-instruction.
                self.dispatch_pc = ctx.pc;

                // P16.19 T5-A: single combined gate; common case = one
                // not-taken branch for BOTH stats and hooks flags.
                if (self.dispatch_gate != 0) {
                    if (self.dispatch_gate & DISPATCH_GATE_STATS != 0) {
                        self.stats.instructions_total += 1;
                        self.stats.instructions_by_op[@intFromEnum(op)] += 1;
                    }

                    // P15.33: Re-check hooks_active_cached every iteration so that
                    // debug.sethook() called from Lua code takes effect
                    // immediately. Uses the cached flag updated by refreshHooksCached().
                    // (P15.51l: hooks_active removed from ctx — use self.hooks_active_cached directly.)

                    // P16.10 T8: SIGINT is checked at backward jumps and frame
                    // boundaries only — no per-instruction check. See the T8
                    // comment block above for the PUC comparison and rationale.

                    if (self.dispatch_gate & DISPATCH_GATE_HOOKS != 0) {
                        // Slow path: hooks may fire. Use a local `fr` that can be
                        // re-derived after hooks execute Lua code (which may grow
                        // exec_frames and invalidate stale pointers).
                        var fr = exec_frames.getPtr(ctx.frame_index);
                        // Sync ctx.pc to the heap CallFrame so the hooks block and
                        // debug.getinfo see the current instruction.
                        // P15.51l: reg_top is now read directly from
                        // the CallFrame (fr), so no sync needed for them.
                        fr.u.lua.pc = ctx.pc;
                        // P15.51n: current_line derived from proto.lineinfo[pc].
                        const hook_state = self.activeHookState();
                        const th = self.activeBytecodeThread();
                        if (hook_state.has_line and !self.isInDebugHook() and self.debug_hooks_suppressed == 0) {
                            const has_line_info = fr.u.lua.pc < ctx.cur_proto.lineinfo.len and ctx.cur_proto.lineinfo[fr.u.lua.pc] != 0;
                            if (has_line_info) {
                                const current_line: i64 = @intCast(ctx.cur_proto.lineinfo[fr.u.lua.pc]);

                                // A direct coroutine yield resumes by replaying the
                                // suspended CALL/TAILCALL opcode. That replay is a VM
                                // continuation, not a new source-line transition.
                                var skip_replayed_hook = fr.isHookYield() and fr.u.lua.pc == @as(usize, fr.u.lua.resume_pc);
                                {
                                    const skip_pc = exec_frames.getPtr(ctx.frame_index).u.lua.skip_line_hook_pc;
                                    if (skip_pc != INVALID_PC) {
                                        if (skip_pc == @as(u32, @intCast(fr.u.lua.pc))) skip_replayed_hook = true;
                                        exec_frames.getPtr(ctx.frame_index).u.lua.skip_line_hook_pc = INVALID_PC;
                                    }
                                }
                                if (!skip_replayed_hook and hook_state.skip_bc_line_once) {
                                    skip_replayed_hook = true;
                                    hook_state.skip_bc_line_once = false;
                                }

                                // PUC starts tracing a vararg function after OP_VARARGPREP:
                                // the first source-visible line is the instruction that
                                // follows it. Record OP_VARARGPREP as oldpc, but do not
                                // dispatch a line event for it.
                                const suppress_varargprep = fr.u.lua.pc == 0 and op == .varargprep;
                                const previous_pc = exec_frames.getPtr(ctx.frame_index).u.lua.last_line_pc;
                                var should_dispatch = false;
                                if (!skip_replayed_hook and !suppress_varargprep) {
                                    if (previous_pc != INVALID_PC) {
                                        const old_pc: usize = previous_pc;
                                        const old_line: i64 = if (old_pc < ctx.cur_proto.lineinfo.len and ctx.cur_proto.lineinfo[old_pc] != 0)
                                            @intCast(ctx.cur_proto.lineinfo[old_pc])
                                        else
                                            current_line;
                                        should_dispatch = fr.u.lua.pc <= old_pc or old_line != current_line;
                                    } else {
                                        should_dispatch = true;
                                    }
                                }

                                // Track every opcode, not only opcodes that emitted a
                                // hook. This is luaG_traceexec's oldpc invariant, kept
                                // per activation so returning from a child on the same
                                // source line does not create a synthetic event merely
                                // because our bytecode density differs from PUC's.
                                if (!suppress_varargprep) {
                                    exec_frames.getPtr(ctx.frame_index).u.lua.last_line_pc = @intCast(fr.u.lua.pc);
                                }

                                if (should_dispatch) {
                                    th.last_hook_line = current_line;
                                    if (try self.tryPushBytecodeDebugHook(
                                        exec_frames,
                                        ctx.frame_index,
                                        "line",
                                        current_line,
                                        null,
                                        null,
                                        1,
                                        .{ .resume_instruction = .{ .skip_line = true } },
                                    )) {
                                        continue :frame_loop;
                                    }
                                    self.dispatchBytecodeHook("line", current_line, null) catch |hook_err| {
                                        if (hook_err == error.Yield) {
                                            self.parkBytecodeIrHookYield(exec_frames, ctx.frame_index, fr.u.lua.pc, false, yielded_in_place);
                                        }
                                        return hook_err;
                                    };
                                    // The hook can execute Lua and grow both the shared
                                    // value stack and runtime-frame array.
                                    ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                                    fr = exec_frames.getPtr(ctx.frame_index);
                                    ctx.pc = fr.u.lua.pc;
                                }
                            } else if (ctx.cur_proto.lineinfo.len == 0 and th.last_hook_line != -2) {
                                // Stripped chunks still produce one line event at the
                                // first instruction, with no line number.
                                const skip_replayed_hook = hook_state.skip_bc_line_once;
                                if (skip_replayed_hook) hook_state.skip_bc_line_once = false;
                                th.last_hook_line = -2;
                                if (!skip_replayed_hook) {
                                    if (try self.tryPushBytecodeDebugHook(
                                        exec_frames,
                                        ctx.frame_index,
                                        "line",
                                        null,
                                        null,
                                        null,
                                        1,
                                        .{ .resume_instruction = .{ .skip_line = true } },
                                    )) {
                                        continue :frame_loop;
                                    }
                                    self.dispatchBytecodeHook("line", null, null) catch |hook_err| {
                                        if (hook_err == error.Yield) {
                                            self.parkBytecodeIrHookYield(exec_frames, ctx.frame_index, fr.u.lua.pc, false, yielded_in_place);
                                        }
                                        return hook_err;
                                    };
                                    ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                                    fr = exec_frames.getPtr(ctx.frame_index);
                                    ctx.pc = fr.u.lua.pc;
                                }
                            }
                        }

                        if (hook_state.count > 0 and !self.isInDebugHook() and self.debug_hooks_suppressed == 0) {
                            // TODO(count-hook-codegen-parity, remove before 1.0.0):
                            // The direct bytecode codegen currently emits MOVE and
                            // LOADNIL as register-allocation/cleanup bookkeeping more
                            // often than PUC Lua. Do not charge those implementation
                            // details to the user-visible instruction count; otherwise
                            // tight loops fire count hooks roughly twice as often as
                            // the reference VM. Removal criterion: db.lua count-hook
                            // assertions pass when every dispatched instruction
                            // decrements the hook budget.
                            var count_this_inst = op != .move and op != .loadnil and op != .close;
                            if (fr.u.lua.resume_skip_count_pc != INVALID_PC) {
                                const skip_pc = fr.u.lua.resume_skip_count_pc;
                                if (skip_pc == @as(u32, @intCast(fr.u.lua.pc))) {
                                    // A count hook yielded before this opcode ran. On
                                    // resume, execute that opcode without immediately
                                    // firing the same hook again.
                                    count_this_inst = false;
                                    fr.u.lua.resume_skip_count_pc = INVALID_PC;
                                } else {
                                    fr.u.lua.resume_skip_count_pc = INVALID_PC;
                                }
                            } else if (hook_state.skip_count_once) {
                                hook_state.skip_count_once = false;
                                count_this_inst = false;
                            }

                            if (count_this_inst) {
                                hook_state.budget -= 1;
                                if (hook_state.budget <= 0) {
                                    hook_state.budget = hook_state.count;
                                    if (try self.tryPushBytecodeDebugHook(
                                        exec_frames,
                                        ctx.frame_index,
                                        "count",
                                        null,
                                        null,
                                        null,
                                        1,
                                        .{ .resume_instruction = .{ .skip_count = true } },
                                    )) {
                                        continue :frame_loop;
                                    }
                                    self.dispatchBytecodeHook("count", null, null) catch |hook_err| {
                                        if (hook_err == error.Yield) {
                                            self.parkBytecodeIrHookYield(exec_frames, ctx.frame_index, fr.u.lua.pc, true, yielded_in_place);
                                        }
                                        return hook_err;
                                    };
                                    // A hook can recursively run Lua and reallocate
                                    // both arrays used by the explicit dispatch loop.
                                    ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                                    fr = exec_frames.getPtr(ctx.frame_index);
                                    ctx.pc = fr.u.lua.pc;
                                }
                            }
                        }
                    }
                } // end combined dispatch gate (P16.19 T5-A)
                // PUC does not check GC every instruction. GC steps happen
                // only at allocation sites via condGcFromDispatch (OP_CONCAT,
                // OP_CLOSURE) and allocTable (OP_NEWTABLE), matching PUC's
                // checkGC(L,c) / luaC_checkGC pattern.

                switch (op) {
                    .move => {
                        // PUC OP_MOVE: setobjs2s(L, ra, RB(i)) — a single
                        // TValue copy, no upvalue check, no barrier.
                        //
                        // P16.8a invariant proof (OP_MOVE classification):
                        //
                        // The old code had a hasOpenUpvalues() slow path that:
                        //   (a) read the source through cell.get() when boxed[b]
                        //       held an open cell, and
                        //   (b) synced the destination cell via gcStoreCellValue
                        //       when boxed[a] held a closed cell.
                        //
                        // Both branches are redundant under the captured-local
                        // storage invariant (see the Cell invariant block at
                        // vm.zig:627):
                        //
                        // (a) Source: boxed[b] is non-null ONLY for open cells
                        //     (closeBytecodeUpvaluesFrom:6974 nulls boxed[i] on
                        //     close). For an open cell, cell.get() reads
                        //     resolveStack(vm)[bc_stack_idx] = ctx.regs[b]
                        //     (bc_stack_idx = base + b, ctx.regs = bc_stack[base..]).
                        //     Therefore cell.get() == ctx.regs[b] always. The
                        //     source read through the cell is REDUNDANT.
                        //
                        // (b) Destination: boxed[a] is non-null ONLY for open
                        //     cells. The check `!cell.isOpen()` is always false
                        //     (boxed[] never holds closed cells). Even if it
                        //     could: for an open cell, ctx.regs[a] = ... already
                        //     updates the stack slot (which IS the cell's
                        //     storage), so no sync is needed. The destination
                        //     sync branch is DEAD CODE.
                        //
                        // (c) GC barrier: PUC OP_MOVE fires NO barrier. Open
                        //     upvalues point to the stack; stack writes
                        //     automatically update them. The barrier is only
                        //     needed on CLOSE (luaF_closeupval → luaC_barrier).
                        //     The old gcStoreCellValue call was not just dead
                        //     code — it was semantically wrong (PUC doesn't
                        //     barrier MOVE).
                        //
                        // Conclusion: the entire hasOpenUpvalues() slow path is
                        // unnecessary. OP_MOVE is a plain TValue copy, exactly
                        // matching PUC's setobjs2s(L, ra, RB(i)).
                        ctx.regs[a] = ctx.regs[b];
                    },
                    .loadk => {
                        const kid: u32 = b;
                        ctx.regs[a] = ctx.cur_proto.resolved_values[kid];
                    },
                    .loadkx => {
                        // Next instruction is EXTRAARG with the constant index.
                        ctx.pc += 1;
                        const extra = ctx.cur_proto.code[ctx.pc];
                        const kid: u32 = extra.extraArg();
                        ctx.regs[a] = ctx.cur_proto.resolved_values[kid];
                    },
                    .loadi => {
                        // 17-bit sBx: k=bit16, b=low8, c=high8.
                        // OFFSET_sBx = 65535 (PUC MAXARG_sBx >> 1).
                        const bits: u17 = @as(u17, b) | (@as(u17, c) << 8) | (@as(u17, inst.k) << 16);
                        const signed: i32 = @as(i32, @intCast(bits)) - 65535;
                        ctx.regs[a] = .{ .Int = signed };
                    },
                    .loadf => {
                        const bits: u17 = @as(u17, b) | (@as(u17, c) << 8) | (@as(u17, inst.k) << 16);
                        const signed: f64 = @floatFromInt(@as(i32, @intCast(bits)) - 65535);
                        ctx.regs[a] = .{ .Num = signed };
                    },
                    .loadnil => {
                        var i: u8 = 0;
                        while (i <= b) : (i += 1) ctx.regs[a + i] = .Nil;
                    },
                    .loadtrue => ctx.regs[a] = .{ .Bool = true },
                    .loadfalse => ctx.regs[a] = .{ .Bool = false },
                    .lfalseskip => {
                        // PUC 5.5 OP_LFALSESKIP: load false, then skip the next
                        // instruction. Used for boolean expression folding.
                        // The default ctx.pc += 1 after the switch advances past
                        // this instruction; the extra += 1 here skips the next.
                        ctx.regs[a] = .{ .Bool = false };
                        ctx.pc += 1;
                    },

                    .getupval => ctx.regs[a] = ctx.cur_upvalues[b].get(self),
                    .setupval => try self.gcStoreCellValue(ctx.cur_upvalues[b], ctx.regs[a]),

                    .gettabup => {
                        // R[A] = UpVal[B][K[C]]
                        const env = ctx.cur_upvalues[b].get(self);
                        const key = ctx.cur_proto.resolved_values[c];
                        // P15.38a: PUC luaV_fastget fast path. If env is a table
                        // without metatable, do a single rawGet instead of the
                        // double lookup (tryPushBytecodeIndexMetamethod probe +
                        // indexValue). Mirrors the .getfield fast path (vm.zig:7584).
                        // Slow path uses indexValue (not bytecodeIndexValue) because
                        // env is an upvalue, not a register — no ctx.regs slice
                        // invalidation possible.
                        if (env == .Table and env.Table.metatable == null) {
                            // P16.1b: inline nodeLookup (same as GETFIELD).
                            // The key is always a constant String here —
                            // rawGet's key-type switch and call overhead are
                            // unnecessary. (Was: rawGet funnel; rawGet was
                            // 10% of the field_access profile.)
                            if (self.stats.enabled) self.stats.tbl_get_fast_str += 1; // P16.0b (constant string key)
                            ctx.regs[a] = if (ltable.nodeLookupStr(env.Table.hash, key.String)) |node|
                                node.value
                            else
                                .Nil;
                        } else {
                            if (try self.bytecodeGetIndex(exec_frames, &ctx, env, key, a, 0, false)) {
                                continue :frame_loop;
                            }
                        }
                    },
                    .settabup => {
                        // UpVal[A][K[B]] = RK[C]
                        // PUC 5.5 k-bit: k=0 → R[C], k=1 → K[C] (constant pool).
                        const env = ctx.cur_upvalues[a].get(self);
                        const key = ctx.cur_proto.resolved_values[b];
                        const val = if (inst.k == 1) ctx.cur_proto.resolved_values[c] else ctx.regs[c];
                        // When the upvalue is nil/non-table, include the
                        // upvalue name in the error message (like GETUPVAL+
                        // SETFIELD does via debugBytecodeOperandName).
                        if (env != .Table) {
                            const upv_name = if (a < ctx.cur_proto.upvalues.len)
                                ctx.cur_proto.upvalues[a].name()
                            else
                                "";
                            const tn = switch (env) {
                                .Nil => "nil",
                                .Int, .Num => "number",
                                .String => "string",
                                .Bool => "boolean",
                                .Builtin, .Closure => "function",
                                .Table => unreachable,
                                else => "table",
                            };
                            return self.fail("attempt to index a {s} value (upvalue '{s}')", .{ tn, upv_name });
                        }
                        if (env.Table.metatable == null) {
                            // Inline fast path: direct nodeLookup for existing
                            // key → value-barrier → store; absent → rawSet owns
                            // new-key semantics. The key is always a constant
                            // String — rawSet's array-part check and call
                            // overhead are unnecessary.
                            const tbl = env.Table;
                            if (self.stats.enabled) self.stats.tbl_set_fast_str += 1;
                            if (ltable.nodeLookupStr(tbl.hash, key.String)) |node| {
                                if (self.stats.enabled) self.stats.tbl_update += 1;
                                if (val == .Nil) {
                                    // Delete: no barrier (no new reference).
                                    node.value = .Nil;
                                } else {
                                    // Existing-slot update: VALUE barrier only
                                    // (key already owned), BEFORE store.
                                    try self.gcTableBarrierBackValue(tbl, val);
                                    if (node.value == .Nil) {
                                        tbl.flags &= ~TableFlags.MASK;
                                    }
                                    node.value = val;
                                }
                            } else {
                                // New key: rawSet owns new-key semantics.
                                try self.rawSet(tbl, key, val);
                            }
                        } else {
                            if (try self.bytecodeSetIndex(exec_frames, &ctx, env, key, val, 0, false)) {
                                continue :frame_loop;
                            }
                        }
                    },

                    .gettable => {
                        // R[A] = R[B][R[C]] — may trigger __index metamethod.
                        const obj = ctx.regs[b];
                        const key = ctx.regs[c];
                        // Fast path: table without metatable. For integer
                        // keys in array range, direct array access (PUC
                        // ikeyinarray). For Int (non-array) and String keys,
                        // inline nodeLookup. Other types (Num, Bool, etc.)
                        // fall back to rawGet which handles float→int coercion.
                        if (obj == .Table and obj.Table.metatable == null) {
                            const tbl = obj.Table;
                            if (key == .Int and key.Int >= 1) {
                                if (self.stats.enabled) self.stats.tbl_get_fast_int += 1; // P16.0b
                                const arr_len: i64 = @intCast(tbl.asize);
                                if (key.Int <= arr_len) {
                                    ctx.regs[a] = tbl.array[@intCast(key.Int - 1)];
                                } else {
                                    // P16.6: specialized int hash lookup (PUC
                                    // getintfromhash, ltable.c:929-942). Key is
                                    // provably .Int — skip Value construction
                                    // and the generic keyMatches tag switch.
                                    ctx.regs[a] = if (ltable.nodeLookupInt(tbl.hash, key.Int, self.hash_seed)) |node|
                                        node.value
                                    else
                                        .Nil;
                                }
                            } else if (key == .String) {
                                if (self.stats.enabled) self.stats.tbl_get_fast_str += 1; // P16.0b
                                ctx.regs[a] = if (ltable.nodeLookupStr(tbl.hash, key.String)) |node|
                                    node.value
                                else
                                    .Nil;
                            } else {
                                ctx.regs[a] = self.rawGet(tbl, key);
                            }
                        } else {
                            if (try self.bytecodeGetIndex(exec_frames, &ctx, obj, key, a, b, true)) {
                                continue :frame_loop;
                            }
                        }
                    },
                    .geti => {
                        // R[A] = R[B][C]  (integer key)
                        const obj = ctx.regs[b];
                        // Fast path: table without metatable, key in array
                        // range — direct array access, no function call.
                        // Mirrors PUC luaH_getint's ikeyinarray fast path
                        // (checkrange: (k-1) < asize), which C compilers inline.
                        if (obj == .Table and obj.Table.metatable == null) {
                            const tbl = obj.Table;
                            const k: usize = c; // c is u8, 1-based
                            if (k >= 1 and k <= tbl.asize) {
                                if (self.stats.enabled) self.stats.tbl_get_fast_int += 1; // P16.0b
                                ctx.regs[a] = tbl.array[k - 1];
                            } else {
                                // P16.6: specialized int hash lookup (PUC
                                // getintfromhash). Key is provably .Int (c is
                                // u8, 1-based) and outside array range — skip
                                // rawGet's switch + redundant array check.
                                ctx.regs[a] = if (ltable.nodeLookupInt(tbl.hash, @intCast(c), self.hash_seed)) |node|
                                    node.value
                                else
                                    .Nil;
                            }
                        } else {
                            const key: Value = .{ .Int = @intCast(c) };
                            if (try self.bytecodeGetIndex(exec_frames, &ctx, obj, key, a, b, true)) {
                                continue :frame_loop;
                            }
                        }
                    },
                    .getfield => {
                        // R[A] = R[B][K[C]]  (string key)
                        const obj = ctx.regs[b];
                        const key = ctx.cur_proto.resolved_values[c];
                        if (obj == .Table and obj.Table.metatable == null) {
                            // Inline rawGet fast path: direct nodeLookup.
                            // rawGet's switch on key type is unnecessary —
                            // key is always String for GETFIELD. This
                            // eliminates the function call to rawGet and
                            // inlines nodeLookup into the dispatch loop.
                            const tbl = obj.Table;
                            if (self.stats.enabled) self.stats.tbl_get_fast_str += 1; // P16.0b
                            ctx.regs[a] = if (ltable.nodeLookupStr(tbl.hash, key.String)) |node|
                                node.value
                            else
                                .Nil;
                        } else {
                            if (try self.bytecodeGetIndex(exec_frames, &ctx, obj, key, a, b, true)) {
                                continue :frame_loop;
                            }
                        }
                    },
                    .getvarg => {
                        // R[A] := vararg_param[R[C]] — virtual vararg access.
                        // PUC 5.5 OP_GETVARG / luaT_getvararg (ltm.c:292-311).
                        // If the vararg table was materialized (VATAB via
                        // needVarargTable), regs[b] is a Table — read from it.
                        // Otherwise (VAHID), read from hidden args on the stack.
                        const va_val = ctx.regs[b];
                        const key = ctx.regs[c];
                        if (va_val == .Table) {
                            // VATAB: read from the materialized table.
                            if (key == .Int) {
                                ctx.regs[a] = self.rawGet(va_val.Table, key);
                            } else if (key == .String) {
                                const sbytes = key.String.bytes();
                                if (sbytes.len == 1 and sbytes[0] == 'n') {
                                    ctx.regs[a] = self.getFieldOpt(va_val.Table, "n") orelse .Nil;
                                } else {
                                    ctx.regs[a] = .Nil;
                                }
                            } else {
                                ctx.regs[a] = .Nil;
                            }
                        } else {
                            // VAHID: read from hidden varargs on the stack.
                            // P15.51l: nextraargs/func_slot are rare fields,
                            // read directly from the CallFrame.
                            const fr_va = exec_frames.getPtr(ctx.frame_index);
                            const nextra: usize = fr_va.u.lua.nextraargs;
                            const va_base_idx = fr_va.func_slot - nextra;
                            if (key == .Int) {
                                const n: i64 = key.Int;
                                if (n >= 1 and @as(usize, @intCast(n)) <= nextra) {
                                    ctx.regs[a] = self.bc_stack[va_base_idx + @as(usize, @intCast(n - 1))];
                                } else {
                                    ctx.regs[a] = .Nil;
                                }
                            } else if (key == .String) {
                                // Only the single-character string "n" is valid.
                                const sbytes = key.String.bytes();
                                if (sbytes.len == 1 and sbytes[0] == 'n') {
                                    ctx.regs[a] = .{ .Int = @intCast(nextra) };
                                } else {
                                    ctx.regs[a] = .Nil;
                                }
                            } else {
                                // Float keys: PUC tries integer coercion (tointegerns).
                                // A float like 2.0 should work. Match PUC's behavior.
                                if (key == .Num) {
                                    const f = key.Num;
                                    if (!std.math.isNan(f) and !std.math.isInf(f) and @floor(f) == f) {
                                        if (f >= 1 and f <= @as(f64, @floatFromInt(std.math.maxInt(i32)))) {
                                            const n: i64 = @intFromFloat(f);
                                            if (@as(usize, @intCast(n)) <= nextra) {
                                                ctx.regs[a] = self.bc_stack[va_base_idx + @as(usize, @intCast(n - 1))];
                                            } else {
                                                ctx.regs[a] = .Nil;
                                            }
                                        } else {
                                            ctx.regs[a] = .Nil;
                                        }
                                    } else {
                                        ctx.regs[a] = .Nil;
                                    }
                                } else {
                                    ctx.regs[a] = .Nil;
                                }
                            }
                        }
                    },
                    .settable => {
                        // R[A][R[B]] = RK[C] — may trigger __newindex metamethod.
                        // PUC 5.5 k-bit: k=0 → R[C], k=1 → K[C] (constant pool).
                        // Snapshot all register values before the call.
                        const obj = ctx.regs[a];
                        const key = ctx.regs[b];
                        const val = if (inst.k == 1) ctx.cur_proto.resolved_values[c] else ctx.regs[c];
                        // Fast path: table without metatable. For String and Int
                        // keys, inline lookup → value-barrier → store; absent →
                        // rawSet owns new-key semantics. Other types fall back
                        // to rawSet (which has float→int coercion).
                        if (obj == .Table and obj.Table.metatable == null) {
                            const tbl = obj.Table;
                            if (key == .String) {
                                if (self.stats.enabled) self.stats.tbl_set_fast_str += 1;
                                if (ltable.nodeLookupStr(tbl.hash, key.String)) |node| {
                                    if (self.stats.enabled) self.stats.tbl_update += 1;
                                    if (val == .Nil) {
                                        node.value = .Nil;
                                    } else {
                                        try self.gcTableBarrierBackValue(tbl, val);
                                        node.value = val;
                                    }
                                } else {
                                    try self.rawSet(tbl, key, val);
                                }
                            } else if (key == .Int) {
                                if (self.stats.enabled) self.stats.tbl_set_fast_int += 1;
                                const k = key.Int;
                                if (k >= 1) {
                                    const arr_len: i64 = @intCast(tbl.asize);
                                    if (k <= arr_len) {
                                        // Array range: value-barrier → store.
                                        try self.gcTableBarrierBackValue(tbl, val);
                                        tbl.array[@intCast(k - 1)] = val;
                                    } else {
                                        // Hash-part lookup: specialized int path.
                                        if (ltable.nodeLookupInt(tbl.hash, k, self.hash_seed)) |node| {
                                            if (self.stats.enabled) self.stats.tbl_update += 1;
                                            if (val == .Nil) {
                                                node.value = .Nil;
                                            } else {
                                                try self.gcTableBarrierBackValue(tbl, val);
                                                if (node.value == .Nil) {
                                                    tbl.flags &= ~TableFlags.MASK;
                                                }
                                                node.value = val;
                                            }
                                        } else {
                                            try self.rawSet(tbl, key, val);
                                        }
                                    }
                                } else {
                                    // Negative/zero int key: hash part only.
                                    if (ltable.nodeLookupInt(tbl.hash, k, self.hash_seed)) |node| {
                                        if (self.stats.enabled) self.stats.tbl_update += 1;
                                        if (val == .Nil) {
                                            node.value = .Nil;
                                        } else {
                                            try self.gcTableBarrierBackValue(tbl, val);
                                            if (node.value == .Nil) {
                                                tbl.flags &= ~TableFlags.MASK;
                                            }
                                            node.value = val;
                                        }
                                    } else {
                                        try self.rawSet(tbl, key, val);
                                    }
                                }
                            } else {
                                try self.rawSet(tbl, key, val);
                            }
                        } else {
                            if (try self.bytecodeSetIndex(exec_frames, &ctx, obj, key, val, a, true)) {
                                continue :frame_loop;
                            }
                        }
                    },
                    .seti => {
                        // R[A][B] = RK[C]  (integer key)
                        // PUC 5.5 k-bit: k=0 → R[C], k=1 → K[C] (constant pool).
                        const obj = ctx.regs[a];
                        const val = if (inst.k == 1) ctx.cur_proto.resolved_values[c] else ctx.regs[c];
                        // Fast path: table without metatable, key in array
                        // range — value-barrier → store (PUC obj2arr).
                        if (obj == .Table and obj.Table.metatable == null) {
                            const tbl = obj.Table;
                            const k: usize = b; // b is u8, 1-based
                            if (k >= 1 and k <= tbl.asize) {
                                if (self.stats.enabled) self.stats.tbl_set_fast_int += 1;
                                try self.gcTableBarrierBackValue(tbl, val);
                                tbl.array[k - 1] = val;
                            } else {
                                try self.rawSet(tbl, .{ .Int = @intCast(b) }, val);
                            }
                        } else {
                            @branchHint(.unlikely);
                            const key: Value = .{ .Int = @intCast(b) };
                            if (try self.bytecodeSetIndex(exec_frames, &ctx, obj, key, val, a, true)) {
                                continue :frame_loop;
                            }
                        }
                    },
                    .setfield => {
                        // R[A][K[B]] = RK[C]  (string key)
                        // PUC 5.5 k-bit: k=0 → R[C], k=1 → K[C] (constant pool).
                        const obj = ctx.regs[a];
                        const key = ctx.cur_proto.resolved_values[b];
                        const val = if (inst.k == 1) ctx.cur_proto.resolved_values[c] else ctx.regs[c];
                        if (obj == .Table and obj.Table.metatable == null) {
                            // Inline fast path: direct nodeLookup for existing
                            // key → value-barrier → store; absent → rawSet
                            // owns new-key semantics.
                            const tbl = obj.Table;
                            if (self.stats.enabled) self.stats.tbl_set_fast_str += 1;
                            if (ltable.nodeLookupStr(tbl.hash, key.String)) |node| {
                                if (self.stats.enabled) self.stats.tbl_update += 1;
                                if (val == .Nil) {
                                    // Delete: no barrier (no new reference).
                                    node.value = .Nil;
                                } else {
                                    // Existing-slot update: VALUE barrier only
                                    // (key already owned), BEFORE store.
                                    try self.gcTableBarrierBackValue(tbl, val);
                                    if (node.value == .Nil) {
                                        tbl.flags &= ~TableFlags.MASK;
                                    }
                                    node.value = val;
                                }
                            } else {
                                // New key: rawSet owns new-key semantics.
                                try self.rawSet(tbl, key, val);
                            }
                        } else {
                            if (try self.bytecodeSetIndex(exec_frames, &ctx, obj, key, val, a, true)) {
                                continue :frame_loop;
                            }
                        }
