                        const rc = ctx.regs[c];
                        if (lb == .Int and rc == .Int) {
                            ctx.regs[a] = .{ .Int = lb.Int & rc.Int };
                            ctx.pc += 1; // skip MMBIN
                        } else {
                            const li = valueToIntForBitwise(lb);
                            const ri = valueToIntForBitwise(rc);
                            if (li != null and ri != null) {
                                ctx.regs[a] = .{ .Int = li.? & ri.? };
                                ctx.pc += 1; // skip MMBIN
                            }
                            // else: fall through to MMBIN.
                        }
                    },
                    .bor => {
                        const lb = ctx.regs[b];
                        const rc = ctx.regs[c];
                        if (lb == .Int and rc == .Int) {
                            ctx.regs[a] = .{ .Int = lb.Int | rc.Int };
                            ctx.pc += 1; // skip MMBIN
                        } else {
                            const li = valueToIntForBitwise(lb);
                            const ri = valueToIntForBitwise(rc);
                            if (li != null and ri != null) {
                                ctx.regs[a] = .{ .Int = li.? | ri.? };
                                ctx.pc += 1; // skip MMBIN
                            }
                            // else: fall through to MMBIN.
                        }
                    },
                    .bxor => {
                        const lb = ctx.regs[b];
                        const rc = ctx.regs[c];
                        if (lb == .Int and rc == .Int) {
                            ctx.regs[a] = .{ .Int = lb.Int ^ rc.Int };
                            ctx.pc += 1; // skip MMBIN
                        } else {
                            const li = valueToIntForBitwise(lb);
                            const ri = valueToIntForBitwise(rc);
                            if (li != null and ri != null) {
                                ctx.regs[a] = .{ .Int = li.? ^ ri.? };
                                ctx.pc += 1; // skip MMBIN
                            }
                            // else: fall through to MMBIN.
                        }
                    },
                    .shl => {
                        const lb = ctx.regs[b];
                        const rc = ctx.regs[c];
                        if (lb == .Int and rc == .Int) {
                            ctx.regs[a] = .{ .Int = shiftLeft(lb.Int, rc.Int) };
                            ctx.pc += 1; // skip MMBIN
                        } else {
                            const li = valueToIntForBitwise(lb);
                            const ri = valueToIntForBitwise(rc);
                            if (li != null and ri != null) {
                                ctx.regs[a] = .{ .Int = shiftLeft(li.?, ri.?) };
                                ctx.pc += 1; // skip MMBIN
                            }
                            // else: fall through to MMBIN.
                        }
                    },
                    .shr => {
                        const lb = ctx.regs[b];
                        const rc = ctx.regs[c];
                        if (lb == .Int and rc == .Int) {
                            ctx.regs[a] = .{ .Int = shiftRight(lb.Int, rc.Int) };
                            ctx.pc += 1; // skip MMBIN
                        } else {
                            const li = valueToIntForBitwise(lb);
                            const ri = valueToIntForBitwise(rc);
                            if (li != null and ri != null) {
                                ctx.regs[a] = .{ .Int = shiftRight(li.?, ri.?) };
                                ctx.pc += 1; // skip MMBIN
                            }
                            // else: fall through to MMBIN.
                        }
                    },

                    // --- Arithmetic: immediate/constant variants (PUC 5.5 style) ---
                    // These opcodes take R[B] as the left operand and a constant
                    // or immediate as the right operand, eliminating the LOADK
                    // instruction that would otherwise materialize the constant.
                    //
                    // ADDI: R[A] = R[B] + sC  (sC = C - 127, signed 8-bit)
                    // Also used for `x - K` via finishbinexpneg: the subtraction
                    // is coded as `x + (-K)`, with the following MMBINI carrying
                    // TmsEvent.sub (not .add) and B = int2sC(K) (original K).
                    // The MMBINI handler decodes the correct event + operands;
                    // ADDI just computes R[B] + sC and falls through on failure.
                    .addi => {
                        const lb = ctx.regs[b];
                        const imm: i64 = @as(i64, c) - 127; // sC2int
                        if (lb == .Int) {
                            ctx.regs[a] = .{ .Int = lb.Int +% imm };
                            ctx.pc += 1; // skip MMBINI
                        } else if (lb == .Num) {
                            ctx.regs[a] = .{ .Num = lb.Num + @as(f64, @floatFromInt(imm)) };
                            ctx.pc += 1;
                        } else {
                            // Fall through to MMBINI (string mt __add).
                        }
                    },

                    // ADDK: R[A] = R[B] + K[C]:number
                    .addk => {
                        const lb = ctx.regs[b];
                        const rc = ctx.cur_proto.resolved_values[c];
                        if (lb == .Int and rc == .Int) {
                            ctx.regs[a] = .{ .Int = lb.Int +% rc.Int };
                            ctx.pc += 1; // skip MMBINK
                        } else if (lb == .Num and rc == .Num) {
                            ctx.regs[a] = .{ .Num = lb.Num + rc.Num };
                            ctx.pc += 1;
                        } else if (lb == .Int and rc == .Num) {
                            ctx.regs[a] = .{ .Num = @as(f64, @floatFromInt(lb.Int)) + rc.Num };
                            ctx.pc += 1;
                        } else if (lb == .Num and rc == .Int) {
                            ctx.regs[a] = .{ .Num = lb.Num + @as(f64, @floatFromInt(rc.Int)) };
                            ctx.pc += 1;
                        } else {
                            // Fall through to MMBINK (string mt __add).
                        }
                    },

                    // SUBK: R[A] = R[B] - K[C]:number
                    .subk => {
                        const lb = ctx.regs[b];
                        const rc = ctx.cur_proto.resolved_values[c];
                        if (lb == .Int and rc == .Int) {
                            ctx.regs[a] = .{ .Int = lb.Int -% rc.Int };
                            ctx.pc += 1; // skip MMBINK
                        } else if (lb == .Num and rc == .Num) {
                            ctx.regs[a] = .{ .Num = lb.Num - rc.Num };
                            ctx.pc += 1;
                        } else if (lb == .Int and rc == .Num) {
                            ctx.regs[a] = .{ .Num = @as(f64, @floatFromInt(lb.Int)) - rc.Num };
                            ctx.pc += 1;
                        } else if (lb == .Num and rc == .Int) {
                            ctx.regs[a] = .{ .Num = lb.Num - @as(f64, @floatFromInt(rc.Int)) };
                            ctx.pc += 1;
                        } else {
                            // Fall through to MMBINK (string mt __sub).
                        }
                    },

                    // MULK: R[A] = R[B] * K[C]:number
                    .mulk => {
                        const lb = ctx.regs[b];
                        const rc = ctx.cur_proto.resolved_values[c];
                        if (lb == .Int and rc == .Int) {
                            ctx.regs[a] = .{ .Int = lb.Int *% rc.Int };
                            ctx.pc += 1; // skip MMBINK
                        } else if (lb == .Num and rc == .Num) {
                            ctx.regs[a] = .{ .Num = lb.Num * rc.Num };
                            ctx.pc += 1;
                        } else if (lb == .Int and rc == .Num) {
                            ctx.regs[a] = .{ .Num = @as(f64, @floatFromInt(lb.Int)) * rc.Num };
                            ctx.pc += 1;
                        } else if (lb == .Num and rc == .Int) {
                            ctx.regs[a] = .{ .Num = lb.Num * @as(f64, @floatFromInt(rc.Int)) };
                            ctx.pc += 1;
                        } else {
                            // Fall through to MMBINK (string mt __mul).
                        }
                    },

                    // MODK: R[A] = R[B] % K[C]:number
                    .modk => {
                        const lb = ctx.regs[b];
                        const rc = ctx.cur_proto.resolved_values[c];
                        if (lb == .Int and rc == .Int) {
                            const li = lb.Int;
                            const ri = rc.Int;
                            if (ri == 0) {
                                exec_frames.getPtr(ctx.frame_index).u.lua.pc = ctx.pc;
                                return self.fail("attempt to perform 'n%0'", .{});
                            }
                            if (li == std.math.minInt(i64) and ri == -1) {
                                ctx.regs[a] = .{ .Int = 0 };
                            } else {
                                var rem = @rem(li, ri);
                                if (rem != 0 and ((rem ^ ri) < 0)) rem += ri;
                                ctx.regs[a] = .{ .Int = rem };
                            }
                            ctx.pc += 1; // skip MMBINK
                        } else if (lb == .Num and rc == .Num) {
                            ctx.regs[a] = .{ .Num = luaNumMod(lb.Num, rc.Num) };
                            ctx.pc += 1;
                        } else if (lb == .Int and rc == .Num) {
                            ctx.regs[a] = .{ .Num = luaNumMod(@as(f64, @floatFromInt(lb.Int)), rc.Num) };
                            ctx.pc += 1;
                        } else if (lb == .Num and rc == .Int) {
                            ctx.regs[a] = .{ .Num = luaNumMod(lb.Num, @as(f64, @floatFromInt(rc.Int))) };
                            ctx.pc += 1;
                        } else {
                            // Fall through to MMBINK (string mt __mod).
                        }
                    },

                    // POWK: R[A] = R[B] ^ K[C]:number
                    .powk => {
                        const lb = ctx.regs[b];
                        const rc = ctx.cur_proto.resolved_values[c];
                        if (lb == .Int and rc == .Int) {
                            ctx.regs[a] = .{ .Num = std.math.pow(f64, @as(f64, @floatFromInt(lb.Int)), @as(f64, @floatFromInt(rc.Int))) };
                            ctx.pc += 1; // skip MMBINK
                        } else if (lb == .Num and rc == .Num) {
                            ctx.regs[a] = .{ .Num = std.math.pow(f64, lb.Num, rc.Num) };
                            ctx.pc += 1;
                        } else if (lb == .Int and rc == .Num) {
                            ctx.regs[a] = .{ .Num = std.math.pow(f64, @as(f64, @floatFromInt(lb.Int)), rc.Num) };
                            ctx.pc += 1;
                        } else if (lb == .Num and rc == .Int) {
                            ctx.regs[a] = .{ .Num = std.math.pow(f64, lb.Num, @as(f64, @floatFromInt(rc.Int))) };
                            ctx.pc += 1;
                        } else {
                            // Fall through to MMBINK (string mt __pow).
                        }
                    },

                    // DIVK: R[A] = R[B] / K[C]:number
                    .divk => {
                        const lb = ctx.regs[b];
                        const rc = ctx.cur_proto.resolved_values[c];
                        if (lb == .Int and rc == .Int) {
                            ctx.regs[a] = .{ .Num = @as(f64, @floatFromInt(lb.Int)) / @as(f64, @floatFromInt(rc.Int)) };
                            ctx.pc += 1; // skip MMBINK
                        } else if (lb == .Num and rc == .Num) {
                            ctx.regs[a] = .{ .Num = lb.Num / rc.Num };
                            ctx.pc += 1;
                        } else if (lb == .Int and rc == .Num) {
                            ctx.regs[a] = .{ .Num = @as(f64, @floatFromInt(lb.Int)) / rc.Num };
                            ctx.pc += 1;
                        } else if (lb == .Num and rc == .Int) {
                            ctx.regs[a] = .{ .Num = lb.Num / @as(f64, @floatFromInt(rc.Int)) };
                            ctx.pc += 1;
                        } else {
                            // Fall through to MMBINK (string mt __div).
                        }
                    },

                    // IDIVK: R[A] = R[B] // K[C]:number
                    .idivk => {
                        const lb = ctx.regs[b];
                        const rc = ctx.cur_proto.resolved_values[c];
                        if (lb == .Int and rc == .Int) {
                            const ri = rc.Int;
                            if (ri == 0) {
                                exec_frames.getPtr(ctx.frame_index).u.lua.pc = ctx.pc;
                                return self.fail("attempt to divide by zero", .{});
                            }
                            if (lb.Int == std.math.minInt(i64) and ri == -1) {
                                ctx.regs[a] = .{ .Int = std.math.minInt(i64) };
                            } else {
                                ctx.regs[a] = .{ .Int = @divFloor(lb.Int, ri) };
                            }
                            ctx.pc += 1; // skip MMBINK
                        } else if (lb == .Num and rc == .Num) {
                            ctx.regs[a] = .{ .Num = @floor(lb.Num / rc.Num) };
                            ctx.pc += 1;
                        } else if (lb == .Int and rc == .Num) {
                            ctx.regs[a] = .{ .Num = @floor(@as(f64, @floatFromInt(lb.Int)) / rc.Num) };
                            ctx.pc += 1;
                        } else if (lb == .Num and rc == .Int) {
                            ctx.regs[a] = .{ .Num = @floor(lb.Num / @as(f64, @floatFromInt(rc.Int))) };
                            ctx.pc += 1;
                        } else {
                            // Fall through to MMBINK (string mt __idiv).
                        }
                    },

                    // --- Bitwise: constant variants ---
                    // BANDK: R[A] = R[B] & K[C]:integer
                    .bandk => {
                        const lb = ctx.regs[b];
                        const rc = ctx.cur_proto.resolved_values[c];
                        if (lb == .Int and rc == .Int) {
                            ctx.regs[a] = .{ .Int = lb.Int & rc.Int };
                            ctx.pc += 1; // skip MMBINK
                        } else {
                            const li = valueToIntForBitwise(lb);
                            const ri = valueToIntForBitwise(rc);
                            if (li != null and ri != null) {
                                ctx.regs[a] = .{ .Int = li.? & ri.? };
                                ctx.pc += 1; // skip MMBINK
                            }
                            // else: fall through to MMBINK.
                        }
                    },
                    .bork => {
                        const lb = ctx.regs[b];
                        const rc = ctx.cur_proto.resolved_values[c];
                        if (lb == .Int and rc == .Int) {
                            ctx.regs[a] = .{ .Int = lb.Int | rc.Int };
                            ctx.pc += 1; // skip MMBINK
                        } else {
                            const li = valueToIntForBitwise(lb);
                            const ri = valueToIntForBitwise(rc);
                            if (li != null and ri != null) {
                                ctx.regs[a] = .{ .Int = li.? | ri.? };
                                ctx.pc += 1; // skip MMBINK
                            }
                            // else: fall through to MMBINK.
                        }
                    },
                    .bxork => {
                        const lb = ctx.regs[b];
                        const rc = ctx.cur_proto.resolved_values[c];
                        if (lb == .Int and rc == .Int) {
                            ctx.regs[a] = .{ .Int = lb.Int ^ rc.Int };
                            ctx.pc += 1; // skip MMBINK
                        } else {
                            const li = valueToIntForBitwise(lb);
                            const ri = valueToIntForBitwise(rc);
                            if (li != null and ri != null) {
                                ctx.regs[a] = .{ .Int = li.? ^ ri.? };
                                ctx.pc += 1; // skip MMBINK
                            }
                            // else: fall through to MMBINK.
                        }
                    },

                    // --- Shifts: immediate variants ---
                    // SHLI: R[A] = sC << R[B]  (sC = C - 127)
                    .shli => {
                        const lb = ctx.regs[b];
                        const imm: i64 = @as(i64, c) - 127;
                        if (lb == .Int) {
                            ctx.regs[a] = .{ .Int = shiftLeft(imm, lb.Int) };
                            ctx.pc += 1; // skip MMBINI
                        } else {
                            if (valueToIntForBitwise(lb)) |ri| {
                                ctx.regs[a] = .{ .Int = shiftLeft(imm, ri) };
                                ctx.pc += 1; // skip MMBINI
                            }
                            // else: fall through to MMBINI.
                        }
                    },
                    // SHRI: R[A] = R[B] >> sC  (sC = C - 127)
                    // Also used for `x << K` via finishbinexpneg: the shift is
                    // coded as `x >> (-K)`, with the following MMBINI carrying
                    // TmsEvent.shl (not .shr). The MMBINI handler decodes the
                    // correct event + operands; SHRI just computes R[B] >> sC
                    // and falls through on failure.
                    .shri => {
                        const lb = ctx.regs[b];
                        const imm: i64 = @as(i64, c) - 127;
                        if (lb == .Int) {
                            ctx.regs[a] = .{ .Int = shiftRight(lb.Int, imm) };
                            ctx.pc += 1; // skip MMBINI
                        } else {
                            if (valueToIntForBitwise(lb)) |li| {
                                ctx.regs[a] = .{ .Int = shiftRight(li, imm) };
                                ctx.pc += 1; // skip MMBINI
                            }
                            // else: fall through to MMBINI.
                        }
                    },

                    // --- Metamethod bookkeeping (PUC 5.5 MMBIN family) ---
                    // Real handlers: when the preceding arithmetic op failed to
                    // compute (non-numeric operands without coercion path), it
                    // falls through to MMBIN/MMBINI/MMBANK. These handlers try
                    // the metamethod (luaT_trybinTM) or produce the type error.
                    //
                    // PUC lvm.c:1556 OP_MMBIN: A=lhs_reg, B=rhs_reg, C=event, k=0.
                    // Result dest = pi.a (previous instruction's A field).
                    // Operands: (R[A], R[B]).
                    .mmbin => {
                        const pi = ctx.cur_proto.code[ctx.pc - 1];
                        const event: TmsEvent = @enumFromInt(@as(u5, @truncate(c)));
                        const lhs = ctx.regs[a];
                        const rhs = ctx.regs[b];
                        // PUC luaT_trybinTM (ltm.c:150-166): try metamethod
                        // on lhs, then rhs. No metamethod → type error.
                        // Metamethod not callable → call error.
                        // Resolve ONCE — no re-lookup in the push/call path.
                        const tm = self.findBinaryTm(lhs, rhs, event);
                        if (tm == null) {
                            return self.failBinaryMmbin(lhs, rhs, event, ctx.cur_proto, ctx.pc - 1, a, b);
                        }
                        // PUC two-stage: resolve the TMS value through normal
                        // callable semantics (handles __call chains), then
                        // invoke — bytecode Closure as continuation frame
                        // (yieldable), Builtin/C-closure synchronously.
                        exec_frames.getPtr(ctx.frame_index).u.lua.pc = ctx.pc;
                        switch (try self.tryPushSimpleResultMetamethod(
                            exec_frames,
                            ctx.frame_index,
                            tm.?,
                            &.{ lhs, rhs },
                            event,
                            .{ .value = pi.a },
                        )) {
                            .pushed => continue :frame_loop,
                            .value => |result| {
                                ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                                ctx.regs[pi.a] = result;
                            },
                            .compare => unreachable, // MMBIN never uses .compare
                        }
                    },
                    // PUC lvm.c:1566 OP_MMBINI: A=lhs_reg, sB=imm, C=event, k=flip.
                    // flip=0 → (R[A], Int(sB)); flip=1 → (Int(sB), R[A]).
                    .mmbini => {
                        const pi = ctx.cur_proto.code[ctx.pc - 1];
                        const event: TmsEvent = @enumFromInt(@as(u5, @truncate(c)));
                        const imm: i64 = @as(i64, b) - 127; // sB2int
                        const imm_val: Value = .{ .Int = imm };
                        const flip = inst.k != 0;
                        const lhs = if (flip) imm_val else ctx.regs[a];
                        const rhs = if (flip) ctx.regs[a] else imm_val;
                        // Resolve ONCE — no re-lookup in the push/call path.
                        const tm = self.findBinaryTm(lhs, rhs, event);
                        if (tm == null) {
                            // Bad operand is always R[A] (immediate is always valid).
                            return self.failBinaryMmbin(lhs, rhs, event, ctx.cur_proto, ctx.pc - 1, a, a);
                        }
                        exec_frames.getPtr(ctx.frame_index).u.lua.pc = ctx.pc;
                        switch (try self.tryPushSimpleResultMetamethod(
                            exec_frames,
                            ctx.frame_index,
                            tm.?,
                            &.{ lhs, rhs },
                            event,
                            .{ .value = pi.a },
                        )) {
                            .pushed => continue :frame_loop,
                            .value => |result| {
                                ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                                ctx.regs[pi.a] = result;
                            },
                            .compare => unreachable, // MMBINI never uses .compare
                        }
                    },
                    // PUC lvm.c:1576 OP_MMBANK: A=lhs_reg, B=K_idx, C=event, k=flip.
                    // flip=0 → (R[A], K[B]); flip=1 → (K[B], R[A]).
                    .mmbink => {
                        const pi = ctx.cur_proto.code[ctx.pc - 1];
                        const event: TmsEvent = @enumFromInt(@as(u5, @truncate(c)));
                        const kv = ctx.cur_proto.resolved_values[b];
                        const flip = inst.k != 0;
                        const lhs = if (flip) kv else ctx.regs[a];
                        const rhs = if (flip) ctx.regs[a] else kv;
                        // Resolve ONCE — no re-lookup in the push/call path.
                        const tm = self.findBinaryTm(lhs, rhs, event);
                        if (tm == null) {
                            // For error annotation: register side is `a`,
                            // constant side has no register (sentinel 255).
                            const p1_reg: u8 = if (flip) 255 else a;
                            const p2_reg: u8 = if (flip) a else 255;
                            return self.failBinaryMmbin(lhs, rhs, event, ctx.cur_proto, ctx.pc - 1, p1_reg, p2_reg);
                        }
                        exec_frames.getPtr(ctx.frame_index).u.lua.pc = ctx.pc;
                        switch (try self.tryPushSimpleResultMetamethod(
                            exec_frames,
                            ctx.frame_index,
                            tm.?,
                            &.{ lhs, rhs },
                            event,
                            .{ .value = pi.a },
                        )) {
                            .pushed => continue :frame_loop,
                            .value => |result| {
                                ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                                ctx.regs[pi.a] = result;
                            },
                            .compare => unreachable, // MMBANK never uses .compare
                        }
                    },

                    // PUC lvm.c:1586 OP_UNM: no following MMBIN — handles
                    // metamethod/error inline (luaT_trybinTM with rb,rb).
                    .unm => {
                        const val = ctx.regs[b];
                        if (val == .Int) {
                            ctx.regs[a] = .{ .Int = -%val.Int };
                        } else if (val == .Num) {
                            ctx.regs[a] = .{ .Num = -val.Num };
                        } else {
                            // PUC OP_UNM: luaT_trybinTM(L, rb, rb, ra, TM_UNM).
                            // String operands handled by string mt __unm
                            // (PUC lstrlib.c arith_unm).
                            // Resolve ONCE — no re-lookup in the push/call path.
                            const tm = self.findUnaryTm(val, .unm);
                            if (tm == null) {
                                exec_frames.getPtr(ctx.frame_index).u.lua.pc = ctx.pc;
                                return self.failBinaryMmbin(val, val, .unm, ctx.cur_proto, ctx.pc, b, b);
                            }
                            exec_frames.getPtr(ctx.frame_index).u.lua.pc = ctx.pc;
                            switch (try self.tryPushSimpleResultMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                tm.?,
                                &.{ val, val },
                                .unm,
                                .{ .value = a },
                            )) {
                                .pushed => continue :frame_loop,
                                .value => |result| {
                                    ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                                    ctx.regs[a] = result;
                                },
                                .compare => unreachable,
                            }
                        }
                    },
                    // PUC lvm.c:1598 OP_BNOT: no following MMBIN — handles
                    // metamethod/error inline (luaT_trybinTM with rb,rb).
                    .bnot => {
                        const val = ctx.regs[b];
                        if (val == .Int) {
                            ctx.regs[a] = .{ .Int = ~val.Int };
                        } else {
                            // Coercion: valueToIntForBitwise handles Int and
                            // Num-with-integer-value (NOT string — matches PUC
                            // tointegerns). On failure, try __bnot metamethod
                            // or produce type error inline.
                            if (valueToIntForBitwise(val)) |iv| {
                                ctx.regs[a] = .{ .Int = ~iv };
                            } else {
                                // PUC OP_BNOT: luaT_trybinTM(L, rb, rb, ra, TM_BNOT).
                                // Resolve ONCE — no re-lookup in the push/call path.
                                const tm = self.findUnaryTm(val, .bnot);
                                if (tm == null) {
                                    exec_frames.getPtr(ctx.frame_index).u.lua.pc = ctx.pc;
                                    return self.failBinaryMmbin(val, val, .bnot, ctx.cur_proto, ctx.pc, b, b);
                                }
                                exec_frames.getPtr(ctx.frame_index).u.lua.pc = ctx.pc;
                                switch (try self.tryPushSimpleResultMetamethod(
                                    exec_frames,
                                    ctx.frame_index,
                                    tm.?,
                                    &.{ val, val },
                                    .bnot,
                                    .{ .value = a },
                                )) {
                                    .pushed => continue :frame_loop,
                                    .value => |result| {
                                        ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                                        ctx.regs[a] = result;
                                    },
                                    .compare => unreachable,
                                }
                            }
                        }
                    },
                    .not => ctx.regs[a] = try self.evalUnOp(.Not, ctx.regs[b]),
                    .len => {
                        const val = ctx.regs[b];
                        // PUC OP_LEN: luaT_trybinTM(L, rb, rb, ra, TM_LEN).
                        // Strings have a fast path (no metamethod lookup).
                        // For all other types, resolve __len ONCE and carry
                        // the resolved value through push + synchronous fallback.
                        if (val == .String) {
                            ctx.regs[a] = .{ .Int = @intCast(val.String.len()) };
                        } else {
                            const tm = self.findUnaryTm(val, .len);
                            if (tm) |mm| {
                                exec_frames.getPtr(ctx.frame_index).u.lua.pc = ctx.pc;
                                switch (try self.tryPushSimpleResultMetamethod(
                                    exec_frames,
                                    ctx.frame_index,
                                    mm,
                                    &.{ val, val },
                                    .len,
                                    .{ .value = a },
                                )) {
                                    .pushed => continue :frame_loop,
                                    .value => |result| {
                                        ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                                        ctx.regs[a] = result;
                                    },
                                    .compare => unreachable,
                                }
                            } else {
                                // No __len metamethod: Table → border length,
                                // anything else → type error (matches evalUnOp).
                                ctx.regs[a] = switch (val) {
                                    .Table => |t| .{ .Int = self.tableBorderLen(t) },
                                    else => return self.fail("attempt to get length of a {s} value", .{val.typeName()}),
                                };
                            }
                        }
                    },

                    .concat => {
                        switch (try self.opConcat(&ctx)) {
                            .continue_dispatch => {},
                            .continue_no_advance => continue,
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => return error.RuntimeError,
                        }
                        // PUC: checkGC(L, L->top.p) after luaV_concat.
                        try self.condGcFromDispatch(&ctx);
                    },

                    // --- Comparisons ---
                    // EQ/LT/LE: if (R[A] op R[B]) != (C!=0) then ctx.pc++
                    // Snapshot operands — comparison may trigger metamethod.
                    .eq => {
                        const la = ctx.regs[a];
                        const lb = ctx.regs[b];
                        // Fast path: valuesEqual handles Int/Num/Bool/String/Nil
                        // comparisons directly. Only Table==Table and
                        // Userdata==Userdata with different identity need
                        // the __eq metamethod (PUC luaV_equalobj).
                        const result: bool = blk: {
                            if (valuesEqual(la, lb)) break :blk true;
                            // PUC luaV_equalobj: __eq only when both operands
                            // are the same type (Table/Table or Userdata/Userdata).
                            if ((la == .Table and lb == .Table) or
                                (la == .Userdata and lb == .Userdata))
                            {
                                // Resolve __eq ONCE — no re-lookup.
                                const tm = self.findBinaryTm(la, lb, .eq);
                                if (tm) |mm| {
                                    exec_frames.getPtr(ctx.frame_index).u.lua.pc = ctx.pc;
                                    switch (try self.tryPushSimpleResultMetamethod(
                                        exec_frames,
                                        ctx.frame_index,
                                        mm,
                                        &.{ la, lb },
                                        .eq,
                                        .{ .compare = c != 0 },
                                    )) {
                                        .pushed => continue :frame_loop,
                                        .value => |ret| {
                                            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                                            break :blk isTruthy(ret);
                                        },
                                        .compare => |cmp| break :blk cmp,
                                    }
                                }
                            }
                            break :blk false;
                        };
                        const invert = (c != 0);
                        if (result != invert) ctx.pc += 1;
                    },
                    .lt => {
                        const la = ctx.regs[a];
                        const lb = ctx.regs[b];
                        // Fast path: inline numeric and string comparisons to
                        // avoid bytecodeComparisonHasFastPath + cmpLt overhead.
                        const result: bool = blk: {
                            if (la == .Int and lb == .Int) break :blk la.Int < lb.Int;
                            if (la == .Num and lb == .Num) break :blk la.Num < lb.Num;
                            if (la == .Int and lb == .Num) break :blk intLtNum(la.Int, lb.Num);
                            if (la == .Num and lb == .Int) break :blk numLtInt(la.Num, lb.Int);
                            if (la == .String and lb == .String) break :blk std.mem.order(u8, la.String.bytes(), lb.String.bytes()) == .lt;
                            // Slow path: resolve ONCE, push or call — no re-lookup.
                            switch (try self.slowCmp(exec_frames, ctx.frame_index, ctx.pc, la, lb, .lt, c != 0)) {
                                .pushed => continue :frame_loop,
                                .value => |v| break :blk v,
                            }
                        };
                        const invert = (c != 0);
                        if (result != invert) ctx.pc += 1;
                    },
                    .le => {
                        const la = ctx.regs[a];
                        const lb = ctx.regs[b];
                        const result: bool = blk: {
                            if (la == .Int and lb == .Int) break :blk la.Int <= lb.Int;
                            if (la == .Num and lb == .Num) break :blk la.Num <= lb.Num;
                            if (la == .Int and lb == .Num) break :blk intLeNum(la.Int, lb.Num);
                            if (la == .Num and lb == .Int) break :blk numLeInt(la.Num, lb.Int);
                            if (la == .String and lb == .String) {
                                const ord = std.mem.order(u8, la.String.bytes(), lb.String.bytes());
                                break :blk ord == .lt or ord == .eq;
                            }
                            // Slow path: resolve ONCE, push or call — no re-lookup.
                            switch (try self.slowCmp(exec_frames, ctx.frame_index, ctx.pc, la, lb, .le, c != 0)) {
                                .pushed => continue :frame_loop,
                                .value => |v| break :blk v,
                            }
                        };
                        const invert = (c != 0);
                        if (result != invert) ctx.pc += 1;
                    },
                    // P15.38d: Immediate comparison opcodes (PUC EQI/LTI/LEI/GTI/GEI/EQK).
                    // These compare R[A] against a signed immediate (sB) or constant
                    // pool entry (K[B]), eliminating a preceding LOADI/LOADK.
                    // sB is decoded the same way as sC: actual = stored - 127.
                    .eqi => {
                        // PUC OP_EQI: if ((R[A] == sB) ~= (C&1) then ctx.pc++
                        // C bit 0 = invert, C bit 1 = isfloat (immediate
                        // originated from a float literal, e.g. 5.0).
                        const la = ctx.regs[a];
                        const im: i64 = @as(i64, b) - 127; // sB2int (same encoding as sC)
                        const result: bool = switch (la) {
                            .Int => |v| v == im,
                            .Num => |v| v == @as(f64, @floatFromInt(im)),
                            else => false,
                        };
                        const invert = (c & 1) != 0;
                        if (result != invert) ctx.pc += 1;
                    },
                    .eqk => {
                        // PUC OP_EQK: if ((R[A] == K[B]) ~= (C&1)) then ctx.pc++
                        // Raw equality (no __eq metamethod) — basic types don't use __eq.
                        const la = ctx.regs[a];
                        const rb = ctx.cur_proto.resolved_values[b];
                        const result = valuesEqual(la, rb);
                        const invert = (c & 1) != 0;
                        if (result != invert) ctx.pc += 1;
                    },
                    .lti => {
                        // PUC OP_LTI: if ((R[A] < sB) ~= (C&1)) then ctx.pc++
                        // C bit 0 = invert, C bit 1 = isfloat (sB originated
                        // from a float literal like 5.0; metamethod must
                        // receive a float, not an integer).
                        const la = ctx.regs[a];
                        const im: i64 = @as(i64, b) - 127;
                        const isfloat = (c & 2) != 0;
                        const result: bool = blk: {
                            if (la == .Int) break :blk la.Int < im;
                            if (la == .Num) break :blk la.Num < @as(f64, @floatFromInt(im));
                            // Slow path: resolve ONCE, push or call — no re-lookup.
                            const rb_val: Value = if (isfloat)
                                .{ .Num = @as(f64, @floatFromInt(im)) }
                            else
                                .{ .Int = im };
                            switch (try self.slowCmp(exec_frames, ctx.frame_index, ctx.pc, la, rb_val, .lt, (c & 1) != 0)) {
                                .pushed => continue :frame_loop,
                                .value => |v| break :blk v,
                            }
                        };
                        const invert = (c & 1) != 0;
                        if (result != invert) ctx.pc += 1;
                    },
                    .lei => {
                        // PUC OP_LEI: if ((R[A] <= sB) ~= (C&1)) then ctx.pc++
                        // C bit 0 = invert, C bit 1 = isfloat.
                        const la = ctx.regs[a];
                        const im: i64 = @as(i64, b) - 127;
                        const isfloat = (c & 2) != 0;
                        const result: bool = blk: {
                            if (la == .Int) break :blk la.Int <= im;
                            if (la == .Num) break :blk la.Num <= @as(f64, @floatFromInt(im));
                            // Slow path: resolve ONCE, push or call — no re-lookup.
                            const rb_val: Value = if (isfloat)
                                .{ .Num = @as(f64, @floatFromInt(im)) }
                            else
                                .{ .Int = im };
                            switch (try self.slowCmp(exec_frames, ctx.frame_index, ctx.pc, la, rb_val, .le, (c & 1) != 0)) {
                                .pushed => continue :frame_loop,
                                .value => |v| break :blk v,
                            }
                        };
                        const invert = (c & 1) != 0;
                        if (result != invert) ctx.pc += 1;
                    },
                    .gti => {
                        // PUC OP_GTI: if ((R[A] > sB) ~= (C&1)) then ctx.pc++
                        // C bit 0 = invert, C bit 1 = isfloat.
                        const la = ctx.regs[a];
                        const im: i64 = @as(i64, b) - 127;
                        const isfloat = (c & 2) != 0;
                        const result: bool = blk: {
                            if (la == .Int) break :blk la.Int > im;
                            if (la == .Num) break :blk la.Num > @as(f64, @floatFromInt(im));
                            // Slow path: GTI uses __lt with swapped operands: (im < la).
                            // Resolve ONCE, push or call — no re-lookup.
                            const rb_val: Value = if (isfloat)
                                .{ .Num = @as(f64, @floatFromInt(im)) }
                            else
                                .{ .Int = im };
                            switch (try self.slowCmp(exec_frames, ctx.frame_index, ctx.pc, rb_val, la, .lt, (c & 1) != 0)) {
                                .pushed => continue :frame_loop,
                                .value => |v| break :blk v,
                            }
                        };
                        const invert = (c & 1) != 0;
                        if (result != invert) ctx.pc += 1;
                    },
                    .gei => {
                        // PUC OP_GEI: if ((R[A] >= sB) ~= (C&1)) then ctx.pc++
                        // C bit 0 = invert, C bit 1 = isfloat.
                        const la = ctx.regs[a];
                        const im: i64 = @as(i64, b) - 127;
                        const isfloat = (c & 2) != 0;
                        const result: bool = blk: {
                            if (la == .Int) break :blk la.Int >= im;
                            if (la == .Num) break :blk la.Num >= @as(f64, @floatFromInt(im));
                            // Slow path: GEI uses __le with swapped operands: (im <= la).
                            // Resolve ONCE, push or call — no re-lookup.
                            const rb_val: Value = if (isfloat)
                                .{ .Num = @as(f64, @floatFromInt(im)) }
                            else
                                .{ .Int = im };
                            switch (try self.slowCmp(exec_frames, ctx.frame_index, ctx.pc, rb_val, la, .le, (c & 1) != 0)) {
                                .pushed => continue :frame_loop,
                                .value => |v| break :blk v,
                            }
                        };
                        const invert = (c & 1) != 0;
                        if (result != invert) ctx.pc += 1;
                    },

                    // --- Test / testset ---
                    .test_ => {
                        const is_truthy = isTruthy(ctx.regs[a]);
                        const skip_if_falsy = (c != 0);
                        if (!is_truthy == skip_if_falsy) ctx.pc += 1;
                    },
                    .testset => {
                        const is_truthy = isTruthy(ctx.regs[b]);
                        const skip_if_falsy = (c != 0);
                        if (!is_truthy == skip_if_falsy) {
                            ctx.pc += 1;
                        } else {
                            ctx.regs[a] = ctx.regs[b];
                        }
                    },

                    // --- Control flow ---
                    .jmp => {
                        ctx.pc = @intCast(@as(i64, @intCast(ctx.pc)) + inst.jumpOffset() + 1);
                        if (check_sigint and signal_int_pending.load(.acquire)) {
                            signal_int_pending.store(false, .release);
                            return self.fail("interrupted!", .{});
                        }
                        continue;
                    },

                    // --- Calls / returns ---
                    .call => {
                        // ── Inline fast path: Lua closure, no hooks, no
                        // coroutine resume. Avoids calling the 200-line opCall
                        // function and DispatchResult enum switch for the
                        // overwhelmingly common case. Mirrors PUC's OP_CALL
                        // which is handled directly in luaV_execute's switch.
                        const callee = ctx.regs[a];
                        // P15.51l: hooks_active/resumed_direct_yield are rare
                        // fields, read directly from the CallFrame.
                        if (callee == .Closure and !self.hooks_active_cached and !exec_frames.getPtr(ctx.frame_index).isHookYield()) {
                            const cl = callee.Closure;
                            if (cl.proto) |proto| {
                                if (self.stats.enabled) self.stats.calls_fast += 1; // P16.0b
                                const nresults: i32 = if (c == 0) -1 else @intCast(c - 1);
                                const nargs: usize = if (b == 0) exec_frames.getPtr(ctx.frame_index).reg_top - a - 1 else b - 1;

                                // Pre-grow shared stack for child frame (PUC
                                // luaD_precall stack check). Usually a no-op
                                // because EXTRA_MARGIN covers typical calls.
                                const child_frame_cap: u32 = @intCast(proto.maxstacksize + EXTRA_MARGIN);
                                const child_nextra: usize = if (proto.flags.is_vararg and nargs > proto.numparams)
                                    nargs - proto.numparams
                                else
                                    0;
                                try self.ensureBcStackCap(self.bc_stack_top + child_frame_cap + child_nextra);
                                ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];

                                // P16.2: no pending-call slot for a plain
                                // Lua→Lua call — the P15.51c direct contract
                                // applies (same as opCall's plain-Lua branch:
                                // dst derived from the child's originalFuncSlot(),
                                // nresults decoded from the child's
                                // callstatus; applyBytecodeResultsDirect
                                // advances pc). The pending slot served no
                                // purpose for plain .results completions —
                                // protection/tail_return/append_nil are not
                                // this call's cases — and cost an
                                // allocPendingCall + payload store at setup,
                                // plus the pending lookup/union switch/
                                // clearPendingCall on every return
                                // (setPendingCall was 9.3% of lua_calls).
                                // Staged-ABI activation (PUC OP_CALL: func at
                                // R[A], nargs args at R[A+1..] — already in
                                // place, zero-copy, no staging needed).
                                try self.pushStagedBytecodeExecFrame(
                                    ctx.exec_frames,
                                    proto,
                                    ctx.base + a,
                                    nargs,
                                    nresults,
                                );
                                // Defer block syncs parent frame state (pc,
                                // regs, etc.) before the frame_loop starts
                                // executing the child frame.
                                continue :frame_loop;
                            }
                        }

                        // ── Slow path: Builtin callee, __call metamethod,
                        // hooks active, or coroutine resume ──
                        switch (try self.opCall(&ctx)) {
                            .continue_dispatch => {},
                            .continue_no_advance => continue,
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => {
                                return error.RuntimeError;
                            },
                        }
                    },
                    .tailcall => {
                        switch (try self.opTailcall(&ctx)) {
                            .continue_dispatch => {},
                            // P16.10 T8: Tail call reuses the frame (pc=0) —
                            // refresh sigint_trap like a backward jump.
                            .continue_no_advance => {
                                if (check_sigint and signal_int_pending.load(.acquire)) {
                                    signal_int_pending.store(false, .release);
                                    return self.fail("interrupted!", .{});
                                }
                                continue;
                            },
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => return error.RuntimeError,
                        }
                    },
                    .return_ => {
                        switch (try self.opReturn(&ctx)) {
                            .continue_dispatch => {},
                            .continue_no_advance => continue,
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => return error.RuntimeError,
                        }
                    },
                    .return0 => {
                        switch (try self.opReturn0(&ctx)) {
                            .continue_dispatch => {},
                            .continue_no_advance => continue,
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => return error.RuntimeError,
                        }
                    },
                    .return1 => {
                        switch (try self.opReturn1(&ctx)) {
                            .continue_dispatch => {},
                            .continue_no_advance => continue,
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => return error.RuntimeError,
                        }
                    },

                    // --- For-loops ---
                    //
                    // PUC Lua has two numeric for-loop modes:
                    //  1. Integer loop: both init and step are integers.
                    //     Uses a count-based approach to avoid overflow.
                    //  2. Float loop: fallback when not all values are integers.
                    //     Includes string-to-number coercion (tonumber).
                    //
                    // Our register layout (codegen_bc):
                    //   R[A]   = init   → (after FORPREP) limit or count
                    //   R[A+1] = limit  → (after FORPREP) step
                    //   R[A+2] = step   → (after FORPREP) control variable (idx)
                    //   R[A+3] = loop variable (user-visible, set by FORPREP/FORLOOP)
                    //
                    .forprep => {
                        switch (try self.opForprep(&ctx)) {
                            .continue_dispatch => {},
                            .continue_no_advance => continue,
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => return error.RuntimeError,
                        }
                    },
                    .forloop => {
                        // After FORPREP, R[A+1] tells us the mode:
                        //   Int  → integer loop (R[A]=count, R[A+1]=step, R[A+2]=idx)
                        //   Num  → float loop   (R[A]=limit, R[A+1]=step, R[A+2]=idx)
                        if (ctx.regs[a + 1] == .Int) {
                            // ── Integer loop ──
                            const count = @as(u64, @bitCast(ctx.regs[a].Int));
                            if (count > 0) {
                                const step_i = ctx.regs[a + 1].Int;
                                const idx = ctx.regs[a + 2].Int;
                                ctx.regs[a] = .{ .Int = @bitCast(count -% 1) };
                                const new_idx = idx +% step_i;
                                ctx.regs[a + 2] = .{ .Int = new_idx };
                                ctx.regs[a + 3] = .{ .Int = new_idx };
                                const off_bits: u16 = @as(u16, b) | (@as(u16, c) << 8);
                                const off: i16 = @bitCast(off_bits);
                                ctx.pc = @intCast(@as(i64, @intCast(ctx.pc)) + @as(i64, off) + 1);
                                if (check_sigint and signal_int_pending.load(.acquire)) {
                                    signal_int_pending.store(false, .release);
                                    return self.fail("interrupted!", .{});
                                }
                                continue;
                            }
                        } else {
                            // ── Float loop ──
                            const limit_f = ctx.regs[a].Num;
                            const step_f = ctx.regs[a + 1].Num;
                            const idx = ctx.regs[a + 2].Num;
                            const next_idx = idx + step_f;
                            const continues = if (step_f > 0) next_idx <= limit_f else next_idx >= limit_f;
                            if (continues) {
                                ctx.regs[a + 2] = .{ .Num = next_idx };
                                ctx.regs[a + 3] = .{ .Num = next_idx };
                                const off_bits: u16 = @as(u16, b) | (@as(u16, c) << 8);
                                const off: i16 = @bitCast(off_bits);
                                ctx.pc = @intCast(@as(i64, @intCast(ctx.pc)) + @as(i64, off) + 1);
                                if (check_sigint and signal_int_pending.load(.acquire)) {
                                    signal_int_pending.store(false, .release);
                                    return self.fail("interrupted!", .{});
                                }
                                continue;
                            }
                        }
                    },

                    .tforcall => {
                        switch (try self.opTforcall(&ctx)) {
                            .continue_dispatch => {},
                            .continue_no_advance => continue,
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => return error.RuntimeError,
                        }
                    },
                    .tforloop => {
                        // A=ctx.base, offset in B:C. If R[ctx.base+2] != nil, loop continues.
                        const ctrl = ctx.regs[a + 2];
                        if (ctrl != .Nil) {
                            ctx.regs[a] = ctrl;
                            const off_bits: u16 = @as(u16, b) | (@as(u16, c) << 8);
                            const off: i16 = @bitCast(off_bits);
                            ctx.pc = @intCast(@as(i64, @intCast(ctx.pc)) + @as(i64, off) + 1);
                            if (check_sigint and signal_int_pending.load(.acquire)) {
                                signal_int_pending.store(false, .release);
                                return self.fail("interrupted!", .{});
                            }
                            continue;
                        }
                    },
                    .tforprep => {
                        // A=ctx.base, offset in B:C. Jump forward to after loop.
                        const off_bits: u16 = @as(u16, b) | (@as(u16, c) << 8);
                        const off: i16 = @bitCast(off_bits);
                        ctx.pc = @intCast(@as(i64, @intCast(ctx.pc)) + @as(i64, off) + 1);
                        if (check_sigint and signal_int_pending.load(.acquire)) {
                            signal_int_pending.store(false, .release);
                            return self.fail("interrupted!", .{});
                        }
                        continue;
                    },

                    // --- Table constructor ---
                    .setlist => {
                        switch (try self.opSetlist(&ctx)) {
                            .continue_dispatch => {},
                            .continue_no_advance => continue,
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => return error.RuntimeError,
                        }
                    },

                    // --- Closures ---
                    .closure => {
                        switch (try self.opClosure(&ctx)) {
                            .continue_dispatch => {},
                            .continue_no_advance => continue,
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => return error.RuntimeError,
                        }
                        // PUC: checkGC(L, ra + 1) after pushclosure.
                        try self.condGcFromDispatch(&ctx);
                    },

                    // --- Upvalue / scope management ---
                    .close => {
                        // Close all to-be-closed variables >= R[A], then close
                        // all upvalues >= R[A]. TBC variables get their __close
                        // metamethod called; upvalue cells just get unlinked.
                        //
                        // PUC Lua: luaF_close(L, level, status, yy) — closes
                        // all TBC upvalues and regular upvalues >= level.
                        // We process TBC in reverse declaration order (LIFO).

                        switch (try self.beginBytecodeClose(
                            exec_frames,
                            boundary_depth,
                            ctx.frame_index,
                            a,
                            null,
                            false,
                            .advance_instruction,
                        )) {
                            .resume_dispatch => {
                                // continueBytecodeClose no longer writes
                                // parent.u.lua.pc (PUC-faithful: dispatch loop owns
                                // pc). Increment ctx.pc here; the defer will
                                // persist it to the frame.
                                ctx.pc += 1;
                                continue :frame_loop;
                            },
                            .final => |final| return final,
                            .propagate_error => return error.RuntimeError,
                        }
                    },
                    .tbc => {
                        const value = ctx.regs[a];
                        // Lua permits nil/false as inert <close> sentinels. Any
                        // other value must already provide __close when the
                        // declaration becomes active; validating only at scope
                        // exit would incorrectly execute the function body.
                        if (value != .Nil and !(value == .Bool and !value.Bool)) {
                            if (self.getTmByObj(value, .close) == null) {
                                const local_name = bytecodeLocalNameAt(ctx.cur_proto, a, ctx.pc) orelse "?";
                                exec_frames.getPtr(ctx.frame_index).u.lua.pc = ctx.pc;
                                return self.fail("variable '{s}' got a non-closable value", .{local_name});
                            }
                            self.bc_tbc_regs.append(self.alloc, a) catch return error.OutOfMemory;
                        }
                    },

                    // --- Varargs ---
                    .vararg => {
                        switch (try self.opVararg(&ctx)) {
                            .continue_dispatch => {},
                            .continue_no_advance => continue,
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => return error.RuntimeError,
                        }
                    },
                    .varargprep => {
                        // First instruction of a vararg function.
                        // If the function has a named vararg table (vararg_table_reg),
                        // create the table and store it in the designated register.
                        if (ctx.cur_proto.vararg_table_reg != bc.Proto.no_vararg_reg) {
                            const va_reg = ctx.cur_proto.vararg_table_reg;
                            try self.testcConsumeAllocCount(); // Table struct
                            const t = try self.allocTableEphemeral();
                            // PUC model (VATAB): extra args at base+numparams
                            // P15.51l: nextraargs is a rare field, read from CallFrame.
                            const fr_vp = exec_frames.getPtr(ctx.frame_index);
                            const nextra_vp: usize = fr_vp.u.lua.nextraargs;
                            const va_slice: []Value = if (nextra_vp != 0) blk: {
                                const np = ctx.cur_proto.numparams;
                                const va_start = ctx.base + np;
                                break :blk self.bc_stack[va_start .. va_start + nextra_vp];
                            } else &.{};
                            try self.tableResizeArray(t, @intCast(va_slice.len));
                            for (va_slice, 0..) |v, i| {
                                t.array[i] = v;
                            }
                            try self.setIndexValue(.{ .Table = t }, .{ .String = try self.internStr("n") }, .{ .Int = @intCast(va_slice.len) });
                            // Allocations above (allocTableEphemeral, tableResizeArray,
                            // setIndexValue, internStr) may trigger GC which
                            // reallocates bc_stack. Refresh ctx.regs before writing
                            // the table to the register.
                            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                            ctx.regs[va_reg] = .{ .Table = t };
                            // P15.51l: reg_top is a rare field, write to CallFrame.
                            fr_vp.reg_top = @max(fr_vp.reg_top, va_reg + 1);
                        }
                    },

                    // --- Error ---
                    .errdefined => {
                        if (ctx.regs[a] != .Nil) {
                            var constant_index: u32 = if (b > 0) @as(u32, b - 1) else 0;
                            if (b == 0) {
                                if (ctx.pc + 1 >= ctx.cur_proto.code.len or ctx.cur_proto.code[ctx.pc + 1].op != @intFromEnum(bc.Op.extraarg)) {
                                    exec_frames.getPtr(ctx.frame_index).u.lua.pc = ctx.pc;
                                    return self.fail("malformed ERRDEFINED instruction", .{});
                                }
                                constant_index = ctx.cur_proto.code[ctx.pc + 1].extraArg();
                                ctx.pc += 1;
                            }
                            const name = if (constant_index < ctx.cur_proto.k.len)
                                ctx.cur_proto.k[constant_index]
                            else
                                bc.Constant.nil;
                            const name_str = if (name == .str) name.str.bytes() else "<global>";
                            exec_frames.getPtr(ctx.frame_index).u.lua.pc = ctx.pc;
                            return self.fail("global '{s}' already defined", .{name_str});
                        }
                    },
                    .errnnil => {
                        if (ctx.regs[a] == .Nil) {
                            const name = if (b > 0) ctx.cur_proto.k[b - 1] else bc.Constant.nil;
                            const name_str = if (name == .str) name.str.bytes() else "<global>";
                            exec_frames.getPtr(ctx.frame_index).u.lua.pc = ctx.pc;
                            return self.fail("attempt to use a nil value (global '{s}')", .{name_str});
                        }
                    },

                    // --- Extended argument ---
                    .extraarg => {
                        // Should be consumed by the preceding instruction.
                    },
                }

                ctx.pc += 1;
            }

            // Should not happen (codegen ensures a terminating return), but
            // preserve the old empty-return fallback for malformed Protos.
            const ret = try self.alloc.alloc(Value, 0);
            if (try self.completeBytecodeExecFrame(exec_frames, boundary_depth, ret)) |final| return final;
        }

        unreachable;
    }

    // ─────────────────────────────────────────────────────────────────────
    // P15.42 extracted opcode handlers.
    //
    // Each handler reads `inst` from `ctx.cur_proto.code[ctx.pc]`, mutates
    // ctx fields directly, and returns a DispatchResult. The dispatcher
    // switch unwraps the result to drive the inner loop. Handlers must
    // re-derive ctx.regs/ctx.boxed after any call that may realloc bc_stack.
    // ─────────────────────────────────────────────────────────────────────

    /// OP_RETURN: return `b-1` values (or all from a..reg_top if b==0) from
    /// the current frame. Runs pending __close metamethods via
    /// beginBytecodeClose before completing the frame.
    fn opReturn(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const inst = ctx.cur_proto.code[ctx.pc];
        const a: usize = inst.a;
        const b: u8 = inst.b;

        // Preserve return values before running closers; __close can execute
        // Lua and grow the shared bytecode stack.
        // P15.51l: reg_top is a rare field, read from CallFrame.
        const fr_ret = ctx.exec_frames.getPtr(ctx.frame_index);
        const nvals: usize = if (b == 0) fr_ret.reg_top - a else b - 1;
        const ret = try self.alloc.dupe(Value, ctx.regs[a .. a + nvals]);
        var ret_owned = true;
        errdefer if (ret_owned) self.alloc.free(ret);
        // beginBytecodeClose takes ownership of `ret` (stored in
        // close_state.post.return_frame). The errdefer must not free it
        // if beginBytecodeClose accepted the slice — even on error.Yield,
        // the close continuation retains the slice for resume.
        ret_owned = false;

        // Sync pc to the heap CallFrame so GC (which may run
        // inside __close finalizers via collectgarbage()) sees the correct
        // live_reg_top[pc] for the parent frame. Without this, the parent
        // frame's pc is stale and live_reg_top[pc] may not include
        // to-be-closed variables, causing GC to clear them.
        // P15.51l: reg_top is already on the CallFrame (rare field).
        {
            const fr = ctx.exec_frames.getPtr(ctx.frame_index);
            fr.u.lua.pc = ctx.pc;
        }

        const close_outcome = try self.beginBytecodeClose(
            ctx.exec_frames,
            ctx.boundary_depth,
            ctx.frame_index,
            0,
            null,
            true,
            .{ .return_frame = ret },
        );
        return switch (close_outcome) {
            .resume_dispatch => .continue_frame_loop,
            .final => |final| .{ .return_results = final },
            .propagate_error => .propagate_error,
        };
    }

    /// OP_SETLIST: R[A][C+i] := R[A+i] for 1<=i<=B. When C==255, the actual
    /// base index is in the following EXTRAARG instruction (consumed here).
    /// Returns `.continue_dispatch` so the dispatcher advances past SETLIST.
    fn opSetlist(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const inst = ctx.cur_proto.code[ctx.pc];
        const a: usize = inst.a;
        const b: u8 = inst.b;
        const c: u8 = inst.c;

        const table_val = ctx.regs[a];
        // P15.51l: reg_top is a rare field, read from CallFrame.
        const count: usize = if (b == 0) ctx.exec_frames.getPtr(ctx.frame_index).reg_top - a - 1 else b;
        const base_idx: u32 = if (c == 255) blk: {
            if (ctx.pc + 1 >= ctx.cur_proto.code.len or
                @as(bc.Op, @enumFromInt(ctx.cur_proto.code[ctx.pc + 1].op)) != .extraarg)
            {
                return self.fail("SETLIST missing EXTRAARG", .{});
            }
            ctx.pc += 1;
            break :blk ctx.cur_proto.code[ctx.pc].extraArg();
        } else c;

        if (table_val == .Table) {
            const tbl = table_val.Table;
            // Fast path: table without metatable — preallocate array part
            // and write directly, mirroring PUC's SETLIST (luaH_resizearray
            // + obj2arr). Skips the per-element tableGetRawValue probe in
            // setIndexValueDepth and the per-element rawSet rehash path.
            if (tbl.metatable == null) {
                const start = base_idx;
                const end = base_idx + @as(u32, @intCast(count));
                // Extend array part if needed (PUC: luaH_resizearray).
                if (end > tbl.asize) {
                    try self.tableResizeArray(tbl, end);
                }
                for (0..count) |i| {
                    const idx = start + i;
                    // Value-barrier BEFORE store (OOM safety: if barrier
                    // fails, the store must not happen).
                    try self.gcTableBarrierBackValue(tbl, ctx.regs[a + 1 + i]);
                    tbl.array[idx] = ctx.regs[a + 1 + i];
                }
                tbl.flags &= ~TableFlags.MASK;
            } else {
                for (0..count) |i| {
                    try self.setIndexValue(table_val, .{ .Int = @intCast(base_idx + i + 1) }, ctx.regs[a + 1 + i]);
                }
            }
        }
        return .continue_dispatch;
    }

    /// OP_RETURN0: return zero values from the current frame.
    /// P15.35 fast path: when no TBC closers and no debug hooks, skip
    /// beginBytecodeClose and use a zero-length slice into bc_return_scratch
    /// (pointer-identity detected, never freed). This eliminates the
    /// alloc(Value, 0)/free pair on every no-value return.
    fn opReturn0(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const has_pending_tbc = self.bc_tbc_regs.items.len >
            ctx.exec_frames.topConstPtr().tbc_mark; // P16.20 T6: current == top
        // P15.51l: hooks_active is read from self.hooks_active_cached.
        if (!has_pending_tbc and !self.hooks_active_cached) {
            // P16.2d: inline return fast arm (same conditions as opReturn1).
            // opReturn0 returns 0 values, so the fast arm handles nresults==0
            // (no stores needed) and nresults<0 (multret: set reg_top=dst, no
            // stores). nresults>=1 would require nil-padding — fall back.
            // See opReturn1 for the full safety proof and condition rationale.
            {
                const child = ctx.exec_frames.topConstPtr();
                if (!child.u.lua.hasOpenUpvalues() and
                    !child.isDebugHook() and
                    ctx.frame_index > 0 and
                    ctx.frame_index != ctx.boundary_depth)
                {
                    const parent_c = ctx.exec_frames.parentPtrOfTopConst();
                    if (parent_c.isLua() and
                        parent_c.pending_call_index == INVALID_PENDING and
                        !parent_c.u.lua.hasSimpleResult())
                    {
                        const nresults = decodeNresults(child.callstatus);
                        if (nresults == 0 or nresults < 0) {
                            const dst = child.originalFuncSlot() - parent_c.frameBase();
                            // Pop child frame — mirror popBytecodeExecFrame
                            // (same skip rationale as opReturn1). T7: stable
                            // parent reused across the shrink.
                            const child_m = @constCast(child);
                            child_m.callstatus = 0;
                            self.bc_stack_top = parent_c.frameBase() + parent_c.u.lua.frame_cap;
                            ctx.exec_frames.shrinkTo(ctx.frame_index);
                            // No value to store (opReturn0 returns 0 values).
                            const parent_m = @constCast(parent_c);
                            if (nresults < 0) {
                                // Multret: 0 values → reg_top = dst.
                                parent_m.reg_top = @intCast(dst);
                            }
                            parent_m.u.lua.pc += 1;
                            return .continue_frame_loop;
                        }
                    }
                    // P16.8 Task 1: simple_result fast arm for opReturn0.
                    // 0 values returned: value mode → nil; compare mode → false.
                    if (parent_c.isLua() and
                        parent_c.pending_call_index == INVALID_PENDING and
                        parent_c.u.lua.hasSimpleResult())
                    {
                        const nresults = decodeNresults(child.callstatus);
                        if (nresults < 0) {
                            // Pop child frame — same as ordinary fast arm
                            // (T7: stable parent reused across the shrink).
                            const child_m = @constCast(child);
                            child_m.callstatus = 0;
                            self.bc_stack_top = parent_c.frameBase() + parent_c.u.lua.frame_cap;
                            ctx.exec_frames.shrinkTo(ctx.frame_index);
                            const parent_m = @constCast(parent_c);
                            if (parent_m.u.lua.simpleResultIsCompare()) {
                                // Compare mode: 0 values → false.
                                const invert = parent_m.u.lua.simpleResultInvert();
                                parent_m.u.lua.pc += 1;
                                if (false != invert) parent_m.u.lua.pc += 1;
                            } else {
                                // Value mode: 0 values → nil.
                                const sr_dst = parent_m.u.lua.simple_result_dst;
                                self.bc_stack[parent_c.frameBase() + sr_dst] = .Nil;
                                parent_m.reg_top = @intCast(sr_dst + 1);
                                parent_m.u.lua.pc += 1;
                            }
                            parent_m.u.lua.clearSimpleResult();
                            return .continue_frame_loop;
                        }
                    }
                }
            }
            // Fallback: scratch + completeBytecodeExecFrame.
            const empty: []Value = self.bc_return_scratch[0..0];
            if (try self.completeBytecodeExecFrame(
                ctx.exec_frames,
                ctx.boundary_depth,
                empty,
            )) |final| return .{ .return_results = final };
            return .continue_frame_loop;
        }
        const ret = try self.alloc.alloc(Value, 0);
        var ret_owned = true;
        errdefer if (ret_owned) self.alloc.free(ret);
        // beginBytecodeClose takes ownership of `ret` (stored in
        // close_state.post.return_frame). The errdefer must not free it
        // if beginBytecodeClose accepted the slice — even on error.Yield,
        // the close continuation retains the slice for resume.
        ret_owned = false;
        // Sync pc so GC (which may run inside __close
        // finalizers via collectgarbage()) sees the correct live_reg_top[pc].
        // P15.51l: reg_top is already on the CallFrame (rare field).
        {
            const fr = ctx.exec_frames.getPtr(ctx.frame_index);
            fr.u.lua.pc = ctx.pc;
        }
        return switch (try self.beginBytecodeClose(
            ctx.exec_frames,
            ctx.boundary_depth,
            ctx.frame_index,
            0,
            null,
            true,
            .{ .return_frame = ret },
        )) {
            .resume_dispatch => .continue_frame_loop,
            .final => |final| .{ .return_results = final },
            .propagate_error => .propagate_error,
        };
    }

    /// OP_RETURN1: return a single value (R[A]) from the current frame.
    /// P15.35 fast path: stash the single return value in bc_return_scratch
    /// (stable across frame pop) and go straight to completeBytecodeExecFrame.
    /// Eliminates the alloc(Value, 1)/free pair on every single-value return
    /// — the hottest return path (e.g. `return s + 1`).
    fn opReturn1(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const inst = ctx.cur_proto.code[ctx.pc];
        const a: usize = inst.a;

        // P16.20 T6/T7: during a return the executing frame IS the top of
        // exec_frames (calls push on top; the dispatch loop sets
        // frame_index = len()-1 at entry). topPtr() = one conditional,
        // no len()+index arithmetic.
        const has_pending_tbc = self.bc_tbc_regs.items.len >
            ctx.exec_frames.topConstPtr().tbc_mark;
        // P15.51l: hooks_active is read from self.hooks_active_cached.
        if (!has_pending_tbc and !self.hooks_active_cached) {
            // P16.2d: inline return fast arm. When the return is a simple
            // Lua-to-Lua call completion (no open upvalues, no TBC closers,
            // no hooks, no pending call, not at an external boundary, parent
            // is Lua), inline the pop + single-copy directly, bypassing
            // completeBytecodeExecFrame + applyBytecodeResultsDirect. This
            // eliminates:
            //   (1) the bc_return_scratch intermediate copy,
            //   (2) the completeBytecodeExecFrame call + its multiple
            //       getConstPtr/getPtr traversals,
            //   (3) the applyBytecodeResultsDirect call + its slice
            //       re-derivation + bcGrowFrame guard,
            //   (4) the returnSliceIsOwned check + free pair.
            //
            // Safety proof (single-copy cannot clobber source): the RHS
            // (ctx.regs[a]) is read into a local BEFORE the write. The write
            // target (self.bc_stack[parent.frameBase() + dst]) is in the parent's
            // register window, which may overlap the child's window (shared
            // stack). But since we read the source value first and perform a
            // single Value assignment, there is no aliasing hazard.
            // Multi-value forward-copy COULD clobber (if src and dst overlap),
            // which is why the multret fast arm is restricted to
            // exactly-1-value opReturn1.
            {
                const child = ctx.exec_frames.topConstPtr();
                // Condition (a): no open upvalues to close.
                // Condition (b): !has_pending_tbc (checked above).
                // Condition (f): no hooks — !hooks_active_cached (above) +
                //   !child.isDebugHook() (popBytecodeExecFrame clears
                //   in_debug_hook for debug-hook frames; skip that path).
                if (!child.u.lua.hasOpenUpvalues() and
                    !child.isDebugHook() and
                    ctx.frame_index > 0 and // (c): parent exists
                    ctx.frame_index != ctx.boundary_depth) // (d): not boundary
                {
                    const parent_idx = ctx.frame_index - 1;
                    const parent_c = ctx.exec_frames.getConstPtr(parent_idx);
                    // Condition (c): parent is a Lua frame.
                    // Condition (e): no pending call.
                    // P16.8 Task 1: also exclude simple_result (handled below).
                    if (parent_c.isLua() and
                        parent_c.pending_call_index == INVALID_PENDING and
                        !parent_c.u.lua.hasSimpleResult())
                    {
                        const nresults = decodeNresults(child.callstatus);
                        // Condition (g): fast arm handles nresults==1 (fixed
                        // 1 result) and nresults<0 (multret with exactly 1
                        // value). Other nresults fall back.
                        if (nresults == 1 or nresults < 0) {
                            // P16.20 T7: the parent pointer obtained here is
                            // PROVEN STABLE across the pop sequence below —
                            // inline slots never move, and shrinkTo only
                            // decrements counts (heap memory is never
                            // reallocated by a shrink), so re-fetching the
                            // parent after shrinkTo (the old 4th lookup) is
                            // dead work.
                            const parent_m = @constCast(parent_c);
                            // Read source BEFORE pop (child reg still valid).
                            const src_val = ctx.regs[a];
                            const dst = child.originalFuncSlot() - parent_c.frameBase();
                            // Pop child frame — mirror popBytecodeExecFrame
                            // exactly, skipping the parts guarded by fast-arm
                            // conditions. The child is the top slot: mutating
                            // through @constCast(child) is the same object
                            // getPtr(ctx.frame_index) returned.
                            const child_m = @constCast(child);
                            child_m.callstatus = 0;
                            self.bc_stack_top = parent_c.frameBase() + parent_c.u.lua.frame_cap;
                            ctx.exec_frames.shrinkTo(ctx.frame_index);
                            // Single-copy: write return value directly into
                            // parent's register window. dst < frame_cap is
                            // guaranteed because the original func slot is within the
                            // parent's window (it's where the function was).
                            self.bc_stack[parent_c.frameBase() + dst] = src_val;
                            if (nresults < 0) {
                                parent_m.reg_top = @intCast(dst + 1);
                            }
                            parent_m.u.lua.pc += 1;
                            return .continue_frame_loop;
                        }
                    }
                    // P16.8 Task 1: simple_result fast arm. When the return
                    // is from a metamethod child frame with an inline
                    // simple_result completion, inline the pop + single-copy
                    // (value mode) or truthiness check (compare mode) directly,
                    // bypassing completeBytecodeExecFrame entirely. Same
                    // conditions as the ordinary fast arm except
                    // hasSimpleResult() replaces the no-simple_result check.
                    // simple_result always uses MULTRET (nresults < 0).
                    if (parent_c.isLua() and
                        parent_c.pending_call_index == INVALID_PENDING and
                        parent_c.u.lua.hasSimpleResult())
                    {
                        const nresults = decodeNresults(child.callstatus);
                        if (nresults < 0) {
                            const src_val = ctx.regs[a];
                            // Pop child frame — same as ordinary fast arm
                            // (T7: stable parent reused across the shrink).
                            const child_m = @constCast(child);
                            child_m.callstatus = 0;
                            self.bc_stack_top = parent_c.frameBase() + parent_c.u.lua.frame_cap;
                            ctx.exec_frames.shrinkTo(ctx.frame_index);
                            const parent_m = @constCast(parent_c);
                            if (parent_m.u.lua.simpleResultIsCompare()) {
                                // Compare mode: check truthiness, adjust pc.
                                const result = isTruthy(src_val);
                                const invert = parent_m.u.lua.simpleResultInvert();
                                parent_m.u.lua.pc += 1;
                                if (result != invert) parent_m.u.lua.pc += 1;
                            } else {
                                // Value mode: single-copy into parent register.
                                const sr_dst = parent_m.u.lua.simple_result_dst;
                                self.bc_stack[parent_c.frameBase() + sr_dst] = src_val;
                                parent_m.reg_top = @intCast(sr_dst + 1);
                                parent_m.u.lua.pc += 1;
                            }
                            parent_m.u.lua.clearSimpleResult();
                            return .continue_frame_loop;
                        }
                    }
                }
            }
            // Fallback: scratch + completeBytecodeExecFrame.
            self.bc_return_scratch[0] = ctx.regs[a];
            if (try self.completeBytecodeExecFrame(
                ctx.exec_frames,
                ctx.boundary_depth,
                self.bc_return_scratch[0..1],
            )) |final| return .{ .return_results = final };
            return .continue_frame_loop;
        }
        const ret = try self.alloc.alloc(Value, 1);
        var ret_owned = true;
        errdefer if (ret_owned) self.alloc.free(ret);
        ret[0] = ctx.regs[a];
        // beginBytecodeClose takes ownership of `ret` (stored in
        // close_state.post.return_frame). The errdefer must not free it
        // if beginBytecodeClose accepted the slice — even on error.Yield,
        // the close continuation retains the slice for resume.
        ret_owned = false;
        // Sync pc so GC (which may run inside __close
        // finalizers via collectgarbage()) sees the correct live_reg_top[pc].
        // P15.51l: reg_top is already on the CallFrame (rare field).
        {
            const fr = ctx.exec_frames.getPtr(ctx.frame_index);
            fr.u.lua.pc = ctx.pc;
        }
        return switch (try self.beginBytecodeClose(
            ctx.exec_frames,
            ctx.boundary_depth,
            ctx.frame_index,
            0,
            null,
            true,
            .{ .return_frame = ret },
        )) {
            .resume_dispatch => .continue_frame_loop,
            .final => |final| .{ .return_results = final },
            .propagate_error => .propagate_error,
        };
    }

    /// OP_VARARG: R[A..A+C-2] = varargs. C-1 results wanted; C==0 means
    /// multret (copy all). Frame may grow to hold the values.
    fn opVararg(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const inst = ctx.cur_proto.code[ctx.pc];
        const a: usize = inst.a;
        const c: u8 = inst.c;

        const named_varargs = try self.getBytecodeVarargTable(ctx.cur_proto, ctx.regs);
        // P16.10b: mode-aware varargs accessor (vahid: below func_slot;
        // table mode: base+numparams). The old unconditional
        // func_slot-nextra slice underflowed for table-mode frames whose
        // func_slot < nextraargs.
        const fr_va = ctx.exec_frames.getPtr(ctx.frame_index);
        const va_slice: []Value = self.frameVarargs(fr_va, null);
        const source_len = if (named_varargs) |src| src.len else va_slice.len;
        const nresults: i32 = if (c == 0) -1 else @intCast(c - 1);
        if (nresults >= 0) {
            const nr: usize = @intCast(nresults);
            try self.growCtxFrame(ctx, a + nr);
            const ncopy2 = @min(nr, source_len);
            for (0..ncopy2) |i| {
                ctx.regs[a + i] = if (named_varargs) |src|
                    try self.tableGetRawValue(src.table, .{ .Int = @intCast(i + 1) })
                else
                    va_slice[i];
            }
            for (ncopy2..nr) |i| ctx.regs[a + i] = .Nil;
            fr_va.reg_top = @max(fr_va.reg_top, @as(u32, @intCast(a + nr)));
        } else {
            // All varargs — grow frame, then copy.
            try self.growCtxFrame(ctx, a + source_len);
            for (0..source_len) |i| {
                ctx.regs[a + i] = if (named_varargs) |src|
                    try self.tableGetRawValue(src.table, .{ .Int = @intCast(i + 1) })
                else
                    va_slice[i];
            }
            fr_va.reg_top = @intCast(@as(usize, a) + source_len);
        }
        return .continue_dispatch;
    }

    /// OP_CLOSURE: R[A] = closure(P[B]). Creates upvalue cells from the
    /// child Proto's upvalue descriptions. Instack upvalues capture from the
    /// current frame's registers; others proxy from current upvalues.
    /// Recursive closures (local f = function() ... f() ... end) require
    /// syncing the boxed cell after the closure is stored in its own slot.
    fn opClosure(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const inst = ctx.cur_proto.code[ctx.pc];
        const a: usize = inst.a;
        const b: u8 = inst.b;

        const child_proto = ctx.cur_proto.p[b];

        // Create upvalue cells from child's upvalue descriptions.
        const nups = child_proto.upvalues.len;
        const cells = try self.alloc.alloc(*Cell, nups);
        // P16.19 T3: boxed slots are not hot dispatch state; derive the
        // frame's boxed slice locally at the (comparatively cold) closure-
        // creation point. Open-upvalue semantics unchanged (smoke 67).
        const boxed = self.bc_boxed[ctx.base .. ctx.base + ctx.frame_cap];
        for (child_proto.upvalues, 0..) |uv, i| {
            if (uv.instack) {
                // Capture from current frame's register.
                if (boxed[uv.idx]) |cell| {
                    cells[i] = cell;
                } else {
                    const cell = try self.alloc.create(Cell);
                    // PUC luaF_findupval: create an OPEN upvalue that points
                    // to the stack slot. The cell's bc_stack_idx is the
                    // absolute index into the owning thread's stack.
                    // bc_stack_thread identifies which thread's stack to use
                    // (needed when the owning coroutine is suspended).
                    const th = self.activeBytecodeThread();
                    cell.* = .{
                        .value = ctx.regs[uv.idx],
                        .bc_stack_idx = @intCast(ctx.base + uv.idx),
                        .bc_stack_thread = th,
                    };
                    try self.gcRegisterCell(cell);
                    // PUC luaC_newobj charges every new GC object to
                    // totalbytes (GCdebt). This is the hottest Cell-creation
                    // path (closure capturing a local from the current
                    // frame); without the charge, gcFreeObject's credit at
                    // collection time over-decrements gc_count_kb, which
                    // collapses the count to 0 and breaks all gen-GC pacing
                    // (P16.4f bug B, cell variant).
                    self.gcNoteAlloc(@sizeOf(Cell));
                    boxed[uv.idx] = cell;
                    cells[i] = cell;
                    // Mark the frame as having open upvalues so that
                    // closeBytecodeUpvaluesFrom knows to scan on return.
                    // The dispatch loop's fast path (OP_MOVE etc.) reads
                    // this flag directly from the CallFrame (P15.51l).
                    ctx.exec_frames.getPtr(ctx.frame_index).u.lua.setOpenUpvalues(true);
                }
            } else {
                // Proxy from current frame's upvalues.
                cells[i] = ctx.cur_upvalues[uv.idx];
            }
        }

        const cl = try self.alloc.create(Closure);
        cl.* = .{
            .proto = child_proto,
            .upvalues = cells,
        };
        // OP_CLOSURE shares the parent's tree: the child closure takes
        // its own reference, so children safely outlive the root
        // closure (P16.10b S5 — supported sharing, not theoretical).
        // P16.16 C2/T4.2: the owner is derived from the child's proto
        // (child.tree == root), no separate field on the closure.
        _ = self.retainTreeForClosure(child_proto);
        try self.gcRegisterClosure(cl);
        // PUC luaM_*: every allocation decrements GCdebt via gcNoteAlloc.
        // Without this, condGcFromDispatch never triggers for closure-heavy
        // loops, and the table with __gc metatable is never collected.
        self.gcNoteAlloc(@sizeOf(Closure) + nups * @sizeOf(*Cell));
        self.testc_obj_functions += 1;
        ctx.regs[a] = .{ .Closure = cl };
        // If this register was captured as an upvalue (ctx.boxed), update the
        // cell to reflect the new value. Essential for recursive closures.
        // For OPEN cells, the register write already updated the stack slot.
        // For CLOSED cells, sync the cell value and fire the write barrier.
        if (boxed[a]) |cell| {
            if (!cell.isOpen()) {
                try self.gcStoreCellValue(cell, ctx.regs[a]);
            }
        }
        return .continue_dispatch;
    }

    /// OP_TFORCALL: R[A+4..A+3+C] := R[A](R[A+1], R[A+2]).
    /// Generic-for iterator call. PUC luaV_execute TFORCALL has 2 fixed args
    /// (state, ctrl) at R[A+1..A+3]; iterator is at R[A]. Arg count is not
    /// encoded — always 2. Resolves `__call` metamethod chain (up to 16 deep).
    /// Bytecode iterators push a child frame via the iterative dispatch stack;
    /// builtins and IR closures are called synchronously via runClosure.
    fn opTforcall(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const inst = ctx.cur_proto.code[ctx.pc];
        const a: u8 = inst.a;
        const c: u8 = inst.c;

        const nresults: u8 = if (c == 0) 0 else c - 1;

        // PUC-faithful TFORCALL: copy func+state+control ABOVE the close value
        // (R[A+3]) BEFORE __call resolution. This preserves R[A..A+3] (iterator,
        // state, control, close value) from being corrupted by __call's
        // in-place shift (tryCallMetamethodInPlace shifts callee+args up by 1,
        // which would overwrite the close value at R[A+3]).
        // PUC luaV_execute copies to ra+3..ra+5 and calls from there; luazig's
        // layout has close at R[A+3] (no TFORPREP swap), so we copy to
        // R[A+4..A+6] and resolve/call from func_slot = A+4.
        ctx.regs[a + 4] = ctx.regs[a]; // func
        ctx.regs[a + 5] = ctx.regs[a + 1]; // state
        ctx.regs[a + 6] = ctx.regs[a + 2]; // control

        // ── PUC luaD_precall: inline callee type resolution ──
        // Resolve on the copy at R[A+4], not the original at R[A].
        var effective_nargs: usize = 2;
        var chain_depth: usize = 0;
        while (true) {
            switch (ctx.regs[a + 4]) {
                .Closure, .Builtin => break,
                else => {
                    if (chain_depth >= 16) return self.fail("'__call' chain too long", .{});
                    const current_callee = ctx.regs[a + 4];
                    self.tryCallMetamethodInPlace(
                        ctx.base,
                        a + 4,
                        &effective_nargs,
                        &ctx.frame_cap,
                        &ctx.regs,
                        &chain_depth,
                    ) catch |err| {
                        if (err == error.RuntimeError and self.err != null and
                            std.mem.startsWith(u8, self.err.?, "attempt to call a "))
                        {
                            return self.fail(
                                "attempt to call a {s} value (iterator)",
                                .{current_callee.typeName()},
                            );
                        }
                        return err;
                    };
                },
            }
        }

        const callee_val = ctx.regs[a + 4];

        // Pre-grow bc_stack so the rargs slice stays valid across pushBytecodeExecFrame.
        const child_frame_cap: u32 = switch (callee_val) {
            .Closure => |cl| if (cl.proto) |p| @intCast(p.maxstacksize + EXTRA_MARGIN) else 0,
            else => 0,
        };
        const child_nextra: usize = switch (callee_val) {
            .Closure => |cl| if (cl.proto) |p| (if (p.flags.is_vararg and effective_nargs > p.numparams) effective_nargs - p.numparams else 0) else 0,
            else => 0,
        };
        try self.ensureBcStackCap(self.bc_stack_top + child_frame_cap + child_nextra);
        ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
        // rargs are at R[A+5..] (after the copy at A+4 which may have been
        // replaced by __call resolution).
        const rargs_builtin = ctx.regs[a + 5 .. a + 5 + effective_nargs];

        // Bytecode iterators join the iterative dispatch stack (same as OP_CALL).
        if (callee_val == .Closure) {
            const cl = callee_val.Closure;
            if (cl.proto) |child_proto| {
                try self.setPendingCall(ctx.exec_frames.getPtr(ctx.frame_index), .{
                    .callee = callee_val,
                    .completion = .{ .results = .{
                        .dst = a + 4,
                        .nresults = @intCast(nresults),
                        .min_reg_top = @as(u32, a) + 4 + nresults,
                    } },
                });
                // Call from R[A+4] — above the close value at R[A+3].
                // Staged-ABI activation: iterator at R[A+4], args at
                // R[A+5..] already in place (zero-copy).
                try self.pushStagedBytecodeExecFrame(ctx.exec_frames, child_proto, ctx.base + a + 4, effective_nargs, @intCast(nresults));
                // PUC OP_TFORCALL (lvm.c): the iterator is invoked via
                // luaD_call → luaG_tracecall → LUA_HOOKCALL with
                // name="for iterator" (ldebug.c funcnamefromcode).
                try self.dispatchCalleeActivationHook(ctx.exec_frames, callee_val, effective_nargs);
                return .continue_frame_loop;
            }
        }

        // Builtins and frozen IR closures remain synchronous.
        const ret = switch (callee_val) {
            .Builtin => |id| blk: {
                const out_len = @max(self.builtinOutLen(id, rargs_builtin), @as(usize, nresults));
                var outs_small: [8]Value = undefined;
                var outs_heap: ?[]Value = null;
                const outs = if (out_len <= outs_small.len) outs_small[0..out_len] else blk2: {
                    outs_heap = try self.alloc.alloc(Value, out_len);
                    break :blk2 outs_heap.?;
                };
                defer if (outs_heap) |h| self.alloc.free(h);
                ctx.exec_frames.getPtr(ctx.frame_index).u.lua.pc = ctx.pc;
                // P15.83r (PUC precallC ordering): a builtin iterator called
                // by OP_TFORCALL goes through luaD_call → precallC in PUC —
                // the C CallInfo exists before LUA_HOOKCALL fires, and the
                // name resolves to "for iterator" (getFuncNameForFrame's
                // .tforcall branch reads this caller's instruction).
                var iter_cframe_pushed = false;
                if (id != .collectgarbage and id != .string_sub) {
                    try self.pushBuiltinCFrame(callee_val);
                    iter_cframe_pushed = true;
                    const cf_idx = self.activeBytecodeThread().call_frames.len() - 1;
                    const iter_hook_args = self.bc_stack[ctx.base + a + 5 .. ctx.base + a + 5 + effective_nargs];
                    self.dispatchCCalleeActivationHook(cf_idx, callee_val, iter_hook_args) catch |hook_err| {
                        self.popBuiltinCFrame();
                        return hook_err;
                    };
                    self.builtin_cframe_pre_pushed = true;
                }
                // P15.51l: reg_top lives directly on the CallFrame.
                // pushBuiltinCFrame may have reallocated bc_stack — re-derive
                // the args slice for callBuiltin.
                const rargs_builtin_fresh = if (iter_cframe_pushed)
                    self.bc_stack[ctx.base + a + 5 .. ctx.base + a + 5 + effective_nargs]
                else
                    rargs_builtin;
                try self.callBuiltin(id, rargs_builtin_fresh, outs);
                const produced: usize = if (builtinHasDynamicOutCount(id))
                    @min(self.last_builtin_out_count, outs.len)
                else
                    out_len;
                break :blk try self.alloc.dupe(Value, outs[0..produced]);
            },
            .Closure => |cl| blk: {
                try self.setPendingCall(ctx.exec_frames.getPtr(ctx.frame_index), .{
                    .callee = callee_val,
                    .completion = .{ .results = .{
                        .dst = a + 4,
                        .nresults = @intCast(nresults),
                        .min_reg_top = @as(u32, a) + 4 + nresults,
                    } },
                });
                const values = self.runClosure(cl, rargs_builtin) catch |call_err| switch (call_err) {
                    error.Yield => {
                        if (ctx.boundary_depth == 0) {
                            if (self.current_thread) |th| {
                                th.bytecode_inplace_suspended = true;
                                ctx.yielded_in_place.* = true;
                            }
                        }
                        return error.Yield;
                    },
                    else => {
                        self.clearPendingCall(ctx.exec_frames.getPtr(ctx.frame_index));
                        return call_err;
                    },
                };
                self.clearPendingCall(ctx.exec_frames.getPtr(ctx.frame_index));
                break :blk values;
            },
            else => unreachable,
        };
        defer self.alloc.free(ret);

        // Refresh ctx.regs after potential realloc, then write results.
        ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
        const fr_tfc = ctx.exec_frames.getPtr(ctx.frame_index);
        if (nresults < 0) {
            // LUA_MULTRET: copy all results, adjust reg_top.
            const n = ret.len;
            for (0..n) |i| ctx.regs[a + 4 + i] = ret[i];
            fr_tfc.reg_top = @max(fr_tfc.reg_top, @as(u32, a) + 4 + @as(u32, @intCast(n)));
        } else {
            const n_results_u: usize = @intCast(nresults);
            const n = @min(ret.len, n_results_u);
            for (0..n) |i| ctx.regs[a + 4 + i] = ret[i];
            for (n..n_results_u) |i| ctx.regs[a + 4 + i] = .Nil;
            fr_tfc.reg_top = @max(fr_tfc.reg_top, @as(u32, a) + 4 + @as(u32, @intCast(n_results_u)));
        }
        return .continue_dispatch;
    }

    /// OP_FORPREP: numeric for-loop setup. Reads R[A]=init, R[A+1]=limit,
    /// R[A+2]=step. Rearranges into the runtime form (count/limit + step +
    /// loop var) and jumps to the loop body (skips by B:C offset). The
    /// `+1` offset is implicit: the dispatcher's `ctx.pc += 1` advances past
    /// FORPREP, so the handler sets `ctx.pc += off` (no extra +1).
    /// Returns `.continue_dispatch` (normal advance) for the loop body and
    /// skip paths.
    fn opForprep(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const inst = ctx.cur_proto.code[ctx.pc];
        const a: u8 = inst.a;
        const b: u8 = inst.b;
        const c: u8 = inst.c;

        const init_val = ctx.regs[a];
        const limit_val = ctx.regs[a + 1];
        const step_val = ctx.regs[a + 2];

        if (init_val == .Int and step_val == .Int) {
            // ── Integer loop path ──
            const init_i = init_val.Int;
            const step_i = step_val.Int;
            if (step_i == 0) return self.fail("'for' step is zero", .{});

            // Try to convert limit to integer (matching PUC forlimit).
            const limit_i: ?i64 = blk: {
                if (limit_val == .Int) break :blk limit_val.Int;
                if (limit_val == .Num) {
                    const f = limit_val.Num;
                    if (step_i < 0) {
                        const r = @ceil(f);
                        if (r >= @as(f64, @floatFromInt(std.math.minInt(i64))) and
                            r <= @as(f64, @floatFromInt(std.math.maxInt(i64))))
                            break :blk @as(i64, @intFromFloat(r));
                    } else {
                        const r = @floor(f);
                        if (r >= @as(f64, @floatFromInt(std.math.minInt(i64))) and
                            r <= @as(f64, @floatFromInt(std.math.maxInt(i64))))
                            break :blk @as(i64, @intFromFloat(r));
                    }
                    if (f > 0) {
                        if (step_i < 0) break :blk null; // skip via float path
                        break :blk std.math.maxInt(i64);
                    }
                    if (step_i > 0) break :blk null; // skip via float path
                    break :blk std.math.minInt(i64);
                }
                if (limit_val == .String) {
                    const s = limit_val.String.bytes();
                    const parsed = luaStrToNum(s) orelse {
                        return self.fail("bad 'for' limit (number expected, got {s})", .{self.valueTypeName(limit_val)});
                    };
                    if (step_i < 0) {
                        break :blk @as(i64, @intFromFloat(@ceil(parsed)));
                    } else {
                        break :blk @as(i64, @intFromFloat(@floor(parsed)));
                    }
                }
                break :blk null;
            };

            if (limit_i) |li| {
                const should_skip = if (step_i > 0) init_i > li else init_i < li;
                if (should_skip) {
                    const off_bits: u16 = @as(u16, b) | (@as(u16, c) << 8);
                    const off: i16 = @bitCast(off_bits);
                    // +1 is supplied by dispatcher's ctx.pc += 1 after return.
                    ctx.pc = @intCast(@as(i64, @intCast(ctx.pc)) + @as(i64, off));
                    return .continue_dispatch;
                }

                // Compute iteration count (PUC approach, avoids overflow).
                const count: u64 = if (step_i > 0) blk: {
                    const n = @as(u64, @bitCast(li)) -% @as(u64, @bitCast(init_i));
                    break :blk if (step_i != 1) n / @as(u64, @bitCast(step_i)) else n;
                } else blk: {
                    const n = @as(u64, @bitCast(init_i)) -% @as(u64, @bitCast(li));
                    break :blk n / (@as(u64, @bitCast(-(step_i + 1))) +% 1);
                };

                // Rearrange registers: R[A]=count, R[A+1]=step, R[A+2]=init.
                ctx.regs[a] = .{ .Int = @bitCast(count) };
                ctx.regs[a + 1] = .{ .Int = step_i };
                ctx.regs[a + 2] = .{ .Int = init_i };
                ctx.regs[a + 3] = .{ .Int = init_i }; // loop variable
                // P15.51l: reg_top is a rare field, write to CallFrame.
                const fr_fp = ctx.exec_frames.getPtr(ctx.frame_index);
                fr_fp.reg_top = @max(fr_fp.reg_top, @as(u32, a) + 4);
                return .continue_dispatch;
            }
        }

        // ── Float loop path (with string coercion) ──
        const init_f = blk: {
            if (init_val == .Int) break :blk @as(f64, @floatFromInt(init_val.Int));
            if (init_val == .Num) break :blk init_val.Num;
            if (init_val == .String) {
                break :blk luaStrToNum(init_val.String.bytes()) orelse
                    return self.fail("bad 'for' initial value (number expected, got {s})", .{self.valueTypeName(init_val)});
            }
            return self.fail("bad 'for' initial value (number expected, got {s})", .{self.valueTypeName(init_val)});
        };
        const limit_f = blk: {
            if (limit_val == .Int) break :blk @as(f64, @floatFromInt(limit_val.Int));
            if (limit_val == .Num) break :blk limit_val.Num;
            if (limit_val == .String) {
                break :blk luaStrToNum(limit_val.String.bytes()) orelse
                    return self.fail("bad 'for' limit (number expected, got {s})", .{self.valueTypeName(limit_val)});
            }
            return self.fail("bad 'for' limit (number expected, got {s})", .{self.valueTypeName(limit_val)});
        };
        const step_f = blk: {
            if (step_val == .Int) break :blk @as(f64, @floatFromInt(step_val.Int));
            if (step_val == .Num) break :blk step_val.Num;
            if (step_val == .String) {
                break :blk luaStrToNum(step_val.String.bytes()) orelse
                    return self.fail("bad 'for' step (number expected, got {s})", .{self.valueTypeName(step_val)});
            }
            return self.fail("bad 'for' step (number expected, got {s})", .{self.valueTypeName(step_val)});
        };

        if (step_f == 0) return self.fail("'for' step is zero", .{});

        const should_run = if (step_f > 0) init_f <= limit_f else init_f >= limit_f;
        if (!should_run) {
            const off_bits: u16 = @as(u16, b) | (@as(u16, c) << 8);
            const off: i16 = @bitCast(off_bits);
            // +1 is supplied by dispatcher's ctx.pc += 1 after return.
            ctx.pc = @intCast(@as(i64, @intCast(ctx.pc)) + @as(i64, off));
            return .continue_dispatch;
        }

        // Rearrange: R[A]=limit, R[A+1]=step, R[A+2]=idx (control var).
        ctx.regs[a] = .{ .Num = limit_f };
        ctx.regs[a + 1] = .{ .Num = step_f };
        ctx.regs[a + 2] = .{ .Num = init_f };
        ctx.regs[a + 3] = .{ .Num = init_f }; // loop variable
        // P15.51l: reg_top is a rare field, write to CallFrame.
        const fr_fp2 = ctx.exec_frames.getPtr(ctx.frame_index);
        fr_fp2.reg_top = @max(fr_fp2.reg_top, @as(u32, a) + 4);
        return .continue_dispatch;
    }

    /// OP_CONCAT: R[A] := R[A].. ... ..R[A+B-2]. The whole range is duplicated
    /// to continuation-owned storage because a bytecode __concat metamethod
    /// can yield or call arbitrarily deep — no Zig activation may retain the
    /// accumulator. `advanceBytecodeConcat` either pushes a metamethod frame
    /// (returns `.continue_frame_loop`) or completes synchronously (returns
    /// `.continue_dispatch` with the result written to R[A]).
    fn opConcat(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const inst = ctx.cur_proto.code[ctx.pc];
        const a: u8 = inst.a;
        const b: u8 = inst.b;

        const concat_vals = try self.alloc.dupe(Value, ctx.regs[a .. a + b]);
        const outcome = try self.advanceBytecodeConcat(
            ctx.exec_frames,
            ctx.frame_index,
            a,
            concat_vals,
            if (concat_vals.len == 0) 0 else concat_vals.len - 1,
            if (concat_vals.len == 0)
                .{ .String = try self.internLiteral("") }
            else
                concat_vals[concat_vals.len - 1],
        );
        return switch (outcome) {
            .pushed => .continue_frame_loop,
            .value => |result| blk: {
                ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                ctx.regs[a] = result;
                break :blk .continue_dispatch;
            },
        };
    }

    /// OP_TAILCALL: return R[A](R[A+1..A+B-1]). Implements PUC's tail-call
    /// semantics: reuse current frame for bytecode-to-bytecode calls (no C
    /// stack growth), host-recursion for builtins/IR closures. Handles:
    ///   - resumed_direct_yield early-return path (coroutine.yield resume)
    ///   - inline callee type resolution with __call metamethod chain
    ///   - tail-call debug hook
    ///   - pending TBC closer scan via beginBytecodeClose
    ///   - pairs/pcall/coroutine fast paths
    ///   - bytecode-to-bytecode frame reuse (the common case)
    ///   - builtin/IR closure fallback via runClosure
    /// Returns `.continue_no_advance` after frame reuse (pc was reset to 0).
    fn opTailcall(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const inst = ctx.cur_proto.code[ctx.pc];
        const a: u8 = inst.a;
        const b: u8 = inst.b;

        // P15.51l: resumed_direct_yield/resume_pc/reg_top are rare fields,
        // read directly from the CallFrame.
        const fr_tc = ctx.exec_frames.getPtr(ctx.frame_index);
        if (fr_tc.isHookYield() and ctx.pc == @as(usize, fr_tc.u.lua.resume_pc)) {
            const vals = if (self.current_thread) |th| takeBytecodeResumeValues(th, self.alloc) orelse try self.alloc.alloc(Value, 0) else try self.alloc.alloc(Value, 0);
            var vals_owned = true;
            errdefer if (vals_owned) self.alloc.free(vals);
            fr_tc.clearHookYield();
            // Clear pending_call_index that was set by the original OP_TAILCALL
            // before the C function yielded. The results are in `vals` now —
            // the pending call is no longer needed. Without this, beginBytecodeClose
            // would assert pending_call_index == INVALID_PENDING.
            self.clearPendingCall(fr_tc);
            _ = &vals_owned;
            return switch (try self.beginBytecodeClose(
                ctx.exec_frames,
                ctx.boundary_depth,
                ctx.frame_index,
                0,
                null,
                true,
                .{ .return_frame = vals },
            )) {
                .resume_dispatch => .continue_frame_loop,
                .final => |final| .{ .return_results = final },
                .propagate_error => .propagate_error,
            };
        }
        const nargs: usize = if (b == 0) fr_tc.reg_top - a - 1 else b - 1;

        // ── PUC luaD_precall: inline callee type resolution ──
        var effective_nargs = nargs;
        var chain_depth: usize = 0;
        while (true) {
            switch (ctx.regs[a]) {
                .Closure, .Builtin => break,
                else => {
                    if (chain_depth >= 16) return self.fail("'__call' chain too long", .{});
                    const current_callee = ctx.regs[a];
                    self.tryCallMetamethodInPlace(
                        ctx.base,
                        a,
                        &effective_nargs,
                        &ctx.frame_cap,
                        &ctx.regs,
                        &chain_depth,
                    ) catch |err| {
                        if (err == error.RuntimeError and self.err != null and
                            std.mem.startsWith(u8, self.err.?, "attempt to call a "))
                        {
                            const inferred = debugBytecodeOperandName(ctx.cur_proto, ctx.pc, a);
                            if (inferred.name) |name| {
                                return self.fail(
                                    "attempt to call a {s} value ({s} '{s}')",
                                    .{ current_callee.typeName(), inferred.namewhat, name },
                                );
                            }
                        }
                        return err;
                    };
                },
            }
        }

        const callee_val = ctx.regs[a];
        var call_args = ctx.regs[a + 1 .. a + 1 + effective_nargs];

        const hook_args = switch (callee_val) {
            .Closure => |cl| debugCallTransferArgsForClosure(cl, call_args),
            else => call_args,
        };
        // PUC event selection for tail calls (lvm.c OP_TAILCALL →
        // luaD_pretailcall): a bytecode callee reuses the current frame and
        // fires LUA_HOOKTAILCALL when the new function starts (ldebug.c:918
        // luaG_tracecall sees CIST_TAIL). A C-function callee goes through
        // precallC (ldo.c:652) which pushes a FRESH CallInfo without
        // CIST_TAIL — firing a plain LUA_HOOKCALL.
        const callee_is_bytecode = switch (callee_val) {
            .Closure => |cl| cl.proto != null,
            else => false,
        };
        const tc_event: []const u8 = if (callee_is_bytecode) "tail call" else "call";
        var deferred_tail_hook = false;
        var deferred_builtin_call_hook = false;
        // P16.21 T4.2: no hook-replay state is read when hooks are off
        // (PUC checks the hook mask first — ldebug.c luaG_tracecall).
        const skip_tail_hook = (self.dispatch_gate & DISPATCH_GATE_HOOKS != 0) and
            ctx.exec_frames.getPtr(ctx.frame_index).u.lua.skip_call_hook_pc == @as(u32, @intCast(ctx.pc));
        if (skip_tail_hook) {
            ctx.exec_frames.getPtr(ctx.frame_index).u.lua.skip_call_hook_pc = INVALID_PC;
        } else if (try self.tryPushBytecodeDebugHook(
            ctx.exec_frames,
            ctx.frame_index,
            tc_event,
            null,
            callee_val,
            hook_args,
            1,
            .retry_call,
        )) {
            return .continue_frame_loop;
        } else if (callee_is_bytecode) {
            // Bytecode callee: fire the TAILCALL hook AFTER the frame is
            // reused for the new function (PUC fires at the new function's
            // first instruction, with ci->func already swapped).
            deferred_tail_hook = true;
        } else switch (callee_val) {
            .Builtin => |id| {
                // P15.83r (PUC precallC via luaD_pretailcall): plain
                // LUA_HOOKCALL on a FRESH C CallInfo. Divert-bound and
                // frameless builtins keep the legacy caller-frame identity
                // (see opCall's dispatch block); sync-bound builtins defer
                // to the callBuiltin site below.
                if (self.builtinCallMayDivert(id, hook_args) or id == .collectgarbage or id == .string_sub) {
                    try self.debugDispatchHookWithCalleeTransfer(
                        "call",
                        null,
                        callee_val,
                        hook_args,
                        1,
                        null,
                    );
                } else {
                    deferred_builtin_call_hook = true;
                }
            },
            .Closure => |cl| {
                if (cl.c_func == null) {
                    // IR closure: no C activation exists — legacy
                    // caller-frame identity.
                    try self.debugDispatchHookWithCalleeTransfer(
                        "call",
                        null,
                        callee_val,
                        hook_args,
                        1,
                        null,
                    );
                }
                // C closure: callCFunction fires the event on its C-frame.
            },
            else => unreachable,
        }

        // P15.51l: tbc_mark is a rare field, read from CallFrame.
        const has_pending_tbc = self.bc_tbc_regs.items.len > ctx.exec_frames.getPtr(ctx.frame_index).tbc_mark;
        if (has_pending_tbc) {
            return switch (try self.beginBytecodeClose(
                ctx.exec_frames,
                ctx.boundary_depth,
                ctx.frame_index,
                0,
                null,
                true,
                .retry_tailcall,
            )) {
                .resume_dispatch => .continue_frame_loop,
                .final => |final| .{ .return_results = final },
                .propagate_error => .propagate_error,
            };
        }
        if (callee_val == .Builtin and
            callee_val.Builtin == .pairs and
            try self.tryPushBytecodePairsMetamethod(
                ctx.exec_frames,
                ctx.frame_index,
                call_args,
                .{ .dst = a, .nresults = -1, .tail_return = true },
            ))
        {
            return .continue_frame_loop;
        }
        if (callee_val == .Builtin and
            try self.tryPushBytecodeProtectedCall(
                ctx.exec_frames,
                ctx.frame_index,
                a,
                -1,
                callee_val.Builtin,
                call_args,
                true,
            ))
        {
            return .continue_frame_loop;
        }
        if (callee_val == .Builtin and
            try self.tryRequestBytecodeCoroutineSwitch(
                ctx.exec_frames,
                ctx.frame_index,
                a,
                -1,
                callee_val.Builtin,
                call_args,
                true,
            )) return error.ThreadSwitch;

        switch (callee_val) {
            .Closure => |cl| if (cl.proto) |new_proto| {
                // ── Bytecode-to-bytecode tail call: frame reuse ──
                // P16.10b Task 15: constants are runtime-ready by
                // construction (adopted at closure creation); Debug
                // tripwire mirrors pushBytecodeExecFrame.
                if (@import("builtin").mode == .Debug) {
                    if (new_proto.tree) |t| std.debug.assert(t.flags.constants_resolved);
                }

                // 1. Close all boxed upvalues (derived locally, P16.19 T3).
                for (self.bc_boxed[ctx.base .. ctx.base + ctx.frame_cap]) |*bc_slot| {
                    if (bc_slot.*) |cell| {
                        cell.close(self);
                        // PUC luaF_closeupval (lfunc.c:205-208): if !iswhite:
                        //   nw2black + luaC_barrier. Fix color, then barrier.
                        if (!gcIsWhite(cell.gc_marked)) {
                            gcSetBlack(&cell.gc_marked);
                            self.gcWriteBarrierCell(cell, cell.value) catch {};
                        }
                        bc_slot.* = null;
                    }
                }

                // 2. Grow frame if needed.
                const new_max = new_proto.maxstacksize;
                const new_cap: usize = new_max;
                try self.growCtxFrame(ctx, new_cap);

                // 3. PUC-faithful tail-call: reuse frame, re-setup varargs.
                //    Step 1: copy func+args from R[A..] down to func_slot_base
                //    (the ORIGINAL position, before any previous buildhiddenargs
                //    shift). This prevents cumulative shifting across repeated
                //    tail calls.
                //    Step 2: if new proto is VAHID, buildhiddenargs shifts
                //    func+params UP past the extra args.
                const np = new_proto.numparams;
                const new_nextra: usize = if (new_proto.flags.is_vararg and effective_nargs > np)
                    effective_nargs - np
                else
                    0;
                const new_is_vahid = new_proto.flags.is_vararg and new_nextra > 0 and
                    new_proto.vararg_table_reg == bc.Proto.no_vararg_reg;

                // Reset to the original (unshifted) func_slot_base.
                const reset_slot = ctx.exec_frames.getPtr(ctx.frame_index).originalFuncSlot();
                const reset_base = reset_slot + 1;
                try self.ensureBcStackCap(reset_base + @max(new_cap, effective_nargs + 1));

                // Copy func + args from regs[a..a+1+effective_nargs] down to
                // [reset_slot..reset_slot+1+effective_nargs].
                const total_move = effective_nargs + 1;
                std.mem.copyForwards(
                    Value,
                    self.bc_stack[reset_slot .. reset_slot + total_move],
                    self.bc_stack[ctx.base + a .. ctx.base + a + total_move],
                );
                // Nil-fill missing params at the copied position.
                const nc = @min(np, effective_nargs);
                for (nc..np) |i| {
                    self.bc_stack[reset_slot + 1 + i] = .Nil;
                }

                // VAHID buildhiddenargs: shift func+params up past extra args.
                var new_func_slot = reset_slot;
                var new_base = new_func_slot + 1;
                if (new_is_vahid) {
                    new_func_slot = reset_slot + effective_nargs + 1;
                    new_base = new_func_slot + 1;
                    try self.ensureBcStackCap(new_base + new_cap);
                    self.bc_stack[new_func_slot] = self.bc_stack[reset_slot];
                    for (0..np) |i| {
                        self.bc_stack[new_base + i] = self.bc_stack[reset_slot + 1 + i];
                        self.bc_stack[reset_slot + 1 + i] = .Nil;
                    }
                }

                // Grow frame to new proto's register needs.
                try self.bcGrowFrame(new_base, new_cap, &ctx.frame_cap, &ctx.regs); // published below after base switch
                ctx.base = new_base;
                // P15.51l: func_slot is a rare field, written to CallFrame below.
                self.bc_stack_top = new_base + ctx.frame_cap;

                // Re-derive register slices after potential base change.
                ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];

                // P15.51l: nextraargs is a rare field, write to CallFrame.
                const new_nextra_u16: u16 = @intCast(new_nextra);
                ctx.exec_frames.getPtr(ctx.frame_index).u.lua.nextraargs = new_nextra_u16;
                ctx.exec_frames.getPtr(ctx.frame_index).u.lua.frame_cap = ctx.frame_cap;

                // Nil-fill remaining registers.
                for (ctx.regs[np..new_max]) |*r| r.* = .Nil;
                for (self.bc_boxed[new_base .. new_base + new_max]) |*bc_slot| bc_slot.* = null;

                // 6. Update frame state.
                ctx.cur_proto = new_proto;
                ctx.cur_upvalues = cl.upvalues;

                // 7. Update Frame struct on exec_frames.
                const fr2 = ctx.exec_frames.getPtr(ctx.exec_frames.len() - 1);
                fr2.u.lua.proto = new_proto;
                // P15.51n: upvalues derived from bc_stack[func_slot], not stored in frame.
                fr2.func_slot = new_func_slot; // base derived: +1 (== ctx.base)
                // P15.51g: regs/boxed no longer cached in the frame.
                // P15.51k: callee is at bc_stack[func_slot] (set by TAILCALL
                // stack setup). No duplicated field write needed.
                fr2.u.lua.pc = 0;
                fr2.reg_top = np;
                fr2.setTailCall();
                fr2.u.lua.nextraargs = new_nextra_u16;

                // 8. Reset dispatch state. pc=0; skip dispatcher's pc+=1.
                // P15.51l: reg_top is a rare field, write to CallFrame.
                ctx.pc = 0;
                fr2.reg_top = np;

                // PUC luaG_tracecall (ldebug.c:918): the TAILCALL hook fires
                // when the reused frame starts executing the NEW function —
                // ci->func already points at the new callee (ldo.c:480 picks
                // LUA_HOOKTAILCALL from CIST_TAIL). Fire it here, after the
                // frame swap, with ar.i_ci referencing this frame.
                // (hook_args is stale: the reuse may have reallocated
                // bc_stack; PUC passes ntransfer=p->numparams — the fixed
                // params now live contiguously at the new frame base.)
                if (deferred_tail_hook) {
                    const n_transfer = @min(effective_nargs, np);
                    // PUC luaD_hookcall savedpc++ (see
                    // dispatchCalleeActivationHook): a vararg callee's hook
                    // observes the instruction after VARARGPREP.
                    const tc_vararg_bump = new_proto.flags.is_vararg;
                    if (tc_vararg_bump) fr2.u.lua.pc = 1;
                    defer if (tc_vararg_bump) {
                        ctx.exec_frames.getPtr(ctx.frame_index).u.lua.pc = 0;
                    };
                    try self.debugDispatchHookWithCalleeTransfer(
                        "tail call",
                        null,
                        callee_val,
                        self.bc_stack[fr2.frameBase() .. fr2.frameBase() + n_transfer],
                        1,
                        ctx.frame_index,
                    );
                }
                return .continue_no_advance;
            },
            .Builtin => {},
            else => {},
        }

        // Non-bytecode tail call: execute the callee and return its results.
        const ret = switch (callee_val) {
            .Builtin => |id| blk: {
                // P16.5b: Fast path for coroutine.resume/yield — skip
                // pushBuiltinCFrame/callBuiltin dispatch (same guards as
                // OP_CALL's fast path).
                const co_fast_path = (id == .coroutine_resume or id == .coroutine_yield) and
                    !deferred_builtin_call_hook and
                    !deferred_tail_hook and
                    ctx.exec_frames.getPtr(ctx.frame_index).pending_call_index == INVALID_PENDING and
                    self.coroutineBuiltinFastPathEligible(id, call_args);

                const out_len = @max(self.builtinOutLen(id, call_args), 1);
                var outs_small: [8]Value = undefined;
                var outs_heap: ?[]Value = null;
                const outs = if (out_len <= outs_small.len) outs_small[0..out_len] else heap: {
                    outs_heap = try self.alloc.alloc(Value, out_len);
                    break :heap outs_heap.?;
                };
                defer if (outs_heap) |h| self.alloc.free(h);
                ctx.exec_frames.getPtr(ctx.frame_index).u.lua.pc = ctx.pc;
                // P15.83r (PUC precallC ordering via luaD_pretailcall): the
                // C CallInfo exists BEFORE the CALL hook fires. Push the
                // builtin's C-frame, fire on it, and reuse the frame inside
                // callBuiltin. (This is the tail-call-to-C path: PUC pushes
                // a FRESH ci without CIST_TAIL, so the event is a plain
                // "call" — see the tc_event selection above.)
                // P16.5b: Skip the C-frame push on the coroutine fast path.
                if (!co_fast_path and deferred_builtin_call_hook) {
                    try self.pushBuiltinCFrame(callee_val);
                    const cf_idx = self.activeBytecodeThread().call_frames.len() - 1;
                    // call_args may be stale after pushBuiltinCFrame grew
                    // bc_stack — re-derive from the caller's registers.
                    const tc_hook_args = self.bc_stack[ctx.base + a + 1 .. ctx.base + a + 1 + effective_nargs];
                    self.dispatchCCalleeActivationHook(cf_idx, callee_val, tc_hook_args) catch |hook_err| {
                        self.popBuiltinCFrame();
                        return hook_err;
                    };
                    self.builtin_cframe_pre_pushed = true;
                    call_args = self.bc_stack[ctx.base + a + 1 .. ctx.base + a + 1 + effective_nargs];
                }
                // P15.51l: reg_top lives directly on the CallFrame.
                // P16.5b: Use direct call for coroutine fast path.
                if (co_fast_path) {
                    self.callCoroutineBuiltinDirect(id, call_args, outs) catch |call_err| switch (call_err) {
                        error.Yield => {
                            if (self.canParkDirectBytecodeYield(ctx.boundary_depth, id)) {
                                const th = self.current_thread.?;
                                const fr_y = ctx.exec_frames.getPtr(ctx.frame_index);
                                var resumed = false;
                                self.parkDirectBytecodeYield(
                                    th,
                                    ctx.pc,
                                    &fr_y.u.lua.resume_pc,
                                    &resumed,
                                    ctx.boundary_depth,
                                );
                                if (resumed) fr_y.setHookYield();
                                ctx.yielded_in_place.* = true;
                            }
                            return error.Yield;
                        },
                        error.OutOfMemory => return error.OutOfMemory,
                        error.RuntimeError => return error.RuntimeError,
                        error.ThreadSwitch => return error.ThreadSwitch,
                    };
                } else {
                    self.callBuiltin(id, call_args, outs) catch |call_err| switch (call_err) {
                        error.Yield => {
                            if (self.canParkDirectBytecodeYield(ctx.boundary_depth, id)) {
                                const th = self.current_thread.?;
                                const fr_y = ctx.exec_frames.getPtr(ctx.frame_index);
                                // P15.51l: resumed_direct_yield is a CIST_HOOKYIELD
                                // flag bit, not a bool field. Use a local and set
                                // the flag after parkDirectBytecodeYield.
                                var resumed = false;
                                self.parkDirectBytecodeYield(
                                    th,
                                    ctx.pc,
                                    &fr_y.u.lua.resume_pc,
                                    &resumed,
                                    ctx.boundary_depth,
                                );
                                if (resumed) fr_y.setHookYield();
                                ctx.yielded_in_place.* = true;
                            }
                            return error.Yield;
                        },
                        error.OutOfMemory => return error.OutOfMemory,
                        error.RuntimeError => return error.RuntimeError,
                        error.ThreadSwitch => return error.ThreadSwitch,
                    };
                }
                const used = if (builtinHasDynamicOutCount(id))
                    @min(self.last_builtin_out_count, outs.len)
                else
                    outs.len;
                break :blk try self.alloc.dupe(Value, outs[0..used]);
            },
            .Closure => |cl| blk: {
                try self.setPendingCall(ctx.exec_frames.getPtr(ctx.frame_index), .{
                    .callee = callee_val,
                    .completion = .{ .results = .{
                        .dst = a,
                        .nresults = -1,
                        .tail_return = true,
                    } },
                });
                const values = self.runClosure(cl, call_args) catch |call_err| switch (call_err) {
                    error.Yield => {
                        if (ctx.boundary_depth == 0) {
                            if (self.current_thread) |th| {
                                th.bytecode_inplace_suspended = true;
                                ctx.yielded_in_place.* = true;
                            }
                        }
                        return error.Yield;
                    },
                    else => {
                        self.clearPendingCall(ctx.exec_frames.getPtr(ctx.frame_index));
                        return call_err;
                    },
                };
                self.clearPendingCall(ctx.exec_frames.getPtr(ctx.frame_index));
                break :blk values;
            },
            else => unreachable,
        };
        var ret_owned = true;
        errdefer if (ret_owned) self.alloc.free(ret);
        // beginBytecodeClose takes ownership of `ret` (stored in
        // close_state.post.return_frame). The errdefer must not free it
        // if beginBytecodeClose accepted the slice — even on error.Yield,
        // the close continuation retains the slice for resume.
        ret_owned = false;
        return switch (try self.beginBytecodeClose(
            ctx.exec_frames,
            ctx.boundary_depth,
            ctx.frame_index,
            0,
            null,
            true,
            .{ .return_frame = ret },
        )) {
            .resume_dispatch => .continue_frame_loop,
            .final => |final| .{ .return_results = final },
            .propagate_error => .propagate_error,
        };
    }

    /// OP_CALL: R[A..A+C-2] := R[A](R[A+1..A+B-1]). The main function-call
    /// opcode. Implements PUC luaD_precall inline callee type resolution:
    ///   1. Resolve `__call` metamethod chain (up to 16 deep) via in-place
    ///      bc_stack shift — no heap allocation.
    ///   2. Pre-grow bc_stack so rargs slice stays valid.
    ///   3. Dispatch call/return debug hooks.
    ///   4. Branch on callee type:
    ///      - Builtin: pairs/pcall/coroutine fast paths, then synchronous
    ///        callBuiltin + moveresults.
    ///      - Closure w/ proto: push iterative dispatch frame (continue_frame_loop).
    ///      - Closure IR: host-recursion via runClosure.
    /// Returns `.continue_dispatch` for the synchronous paths (dispatcher's
    /// pc+=1 advances past OP_CALL). Returns `.continue_frame_loop` when
    /// pushing a child frame for iterative dispatch.
    fn opCall(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const inst = ctx.cur_proto.code[ctx.pc];
        const a: u8 = inst.a;
        const b: u8 = inst.b;
        const c: u8 = inst.c;

        const nresults: i32 = if (c == 0) -1 else @intCast(c - 1);
        // P15.51l: resumed_direct_yield/resume_pc/reg_top are rare fields,
        // read directly from the CallFrame.
        const fr_call = ctx.exec_frames.getPtr(ctx.frame_index);
        if (fr_call.isHookYield() and ctx.pc == @as(usize, fr_call.u.lua.resume_pc)) {
            const vals = if (self.current_thread) |th| takeBytecodeResumeValues(th, self.alloc) orelse try self.alloc.alloc(Value, 0) else try self.alloc.alloc(Value, 0);
            var vals_owned = true;
            errdefer if (vals_owned) self.alloc.free(vals);
            fr_call.clearHookYield();
            if (try self.tryPushBytecodeDebugHook(
                ctx.exec_frames,
                ctx.frame_index,
                "return",
                null,
                ctx.regs[a],
                vals,
                1,
                .{ .store_results = .{
                    .continuation = .{ .dst = a, .nresults = nresults },
                    .values = vals,
                } },
            )) {
                vals_owned = false;
                return .continue_frame_loop;
            }
            try self.dispatchBytecodeHookWithCallee("return", ctx.regs[a], vals);
            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
            const nstore: usize = if (nresults >= 0) @intCast(nresults) else vals.len;
            try self.growCtxFrame(ctx, a + nstore);
            for (0..nstore) |i| ctx.regs[a + i] = if (i < vals.len) vals[i] else .Nil;
            // PUC Lua sets L->top = ci->top (maxstacksize) after calls.
            // We track reg_top as the runtime stack top. For multi-return
            // (nresults < 0), reg_top = a + actual count. For fixed nresults,
            // reg_top must include the stored results so GC marks them.
            // P15.51l: reg_top is a rare field, write to CallFrame.
            if (nresults < 0)
                fr_call.reg_top = @intCast(@as(usize, a) + vals.len)
            else
                fr_call.reg_top = @max(fr_call.reg_top, @as(u32, @intCast(a + nstore)));
            self.alloc.free(vals);
            _ = &vals_owned;
            // Original code did `ctx.pc += 1; continue;` — skip dispatcher +1.
            // Returning `.continue_dispatch` adds the +1 from the dispatcher,
            // giving the same final pc.
            return .continue_dispatch;
        }
        const nargs: usize = if (b == 0) fr_call.reg_top - a - 1 else b - 1;
        if (self.stats.enabled) self.stats.calls_slow += 1; // P16.0b (after hook-yield replay: a real call)

        // ── PUC luaD_precall: inline callee type resolution ──
        var effective_nargs = nargs;
        var chain_depth: usize = 0;
        while (true) {
            switch (ctx.regs[a]) {
                .Closure, .Builtin => break,
                else => {
                    if (chain_depth >= 16) return self.fail("'__call' chain too long", .{});
                    const current_callee = ctx.regs[a];
                    self.tryCallMetamethodInPlace(
                        ctx.base,
                        a,
                        &effective_nargs,
                        &ctx.frame_cap,
                        &ctx.regs,
                        &chain_depth,
                    ) catch |err| {
                        if (err == error.RuntimeError and self.err != null and
                            std.mem.startsWith(u8, self.err.?, "attempt to call a "))
                        {
                            const inferred = debugBytecodeOperandName(ctx.cur_proto, ctx.pc, a);
                            if (inferred.name) |name| {
                                return self.fail(
                                    "attempt to call a {s} value ({s} '{s}')",
                                    .{ current_callee.typeName(), inferred.namewhat, name },
                                );
                            }
                        }
                        return err;
                    };
                },
            }
        }

        // Pre-grow bc_stack so rargs stays valid across pushBytecodeExecFrame.
        // Include EXTRA_MARGIN because pushBytecodeExecFrame uses
        // proto.maxstacksize + EXTRA_MARGIN for frame_cap.
        const child_frame_cap: u32 = switch (ctx.regs[a]) {
            .Closure => |cl| if (cl.proto) |p| @intCast(p.maxstacksize + EXTRA_MARGIN) else 0,
            else => 0,
        };
        const child_nextra: usize = switch (ctx.regs[a]) {
            .Closure => |cl| if (cl.proto) |p| (if (p.flags.is_vararg and nargs > p.numparams) nargs - p.numparams else 0) else 0,
            else => 0,
        };
        try self.ensureBcStackCap(self.bc_stack_top + child_frame_cap + child_nextra);
        ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];

        const rargs = ctx.regs[a + 1 .. a + 1 + effective_nargs];

        const resolved_callee = ctx.regs[a];
        const skip_call_hook = (self.dispatch_gate & DISPATCH_GATE_HOOKS != 0) and
            ctx.exec_frames.getPtr(ctx.frame_index).u.lua.skip_call_hook_pc == @as(u32, @intCast(ctx.pc));
        // PUC ordering (luaD_precall ldo.c:715 + luaG_tracecall ldebug.c:918):
        // the callee's CallInfo is created FIRST; the CALL hook fires with
        // ar.i_ci = the callee frame. For bytecode callees we therefore defer
        // the sync (C-hook) dispatch until after pushBytecodeExecFrame below.
        // The async (Lua-hook) path keeps firing here: it pushes its own hook
        // frame as a child of the caller and installs the callee at the
        // caller's func_slot for the duration of the hook (debug.getinfo
        // parity for Lua hooks is covered by the upstream db.lua suite).
        //
        // P15.83r: C-function callees mirror PUC precallC (ldo.c:642-656) —
        // the C CallInfo exists BEFORE the hook fires:
        //   - sync-bound builtin callee: the dispatch is deferred to the
        //     synchronous callBuiltin site below, which pushes the C-frame,
        //     fires on it (ar.i_ci = the C activation), and reuses the frame
        //     inside callBuiltin via `builtin_cframe_pre_pushed`.
        //   - divert-bound builtin callee (builtinCallMayDivert): the OP_CALL
        //     fast paths below (pairs/__pairs, pcall target, coroutine
        //     switch, gsub) replace the call with bytecode continuations
        //     whose completion machinery requires the body frame to sit
        //     directly above the pending-call owner (a plain builtin C-frame
        //     in between would be misrouted by the `parent.isC()` return
        //     routing). These keep the legacy caller-frame identity —
        //     documented sub-deviation (see STATUS.md P15.83r).
        //   - frameless builtins (collectgarbage/string_sub) and IR-closure
        //     callees: legacy caller-frame identity (no C activation exists).
        //   - C-closure callee (c_func set): no dispatch here — callCFunction
        //     fires the event on its own C-frame push, which also covers
        //     lua_call/lua_pcall entries from C code (PUC precallC fires for
        //     every C activation).
        var deferred_call_hook = false;
        var deferred_builtin_call_hook = false;
        if (skip_call_hook) {
            ctx.exec_frames.getPtr(ctx.frame_index).u.lua.skip_call_hook_pc = INVALID_PC;
        } else if (!self.hooks_active_cached) {
            // No hooks active — skip both noinline hook-dispatch calls.
        } else if (try self.tryPushBytecodeDebugHook(
            ctx.exec_frames,
            ctx.frame_index,
            "call",
            null,
            resolved_callee,
            rargs,
            1,
            .retry_call,
        )) {
            return .continue_frame_loop;
        } else if (switch (resolved_callee) {
            // Bytecode callee: fire after the callee frame exists (see
            // comment above). Evaluated lazily — only on the hook path.
            .Closure => |cl| cl.proto != null,
            else => false,
        }) {
            deferred_call_hook = true;
        } else switch (resolved_callee) {
            .Builtin => |id| {
                if (self.builtinCallMayDivert(id, rargs) or id == .collectgarbage or id == .string_sub) {
                    // Legacy caller-frame identity for divert-bound and
                    // frameless builtins.
                    try self.dispatchBytecodeHookWithCallee("call", resolved_callee, rargs);
                } else {
                    // Sync-bound builtin: C-frame push + dispatch happen at
                    // the callBuiltin site below (precallC ordering).
                    deferred_builtin_call_hook = true;
                }
            },
            .Closure => |cl| {
                if (cl.c_func == null) {
                    // IR closure: no C activation exists — keep the legacy
                    // caller-frame sync dispatch.
                    try self.dispatchBytecodeHookWithCallee("call", resolved_callee, rargs);
                }
                // C closure: callCFunction fires the event on its C-frame.
            },
            else => unreachable,
        }

        const callee_val = resolved_callee;
        switch (callee_val) {
            .Builtin => |id| {
                if (id == .pairs and try self.tryPushBytecodePairsMetamethod(
                    ctx.exec_frames,
                    ctx.frame_index,
                    rargs,
                    .{ .dst = a, .nresults = nresults },
                )) {
                    return .continue_frame_loop;
                }
                if (try self.tryPushBytecodeProtectedCall(
                    ctx.exec_frames,
                    ctx.frame_index,
                    a,
                    nresults,
                    id,
                    rargs,
                    false,
                )) {
                    return .continue_frame_loop;
                }
                if (try self.tryRequestBytecodeCoroutineSwitch(
                    ctx.exec_frames,
                    ctx.frame_index,
                    a,
                    nresults,
                    id,
                    rargs,
                    false,
                )) return error.ThreadSwitch;

                if (id == .string_gsub) {
                    switch (try self.tryStartBytecodeGsub(
                        ctx.exec_frames,
                        ctx.frame_index,
                        rargs,
                        .{ .dst = a, .nresults = nresults },
                    )) {
                        .not_handled => {},
                        .pushed => return .continue_frame_loop,
                        .returned => |values| {
                            var values_owned = true;
                            errdefer if (values_owned) self.alloc.free(values);
                            if (try self.tryPushBytecodeDebugHook(
                                ctx.exec_frames,
                                ctx.frame_index,
                                "return",
                                null,
                                callee_val,
                                values,
                                1,
                                .{ .store_results = .{
                                    .continuation = .{ .dst = a, .nresults = nresults },
                                    .values = values,
                                } },
                            )) {
                                values_owned = false;
                                return .continue_frame_loop;
                            }
                            try self.dispatchBytecodeHookWithCallee("return", callee_val, values);
                            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                            const nstore: usize = if (nresults >= 0) @intCast(nresults) else values.len;
                            try self.growCtxFrame(ctx, a + nstore);
                            for (0..nstore) |i| ctx.regs[a + i] = if (i < values.len) values[i] else .Nil;
                            if (nresults < 0) ctx.exec_frames.getPtr(ctx.frame_index).reg_top = @intCast(@as(usize, a) + values.len);
                            self.alloc.free(values);
                            _ = &values_owned;
                            return .continue_dispatch;
                        },
                    }
                }

                // P16.5b: Fast path for coroutine.resume/yield — skip the
                // generic pushBuiltinCFrame/callBuiltin dispatch cycle when
                // the C-frame is provably unnecessary (no hooks, no C
                // continuations, no close mode, no wrap eager, etc.).
                // See coroutineBuiltinFastPathEligible for the full guard list.
                const co_fast_path = (id == .coroutine_resume or id == .coroutine_yield) and
                    !deferred_builtin_call_hook and
                    !deferred_call_hook and
                    ctx.exec_frames.getPtr(ctx.frame_index).pending_call_index == INVALID_PENDING and
                    self.coroutineBuiltinFastPathEligible(id, rargs);

                const out_len: usize = if (nresults >= 0)
                    @max(@as(usize, @intCast(nresults)), self.builtinOutLen(id, rargs))
                else
                    self.builtinOutLen(id, rargs);
                const outs_start = a + 1 + effective_nargs;
                try self.growCtxFrame(ctx, outs_start + out_len);
                // Re-derive rargs after bcGrowFrame: it may have reallocated
                // bc_stack, invalidating the old rargs slice (use-after-free).
                var rargs_fresh = ctx.regs[a + 1 .. a + 1 + effective_nargs];
                var outs = ctx.regs[outs_start .. outs_start + out_len];
                // Sync pc and frame_cap to frame before callBuiltin — the
                // builtin may trigger GC (reads live_reg_top[pc]) or shrink
                // bc_stack (reads frame_cap to compute inuse). Without
                // syncing frame_cap, shrinkBcStack sees the OLD (smaller)
                // frame_cap, computes a too-small inuse, and shrinks bc_stack
                // below ctx.base + ctx.frame_cap → OOB panic on return.
                // P15.51l: reg_top lives directly on the CallFrame.
                const fr_pre_call = ctx.exec_frames.getPtr(ctx.frame_index);
                fr_pre_call.u.lua.pc = ctx.pc;
                if (!fr_pre_call.isC()) fr_pre_call.u.lua.frame_cap = ctx.frame_cap;
                // P15.83r (PUC ldo.c:642-656 precallC ordering): the C
                // CallInfo exists BEFORE the CALL hook fires. Push the
                // builtin's C-frame, fire the event on it (ar.i_ci = the C
                // activation), then run the builtin reusing this frame.
                // P16.5b: Skip the C-frame push entirely on the coroutine
                // fast path — guards guarantee no hooks need it.
                if (!co_fast_path and deferred_builtin_call_hook) {
                    try self.pushBuiltinCFrame(callee_val);
                    const cf_idx = self.activeBytecodeThread().call_frames.len() - 1;
                    // pushBuiltinCFrame may have reallocated bc_stack —
                    // re-derive the caller-window slices (the C-frame's
                    // func_slot sits above the window, which is unchanged).
                    ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                    rargs_fresh = ctx.regs[a + 1 .. a + 1 + effective_nargs];
                    outs = ctx.regs[outs_start .. outs_start + out_len];
                    const hook_args = rargs_fresh;
                    self.dispatchCCalleeActivationHook(cf_idx, callee_val, hook_args) catch |hook_err| {
                        self.popBuiltinCFrame();
                        return hook_err;
                    };
                    self.builtin_cframe_pre_pushed = true;
                }
                // P16.5b: Use the direct call (no C-frame) for the coroutine
                // fast path; generic callBuiltin for everything else.
                if (co_fast_path) {
                    self.callCoroutineBuiltinDirect(id, rargs_fresh, outs) catch |call_err| switch (call_err) {
                        error.Yield => {
                            if (self.canParkDirectBytecodeYield(ctx.boundary_depth, id)) {
                                const th = self.current_thread.?;
                                const fr_y2 = ctx.exec_frames.getPtr(ctx.frame_index);
                                var resumed2 = false;
                                self.parkDirectBytecodeYield(
                                    th,
                                    ctx.pc,
                                    &fr_y2.u.lua.resume_pc,
                                    &resumed2,
                                    ctx.boundary_depth,
                                );
                                if (resumed2) fr_y2.setHookYield();
                                ctx.yielded_in_place.* = true;
                            }
                            return error.Yield;
                        },
                        error.OutOfMemory => return error.OutOfMemory,
                        error.RuntimeError => return error.RuntimeError,
                        error.ThreadSwitch => return error.ThreadSwitch,
                    };
                } else {
                    self.callBuiltin(id, rargs_fresh, outs) catch |call_err| switch (call_err) {
                        error.Yield => {
                            if (self.canParkDirectBytecodeYield(ctx.boundary_depth, id)) {
                                const th = self.current_thread.?;
                                const fr_y2 = ctx.exec_frames.getPtr(ctx.frame_index);
                                // P15.51l: resumed_direct_yield is a CIST_HOOKYIELD
                                // flag bit, not a bool field. Use a local and set
                                // the flag after parkDirectBytecodeYield.
                                var resumed2 = false;
                                self.parkDirectBytecodeYield(
                                    th,
                                    ctx.pc,
                                    &fr_y2.u.lua.resume_pc,
                                    &resumed2,
                                    ctx.boundary_depth,
                                );
                                if (resumed2) fr_y2.setHookYield();
                                ctx.yielded_in_place.* = true;
                            }
                            return error.Yield;
                        },
                        error.OutOfMemory => return error.OutOfMemory,
                        error.RuntimeError => return error.RuntimeError,
                        error.ThreadSwitch => return error.ThreadSwitch,
                    };
                }
                ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                outs = ctx.regs[outs_start .. outs_start + out_len];
                const produced: usize = if (builtinHasDynamicOutCount(id))
                    @min(self.last_builtin_out_count, outs.len)
                else
                    out_len;
                if (try self.tryPushBytecodeDebugHook(
                    ctx.exec_frames,
                    ctx.frame_index,
                    "return",
                    null,
                    callee_val,
                    outs[0..produced],
                    1,
                    .{ .store_results = .{
                        .continuation = .{ .dst = a, .nresults = nresults },
                        .values = outs[0..produced],
                    } },
                )) {
                    const pc2_idx = ctx.exec_frames.getPtr(ctx.frame_index).pending_call_index;
                    if (self.getPendingCallPtr(pc2_idx)) |pending| {
                        if (pending.completion == .hook and pending.completion.hook.post == .store_results) {
                            const old_values = pending.completion.hook.post.store_results.values;
                            if (self.returnSliceIsOwned(old_values)) {
                                // Already scratch-owned, no free needed
                            } else if (@intFromPtr(old_values.ptr) >= @intFromPtr(self.bc_stack.ptr) and
                                @intFromPtr(old_values.ptr) < @intFromPtr(self.bc_stack.ptr) + self.bc_stack.len * @sizeOf(Value))
                            {
                                const owned = try self.alloc.dupe(Value, old_values);
                                pending.completion.hook.post.store_results.values = owned;
                            }
                        }
                    }
                    return .continue_frame_loop;
                }
                try self.dispatchBytecodeHookWithCallee("return", callee_val, outs[0..produced]);
                const nstore: usize = if (nresults >= 0) @intCast(nresults) else produced;
                for (0..nstore) |i| {
                    ctx.regs[a + i] = if (i < produced) outs[i] else .Nil;
                }
                if (nresults < 0) ctx.exec_frames.getPtr(ctx.frame_index).reg_top = @intCast(@as(usize, a) + produced);
                try self.condGcFromDispatch(ctx);
            },
            .Closure => |cl| {
                if (cl.proto) |proto2| {
                    // PUC-faithful: result contract is in callee's callstatus
                    // (CIST_NRESULTS) and func_slot (dst derivation). No
                    // pending_call needed for ordinary Lua CALL.
                    // Staged-ABI activation: callee at R[A] (possibly the
                    // __call-resolved value), args at R[A+1..] in place.
                    try self.pushStagedBytecodeExecFrame(ctx.exec_frames, proto2, ctx.base + a, effective_nargs, nresults);
                    // CALL hook on the callee activation (PUC luaD_hookcall:
                    // the new ci exists, then the hook fires). rargs may be
                    // stale after the push (bc_stack realloc) — the helper
                    // re-derives the transfer slice from the new frame.
                    if (deferred_call_hook) {
                        try self.dispatchCalleeActivationHook(ctx.exec_frames, resolved_callee, effective_nargs);
                    }
                    return .continue_frame_loop;
                }

                // IR closure: host-recursion via runClosure. (Frozen IR
                // closures are equivalent to PUC's C-function calls — they
                // cross the C/Lua boundary and DO use host recursion.)
                try self.setPendingCall(ctx.exec_frames.getPtr(ctx.frame_index), .{
                    .callee = callee_val,
                    .completion = .{ .results = .{
                        .dst = a,
                        .nresults = nresults,
                    } },
                });
                const ret = self.runClosure(cl, rargs) catch |call_err| switch (call_err) {
                    error.Yield => {
                        if (ctx.boundary_depth == 0) {
                            if (self.current_thread) |th| {
                                th.bytecode_inplace_suspended = true;
                                ctx.yielded_in_place.* = true;
                            }
                        }
                        return error.Yield;
                    },
                    else => {
                        self.clearPendingCall(ctx.exec_frames.getPtr(ctx.frame_index));
                        return call_err;
                    },
                };
                self.clearPendingCall(ctx.exec_frames.getPtr(ctx.frame_index));
                var ret_owned = true;
                errdefer if (ret_owned) self.alloc.free(ret);
                if (try self.tryPushBytecodeDebugHook(
                    ctx.exec_frames,
                    ctx.frame_index,
                    "return",
                    null,
                    callee_val,
                    ret,
                    1,
                    .{ .store_results = .{
                        .continuation = .{ .dst = a, .nresults = nresults },
                        .values = ret,
                    } },
                )) {
                    ret_owned = false;
                    return .continue_frame_loop;
                }
                try self.dispatchBytecodeHookWithCallee("return", callee_val, ret);
                const nstore: usize = if (nresults >= 0) @intCast(nresults) else ret.len;
                try self.growCtxFrame(ctx, a + nstore);
                for (0..nstore) |i| {
                    ctx.regs[a + i] = if (i < ret.len) ret[i] else .Nil;
                }
                if (nresults < 0) ctx.exec_frames.getPtr(ctx.frame_index).reg_top = @intCast(@as(usize, a) + ret.len);
                self.alloc.free(ret);
                _ = &ret_owned;
            },
            else => unreachable,
        }
        return .continue_dispatch;
    }

    /// Direct string concatenation — all values must be String/Int/Num.
    fn concatValuesDirect(self: *Vm, vals: []Value) DispatchError!Value {
        if (vals.len == 0) return .{ .String = try self.internLiteral("") };
        if (vals.len == 1) return vals[0];

        // Convert all values to strings and compute total length.
        var bufs: [16][]const u8 = undefined;
        var heap_bufs: ?std.ArrayListUnmanaged([]const u8) = null;
        defer if (heap_bufs) |*hb| {
            for (hb.items) |b| self.alloc.free(b);
            hb.deinit(self.alloc);
        };
        var total: usize = 0;
        for (vals, 0..) |v, i| {
            const s = switch (v) {
                .String => |ls| ls.bytes(),
                .Int => blk: {
                    var buf: [32]u8 = undefined;
                    const s = std.fmt.bufPrint(&buf, "{d}", .{v.Int}) catch unreachable;
                    const owned = try self.alloc.dupe(u8, s);
                    if (heap_bufs == null) heap_bufs = .empty;
                    try heap_bufs.?.append(self.alloc, owned);
                    break :blk owned;
                },
                .Num => blk: {
                    const owned = try self.numberToStringAlloc(v.Num);
                    if (heap_bufs == null) heap_bufs = .empty;
                    try heap_bufs.?.append(self.alloc, owned);
                    break :blk owned;
                },
                else => return self.fail("attempt to concatenate a {s} value", .{v.typeName()}),
            };
            if (i < bufs.len) bufs[i] = s;
            total += s.len;
        }

        // Build result. PUC luaV_concat fills a temporary buffer, then
        // luaS_createlngstrobj COPIES it into the final string object and the
        // temporary is released. The temporary must be freed on BOTH intern
        // outcomes: a hit returns the existing canonical string (this buffer
        // is then garbage), a miss copies the bytes into a new LuaString.
        // Leaking it here turned accumulator-style `s = s .. x` loops into
        // quadratic memory blowups (found via systemd-oomd kills).
        var result = try self.alloc.alloc(u8, total);
        defer self.alloc.free(result);
        var pos: usize = 0;
        for (vals, 0..) |v, i| {
            const s = if (i < bufs.len) bufs[i] else switch (v) {
                .String => |ls| ls.bytes(),
                else => unreachable,
            };
            @memcpy(result[pos..][0..s.len], s);
            pos += s.len;
        }

        return .{ .String = try self.internStr(result) };
    }

    // Intern `raw` and return the canonical *LuaString. ALL string-creating
    // sites must go through here so two equal-content strings share one
    // pointer (then string equality is pointer comparison). Seed from the
    // per-VM RNG so the cached hash is randomized (matches PUC Lua's
    // random-seed string hashing).
    pub fn internStr(self: *Vm, raw: []const u8) std.mem.Allocator.Error!*LuaString {
        // PUC luaS_hash uses g->seed — fixed for the state's lifetime and
        // never mutated (math.random runs on a separate RNG). Using a live
        // RNG word here would re-hash the same content differently after
        // math.random/math.randomseed calls, breaking intern-table lookups
        // for strings interned earlier. The VM-wide `hash_seed` (also used
        // for table keys) is the stable equivalent.
        const seed = self.hash_seed;
        var h = std.hash.Wyhash.init(seed);
        h.update(raw);
        const hash = h.final();
        // Short strings are interned (dedup => pointer identity) in the
        // string_intern table, matching PUC's internshrstr.
        // Long strings are allocated fresh every time, matching PUC
        // luaS_createlngstrobj (not interned).
        if (raw.len <= lua_string_max_short_len) {
            if (self.string_intern.lookup(raw, hash)) |existing| {
                // PUC internshrstr (lstring.c:223-226): a dead-but-not-yet-
                // swept string found in the table is resurrected (changewhite)
                // instead of re-creating an identical copy.
                if (gcIsDead(existing.gc_marked, self.gc_current_white)) {
                    existing.gc_marked = self.gc_current_white & WHITEBITS;
                }
                return existing;
            }
            const ls = try createLuaString(self.alloc, raw, hash);
            // PUC luaC_newobj: set current=white on all new objects.
            ls.gc_marked = self.gc_current_white & WHITEBITS;
            if (self.gc_mode == .generational and self.gc_gen_phase == .minor) ls.gc_age = .old;
            try self.string_intern.insert(self.alloc, ls);
            // Register in gc_objects (PUC allgc) so the normal per-object
            // incremental sweep handles short string collection. This is the
            // PUC-faithful approach: PUC keeps all short strings in allgc.
            try self.gcRegisterString(ls);
            // PUC sizestrshr/luaS_sizelngstr(LSTRREG) include the NUL;
            // T7: single per-kind rule via allocatedSize().
            self.gcNoteAlloc(ls.allocatedSize());
            self.testcNoteMemory(ls.allocatedSize() + 24);
            self.testc_obj_strings += 1;
            return ls;
        }
        const ls = try createLuaString(self.alloc, raw, hash);
        try self.gcRegisterString(ls);
        self.gcNoteAlloc(ls.allocatedSize());
        self.testcNoteMemory(ls.allocatedSize() + 24);
        self.testc_obj_strings += 1;
        return ls;
    }

    /// Create an external LuaString (PUC 5.5 `lua_pushexternalstring` /
    /// `luaS_newextlstr` with `LSTRMEM`). The content at `content[0..len]` is
    /// NOT copied — it must remain valid until the dealloc callback `falloc`
    /// is invoked during GC of this string. The LuaString header itself is a
    /// normal GC-managed allocation (freed by `destroyLuaString` after the
    /// callback runs).
    ///
    /// PUC always creates external strings as `LUA_VLNGSTR` (long), regardless
    /// of actual length — they are never interned. Equality between two
    /// external strings (or an external and a regular long string) is by
    /// content, handled by `luaStringEq` via the non-`short`-kind path.
    ///
    /// The hash is computed with the same per-VM seed as `internStr` so that
    /// table-key lookups involving an external string are consistent with the
    /// interned-string hash space.
    ///
    /// `falloc` has the PUC `lua_Alloc` signature and is called as
    /// `falloc(ud, content, len+1, 0)` when the string is collected. If
    /// `falloc` is null, the string is "fixed" (PUC `LSTRFIX`) — the content
    /// is assumed to be static and no dealloc runs.
    pub fn createExternalLuaString(
        self: *Vm,
        content: [*]const u8,
        len: usize,
        falloc: ?*const fn (?*anyopaque, ?*anyopaque, usize, usize) callconv(.c) ?*anyopaque,
        ud: ?*anyopaque,
    ) std.mem.Allocator.Error!*LuaString {
        // PUC luaS_hash uses g->seed — fixed for the state's lifetime and
        // never mutated (math.random runs on a separate RNG). Using a live
        // RNG word here would re-hash the same content differently after
        // math.random/math.randomseed calls, breaking intern-table lookups
        // for strings interned earlier. The VM-wide `hash_seed` (also used
        // for table keys) is the stable equivalent.
        const seed = self.hash_seed;
        var h = std.hash.Wyhash.init(seed);
        h.update(content[0..len]);
        // PUC lstring.c:327-330: if header creation fails (OOM), the caller has
        // already transferred ownership of the external content to Lua, so Lua
        // must give it back by invoking falloc before propagating the error.
        // Without this, the external memory is silently leaked on allocation
        // failure.
        // PUC luaS_newextlstr (lstring.c:308-332) allocates PER KIND:
        //   LSTRFIX (falloc==null) → luaS_sizelngstr(0, LSTRFIX) = truncated
        //     header (offsetof(TString, falloc) = 32 B) and only writes
        //     contents/lnglen/hash — never touches falloc/ud;
        //   LSTRMEM → full sizeof(TString) header, writes falloc/ud too.
        // We mirror both the truncated size and the field-wise writes: on a
        // 32-B allocation, a whole-struct `ls.* = .{...}` assign would write
        // `meta.external` (24 B, up to offset 48) out of bounds.
        const fixed = falloc == null;
        const header_size: usize =
            if (fixed) LuaString.lstrfix_header_size else @sizeOf(LuaString);
        const buf = self.alloc.alignedAlloc(
            u8,
            std.mem.Alignment.fromByteUnits(@alignOf(LuaString)),
            header_size,
        ) catch |e| {
            // PUC lstring.c:327-330: if header creation fails (OOM), the
            // caller has already transferred ownership of the external
            // content to Lua, so Lua must give it back by invoking falloc
            // before propagating the error. Without this, the external
            // memory is silently leaked on allocation failure.
            if (falloc) |fa| {
                _ = fa(ud, @ptrCast(@constCast(content)), len + 1, 0);
            }
            return e;
        };
        const ls: *LuaString = @ptrCast(@alignCast(buf.ptr));
        // If GC registration fails after the header was allocated, free both
        // the header and the external content (same ownership-transfer logic).
        errdefer {
            if (falloc) |fa| {
                _ = fa(ud, @ptrCast(@constCast(content)), len + 1, 0);
            }
            self.alloc.free(buf);
        }
        // Field-wise init: every write below stays within `header_size`
        // (for LSTRFIX that is 32 B — writing the whole struct would run
        // past the allocation).
        ls.hash = h.final();
        ls.u.lnglen = len;
        // External strings are always "long" (PUC VLNGSTR), never interned.
        // PUC shrlen encodes the kind: LSTRFIX -2 / LSTRMEM -3.
        ls.srkind = if (fixed) LuaString.lstrfix else LuaString.lstrmem;
        ls.gc_marked = 0;
        ls.gc_age = .new;
        ls.gc_index = 0;
        ls._pad = 0;
        ls.c = .{ .extptr = content }; // offset 24 — inside the LSTRFIX prefix
        if (!fixed) {
            // LSTRMEM only: falloc/ud live past the LSTRFIX prefix (offsets
            // 32/40), so these writes are legal ONLY on the full-header
            // allocation.
            ls.falloc = falloc;
            ls.ud = ud;
        }
        try self.gcRegisterString(ls);
        // Only the header is owned by the GC; the external content is accounted
        // for by the caller (and released via `falloc` for LSTRMEM).
        self.gcNoteAlloc(header_size);
        self.testcNoteMemory(header_size);
        self.testc_obj_strings += 1;
        return ls;
    }

    /// Like internStr, but also deduplicates long strings. Used for
    /// bytecode constant pool loads where PUC Lua shares long string
    /// constants across functions in the same chunk.
    ///
    /// P15.35 fix: the cache key must point into the long-lived interned
    /// LuaString's body (which is owned by the VM and never freed while the
    /// cache holds it), NOT into the caller's borrowed `raw` slice. The
    /// previous implementation stored `raw` as the key — but `resolveProtoConstants`
    /// frees the source LuaString right after this call, leaving the cache key
    /// dangling. On the next grow/rehash, the map compared keys through freed
    /// memory, corrupting the table and tripping `assert(!containsContext(...))`.
    fn internStrAll(self: *Vm, raw: []const u8) std.mem.Allocator.Error!*LuaString {
        if (raw.len <= lua_string_max_short_len) return self.internStr(raw);
        // For long strings, deduplicate via a separate cache so identical
        // constants share pointer identity (matching PUC's constant pool sharing).
        if (self.long_string_cache.get(raw)) |existing| return existing;
        const ls = try self.internStr(raw);
        // Store ls.bytes() as the key — it points into the interned LuaString's
        // inline body, which is stable for the string's lifetime (GC-managed,
        // rooted via long_string_cache itself in gcMarkMutableRoots).
        try self.long_string_cache.put(self.alloc, ls.bytes(), ls);
        return ls;
    }

    // Intern a string LITERAL (loaded from source via ConstString / bytecode
    // const pool). Short literals go through the global short-string intern
    // table (so a short literal and a short runtime string with the same content
    // share a pointer, as in PUC). Long literals are deduped by content in a
    // separate table — they share a pointer with equal long literals but NOT
    // with equal long runtime strings. Mirrors PUC's compile-time constant
    // folding (luaK_stringK), which dedups literals per Proto regardless of
    // length; we dedup globally (observable only via %p across functions).
    pub fn internLiteral(self: *Vm, raw: []const u8) std.mem.Allocator.Error!*LuaString {
        if (raw.len <= lua_string_max_short_len) return self.internStr(raw);
        if (self.long_literals.table.get(raw)) |existing| {
            if (self.gc_mode == .generational and self.gc_gen_phase == .minor) existing.gc_age = .old;
            return existing;
        }
        // PUC luaS_hash uses g->seed — fixed for the state's lifetime and
        // never mutated (math.random runs on a separate RNG). Using a live
        // RNG word here would re-hash the same content differently after
        // math.random/math.randomseed calls, breaking intern-table lookups
        // for strings interned earlier. The VM-wide `hash_seed` (also used
        // for table keys) is the stable equivalent.
        const seed = self.hash_seed;
        var h = std.hash.Wyhash.init(seed);
        h.update(raw);
        const ls = try createLuaString(self.alloc, raw, h.final());
        if (self.gc_mode == .generational and self.gc_gen_phase == .minor) ls.gc_age = .old;
        try self.long_literals.table.put(self.alloc, ls.bytes(), ls);
        self.testcNoteMemory(@sizeOf(LuaString) + raw.len + 24);
        self.testc_obj_strings += 1;
        return ls;
    }

    // Intern `raw` from a context that cannot propagate errors (a `void` or
    // bare-`Value` returning function, e.g. the OOM-error setter or a global
    // accessor). These sites only ever feed short constant strings or
    // already-interned messages, so on the rare first-time allocation we
    // abort — exactly what `Vm.init` does for its own allocations. This keeps
    // the call sites free of `try` without introducing a parallel interning
    // path: it routes through `internStr`, so dedup/pointer-identity still hold.
    fn internStrAssume(self: *Vm, raw: []const u8) *LuaString {
        return self.internStr(raw) catch @panic("luazig: oom interning constant string");
    }

    fn expectTable(self: *Vm, v: Value) DispatchError!*Table {
        return switch (v) {
            .Table => |t| t,
            else => self.fail("type error: expected table, got {s}", .{v.typeName()}),
        };
    }

    fn expectThread(self: *Vm, v: Value) DispatchError!*Thread {
        return switch (v) {
            .Thread => |t| t,
            else => self.fail("type error: expected thread, got {s}", .{v.typeName()}),
        };
    }

    fn getGlobal(self: *Vm, name: []const u8) Value {
        if (std.mem.eql(u8, name, "_G")) return .{ .Table = self.global_env };
        if (std.mem.eql(u8, name, "_ENV")) return .{ .Table = self.global_env };
        const v = self.getField(self.global_env, name);
        if (v != .Nil) return v;
        if (std.mem.eql(u8, name, "_VERSION")) return .{ .String = self.internStrAssume("Lua 5.5") };
        return .Nil;
    }

    fn setGlobal(self: *Vm, name: []const u8, v: Value) DispatchError!void {
        // Writing Nil removes the entry (rawSet semantics); no separate dup of
        // the name is needed — the key lives inside the interned LuaString.
        try self.setField(self.global_env, name, v);
    }

    fn errorLocationFrameIndex(self: *const Vm, level: usize) ?*const CallFrame {
        // PUC luaL_where(L, level): calls lua_getstack(L, level) to find the
        // frame at `level`, then checks ar.currentline. lua_getstack starts
        // from L->ci (current frame = error's C-frame) and goes `level` frames
        // up, counting ALL frames (CIST_C and Lua).
        //
        // P15.79: Hidden C-frames from testC (C API functions) are counted
        // — PUC pushes C-frames for C API functions. We identify testC
        // C-frames by checking if bc_stack[func_slot] is a Builtin with
        // value .testC (the testC builtin). Hidden C-frames from other
        // builtins (pcall, table.sort, etc.) are skipped — PUC doesn't
        // push C-frames for these.
        const isTestcCFrame = struct {
            fn check(vm: *const Vm, fr: *const CallFrame) bool {
                if (!fr.isC()) return false;
                if (fr.func_slot >= vm.bc_stack.len) return false;
                return vm.bc_stack[fr.func_slot] == .Builtin and
                    vm.bc_stack[fr.func_slot].Builtin == .testc_testC;
            }
        }.check;
        if (level == 0) return null;
        var remaining = level;

        const bc_count = self.activeBytecodeThreadConst().call_frames.len();
        const lua_top = bc_count;
        var protected_index = self.protected_c_frame_count;

        while (protected_index != 0) {
            protected_index -= 1;
            const boundary = @min(self.protected_c_frame_depths[protected_index], lua_top);
            // Count visible frames + testC C-frames (hidden but identified
            // as testC C-frames). Hidden builtin C-frames (pcall, etc.) are
            // transparent — PUC doesn't push C-frames for builtins.
            var visible_count: usize = 0;
            var idx = lua_top;
            while (idx > boundary) {
                idx -= 1;
                const fr = self.activeBytecodeThreadConst().call_frames.getConstPtr(idx);
                if (!fr.isHidden() or isTestcCFrame(self, fr)) {
                    visible_count += 1;
                }
            }
            if (remaining <= visible_count) {
                var rem = remaining;
                var i = lua_top;
                while (i > boundary) {
                    i -= 1;
                    const fr = self.activeBytecodeThreadConst().call_frames.getConstPtr(i);
                    if (fr.isHidden() and !isTestcCFrame(self, fr)) continue;
                    rem -= 1;
                    if (rem == 0) return fr;
                }
                return null;
            }
            remaining -= visible_count;

            if (remaining == 1) return null;
            remaining -= 1;
        }

        var rem = remaining;
        var i = lua_top;
        while (i > 0) {
            i -= 1;
            const fr = self.activeBytecodeThreadConst().call_frames.getConstPtr(i);
            if (fr.isHidden() and !isTestcCFrame(self, fr)) continue;
            rem -= 1;
            if (rem == 0) return fr;
        }
        return null;
    }

    /// Find the topmost Lua frame on the active thread's call_frames stack.
    /// Used by fail()/failC() and other error-path code that needs to access
    /// u.lua fields (pc, sourceName, frameCurrentLine). C-frames don't have
    /// u.lua fields, so we skip them. Returns null if there are no Lua frames.
    fn topLuaFrame(self: *Vm) ?*CallFrame {
        const th = self.activeBytecodeThread();
        var i = th.call_frames.len();
        while (i != 0) {
            i -= 1;
            const fr = th.call_frames.getPtr(i);
            if (fr.isLua()) return fr;
        }
        return null;
    }

    /// Const variant of topLuaFrame for use in const methods.
    fn topLuaFrameConst(self: *const Vm) ?*const CallFrame {
        const th = self.activeBytecodeThreadConst();
        var i = th.call_frames.len();
        while (i != 0) {
            i -= 1;
            const fr = th.call_frames.getConstPtr(i);
            if (fr.isLua()) return fr;
        }
        return null;
    }

    /// Resolve a combined 0-based index (from bottom) to a *const CallFrame
    /// pointer. Only bytecode frames exist (in Thread.call_frames).
    fn frameAtCombinedIndex(self: *const Vm, combined_index: usize, bc_count: usize) ?*const CallFrame {
        if (combined_index < bc_count) {
            return self.activeBytecodeThreadConst().call_frames.getConstPtr(combined_index);
        }
        return null;
    }

    /// Const variant of activeBytecodeThread for use in const methods.
    fn activeBytecodeThreadConst(self: *const Vm) *const Thread {
        return self.current_thread orelse self.main_thread.?;
    }

    fn enterProtectedCFrame(self: *Vm) void {
        std.debug.assert(self.protected_c_frame_count < self.protected_c_frame_depths.len);
        // Record the bytecode Lua frame depth so errorLocationFrameIndex can
        // walk the frame stack correctly.
        const bc_count = self.activeBytecodeThread().call_frames.len();
        self.protected_c_frame_depths[self.protected_c_frame_count] = bc_count;
        self.protected_c_frame_count += 1;
    }

    fn leaveProtectedCFrame(self: *Vm) void {
        std.debug.assert(self.protected_c_frame_count != 0);
        self.protected_c_frame_count -= 1;
    }

    /// P15.38i: Re-derive the builtin outs slice from bc_stack after a nested
    /// Lua call that may have triggered bc_stack realloc. Only valid when
    /// builtin_outs_on_bc_stack is true (set by callBuiltin when outs points
    /// into bc_stack). Returns null when outs is not on bc_stack (internal
    /// callers that pass local buffers). Mirrors PUC Lua's restorestack macro.
    fn refreshBuiltinOuts(self: *Vm) ?[]Value {
        if (!self.builtin_outs_on_bc_stack) return null;
        return self.bc_stack[self.builtin_outs_base .. self.builtin_outs_base + self.builtin_outs_len];
    }

    fn callBuiltin(self: *Vm, id: BuiltinId, args: []const Value, outs: []Value) DispatchError!void {
        if (self.stats.enabled) self.stats.calls_builtin += 1; // P16.0b
        // P15.38i: Track whether outs points into bc_stack. When true, builtins
        // with re-entry (pcall, xpcall, tostring with __tostring, etc.) can
        // re-derive their outs slice via refreshBuiltinOuts() after nested Lua
        // calls that may realloc bc_stack. This mirrors PUC Lua's
        // savestack/restorestack mechanism (ldo.c:277-282).
        const outs_ptr = @intFromPtr(outs.ptr);
        const bc_start = @intFromPtr(self.bc_stack.ptr);
        const bc_end = bc_start + self.bc_stack.len * @sizeOf(Value);
        const prev_on_bc = self.builtin_outs_on_bc_stack;
        const prev_base = self.builtin_outs_base;
        const prev_len = self.builtin_outs_len;
        if (outs_ptr >= bc_start and outs_ptr < bc_end) {
            self.builtin_outs_on_bc_stack = true;
            self.builtin_outs_base = (outs_ptr - bc_start) / @sizeOf(Value);
            self.builtin_outs_len = outs.len;
        } else {
            self.builtin_outs_on_bc_stack = false;
        }
        defer {
            self.builtin_outs_on_bc_stack = prev_on_bc;
            self.builtin_outs_base = prev_base;
            self.builtin_outs_len = prev_len;
        }

        // P15.79: Track whether args points into bc_stack. pushBuiltinCFrame
        // may reallocate bc_stack (growing it to fit the C-frame's func_slot),
        // which invalidates any []const Value slice that points into the old
        // allocation. Save the offset now; after pushBuiltinCFrame, re-derive
        // args from the new bc_stack if it was on bc_stack. If args is from a
        // different allocation (e.g. resolveCallable's owned_args), it's safe.
        const args_ptr = @intFromPtr(args.ptr);
        const args_on_bc = args_ptr >= bc_start and args_ptr < bc_end;
        const args_base = if (args_on_bc) (args_ptr - bc_start) / @sizeOf(Value) else 0;

        const callee_val: Value = .{ .Builtin = id };
        // P15.83r: the OP_CALL/OP_TAILCALL/OP_TFORCALL dispatch sites may
        // have already pushed this builtin's C-frame so the CALL hook could
        // fire on the C activation (PUC precallC ordering). Consume the flag
        // (exactly one callBuiltin entry per push) and REUSE that frame —
        // exactly one C-frame per builtin invocation, whoever pushed it.
        const cframe_pre_pushed = self.builtin_cframe_pre_pushed;
        self.builtin_cframe_pre_pushed = false;
        const cframe_pushed = cframe_pre_pushed or (id != .collectgarbage and id != .string_sub);
        if (!cframe_pre_pushed and cframe_pushed) try self.pushBuiltinCFrame(callee_val);
        // Re-derive args from the (possibly reallocated) bc_stack.
        const args_fresh: []const Value = if (args_on_bc)
            self.bc_stack[args_base .. args_base + args.len]
        else
            args;
        // Re-derive outs from the (possibly reallocated) bc_stack.
        const outs_fresh: []Value = if (self.builtin_outs_on_bc_stack)
            self.bc_stack[self.builtin_outs_base .. self.builtin_outs_base + self.builtin_outs_len]
        else
            outs;
        var cframe_preserved = false;
        defer if (cframe_pushed and !cframe_preserved) self.popBuiltinCFrame();

        // P15.38i: Helper for builtins with re-entry. After a nested Lua call
        // that may realloc bc_stack, call this to get a fresh outs slice.
        // Usage: const outs = self.refreshBuiltinOuts();

        // Initialize outputs to nil.
        for (outs_fresh) |*o| o.* = .Nil;
        self.last_builtin_out_count = outs_fresh.len;
        const prev_active_builtin = self.active_builtin;
        const prev_active_builtin_args = self.active_builtin_args;
        self.active_builtin = id;
        self.active_builtin_args = args_fresh;
        defer {
            self.active_builtin = prev_active_builtin;
            self.active_builtin_args = prev_active_builtin_args;
        }
        self.callBuiltinSwitch(id, args_fresh, outs_fresh) catch |err| {
            if (err == error.Yield or err == error.ThreadSwitch) {
                cframe_preserved = true;
            } else if (err == error.RuntimeError) {
                // P15.82e: Mirror callCFunction's CIST_YPCALL guard (see its
                // `nret_signed < 0` branch): if the TOP C-frame has
                // CIST_YPCALL (a yieldable pcall in progress — either this
                // builtin's own frame marked by builtinPcall/testC-pcallk
                // following PUC lua_pcallk which sets the flag on L->ci, or
                // a pcallk C-frame pushed above), the frame MUST survive so
                // precover → finishCcall → finishpcallk → k can perform
                // error recovery. The defer pops the TOP frame; without this
                // guard it would destroy the recovery frame and the error
                // would escape the coroutine uncaught.
                const cur_th = self.activeBytecodeThread();
                if (cur_th.call_frames.len() > 0) {
                    const cur_fr = cur_th.call_frames.getConstPtr(cur_th.call_frames.len() - 1);
                    if (cur_fr.isC() and cur_fr.isYpcall()) {
                        cframe_preserved = true;
                    }
                }
            }
            return err;
        };
    }

    fn callBuiltinSwitch(self: *Vm, id: BuiltinId, args: []const Value, outs: []Value) DispatchError!void {
        switch (id) {
            .print => try self.builtinPrint(args),
            .warn => try self.builtinWarn(args, outs),
            .tostring => {
                if (outs.len == 0) return;
                if (args.len == 0) return self.fail("bad argument #1 to 'tostring' (value expected)", .{});
                if (self.getMetaFieldByObj(args[0], .tostring)) |mm| {
                    var call_args = [_]Value{args[0]};
                    const v = try self.callMetamethod(mm, "__tostring", call_args[0..]);
                    if (v != .String) return self.fail("'__tostring' must return a string", .{});
                    // P15.38i: Re-derive outs — callMetamethod may trigger realloc.
                    const outs_fresh = self.refreshBuiltinOuts() orelse outs;
                    outs_fresh[0] = v;
                } else {
                    // P15.38h: Use stack-buffer fast path for Int/Num to avoid
                    // heap allocation (PUC luaO_tostring model).
                    outs[0] = .{ .String = try self.valueToInternedStr(args[0]) };
                }
            },
            .tonumber => try self.builtinTonumber(args, outs),
            .rawlen => try self.builtinRawlen(args, outs),
            .rawequal => try self.builtinRawequal(args, outs),
            .@"error" => {
                // Fresh error: reset LUA_ERRERR signal before invokeErrfunc.
                self.err_is_errerr = false;
                // P15.83q: fresh raise — no C-frame residue yet (only the
                // string-prefix path below can set one).
                self.err_cframe_residue = null;
                if (args.len == 0 or args[0] == .Nil) {
                    self.err = null;
                    self.err_obj = .Nil;
                    self.err_has_obj = false;
                    self.err_source = null;
                    self.err_line = -1;
                    self.clearErrorTraceback();
                    return error.RuntimeError;
                }
                const msg = switch (args[0]) {
                    .String => |s| s.bytes(),
                    else => "",
                };
                const level: i64 = if (args.len >= 2) switch (args[1]) {
                    .Int => |i| i,
                    .Num => |n| @intFromFloat(n),
                    else => 1,
                } else 1;
                // PUC luaL_where(L, level): calls lua_getstack(L, level) to
                // find the frame at `level`, then checks ar.currentline.
                // For C functions (currentline = -1), luaL_where pushes ""
                // (no source prefix). For Lua functions (currentline > 0),
                // it pushes "source:line: ".
                //
                // P15.79: The former caller_builtin_id field (used to detect
                // C-function callers for source-prefix suppression) has been
                // removed entirely. Now that builtin C-frames are pushed
                // (hidden) for all builtins, errorLocationFrameIndex correctly
                // skips hidden C-frames and finds the Lua frame at the requested
                // level. The old caller_builtin_id check was wrong: when a
                // builtin (like table.sort) calls a Lua callback that calls
                // error(), caller_builtin_id was set to table.sort, causing
                // error() to suppress the source prefix — even though the
                // actual caller of error() is the Lua callback, not table.sort.
                const location_frame = if (args[0] == .String and level > 0)
                    self.errorLocationFrameIndex(@intCast(level))
                else
                    null;
                // P15.83q: PUC luaB_error builds `where .. msg` by pushing
                // luaL_where + a COPY of the argument on the error() C-frame
                // and concatenating — the ORIGINAL string stays on the frame
                // below the built message, for ANY level >= 1 string error
                // (even when the prefix ends up empty). Transcribe it as the
                // C-frame residue exposed at the lua_resume error boundary:
                // [orig, msg, msg] (luaD_seterrorobj adds the dup).
                if (args[0] == .String and level > 0)
                    self.err_cframe_residue = args[0];
                if (location_frame) |fr_ptr| {
                    const fr = fr_ptr.*;
                    // P15.51n: current_line derived from proto.lineinfo[pc].
                    const line: i64 = self.frameCurrentLine(fr_ptr);
                    // PUC 5.5 luaL_where: only add source prefix if
                    // currentline > 0. For C functions (currentline = -1),
                    // luaL_where pushes "" (no source info). This matches
                    // PUC behavior where error("msg") from a C function
                    // produces just "msg" (no "=[C]: " prefix).
                    if (line > 0) {
                        const src = fr.sourceName();
                        // PUC luaG_addinfo uses luaO_chunkid for the source name.
                        var id_buf: [59]u8 = undefined;
                        const chunk = diag.chunkId(id_buf[0..], src);
                        var msg_tmp: [256]u8 = undefined;
                        const mlen = @min(msg.len, msg_tmp.len);
                        var mi: usize = 0;
                        while (mi < mlen) : (mi += 1) msg_tmp[mi] = msg[mi];
                        const msg_copy = msg_tmp[0..mlen];
                        self.err = std.fmt.bufPrint(self.err_buf[0..], "{s}:{d}: {s}", .{ chunk, line, msg_copy }) catch blk: {
                            const stable_len = @min(msg_copy.len, self.err_buf.len);
                            @memcpy(self.err_buf[0..stable_len], msg_copy[0..stable_len]);
                            break :blk self.err_buf[0..stable_len];
                        };
                        self.err_obj = .{ .String = try self.internStr(self.err.?) };
                    } else {
                        // C function caller: no source prefix (PUC luaL_where
                        // pushes "" for currentline <= 0).
                        self.err = if (args[0] == .String) msg else null;
                        self.err_obj = args[0];
                    }
                } else {
                    self.err = if (args[0] == .String) msg else null;
                    self.err_obj = args[0];
                }
                self.err_has_obj = true;
                self.err_source = null;
                self.err_line = -1;
                self.err_cfunc_label = "global 'error'";
                // fr.u.lua.pc is already current — no sync needed.
                // Bytecode frames are in Thread.call_frames.
                {
                    const th = self.activeBytecodeThread();
                    if (th.call_frames.len() != 0) {
                        // P15.51n: current_line derived on demand.
                        _ = th.call_frames.getPtr(th.call_frames.len() - 1);
                    }
                }
                // Capture traceback. The error C-frame is not pushed at runtime
                // (it causes stack management issues). Instead, captureErrorTraceback
                // and debugBuildCurrentTraceback synthetically insert
                // [C]: in global 'error' by checking err_cfunc_label.
                self.captureErrorTraceback();
                try self.invokeErrfunc();
                return error.RuntimeError;
            },
            .assert => try self.builtinAssert(args, outs),
            .select => try self.builtinSelect(args, outs),
            .type => try self.builtinType(args, outs),
            .collectgarbage => try self.builtinCollectgarbage(args, outs),
            .pcall => try self.builtinPcall(args, outs),
            .xpcall => try self.builtinXpcall(args, outs),
            .next => try self.builtinNext(args, outs),
            .dofile => try self.builtinDofile(args, outs),
            .loadfile => try self.builtinLoadfile(args, outs),
            .load => try self.builtinLoad(args, outs),
            .require => try self.builtinRequire(args, outs),
            .package_searchpath => try self.builtinPackageSearchpath(args, outs),
            .package_loadlib => try self.builtinPackageLoadlib(args, outs),
            .setmetatable => try self.builtinSetmetatable(args, outs),
            .getmetatable => try self.builtinGetmetatable(args, outs),
            .debug_getinfo => try self.builtinDebugGetinfo(args, outs),
            .debug_getlocal => try self.builtinDebugGetlocal(args, outs),
            .debug_setlocal => try self.builtinDebugSetlocal(args, outs),
            .debug_getupvalue => try self.builtinDebugGetupvalue(args, outs),
            .debug_setupvalue => try self.builtinDebugSetupvalue(args, outs),
            .debug_upvalueid => try self.builtinDebugUpvalueid(args, outs),
            .debug_upvaluejoin => try self.builtinDebugUpvaluejoin(args, outs),
            .debug_gethook => try self.builtinDebugGethook(args, outs),
            .debug_sethook => try self.builtinDebugSethook(args, outs),
            .debug_getregistry => try self.builtinDebugGetregistry(args, outs),
