        const x = try self.mathArgToNum(args[0], "frexp", 1);
        if (x == 0.0) {
            outs[0] = .{ .Num = 0.0 };
            if (outs.len > 1) outs[1] = .{ .Int = 0 };
            return;
        }
        if (!std.math.isFinite(x)) {
            outs[0] = .{ .Num = x };
            if (outs.len > 1) outs[1] = .{ .Int = 0 };
            return;
