            },
            .newmetatable => {
                if (cargs.len != 1) return self.fail("testC newmetatable expects 1 arg", .{});
                const reg = try self.ensureDebugRegistry();
                const k = trimTestcQuoted(cargs[0]);
                if (self.getFieldOpt(reg, k)) |existing| {
                    try st.append(self.alloc, existing);
                    try st.append(self.alloc, .{ .Bool = false });
                } else {
                    const mt = try self.allocTable();
                    try self.setField(reg, k, .{ .Table = mt });
                    try st.append(self.alloc, .{ .Table = mt });
                    try st.append(self.alloc, .{ .Bool = true });
                }
            },
            .testudata => {
                if (cargs.len != 2) return self.fail("testC testudata expects 2 args", .{});
                const idx = try self.parseTestcIndexMaybe(cargs[0], st.items.len);
                const reg = try self.ensureDebugRegistry();
                const key = trimTestcQuoted(cargs[1]);
                const want = self.getFieldOpt(reg, key) orelse .Nil;
                if (idx == null or want != .Table) {
                    try st.append(self.alloc, .Nil);
                    return null;
                }
                const v = st.items[idx.?];
                // Check if the object has the expected metatable.
                // Works for both tables and userdata (real Userdata).
                const has_mt: bool = switch (v) {
                    .Table => |t| t.metatable != null and t.metatable.? == want.Table,
                    .Userdata => |u| u.metatable != null and u.metatable.? == want.Table,
                    else => false,
                };
                if (has_mt) {
                    try st.append(self.alloc, v);
                } else {
                    try st.append(self.alloc, .Nil);
                }
            },
            .gsub => {
                if (cargs.len != 3) return self.fail("testC gsub expects 3 args", .{});
                const sidx = try self.parseTestcIndex(cargs[0], st.items.len);
                const pidx = try self.parseTestcIndex(cargs[1], st.items.len);
                const ridx = try self.parseTestcIndex(cargs[2], st.items.len);
                const src = switch (st.items[sidx]) {
                    .String => |s| s.bytes(),
                    else => return self.fail("testC gsub expects string source", .{}),
                };
                const patt = switch (st.items[pidx]) {
                    .String => |s| s.bytes(),
                    else => return self.fail("testC gsub expects string pattern", .{}),
                };
                const repl = switch (st.items[ridx]) {
                    .String => |s| s.bytes(),
                    else => return self.fail("testC gsub expects string replacement", .{}),
                };
                const replaced = try std.mem.replaceOwned(u8, self.alloc, src, patt, repl);
                try st.append(self.alloc, .{ .String = try self.internStr(replaced) });
            },
            .closeslot => {
                if (cargs.len != 1) return self.fail("testC closeslot expects 1 arg", .{});
                const idx = try self.parseTestcIndex(cargs[0], st.items.len);
                const obj = st.items[idx];
                const th = self.activeBytecodeThread();
                th.incnny();
                defer th.decnny();
                self.runTestcCloseMetamethod(obj, null) catch |e| {
                    st.items[idx] = .Nil;
                    testcUnmark(toclose, idx);
                    return e;
                };
                st.items[idx] = .Nil;
                testcUnmark(toclose, idx);
            },
            .sethook => {
                if (cargs.len < 3) return self.fail("testC sethook expects at least 3 args", .{});
                const mask_bits = std.fmt.parseInt(i64, cargs[0], 10) catch return self.fail("testC invalid hook mask", .{});
                const count = std.fmt.parseInt(i64, cargs[1], 10) catch return self.fail("testC invalid hook count", .{});
                var hook_fn: Value = .Nil;
                const hook_body = cargs[2];
                const t_global = self.getGlobal("T");
                if (t_global != .Table) return self.fail("testC sethook: T table missing", .{});
                const mk = self.getFieldOpt(t_global.Table, "makeCfunc") orelse return self.fail("testC sethook: makeCfunc missing", .{});
                var hook_args = [_]Value{.{ .String = try self.internStr(hook_body) }};
                const ret = try self.apiCall(Thread.CCALL_INC_NOYIELD, mk, hook_args[0..]);
                defer self.alloc.free(ret);
                hook_fn = if (ret.len > 0) ret[0] else .Nil;

                var mask_buf: [3]u8 = undefined;
                var mask_len: usize = 0;
                if ((mask_bits & 1) != 0) {
                    mask_buf[mask_len] = 'c';
                    mask_len += 1;
                }
                if ((mask_bits & 2) != 0) {
                    mask_buf[mask_len] = 'r';
                    mask_len += 1;
                }
                if ((mask_bits & 4) != 0) {
                    mask_buf[mask_len] = 'l';
                    mask_len += 1;
                }
                const mask = mask_buf[0..mask_len];
                var dbg_args: [3]Value = .{
                    hook_fn,
                    .{ .String = try self.internStr(mask) },
                    .{ .Int = count },
                };
                var outv: [1]Value = .{.Nil};
                try self.builtinTestcAllowHookYield(dbg_args[0..], outv[0..]);
            },
            .traceback => {
                if (cargs.len != 2) return self.fail("testC traceback expects 2 args", .{});
                const msg = trimTestcQuoted(cargs[0]);
                const level = std.fmt.parseInt(i64, cargs[1], 10) catch return self.fail("testC invalid traceback level", .{});
                var dbg_args: [2]Value = .{
                    .{ .String = try self.internStr(msg) },
                    .{ .Int = level },
                };
                var outv: [1]Value = .{.Nil};
                try self.builtinDebugTraceback(dbg_args[0..], outv[0..]);
                try st.append(self.alloc, outv[0]);
            },
            .pcall => {
                if (cargs.len != 2 and cargs.len != 3) return self.fail("testC pcall expects 2 or 3 args", .{});
                const nargs = std.fmt.parseInt(usize, cargs[0], 10) catch return self.fail("testC invalid nargs", .{});
                const nresults = std.fmt.parseInt(i32, cargs[1], 10) catch return self.fail("testC invalid nresults", .{});
                if (st.items.len < nargs + 1) return self.fail("testC stack underflow", .{});
                const fn_idx = st.items.len - nargs - 1;
                var call_idx = fn_idx;
                if (!isCallableValue(st.items[call_idx])) {
                    var j = call_idx;
                    while (j > 0) {
                        j -= 1;
                        if (isCallableValue(st.items[j])) {
                            call_idx = j;
                            break;
                        }
                    }
                }
                const callee = st.items[call_idx];
                const call_args = st.items[st.items.len - nargs ..];
                const handler_idx: ?usize = if (cargs.len == 3) blk: {
                    const ei = std.fmt.parseInt(i32, cargs[2], 10) catch break :blk null;
                    if (ei == 0) break :blk null;
                    if (ei > 0) {
                        // ltests 'pcall ... errfunc' uses a relative index around
                        // the callee slot (so `1` can point to handler argument).
                        const rel: usize = @intCast(ei);
                        if (rel > fn_idx) break :blk null;
                        break :blk fn_idx - rel;
                    }
                    break :blk try self.parseTestcIndex(cargs[2], st.items.len);
                } else null;
                const handler_val: ?Value = if (handler_idx) |hi| st.items[hi] else null;
                const mem_before_call = self.testc_total_bytes;
                const obj_tables_before_call = self.testc_obj_tables;
                const obj_functions_before_call = self.testc_obj_functions;
                const obj_threads_before_call = self.testc_obj_threads;
                const obj_strings_before_call = self.testc_obj_strings;
                // PUC luaD_pcall: clear errfunc for the protected child.
                // In testC mode, errfunc might be set from the CLI handler.
                // Clear it so the error message isn't modified by the handler.
                const th_xpcall = self.activeBytecodeThread();
                const saved_errfunc = th_xpcall.errfunc;
                th_xpcall.errfunc = ERRFUNC_NONE;
                defer th_xpcall.errfunc = saved_errfunc;
                const ret = self.apiCall(Thread.CCALL_INC_NOYIELD, callee, call_args) catch {
                    const errv = self.protectedErrorValue();
                    if (isTestcMemoryErrorValue(errv)) {
                        // This VM does not have PUC Lua's real collector yet.
                        // For ltests memory-limit probes, failed protected
                        // calls must not leave partial allocations counted as
                        // live; after the script's collectgarbage() they would
                        // be unreachable in PUC.
                        self.testc_total_bytes = mem_before_call;
                        self.testc_obj_tables = obj_tables_before_call;
                        self.testc_obj_functions = obj_functions_before_call;
                        self.testc_obj_threads = obj_threads_before_call;
                        self.testc_obj_strings = obj_strings_before_call;
                    }
                    // PUC model: the message handler receives the exact
                    // error object — no source-location stripping. The error
                    // object is the exact Lua value from error() or fail().
                    const handler_errv = errv;
                    st.items.len = call_idx;
                    if (handler_val) |h| {
                        var hargs = [_]Value{handler_errv};
                        const hret = self.apiCall(Thread.CCALL_INC_NOYIELD, h, hargs[0..]) catch {
                            try st.append(self.alloc, errv);
                            last_status.* = "ERRRUN";
                            return null;
                        };
                        defer self.alloc.free(hret);
                        if (hret.len > 0) {
                            try st.append(self.alloc, hret[0]);
                        } else {
                            try st.append(self.alloc, .Nil);
                        }
                    } else {
                        try st.append(self.alloc, errv);
                    }
                    last_status.* = if (isTestcMemoryErrorValue(errv))
                        "not enough memory"
                    else
                        "ERRRUN";
                    return null;
                };
                defer self.alloc.free(ret);
                st.items.len = call_idx;
                const want: usize = if (nresults < 0) ret.len else @min(ret.len, @as(usize, @intCast(nresults)));
                try st.appendSlice(self.alloc, ret[0..want]);
                last_status.* = "OK";
            },
            .pcallk => {
                if (cargs.len != 3) return self.fail("testC pcallk expects 3 args", .{});
                const nargs = std.fmt.parseInt(usize, cargs[0], 10) catch return self.fail("testC invalid nargs", .{});
                const nresults = std.fmt.parseInt(i32, cargs[1], 10) catch return self.fail("testC invalid nresults", .{});
                const cont_res = try self.resolveTestcContinuationScript(ctx, st, cargs[2]);
                const cont_script = cont_res.script;
                const ctx_id = cont_res.ctx_id;
                if (st.items.len < nargs + 1) return self.fail("testC stack underflow", .{});
                const fn_idx = st.items.len - nargs - 1;
                var call_idx = fn_idx;
                if (!isCallableValue(st.items[call_idx])) {
                    var j = call_idx;
                    while (j > 0) {
                        j -= 1;
                        if (isCallableValue(st.items[j])) {
                            call_idx = j;
                            break;
                        }
                    }
                }
                const callee = st.items[call_idx];
                const call_args = st.items[st.items.len - nargs ..];
                const prefix_len = call_idx;

                // PUC-faithful single-C-frame model (P15.82e): PUC
                // lua_pcallk (lapi.c:1100-1108) saves k/ctx/funcidx/
                // old_errfunc/OAH on L->ci — the CURRENT CallInfo (testC's
                // own frame) — and does NOT push a new one. Reuse the
                // existing top C-frame:
                //   1. testC's own C-frame pushed by callBuiltin (k == null),
                //      exactly PUC's L->ci;
                //   2. a continuation frame (k == testcContShim with its
                //      testc_state already consumed) when pcallk runs inside
                //      testcContShim via finishCcall.
                // The old design (push a separate C-frame) left TWO frames
                // on error and forced callBuiltin's defer to guess which to
                // pop — it destroyed the CIST_YPCALL recovery frame.
                const th = self.current_thread orelse return self.fail("testC pcallk: no current thread", .{});
                const reuse_cframe = blk: {
                    if (th.call_frames.len() == 0) break :blk false;
                    const top_fr = th.call_frames.getConstPtr(th.call_frames.len() - 1);
                    if (!top_fr.isC()) break :blk false;
                    if (top_fr.u.c.k == null) break :blk true; // testC's own frame (PUC L->ci)
                    if (top_fr.u.c.k != &testcContShim) break :blk false;
                    break :blk true; // continuation frame — replace its state
                };

                // Reuse the existing C-frame (or push one only as a
                // fallback when there is none at all).
                if (!reuse_cframe) {
                    try self.pushBuiltinCFrame(callee);
                }
                const cframe = th.call_frames.getPtr(th.call_frames.len() - 1);

                // P15.82e single-frame ownership: the frame's previous state
                // (if any) is owned by the OUTER running testcContShim
                // invocation (its defer frees it) — save it for restore on
                // normal return; never destroy it here.
                const prev_state = cframe.u.c.testc_state;
                cframe.u.c.testc_state = null;
                {
                    const stack_copy = try self.alloc.alloc(Value, prefix_len);
                    errdefer self.alloc.free(stack_copy);
                    for (st.items[0..prefix_len], 0..) |v, i| stack_copy[i] = v;
                    var uv_copy: ?[]Value = null;
                    errdefer if (uv_copy) |uv| self.alloc.free(uv);
                    if (ctx.upvalues) |vals| {
                        uv_copy = try self.alloc.alloc(Value, vals.len);
                        for (vals, 0..) |v, i| uv_copy.?[i] = v;
                    }
                    const closers = try self.collectTestcClosers(st, toclose, prefix_len);
                    defer self.alloc.free(closers);
                    var cc: ?[]Value = null;
                    errdefer if (cc) |c| self.alloc.free(c);
                    if (closers.len != 0) {
                        cc = try self.alloc.alloc(Value, closers.len);
                        for (closers, 0..) |v, i| cc.?[i] = v;
                    }
                    const new_state = try self.allocTestcState(.{
                        .script = cont_script,
                        .stack_prefix = stack_copy,
                        .upenv = ctx.upenv orelse .Nil,
                        .state = ctx.state,
                        .ctx_id = ctx_id,
                        .first_arg = ctx.first_arg,
                        .nupvalues = ctx.nupvalues,
                        .nresults = nresults,
                        .is_pcallk = true,
                        .upvalues = uv_copy,
                        .closers = cc,
                    });
                    cframe.u.c.testc_state = new_state;
                }

                th.bytecode_resume_boundary = th.call_frames.len();

                // PRODUCTION lifecycle (P15.83d): PUC lua_pcallk's yieldable
                // path (k/ctx/funcidx/old_errfunc/OAH/CIST_YPCALL saving, the
                // apiCall invocation, and the normal-return clearYpcall +
                // errfunc restore, lapi.c:1097-1117) lives in the shared
                // helper — the SAME implementation c_api lua_pcallk uses.
                // funcidx = cframe.frameBase() (callee stack position, same
                // convention as builtinPcall); errfunc arg is always 0 for
                // testC pcallk (ltests passes errfunc=0), so errfunc_val =
                // null (th.errfunc := ERRFUNC_NONE for the duration, exactly
                // PUC's `L->errfunc = func` with func = 0).
                const ret = self.luaPcallKShared(th, callee, call_args, null, cframe.frameBase(), &testcContShim, 0) catch |e| switch (e) {
                    error.Yield => {
                        th.bytecode_inplace_suspended = true;
                        last_status.* = "YIELD";
                        return e;
                    },
                    // P15.78: On RuntimeError, let precover handle it.
                    // precover finds the CIST_YPCALL C-frame, pops frames
                    // above it, saves error status. Then finishCcall →
                    // finishpcallk → testcContShim runs with error status.
                    // Set bytecode_inplace_suspended so the errdefer in
                    // runBytecodeInternal preserves the CIST_YPCALL C-frame
                    // (and any C-frames with testc_state below it). Without
                    // this, the errdefer's assert fails because
                    // unwindBytecodeExecFrames stops at the CIST_YPCALL
                    // frame but bytecode_inplace_suspended is false.
                    else => {
                        th.bytecode_inplace_suspended = true;
                        last_status.* = "ERRRUN";
                        return e;
                    },
                };

                // Normal return — the shared helper already performed PUC
                // lapi.c:1110-1112 (clearYpcall + errfunc restore). The
                // C-frame itself is NOT popped here: callBuiltin's defer
                // pops it (fresh call, cframe_preserved == false on normal
                // return) — or poscallCFrame pops it later when pcallk ran
                // inside a continuation (finishCcall context). Destroy the
                // new state and restore prev_state so the outer shim
                // invocation still finds its own state on the frame.
                if (cframe.u.c.testc_state) |s| {
                    self.destroyTestcState(s);
                }
                cframe.u.c.testc_state = prev_state;

                defer self.alloc.free(ret);
                st.items.len = call_idx;
                const want: usize = if (nresults < 0) ret.len else @min(ret.len, @as(usize, @intCast(nresults)));
                try st.appendSlice(self.alloc, ret[0..want]);
                last_status.* = "OK";
            },
            .ret => {
                if (cargs.len != 1) return self.fail("testC return expects 1 arg", .{});
                if (std.mem.eql(u8, cargs[0], "*")) return .all;
                if (std.mem.eql(u8, cargs[0], ".")) {
                    if (st.items.len == 0) return self.fail("testC return . expects count on stack", .{});
                    const count_v = st.pop().?;
                    const n: usize = switch (count_v) {
                        .Int => |i| if (i >= 0) @intCast(i) else return self.fail("testC invalid return count", .{}),
                        .Num => |x| if (std.math.isFinite(x) and x >= 0 and x == @floor(x)) @intFromFloat(x) else return self.fail("testC invalid return count", .{}),
                        else => return self.fail("testC invalid return count", .{}),
                    };
                    return .{ .fixed = n };
                }
                const n = std.fmt.parseInt(usize, cargs[0], 10) catch return self.fail("testC invalid return count", .{});
                return .{ .fixed = n };
            },
        }
        return null;
    }

    fn parseTestcIndex(self: *Vm, tok: []const u8, top: usize) DispatchError!usize {
        const idx = std.fmt.parseInt(i32, tok, 10) catch return self.fail("testC invalid index '{s}'", .{tok});
        if (idx == 0) return self.fail("testC invalid index '{s}'", .{tok});
        if (idx > 0) {
            const abs: usize = @intCast(idx - 1);
            if (abs >= top) return self.fail("testC index out of range '{s}' (top={d})", .{ tok, top });
            return abs;
        }
        const r: usize = @intCast(-idx);
        if (r == 0 or r > top) return self.fail("testC index out of range '{s}' (top={d})", .{ tok, top });
        return top - r;
    }

    fn parseTestcIndexMaybe(self: *Vm, tok: []const u8, top: usize) DispatchError!?usize {
        const idx = std.fmt.parseInt(i32, tok, 10) catch return self.fail("testC invalid index", .{});
        if (idx == 0) return self.fail("testC invalid index", .{});
        if (idx > 0) {
            const abs: usize = @intCast(idx - 1);
            if (abs >= top) return null;
            return abs;
        }
        const r: usize = @intCast(-idx);
        if (r == 0 or r > top) return null;
        return top - r;
    }

    fn parseTestcSettop(self: *Vm, tok: []const u8, top: usize) DispatchError!usize {
        const idx = std.fmt.parseInt(i32, tok, 10) catch return self.fail("testC invalid settop", .{});
        if (idx >= 0) return @intCast(idx);
        const t: i64 = @intCast(top);
        const nt = t + @as(i64, idx) + 1;
        if (nt < 0) return self.fail("testC invalid settop", .{});
        return @intCast(nt);
    }

    fn testcIsMarked(marks: []const usize, idx: usize) bool {
        for (marks) |m| {
            if (m == idx) return true;
        }
        return false;
    }

    fn testcUnmark(marks: *std.ArrayListUnmanaged(usize), idx: usize) void {
        var i: usize = 0;
        while (i < marks.items.len) {
            if (marks.items[i] == idx) {
                _ = marks.swapRemove(i);
                continue;
            }
            i += 1;
        }
    }

    fn testcDropMarksAbove(marks: *std.ArrayListUnmanaged(usize), new_len: usize) void {
        var i: usize = 0;
        while (i < marks.items.len) {
            if (marks.items[i] >= new_len) {
                _ = marks.swapRemove(i);
                continue;
            }
            i += 1;
        }
    }

    fn resolveTestcContinuationScript(self: *Vm, ctx: TestcContext, st: *std.ArrayListUnmanaged(Value), tok: []const u8) DispatchError!struct { script: []const u8, ctx_id: i64 } {
        // PUC `getindex(".")`: pops the top of stack as a number (stack index),
        // then `Cfunck` uses `lua_tostring(L, ctx)` to get the continuation
        // script at that index. In our model, `pushupvalueindex N` pushes the
        // integer N (upvalue index), and `.` pops it and fetches upvalue N.
        // The popped value is also used as `ctx` (set as the `ctx` global by
        // Cfunck/testcContShim).
        var ctx_id: i64 = 0;
        const v: Value = if (std.mem.eql(u8, tok, ".")) blk: {
            if (st.items.len == 0) return self.fail("testC stack underflow", .{});
            const idx_val = st.pop().?;
            const uix: usize = switch (idx_val) {
                .Int => |i| if (i > 0) @intCast(i) else return self.fail("testC invalid upvalue index from '.'", .{}),
                else => return self.fail("testC '.' expects integer index on stack", .{}),
            };
            ctx_id = @intCast(uix);
            break :blk try self.getTestcUpvalue(ctx, uix);
        } else if (parseTestcUpvalueToken(tok)) |uix| blk: {
            ctx_id = @intCast(uix);
            break :blk try self.getTestcUpvalue(ctx, uix);
        } else blk: {
            const idx = try self.parseTestcIndex(tok, st.items.len);
            ctx_id = @intCast(idx + 1); // PUC uses 1-based absolute index
            break :blk st.items[idx];
        };
        const script = switch (v) {
            .String => |s| s.bytes(),
            else => return self.fail("testC continuation expects script string", .{}),
        };
        return .{ .script = script, .ctx_id = ctx_id };
    }

    fn testcContinuationCtxId(tok: []const u8) i64 {
        if (parseTestcUpvalueToken(tok)) |uix| return @intCast(uix);
        return std.fmt.parseInt(i64, tok, 10) catch 0;
    }

    fn collectTestcClosers(
        self: *Vm,
        st: *std.ArrayListUnmanaged(Value),
        toclose: *std.ArrayListUnmanaged(usize),
        stack_len: usize,
    ) DispatchError![]Value {
        var count: usize = 0;
        for (toclose.items) |idx| {
            if (idx < stack_len) count += 1;
        }
        const vals = try self.alloc.alloc(Value, count);
        var out_i: usize = 0;
        for (toclose.items) |idx| {
            if (idx < stack_len) {
                vals[out_i] = st.items[idx];
                out_i += 1;
            }
        }
        return vals;
    }

    fn trimTestcQuoted(s0: []const u8) []const u8 {
        // parseTestcWords already strips quotes and trims unquoted tokens.
        // This function is a defensive no-op for already-processed tokens;
        // it must NOT trim whitespace (would destroy leading/trailing spaces
        // in quoted content like pushstring ' alo' → " alo").
        var s = s0;
        if (s.len >= 2 and ((s[0] == '\'' and s[s.len - 1] == '\'') or (s[0] == '"' and s[s.len - 1] == '"'))) {
            s = s[1 .. s.len - 1];
        }
        return s;
    }

    fn parseLeadingIntTail(tok: []const u8) ?struct { n: i64, tail: []const u8 } {
        if (tok.len == 0) return null;
        var i: usize = 0;
        if (tok[0] == '+' or tok[0] == '-') i = 1;
        const start_digits = i;
        while (i < tok.len and tok[i] >= '0' and tok[i] <= '9') : (i += 1) {}
        if (i == start_digits) return null;
        const n = std.fmt.parseInt(i64, tok[0..i], 10) catch return null;
        return .{ .n = n, .tail = tok[i..] };
    }

    fn parseTestcUpvalueToken(tok: []const u8) ?usize {
        if (tok.len < 2 or tok[0] != 'U') return null;
        return std.fmt.parseInt(usize, tok[1..], 10) catch null;
    }

    fn getTestcUpvalue(_: *Vm, ctx: TestcContext, uix: usize) DispatchError!Value {
        if (uix == 0) return ctx.upenv orelse .Nil;
        const upvs = ctx.upvalues orelse return .Nil;
        const i = uix - 1;
        // PUC index2value: if idx > nupvalues, return &G(L)->nilvalue (the
        // nil sentinel). We return a "null pointer" userdata (matching PUC's
        // distinction between LUA_TNONE and LUA_TNIL for isnil/isnull checks).
        if (i >= ctx.nupvalues) return makeTestcPointerValue(0);
        return upvs[i];
    }

    fn setTestcUpvalue(self: *Vm, ctx: TestcContext, uix: usize, v: Value) DispatchError!void {
        if (uix == 0) {
            _ = self;
            return;
        }
        const upvs = ctx.upvalues orelse return;
        const i = uix - 1;
        if (i >= upvs.len) return;
        upvs[i] = v;
    }

    fn isCallableValue(v: Value) bool {
        return switch (v) {
            .Builtin, .Closure, .Table => true,
            else => false,
        };
    }

    fn failTestcRaw(self: *Vm, msg: []const u8) Error {
        const ls = try self.internStr(msg);
        self.err = ls.bytes();
        self.err_obj = .{ .String = ls };
        self.err_has_obj = true;
        self.err_source = null;
        self.err_line = -1;
        self.err_cfunc_label = "global 'error'";
        self.captureErrorTraceback();
        return error.RuntimeError;
    }

    fn isUserdataLike(self: *Vm, v: Value) bool {
        if (asFileTable(self, v) != null) return true;
        return v == .Userdata or v == .LightUserdata;
    }

    /// PUC `checktab` (ltablib.c:47). Check that `v` either is a real table
    /// or can behave like one (has a metatable with the required metamethods).
    /// `what` flags: read → needs `__index`, write → needs `__newindex`,
    /// len → needs `__len`. If `v` is a file table, it is NOT a real table
    /// and must have the metamethods.
    const TabCheck = struct { read: bool = false, write: bool = false, len: bool = false };

    fn checkTabArg(self: *Vm, v: Value, what: TabCheck, fname: []const u8) DispatchError!void {
        if (v == .Table and asFileTable(self, v) == null) return;
        // Not a real table: must have a metatable with the required metamethods.
        const mt: ?*Table = switch (v) {
            .Table => |t| t.metatable,
            .Userdata => |ud| ud.metatable,
            else => null,
        };
        if (mt) |m| {
            const has_index = !what.read or (self.fastTm(m, .index) orelse .Nil) != .Nil;
            const has_newindex = !what.write or (self.fastTm(m, .newindex) orelse .Nil) != .Nil;
            const has_len = !what.len or (self.fastTm(m, .len) orelse .Nil) != .Nil;
            if (has_index and has_newindex and has_len) {
                return; // all required metamethods present
            }
        }
        return self.fail("bad argument #1 to '{s}' (table expected)", .{fname});
    }

    fn isTestcLightUserdata(self: *Vm, v: Value) bool {
        _ = self;
        return v == .LightUserdata;
    }

    fn isTestcNullPointer(v: Value) bool {
        return v == .LightUserdata and @intFromPtr(v.LightUserdata) == 0;
    }

    /// Create a testC pointer value from a raw integer id. PUC encodes the
    /// integer directly as a light userdata pointer (ltests.c:1267-1271).
    /// We do the same: @ptrFromInt(id) is deterministic, so identity holds
    /// and table-key lookup works via pointer hashing (ltable.zig:295).
    fn makeTestcPointerValue(ptr_id: u64) Value {
        // PUC allows null light userdata. Zig @ptrFromInt(0) panics in Debug
        // but works in ReleaseFast (UB). Pre-existing issue — see plan §4.2.1.
        return .{ .LightUserdata = @ptrFromInt(ptr_id) };
    }

    fn testcLiveUserdataKb(self: *Vm) f64 {
        // Real Userdata memory is tracked by gc_count_kb (via gcNoteAlloc in
        // allocUserdata). The live table only tracks payload size for the
        // old table-based emulation. Skip real Userdata entries to avoid
        // double-counting.
        const t_global = self.getGlobal("T");
        if (t_global != .Table) return 0.0;
        const fnv = self.getFieldOpt(t_global.Table, "_liveudbytes") orelse return 0.0;
        const retv: Value = switch (fnv) {
            .Builtin => |id| blk: {
                var out: [1]Value = .{.Nil};
                self.callBuiltin(id, &[_]Value{}, out[0..]) catch return 0.0;
                break :blk out[0];
            },
            .Closure => |cl| blk: {
                const ret = self.runClosure(cl, &[_]Value{}) catch return 0.0;
                defer self.alloc.free(ret);
                break :blk if (ret.len > 0) ret[0] else .Nil;
            },
            else => return 0.0,
        };
        const bytes: f64 = switch (retv) {
            .Int => |v| @floatFromInt(v),
            .Num => |v| v,
            else => 0.0,
        };
        return if (bytes > 0.0) bytes / 1024.0 else 0.0;
    }

    fn builtinHasDynamicOutCount(id: BuiltinId) bool {
        return switch (id) {
            .coroutine_resume, .coroutine_wrap_iter, .coroutine_yield, .pcall, .xpcall, .utf8_codepoint, .io_lines_iter, .io_read, .file_read, .file_close, .io_close, .io_popen, .os_execute, .dofile, .io_lines, .file_lines, .testc_testC => true,
            else => false,
        };
    }

    fn builtinOutLen(self: *Vm, id: BuiltinId, call_args: []const Value) usize {
        return switch (id) {
            .print => 0,
            .warn => 0,
            .@"error" => 0,
            .io_write, .io_stderr_write => 1,
            .io_close, .file_close => 3,
            .io_open, .io_popen, .io_tmpfile => 3,
            .os_execute => 3,
            .os_exit => 0,
            .io_read, .file_read => 8,
            .io_lines => blk: {
                if (call_args.len > 0 and call_args[0] == .String) break :blk 4;
                break :blk 3;
            },
            .file_lines => 3,
            .io_lines_iter => blk: {
                if (call_args.len == 0 or call_args[0] != .Table) break :blk 8;
                const it = call_args[0].Table;
                const n = if (self.getFieldOpt(it, "__fmts")) |v|
                    if (v == .Table) v.Table.asize else 0
                else
                    0;
                break :blk if (n == 0) 1 else n;
            },
            .io_flush, .file_flush, .file_setvbuf => 1,
            .file_seek => 3,
            .file_write => 4,
            .os_remove, .os_rename => 3,

            .math_random => 1,
            .math_randomseed => 2,
            .pairs => 4,
            .ipairs => 3,
            .pairs_iter, .ipairs_iter => 2,
            .coroutine_running => 2,

            .assert => call_args.len,
            .select => blk: {
                if (call_args.len == 0) break :blk 0;
                switch (call_args[0]) {
                    .String => |s| {
                        if (s == self.internStrAssume("#")) break :blk 1;
                        break :blk 0;
                    },
                    .Int => |raw_idx| {
                        var idx = raw_idx;
                        const n = call_args.len - 1;
                        if (idx == 0) break :blk 0;
                        if (idx < 0) idx += @as(i64, @intCast(n)) + 1;
                        if (idx < 1) break :blk 0;
                        if (@as(usize, @intCast(idx)) > n) break :blk 0;
                        break :blk n - @as(usize, @intCast(idx)) + 1;
                    },
                    else => break :blk 0,
                }
            },
            .pcall, .xpcall => 256,
            .coroutine_resume => 8,
            .coroutine_yield => 8,
            .coroutine_close => 2,
            .coroutine_wrap_iter => 256,
            .next => 2,
            .dofile => 16,
            .testc_testC => 256,
            .testc_makecfunc => 1,
            .testc_allowhookyield => 0,
            .testc_totalmem => 3,
            .testc_stats => 1,
            .testc_querytab => 3,
            .testc_gcstate => 1,
            .loadfile, .load => 2,
            .require => 2,
            .package_searchpath => 2,
            .setmetatable, .getmetatable => 1,
            .debug_getinfo => 1,
            .debug_getlocal => 2,
            .debug_setlocal => 1,
            .debug_getupvalue => 2,
            .debug_setupvalue => 1,
            .debug_upvaluejoin => 0,
            .debug_gethook => 3,
            .debug_sethook => 0,
            .debug_getuservalue => 2,
            .debug_setuservalue => 1,
            .debug_debug => 0,
            .math_type => 1,
            .math_modf => 2,
            .math_frexp => 2,
            .math_min => 1,
            .math_max => 1,
            .math_floor => 1,
            .string_len => 1,
            .string_char => 1,
            .string_byte => blk: {
                if (call_args.len == 0 or call_args[0] != .String) break :blk 1;
                const s = call_args[0].String;
                var start_idx: i64 = if (call_args.len >= 2 and call_args[1] == .Int) call_args[1].Int else 1;
                var end_idx: i64 = if (call_args.len >= 3 and call_args[2] == .Int) call_args[2].Int else start_idx;
                const len: i64 = @intCast(s.len());
                if (start_idx < 0) start_idx += len + 1;
                if (end_idx < 0) end_idx += len + 1;
                if (start_idx < 1) start_idx = 1;
                if (end_idx > len) end_idx = len;
                if (start_idx > end_idx or start_idx > len) break :blk 0;
                break :blk @intCast(end_idx - start_idx + 1);
            },
            .string_sub => 1,
            .string_find => blk: {
                if (call_args.len < 2 or call_args[1] != .String) break :blk 2;
                const caps = estimatePatternCaptureCount(call_args[1].String.bytes());
                break :blk 2 + caps;
            },
            .string_gsub => 2,
            .string_gmatch => 1,
            .string_gmatch_iter => 10,
            .string_match => blk: {
                if (call_args.len < 2 or call_args[1] != .String) break :blk 1;
                const caps = estimatePatternCaptureCount(call_args[1].String.bytes());
                break :blk if (caps == 0) 1 else caps;
            },
            .utf8_char => 1,
            .utf8_codepoint => blk: {
                if (call_args.len == 0 or call_args[0] != .String) break :blk 1;
                const s = call_args[0].String;
                var i: i64 = 1;
                var j: i64 = 1;
                if (call_args.len >= 2) i = switch (call_args[1]) {
                    .Int => |x| x,
                    else => break :blk 1,
                };
                j = if (call_args.len >= 3)
                    switch (call_args[2]) {
                        .Int => |x| x,
                        else => break :blk 1,
                    }
                else
                    i;
                const len: i64 = @intCast(s.len());
                if (i < 0) i += len + 1;
                if (j < 0) j += len + 1;
                if (i < 1 or j < 1 or i > len or j > len or i > j) break :blk 0;
                break :blk @intCast(j - i + 1);
            },
            .utf8_len => 2,
            .utf8_offset => 2,
            .utf8_codes => 3,
            .utf8_codes_iter, .utf8_codes_iter_ns => 2,
            .string_unpack => blk: {
                if (call_args.len == 0 or call_args[0] != .String) break :blk 2;
                const fmt = call_args[0].String.bytes();
                var i: usize = 0;
                var nvals: usize = 0;
                while (i < fmt.len) {
                    const ch = fmt[i];
                    if (ch == ' ' or ch == '\t' or ch == '\n' or ch == '\r' or ch == '<' or ch == '>' or ch == '=') {
                        i += 1;
                        continue;
                    }
                    if (ch == '!') {
                        i += 1;
                        while (i < fmt.len and fmt[i] >= '0' and fmt[i] <= '9') : (i += 1) {}
                        continue;
                    }
                    if (ch == 'b' or ch == 'B' or ch == 'h' or ch == 'H' or ch == 'l' or ch == 'L' or ch == 'i' or ch == 'I' or ch == 'j' or ch == 'J' or ch == 'n' or ch == 'f' or ch == 'd' or ch == 's' or ch == 'z' or ch == 'T') {
                        nvals += 1;
                        i += 1;
                        while (i < fmt.len and fmt[i] >= '0' and fmt[i] <= '9') : (i += 1) {}
                        continue;
                    }
                    if (ch == 'c') {
                        nvals += 1;
                        i += 1;
                        while (i < fmt.len and fmt[i] >= '0' and fmt[i] <= '9') : (i += 1) {}
                        continue;
                    }
                    i += 1;
                }
                break :blk nvals + 1; // include next-position result
            },
            .string_dump => 1,
            .string_rep => 1,
            .table_insert => 0,
            .table_sort => 0,
            .table_unpack => blk: {
                if (call_args.len == 0 or call_args[0] != .Table) break :blk 0;
                const tbl = call_args[0].Table;
                if (tbl.metatable) |mt| {
                    if (self.fastTm(mt, .len) != null) break :blk 256;
                }
                const start_idx0: i64 = if (call_args.len >= 2) switch (call_args[1]) {
                    .Nil => 1,
                    .Int => |x| x,
                    .Num => |n| nblk: {
                        if (!std.math.isFinite(n)) break :blk 0;
                        const i: i64 = @intFromFloat(std.math.trunc(n));
                        if (@as(f64, @floatFromInt(i)) != n) break :blk 0;
                        break :nblk i;
                    },
                    else => break :blk 0,
                } else 1;
                const end_idx0: i64 = if (call_args.len >= 3) switch (call_args[2]) {
                    .Nil => self.tableBorderLen(tbl),
                    .Int => |x| x,
                    .Num => |n| nblk: {
                        if (!std.math.isFinite(n)) break :blk 0;
                        const i: i64 = @intFromFloat(std.math.trunc(n));
                        if (@as(f64, @floatFromInt(i)) != n) break :blk 0;
                        break :nblk i;
                    },
                    else => break :blk 0,
                } else self.tableBorderLen(tbl);
                if (end_idx0 < start_idx0) break :blk 0;
                const count_i128: i128 = (@as(i128, end_idx0) - @as(i128, start_idx0)) + 1;
                if (count_i128 <= 0) break :blk 0;
                if (count_i128 > 100_000) break :blk 1;
                break :blk @intCast(count_i128);
            },

            // Most builtins return a single value.
            else => 1,
        };
    }

    fn binAdd(self: *Vm, lhs: Value, rhs: Value) DispatchError!Value {
        if (rawArithCompute(.add, lhs, rhs)) |result| return result;
        if (try self.callBinaryMetamethod(lhs, rhs, .add)) |v| return v;
        return self.failArithmeticOperands(lhs, rhs);
    }

    fn binSub(self: *Vm, lhs: Value, rhs: Value) DispatchError!Value {
        if (rawArithCompute(.sub, lhs, rhs)) |result| return result;
        if (try self.callBinaryMetamethod(lhs, rhs, .sub)) |v| return v;
        return self.failArithmeticOperands(lhs, rhs);
    }

    fn binMul(self: *Vm, lhs: Value, rhs: Value) DispatchError!Value {
        if (rawArithCompute(.mul, lhs, rhs)) |result| return result;
        if (try self.callBinaryMetamethod(lhs, rhs, .mul)) |v| return v;
        return self.failArithmeticOperands(lhs, rhs);
    }

    fn binDiv(self: *Vm, lhs: Value, rhs: Value) DispatchError!Value {
        if (rawArithCompute(.div, lhs, rhs)) |result| return result;
        if (try self.callBinaryMetamethod(lhs, rhs, .div)) |v| return v;
        return self.failArithmeticOperands(lhs, rhs);
    }

    fn binIdiv(self: *Vm, lhs: Value, rhs: Value) DispatchError!Value {
        if (rawArithCompute(.idiv, lhs, rhs)) |result| return result;
        // rawArithCompute returns null for int // 0 (PUC luaV_idiv error).
        if (lhs == .Int and rhs == .Int and rhs.Int == 0)
            return self.fail("attempt to divide by zero", .{});
        if (try self.callBinaryMetamethod(lhs, rhs, .idiv)) |v| return v;
        return self.failArithmeticOperands(lhs, rhs);
    }

    fn binMod(self: *Vm, lhs: Value, rhs: Value) DispatchError!Value {
        if (rawArithCompute(.mod, lhs, rhs)) |result| return result;
        // rawArithCompute returns null for int % 0 (PUC luaV_mod error).
        if (lhs == .Int and rhs == .Int and rhs.Int == 0)
            return self.fail("attempt to perform 'n%0'", .{});
        if (try self.callBinaryMetamethod(lhs, rhs, .mod)) |v| return v;
        return self.failArithmeticOperands(lhs, rhs);
    }

    fn luaNumMod(a: f64, b: f64) f64 {
        var m = @rem(a, b);
        if ((m > 0 and b < 0) or (m < 0 and b > 0)) m += b;
        return m;
    }

    fn binPow(self: *Vm, lhs: Value, rhs: Value) DispatchError!Value {
        if (rawArithCompute(.pow, lhs, rhs)) |result| return result;
        if (try self.callBinaryMetamethod(lhs, rhs, .pow)) |v| return v;
        return self.failArithmeticOperands(lhs, rhs);
    }

    fn binBand(self: *Vm, lhs: Value, rhs: Value) DispatchError!Value {
        if (valueToIntForBitwise(lhs)) |li| {
            if (valueToIntForBitwise(rhs)) |ri| return .{ .Int = li & ri };
        }
        if (try self.callBinaryMetamethod(lhs, rhs, .band)) |v| return v;
        if (isNumWithoutInteger(lhs) or isNumWithoutInteger(rhs)) return self.fail("number has no integer representation", .{});
        return self.fail("bitwise operation on {s} value and {s} value", .{ lhs.typeName(), rhs.typeName() });
    }

    fn binBor(self: *Vm, lhs: Value, rhs: Value) DispatchError!Value {
        if (valueToIntForBitwise(lhs)) |li| {
            if (valueToIntForBitwise(rhs)) |ri| return .{ .Int = li | ri };
        }
        if (try self.callBinaryMetamethod(lhs, rhs, .bor)) |v| return v;
        if (isNumWithoutInteger(lhs) or isNumWithoutInteger(rhs)) return self.fail("number has no integer representation", .{});
        return self.fail("bitwise operation on {s} value and {s} value", .{ lhs.typeName(), rhs.typeName() });
    }

    fn binBxor(self: *Vm, lhs: Value, rhs: Value) DispatchError!Value {
        if (valueToIntForBitwise(lhs)) |li| {
            if (valueToIntForBitwise(rhs)) |ri| return .{ .Int = li ^ ri };
        }
        if (try self.callBinaryMetamethod(lhs, rhs, .bxor)) |v| return v;
        if (isNumWithoutInteger(lhs) or isNumWithoutInteger(rhs)) return self.fail("number has no integer representation", .{});
        return self.fail("bitwise operation on {s} value and {s} value", .{ lhs.typeName(), rhs.typeName() });
    }

    fn binShl(self: *Vm, lhs: Value, rhs: Value) DispatchError!Value {
        if (valueToIntForBitwise(lhs)) |li| {
            if (valueToIntForBitwise(rhs)) |ri| {
                return .{ .Int = shiftLeft(li, ri) };
            }
        }
        if (try self.callBinaryMetamethod(lhs, rhs, .shl)) |v| return v;
        if (isNumWithoutInteger(lhs) or isNumWithoutInteger(rhs)) return self.fail("number has no integer representation", .{});
        return self.fail("bitwise operation on {s} value and {s} value", .{ lhs.typeName(), rhs.typeName() });
    }

    /// PUC luaV_shiftl: left shift by non-negative amount, right shift by
    /// negative amount. Shifts >= 64 produce 0. MIN_INT shift also produces 0
    /// (avoids UB on negating MIN_INT).
    fn shiftLeft(li: i64, ri: i64) i64 {
        const lu: u64 = @bitCast(li);
        if (ri >= 0 and ri < 64) {
            const out: i64 = @bitCast(lu << @as(u6, @intCast(ri)));
            return out;
        }
        if (ri >= 64) return 0;
        if (ri == std.math.minInt(i64)) return 0;
        const s: i64 = -ri;
        if (s >= 64) return 0;
        const out: i64 = @bitCast(lu >> @as(u6, @intCast(s)));
        return out;
    }

    fn binShr(self: *Vm, lhs: Value, rhs: Value) DispatchError!Value {
        if (valueToIntForBitwise(lhs)) |li| {
            if (valueToIntForBitwise(rhs)) |ri| {
                return .{ .Int = shiftRight(li, ri) };
            }
        }
        if (try self.callBinaryMetamethod(lhs, rhs, .shr)) |v| return v;
        if (isNumWithoutInteger(lhs) or isNumWithoutInteger(rhs)) return self.fail("number has no integer representation", .{});
        return self.fail("bitwise operation on {s} value and {s} value", .{ lhs.typeName(), rhs.typeName() });
    }

    /// PUC luaV_shrl: right shift by non-negative amount, left shift by
    /// negative amount. Mirrors shiftLeft semantics.
    fn shiftRight(li: i64, ri: i64) i64 {
        const lu: u64 = @bitCast(li);
        if (ri >= 0 and ri < 64) {
            const out: i64 = @bitCast(lu >> @as(u6, @intCast(ri)));
            return out;
        }
        if (ri >= 64) return 0;
        if (ri == std.math.minInt(i64)) return 0;
        const s: i64 = -ri;
        if (s >= 64) return 0;
        const out: i64 = @bitCast(lu << @as(u6, @intCast(s)));
        return out;
    }

    fn cmpLt(self: *Vm, lhs: Value, rhs: Value) DispatchError!bool {
        return switch (lhs) {
            .Int => |li| switch (rhs) {
                .Int => |ri| li < ri,
                .Num => |rn| intLtNum(li, rn),
                else => if (try self.callBinaryMetamethod(lhs, rhs, .lt)) |v| isTruthy(v) else self.failCompare(lhs, rhs),
            },
            .Num => |ln| switch (rhs) {
                .Int => |ri| numLtInt(ln, ri),
                .Num => |rn| ln < rn,
                else => if (try self.callBinaryMetamethod(lhs, rhs, .lt)) |v| isTruthy(v) else self.failCompare(lhs, rhs),
            },
            .String => |ls| switch (rhs) {
                .String => |rs| std.mem.order(u8, ls.bytes(), rs.bytes()) == .lt,
                else => if (try self.callBinaryMetamethod(lhs, rhs, .lt)) |v| isTruthy(v) else self.failCompare(lhs, rhs),
            },
            else => if (try self.callBinaryMetamethod(lhs, rhs, .lt)) |v| isTruthy(v) else self.failCompare(lhs, rhs),
        };
    }

    fn cmpLte(self: *Vm, lhs: Value, rhs: Value) DispatchError!bool {
        return switch (lhs) {
            .Int => |li| switch (rhs) {
                .Int => |ri| li <= ri,
                .Num => |rn| intLeNum(li, rn),
                else => if (try self.callBinaryMetamethod(lhs, rhs, .le)) |v| isTruthy(v) else self.failCompare(lhs, rhs),
            },
            .Num => |ln| switch (rhs) {
                .Int => |ri| numLeInt(ln, ri),
                .Num => |rn| ln <= rn,
                else => if (try self.callBinaryMetamethod(lhs, rhs, .le)) |v| isTruthy(v) else self.failCompare(lhs, rhs),
            },
            .String => |ls| switch (rhs) {
                .String => |rs| {
                    const ord = std.mem.order(u8, ls.bytes(), rs.bytes());
                    return ord == .lt or ord == .eq;
                },
                else => if (try self.callBinaryMetamethod(lhs, rhs, .le)) |v| isTruthy(v) else self.failCompare(lhs, rhs),
            },
            else => if (try self.callBinaryMetamethod(lhs, rhs, .le)) |v| isTruthy(v) else self.failCompare(lhs, rhs),
        };
    }

    fn cmpGt(self: *Vm, lhs: Value, rhs: Value) DispatchError!bool {
        return try self.cmpLt(rhs, lhs);
    }

    fn cmpGte(self: *Vm, lhs: Value, rhs: Value) DispatchError!bool {
        return try self.cmpLte(rhs, lhs);
    }

    fn intLtNum(i: i64, n: f64) bool {
        if (std.math.isNan(n)) return false;
        const min_i_f = -9_223_372_036_854_775_808.0;
        const max_i_plus1_f = 9_223_372_036_854_775_808.0;
        if (n <= min_i_f) return false;
        if (n >= max_i_plus1_f) return true;
        const t = std.math.trunc(n);
        if (t == n) {
            const ni: i64 = @intFromFloat(t);
            return i < ni;
        }
        return @as(f64, @floatFromInt(i)) < n;
    }

    fn intLeNum(i: i64, n: f64) bool {
        if (std.math.isNan(n)) return false;
        const min_i_f = -9_223_372_036_854_775_808.0;
        const max_i_plus1_f = 9_223_372_036_854_775_808.0;
        if (n < min_i_f) return false;
        if (n >= max_i_plus1_f) return true;
        const t = std.math.trunc(n);
        if (t == n) {
            const ni: i64 = @intFromFloat(t);
            return i <= ni;
        }
        return @as(f64, @floatFromInt(i)) <= n;
    }

    fn numLtInt(n: f64, i: i64) bool {
        if (std.math.isNan(n)) return false;
        const min_i_f = -9_223_372_036_854_775_808.0;
        const max_i_plus1_f = 9_223_372_036_854_775_808.0;
        if (n < min_i_f) return true;
        if (n >= max_i_plus1_f) return false;
        const t = std.math.trunc(n);
        if (t == n) {
            const ni: i64 = @intFromFloat(t);
            return ni < i;
        }
        return n < @as(f64, @floatFromInt(i));
    }

    fn numLeInt(n: f64, i: i64) bool {
        if (std.math.isNan(n)) return false;
        const min_i_f = -9_223_372_036_854_775_808.0;
        const max_i_plus1_f = 9_223_372_036_854_775_808.0;
        if (n <= min_i_f) return true;
        if (n >= max_i_plus1_f) return false;
        const t = std.math.trunc(n);
        if (t == n) {
            const ni: i64 = @intFromFloat(t);
            return ni <= i;
        }
        return n <= @as(f64, @floatFromInt(i));
    }

    const ConcatString = struct {
        bytes: []const u8,
        owned: bool = false,
    };

    fn concatOperandToString(self: *Vm, v: Value) DispatchError!ConcatString {
        return switch (v) {
            .String => |s| .{ .bytes = s.bytes(), .owned = false },
            .Int => |i| .{ .bytes = try std.fmt.allocPrint(self.alloc, "{d}", .{i}), .owned = true },
            .Num => |n| .{ .bytes = try self.numberToStringAlloc(n), .owned = true },
            else => self.fail("attempt to concatenate a {s} value", .{v.typeName()}),
        };
    }

    fn binConcat(self: *Vm, lhs: Value, rhs: Value) DispatchError!Value {
        // Hot path for loops like `i .. "."` in nextvar.lua:
        // format integer operand into a stack buffer to avoid temporary heap
        // allocation from `allocPrint`.
        if (lhs == .Int and rhs == .String) {
            var ibuf: [32]u8 = undefined;
            const is = std.fmt.bufPrint(ibuf[0..], "{d}", .{lhs.Int}) catch unreachable;
            const out = try self.alloc.alloc(u8, is.len + rhs.String.len());
            std.mem.copyForwards(u8, out[0..is.len], is);
            std.mem.copyForwards(u8, out[is.len..], rhs.String.bytes());
            return .{ .String = try self.internStr(out) };
        }
        if (lhs == .String and rhs == .Int) {
            var ibuf: [32]u8 = undefined;
            const is = std.fmt.bufPrint(ibuf[0..], "{d}", .{rhs.Int}) catch unreachable;
            const llen = lhs.String.len();
            const out = try self.alloc.alloc(u8, llen + is.len);
            std.mem.copyForwards(u8, out[0..llen], lhs.String.bytes());
            std.mem.copyForwards(u8, out[llen..], is);
            return .{ .String = try self.internStr(out) };
        }
        const a = self.concatOperandToString(lhs) catch {
            if (try self.callBinaryMetamethod(lhs, rhs, .concat)) |v| return v;
            return self.fail("attempt to concatenate a {s} value", .{lhs.typeName()});
        };
        defer if (a.owned) self.alloc.free(a.bytes);
        const b = self.concatOperandToString(rhs) catch {
            if (try self.callBinaryMetamethod(lhs, rhs, .concat)) |v| return v;
            return self.fail("attempt to concatenate a {s} value", .{rhs.typeName()});
        };
        defer if (b.owned) self.alloc.free(b.bytes);
        const out = try self.alloc.alloc(u8, a.bytes.len + b.bytes.len);
        std.mem.copyForwards(u8, out[0..a.bytes.len], a.bytes);
        std.mem.copyForwards(u8, out[a.bytes.len..], b.bytes);
        return .{ .String = try self.internStr(out) };
    }
};

test "vm: run return 1+2" {
    const testing = std.testing;
    const Source = @import("source.zig").Source;
    const Lexer = @import("lexer.zig").Lexer;
    const Parser = @import("parser.zig").Parser;
    const ast = @import("ast.zig");
    const CodegenBc = @import("codegen_bc.zig").Codegen;

    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const aalloc = arena.allocator();

    const src = Source{
        .name = "<test>",
        .bytes = "return 1 + 2\n",
    };

    var lex = Lexer.init(src);
    var p = try Parser.init(&lex);

    var ast_arena = ast.AstArena.init(aalloc);
    defer ast_arena.deinit();
    const chunk = try p.parseChunkAst(&ast_arena);

    var cg_bc = CodegenBc.init(aalloc, src.name, src.bytes);
    defer cg_bc.deinit();
    const proto = try cg_bc.compileChunk(chunk);

    var vm = Vm.init(aalloc, false);
    defer vm.deinit();
    const ret = try vm.runBytecode(proto, &.{}, &.{}, null);

    try testing.expectEqual(@as(usize, 1), ret.len);
    switch (ret[0]) {
        .Int => |v| try testing.expectEqual(@as(i64, 3), v),
        else => try testing.expect(false),
    }
}

test "vm: callCFunction dispatches a c_func closure" {
    // Proves the c_func dispatch path (B1): a Closure with c_func set and
    // proto == null is invoked through its C function pointer via
    // runClosure -> callCFunction. Exercises the full bc_stack<->c_stack
    // marshaling round-trip (arg bc->c, result c->bc) and the c_stack
    // save/restore around the call.
    const testing = std.testing;

    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const aalloc = arena.allocator();

    var vm = Vm.init(aalloc, false);
    defer vm.deinit();
    _ = try vm.setupMainHandle();

    // A C-ABI function (lua_CFunction): reads one int arg from c_stack[0],
    // pushes 2*arg, returns 1 result. Mirrors how a real luaopen_* / C
    // extension function interacts with the VM through the C API shim.
    const doubler = struct {
        fn run(L: ?*lua_State) callconv(.c) c_int {
            const v = L.?.vm.cur_c_stack.items[0];
            const n: i64 = switch (v) {
                .Int => |i| i,
                else => 0,
            };
            L.?.vm.cur_c_stack.append(L.?.vm.alloc, .{ .Int = n * 2 }) catch {};
            return 1;
        }
    }.run;

    // Register a C closure (proto null, c_func set) exactly as
    // luaL_setfuncs/lua_pushcfunction do.
    const cl = try vm.alloc.create(Closure);
    cl.* = .{ .upvalues = &.{}, .c_func = doubler };
    try vm.gcRegisterClosure(cl);

    // apiCall (pub) -> resolveCallable -> runClosure -> callCFunction.
    const args = [_]Value{.{ .Int = 21 }};
    const ret = try vm.apiCall(Thread.CCALL_INC_NOYIELD, .{ .Closure = cl }, args[0..]);
    defer vm.alloc.free(ret);

    try testing.expectEqual(@as(usize, 1), ret.len);
    try testing.expectEqual(@as(i64, 42), ret[0].Int);

    // The C-API stack must be restored to its pre-call state (empty here) —
    // the swap-in/swap-out in callCFunction must not leak the temp stack.
    try testing.expectEqual(@as(usize, 0), vm.cur_c_stack.items.len);
}

test "vm: callCFunction with zero results" {
    // A C function returning 0 results exercises the nret<=0 fast path
    // (restore caller stack, return empty slice, no result dupe).
    const testing = std.testing;

    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const aalloc = arena.allocator();

    var vm = Vm.init(aalloc, false);
    defer vm.deinit();
    _ = try vm.setupMainHandle();

    const noop = struct {
        fn run(_: ?*lua_State) callconv(.c) c_int {
            return 0;
        }
    }.run;

    const cl = try vm.alloc.create(Closure);
    cl.* = .{ .upvalues = &.{}, .c_func = noop };
    try vm.gcRegisterClosure(cl);

    const ret = try vm.apiCall(Thread.CCALL_INC_NOYIELD, .{ .Closure = cl }, &.{});
    defer vm.alloc.free(ret);

    try testing.expectEqual(@as(usize, 0), ret.len);
    try testing.expectEqual(@as(usize, 0), vm.cur_c_stack.items.len);
}

test "vm: table constructor and access" {
    const testing = std.testing;
    const Source = @import("source.zig").Source;
    const Lexer = @import("lexer.zig").Lexer;
    const Parser = @import("parser.zig").Parser;
    const ast = @import("ast.zig");
    const CodegenBc = @import("codegen_bc.zig").Codegen;

    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const aalloc = arena.allocator();

    const src = Source{
        .name = "<test>",
        .bytes = "x = {a = 1, [2] = 3, 4}\n" ++
            "return x.a + x[2]\n",
    };

    var lex = Lexer.init(src);
    var p = try Parser.init(&lex);

    var ast_arena = ast.AstArena.init(aalloc);
    defer ast_arena.deinit();
    const chunk = try p.parseChunkAst(&ast_arena);

    var cg_bc = CodegenBc.init(aalloc, src.name, src.bytes);
    defer cg_bc.deinit();
    const proto = try cg_bc.compileChunk(chunk);

    var vm = Vm.init(aalloc, false);
    defer vm.deinit();
    // Source uses global `x` (GETTABUP on _ENV upvalue 0); provide _ENV.
    var env_cell = Cell{ .value = .{ .Table = vm.global_env } };
    const upvals = [_]*Cell{&env_cell};
    const ret = try vm.runBytecode(proto, &upvals, &.{}, null);

    try testing.expectEqual(@as(usize, 1), ret.len);
    switch (ret[0]) {
        .Int => |v| try testing.expectEqual(@as(i64, 4), v),
        else => try testing.expect(false),
    }
}

