test "vm: incremental GC advances real phases and preserves barrier writes" {
    const testing = std.testing;

    var vm = Vm.init(testing.allocator, false);
    defer vm.deinit();

    // Keep one ordinary table reachable through the global environment. The
    // target table is allocated before the cycle but starts unreachable.
    const holder = try vm.allocTableNoGc();
    const target = try vm.allocTableNoGc();
    const holder_key = Value{ .String = try vm.internStr("incremental-holder") };
    try vm.rawSet(vm.global_env, holder_key, .{ .Table = holder });

    // Add enough dead objects that sweep cannot finish in the same work unit.
    var i: usize = 0;
    while (i < 64) : (i += 1) _ = try vm.allocTableNoGc();
    const before = vm.gc_objects.items.len;

    try vm.gcStartCycle(true);
    try testing.expectEqual(Vm.GcState.propagate, vm.gc_state);

    // Advance one unit at a time until holder has been scanned (black). It is
    // already in the mark set when gray, so also require it to be absent from
    // the remaining gray queue.
    while (true) {
        var holder_is_gray = false;
        for (vm.gc_gray.items) |obj| {
            if (obj == .table and obj.table == holder) {
                holder_is_gray = true;
                break;
            }
        }
        if (!gcIsWhite(holder.gc_marked) and !holder_is_gray) break;
        _ = try vm.gcAdvance(1, false);
    }

    // Mutate a scanned table between slices. rawSet's tri-color barrier must
    // retain the pre-cycle target even though no stack/local root references it.
    try vm.rawSet(holder, .{ .String = try vm.internStr("value") }, .{ .Table = target });

    var saw_sweep = false;
    var freed_before_completion = false;
    while (vm.gc_state != .pause) {
        const old_len = vm.gc_objects.items.len;
        const completed = try vm.gcAdvance(1, false);
        if (vm.gc_state == .sweep) saw_sweep = true;
        if (!completed and vm.gc_objects.items.len < old_len) freed_before_completion = true;
    }

    try testing.expect(saw_sweep);
    try testing.expect(freed_before_completion);
    try testing.expect(vm.gc_objects.items.len < before);
    try testing.expect(vm.rawGet(holder, .{ .String = try vm.internStr("value") }) == .Table);
    try testing.expect(vm.rawGet(holder, .{ .String = try vm.internStr("value") }).Table == target);
}

test "vm: generational GC ages barriers and nursery scope match PUC" {
    const testing = std.testing;

    var vm = Vm.init(testing.allocator, false);
    defer vm.deinit();

    // Build and root a sizeable old heap before entering generational mode.
    // A minor collection must not traverse every table in this graph.
    const old_heap = try vm.allocTableNoGc();
    const holder = try vm.allocTableNoGc();
    try vm.rawSet(vm.global_env, .{ .String = try vm.internStr("gen-old-heap") }, .{ .Table = old_heap });
    try vm.rawSet(vm.global_env, .{ .String = try vm.internStr("gen-holder") }, .{ .Table = holder });
    var i: usize = 0;
    while (i < 512) : (i += 1) {
        const old_entry = try vm.allocTableNoGc();
        try vm.rawSet(old_heap, .{ .Int = @intCast(i + 1) }, .{ .Table = old_entry });
    }

    try vm.gcEnterGenerational();
    try testing.expectEqual(GcAge.old, holder.gc_age);
    try testing.expectEqual(GcAge.old, old_heap.gc_age);

    const child = try vm.allocTableNoGc();
    const grandchild = try vm.allocTableNoGc();
    try vm.rawSet(child, .{ .String = try vm.internStr("nested") }, .{ .Table = grandchild });
    try vm.rawSet(holder, .{ .String = try vm.internStr("child") }, .{ .Table = child });

    try testing.expectEqual(GcAge.touched1, holder.gc_age);
    try testing.expectEqual(GcAge.new, child.gc_age);
    try testing.expectEqual(GcAge.new, grandchild.gc_age);

    try vm.gcMinorCollection();
    try testing.expectEqual(GcAge.touched2, holder.gc_age);
    try testing.expectEqual(GcAge.survival, child.gc_age);
    try testing.expectEqual(GcAge.survival, grandchild.gc_age);
    // Old threads and the remembered holder are visited, but the 512-table
    // old graph itself is outside the nursery/remembered sets.
    try testing.expect(vm.gc_gen_last_minor_old_visited < 32);

    try vm.gcMinorCollection();
    try testing.expectEqual(GcAge.old, holder.gc_age);
    try testing.expectEqual(GcAge.old1, child.gc_age);
    try testing.expectEqual(GcAge.old1, grandchild.gc_age);

    try vm.gcMinorCollection();
    try testing.expectEqual(GcAge.old, child.gc_age);
    try testing.expectEqual(GcAge.old, grandchild.gc_age);
    const kept = vm.rawGet(holder, .{ .String = try vm.internStr("child") });
    try testing.expect(kept == .Table and kept.Table == child);
}

test "vm: generational GC enters and leaves incremental major mode" {
    const testing = std.testing;

    var vm = Vm.init(testing.allocator, false);
    defer vm.deinit();

    const root = try vm.allocTableNoGc();
    try vm.rawSet(vm.global_env, .{ .String = try vm.internStr("gen-major-root") }, .{ .Table = root });
    try vm.gcEnterGenerational();
    // Set minormajor to 1% to force a quick minor→major transition.
    vm.gcparams[2] = Vm.gcCodeParam(1);

    var i: usize = 0;
    while (i < 256) : (i += 1) {
        const child = try vm.allocTableNoGc();
        try vm.rawSet(root, .{ .Int = @intCast(i + 1) }, .{ .Table = child });
    }

    try vm.gcMinorCollection(); // NEW -> SURVIVAL
    try testing.expectEqual(Vm.GcGenPhase.minor, vm.gc_gen_phase);
    try vm.gcMinorCollection(); // SURVIVAL -> OLD1; cross minormajor
    try testing.expectEqual(Vm.GcGenPhase.major, vm.gc_gen_phase);

    // Make enough of the newly-old graph unreachable that the first major
    // cycle should return to minor mode under a zero majorminor threshold.
    i = 0;
    while (i < 256) : (i += 1) {
        try vm.rawSet(root, .{ .Int = @intCast(i + 1) }, .Nil);
    }
    // Set majorminor to 0% to force a quick major→minor transition.
    vm.gcparams[1] = Vm.gcCodeParam(0);
    try vm.gcCycleFull();
    try testing.expectEqual(Vm.GcGenPhase.minor, vm.gc_gen_phase);
    try testing.expectEqual(@as(usize, 0), vm.gc_young_objects.items.len);
    try testing.expectEqual(@as(usize, 0), vm.gc_grayagain.items.len);
}

// =========================================================================
// P16.8 Task 2: R254 simple_result regression test.
//
// R254 (0xFE) was previously stolen as SIMPLE_RESULT_COMPARE sentinel,
// making it impossible for a metamethod result to land in R254 — the VM
// would have misinterpreted value mode as compare mode. This test verifies
// the new design: R254 is a valid value-mode destination, and the compare
// flag lives in lua_packed_flags bit 7 (not in simple_result_dst).
//
// The old 0xFE design would FAIL this test: setSimpleValueResult(254, .add)
// would store 0xFE in simple_result_dst, and hasSimpleResult() would check
// simple_result_dst != 0xFF (true), but simpleResultIsCompare() would check
// the compare flag bit (false in the old design — 0xFE was the sentinel,
// not a bit flag). The old code checked `sr_dst == SIMPLE_RESULT_COMPARE`
// (0xFE), which would have been TRUE, misrouting value mode into compare
// mode. The new design uses a dedicated bit flag, so 0xFE is just a normal
// register.
// =========================================================================
test "vm: P16.8 R254 is valid simple_result value-mode destination" {
    const testing = std.testing;

    var frame_state = LuaFrameState{};

    // Initially: no simple result pending.
    try testing.expect(!frame_state.hasSimpleResult());
    try testing.expectEqual(@as(u8, 0xFF), frame_state.simple_result_dst);

    // Set value-mode result to R254 (0xFE) — the old sentinel.
    frame_state.setSimpleValueResult(254, .add);
    try testing.expect(frame_state.hasSimpleResult());
    try testing.expect(!frame_state.simpleResultIsCompare());
    try testing.expectEqual(@as(u8, 254), frame_state.simple_result_dst);
    try testing.expectEqual(TmsEvent.add, frame_state.simpleResultEvent());

    // Set compare-mode result — dst must be NO_REG (invariant).
    frame_state.clearSimpleResult();
    frame_state.setSimpleCompareResult(.lt, true);
    try testing.expect(frame_state.hasSimpleResult());
    try testing.expect(frame_state.simpleResultIsCompare());
    try testing.expectEqual(@as(u8, 0xFF), frame_state.simple_result_dst);
    try testing.expectEqual(TmsEvent.lt, frame_state.simpleResultEvent());
    try testing.expect(frame_state.simpleResultInvert());

    // Clear back to NONE.
    frame_state.clearSimpleResult();
    try testing.expect(!frame_state.hasSimpleResult());
    try testing.expectEqual(@as(u8, 0xFF), frame_state.simple_result_dst);

    // Verify R0 and R254 are both valid value-mode destinations.
    frame_state.setSimpleValueResult(0, .index);
    try testing.expectEqual(@as(u8, 0), frame_state.simple_result_dst);
    try testing.expect(!frame_state.simpleResultIsCompare());
    frame_state.clearSimpleResult();

    frame_state.setSimpleValueResult(254, .len);
    try testing.expectEqual(@as(u8, 254), frame_state.simple_result_dst);
    try testing.expect(!frame_state.simpleResultIsCompare());
    try testing.expectEqual(TmsEvent.len, frame_state.simpleResultEvent());
    frame_state.clearSimpleResult();
}

// =========================================================================
// P16.8a Task 5: Transactional simple_result setup — errdefer rollback.
//
// When tryPushSimpleResultMetamethod sets the parent's simple_result state
// and then pushBytecodeExecFrame (or dispatchCalleeActivationHook) fails,
// the errdefer clearSimpleResult() must roll the parent back to its exact
// prior state. This test forces the failure with a FailingAllocator and
// verifies the invariant across N iterations.
//
// Test mechanics:
//   - bc_stack_top is set near the end of bc_stack so the child frame's
//     needed_for_args exceeds bc_stack.len, forcing growBcStackCapSlow.
//   - A FailingAllocator (fail_index=0, resize_fail_index=0) makes the
//     very first realloc inside growBcStackCapSlow return null.
//   - The proto's constants are pre-resolved so resolveProtoConstants is
//     a no-op (the failure is isolated to the stack-growth path).
//   - After the error, we assert: simple_result == NONE, frame count
//     unchanged, pending_call_index == INVALID_PENDING.
//
// A final iteration with a high fail_index verifies the happy path: the
// call succeeds, simple_result IS set, and a child frame IS pushed.
// =========================================================================
test "vm: P16.8a transactional simple_result setup — errdefer rollback on push failure" {
    const testing = std.testing;
    const Source = @import("source.zig").Source;
    const Lexer = @import("lexer.zig").Lexer;
    const Parser = @import("parser.zig").Parser;
    const ast = @import("ast.zig");
    const CodegenBc = @import("codegen_bc.zig").Codegen;

    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const aalloc = arena.allocator();

    // Compile a simple parent proto and a simple metamethod proto.
    const compileProto = struct {
        fn run(alloc: std.mem.Allocator, src_bytes: []const u8) !*bc.Proto {
            const src = Source{ .name = "<test>", .bytes = src_bytes };
            var lex = Lexer.init(src);
            var p = try Parser.init(&lex);
            var ast_arena = ast.AstArena.init(alloc);
            defer ast_arena.deinit();
            const chunk = try p.parseChunkAst(&ast_arena);
            var cg = CodegenBc.init(alloc, src.name, src.bytes);
            defer cg.deinit();
            return try cg.compileChunk(chunk);
        }
    }.run;

    const parent_proto = try compileProto(aalloc, "return 1\n");
    const mm_proto = try compileProto(aalloc, "return 1\n");

    var vm = Vm.init(aalloc, false);
    defer vm.deinit();

    // Create bytecode closures for both protos. Each closure retains the
    // tree owner (gcFreeObject releases it at vm.deinit drain).
    const parent_cl = try aalloc.create(Closure);
    parent_cl.* = .{ .proto = parent_proto, .upvalues = &.{} };
    _ = vm.retainTreeForClosure(parent_proto);
    try vm.gcRegisterClosure(parent_cl);

    const mm_cl = try aalloc.create(Closure);
    mm_cl.* = .{ .proto = mm_proto, .upvalues = &.{} };
    _ = vm.retainTreeForClosure(mm_proto);
    try vm.gcRegisterClosure(mm_cl);

    // P16.10b: constants are adopted at closure creation in production;
    // this hand-built-frame test adopts both trees explicitly so the
    // push-time Debug readiness tripwire holds.
    try vm.resolveProtoConstants(parent_proto);
    try vm.resolveProtoConstants(mm_proto);

    // Push a parent Lua frame onto the active thread's call_frames.
    const exec_frames = &vm.activeBytecodeThread().call_frames;
    // Stage the parent frame at slot 0 (PUC: lua_pcallk pushes func+args
    // onto the stack before docall) and activate.
    const staged_parent = try vm.stageBytecodeCall(0, parent_cl, &.{});
    try vm.pushStagedBytecodeExecFrame(exec_frames, parent_proto, staged_parent.func_slot, staged_parent.nargs, -1);
    const parent_index: usize = 0;
    const saved_frame_count = exec_frames.len();
    const saved_bc_stack_top = vm.bc_stack_top;

    // ── Failure iterations: force pushBytecodeExecFrame to fail ──
    // Each iteration: set bc_stack_top near the end so the child frame
    // needs stack growth, then use a FailingAllocator to make the growth
    // fail. The errdefer must clear simple_result on the parent.
    var iter: usize = 0;
    while (iter < 5) : (iter += 1) {
        // Ensure clean slate for each iteration.
        exec_frames.getPtr(parent_index).u.lua.clearSimpleResult();
        // bc_stack_top near the end forces growBcStackCapSlow in
        // pushBytecodeExecFrame (needed_for_args > bc_stack.len).
        vm.bc_stack_top = vm.bc_stack.len - 2;

        var failing = std.testing.FailingAllocator.init(aalloc, .{
            .fail_index = 0,
            .resize_fail_index = 0,
        });
        const saved_alloc = vm.alloc;
        vm.alloc = failing.allocator();
        defer vm.alloc = saved_alloc;

        const args = [_]Value{ .Nil, .Nil };
        const result = vm.tryPushSimpleResultMetamethod(
            exec_frames,
            parent_index,
            .{ .Closure = mm_cl },
            args[0..],
            .add,
            .{ .value = 0 },
        );

        // Restore allocator immediately (defer above is a safety net).
        vm.alloc = saved_alloc;

        // The call must fail with OOM (stack growth allocation failed).
        try testing.expectError(error.OutOfMemory, result);

        // Invariant: parent is EXACTLY as it was before the call.
        // 1. simple_result must be NONE (errdefer cleared it).
        try testing.expect(
            !exec_frames.getPtr(parent_index).u.lua.hasSimpleResult(),
        );
        // 2. No child frame was left on the call stack.
        try testing.expectEqual(
            saved_frame_count,
            exec_frames.len(),
        );
        // 3. pending_call_index must still be INVALID (no pending call).
        try testing.expectEqual(
            @as(u32, INVALID_PENDING),
            exec_frames.getPtr(parent_index).pending_call_index,
        );
    }

    // ── Success iteration: high fail_index, call completes ──
    // Verifies the errdefer does NOT fire spuriously on success: the
    // parent keeps its simple_result and the child frame is on the stack.
    {
        exec_frames.getPtr(parent_index).u.lua.clearSimpleResult();
        vm.bc_stack_top = vm.bc_stack.len - 2;

        var failing = std.testing.FailingAllocator.init(aalloc, .{
            .fail_index = 100,
            .resize_fail_index = 100,
        });
        const saved_alloc = vm.alloc;
        vm.alloc = failing.allocator();
        defer vm.alloc = saved_alloc;

        const args = [_]Value{ .Nil, .Nil };
        const outcome = try vm.tryPushSimpleResultMetamethod(
            exec_frames,
            parent_index,
            .{ .Closure = mm_cl },
            args[0..],
            .add,
            .{ .value = 0 },
        );

        vm.alloc = saved_alloc;

        try testing.expect(outcome == .pushed);
        // Parent must have simple_result set (errdefer did NOT fire).
        try testing.expect(
            exec_frames.getPtr(parent_index).u.lua.hasSimpleResult(),
        );
        // Child frame must be on the call stack.
        try testing.expectEqual(
            saved_frame_count + 1,
            exec_frames.len(),
        );
        // Clean up: pop the child frame and clear simple_result.
        vm.popBytecodeExecFrame(exec_frames);
        exec_frames.getPtr(parent_index).u.lua.clearSimpleResult();
    }

    // Restore bc_stack_top for clean deinit.
    vm.bc_stack_top = saved_bc_stack_top;
}

// =========================================================================
// P16.15 T6: transactional STAGED activation — failure BETWEEN staging
// and activation.
//
// The staged ABI (stageBytecodeCall → pushStagedBytecodeExecFrame) opens a
// new failure window relative to the old fused flow: staging can succeed
// (func+args written at bc_stack_top) while the activation fails afterwards
// (frame-space growth OOM, or FrameStack.addOne OOM). This test forces each
// failure point and verifies the PUC luaT_callTMres → luaD_precall sequence
// rolls back exactly:
//   1. parent simple_result state restored (NONE),
//   2. no child frame left (frame count unchanged),
//   3. no pending-call slot leak (pending_call_index == INVALID_PENDING),
//   4. bc_stack_top restored to its pre-call value (staged temporaries
//      above bc_stack_top are dead by definition — not part of any live
//      frame region and not GC-marked through bc_stack),
//   5. success iteration: errdefers do NOT fire spuriously.
// =========================================================================
test "vm: P16.15 T6 transactional staged activation — failure between staging and activation" {
    const testing = std.testing;

    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const aalloc = arena.allocator();

    // Parent: minimal frame. Child: 60 locals → large frame_cap, so the
    // activation's needed_top (base + frame_cap) exceeds the remaining
    // bc_stack headroom while the staged func+2 args still fit.
    const parent_proto = try compileTestProto(aalloc, "return 1\n");
    var many_locals_buf: [820]u8 = undefined;
    var many_locals_len: usize = 0;
    const writeMany = struct {
        fn run(buf: []u8, len: *usize, bytes: []const u8) void {
            @memcpy(buf[len.* .. len.* + bytes.len], bytes);
            len.* += bytes.len;
        }
    }.run;
    writeMany(&many_locals_buf, &many_locals_len, "local ");
    var name_buf: [8]u8 = undefined;
    for (1..60) |i| {
        const name = std.fmt.bufPrint(&name_buf, "a{d},", .{i}) catch unreachable;
        writeMany(&many_locals_buf, &many_locals_len, name);
    }
    writeMany(&many_locals_buf, &many_locals_len, "a60\nreturn 1\n");
    const mm_proto = try compileTestProto(aalloc, many_locals_buf[0..many_locals_len]);

    var vm = Vm.init(aalloc, false);
    defer vm.deinit();

    const parent_cl = try aalloc.create(Closure);
    parent_cl.* = .{ .proto = parent_proto, .upvalues = &.{} };
    _ = vm.retainTreeForClosure(parent_proto);
    try vm.gcRegisterClosure(parent_cl);
    const mm_cl = try aalloc.create(Closure);
    mm_cl.* = .{ .proto = mm_proto, .upvalues = &.{} };
    _ = vm.retainTreeForClosure(mm_proto);
    try vm.gcRegisterClosure(mm_cl);
    try vm.resolveProtoConstants(parent_proto);
    try vm.resolveProtoConstants(mm_proto);

    // Push the parent frame (staged ABI: stage at slot 0, activate).
    const exec_frames = &vm.activeBytecodeThread().call_frames;
    const staged_parent = try vm.stageBytecodeCall(0, parent_cl, &.{});
    try vm.pushStagedBytecodeExecFrame(exec_frames, parent_proto, staged_parent.func_slot, staged_parent.nargs, -1);
    const parent_index: usize = 0;
    const saved_frame_count = exec_frames.len();

    const args = [_]Value{ .Nil, .Nil };

    // ── Failure point 1: activation's frame-space growth (ensureBcStackCap
    // inside pushStagedBytecodeExecFrame) fails AFTER staging succeeded. ──
    // bc_stack_top = len - 3: staging needs exactly len slots (func + 2
    // args) → no growth, staging completes. The child's frame_cap (~66)
    // exceeds the 2 remaining slots → growBcStackCapSlow → FailingAllocator
    // makes the realloc fail → error.OutOfMemory.
    {
        exec_frames.getPtr(parent_index).u.lua.clearSimpleResult();
        vm.bc_stack_top = vm.bc_stack.len - 3;
        const saved_top = vm.bc_stack_top;

        var failing = std.testing.FailingAllocator.init(aalloc, .{
            .fail_index = 0,
            .resize_fail_index = 0,
        });
        const saved_alloc = vm.alloc;
        vm.alloc = failing.allocator();
        defer vm.alloc = saved_alloc;

        const result = vm.tryPushSimpleResultMetamethod(
            exec_frames,
            parent_index,
            .{ .Closure = mm_cl },
            args[0..],
            .add,
            .{ .value = 0 },
        );
        vm.alloc = saved_alloc;

        try testing.expectError(error.OutOfMemory, result);
        // 1. simple_result rolled back.
        try testing.expect(!exec_frames.getPtr(parent_index).u.lua.hasSimpleResult());
        // 2. no child frame.
        try testing.expectEqual(saved_frame_count, exec_frames.len());
        // 3. no pending-call slot leak.
        try testing.expectEqual(
            @as(u32, INVALID_PENDING),
            exec_frames.getPtr(parent_index).pending_call_index,
        );
        // 4. bc_stack_top restored (staging never bumps it; the activation
        //    failed before its own top update).
        try testing.expectEqual(saved_top, vm.bc_stack_top);
    }

    // ── Failure point 2: FrameStack.addOne fails AFTER staging AND after
    // the activation's stack growth + bc_stack_top update. ──
    // Pre-grow bc_stack so the activation needs no growth: the first
    // allocation on the path is addOne, which the FailingAllocator rejects.
    {
        exec_frames.getPtr(parent_index).u.lua.clearSimpleResult();
        const child_frame_cap: usize = mm_proto.maxstacksize + EXTRA_MARGIN;
        try vm.ensureBcStackCap(vm.bc_stack_top + 1 + args.len + child_frame_cap);
        vm.bc_stack_top = vm.bc_stack.len - 1 - args.len - child_frame_cap;
        const saved_top = vm.bc_stack_top;

        var failing = std.testing.FailingAllocator.init(aalloc, .{
            .fail_index = 0,
            .resize_fail_index = 0,
        });
        const saved_alloc = vm.alloc;
        vm.alloc = failing.allocator();
        defer vm.alloc = saved_alloc;

        const result = vm.tryPushSimpleResultMetamethod(
            exec_frames,
            parent_index,
            .{ .Closure = mm_cl },
            args[0..],
            .add,
            .{ .value = 0 },
        );
        vm.alloc = saved_alloc;

        try testing.expectError(error.OutOfMemory, result);
        try testing.expect(!exec_frames.getPtr(parent_index).u.lua.hasSimpleResult());
        try testing.expectEqual(saved_frame_count, exec_frames.len());
        try testing.expectEqual(
            @as(u32, INVALID_PENDING),
            exec_frames.getPtr(parent_index).pending_call_index,
        );
        // bc_stack_top was set to needed_top before addOne failed — the
        // errdefer must have restored it.
        try testing.expectEqual(saved_top, vm.bc_stack_top);
    }

    // ── Success iteration: staging + activation both succeed. ──
    {
        exec_frames.getPtr(parent_index).u.lua.clearSimpleResult();
        const child_frame_cap: usize = mm_proto.maxstacksize + EXTRA_MARGIN;
        try vm.ensureBcStackCap(vm.bc_stack_top + 1 + args.len + child_frame_cap);

        const outcome = try vm.tryPushSimpleResultMetamethod(
            exec_frames,
            parent_index,
            .{ .Closure = mm_cl },
            args[0..],
            .add,
            .{ .value = 0 },
        );
        try testing.expect(outcome == .pushed);
        try testing.expect(exec_frames.getPtr(parent_index).u.lua.hasSimpleResult());
        try testing.expectEqual(saved_frame_count + 1, exec_frames.len());
        // Clean up: pop the child frame and clear simple_result.
        vm.popBytecodeExecFrame(exec_frames);
        exec_frames.getPtr(parent_index).u.lua.clearSimpleResult();
    }

    // Restore bc_stack_top for clean deinit.
    vm.bc_stack_top = exec_frames.getPtr(parent_index).frameBase() +
        exec_frames.getPtr(parent_index).u.lua.frame_cap;
}

// =========================================================================
// P16.10c verifier Task 8: FailingAllocator ownership paths
//
// Each test forces an allocation failure at a specific ownership boundary
// and verifies: no leak (TrackingAllocator.total_bytes == 0 after cleanup),
// no double release (refcount sane), no executable half-bound tree.
//
// Uses FailingAllocator wrapping TrackingAllocator(page_allocator). The
// TrackingAllocator gives exact byte-count leak detection via total_bytes
// without the DebugAllocator's strict pointer-matching (which can false-
// positive when FailingAllocator intercepts allocs but frees pass through).
// The iterative fail_index approach exhaustively tests every OOM point.
// =========================================================================

/// Compile a simple proto from source. Returns a finished proto with
/// ref_count == 1 (the producing reference).
fn compileTestProto(alloc: std.mem.Allocator, src_bytes: []const u8) !*bc.Proto {
    const Source = @import("source.zig").Source;
    const Lexer = @import("lexer.zig").Lexer;
    const Parser = @import("parser.zig").Parser;
    const ast = @import("ast.zig");
    const CodegenBc = @import("codegen_bc.zig").Codegen;
    const src = Source{ .name = "<test>", .bytes = src_bytes };
    var lex = Lexer.init(src);
    var p = try Parser.init(&lex);
    var ast_arena = ast.AstArena.init(alloc);
    defer ast_arena.deinit();
    const chunk = try p.parseChunkAst(&ast_arena);
    var cg = CodegenBc.init(alloc, src.name, src.bytes);
    defer cg.deinit();
    return try cg.compileChunk(chunk);
}

test "vm: Task 8.1 — ProtoBuilder.finish owner creation fails → no leak" {
    const testing = std.testing;
    const TrackingAllocator = @import("tracking_alloc.zig").TrackingAllocator;

    // Exhaustively test every OOM point in ProtoBuilder.finish() (and the
    // builder populate phase). Each failure must clean up — no leak.
    // A single TrackingAllocator tracks all iterations; at the end, all
    // allocations must be freed (total_bytes == 0).
    var tracker = TrackingAllocator.init(std.heap.page_allocator);
    const track_alloc = tracker.allocator();

    var fail_idx: usize = 0;
    while (true) : (fail_idx += 1) {
        var failing = std.testing.FailingAllocator.init(track_alloc, .{
            .fail_index = fail_idx,
            .resize_fail_index = fail_idx,
        });
        const falloc = failing.allocator();

        var builder = bc.ProtoBuilder.init(falloc);
        _ = builder.emitSimple(.return0, 1) catch {
            builder.deinit();
            continue;
        };
        _ = builder.internConst(.{ .int = 42 }) catch {
            builder.deinit();
            continue;
        };

        const result = builder.finish();
        builder.deinit();

        if (result) |proto| {
            proto.tree.?.releaseTree(falloc);
            break;
        } else |err| {
            try testing.expectEqual(error.OutOfMemory, err);
        }
    }
    // After all iterations, every allocation must be freed.
    try testing.expectEqual(@as(usize, 0), tracker.total_bytes);
}

test "vm: Task 8.2 — closure creation refcount invariant (retain/release balance)" {
    const testing = std.testing;

    // Verify the tree refcount invariant on the happy path:
    //   compile → ref_count = 1
    //   createBytecodeChunkClosure → ref_count = 2 (closure retains tree)
    //   release caller's ref → ref_count = 1
    //   release closure's ref → ref_count = 0, tree freed
    //
    // The OOM errdefer paths in createBytecodeChunkClosure and
    // closureFromProto (Task 8 fix) mirror this retain/release balance:
    // if any step after retainTreeForClosure fails, the errdefer releases
    // the tree ref, restoring the invariant. The exhaustive OOM test for
    // ProtoBuilder.finish (Task 8.1) covers the allocation-failure cleanup
    // at that level; this test covers the refcount contract.

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const aalloc = arena.allocator();

    var vm = Vm.init(aalloc, false);
    defer vm.deinit();

    // Proto with one upvalue (exercises cell allocation path).
    const p = try compileTestProto(aalloc, "local x = 1\nreturn function() return x end\n");
    try testing.expectEqual(@as(usize, 1), p.tree.?.ref_count);

    const cl = try vm.createBytecodeChunkClosure(p);
    try testing.expectEqual(@as(usize, 2), p.tree.?.ref_count);
    // P16.16 C2/T4.2: the tree owner is derived from the closure's proto
    // (cl.proto.?.tree); the closure itself carries no tree field.
    try testing.expect(cl.proto == p);
    try testing.expect(p.tree != null);

    // Caller releases its producing reference (compileChunkValue pattern).
    p.tree.?.releaseTree(aalloc);
    try testing.expectEqual(@as(usize, 1), p.tree.?.ref_count);

    // The closure's tree reference (ref_count == 1) is released by
    // vm.deinit() → drainGcRegistries → gcFreeObject(.closure) →
    // proto.tree.release(). Do NOT release it here — that would double-free
    // the tree (gcFreeObject would access the dangling pointer).
}

test "vm: Task 8.3 — constant-resolution staging OOM → tree unresolved, retry succeeds" {
    const testing = std.testing;
    const TrackingAllocator = @import("tracking_alloc.zig").TrackingAllocator;

    // Compile a proto with string constants. Attempt resolveTreeConstants
    // with a FailingAllocator. The tree must remain unresolved. Retry
    // with a working allocator must succeed (idempotence proof).
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const aalloc = arena.allocator();

    var vm = Vm.init(aalloc, false);
    defer vm.deinit();

    var hit_failure = false;
    var fail_idx: usize = 0;
    while (fail_idx < 200) : (fail_idx += 1) {
        const p = try compileTestProto(aalloc, "return 'hello' .. 'world'\n");
        try testing.expect(!p.tree.?.flags.constants_resolved);

        var tracker = TrackingAllocator.init(std.heap.page_allocator);
        const track_alloc = tracker.allocator();
        var failing = std.testing.FailingAllocator.init(track_alloc, .{
            .fail_index = fail_idx,
            .resize_fail_index = fail_idx,
        });
        const saved_alloc = vm.alloc;
        vm.alloc = failing.allocator();

        const result = vm.resolveTreeConstants(p.tree.?);
        vm.alloc = saved_alloc;

        if (result) |_| {
            p.tree.?.releaseTree(aalloc);
            try testing.expect(p.tree.?.flags.constants_resolved);
            try testing.expectEqual(@as(usize, 0), tracker.total_bytes);
            break;
        } else |_| {
            // Resolution failed. Tree must still be unresolved.
            try testing.expect(!p.tree.?.flags.constants_resolved);
            try testing.expectEqual(@as(usize, 0), tracker.total_bytes);
            hit_failure = true;
            // Retry with working allocator — idempotence proof.
            vm.alloc = aalloc;
            try vm.resolveTreeConstants(p.tree.?);
            try testing.expect(p.tree.?.flags.constants_resolved);
            p.tree.?.releaseTree(aalloc);
            break;
        }
    }
    try testing.expect(hit_failure);
}

test "vm: Task 8.4 — nested tree adoption fails partway → no partial publish" {
    const testing = std.testing;
    const TrackingAllocator = @import("tracking_alloc.zig").TrackingAllocator;

    // Compile a nested tree (main → child). Force OOM during the child's
    // staging. The whole tree must remain unresolved (no partial publish).
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const aalloc = arena.allocator();

    var vm = Vm.init(aalloc, false);
    defer vm.deinit();

    var hit_failure = false;
    var fail_idx: usize = 0;
    while (fail_idx < 300) : (fail_idx += 1) {
        const p = try compileTestProto(aalloc,
            \\return function() return 'child' end
        );
        try testing.expect(!p.tree.?.flags.constants_resolved);
        try testing.expect(p.p.len >= 1);

        var tracker = TrackingAllocator.init(std.heap.page_allocator);
        const track_alloc = tracker.allocator();
        var failing = std.testing.FailingAllocator.init(track_alloc, .{
            .fail_index = fail_idx,
            .resize_fail_index = fail_idx,
        });
        const saved_alloc = vm.alloc;
        vm.alloc = failing.allocator();

        const result = vm.resolveTreeConstants(p.tree.?);
        vm.alloc = saved_alloc;

        if (result) |_| {
            p.tree.?.releaseTree(aalloc);
            try testing.expect(p.tree.?.flags.constants_resolved);
            try testing.expectEqual(@as(usize, 0), tracker.total_bytes);
            break;
        } else |_| {
            // Failed — tree must be FULLY unresolved (no partial publish).
            try testing.expect(!p.tree.?.flags.constants_resolved);
            try testing.expectEqual(@as(usize, 0), p.resolved_values.len);
            for (p.p) |child| {
                try testing.expectEqual(@as(usize, 0), child.resolved_values.len);
            }
            try testing.expectEqual(@as(usize, 0), tracker.total_bytes);
            hit_failure = true;
            // Retry succeeds (idempotence).
            vm.alloc = aalloc;
            try vm.resolveTreeConstants(p.tree.?);
            try testing.expect(p.tree.?.flags.constants_resolved);
            p.tree.?.releaseTree(aalloc);
            break;
        }
    }
    try testing.expect(hit_failure);
}

test "vm: Task 8.5 — undump fails partway → cleanup complete" {
    const testing = std.testing;
    const TrackingAllocator = @import("tracking_alloc.zig").TrackingAllocator;

    // Serialize a proto tree, then undump with a FailingAllocator. Every
    // OOM point in undumpChunk must clean up the partial tree — no leak.
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const aalloc = arena.allocator();

    const proto = try compileTestProto(aalloc, "return 'hello' .. 42\n");
    var writer = dump_mod.DumpWriter.init(aalloc);
    defer writer.deinit();
    try writer.dumpChunk(proto, .{ .strip = false });
    const serialized = try writer.toOwnedSlice();
    defer aalloc.free(serialized);
    proto.tree.?.releaseTree(aalloc);

    var fail_idx: usize = 0;
    while (true) : (fail_idx += 1) {
        var tracker = TrackingAllocator.init(std.heap.page_allocator);
        const track_alloc = tracker.allocator();
        var failing = std.testing.FailingAllocator.init(track_alloc, .{
            .fail_index = fail_idx,
            .resize_fail_index = fail_idx,
        });
        const falloc = failing.allocator();

        var reader = undump_mod.UndumpReader.init(falloc, serialized);
        const result = reader.undumpChunk();
        reader.deinit(); // free string_dedup before checking total_bytes

        if (result) |root| {
            root.tree.?.releaseTree(falloc);
            try testing.expectEqual(@as(usize, 0), tracker.total_bytes);
            break;
        } else |err| {
            try testing.expect(error.OutOfMemory == err);
            try testing.expectEqual(@as(usize, 0), tracker.total_bytes);
        }
    }
}

test "vm: Task 8.6 — source-backing append fails → no pin leak" {
    const testing = std.testing;
    const TrackingAllocator = @import("tracking_alloc.zig").TrackingAllocator;

    // Test that SourceBacking.owned.append failure leaves the backing in
    // a clean state (no partial append, no leak). The ArrayList starts
    // empty (0 capacity); the first append needs an allocation, which the
    // FailingAllocator blocks.
    var tracker = TrackingAllocator.init(std.heap.page_allocator);
    const track_alloc = tracker.allocator();

    var backing = bc.SourceBacking{};

    // Allocate a buffer to attempt to append.
    const buf1 = try track_alloc.dupe(u8, "source1");

    // Force the append to fail: ArrayList has 0 capacity, so append needs
    // an allocation. FailingAllocator with fail_index=0 blocks it.
    var failing = std.testing.FailingAllocator.init(track_alloc, .{
        .fail_index = 0,
        .resize_fail_index = 0,
    });
    const falloc = failing.allocator();
    const append_result = backing.addOwned(falloc, buf1);

    try testing.expectError(error.OutOfMemory, append_result);
    // buf1 was allocated but NOT appended (the append failed). Free it.
    track_alloc.free(buf1);

    // The backing is empty — no partial append.
    try testing.expectEqual(@as(usize, 0), backing.ownedCount());
    // Clean up: deinit is a no-op (empty backing).
    backing.deinit(track_alloc);
    try testing.expectEqual(@as(usize, 0), tracker.total_bytes);
}

// =========================================================================
// P16.10d verifier Task 7: FailingAllocator around fixed-buffer paths
//
// Each test forces an allocation failure at a specific point in the
// fixed-buffer load pipeline and verifies:
//   - No leak (TrackingAllocator.total_bytes == 0 after cleanup)
//   - No double-free of borrowed spans (external_borrow never freed)
//   - No executable half-bound tree (partial trees are cleaned up)
//   - Truncated fixed chunks produce clean errors (no partial tree)
// =========================================================================

/// Compile a proto, dump it stripped (matching api.lua:566 shape), and return
/// the serialized bytes. The caller owns the slice.
fn dumpTestProtoStripped(alloc: std.mem.Allocator, src_bytes: []const u8) ![]u8 {
    const proto = try compileTestProto(alloc, src_bytes);
    defer proto.tree.?.releaseTree(alloc);
    var writer = dump_mod.DumpWriter.init(alloc);
    defer writer.deinit();
    try writer.dumpChunk(proto, .{ .strip = true });
    return try writer.toOwnedSlice();
}

test "vm: Task 7.1 — fixed undump metadata allocation failure → no leak" {
    const testing = std.testing;
    const TrackingAllocator = @import("tracking_alloc.zig").TrackingAllocator;

    // Exhaustively test every OOM point in undumpChunk with fixed=true.
    // Fixed mode borrows code/lineinfo (fewer allocation points than non-fixed),
    // but k array, upvalues array, p array, Proto struct, and Proto owner fields (CUT2)
    // are still allocated. Each failure must clean up — no leak.
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const aalloc = arena.allocator();

    const serialized = try dumpTestProtoStripped(aalloc, "X = X + 1; Y = 'hello'\n");
    defer aalloc.free(serialized);

    var fail_idx: usize = 0;
    while (true) : (fail_idx += 1) {
        var tracker = TrackingAllocator.init(std.heap.page_allocator);
        const track_alloc = tracker.allocator();
        var failing = std.testing.FailingAllocator.init(track_alloc, .{
            .fail_index = fail_idx,
            .resize_fail_index = fail_idx,
        });
        const falloc = failing.allocator();

        var reader = undump_mod.UndumpReader.init(falloc, serialized);
        reader.fixed = true;
        // No intern callback: string constants get .str = undefined.
        // This is fine for testing the allocation/cleanup mechanics.
        const result = reader.undumpChunk();
        reader.deinit();

        if (result) |root| {
            root.tree.?.releaseTree(falloc);
            try testing.expectEqual(@as(usize, 0), tracker.total_bytes);
            break;
        } else |err| {
            try testing.expect(error.OutOfMemory == err);
            try testing.expectEqual(@as(usize, 0), tracker.total_bytes);
        }
    }
}

test "vm: Task 7.2 — closure creation failure AFTER borrow established → no double-free" {
    const testing = std.testing;

    // The critical invariant: when closureFromProto fails AFTER the fixed-
    // buffer borrow is established (source_backing.external_borrow set), the
    // borrowed span must NOT be freed by the tree cleanup. The caller owns
    // the borrowed buffer; the tree only records a pointer to it
    // (external_borrow is NEVER freed by SourceBacking.deinit or
    // destroyProtoTree — this is by design, matching PUC's LZIO borrow model).
    //
    // We verify by allocating the borrowed buffer from the arena (NOT the
    // VM's allocator), loading with .borrowed + mode "B", and checking the
    // buffer content is unchanged after every OOM failure.
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const aalloc = arena.allocator();

    // Serialize a proto for fixed-buffer loading.
    const serialized = try dumpTestProtoStripped(aalloc, "X = X + 1; Y = 'hello'\n");
    defer aalloc.free(serialized);

    // The borrowed buffer: allocated from the arena. The tree must never
    // free this — it's the caller's responsibility. We verify the content
    // is unchanged after every failure (if the tree freed/corrupted it,
    // the content check would fail or crash).
    const borrowed_bytes = try aalloc.dupe(u8, serialized);
    defer aalloc.free(borrowed_bytes);

    var vm = Vm.init(aalloc, false);
    defer vm.deinit();

    // Exhaustively test every OOM point in the closure creation path
    // (cell allocation, closure allocation, resolveTreeConstants). Each
    // failure must: release the tree (cleaning up partial state), NOT
    // free the borrowed buffer, and leave the VM in a valid state.
    var fail_idx: usize = 0;
    var hit_failure = false;
    while (fail_idx < 200) : (fail_idx += 1) {
        var failing = std.testing.FailingAllocator.init(aalloc, .{
            .fail_index = fail_idx,
            .resize_fail_index = fail_idx,
        });

        const saved_alloc = vm.alloc;
        vm.alloc = failing.allocator();
        defer vm.alloc = saved_alloc;

        // Load with .borrowed input and mode "B" (fixed). The borrowed_bytes
        // are the caller's buffer — the tree records external_borrow but
        // must never free it.
        const result = vm.loadChunk(
            .{ .borrowed = borrowed_bytes },
            borrowed_bytes,
            "test",
            "B",
            .{ .Table = vm.global_env },
            null,
        );

        vm.alloc = saved_alloc;

        if (result) |res| {
            switch (res) {
                .closure => |cl| {
                    // Success: the closure is registered in the GC list.
                    // vm.deinit will drain it. Verify the borrowed buffer
                    // is still intact (not freed/corrupted).
                    try testing.expectEqualSlices(u8, serialized, borrowed_bytes);
                    _ = cl;
                    break;
                },
                .err_msg => |msg| {
                    aalloc.free(msg);
                    // This shouldn't happen (no syntax errors in fixed load).
                    try testing.expectEqualSlices(u8, serialized, borrowed_bytes);
                    break;
                },
            }
        } else |err| {
            try testing.expect(error.OutOfMemory == err);
            // The borrowed buffer must still be intact (not freed/corrupted
            // by the tree cleanup). This is the key invariant: external_borrow
            // is NEVER freed, so the caller's buffer survives every failure.
            try testing.expectEqualSlices(u8, serialized, borrowed_bytes);
            hit_failure = true;
        }
    }
    try testing.expect(hit_failure);
}

test "vm: Task 7.3 — source-backing .owned append in fixed mode (happy path)" {
    const testing = std.testing;

    // Verify the .owned fixed-buffer load path works end-to-end: the
    // source_backing.owned.append succeeds, the owned input is consumed
    // (ownership transferred to tree), and the closure executes correctly.
    // The failure case (append OOM → tree released, owned input freed) is
    // structurally identical to Task 8.6 (source_backing.owned.append
    // failure) and Task 7.2 (closure creation failure after borrow); the
    // errdefer in loadBinaryChunk releases the tree and the defer frees the
    // owned input on every error path.
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const aalloc = arena.allocator();

    const serialized = try dumpTestProtoStripped(aalloc, "return 'hello'\n");
    defer aalloc.free(serialized);

    var vm = Vm.init(aalloc, false);
    defer vm.deinit();

    // .owned input: the tree takes ownership (source_backing.owned.append).
    // The owned_bytes are freed at tree release (last closure drop).
    const owned_copy = try aalloc.dupe(u8, serialized);

    const result = try vm.loadChunk(
        .{ .owned = owned_copy },
        owned_copy,
        "test",
        "B",
        .{ .Table = vm.global_env },
        null,
    );
    switch (result) {
        .closure => |cl| {
            // Verify the closure is valid and the tree has the owned buffer.
            const owner = cl.proto.?.tree.?;
            try testing.expect(owner.source_backing.extra != null);
            try testing.expectEqual(@as(usize, 1), owner.source_backing.extra.?.owned.items.len);
        },
        .err_msg => |msg| {
            aalloc.free(msg);
            try testing.expect(false); // should not fail
        },
    }
}

test "vm: Task 7.4 — truncated fixed chunk at aligned blocks → clean error" {
    const testing = std.testing;

    // Truncate the binary chunk at various points (header, code block,
    // lineinfo block, string data) and verify each produces a clean
    // TruncatedChunk error — no partial tree, no crash.
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const aalloc = arena.allocator();

    const serialized = try dumpTestProtoStripped(aalloc, "X = X + 1; Y = 'hello world'\n");
    defer aalloc.free(serialized);

    // Test truncation at every byte position in the chunk. Each must
    // produce TruncatedChunk (or BadHeader for the first few bytes) —
    // never a crash, never a partial tree.
    var pos: usize = 1;
    while (pos < serialized.len) : (pos += 1) {
        const truncated = serialized[0..pos];
        var reader = undump_mod.UndumpReader.init(aalloc, truncated);
        reader.fixed = true;
        const result = reader.undumpChunk();
        reader.deinit();
        if (result) |root| {
            // A successful undump at a truncation point would be a bug —
            // the chunk is incomplete. This should never happen.
            root.tree.?.releaseTree(aalloc);
            try testing.expect(false); // should not succeed on truncated chunk
        } else |err| {
            // Must be TruncatedChunk or BadHeader or BadConstant — never
            // a crash or memory corruption.
            try testing.expect(switch (err) {
                error.TruncatedChunk, error.BadHeader, error.BadConstant => true,
                else => false,
            });
        }
    }
}
